defmodule Singularity.Runtime.LegacyUpgradeProcessTest do
  use ExUnit.Case, async: false

  alias Singularity.Runtime.LegacyUpgradeRuntimeFixture

  @moduletag :integration

  @fingerprint "d7506f511de599dfb92cd2313f843abb27ca26eafd3bf89939ecbf07e2a22924"
  @owner "11111111-1111-4111-8111-111111111111"
  @database "singularity_test_0123456789abcdef01234567"

  # Fixed synthetic contract inputs, never credentials/content from a real owner.
  # These literals are a complete ASCII PDF and two distinct complete RGBA PNGs.
  @text_pdf ""
  @binary_png "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGP4z8DwHwAFAAH/iZk9HQAAAABJRU5ErkJggg=="
  @deleted_png "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGNgYPj/HwADAgH/5ncLrgAAAABJRU5ErkJggg=="

  test "the fixed configuration is one bounded version-one frame before an oversized mutant" do
    configuration = configuration()
    payload = Jason.encode!(configuration)
    expected = <<byte_size(payload)::unsigned-big-integer-size(32), payload::binary>>
    encoded = apply(LegacyUpgradeRuntimeFixture, :encode_configuration!, [configuration])
    matches? = encoded == expected and byte_size(payload) <= 16_384
    assert matches?

    oversized = put_in(configuration, ["credentials", "password"], String.duplicate("x", 16_384))

    rejected? =
      try do
        apply(LegacyUpgradeRuntimeFixture, :encode_configuration!, [oversized])
        false
      rescue
        error in ArgumentError -> Exception.message(error) == "legacy_configuration"
      end

    assert rejected?
  end

  test "a typed synthetic receipt decodes before a shorter-frame trailer is rejected" do
    receipt = receipt()
    payload = Jason.encode!(receipt)
    frame = <<byte_size(payload)::unsigned-big-integer-size(32), payload::binary>>
    decoded = apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [frame])
    matches? = decoded == {:ok, receipt} and byte_size(payload) < 65_536
    assert matches?

    result = apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [frame <> <<0>>])
    rejected? = result == {:error, :legacy_protocol}
    assert rejected?
  end

  for mutation <-
        ~w(not_map missing unknown protocol fingerprint oid oid_type relative_root traversal_root nul_root nested_root repository_keys repository_missing repository_extra repository_role repository_database repository_port credentials_keys login_type empty_password invalid_utf8 original_keys original_base64 original_noncanonical original_size original_duplicate original_magic duplicate_top duplicate_nested)a do
    test "#{mutation} configuration fails after the same valid encoding control" do
      configuration = configuration()
      assert_configuration_control!(configuration)
      changed = mutate_configuration(unquote(mutation), configuration)
      rejected? = configuration_rejected?(changed)
      assert rejected?
      assert_configuration_control!(configuration)
    end
  end

  for mutation <-
        ~w(not_map missing unknown protocol fingerprint owner_keys owner_uuid owner_scope notes_keys note_missing note_extra note_uuid note_state note_lineage assets_keys asset_missing asset_extra asset_uuid asset_hash asset_size asset_state object_lifecycle duplicate_object duplicate_digest work_keys work_encoding empty_completed completed_keys completed_uuid completed_type runner_type runner_noncanonical event_submission pending_keys pending_uuid pending_runner reused_runner secret_field)a do
    test "#{mutation} receipt fails after the same valid decoding control" do
      receipt = receipt()
      assert_receipt_control!(receipt)
      changed = mutate_receipt(unquote(mutation), receipt)

      result =
        apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [frame(Jason.encode!(changed))])

      rejected? = result == {:error, :legacy_protocol}
      assert rejected?
      assert_receipt_control!(receipt)
    end
  end

  for mutation <-
        ~w(nonbinary duplicate_top duplicate_nested invalid_utf8 invalid_json truncated_header truncated_body extra_frame diagnostic_prefix diagnostic_body)a do
    test "#{mutation} bytes fail after a valid private frame control" do
      receipt = receipt()
      assert_receipt_control!(receipt)

      result =
        apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [
          mutate_frame(unquote(mutation), receipt)
        ])

      rejected? = result == {:error, :legacy_protocol}
      assert rejected?
    end
  end

  test "a full-boundary configuration accepts before one additional payload byte is rejected" do
    configuration = configuration()
    assert_configuration_control!(configuration)
    remaining = 16_384 - byte_size(Jason.encode!(configuration))
    password = configuration["credentials"]["password"] <> String.duplicate("x", remaining)
    full = put_in(configuration, ["credentials", "password"], password)
    encoded = apply(LegacyUpgradeRuntimeFixture, :encode_configuration!, [full])
    accepted? = byte_size(encoded) == 16_388 and encoded == frame(Jason.encode!(full))
    assert accepted?

    rejected? =
      configuration_rejected?(put_in(full, ["credentials", "password"], password <> "x"))

    assert rejected?
  end

  test "a full-boundary whitespace-padded body accepts before one extra byte exceeds the ceiling" do
    receipt = receipt()
    assert_receipt_control!(receipt)
    json = Jason.encode!(receipt)
    payload = json <> String.duplicate(" ", 65_536 - byte_size(json))
    full = frame(payload)
    result = apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [full])
    accepted? = result == {:ok, receipt} and byte_size(full) == 65_540
    assert accepted?
    result = apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [full <> <<0>>])
    rejected? = result == {:error, :legacy_output_limit}
    assert rejected?
  end

  test "an oversized declared length rejects from its header before JSON parsing" do
    assert_receipt_control!(receipt())

    for bytes <- [
          <<65_537::unsigned-big-integer-size(32)>>,
          <<65_537::unsigned-big-integer-size(32), "!">>,
          String.duplicate("A", 65_541)
        ] do
      result = apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [bytes])
      rejected? = result == {:error, :legacy_output_limit}
      assert rejected?
    end
  end

  defp assert_configuration_control!(configuration) do
    expected = frame(Jason.encode!(configuration))
    encoded = apply(LegacyUpgradeRuntimeFixture, :encode_configuration!, [configuration])
    accepted? = encoded == expected
    assert accepted?
  end

  defp assert_receipt_control!(receipt) do
    result = apply(LegacyUpgradeRuntimeFixture, :decode_receipt!, [frame(Jason.encode!(receipt))])
    accepted? = result == {:ok, receipt}
    assert accepted?
  end

  defp configuration_rejected?(configuration) do
    try do
      apply(LegacyUpgradeRuntimeFixture, :encode_configuration!, [configuration])
      false
    rescue
      error in ArgumentError -> Exception.message(error) == "legacy_configuration"
    end
  end

  defp frame(payload), do: <<byte_size(payload)::unsigned-big-integer-size(32), payload::binary>>

  defp mutate_configuration(mutation, configuration) do
    case mutation do
      :not_map ->
        []

      :missing ->
        Map.delete(configuration, "database_oid")

      :unknown ->
        Map.put(configuration, "codepath", "/current/_build/test/lib/singularity_runtime/ebin")

      :protocol ->
        Map.put(configuration, "protocol", 1.0)

      :fingerprint ->
        Map.put(configuration, "source_fingerprint", String.duplicate("0", 64))

      :oid ->
        Map.put(configuration, "database_oid", 0)

      :oid_type ->
        Map.put(configuration, "database_oid", "123456")

      :relative_root ->
        Map.put(configuration, "object_root", "relative/objects")

      :traversal_root ->
        Map.put(configuration, "build_root", "/contract/../build")

      :nul_root ->
        Map.put(configuration, "object_root", "/contract/objects" <> <<0>>)

      :nested_root ->
        Map.put(configuration, "build_root", configuration["object_root"] <> "/build")

      :repository_keys ->
        update_in(configuration, ["repositories"], &Map.delete(&1, "worker"))

      :repository_missing ->
        update_in(configuration, ["repositories", "request"], &Map.delete(&1, "port"))

      :repository_extra ->
        put_in(configuration, ["repositories", "request", "sql"], "not-executable")

      :repository_role ->
        put_in(configuration, ["repositories", "request", "username"], "singularity_migration")

      :repository_database ->
        put_in(configuration, ["repositories", "request", "database"], "postgres")

      :repository_port ->
        put_in(configuration, ["repositories", "request", "port"], 65_536)

      :credentials_keys ->
        put_in(configuration, ["credentials", "credential_hash"], "forbidden")

      :login_type ->
        put_in(configuration, ["credentials", "login"], 1)

      :empty_password ->
        put_in(configuration, ["credentials", "password"], "")

      :invalid_utf8 ->
        put_in(configuration, ["credentials", "password"], <<255>>)

      :original_keys ->
        update_in(configuration, ["originals"], &Map.delete(&1, "deleted_png_base64"))

      :original_base64 ->
        put_in(configuration, ["originals", "text_pdf_base64"], "!")

      :original_noncanonical ->
        put_in(configuration, ["originals", "text_pdf_base64"], @text_pdf <> "\n")

      :original_size ->
        put_in(
          configuration,
          ["originals", "text_pdf_base64"],
          Base.encode64(String.duplicate("x", 1_025))
        )

      :original_duplicate ->
        put_in(configuration, ["originals", "deleted_png_base64"], @binary_png)

      :original_magic ->
        put_in(configuration, ["originals", "text_pdf_base64"], @binary_png)

      :duplicate_top ->
        configuration
        |> Jason.encode!()
        |> duplicate_json("protocol", "1")
        |> Jason.decode!(objects: :ordered_objects)

      :duplicate_nested ->
        configuration
        |> Jason.encode!()
        |> String.replace("\"credentials\":{", "\"credentials\":{\"login\":\"duplicate\",",
          global: false
        )
        |> Jason.decode!(objects: :ordered_objects)
    end
  end

  defp mutate_receipt(mutation, receipt) do
    case mutation do
      :not_map ->
        []

      :missing ->
        Map.delete(receipt, "work")

      :unknown ->
        Map.put(receipt, "credentials", %{"password" => "forbidden"})

      :protocol ->
        Map.put(receipt, "protocol", "1")

      :fingerprint ->
        Map.put(receipt, "source_fingerprint", String.upcase(@fingerprint))

      :owner_keys ->
        put_in(receipt, ["owner", "credential_hash"], "forbidden")

      :owner_uuid ->
        put_in(receipt, ["owner", "credential_id"], "not-a-uuid")

      :owner_scope ->
        put_in(receipt, ["owner", "vault_id"], "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa")

      :notes_keys ->
        update_in(receipt, ["notes"], &Map.delete(&1, "tombstoned"))

      :note_missing ->
        update_in(receipt, ["notes", "open_conflict"], &Map.delete(&1, "conflict_id"))

      :note_extra ->
        put_in(receipt, ["notes", "open_conflict", "markdown"], "forbidden")

      :note_uuid ->
        put_in(
          receipt,
          ["notes", "open_conflict", "resource_id"],
          String.upcase("abcdefab-cdef-4abc-8def-abcdefabcdef")
        )

      :note_state ->
        put_in(receipt, ["notes", "resolved_conflict", "conflict_state"], "open")

      :note_lineage ->
        put_in(
          receipt,
          ["notes", "resolved_conflict", "merge_version_id"],
          receipt["notes"]["resolved_conflict"]["accepted_version_id"]
        )

      :assets_keys ->
        update_in(receipt, ["assets"], &Map.delete(&1, "deleted_png"))

      :asset_missing ->
        update_in(receipt, ["assets", "text_pdf"], &Map.delete(&1, "object_id"))

      :asset_extra ->
        put_in(receipt, ["assets", "text_pdf", "body"], "forbidden")

      :asset_uuid ->
        put_in(receipt, ["assets", "text_pdf", "asset_id"], 1)

      :asset_hash ->
        put_in(receipt, ["assets", "text_pdf", "sha256"], String.duplicate("g", 64))

      :asset_size ->
        put_in(receipt, ["assets", "text_pdf", "bytes"], 1_025)

      :asset_state ->
        put_in(receipt, ["assets", "text_pdf", "state"], "available")

      :object_lifecycle ->
        put_in(receipt, ["assets", "deleted_png", "object_lifecycle"], "available")

      :duplicate_object ->
        put_in(
          receipt,
          ["assets", "deleted_png", "object_id"],
          receipt["assets"]["binary_png"]["object_id"]
        )

      :duplicate_digest ->
        put_in(
          receipt,
          ["assets", "deleted_png", "sha256"],
          receipt["assets"]["binary_png"]["sha256"]
        )

      :work_keys ->
        put_in(receipt, ["work", "raw_output"], "forbidden")

      :work_encoding ->
        put_in(receipt, ["work", "native_name_encoding"], "latin1")

      :empty_completed ->
        put_in(receipt, ["work", "completed"], [])

      :completed_keys ->
        update_completed(receipt, &Map.put(&1, "checkpoint", %{}))

      :completed_uuid ->
        update_completed(receipt, &Map.put(&1, "progress_id", nil))

      :completed_type ->
        update_completed(receipt, &Map.put(&1, "job_type", "asset_verify"))

      :runner_type ->
        update_completed(receipt, &Map.put(&1, "runner_job_id", 1))

      :runner_noncanonical ->
        update_completed(receipt, &Map.put(&1, "runner_job_id", "01"))

      :event_submission ->
        update_completed(receipt, &Map.put(&1, "submission_id", @owner))

      :pending_keys ->
        put_in(receipt, ["work", "pending_object_cleanup", "effect_id"], @owner)

      :pending_uuid ->
        put_in(receipt, ["work", "pending_object_cleanup", "event_id"], "invalid")

      :pending_runner ->
        put_in(receipt, ["work", "pending_object_cleanup", "runner_job_id"], "0")

      :reused_runner ->
        put_in(receipt, ["work", "pending_object_cleanup", "runner_job_id"], "1")

      :secret_field ->
        put_in(receipt, ["assets", "binary_png", "wrapped_key"], "forbidden")
    end
  end

  defp update_completed(receipt, fun),
    do: update_in(receipt, ["work", "completed"], fn [entry] -> [fun.(entry)] end)

  defp mutate_frame(mutation, receipt) do
    json = Jason.encode!(receipt)

    case mutation do
      :nonbinary ->
        nil

      :duplicate_top ->
        frame(duplicate_json(json, "protocol", "1"))

      :duplicate_nested ->
        frame(
          String.replace(json, "\"owner\":{", "\"owner\":{\"account_id\":\"#{@owner}\",",
            global: false
          )
        )

      :invalid_utf8 ->
        frame(<<255>>)

      :invalid_json ->
        frame("!")

      :truncated_header ->
        <<0, 0, 0>>

      :truncated_body ->
        <<byte_size(json) + 1::unsigned-big-integer-size(32), json::binary>>

      :extra_frame ->
        frame(json) <> frame(json)

      :diagnostic_prefix ->
        <<0, 0, 0, 1, "!">> <> frame(json)

      :diagnostic_body ->
        frame("!" <> json)
    end
  end

  defp duplicate_json(json, key, value),
    do: String.replace(json, "{", "{\"#{key}\":#{value},", global: false)

  # TASK18_PARENT_PROTOCOL_CONTRACT_BEGIN
  @parent_protocol_specs [
    {DBConnection.Query, :db_connection, "lib/db_connection/query.ex"},
    {Ecto.Queryable, :ecto, "lib/ecto/queryable.ex"},
    {Jason.Encoder, :jason, "lib/encoder.ex"},
    {Plug.Exception, :plug, "lib/plug/exceptions.ex"}
  ]
  @parent_protocol_apps ~w(argon2_elixir comeonin db_connection decimal ecto ecto_sql elixir_make jason logger_json mime oban plug plug_crypto postgrex telemetry telemetry_metrics telemetry_poller)a

  test "fixed parent protocol origins preserve the selected identity across unloaded and loaded facts" do
    parent_protocol_entrypoint!()

    for selection <- [:original, :consolidated] do
      observations = parent_protocol_observations(selection)
      paths = parent_protocol_child_paths()
      expected = parent_protocol_snapshot(observations)

      unloaded =
        apply(LegacyUpgradeRuntimeFixture, :validate_parent_protocols!, [observations, paths])

      matches? = unloaded == expected
      assert matches?, "fixed unloaded parent protocol identity must qualify"

      loaded =
        Map.new(observations, fn {module, row} ->
          {module, %{row | loaded_md5: elem(Map.fetch!(expected, module), 1)}}
        end)

      actual = apply(LegacyUpgradeRuntimeFixture, :validate_parent_protocols!, [loaded, paths])
      unchanged? = actual == unloaded and actual == expected
      assert unchanged?, "loading the same selected BEAM must preserve the private snapshot"
    end
  end

  for mutation <- [
        :wrong_app,
        :wrong_module,
        :mismapped_module,
        :missing_module,
        :extra_module,
        :source_path,
        :original_path,
        :consolidated_path,
        :located_path,
        :source_bytes,
        :original_bytes,
        :consolidated_bytes,
        :original_cinf_source,
        :consolidated_cinf_source,
        :loaded_md5,
        :missing_field,
        :extra_field
      ] do
    test "fixed parent protocol identity rejects #{mutation} after the same positive control" do
      parent_protocol_entrypoint!()
      observations = parent_protocol_observations(:consolidated)
      paths = parent_protocol_child_paths()

      for {module, _app, _source} <- @parent_protocol_specs do
        parent_protocol_positive!(observations, paths)
        mutant = parent_protocol_mutant(observations, module, unquote(mutation))
        parent_protocol_rejected!(mutant, paths)
      end
    end
  end

  for mutation <- [:consolidated, :current_singularity, :extra, :missing, :duplicate, :reordered] do
    test "fixed child dependency paths reject #{mutation} after the same positive control" do
      parent_protocol_entrypoint!()
      observations = parent_protocol_observations(:consolidated)
      paths = parent_protocol_child_paths()
      parent_protocol_positive!(observations, paths)

      mutant = parent_protocol_child_mutant(paths, unquote(mutation))

      parent_protocol_rejected!(observations, mutant)
    end
  end

  defp parent_protocol_entrypoint! do
    present? =
      Code.ensure_loaded?(LegacyUpgradeRuntimeFixture) and
        function_exported?(LegacyUpgradeRuntimeFixture, :validate_parent_protocols!, 2)

    assert present?, "fixed parent protocol identity entrypoint is missing"
  end

  defp parent_protocol_project, do: Path.expand("../../../../..", __DIR__)

  defp parent_protocol_child_paths do
    Enum.map(@parent_protocol_apps, fn app ->
      Path.join([parent_protocol_project(), "_build", "test", "lib", Atom.to_string(app), "ebin"])
    end)
  end

  defp parent_protocol_observations(selection) do
    Map.new(@parent_protocol_specs, fn {module, app, relative} ->
      source =
        Path.join([
          "/home/gao/Workspace/gsmlg-opt/Singularity/deps",
          Atom.to_string(app),
          relative
        ])

      filename = Atom.to_string(module) <> ".beam"

      original =
        Path.join([
          parent_protocol_project(),
          "_build",
          "test",
          "lib",
          Atom.to_string(app),
          "ebin",
          filename
        ])

      consolidated =
        Path.join([parent_protocol_project(), "_build", "test", "consolidated", filename])

      {module,
       %{
         app: app,
         source_path: source,
         original_path: original,
         consolidated_path: consolidated,
         source_bytes: File.read!(source),
         original_bytes: File.read!(original),
         consolidated_bytes: File.read!(consolidated),
         located_path: if(selection == :original, do: original, else: consolidated),
         loaded_md5: :unloaded
       }}
    end)
  end

  defp parent_protocol_snapshot(observations) do
    Map.new(observations, fn {module, row} ->
      bytes =
        if row.located_path == row.original_path,
          do: row.original_bytes,
          else: row.consolidated_bytes

      {module, {row.located_path, parent_protocol_md5!(module, bytes)}}
    end)
  end

  defp parent_protocol_md5!(module, bytes) do
    case :beam_lib.md5(bytes) do
      {:ok, {^module, md5}} when is_binary(md5) and byte_size(md5) == 16 -> md5
      _ -> flunk("fixed parent protocol BEAM MD5 is unavailable")
    end
  end

  defp parent_protocol_positive!(observations, paths) do
    actual =
      apply(LegacyUpgradeRuntimeFixture, :validate_parent_protocols!, [observations, paths])

    matches? = actual == parent_protocol_snapshot(observations)
    assert matches?, "the same fixed parent protocol control must qualify first"
  end

  defp parent_protocol_rejected!(observations, paths) do
    rejected? =
      try do
        apply(LegacyUpgradeRuntimeFixture, :validate_parent_protocols!, [observations, paths])
        false
      rescue
        error in ArgumentError -> Exception.message(error) == "legacy_dependency_identity"
      end

    assert rejected?, "fixed parent protocol mutant must fail with its content-free category"
  end

  defp parent_protocol_child_mutant(paths, mutation) do
    case mutation do
      :consolidated ->
        paths ++ [Path.join(parent_protocol_project(), "_build/test/consolidated")]

      :current_singularity ->
        paths ++
          [Path.join(parent_protocol_project(), "_build/test/lib/singularity_runtime/ebin")]

      :extra ->
        paths ++ [Path.join(parent_protocol_project(), "_build/test/lib/ex_cmd/ebin")]

      :missing ->
        tl(paths)

      :duplicate ->
        [hd(paths) | paths]

      :reordered ->
        Enum.reverse(paths)
    end
  end

  defp parent_protocol_mutant(observations, module, mutation) do
    row = Map.fetch!(observations, module)

    case mutation do
      :wrong_app ->
        put_in(observations, [module, :app], :singularity_runtime)

      :wrong_module ->
        observations |> Map.delete(module) |> Map.put(LegacyUpgradeRuntimeFixture, row)

      :mismapped_module ->
        {_other, other_row} = Enum.find(observations, fn {other, _row} -> other != module end)
        Map.put(observations, module, other_row)

      :missing_module ->
        Map.delete(observations, module)

      :extra_module ->
        Map.put(observations, LegacyUpgradeRuntimeFixture, row)

      field when field in [:source_path, :original_path, :consolidated_path, :located_path] ->
        put_in(observations, [module, field], Map.fetch!(row, field) <> ".invalid")

      field when field in [:source_bytes, :original_bytes, :consolidated_bytes] ->
        bytes = Map.fetch!(row, field)
        changed = parent_protocol_flip(bytes)
        same_size? = byte_size(changed) == byte_size(bytes) and changed != bytes
        assert same_size?, "program-byte mutant must change bytes without changing length"
        put_in(observations, [module, field], changed)

      field when field in [:original_cinf_source, :consolidated_cinf_source] ->
        target = if field == :original_cinf_source, do: :original_bytes, else: :consolidated_bytes
        changed = parent_protocol_cinf_mutant!(module, Map.fetch!(row, target))
        put_in(observations, [module, target], changed)

      :loaded_md5 ->
        selected = parent_protocol_md5!(module, row.consolidated_bytes)
        put_in(observations, [module, :loaded_md5], parent_protocol_flip(selected))

      :missing_field ->
        Map.put(observations, module, Map.delete(row, :source_bytes))

      :extra_field ->
        Map.put(observations, module, Map.put(row, :unexpected, true))
    end
  end

  defp parent_protocol_flip(<<first, rest::binary>>) do
    changed = if first == 0, do: 1, else: 0
    <<changed, rest::binary>>
  end

  # CInf mutation also violates the fixed raw SHA pin; this is overlapping
  # defense coverage, not independent causal proof of the metadata predicate.
  defp parent_protocol_cinf_mutant!(module, bytes) do
    case :beam_lib.all_chunks(bytes) do
      {:ok, ^module, chunks} ->
        changed =
          Enum.map(chunks, fn
            {~c"CInf", encoded} ->
              information = :erlang.binary_to_term(encoded, [:safe])
              altered = Keyword.update!(information, :source, &(&1 ++ ~c".invalid"))
              {~c"CInf", :erlang.term_to_binary(altered)}

            chunk ->
              chunk
          end)

        case :beam_lib.build_module(changed) do
          {:ok, mutant} ->
            changed? = mutant != bytes
            assert changed?, "fixed CInf source mutant must alter the original BEAM"
            mutant

          _ ->
            flunk("fixed parent protocol CInf mutation could not be built")
        end

      _ ->
        flunk("fixed parent protocol chunks are unavailable")
    end
  end

  # TASK18_PARENT_PROTOCOL_CONTRACT_END

  # TASK18_BACKEND_ATTRIBUTION_CONTRACT_BEGIN
  test "backend attribution retains only bounded offender evidence and corroborated lifetimes" do
    # Independent JSON-ready literal, never derived from the sampler under test.
    literal = fn ->
      %{
        "version" => 1,
        "sequence" => 1,
        "stage" => "gate",
        "scenario" => "declared_oversize",
        "columns" => 3,
        "result" => "rows",
        "row_count" => 3,
        "database_oid" => 77,
        "child_pid" => 22,
        "baseline_pids" => [11],
        "authority" => "verified",
        "capture" => "complete",
        "clock" => %{
          "before_ns" => "-9007199254740995",
          "query_before_ns" => "-9007199254740994",
          "query_after_ns" => "-9007199254740993",
          "after_ns" => "-9007199254740992"
        },
        "candidates" => [
          %{
            "kind" => "invalid_row",
            "row_index" => 2,
            "pid" => 33,
            "shape" => "three",
            "username" => "null",
            "backend" => "null",
            "child_relation" => "different",
            "baseline_relation" => "absent",
            "before" => %{
              "pid" => 33,
              "datid" => 77,
              "usesysid" => "unavailable",
              "backend" => "autovacuum_worker",
              "backend_start_us" => "9007199254740993"
            },
            "after" => %{
              "pid" => 33,
              "datid" => 77,
              "usesysid" => "unavailable",
              "backend" => "autovacuum_worker",
              "backend_start_us" => "9007199254740993"
            },
            "attribution" => "same_incarnation_bracket_corroborated"
          }
        ]
      }
    end

    input = fn ->
      metadata = %{
        pid: 33,
        datid: 77,
        usesysid: nil,
        backend_type: "autovacuum worker",
        backend_start_us: 9_007_199_254_740_993
      }

      {
        {:ok,
         %Postgrex.Result{
           rows: [
             [11, "singularity_migration", "client backend"],
             [22, "singularity_migration", "client backend"],
             [33, nil, nil]
           ]
         }},
        %{
          sequence: 1,
          stage: :gate,
          scenario: :declared_oversize,
          columns: 3,
          database_oid: 77,
          child_pid: 22,
          baseline: [{11, "singularity_migration"}],
          authority: :verified,
          capture: :complete,
          before_ns: -9_007_199_254_740_995,
          query_before_ns: -9_007_199_254_740_994,
          query_after_ns: -9_007_199_254_740_993,
          after_ns: -9_007_199_254_740_992,
          before: [metadata],
          after: [metadata]
        }
      }
    end

    positive = fn ->
      expected = literal.()
      literal_valid? = transport_backend_attribution_valid?(expected) == true
      assert literal_valid?, "independent attribution literal must qualify"

      {result, context} = input.()
      observed = transport_backend_attribution_sample(result, context)
      exact? = observed === expected
      assert exact?, "sampler must match independent offender evidence"

      encoded = Jason.encode!(observed)
      bounded? = byte_size(encoded) <= 32_768 and Jason.decode!(encoded) === expected
      assert bounded?, "attribution record must preserve exact bounded JSON values"
      expected
    end

    positive.()

    candidate = ["candidates", Access.at(0)]
    before = candidate ++ ["before"]
    after_sample = candidate ++ ["after"]

    map_paths = [[], ["clock"], candidate, before, after_sample]

    # Every deletion/type/unknown-field mutant gets a fresh independent control.
    for path <- map_paths do
      fields = Map.keys(if(path == [], do: literal.(), else: get_in(literal.(), path)))

      for field <- fields do
        valid = positive.()

        mutant =
          if path == [],
            do: Map.delete(valid, field),
            else: update_in(valid, path, &Map.delete(&1, field))

        rejected? = transport_backend_attribution_valid?(mutant) == false
        assert rejected?, "missing attribution field must fail closed"

        valid = positive.()
        mutant = put_in(valid, path ++ [field], {:invalid, :type})
        rejected? = transport_backend_attribution_valid?(mutant) == false
        assert rejected?, "wrong attribution field type must fail closed"
      end

      valid = positive.()

      mutant =
        if path == [],
          do: Map.put(valid, "unexpected", "ATTRIBUTION_CANARY"),
          else: update_in(valid, path, &Map.put(&1, "unexpected", "ATTRIBUTION_CANARY"))

      rejected? = transport_backend_attribution_valid?(mutant) == false
      assert rejected?, "unknown attribution field must fail closed"
    end

    mutants = [
      {["version"], 2},
      {["sequence"], 0},
      {["sequence"], 33},
      {["stage"], "unknown"},
      {["scenario"], "unknown"},
      {["columns"], 4},
      {["result"], "query_error"},
      {["row_count"], 2},
      {["row_count"], 65},
      {["row_count"], 1.5},
      {["row_count"], "overflow"},
      {["database_oid"], 0},
      {["database_oid"], 78},
      {["database_oid"], 4_294_967_296},
      {["child_pid"], 0},
      {["child_pid"], 33},
      {["child_pid"], 2_147_483_648},
      {["baseline_pids"], [11, 11]},
      {["baseline_pids"], [33]},
      {["baseline_pids"], [0]},
      {["baseline_pids"], Enum.to_list(1..65)},
      {["authority"], "unavailable"},
      {["authority"], "failed"},
      {["capture"], "overflow"},
      {["capture"], "failed"},
      {["clock", "before_ns"], "-09007199254740995"},
      {["clock", "before_ns"], "-0"},
      {["clock", "before_ns"], "9223372036854775808"},
      {["clock", "before_ns"], "-9223372036854775809"},
      {["clock", "before_ns"], "+1"},
      {["clock", "before_ns"], "1.0"},
      {["clock", "query_before_ns"], "-9007199254740996"},
      {["clock", "query_after_ns"], "-9007199254740995"},
      {["clock", "after_ns"], "-9007199254740994"},
      {candidate ++ ["kind"], "missing"},
      {candidate ++ ["row_index"], -1},
      {candidate ++ ["row_index"], 3},
      {candidate ++ ["pid"], 0},
      {candidate ++ ["pid"], 34},
      {candidate ++ ["pid"], 33.5},
      {candidate ++ ["pid"], 2_147_483_648},
      {candidate ++ ["shape"], "two"},
      {candidate ++ ["username"], "ATTRIBUTION_CANARY"},
      {candidate ++ ["backend"], "ATTRIBUTION_CANARY"},
      {candidate ++ ["child_relation"], "same"},
      {candidate ++ ["child_relation"], "unavailable"},
      {candidate ++ ["baseline_relation"], "present"},
      {candidate ++ ["baseline_relation"], "unavailable"},
      {candidate ++ ["attribution"], "atomic_snapshot"},
      {before ++ ["pid"], 34},
      {after_sample ++ ["pid"], 34},
      {before ++ ["datid"], 78},
      {after_sample ++ ["datid"], 78},
      {before ++ ["usesysid"], 0},
      {after_sample ++ ["usesysid"], 4_294_967_296},
      {after_sample ++ ["usesysid"], 99},
      {before ++ ["backend"], "unknown"},
      {after_sample ++ ["backend"], "client"},
      {before ++ ["backend_start_us"], "0"},
      {before ++ ["backend_start_us"], "09007199254740993"},
      {before ++ ["backend_start_us"], "-1"},
      {after_sample ++ ["backend_start_us"], "9007199254740994"},
      {after_sample ++ ["backend_start_us"], "9007199254740993.0"},
      {after_sample ++ ["backend_start_us"], "9223372036854775808"},
      {candidate ++ ["before"], "unavailable"},
      {candidate ++ ["after"], "unavailable"},
      {["clock"], "unavailable"},
      {["candidates"], List.duplicate(hd(literal.()["candidates"]), 9)},
      {["candidates"], List.duplicate(hd(literal.()["candidates"]), 2)}
    ]

    for {path, value} <- mutants do
      valid = positive.()
      mutant = put_in(valid, path, value)
      rejected? = transport_backend_attribution_valid?(mutant) == false
      assert rejected?, "forged attribution claim must fail closed"
    end

    for value <- [nil, [], true, %Postgrex.Result{}, %{"unexpected" => "ATTRIBUTION_CANARY"}] do
      positive.()
      rejected? = transport_backend_attribution_valid?(value) == false
      assert rejected?, "nonrecord attribution value must fail closed"
    end

    # Unresolved is honest evidence, not a disguised corroborated claim.
    unresolved_changes = [
      {["authority"], "unavailable"},
      {["authority"], "failed"},
      {["clock"], "unavailable"},
      {candidate ++ ["before"], "unavailable"},
      {candidate ++ ["after"], "unavailable"},
      {after_sample ++ ["pid"], 34},
      {after_sample ++ ["datid"], 78},
      {after_sample ++ ["usesysid"], 99},
      {after_sample ++ ["backend"], "client"},
      {after_sample ++ ["backend_start_us"], "9007199254740994"}
    ]

    for {path, value} <- unresolved_changes do
      valid = positive.()

      unresolved =
        valid
        |> put_in(path, value)
        |> put_in(candidate ++ ["attribution"], "unresolved")

      accepted? = transport_backend_attribution_valid?(unresolved) == true
      assert accepted?, "explicit unresolved evidence must remain representable"

      positive.()

      forged =
        put_in(unresolved, candidate ++ ["attribution"], "same_incarnation_bracket_corroborated")

      rejected? = transport_backend_attribution_valid?(forged) == false
      assert rejected?, "unresolved evidence cannot claim a corroborated lifetime"
    end

    # Each adverse sampler input starts after the same independent positive.
    row_cases = [
      {[
         [11, "singularity_migration", "client backend"],
         [22, "singularity_migration", "client backend"],
         [33, nil, nil]
       ], %{}, 33, "three", "null", "null", "different", "absent"},
      {[[11, nil, nil], [22, "singularity_migration", "client backend"]], %{}, 11, "three",
       "null", "null", "different", "present"},
      {[[11, "singularity_migration", "client backend"], [22, nil, nil]], %{}, 22, "three",
       "null", "null", "same", "absent"},
      {[[33, nil]],
