      {[[nil, nil, nil]], %{baseline: :unavailable, child_pid: :unavailable}, "unavailable",
       "three", "null", "null", "unavailable", "unavailable"},
      {[[33, nil, nil, "ATTRIBUTION_CANARY"]], %{baseline: :unavailable, child_pid: :unavailable},
       "unavailable", "other", "unavailable", "unavailable", "unavailable", "unavailable"},
      {["ATTRIBUTION_CANARY"], %{baseline: :unavailable, child_pid: :unavailable}, "unavailable",
       "other", "unavailable", "unavailable", "unavailable", "unavailable"},
      {[[33, {:secret, "ATTRIBUTION_CANARY"}, "ATTRIBUTION_CANARY"]],
