      matching? =
        case observed["candidates"] do
          [row] -> Map.take(row, Map.keys(expected)) === expected
          _ -> false
        end

      valid? = transport_backend_attribution_valid?(observed) == true
      private? = not String.contains?(Jason.encode!(observed), "ATTRIBUTION_CANARY")
      stage? = observed["stage"] === Atom.to_string(context.stage)

      assert matching? and valid? and private? and stage?,
