             "shape" => "missing",
             "username" => "unavailable"
           }}
        ] do
      positive.()
      {_result, context} = input.()

      observed =
        transport_backend_attribution_sample({:ok, %Postgrex.Result{rows: rows}}, context)

      matching? =
        case observed["candidates"] do
          [row] -> Map.take(row, Map.keys(expected)) === expected
          _ -> false
        end

      valid? = transport_backend_attribution_valid?(observed) == true
      private? = not String.contains?(Jason.encode!(observed), "ATTRIBUTION_CANARY")

      assert matching? and valid? and private?,
             "membership anomalies must not fabricate current rows"
    end

    for {result, expected} <- [
          {{:error, %{message: "ATTRIBUTION_CANARY"}}, "query_error"},
          {{:ok, %Postgrex.Result{rows: nil}}, "malformed_result"},
          {{:ok, %{rows: [[33, nil, nil]], query: "ATTRIBUTION_CANARY"}}, "malformed_result"},
          {"ATTRIBUTION_CANARY", "malformed_result"}
        ] do
      positive.()
      {_result, context} = input.()
      observed = transport_backend_attribution_sample(result, context)

      safe? =
        observed["result"] == expected and observed["row_count"] == "unavailable" and
          observed["candidates"] == [] and transport_backend_attribution_valid?(observed) == true and
          not String.contains?(Jason.encode!(observed), "ATTRIBUTION_CANARY")

      assert safe?, "unavailable query evidence must remain bounded and explicit"
    end

    context_mutants = [
