        boundary["capture"] == "complete" and boundary["candidates"] == [] and
        transport_backend_attribution_valid?(boundary) == true

    assert boundary?, "exact diagnostic row metadata and record limits must remain usable"

    positive.()
    {_result, context} = input.()
    eight = {:ok, %Postgrex.Result{rows: Enum.map(31..38, &[&1, nil, nil])}}
    boundary = transport_backend_attribution_sample(eight, %{context | baseline: :unavailable})

    boundary? =
