        transport_backend_attribution_valid?(boundary) == true and
        byte_size(Jason.encode!(boundary)) <= 32_768

    assert boundary?, "eight complete candidate records must fit the finite evidence budget"

    positive.()
    {result, context} = input.()
    failed = transport_backend_attribution_sample(result, %{context | capture: :failed})

    finite_failure? =
      failed["capture"] == "failed" and failed["candidates"] == [] and
        transport_backend_attribution_valid?(failed) == true

    assert finite_failure?, "capture failure must remain explicit and unattributed"

    positive.()
    {result, context} = input.()

    limited? =
      transport_backend_attribution_sample(result, %{context | sequence: 33}) ==
        {:error, :record_limit}

    assert limited?, "a diagnostic observation must not exceed its record cap"

    positive.()
    {result, context} = input.()

    positive_clock =
      %{context | before_ns: 1, query_before_ns: 2, query_after_ns: 3, after_ns: 4}

    observed = transport_backend_attribution_sample(result, positive_clock)

    exact_clock? =
      observed["clock"] == %{
        "before_ns" => "1",
        "query_before_ns" => "2",
        "query_after_ns" => "3",
        "after_ns" => "4"
      } and transport_backend_attribution_valid?(observed) == true

    assert exact_clock?, "positive and signed negative monotonic clocks must remain exact"

    positive.()
    {_result, context} = input.()

    clean =
      {:ok,
       %Postgrex.Result{
         rows: [
           [11, "singularity_migration", "client backend"],
           [22, "singularity_migration", "client backend"]
         ]
       }}

    observed = transport_backend_attribution_sample(clean, context)

    clean? =
      observed["candidates"] == [] and transport_backend_attribution_valid?(observed) == true

    assert clean?, "a clean sample must not invent an offending backend"
  end

