  test "a real pre-allocation start rejection closes before automatic database removal" do
    transport_entrypoint!()
    control = transport_observation(:clean_frame)
    controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
    assert controlled?, "the same real clean transport must qualify before rejection"

    proof = start_failure_observation()
    IO.puts("Task18 actual no-start observation: " <> inspect(proof.summary))
    assert proof.evidence?, "actual rejection, guards, origins and original custody must qualify"
    assert proof.hygiene?, "retained quarantine must be safely recovered without cleanup credit"
    assert proof.closed?, "the known no-allocation rejection must report real closed cleanup"
    assert proof.dropped?, "ordinary cleanup, not diagnostic recovery, must remove exact A"
    assert proof.secondary_free?, "known no-allocation rejection must have no secondary failure"
    valid? = start_failure_valid?(proof.witness)
    assert valid?, "the independent ordered no-start witness must be complete"
  end

  test "no-start predicates reject each missing, foreign or reordered fact after a literal control" do
    positive = fn ->
      owner = self()
      actor = Process.group_leader()
      key = make_ref()
      origins = Enum.map([:process, :exec, :gen_server], fn label ->
        Map.new([{:label, label} | Enum.map(@start_failure_origin_fields, &{&1, true})])
      end)
      %{
        key: key, trace_key: key, owner: owner, actor: actor,
        start_owner: owner, return_owner: owner, sql_owner: owner,
        database: @database, oid: 1, origins_before: origins, origins_after: origins,
        installed?: true, start_guard?: true, gen_guard?: true, await_guard?: true,
        flags?: true, tracer?: true, extra_guards?: true,
        restored?: true, fence?: true, drained?: true,
        owner_normal?: true, actor_normal?: true, resources_down?: true,
        baseline?: true, private?: true, roots?: true, workspace_owned?: true,
        workspace_empty?: true, no_ready?: true, no_handle?: true,
        start_calls: 1, start_returns: 1, gen_calls: 0, await_calls: 0,
        sql_calls: 1, sql_returns: 1, rmdir_calls: 1, rmdir_returns: 1,
        enoent_calls: 1, enoent_returns: 1, cleanup_events: 1,
        result: :known_error, sql: :zero, rmdir: :ok, lstat: :enoent,
        cleanup: :closed, secondary: :none, ordinary_drop?: true,
        order: Enum.zip([:arm, :directory, :call, :return, :sql_call, :sql_zero,
          :rmdir_call, :rmdir_ok, :lstat_call, :enoent, :independent, :closed,
          :cleanup_event, :drop], 1..14)
      }
    end
    booleans = ~w(installed? start_guard? gen_guard? await_guard? flags? tracer? extra_guards? restored? fence? drained? owner_normal? actor_normal? resources_down? baseline? private? roots? workspace_owned? workspace_empty? no_ready? no_handle? ordinary_drop?)a
    counters = ~w(start_calls start_returns sql_calls sql_returns rmdir_calls rmdir_returns enoent_calls enoent_returns cleanup_events)a
    mutations =
      Enum.map(Map.keys(positive.()), fn key -> fn w -> Map.delete(w, key) end end) ++
      Enum.map(booleans, fn key -> fn w -> Map.put(w, key, false) end end) ++
      Enum.flat_map(counters, fn key -> for n <- [0, 2], do: fn w -> Map.put(w, key, n) end end) ++
      Enum.map([:gen_calls, :await_calls], fn key -> fn w -> Map.put(w, key, 1) end end) ++
      Enum.map([:start_owner, :return_owner, :sql_owner], fn key -> fn w -> Map.put(w, key, :foreign) end end) ++
      [fn w -> %{w | trace_key: make_ref()} end,
       fn w -> Map.put(w, :extra, true) end,
       fn w -> %{w | result: :other} end, fn w -> %{w | result: :exception} end,
       fn w -> %{w | sql: :other} end, fn w -> %{w | rmdir: :other} end,
       fn w -> %{w | lstat: :present} end, fn w -> %{w | cleanup: :unconfirmed} end,
       fn w -> %{w | secondary: :quarantined} end, fn w -> %{w | oid: 0} end,
       fn w -> %{w | database: "foreign"} end,
       fn w -> %{w | order: tl(w.order)} end,
       fn w -> %{w | order: Enum.reverse(w.order)} end,
       fn w -> %{w | order: w.order ++ [List.last(w.order)]} end] ++
      Enum.flat_map(0..13, fn index ->
        [fn w -> %{w | order: List.delete_at(w.order, index)} end,
         fn w -> %{w | order: List.insert_at(w.order, index, Enum.at(w.order, index))} end,
         fn w -> %{w | order: List.update_at(w.order, index, fn {stage, _} -> {stage, nil} end)} end]
      end) ++
      Enum.flat_map([:origins_before, :origins_after], fn phase ->
        [fn w -> Map.put(w, phase, []) end,
         fn w -> Map.update!(w, phase, &tl/1) end,
         fn w -> Map.update!(w, phase, &(&1 ++ [hd(&1)])) end,
         fn w -> Map.update!(w, phase, fn [row | rows] -> [%{row | label: :foreign} | rows] end) end] ++
        Enum.flat_map(@start_failure_origin_fields, fn field ->
          [fn w -> Map.update!(w, phase, fn [row | rows] -> [Map.put(row, field, false) | rows] end) end,
           fn w -> Map.update!(w, phase, fn [row | rows] -> [Map.delete(row, field) | rows] end) end]
        end)
      end)
    for mutate <- mutations do
      witness = positive.()
      accepted? = start_failure_valid?(witness)
      assert accepted?, "the independent literal no-start control must qualify first"
      rejected? = not start_failure_valid?(mutate.(witness))
      assert rejected?, "a changed no-start fact must not receive cleanup credit"
    end
  end

  defp start_failure_valid?(w) when is_map(w) and not is_struct(w) do
    expected = ~w(key trace_key owner actor start_owner return_owner sql_owner database oid origins_before origins_after installed? start_guard? gen_guard? await_guard? flags? tracer? extra_guards? restored? fence? drained? owner_normal? actor_normal? resources_down? baseline? private? roots? workspace_owned? workspace_empty? no_ready? no_handle? start_calls start_returns gen_calls await_calls sql_calls sql_returns rmdir_calls rmdir_returns enoent_calls enoent_returns cleanup_events result sql rmdir lstat cleanup secondary ordinary_drop? order)a
    labels = [:arm, :directory, :call, :return, :sql_call, :sql_zero, :rmdir_call,
      :rmdir_ok, :lstat_call, :enoent, :independent, :closed, :cleanup_event, :drop]
    booleans = ~w(installed? start_guard? gen_guard? await_guard? flags? tracer? extra_guards? restored? fence? drained? owner_normal? actor_normal? resources_down? baseline? private? roots? workspace_owned? workspace_empty? no_ready? no_handle? ordinary_drop?)a
    counters = ~w(start_calls start_returns sql_calls sql_returns rmdir_calls rmdir_returns enoent_calls enoent_returns cleanup_events)a
    with true <- Enum.sort(Map.keys(w)) == Enum.sort(expected),
         true <- is_reference(w.key) and w.key == w.trace_key,
         true <- is_pid(w.owner) and is_pid(w.actor) and w.owner != w.actor,
         true <- Enum.all?([w.start_owner, w.return_owner, w.sql_owner], &(&1 == w.owner)),
         true <- is_binary(w.database) and Regex.match?(~r/\Asingularity_test_[0-9a-f]{24}\z/, w.database),
         true <- is_integer(w.oid) and w.oid > 0,
         true <- start_failure_origins_valid?(w.origins_before),
         true <- w.origins_before == w.origins_after,
         true <- Enum.all?(booleans, &(Map.fetch!(w, &1) == true)),
         true <- Enum.all?(counters, &(Map.fetch!(w, &1) == 1)),
         true <- w.gen_calls == 0 and w.await_calls == 0,
         true <- {w.result, w.sql, w.rmdir, w.lstat, w.cleanup, w.secondary} ==
                   {:known_error, :zero, :ok, :enoent, :closed, :none},
         true <- is_list(w.order) and length(w.order) == length(labels),
         true <- Enum.map(w.order, &elem(&1, 0)) == labels,
         times <- Enum.map(w.order, &elem(&1, 1)),
         true <- Enum.all?(times, &is_integer/1),
         true <- Enum.all?(Enum.chunk_every(times, 2, 1, :discard), fn [a,b] -> a < b end) do
      true
    else
      _ -> false
    end
  rescue
    _ -> false
  end
