  defp start_failure_sha(bytes), do: Base.encode16(:crypto.hash(:sha256, bytes), case: :lower)

  defp start_failure_gen_server_beam!(canonical, bytes, sha) do
    transport_require!(canonical == @start_failure_elixir <> "/lib/elixir/lib/elixir/ebin/Elixir.GenServer.beam")
    alternate = @start_failure_elixir <> "/lib/elixir/bin/../lib/elixir/ebin/Elixir.GenServer.beam"
    start_failure_launcher!()
    canonical_before = start_failure_fixed_stat!(canonical, :regular)
    alternate_before = start_failure_fixed_stat!(alternate, :regular)
    transport_require!(start_failure_file_identity(canonical_before) == start_failure_file_identity(alternate_before))
    canonical_data = File.read!(canonical)
    alternate_data = File.read!(alternate)
    transport_require!(byte_size(canonical_data) == bytes and start_failure_sha(canonical_data) == sha)
    transport_require!(alternate_data == canonical_data)
    transport_require!(start_failure_file_identity(start_failure_fixed_stat!(canonical, :regular)) == start_failure_file_identity(canonical_before))
    transport_require!(start_failure_file_identity(start_failure_fixed_stat!(alternate, :regular)) == start_failure_file_identity(alternate_before))
    origin = :code.which(GenServer)
    transport_require!(origin in [String.to_charlist(canonical), String.to_charlist(alternate)])
    {canonical_data, origin, true}
  end

