    transport_require!(byte_size(distribution_data) == 6_711 and start_failure_sha(distribution_data) == "39c124fec322a56171da6ce5420be0b897e5379fb9b252012decf9b1364bbf6a")
    transport_require!(start_failure_file_identity(File.stat!(wrapped)) == start_failure_file_identity(distribution_before))
    transport_require!(start_failure_file_identity(start_failure_fixed_stat!(wrapper, :regular)) == start_failure_file_identity(wrapper_before))
    transport_require!(start_failure_file_identity(start_failure_fixed_stat!(wrapped, :symlink)) == start_failure_file_identity(wrapped_before))
    transport_require!(start_failure_file_identity(start_failure_fixed_stat!(distribution, :regular)) == start_failure_file_identity(distribution_before))
    transport_require!(File.read_link!(wrapped) == "../lib/elixir/bin/elixir")
