  defp start_failure_fixed_stat!(path, leaf_type) do
    allowed = [
      {@start_failure_elixir <> "/lib/elixir/lib/elixir/ebin/Elixir.GenServer.beam", :regular},
      {@start_failure_elixir <> "/lib/elixir/bin/../lib/elixir/ebin/Elixir.GenServer.beam", :regular},
      {@start_failure_elixir <> "/bin/elixir", :regular},
      {@start_failure_elixir <> "/bin/.elixir-wrapped", :symlink},
      {@start_failure_elixir <> "/lib/elixir/bin/elixir", :regular}
    ]
    transport_require!({path, leaf_type} in allowed)
    %File.Stat{type: :directory, uid: 0} = File.lstat!("/")
    # Concatenation deliberately retains the one fixed bin/.. component.
    Enum.reduce(String.split(path, "/", trim: true), "", fn part, prefix ->
      literal = prefix <> "/" <> part
      stat = File.lstat!(literal)
      transport_require!(stat.uid == 0 and stat.type == if(literal == path, do: leaf_type, else: :directory))
      literal
    end)
    File.lstat!(path)
  end

  defp start_failure_file_identity(stat),
    do: {stat.major_device, stat.minor_device, stat.inode, stat.uid, stat.size}

  defp start_failure_regular!(path) do
    start_failure_ancestors(path)
    %File.Stat{type: :regular} = File.lstat!(path)
    :ok
