  defp start_failure_ancestors(path) do
    transport_require!(transport_workspace_path?(path))
    parent = Path.dirname(path)
    if parent != path, do: start_failure_ancestors(parent)
    %File.Stat{type: :directory} = File.lstat!(parent)
    :ok
  end

  defp start_failure_directory(path) do
    start_failure_ancestors(path)
    %File.Stat{type: :directory, uid: 1000, major_device: major, minor_device: minor,
      inode: inode, mode: mode} = File.lstat!(path)
    transport_require!(Bitwise.band(mode, 0o7777) == 0o700)
    {major, minor, inode}
