  defp start_failure_roots(destination) do
    allocation = Path.dirname(destination.object_root)
    transport_require!(Regex.match?(~r/\Asingularity_test_[0-9a-f]{24}\z/, destination.database))
    suffix = String.replace_prefix(destination.database, "singularity_test_", "")
    transport_require!(allocation == Path.join([System.tmp_dir!(), "singularity", "integration", suffix]))
    transport_require!(destination.object_root == Path.join(allocation, "objects"))
    paths = [allocation, destination.object_root]
    ancestors = paths |> Enum.flat_map(&start_failure_ancestor_paths/1) |> Enum.uniq()
    %{allocation: allocation, objects: destination.object_root,
      workspace: Path.join(allocation, "historical-build"),
      directories: Map.new(paths, &{&1, start_failure_directory(&1)}),
      ancestors: Map.new(ancestors, fn path ->
        %File.Stat{type: :directory, major_device: major, minor_device: minor, inode: inode} = File.lstat!(path)
        {path, {major, minor, inode}}
      end)}
  end

  defp start_failure_ancestor_paths(path) do
    parent = Path.dirname(path)
    if parent == path, do: [path], else: [path | start_failure_ancestor_paths(parent)]
  end

  defp start_failure_roots_same?(roots) do
    Enum.all?(roots.ancestors, fn {path, identity} ->
      case File.lstat(path) do
        {:ok, %File.Stat{type: :directory, major_device: major, minor_device: minor, inode: inode}} ->
          identity == {major, minor, inode}
        _ -> false
      end
    end) and Enum.all?(roots.directories, fn {path, identity} -> start_failure_directory(path) == identity end)
  rescue
    _ -> false
  catch
    _, _ -> false
  end

  defp start_failure_actor(parent, key, deadline) do
    parent_monitor = Process.monitor(parent)
    checkpoint = fn stage, resources ->
      if stage == :before_arm,
        do: send(parent, {key, :owner_registered, resources.owner, self(), is_nil(resources.on_exit)})
      if Map.has_key?(resources, :maintenance), do: Process.put({key, :resources}, resources)
      if stage == :root_created do
        roots = start_failure_roots(%{database: resources.names.database,
          object_root: Path.join(resources.names.storage_root, "objects")})
        Process.put({key, :roots}, roots)
      end
      if stage in [:ready, :before_database_drop, :owner_cleanup_completed, :owner_cleanup_failed],
        do: send(parent, {key, :checkpoint, self(), stage, System.monotonic_time()})
      :ok
    end
    prepare = fn destination, context ->
      owner = self()
      transport_require!(context.caller != owner and Enum.sort(Map.keys(context)) == [:caller, :report_cleanup])
      send(parent, {key, :prepare, owner, context.caller, destination,
        Process.get({key, :roots}), Process.get({key, :resources})})
      monitor = Process.monitor(parent)
      try do
        receive do
          {^key, :armed, ^parent} -> :ok
          {^key, :abort, ^parent} -> throw(:legacy_transport_observer)
          {:DOWN, ^monitor, :process, ^parent, _} -> throw(:legacy_transport_observer)
        after
          min(5_000, max(0, deadline - System.monotonic_time(:millisecond))) -> throw(:legacy_transport_observer)
        end
      after
        Process.demonitor(monitor, [:flush])
      end
      report = fn status ->
        transport_require!(self() == owner)
        if status == :closed do
          monitor = Process.monitor(parent)
          send(parent, {key, :preclosed, owner})
          try do
            receive do
              {^key, :release_closed, ^parent, ^owner} -> :ok
              {:DOWN, ^monitor, :process, ^parent, _} -> throw(:legacy_transport_observer)
            after
              max(0, deadline - System.monotonic_time(:millisecond)) -> throw(:legacy_transport_observer)
            end
          after
            Process.demonitor(monitor, [:flush])
          end
        end
        result = context.report_cleanup.(status)
        send(parent, {key, :report, owner, status, System.monotonic_time()})
        result
      end
      apply(LegacyUpgradeRuntimeFixture, :probe_transport!, [destination,
        %{caller: context.caller, report_cleanup: report}, :start_failure, parent])
    end
    try do
      {owner, _, _} = Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.with_checkpoint(checkpoint, fn ->
        Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.open_legacy_v0_1_0(prepare)
      end)
      Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.close(owner)
      send(parent, {key, :outcome, :unexpected_success, false, false})
    rescue
      error in Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.PreparationError ->
        {queued, queued?} = transport_queued(nil, [], true)
        private? = not transport_contains?(Exception.message(error)) and
          not transport_contains?(inspect(error, limit: :infinity, printable_limit: :infinity))
        cleanup = cond do
          error.cleanup == [] -> :none
          error.cleanup == [{:legacy_preparation_quarantined, :unconfirmed}] -> :quarantined
          true -> :other
        end
        queue? = queued? and queued in [[], [{:cleanup, :closed}]]
        send(parent, {key, :outcome, {error.primary == :legacy_start, cleanup}, private?, queue?})
      _ -> send(parent, {key, :outcome, :other, false, false})
    catch
      _, _ -> send(parent, {key, :outcome, :other, false, false})
    after
      Process.demonitor(parent_monitor, [:flush])
    end
  end

  defp start_failure_trace_snapshot(owner) do
