  defp start_failure_trace_install(key, session, owner, actor, destination, workspace) do
    labels = [:ex_cmd_start, :gen_server_start, :ex_cmd_await, :sql_zero,
      :workspace_identity, :cleanup_event, :workspace_rmdir, :workspace_lstat]
    for {mfa, label} <- Enum.zip(@start_failure_mfas, labels) do
      start_failure_setup(key, {label, :initial_traced}, :entered)
      transport_require!(:trace.info(session, mfa, :traced) == {:traced, false})
      start_failure_setup(key, {label, :initial_traced}, :passed)
    end
    start_failure_setup(key, :initial_owner_flags, :entered)
    transport_require!(:trace.info(session, owner, :flags) == {:flags, []})
    start_failure_setup(key, :initial_owner_flags, :passed)
    start_failure_setup(key, :initial_owner_tracer, :entered)
    transport_require!(:trace.info(session, owner, :tracer) == {:tracer, []})
    start_failure_setup(key, :initial_owner_tracer, :passed)
    start = [{[:_, :_], [], [{:return_trace}]}]
    gen = [{[:_, :_, :_], [], []}]
    await = [{[:_, :_], [], []}]
    sql = [{[Singularity.Storage.MigrationRepo, @transport_sql,
      [destination.database, @transport_tag], [{:timeout, :"$1"}]],
      [{:is_integer, :"$1"}, {:>, :"$1", 0}, {:"=<", :"$1", 1_000}], [{:return_trace}]}]
    directory = [{[workspace], [], [{:return_trace}]}]
    events = Enum.map([:closed, :unconfirmed], fn status ->
      {[actor, {:legacy_upgrade_transport, :"$1", owner, {:cleanup, status}}],
        [{:is_reference, :"$1"}], [{:message, {{:start_failure_cleanup, status}}}]}
    end) ++ [{[actor, {:legacy_upgrade_transport, :_, owner, :_}], [],
      [{:message, {{:start_failure_forbidden, true}}}]}]
    patterns = Enum.zip(@start_failure_mfas, [start, gen, await, sql, directory, events, directory, directory])
    for {{mfa, pattern}, label} <- Enum.zip(patterns, labels) do
      start_failure_setup(key, {label, :install}, :entered)
      transport_require!(:trace.function(session, mfa, pattern, [:local]) == 1)
      start_failure_setup(key, {label, :install}, :passed)
      start_failure_setup(key, {label, :traced}, :entered)
      transport_require!(:trace.info(session, mfa, :traced) == {:traced, :local})
      start_failure_setup(key, {label, :traced}, :passed)
      start_failure_setup(key, {label, :match_spec}, :entered)
      transport_require!(:trace.info(session, mfa, :match_spec) == {:match_spec, pattern})
      start_failure_setup(key, {label, :match_spec}, :passed)
      start_failure_setup(key, {label, :meta}, :entered)
      # OTP also reports an absent meta tracer as [] on a locally traced MFA.
      # [] alone can mean an invalid meta tracer; the independent false
      # meta_match_spec guard below must also pass before the owner is armed.
      transport_require!(:trace.info(session, mfa, :meta) in [{:meta, false}, {:meta, []}])
      start_failure_setup(key, {label, :meta}, :passed)
      start_failure_setup(key, {label, :meta_match_spec}, :entered)
      transport_require!(:trace.info(session, mfa, :meta_match_spec) == {:meta_match_spec, false})
      start_failure_setup(key, {label, :meta_match_spec}, :passed)
    end
    start_failure_setup(key, :owner_process_enable, :entered)
    transport_require!(:trace.process(session, owner, true, [:call, :arity, :monotonic_timestamp]) == 1)
    start_failure_setup(key, :owner_process_enable, :passed)
    start_failure_setup(key, :owner_flags_readback, :entered)
    {:flags, flags} = :trace.info(session, owner, :flags)
    start_failure_setup(key, :owner_flags_readback, :passed)
    start_failure_setup(key, :owner_flags_guard, :entered)
    transport_require!(Enum.sort(flags) == Enum.sort([:call, :arity, :monotonic_timestamp]))
    start_failure_setup(key, :owner_flags_guard, :passed)
    start_failure_setup(key, :owner_tracer_guard, :entered)
    transport_require!(:trace.info(session, owner, :tracer) == {:tracer, self()})
    start_failure_setup(key, :owner_tracer_guard, :passed)
    :ok
  end

  defp start_failure_observation do
    key = make_ref()
    deadline = System.monotonic_time(:millisecond) + 50_000
    baseline = transport_cleanup_baseline(deadline)
    transport_require!(Enum.all?(baseline.repos, fn {_, value} -> value != :invalid end))
    maintenance_options = Singularity.Storage.MigrationRepo.config()
      |> Keyword.drop([:url, :name]) |> Keyword.put(:database, "postgres")
      |> Keyword.put(:pool_size, 1) |> Keyword.put(:pool_count, 1)
      |> Keyword.put(:parameters, application_name: @transport_observer_tag)
    parent = self()
    events = Enum.uniq(Enum.map(@transport_repos, &(&1.config()[:telemetry_prefix] ++ [:query])) ++
      [[:singularity, :authorization, :rls_denial], [:oban, :job, :start], [:oban, :job, :stop],
       [:oban, :job, :exception], [:singularity, :job, :retry], [:singularity, :outbox, :dispatch],
       [:singularity, :integrity, :failure]])
    handler = {__MODULE__, :start_failure_privacy, key}
    telemetry_before = start_failure_telemetry(events)
    Process.put({key, :start_failure_cleanup_failures}, [])
    :ok = :telemetry.attach_many(handler, events, fn _, measurements, metadata, _ ->
      send(parent, {key, :privacy, not transport_contains?(measurements) and not transport_contains?(metadata)})
    end, nil)
    try do
      logs = ExUnit.CaptureLog.capture_log(fn ->
        stderr = ExUnit.CaptureIO.capture_io(:stderr, fn ->
          stdout = ExUnit.CaptureIO.capture_io(fn ->
            proof = try do
              start_failure_run(key, deadline, baseline, maintenance_options)
            rescue
              _ -> start_failure_failed_proof(key, :error)
            catch
              kind, _ -> start_failure_failed_proof(key, kind)
            end
            Process.put({key, :start_failure_proof}, proof)
          end)
          Process.put({key, :stdout}, not transport_contains?(stdout))
        end)
        Process.put({key, :stderr}, not transport_contains?(stderr))
      end)
      proof = Process.get({key, :start_failure_proof})
      private? = Process.get({key, :stdout}) == true and Process.get({key, :stderr}) == true and
        not transport_contains?(logs) and transport_privacy_tail(key)
      registered? = Enum.all?(events, fn event ->
        Enum.any?(:telemetry.list_handlers(event), &(&1.id == handler))
      end)
      detached? = :telemetry.detach(handler) == :ok
      Process.put({key, :start_failure_handler_detached}, true)
      telemetry_restored? = start_failure_telemetry(events) == telemetry_before
      private? = private? and registered? and transport_privacy_tail(key)
      cleanup_failures = Process.get({key, :start_failure_cleanup_failures}, [:missing])
      original_closed? = Process.get({key, :start_failure_session_closed}) == true and
        Process.get({key, :start_failure_observer_closed}) == true and cleanup_failures == []
      baseline_restored? = transport_cleanup_baseline(deadline) == baseline
      restored? = detached? and telemetry_restored? and original_closed? and baseline_restored?
      admitted? = proof.evidence? and private? and restored?
      # This boundary is deliberately outside all original transport captures.
      # Nothing below changes the immutable helper outcome or GREEN witness.
      hygiene? = cond do
        admitted? and proof.retained? ->
          start_failure_hygiene(key, proof.original, maintenance_options)
        admitted? and proof.dropped? -> true
        true -> false
      end
      witness = %{proof.witness | private?: proof.witness.private? and private?,
        restored?: proof.witness.restored? and restored?}
      %{proof | witness: witness, evidence?: admitted?, hygiene?: hygiene?,
        cleanup_failures: Process.get({key, :start_failure_cleanup_failures}, []),
        original_cleanup_failures: cleanup_failures,
        hygiene_failures: Process.get({key, :start_failure_cleanup_failures}, []) -- cleanup_failures,
        terminal_facts: Map.new(Process.get({key, :start_failure_join_roles}, []),
          &{&1, Process.get({key, :start_failure_terminal, &1})}),
        summary: proof.summary |> Map.put(:private, private?) |> Map.put(:telemetry_restored, telemetry_restored?)
          |> Map.put(:original_observer_closed, original_closed?) |> Map.put(:diagnostic_hygiene, hygiene?)
          |> Map.put(:setup, Process.get({key, :start_failure_setup}, {:unobserved, :unobserved}))
          |> Map.put(:armed, Process.get({key, :start_failure_setup_armed}) == true)
          |> Map.put(:original_terminals, start_failure_terminal_summary(key))
          |> Map.put(:original_finalizers, cleanup_failures == [])}
    after
      unless Process.delete({key, :start_failure_handler_detached}) == true,
        do: :telemetry.detach(handler)
      for role <- Process.delete({key, :start_failure_join_roles}) || [],
        do: Process.delete({key, :start_failure_terminal, role})
      for name <- [:start_failure_proof, :stdout, :stderr, :start_failure_last_state,
        :start_failure_cleanup_failures, :start_failure_session_closed, :start_failure_observer_closed,
        :start_failure_unregistered, :start_failure_recovery_closed, :start_failure_recovery_result,
        :start_failure_recovery_stdout, :start_failure_recovery_stderr,
        :start_failure_setup, :start_failure_setup_armed], do: Process.delete({key, name})
    end
  end

  defp start_failure_setup(key, phase, status) do
    Process.put({key, :start_failure_setup}, {phase, status})
    :ok
  end

  defp start_failure_terminal_summary(key) do
    resources = for {:resource, _} = role <- Process.get({key, :start_failure_join_roles}, []),
      do: start_failure_terminal_class(Process.get({key, :start_failure_terminal, role}))
    %{owner: start_failure_terminal_class(Process.get({key, :start_failure_terminal, :owner})),
      actor: start_failure_terminal_class(Process.get({key, :start_failure_terminal, :actor})),
      observer: start_failure_terminal_class(Process.get({key, :start_failure_terminal, :observer})),
      six_original_resources: length(resources) == 6, resources: Enum.sort(resources)}
  end

  defp start_failure_terminal_class({:terminal, :normal}), do: :normal
  defp start_failure_terminal_class({:terminal, :shutdown}), do: :shutdown
  defp start_failure_terminal_class({:terminal,
    {:fixture_cleanup_failed, [{:legacy_preparation_quarantined, :unconfirmed}]}}),
    do: :known_quarantine
  defp start_failure_terminal_class({:terminal, _}), do: :other
  defp start_failure_terminal_class(_), do: :unobserved

  defp start_failure_telemetry(events),
    do: Map.new(events, &{&1, Enum.sort(:telemetry.list_handlers(&1))})

  defp start_failure_failed_proof(key, failure) do
    original = Process.get({key, :start_failure_last_state})
    %{witness: %{private?: false, restored?: false}, evidence?: false, hygiene?: false,
      closed?: false, dropped?: false, secondary_free?: false, retained?: false,
      original: original, cleanup_failures: Process.get({key, :start_failure_cleanup_failures}, []),
      original_cleanup_failures: [], hygiene_failures: [],
      terminal_facts: %{},
      summary: %{observer_failure: failure, original_primary: if(is_map(original), do: original.outcome, else: :unobserved),
        original_cleanup: :unobserved, ordinary_drop: :unobserved, diagnostic_hygiene: false}}
  end

  defp start_failure_run(key, deadline, baseline, maintenance_options) do
    Enum.each([ExCmd.Process, ExCmd.Process.Exec, GenServer], fn module ->
      transport_require!(Code.ensure_loaded?(module))
    end)
    runner = Path.join(@start_failure_root, "apps/singularity_runtime/test/fixtures/legacy_v0_1_0/runner.exs")
    start_failure_regular!(runner)
    %File.Stat{uid: 1000} = File.lstat!(runner)
    transport_require!(start_failure_sha(File.read!(runner)) == "ece557b0798104f74f2876b00c5baf3e6e65e4908173d421a9837cbd5350929b")
    origin_before = start_failure_origins()
    transport_require!(start_failure_origins_valid?(origin_before))
    parent = self()
    {actor, actor_ref} = spawn_monitor(fn -> start_failure_actor(parent, key, deadline) end)
    Process.put({key, :start_failure_actor}, {actor, actor_ref})
    try do
      {owner, owner_ref, destination, roots, resources} =
        start_failure_initial(key, actor, actor_ref, deadline, nil)
        transport_require!(resources.owner == owner and resources.caller == actor)
        transport_require!(map_size(resources.repos) == 5 and Enum.sort(Map.keys(resources.repos)) == Enum.sort(@transport_repos))
        originals = [resources.maintenance | Map.values(resources.repos)]
        transport_require!(length(Enum.uniq(originals)) == 6 and Enum.all?(originals, &(is_pid(&1) and Process.alive?(&1))))
        resource_refs = Map.new(originals, &{Process.monitor(&1), &1})
        Process.put({key, :start_failure_resources}, resource_refs)
        transport_require!(start_failure_roots_same?(roots))
        {:ok, connection} = Postgrex.start_link(maintenance_options)
        Process.unlink(connection)
        connection_ref = Process.monitor(connection)
        Process.put({key, :start_failure_observer}, {connection, connection_ref})
        try do
        start_failure_setup(key, :legacy_trace_snapshot, :entered)
        before = start_failure_trace_snapshot(owner)
        transport_require!(before.owner == [{:flags, []}, {:tracer, []}])
        start_failure_setup(key, :legacy_trace_snapshot, :passed)
        start_failure_setup(key, :session_create, :entered)
        session = :trace.session_create(:task18_start_failure, self(), [])
        start_failure_setup(key, :session_create, :passed)
        try do
          start_failure_setup(key, :oid_query, :entered)
          [[oid]] = transport_rows(connection, "SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [destination.database])
          start_failure_setup(key, :oid_query, :passed)
          start_failure_setup(key, :oid_positive, :entered)
          transport_require!(is_integer(oid) and oid > 0)
          start_failure_setup(key, :oid_positive, :passed)
          start_failure_trace_install(key, session, owner, actor, destination, roots.workspace)
          state = %{
            key: key, owner: owner, actor: actor, owner_ref: owner_ref, actor_ref: actor_ref,
            owner_down: nil, actor_down: nil, resource_refs: resource_refs, resource_down: %{},
            connection: connection, destination: destination, roots: roots, oid: oid,
            deadline: deadline, events: [], trace_events: 0, valid?: true,
            private?: Process.get({key, :start_failure_initial_private}, true),
            counts: %{}, order: %{arm: System.monotonic_time()}, result: :unobserved,
            sql: :unobserved, rmdir: :unobserved, lstat: :unobserved,
            workspace_identity: nil, directory_samples: 0, reports: [], cleanup_events: [], outcome: nil,
            unregistered?: Process.get({key, :start_failure_unregistered}) == true,
            ready?: false, drop: nil, owner_cleanup: nil, independent?: false
          }
          start_failure_setup(key, :arm_send, :entered)
          send(owner, {key, :armed, self()})
          Process.put({key, :start_failure_armed}, true)
          Process.put({key, :start_failure_setup_armed}, true)
          start_failure_setup(key, :arm_send, :passed)
          start_failure_setup(key, :loop_entry, :entered)
          state = start_failure_loop(state)
          start_failure_setup(key, :loop_entry, :passed)
          fence = :trace.delivered(session, owner)
          state = start_failure_fence(state, fence)
          transport_require!(:trace.session_destroy(session) == true)
          Process.put({key, :start_failure_session_destroyed}, true)
          state = start_failure_tail(state, 0)
          restored? = start_failure_trace_snapshot(owner).patterns == before.patterns
          origin_after = start_failure_origins()
          origins? = start_failure_origins_valid?(origin_after) and origin_before == origin_after
          baseline? = transport_cleanup_baseline(deadline) == baseline
          resources_down? = map_size(state.resource_down) == 6 and
            Enum.all?(state.resource_down, fn {_, reason} -> reason in [:normal, :shutdown] end)
          red_terminal? = state.unregistered? and state.owner_down ==
            {:fixture_cleanup_failed, [{:legacy_preparation_quarantined, :unconfirmed}]} and
            state.outcome == {true, :quarantined} and state.reports == [:running, :unconfirmed] and
            state.cleanup_events == [] and state.owner_cleanup == :owner_cleanup_failed and is_nil(state.drop)
          green_terminal? = state.owner_down == :normal and state.outcome == {true, :none}
          common? = state.valid? and state.private? and (red_terminal? or green_terminal?) and
            state.actor_down == :normal and resources_down? and restored? and origins? and baseline? and
            state.result == :known_error and state.counts[:start_call] == 1 and
            state.counts[:start_return] == 1 and Map.get(state.counts, :gen_call, 0) == 0 and
            Map.get(state.counts, :await_call, 0) == 0 and not state.ready? and
            state.outcome in [{true, :none}, {true, :quarantined}]
          ordinary? = state.outcome == {true, :none} and state.owner_cleanup == :owner_cleanup_completed
          closed? = state.reports == [:running, :closed] and state.cleanup_events == [:closed]
          ordinary_drop? = ordinary? and is_integer(state.drop) and
            transport_rows(connection, "SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [destination.database]) == [] and
            File.lstat(roots.allocation) == {:error, :enoent}
          retained? = state.outcome == {true, :quarantined} and state.owner_cleanup == :owner_cleanup_failed and
            state.reports == [:running, :unconfirmed] and state.cleanup_events == [] and is_nil(state.drop)
          witness = %{
            key: key, trace_key: key, owner: owner, actor: actor,
            start_owner: owner, return_owner: owner, sql_owner: owner,
            database: destination.database, oid: oid, origins_before: origin_before, origins_after: origin_after,
            installed?: true, start_guard?: true, gen_guard?: true, await_guard?: true,
            flags?: true, tracer?: true, extra_guards?: true,
            restored?: restored?, fence?: true, drained?: state.valid?,
            owner_normal?: state.owner_down == :normal, actor_normal?: state.actor_down == :normal,
            resources_down?: resources_down?, baseline?: baseline?, private?: state.private?,
            roots?: state.independent?, workspace_owned?: transport_workspace_identity?(state.workspace_identity),
            workspace_empty?: state.rmdir == :ok, no_ready?: not state.ready?, no_handle?: state.valid?,
            start_calls: Map.get(state.counts, :start_call, 0), start_returns: Map.get(state.counts, :start_return, 0),
            gen_calls: Map.get(state.counts, :gen_call, 0), await_calls: Map.get(state.counts, :await_call, 0),
            sql_calls: Map.get(state.counts, :sql_call, 0), sql_returns: Map.get(state.counts, :sql_return, 0),
            rmdir_calls: Map.get(state.counts, :rmdir_call, 0), rmdir_returns: Map.get(state.counts, :rmdir_return, 0),
            enoent_calls: Map.get(state.counts, :lstat_call, 0), enoent_returns: Map.get(state.counts, :lstat_return, 0),
            cleanup_events: length(state.cleanup_events), result: state.result, sql: state.sql,
            rmdir: state.rmdir, lstat: state.lstat, cleanup: if(closed?, do: :closed, else: :unconfirmed),
            secondary: if(state.outcome == {true, :none}, do: :none, else: :quarantined),
            ordinary_drop?: ordinary_drop?,
            order: Enum.map([:arm, :directory, :call, :return, :sql_call, :sql_zero,
              :rmdir_call, :rmdir_ok, :lstat_call, :enoent, :independent, :closed,
              :cleanup_event, :drop], &{&1, Map.get(state.order, &1)})
          }
          %{witness: witness, evidence?: common?, hygiene?: false, closed?: closed?,
            retained?: retained? and red_terminal?, original: state, cleanup_failures: [],
            original_cleanup_failures: [], hygiene_failures: [],
            terminal_facts: %{},
            dropped?: ordinary_drop?, secondary_free?: state.outcome == {true, :none},
            summary: %{known_error: state.result == :known_error, original_cleanup: witness.cleanup,
              ordinary_drop: ordinary_drop?, diagnostic_hygiene: false,
              owner_normal: state.owner_down == :normal, known_quarantine_terminal: red_terminal?,
              helper_sql_zero: state.sql == :zero, helper_rmdir: state.rmdir == :ok,
              helper_enoent: state.lstat == :enoent, guards: common?}}
        after
          # Never kill actors/owners or delete retained data on observer failure.
          # Only this observer's session and maintenance connection are released.
          start_failure_cleanup_attempt(key, :session_destroy, fn ->
            closed? = Process.delete({key, :start_failure_session_destroyed}) == true or
              :trace.session_destroy(session) == true
            Process.put({key, :start_failure_session_closed}, closed?)
            closed?
          end)
        end
        after
          start_failure_cleanup_attempt(key, :observer_stop, fn ->
            if Process.alive?(connection), do: GenServer.stop(connection, :normal,
              min(1_000, max(1, deadline - System.monotonic_time(:millisecond))))
            true
          end)
          start_failure_cleanup_attempt(key, :observer_join, fn ->
            closed? = start_failure_join(key, :observer, {connection, connection_ref}, deadline) == {:terminal, :normal}
            Process.put({key, :start_failure_observer_closed}, closed?)
            closed?
          end)
        end
    after
      case Process.get({key, :start_failure_owner}) do
        {owner, _} ->
          unless Process.get({key, :start_failure_armed}) == true,
            do: send(owner, {key, :abort, self()})
        nil -> :ok
      end
      # Each consumed reason is final; join every still-missing original
      # independently. Qualification below never rewrites a terminal reason.
      for {role, binding} <- [owner: :start_failure_owner, actor: :start_failure_actor] do
        case Process.get({key, binding}) do
          {_, _} = owned -> start_failure_cleanup_attempt(key, {:join, role}, fn ->
            match?({:terminal, _}, start_failure_join(key, role, owned, deadline))
          end)
          nil -> :ok
        end
      end
      for {ref, pid} <- Process.get({key, :start_failure_resources}, %{}) do
        start_failure_cleanup_attempt(key, {:join_resource, ref}, fn ->
          match?({:terminal, _}, start_failure_join(key, {:resource, ref}, {pid, ref}, deadline))
        end)
      end
      for name <- [:start_failure_owner, :start_failure_actor, :start_failure_armed,
        :start_failure_initial_private, :start_failure_resources, :start_failure_observer],
        do: Process.delete({key, name})
    end
  end

  defp start_failure_initial(key, actor, actor_ref, deadline, registered) do
    receive do
      {^key, :owner_registered, owner, ^actor, unregistered?}
          when is_pid(owner) and is_nil(registered) and is_boolean(unregistered?) ->
        ref = Process.monitor(owner)
        Process.put({key, :start_failure_owner}, {owner, ref})
        Process.put({key, :start_failure_unregistered}, unregistered?)
        start_failure_initial(key, actor, actor_ref, deadline, {owner, ref})
      {^key, :prepare, owner, ^actor, destination, roots, resources} when not is_nil(registered) ->
        {^owner, ref} = registered
        {owner, ref, destination, roots, resources}
      {^key, :privacy, private?} when is_boolean(private?) ->
        Process.put({key, :start_failure_initial_private},
          Process.get({key, :start_failure_initial_private}, true) and private?)
        start_failure_initial(key, actor, actor_ref, deadline, registered)
      {:DOWN, ^actor_ref, :process, ^actor, reason} ->
        Process.put({key, :start_failure_terminal, :actor}, {:terminal, reason})
        throw(:legacy_transport_observer)
    after
      min(5_000, max(0, deadline - System.monotonic_time(:millisecond))) ->
        throw(:legacy_transport_observer)
    end
  end

  defp start_failure_loop(state) do
    Process.put({state.key, :start_failure_last_state}, state)
    terminal? = not is_nil(state.outcome) and not is_nil(state.owner_down) and
      not is_nil(state.actor_down) and map_size(state.resource_down) == map_size(state.resource_refs)
    if terminal? do
      state
    else
      receive do
        message -> start_failure_loop(start_failure_message(message, state))
      after
        max(0, state.deadline - System.monotonic_time(:millisecond)) -> throw(:legacy_transport_observer)
      end
    end
  end

  defp start_failure_message({:trace_ts, owner, :call, {ExCmd.Process, :start_link, 2}, at}, %{owner: owner} = s),
    do: start_failure_fact(s, :start_call, :call, at)
  defp start_failure_message({:trace_ts, owner, :return_from, {ExCmd.Process, :start_link, 2}, result, at}, %{owner: owner} = s) do
    s = start_failure_fact(s, :start_return, :return, at)
    %{s | result: if(result == @start_failure_error, do: :known_error, else: :other)}
  end
  defp start_failure_message({:trace_ts, owner, :call, {GenServer, :start_link, 3}, at}, %{owner: owner} = s),
    do: start_failure_fact(s, :gen_call, nil, at)
  defp start_failure_message({:trace_ts, owner, :call, {ExCmd.Process, :await_exit, 2}, at}, %{owner: owner} = s),
    do: start_failure_fact(s, :await_call, nil, at)
  defp start_failure_message({:trace_ts, owner, :call, {Singularity.Storage.SafeSQL, :query!, 4}, at}, %{owner: owner} = s),
    do: start_failure_fact(s, :sql_call, :sql_call, at)
  defp start_failure_message({:trace_ts, owner, :return_from, {Singularity.Storage.SafeSQL, :query!, 4}, result, at}, %{owner: owner} = s) do
    s = start_failure_fact(s, :sql_return, :sql_zero, at)
    zero? = case result do
      %Postgrex.Result{command: :select, columns: ["pid"], rows: [], num_rows: 0} -> true
      _ -> false
    end
    %{s | sql: if(zero?, do: :zero, else: :other)}
  end
  defp start_failure_message({:trace_ts, owner, :call, {LegacyUpgradeRuntimeFixture, :transport_directory_identity!, 1}, _at}, %{owner: owner} = s), do: s
  defp start_failure_message({:trace_ts, owner, :return_from, {LegacyUpgradeRuntimeFixture, :transport_directory_identity!, 1}, identity, at}, %{owner: owner} = s) do
    valid? = transport_workspace_identity?(identity) and s.directory_samples < 2 and
      (is_nil(s.workspace_identity) or s.workspace_identity == identity)
    %{s | workspace_identity: if(valid?, do: identity, else: nil),
      directory_samples: s.directory_samples + 1, valid?: s.valid? and valid?,
      order: if(s.directory_samples == 0, do: Map.put(s.order, :directory, at), else: s.order)}
  end
  defp start_failure_message({:trace_ts, owner, :call, {File, :rmdir, 1}, at}, %{owner: owner} = s),
    do: start_failure_fact(s, :rmdir_call, :rmdir_call, at)
  defp start_failure_message({:trace_ts, owner, :return_from, {File, :rmdir, 1}, result, at}, %{owner: owner} = s) do
    s = start_failure_fact(s, :rmdir_return, :rmdir_ok, at)
    %{s | rmdir: if(result == :ok, do: :ok, else: :other)}
  end
  defp start_failure_message({:trace_ts, owner, :call, {File, :lstat, 1}, at}, %{owner: owner} = s),
    do: start_failure_fact(s, :lstat_call, :lstat_call, at)
  defp start_failure_message({:trace_ts, owner, :return_from, {File, :lstat, 1}, result, at}, %{owner: owner} = s) do
    s = start_failure_fact(s, :lstat_return, :enoent, at)
    %{s | lstat: if(result == {:error, :enoent}, do: :enoent, else: :other)}
  end
  defp start_failure_message({:trace_ts, owner, :call, {LegacyUpgradeRuntimeFixture, :transport_event, 2}, {:start_failure_cleanup, status}, at}, %{owner: owner} = s)
       when status in [:closed, :unconfirmed] do
    %{s | cleanup_events: s.cleanup_events ++ [status], order: Map.put(s.order, :cleanup_event, at)}
  end
  defp start_failure_message({key, :preclosed, owner}, %{key: key, owner: owner} = s) do
    zero? = transport_rows(s.connection, @transport_sql, [s.destination.database, @transport_tag]) == []
    absent? = File.lstat(s.roots.workspace) == {:error, :enoent}
    roots? = start_failure_roots_same?(s.roots)
    valid? = zero? and absent? and roots? and is_nil(s.order[:independent])
    if valid?, do: send(owner, {key, :release_closed, self(), owner})
    %{s | independent?: valid?, valid?: s.valid? and valid?,
      order: Map.put(s.order, :independent, System.monotonic_time())}
  end
  defp start_failure_message({key, :report, owner, status, at}, %{key: key, owner: owner} = s)
       when status in [:running, :closed, :unconfirmed] and is_integer(at) do
    order = if status == :closed, do: Map.put(s.order, :closed, at), else: s.order
    %{s | reports: s.reports ++ [status], order: order}
  end
  defp start_failure_message({key, :checkpoint, owner, stage, at}, %{key: key, owner: owner} = s)
       when is_integer(at) do
    case stage do
      :ready -> %{s | ready?: true, valid?: false}
      :before_database_drop -> %{s | drop: at, order: Map.put(s.order, :drop, at)}
      stage when stage in [:owner_cleanup_completed, :owner_cleanup_failed] -> %{s | owner_cleanup: stage}
      _ -> %{s | valid?: false}
    end
  end
  defp start_failure_message({key, :outcome, outcome, private?, queue?}, %{key: key} = s)
       when is_boolean(private?) and is_boolean(queue?) do
    %{s | outcome: outcome, private?: s.private? and private? and queue?, valid?: s.valid? and is_nil(s.outcome)}
  end
  defp start_failure_message({key, :privacy, private?}, %{key: key} = s) when is_boolean(private?),
    do: %{s | private?: s.private? and private?}
  defp start_failure_message({:DOWN, ref, :process, owner, reason}, %{owner: owner, owner_ref: ref} = s) do
    first? = is_nil(Process.get({s.key, :start_failure_terminal, :owner}))
    if first?, do: Process.put({s.key, :start_failure_terminal, :owner}, {:terminal, reason})
    %{s | owner_down: if(first?, do: reason, else: s.owner_down), valid?: s.valid? and first?}
  end
  defp start_failure_message({:DOWN, ref, :process, actor, reason}, %{actor: actor, actor_ref: ref} = s) do
    first? = is_nil(Process.get({s.key, :start_failure_terminal, :actor}))
    if first?, do: Process.put({s.key, :start_failure_terminal, :actor}, {:terminal, reason})
    %{s | actor_down: if(first?, do: reason, else: s.actor_down), valid?: s.valid? and first?}
  end
  defp start_failure_message({:DOWN, ref, :process, pid, reason}, s) do
    valid? = s.resource_refs[ref] == pid and not Map.has_key?(s.resource_down, ref)
    if valid?, do: Process.put({s.key, :start_failure_terminal, {:resource, ref}}, {:terminal, reason})
    %{s | resource_down: if(valid?, do: Map.put(s.resource_down, ref, reason), else: s.resource_down),
      valid?: s.valid? and valid?}
  end
  defp start_failure_message(_, s), do: %{s | valid?: false}

  defp start_failure_fact(s, count, stage, at) do
    n = Map.get(s.counts, count, 0) + 1
    %{s | counts: Map.put(s.counts, count, n), trace_events: s.trace_events + 1,
      valid?: s.valid? and n == 1 and is_integer(at) and s.trace_events < 64,
      order: if(is_nil(stage), do: s.order, else: Map.put(s.order, stage, at))}
  end

  defp start_failure_fence(s, ref) do
    Process.put({s.key, :start_failure_last_state}, s)
    owner = s.owner
    receive do
      {:trace_delivered, ^owner, ^ref} -> s
      message -> start_failure_fence(start_failure_message(message, s), ref)
    after
      max(0, s.deadline - System.monotonic_time(:millisecond)) -> throw(:legacy_transport_observer)
    end
  end

  defp start_failure_tail(s, 32), do: %{s | valid?: false}
  defp start_failure_tail(s, count) do
    receive do
      {:trace_ts, _, _, _, _} = message -> start_failure_tail(start_failure_message(message, s), count + 1)
      {:trace_ts, _, _, _, _, _} = message -> start_failure_tail(start_failure_message(message, s), count + 1)
    after
      0 -> s
    end
  end

  defp start_failure_cleanup_attempt(key, stage, fun) do
    confirmed? = try do
      fun.() == true
    rescue
      _ -> false
    catch
      _, _ -> false
    end
    unless confirmed?, do: Process.put({key, :start_failure_cleanup_failures},
      Process.get({key, :start_failure_cleanup_failures}, []) ++ [{stage, :unconfirmed}])
    confirmed?
  end

  defp start_failure_join(key, role, {pid, ref}, deadline) do
    roles = Process.get({key, :start_failure_join_roles}, [])
    unless role in roles, do: Process.put({key, :start_failure_join_roles}, [role | roles])
    case Process.get({key, :start_failure_terminal, role}) do
      {:terminal, _} = observed -> observed
      nil ->
        receive do
          {:DOWN, ^ref, :process, ^pid, reason} ->
            observed = {:terminal, reason}
            Process.put({key, :start_failure_terminal, role}, observed)
            observed
        after
          max(0, deadline - System.monotonic_time(:millisecond)) -> :missing
        end
    end
  end

  defp start_failure_hygiene(key, original, options) do
    # Original capture/privacy/telemetry and original connection/session custody
    # have already qualified. This is a separate hygiene-only connection.
    logs = ExUnit.CaptureLog.capture_log(fn ->
      stderr = ExUnit.CaptureIO.capture_io(:stderr, fn ->
        stdout = ExUnit.CaptureIO.capture_io(fn ->
          recovered? = start_failure_hygiene_connection(key, original, options)
          Process.put({key, :start_failure_recovery_result}, recovered?)
        end)
        Process.put({key, :start_failure_recovery_stdout}, not transport_contains?(stdout))
      end)
      Process.put({key, :start_failure_recovery_stderr}, not transport_contains?(stderr))
    end)
    Process.delete({key, :start_failure_recovery_result}) == true and
      Process.delete({key, :start_failure_recovery_stdout}) == true and
      Process.delete({key, :start_failure_recovery_stderr}) == true and not transport_contains?(logs)
  end

  defp start_failure_hygiene_connection(key, original, options) do
    failures_before = Process.get({key, :start_failure_cleanup_failures}, [])
    case Postgrex.start_link(options) do
      {:ok, connection} ->
        Process.unlink(connection)
        ref = Process.monitor(connection)
        recovered? = try do
          start_failure_recover(original, connection)
        after
          start_failure_cleanup_attempt(key, :recovery_stop, fn ->
            if Process.alive?(connection), do: GenServer.stop(connection, :normal,
              min(1_000, max(1, original.deadline - System.monotonic_time(:millisecond))))
            true
          end)
          start_failure_cleanup_attempt(key, :recovery_join, fn ->
            closed? = start_failure_join(key, :recovery, {connection, ref}, original.deadline) == {:terminal, :normal}
            Process.put({key, :start_failure_recovery_closed}, closed?)
            closed?
          end)
        end
        recovered? and Process.get({key, :start_failure_recovery_closed}) == true and
          Process.get({key, :start_failure_cleanup_failures}, []) == failures_before
      _ -> false
    end
  rescue
    _ -> false
  catch
    _, _ -> false
  end

  defp start_failure_recover(s, connection) do
    # Hygiene only: all helper outcome/order facts above remain unchanged.
    try do
      transport_require!(start_failure_roots_same?(s.roots))
      transport_require!(start_failure_directory(s.roots.workspace) == s.workspace_identity)
      transport_require!(File.ls!(s.roots.workspace) == [] and File.ls!(s.roots.objects) == [])
      transport_require!(Enum.sort(File.ls!(s.roots.allocation)) == ["historical-build", "objects"])
      transport_require!(transport_rows(connection, "SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [s.destination.database]) == [[s.oid]])
      transport_require!(transport_rows(connection, "SELECT pid FROM pg_catalog.pg_stat_activity WHERE datname=$1 ORDER BY pid", [s.destination.database]) == [])
      # Repeat identity, inventory and session checks immediately before DROP.
      transport_require!(start_failure_roots_same?(s.roots))
      transport_require!(start_failure_directory(s.roots.workspace) == s.workspace_identity)
      transport_require!(File.ls!(s.roots.workspace) == [] and File.ls!(s.roots.objects) == [])
      transport_require!(Enum.sort(File.ls!(s.roots.allocation)) == ["historical-build", "objects"])
      transport_require!(transport_rows(connection, "SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [s.destination.database]) == [[s.oid]])
      transport_require!(transport_rows(connection, "SELECT pid FROM pg_catalog.pg_stat_activity WHERE datname=$1 ORDER BY pid", [s.destination.database]) == [])
      {:ok, %Postgrex.Result{command: :drop_database}} = Postgrex.query(connection,
        "DROP DATABASE \"#{s.destination.database}\"", [], timeout: min(1_000, max(1, s.deadline - System.monotonic_time(:millisecond))))
      transport_require!(transport_rows(connection, "SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [s.destination.database]) == [])
      transport_require!(start_failure_roots_same?(s.roots))
      transport_require!(start_failure_directory(s.roots.workspace) == s.workspace_identity and File.ls!(s.roots.workspace) == [])
      :ok = File.rmdir(s.roots.workspace)
      transport_require!(File.lstat(s.roots.workspace) == {:error, :enoent})
      transport_require!(start_failure_roots_same?(s.roots))
      transport_require!(start_failure_directory(s.roots.objects) == s.roots.directories[s.roots.objects] and File.ls!(s.roots.objects) == [])
      :ok = File.rmdir(s.roots.objects)
      transport_require!(File.lstat(s.roots.objects) == {:error, :enoent})
      transport_require!(Enum.all?(Map.delete(s.roots.ancestors, s.roots.objects), fn {path, identity} ->
        case File.lstat(path) do
          {:ok, %File.Stat{type: :directory, major_device: major, minor_device: minor, inode: inode}} ->
            identity == {major, minor, inode}
          _ -> false
        end
      end))
      transport_require!(start_failure_directory(s.roots.allocation) == s.roots.directories[s.roots.allocation] and File.ls!(s.roots.allocation) == [])
      :ok = File.rmdir(s.roots.allocation)
      File.lstat(s.roots.allocation) == {:error, :enoent}
    rescue
      _ -> false
    catch
      _, _ -> false
    end
  end
