  test "unconfirmed-await stat grammar preserves exact field22 before each malformed literal" do
    fields = ua_stat_fields()
    expected = {:ok, %{pid: "4242", state: "S", start_ticks: "987654321"}}

    assert Enum.zip(4..52, fields) == [
             {4, "1"}, {5, "1"}, {6, "1"}, {7, "0"}, {8, "-1"}, {9, "0"},
             {10, "0"}, {11, "0"}, {12, "0"}, {13, "0"}, {14, "0"}, {15, "0"},
             {16, "0"}, {17, "0"}, {18, "20"}, {19, "0"}, {20, "1"}, {21, "0"},
             {22, "987654321"}, {23, "4096"}, {24, "1"}, {25, "18446744073709551615"},
             {26, "0"}, {27, "0"}, {28, "0"}, {29, "0"}, {30, "0"}, {31, "0"},
             {32, "0"}, {33, "0"}, {34, "0"}, {35, "0"}, {36, "0"}, {37, "0"},
             {38, "0"}, {39, "0"}, {40, "0"}, {41, "0"}, {42, "0"}, {43, "0"},
             {44, "0"}, {45, "0"}, {46, "0"}, {47, "0"}, {48, "0"}, {49, "0"},
             {50, "0"}, {51, "0"}, {52, "0"}
           ]

    malformed = [
      {:no_lf, String.trim_trailing(ua_stat_literal("beam.smp", "S", fields), "\n")},
      {:two_final_lf, ua_stat_literal("beam.smp", "S", fields) <> "\n"},
      {:nul, ua_stat_literal(<<0>>, "S", fields)},
      {:wrong_pid, String.replace_prefix(ua_stat_literal("beam.smp", "S", fields), "4242", "4243")},
      {:zero_pid, String.replace_prefix(ua_stat_literal("beam.smp", "S", fields), "4242", "0")},
      {:leading_zero_pid, String.replace_prefix(ua_stat_literal("beam.smp", "S", fields), "4242", "04242")},
      {:plus_pid, String.replace_prefix(ua_stat_literal("beam.smp", "S", fields), "4242", "+4242")},
      {:overflow_pid, String.replace_prefix(ua_stat_literal("beam.smp", "S", fields), "4242", "4294967296")},
      {:prefix_space, " " <> ua_stat_literal("beam.smp", "S", fields)},
      {:missing_open, String.replace_prefix(ua_stat_literal("beam.smp", "S", fields), "4242 (", "4242 ")},
      {:missing_delimiter, String.replace(ua_stat_literal("beam.smp", "S", fields), ") S ", ")S ")},
      {:comm65, ua_stat_literal(String.duplicate("x", 65), "S", fields)},
      {:state_unknown, ua_stat_literal("beam.smp", "Q", fields)},
      {:state_two_bytes, ua_stat_literal("beam.smp", "SS", fields)},
      {:fields48, ua_stat_literal("beam.smp", "S", Enum.drop(fields, -1))},
      {:fields50, ua_stat_literal("beam.smp", "S", fields ++ ["0"])},
      {:move22_to21, ua_stat_literal("beam.smp", "S", fields |> List.replace_at(17, "987654321") |> List.replace_at(18, "0"))},
      {:field21_nonzero, ua_stat_literal("beam.smp", "S", List.replace_at(fields, 17, "1"))},
      {:double_suffix_space, String.replace(ua_stat_literal("beam.smp", "S", fields), ") S ", ") S  ")},
      {:suffix_tab, String.replace(ua_stat_literal("beam.smp", "S", fields), ") S ", ") S\t")},
      {:suffix_cr, ua_stat_literal("beam.smp", "S", fields) <> "\r"},
      {:suffix_trailing_space, String.trim_trailing(ua_stat_literal("beam.smp", "S", fields), "\n") <> " \n"},
      {:empty, ""},
      {:nonbinary, []},
      {:overflow4097, :binary.copy("x", 4097)}
    ]

    # These delimiter/zero/state changes are valid grammar, not malformed input.
    grammar_controls = [
      {:parenthesis_newline, ua_stat_literal("a ) b\nc", "S", fields), expected},
      {:delimiter_in_comm, ua_stat_literal(") ", "S", fields), expected},
      {:empty_comm, ua_stat_literal("", "S", fields), expected},
      {:non_utf8_comm, ua_stat_literal(<<255, 41, 32, 10>>, "S", fields), expected},
      {:comm64, ua_stat_literal(String.duplicate("x", 64), "S", fields), expected},
      {:zero_ticks, ua_stat_literal("beam.smp", "S", List.replace_at(fields, 18, "0")),
       {:ok, %{pid: "4242", state: "S", start_ticks: "0"}}},
      {:move22_to23, ua_stat_literal("beam.smp", "S", fields |> List.replace_at(18, "0") |> List.replace_at(19, "987654321")),
       {:ok, %{pid: "4242", state: "S", start_ticks: "0"}}}
    ]

    states =
      for state <- ["R", "S", "D", "T", "t", "X", "Z", "P", "I"] do
        {:recognized_state, ua_stat_literal("beam.smp", state, ua_stat_fields()),
         {:ok, %{pid: "4242", state: state, start_ticks: "987654321"}}}
      end

    signed = [4, 5, 6, 7, 8, 16, 17, 18, 19, 20, 38, 39, 44, 52]

    signed_controls =
      for field <- signed, value <- ["-9223372036854775808", "9223372036854775807"] do
        {:signed_boundary, ua_stat_literal("beam.smp", "S", List.replace_at(ua_stat_fields(), field - 4, value)), expected}
      end

    signed_rejections =
      for field <- signed,
          value <- ["-9223372036854775809", "9223372036854775808", "+1", "-0", "01", "-01", "1e2", "x"] do
        {:signed_format_range, ua_stat_literal("beam.smp", "S", List.replace_at(ua_stat_fields(), field - 4, value)),
         {:error, :invalid_stat}}
      end

    unsigned = Enum.reject(4..52, &(&1 in signed or &1 == 21))

    unsigned_controls =
      for field <- unsigned do
        {:unsigned_boundary, ua_stat_literal("beam.smp", "S", List.replace_at(ua_stat_fields(), field - 4, "18446744073709551615")),
         {:ok, %{pid: "4242", state: "S", start_ticks: if(field == 22, do: "18446744073709551615", else: "987654321")}}}
      end

    unsigned_rejections =
      for field <- unsigned,
          value <- ["-1", "18446744073709551616", "+1", "-0", "01", "1e2", "x"] do
        {:unsigned_format_range, ua_stat_literal("beam.smp", "S", List.replace_at(ua_stat_fields(), field - 4, value)),
         {:error, :invalid_stat}}
      end

    cases =
      Enum.map(malformed, fn {label, bytes} -> {label, bytes, {:error, :invalid_stat}} end) ++
        grammar_controls ++ states ++ signed_controls ++ signed_rejections ++
        unsigned_controls ++ unsigned_rejections

    for {_label, mutated, result} <- cases,
        {bytes, wanted} <- [
          {ua_stat_literal("beam.smp", "S", ua_stat_fields()), expected},
          {mutated, result}
        ] do
      assert ua_parse_stat(bytes, "4242") == wanted
    end

    for expected_pid <- ["0", "04242", "+4242", "4294967296", nil],
        {bytes, pid, result} <- [
          {ua_stat_literal("beam.smp", "S", ua_stat_fields()), "4242", expected},
          {ua_stat_literal("beam.smp", "S", ua_stat_fields()), expected_pid, {:error, :invalid_stat}}
        ] do
      assert ua_parse_stat(bytes, pid) == result
    end
  end

