      end

    grammar_controls =
      for {state, descriptor} <- [
            {"R", "running"}, {"S", "sleeping"}, {"D", "disk sleep"}, {"T", "stopped"},
            {"t", "tracing stop"}, {"X", "dead"}, {"Z", "zombie"}, {"P", "parked"}, {"I", "idle"}
          ] do
        {:recognized_state, String.replace(ua_status_literal(), "S (sleeping)", state <> " (" <> descriptor <> ")"),
         ua_status_expected("4242", state)}
      end

    cases =
      Enum.map(malformed ++ structural ++ namespace ++ uids, fn {label, bytes} ->
        {label, bytes, {:error, :invalid_status}}
      end) ++ grammar_controls ++ [
        {:unrelated_rows, ua_status_literal() <> "Threads:\t8\nVmPeak:\t12345 kB\n", expected}
      ]

    for {_label, mutated, result} <- cases,
        {bytes, wanted} <- [{ua_status_literal(), expected}, {mutated, result}] do
      assert ua_parse_status(bytes, "4242") == wanted
    end

    for pid <- ["0", "04242", "4294967296", nil],
        {bytes, supplied, result} <- [
          {ua_status_literal(), "4242", expected},
          {ua_status_literal(), pid, {:error, :invalid_status}}
        ] do
      assert ua_parse_status(bytes, supplied) == result
    end
  end

  test "unconfirmed-await cgroup grammar compares independent bytes and reviewed topology" do
    expected = {:ok, [%{hierarchy: "0", controllers: [], path: "/owned:test scope"}]}

    malformed = [
      {:different_raw, "0::/other\n", "0::/owned:test scope\n", :v2},
      {:no_expected, "0::/owned:test scope\n", nil, :v2},
      {:unreviewed, "0::/owned:test scope\n", "0::/owned:test scope\n", :unreviewed},
      {:no_lf, "0::/owned:test scope", "0::/owned:test scope", :v2},
      {:empty, "", "", :v2},
      {:nonbinary, [], [], :v2},
      {:nul, "0::/owned\0scope\n", "0::/owned\0scope\n", :v2},
      {:cr, "0::/owned\r\n", "0::/owned\r\n", :v2},
      {:relative, "0::relative\n", "0::relative\n", :v2},
      {:missing_separator, "0:/owned\n", "0:/owned\n", :v2},
