      {:empty_path, "0::\n", "0::\n", :v2},
      {:deleted, "0::/owned (deleted)\n", "0::/owned (deleted)\n", :v2},
      {:leading_zero, "00::/owned\n", "00::/owned\n", :v2},
      {:negative_id, "-1::/owned\n", "-1::/owned\n", :v1},
      {:plus_id, "+1:cpu:/owned\n", "+1:cpu:/owned\n", :v1},
      {:v2_controllers, "0:cpu:/owned\n", "0:cpu:/owned\n", :v2},
      {:v2_two_rows, "0::/owned\n0::/other\n", "0::/owned\n0::/other\n", :v2},
      {:v2_nonzero, "1::/owned\n", "1::/owned\n", :v2},
      {:v1_empty_controllers, "1::/owned\n", "1::/owned\n", :v1},
      {:duplicate_hierarchy, "1:cpu:/owned\n1:memory:/owned\n", "1:cpu:/owned\n1:memory:/owned\n", :v1},
      {:duplicate_controller, "1:cpu,cpu:/owned\n", "1:cpu,cpu:/owned\n", :v1},
      {:controller_empty, "1:cpu,:/owned\n", "1:cpu,:/owned\n", :v1},
      {:controller_space, "1:cpu, memory:/owned\n", "1:cpu, memory:/owned\n", :v1},
      {:duplicate_controller_across_rows, "1:cpu:/owned\n2:cpu:/other\n", "1:cpu:/owned\n2:cpu:/other\n", :v1},
      {:missing_record, "2:cpu,cpuacct:/owned:test scope\n", "2:cpu,cpuacct:/owned:test scope\n3:name=systemd:/user.slice\n", :v1},
      {:extra_record, "0::/owned:test scope\n2:cpu:/owned\n", "0::/owned:test scope\n", :hybrid},
      {:topology_mismatch, "2:cpu:/owned\n", "2:cpu:/owned\n", :v2},
      {:hybrid_without_v2, "2:cpu:/owned\n", "2:cpu:/owned\n", :hybrid},
      {:hybrid_without_v1, "0::/owned\n", "0::/owned\n", :hybrid},
      {:extra_newline, "0::/owned\n\n", "0::/owned\n\n", :v2},
      {:overflow4097, :binary.copy("x", 4097), :binary.copy("x", 4097), :v2}
    ]

    grammar_controls = [
          {"0::/a:b c:d\n", :v2, {:ok, [%{hierarchy: "0", controllers: [], path: "/a:b c:d"}]}},
          {"2:cpu,cpuacct:/owned:test scope\n3:name=systemd:/user.slice\n", :v1,
           {:ok, [%{hierarchy: "2", controllers: ["cpu", "cpuacct"], path: "/owned:test scope"},
                  %{hierarchy: "3", controllers: ["name=systemd"], path: "/user.slice"}]}},
          {"0::/owned:test scope\n2:cpu,cpuacct:/owned:test scope\n3:name=systemd:/user.slice\n", :hybrid,
           {:ok, [%{hierarchy: "0", controllers: [], path: "/owned:test scope"},
                  %{hierarchy: "2", controllers: ["cpu", "cpuacct"], path: "/owned:test scope"},
                  %{hierarchy: "3", controllers: ["name=systemd"], path: "/user.slice"}]}}
        ]

    cases =
      Enum.map(malformed, fn {label, bytes, raw, topology} ->
        {label, bytes, raw, topology, {:error, :invalid_cgroup}}
      end) ++
        Enum.map(grammar_controls, fn {bytes, topology, result} ->
          {:reviewed_topology, bytes, bytes, topology, result}
        end)

    for {_label, bytes, raw, topology, result} <- cases,
        {input, independent, version, wanted} <- [
          {"0::/owned:test scope\n", "0::/owned:test scope\n", :v2, expected},
          {bytes, raw, topology, result}
        ] do
      assert ua_parse_cgroup(input, independent, version) == wanted
    end
  end

  test "unconfirmed-await mountinfo grammar excludes every covered self and native overmount" do
    expected = ua_mount_expected()
    context = %{self_pid: "4242", native_pid: "5252", proc_device: {0, 5}}

    malformed = [
      {:no_lf, String.trim_trailing(ua_mount_literal(), "\n")},
      {:blank_line, ua_mount_literal() <> "\n"},
      {:empty, ""},
      {:nonbinary, []},
      {:nul, ua_mount_literal() <> <<0>>},
      {:cr, String.replace(ua_mount_literal(), "\n", "\r\n")},
      {:overflow16385, :binary.copy("x", 16385)},
      {:no_separator, String.replace(ua_mount_literal(), " - ", " ")},
      {:double_separator, String.replace(ua_mount_literal(), " - ", " - - ")},
      {:missing_left, String.replace(ua_mount_literal(), "21 1 ", "21 ")},
      {:missing_right, String.replace(ua_mount_literal(), "proc proc rw", "proc rw")},
      {:extra_right, String.replace(ua_mount_literal(), "proc proc rw", "proc proc rw extra")},
      {:noncanonical_id, String.replace_prefix(ua_mount_literal(), "21", "021")},
      {:zero_id, String.replace_prefix(ua_mount_literal(), "21", "0")},
      {:noncanonical_parent, String.replace(ua_mount_literal(), "21 1 ", "21 +1 ")},
      {:noncanonical_device, String.replace(ua_mount_literal(), "0:5", "00:5")},
      {:bad_device, String.replace(ua_mount_literal(), "0:5", "0:x")},
      {:wrong_device, String.replace(ua_mount_literal(), "0:5", "0:6")},
      {:wrong_root, String.replace(ua_mount_literal(), "0:5 / /proc ", "0:5 /other /proc ")},
      {:wrong_type, String.replace(ua_mount_literal(), " - proc proc ", " - tmpfs proc ")},
      {:wrong_point, String.replace(ua_mount_literal(), " /proc ", " /other ")},
      {:duplicate_proc_cover, ua_mount_literal() <> "22 1 0:5 / /proc rw - proc proc rw\n"},
      {:optional_unknown, String.replace(ua_mount_literal(), " - ", " mystery:1 - ")},
      {:optional_duplicate, String.replace(ua_mount_literal(), " - ", " shared:1 shared:1 - ")},
      {:optional_zero, String.replace(ua_mount_literal(), " - ", " shared:0 - ")},
      {:optional_noncanonical, String.replace(ua_mount_literal(), " - ", " master:01 - ")},
      {:optional_duplicate_unbindable, String.replace(ua_mount_literal(), " - ", " unbindable unbindable - ")},
      {:duplicate_mount_id, ua_mount_literal() <> "21 1 0:6 / /other rw - tmpfs tmpfs rw\n"},
      {:bad_escape, ua_mount_literal() <> "22 1 0:6 / /other\\999 rw - tmpfs tmpfs rw\n"},
      {:partial_escape, ua_mount_literal() <> "22 1 0:6 / /other\\04 rw - tmpfs tmpfs rw\n"},
      {:unknown_escape, ua_mount_literal() <> "22 1 0:6 / /other\\141 rw - tmpfs tmpfs rw\n"},
      {:empty_mount_option, String.replace(ua_mount_literal(), "rw,nosuid", "rw,,nosuid")},
      {:duplicate_mount_option, String.replace(ua_mount_literal(), "rw,nosuid", "rw,rw,nosuid")},
      {:empty_super_option, String.replace(ua_mount_literal(), "proc proc rw\n", "proc proc rw,\n")}
    ]

    hidepid =
      for value <- ["1", "2", "3", "4", "-1", "0foo", "invisible", "ptraceable", "00", "+0", "-0", "", "unknown"],
          location <- [:mount, :super] do
        mutated =
          case location do
            :mount -> String.replace(ua_mount_literal(), "rw,nosuid", "rw,hidepid=" <> value <> ",nosuid")
            :super -> String.replace(ua_mount_literal(), "proc proc rw\n", "proc proc rw,hidepid=" <> value <> "\n")
          end

        {:hidepid, mutated}
      end

    duplicate_policy = [
      {:duplicate_hidepid, String.replace(ua_mount_literal(), "proc proc rw\n", "proc proc rw,hidepid=0,hidepid=0\n")},
      {:cross_hidepid, ua_mount_literal() |> String.replace("rw,nosuid", "rw,hidepid=0,nosuid") |> String.replace("proc proc rw\n", "proc proc rw,hidepid=0\n")},
      {:bare_hidepid, String.replace(ua_mount_literal(), "proc proc rw\n", "proc proc rw,hidepid\n")}
    ]

    nsfs_roots =
      for kind <- ~w(cgroup ipc mnt net pid time user uts),
          inode <- ~w(1 4026531836 4294967295),
          do: kind <> ":[" <> inode <> "]"

    nsfs_controls =
      for root <- nsfs_roots ++ ["/", "/escaped\\040space"] do
        {ua_mount_literal() <> "22 1 0:6 " <> root <> " /other rw - nsfs nsfs rw\n", expected}
      end

    nsfs_malformed =
      for {root, type, point} <-
            Enum.map([
              "unknown:[1]", "pid_for_children:[1]", "time_for_children:[1]", "PID:[1]", ":[1]",
              "pid:[0]", "pid:[00]", "pid:[01]", "pid:[+1]", "pid:[-1]",
              "pid:[4294967296]", "pid:[18446744073709551615]", "pid:[]",
              "pid:[1", "pid:1]", "pid:[1]]", "pid:[1]suffix", "pid:[1]/",
              "pid:[1.0]", "pid:\\1331\\135", "pid:[\\061]"
            ], &{&1, "nsfs", "/other"}) ++
              Enum.map(["proc", "tmpfs", "NSFS", "nsfsx"], &{"pid:[1]", &1, "/other"}) ++
              [{"/", "nsfs", "pid:[1]"}, {"pid:[1]", "nsfs", "pid:[1]"}] do
        {:nsfs_root, ua_mount_literal() <>
          "22 1 0:6 " <> root <> " " <> point <> " rw - " <> type <> " nsfs rw\n"}
      end

    nsfs_malformed = nsfs_malformed ++ [
      {:nsfs_selected_proc, "21 1 0:5 pid:[1] /proc rw - nsfs nsfs rw\n"}
    ]

    grammar_controls = [
          {ua_mount_literal() <> "22 21 0:6 / /proc/9999 rw - tmpfs tmpfs rw\n", expected},
          {ua_mount_literal() <> "22 21 0:6 / /proc/42420 rw - tmpfs tmpfs rw\n", expected},
          {ua_mount_literal() <> "22 1 0:6 / /escaped\\040space\\011tab\\012lf\\134slash\\043hash rw - tmpfs tmpfs rw\n", expected},
          {String.replace(ua_mount_literal(), " - ", " shared:7 master:8 propagate_from:9 - "),
           {:ok, %{record: "21 1 0:5 / /proc rw,nosuid,nodev,noexec,relatime shared:7 master:8 propagate_from:9 - proc proc rw",
                   device: {0, 5}, hidepid: 0, paths: ua_proc_paths()}}},
          {String.replace(ua_mount_literal(), " - ", " unbindable - "),
           {:ok, %{record: "21 1 0:5 / /proc rw,nosuid,nodev,noexec,relatime unbindable - proc proc rw",
                   device: {0, 5}, hidepid: 0, paths: ua_proc_paths()}}},
          {String.replace(ua_mount_literal(), "proc proc rw\n", "proc proc rw,hidepid=0\n"),
           {:ok, %{record: "21 1 0:5 / /proc rw,nosuid,nodev,noexec,relatime - proc proc rw,hidepid=0",
                   device: {0, 5}, hidepid: 0, paths: ua_proc_paths()}}},
          {String.replace(ua_mount_literal(), "rw,nosuid", "rw,hidepid=0,nosuid"),
           {:ok, %{record: "21 1 0:5 / /proc rw,hidepid=0,nosuid,nodev,noexec,relatime - proc proc rw",
                   device: {0, 5}, hidepid: 0, paths: ua_proc_paths()}}}
        ]

    overmounts =
      for path <- ua_proc_paths(), suffix <- [
            "22 21 0:6 / " <> path <> " rw - tmpfs tmpfs rw\n",
            "22 21 0:5 / " <> path <> " rw - proc proc rw\n",
            "22 21 0:6 pid:[1] " <> path <> " rw - nsfs nsfs rw\n",
            "22 21 0:6 / " <> path <> " rw - nsfs nsfs rw\n"
          ] do
        {:covering_mount, ua_mount_literal() <> suffix}
      end

    cases =
      Enum.map(malformed ++ hidepid ++ duplicate_policy ++ overmounts ++ nsfs_malformed, fn {label, bytes} ->
        {label, bytes, {:error, :invalid_mountinfo}}
      end) ++
        Enum.map(grammar_controls ++ nsfs_controls, fn {bytes, result} -> {:valid_route, bytes, result} end)

    for {_label, mutated, result} <- cases,
        {bytes, wanted} <- [{ua_mount_literal(), expected}, {mutated, result}] do
      assert ua_parse_mountinfo(bytes, context) == wanted
    end

    for changed <- [
          %{context | self_pid: "04242"}, %{context | native_pid: "05252"},
          %{context | self_pid: "0"}, %{context | native_pid: "4294967296"},
          %{context | native_pid: "4242"}, %{context | proc_device: {0, 6}},
          Map.delete(context, :proc_device)
        ],
        {input, admission, result} <- [
          {ua_mount_literal(), context, expected},
          {ua_mount_literal(), changed, {:error, :invalid_mountinfo}}
        ] do
      assert ua_parse_mountinfo(input, admission) == result
    end
  end

