      {:no_await, good, put_in(good, [:boundary, :await_entry], nil)},
      {:no_exception, good, put_in(good, [:boundary, :await_exception], nil)},
      {:no_unlock, good, put_in(good, [:boundary, :unlock], nil)},
      {:not_held, good, put_in(good, [:boundary, :held], false)},
