      {:cached_native_status_claimed_fresh, good, %{good | observations: [
        %{absent | before: Map.put(absent.before, :native_status, live.status)}
      ]}},
      {:full_live_admission_reused_as_fresh, good, %{good | observations: [
        %{absent | before: good.original.admission}
      ]}},
      {:wrong_absence_pid, good, %{good | observations: [
        %{absent | reads: [{:lstat, "/proc/5253", {:error, :enoent}},
                          {:stat_path, "/proc/5253/stat", {:error, :enoent}},
                          {:lstat, "/proc/5253", {:error, :enoent}}]}
      ]}},
      {:exe_only, good, %{good | observations: [
