      {:expired, good, %{good | observations: [%{absent | at: 100}]}},
      {:no_port_monitor, good, put_in(good, [:original, :port_monitor_installed_live], false)},
      {:late_port_monitor, good, put_in(good, [:original, :port_monitor_at], 11)},
