      {:foreign_port_down, good, %{good | port_down: [{:other_ref, :port, :port, :normal, 18}]}},
      {:foreign_port, good, %{good | port_down: [{:port_ref, :port, :other_port, :normal, 18}]}},
      {:duplicate_port_down, good, %{good | port_down: good.port_down ++ good.port_down}},
      {:no_port_down, good, %{good | port_down: []}},
      {:port_non_nil, good, %{good | port_info: {:connected, :command}}},
