            {0, {:lstat, "/proc/5252", {:ok, {:directory, 0, 5, 9999}}}},
            {1, {:stat, {:ok, %{pid: "5252", state: "Z", start_ticks: "987654322"}}}},
            {2, {:status, {:ok, %{pid: "5252", tgid: "5252", state: "Z",
               uids: {"1001", "1001", "1001", "1001"}, nspid: ["5252"], nstgid: ["5252"]}}}},
            {3, {:cgroup, {:error, :invalid_cgroup}}}
          ] do
        {{:terminal_conflict_then_absent, index}, %{good | observations: [terminal_sample, absent]},
         %{good | observations: [
           %{terminal_sample | reads: List.replace_at(terminal_sample.reads, index, replacement)}, absent]}}
      end

    mutations = mutations ++
      for index <- 0..2, result <- [
        {:error, :eacces}, {:error, :eperm}, {:error, :esrch}, {:error, :enotdir},
        {:error, :eio}, {:ok, :present}
      ] do
        {{:absence_read, index, result}, good, %{good | observations: [
          %{absent | reads: List.update_at(absent.reads, index, fn {kind, path, _} ->
