      end

    mutations = mutations ++
      for index <- [0, 1], key <- Map.keys(live) do
        {{:missing_live_sample_fact, index, key}, good,
         update_in(good.original.live, &List.update_at(&1, index, fn s -> Map.delete(s, key) end))}
      end

    mutations = mutations ++
