        {:await_exception, {12, :exit, {:killed, {ExCmd.Process, :await_exit, [:foreign, 5000]}}}},
        {:await_exception, {12, :return, {:error, :killed}}},
        {:unlock, {10, :observer, :observer_connection, [1413567307, 18], [[true]]}},
