              uids: {"1001", "1001", "1001", "1001"}, nspid: ["4242"], nstgid: ["4242"]}}}
          end)
        ]}}
      end

    mutations = mutations ++
      for bad <- [nil, [], :unknown, %{}] do
        {:total_native_domain, good, bad}
      end

    mutations = mutations ++
      for index <- [0, 1], at <- if(index == 0, do: [2, 3, 10], else: [0, 3, 10]) do
        {{:live_sample_order, index, at}, good,
         update_in(good.original.live, &List.update_at(&1, index, fn s -> %{s | at: at} end))}
      end

    mutations = mutations ++
