        status: ua_parse_status(String.replace(ua_status_literal(), "S (sleeping)", "R (running)"), "4242")}}
    ]}
    mutations = mutations ++ [
      {:fresh_self_live_state_variation, self_running, %{self_running | sticky_invalid: true}}
    ]

    # Ordinary paired rows and one equality site: the first valid row is genuine RED.
    cases = Enum.flat_map(mutations, fn {label, control, mutant} ->
      [{label, true, control}, {label, false, mutant}]
    end)

    for {_label, expected, facts} <- cases do
      assert ua_original_gone?(facts) == expected
    end
  end

  test "unconfirmed-await boundary protocol retains original errors and orders independent hygiene" do
    good = ua_b_boundary_literal()
    # Reversed mailbox delivery is legal; causal operation timestamps remain fixed.
    reordered_mailbox = %{good | mailbox_arrival: Enum.reverse(good.mailbox_arrival)}
    sampled = good
    aborts = for reason <- [:abort, :timeout, :observer_down, :observation_error, :failed_release] do
      events = Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:measurement, :continuation, :boundary_exit, :hygiene]
      end)
      exit_reason = case reason do
        :observation_error -> :error
        :failed_release -> :timeout
        other -> other
      end
      release = if reason == :failed_release, do: {:error, :failed_release}, else: :attempted
      events = events ++ [
        {24, :continuation, {:abort_attempt, :observer, :owner, :nonce, :bounded, release}},
        {25, :boundary_exit, {:owner, :nonce, exit_reason}},
        {26, :rethrow, good.caught}
      ]
      %{good |
        mode: reason, events: Enum.sort_by(Enum.reject(events, fn {_at, kind, _} ->
          kind == :rethrow
        end) ++ [{26, :rethrow, good.caught}], &elem(&1, 0)),
        credits: %{sample: false, recovery: false, hygiene: false},
        failures: [{:observation, reason}], hygiene: :forbidden
      }
    end

    unknown = %{good |
      mode: :unknown_catch, caught: {:exit, {:unexpected_helper, :original}, [:original_stack]},
      events: Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:caught, :boundary_entry, :measurement, :continuation, :boundary_exit, :rethrow, :hygiene]
      end) ++ [{10, :caught, {:exit, {:unexpected_helper, :original}, [:original_stack]}},
        {26, :rethrow, {:exit, {:unexpected_helper, :original}, [:original_stack]}}],
      credits: %{sample: false, recovery: false, hygiene: false},
      failures: [{:catch, :ineligible}], hygiene: :forbidden
    }
    unknown = %{unknown | events: Enum.sort_by(unknown.events, &elem(&1, 0))}
    # A bounded join can fail, but all other joins still run; retained failures and
    # permanent quarantine are protocol conformity, not successful cleanup.
    join_failure = %{hd(aborts) |
      joins: List.replace_at(good.joins, 0, {:reader, :reader_ref, :bounded, {:error, :timeout}}),
      failures: [{:observation, :abort}, {:join, :reader, :timeout}]
    }
    controls = [sampled, reordered_mailbox, unknown, join_failure | aborts]

    mutations = [
      {:wrong_primary, good, put_in(good, [:helper, :primary], :legacy_exit)},
      {:helper_confirmed, good, put_in(good, [:helper, :await], :confirmed)},
      {:cleanup_confirmed, good, put_in(good, [:helper, :cleanup], :confirmed)},
      {:extra_secondary, good, put_in(good, [:helper, :secondary],
        [{:legacy_preparation_quarantined, :unconfirmed}, :other])},
      {:masked_preparation_error, good, put_in(good, [:helper, :preparation_error],
        {:legacy_exit, [{:legacy_preparation_quarantined, :unconfirmed}]})},
      {:normal_owner_credit, good, put_in(good, [:terminal, :owner], :normal)},
      {:wrong_actor_terminal, good, put_in(good, [:terminal, :actor], :killed)},
      {:registered_actor, good, put_in(good, [:preconditions, :on_exit], :registered)},
      {:gate_changed, good, put_in(good, [:gate, :key], [1413567307, 19])},
      {:child_holds_gate, good, put_in(good, [:gate, :locks],
        [[401, false, "ExclusiveLock", 1413567307, 18, 2],
         [501, true, "ExclusiveLock", 1413567307, 18, 2]])},
      {:wrong_blocker, good, put_in(good, [:gate, :waits],
        [[501, "Lock", "advisory", [402]]])},
      {:wrong_wait, good, put_in(good, [:gate, :waits],
        [[501, nil, nil, []]])},
      {:recursive_gate_acquisition, good, put_in(good, [:gate, :acquisitions], 2)},
      {:one_gate_sample, good, put_in(good, [:gate, :samples], [3])},
      {:unbounded_gate_query, good, put_in(good, [:gate, :query_bound_ms], 1001)},
      {:wrong_observer_role, good, put_in(good, [:gate, :observer_identity],
        [[401, "singularity_runtime", "A"]])},
      {:wrong_oid, good, put_in(good, [:gate, :oid], 7002)},
      {:changed_expected_oid, good, put_in(good, [:expected, :oid], 7002)},
      {:changed_expected_handle, good, put_in(good, [:expected, :handle], :other_handle)},
      {:changed_original_handle, good, put_in(good, [:preconditions, :handle], :other_handle)},
      {:two_kills, good, put_in(good, [:preconditions, :command_kills], [:command, :command])},
      {:wrong_kill_target, good, put_in(good, [:preconditions, :command_kills], [:native])},
      {:signals_added, good, put_in(good, [:preconditions, :extra_signals], [:kill])},
      {:unlock_twice, good, put_in(good, [:gate, :unlock_results], [[[true]], [[true]]])},
