  end

  test "unconfirmed-await causal boundary uses coherent unlock and actual worker DOWN times" do
    good = ua_b_boundary_literal()
    aborts = for reason <- [:abort, :timeout, :observer_down, :observation_error, :failed_release] do
      events = Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:measurement, :continuation, :boundary_exit, :hygiene]
      end)
      exit_reason = case reason do
        :observation_error -> :error
        :failed_release -> :timeout
        other -> other
      end
      release = if reason == :failed_release, do: {:error, :failed_release}, else: :attempted
      events = events ++ [
        {24, :continuation, {:abort_attempt, :observer, :owner, :nonce, :bounded, release}},
        {25, :boundary_exit, {:owner, :nonce, exit_reason}},
        {26, :rethrow, good.caught}
      ]
      %{good |
        mode: reason, events: Enum.sort_by(Enum.reject(events, fn {_at, kind, _} ->
          kind == :rethrow
        end) ++ [{26, :rethrow, good.caught}], &elem(&1, 0)),
        credits: %{sample: false, recovery: false, hygiene: false},
        failures: [{:observation, reason}], hygiene: :forbidden
      }
    end

    unknown = %{good |
      mode: :unknown_catch, caught: {:exit, {:unexpected_helper, :original}, [:original_stack]},
      events: Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:caught, :boundary_entry, :measurement, :continuation, :boundary_exit, :rethrow, :hygiene]
      end) ++ [{10, :caught, {:exit, {:unexpected_helper, :original}, [:original_stack]}},
        {26, :rethrow, {:exit, {:unexpected_helper, :original}, [:original_stack]}}],
      credits: %{sample: false, recovery: false, hygiene: false},
      failures: [{:catch, :ineligible}], hygiene: :forbidden
    }
    unknown = %{unknown | events: Enum.sort_by(unknown.events, &elem(&1, 0))}
    eligible = [good | aborts]
    controls = eligible ++ [unknown]

    # Both independent views change coherently; this is not an event-only conflict.
    # Standalone OriginalGone's existing unlock13/entry14 control is untouched.
    early_unlock_pairs = for control <- eligible do
      events = Enum.map(control.events, fn
        {_at, :boundary_entry, payload} -> {12, :boundary_entry, payload}
        {_at, :unlock, payload} -> {11, :unlock, payload}
        event -> event
      end) |> Enum.sort_by(&elem(&1, 0))
      boundary = control.measurement.native.boundary
      boundary = %{boundary |
        entry: put_elem(boundary.entry, 0, 12),
        unlock: put_elem(boundary.unlock, 0, 11)
      }
      mutant = put_in(control, [:measurement, :native, :boundary], boundary)
      {{:coherent_early_unlock, control.mode}, control, %{mutant | events: events}}
    end

    # :down is the original terminal occurrence, not later join observation.
    # All thirteen bounded attempts/refs remain; Port DOWN18 is separate.
    early_worker_pairs =
      for control <- controls, at <- [7, 8, 9], worker <- [:reader, :writer] do
        joins = Enum.map(control.joins, fn
          {id, ref, bound, {:down, _at}} when id in [:reader, :writer] ->
            {id, ref, bound, {:down, at}}
          join -> join
        end)
        positive = %{control | joins: joins}
        late_at = if control.mode == :unknown_catch, do: 26, else: 12
        mutant = %{positive | joins: Enum.map(positive.joins, fn
          {^worker, ref, bound, {:down, _at}} -> {worker, ref, bound, {:down, late_at}}
          join -> join
        end)}
        {{:actual_worker_down, control.mode, at, worker}, positive, mutant}
      end

    # Unknown catch has no eligible boundary entry: DOWN12 is still pre-rethrow.
    later_unknown_pairs = for worker <- [:reader, :writer] do
      joins = Enum.map(unknown.joins, fn
        {id, ref, bound, {:down, _at}} when id in [:reader, :writer] ->
          {id, ref, bound, {:down, 12}}
        join -> join
      end)
      positive = %{unknown | joins: joins}
      mutant = %{positive | joins: Enum.map(positive.joins, fn
        {^worker, ref, bound, {:down, _at}} -> {worker, ref, bound, {:down, 26}}
        join -> join
      end)}
      {{:unknown_worker_down_after_ineligible_catch, worker}, positive, mutant}
    end

    cases = Enum.flat_map(early_unlock_pairs ++ early_worker_pairs ++ later_unknown_pairs,
      fn {label, control, mutant} -> [{label, true, control}, {label, false, mutant}] end)
    for {_label, expected, facts} <- cases do
