  test "unconfirmed-await boundary rejects improper collections and coherently retained stacks" do
    good = ua_b_boundary_literal()
    improper = fn values ->
      Enum.reduce(Enum.reverse(values), :invalid_tail, fn value, tail -> [value | tail] end)
    end
    aborts = for reason <- [:abort, :timeout, :observer_down, :observation_error, :failed_release] do
      events = Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:measurement, :continuation, :boundary_exit, :hygiene]
      end)
      exit_reason = case reason do
        :observation_error -> :error
        :failed_release -> :timeout
        other -> other
      end
      release = if reason == :failed_release, do: {:error, :failed_release}, else: :attempted
      events = events ++ [
        {24, :continuation, {:abort_attempt, :observer, :owner, :nonce, :bounded, release}},
        {25, :boundary_exit, {:owner, :nonce, exit_reason}},
        {26, :rethrow, good.caught}
      ]
      %{good |
        mode: reason, events: Enum.sort_by(Enum.reject(events, fn {_at, kind, _} ->
          kind == :rethrow
        end) ++ [{26, :rethrow, good.caught}], &elem(&1, 0)),
        credits: %{sample: false, recovery: false, hygiene: false},
        failures: [{:observation, reason}], hygiene: :forbidden
      }
    end

    unknown = %{good |
      mode: :unknown_catch, caught: {:exit, {:unexpected_helper, :original}, [:original_stack]},
      events: Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:caught, :boundary_entry, :measurement, :continuation, :boundary_exit, :rethrow, :hygiene]
      end) ++ [{10, :caught, {:exit, {:unexpected_helper, :original}, [:original_stack]}},
        {26, :rethrow, {:exit, {:unexpected_helper, :original}, [:original_stack]}}],
      credits: %{sample: false, recovery: false, hygiene: false},
      failures: [{:catch, :ineligible}], hygiene: :forbidden
    }
    unknown = %{unknown | events: Enum.sort_by(unknown.events, &elem(&1, 0))}
    abort = hd(aborts)

    sampled_pairs = for {label, path} <- [
      {:original_monitors, [:expected, :original_monitors]},
      {:backend_baseline, [:expected, :backend_baseline]},
      {:ancestors, [:expected, :ancestors]},
      {:events, [:events]},
      {:mailbox_arrival, [:mailbox_arrival]},
      {:joins, [:joins]},
      {:native_observations, [:measurement, :native, :observations]},
      {:native_port_down, [:measurement, :native, :port_down]},
      {:baselines, [:measurement, :baselines]},
      {:sample_times, [:measurement, :sample_times]},
      {:brackets, [:measurement, :brackets]},
      {:gate_samples, [:gate, :samples]},
      {:hygiene_observations, [:hygiene, :native, :observations]}
    ] do
      {{:sampled_collection, label}, good, update_in(good, path, improper)}
    end

    abort_pairs = for field <- [:tagged_rows, :baselines, :sample_times, :brackets] do
      # Retained failed observations confer no sampled or hygiene credit.
      control = if field == :tagged_rows,
        do: put_in(abort, [:measurement, field], [[good.expected.child_backend]]), else: abort
      {{:abort_payload, field}, control, update_in(control, [:measurement, field], improper)}
    end

    stack_pairs = for control <- [good, abort, unknown] do
      changed = put_elem(control.caught, 2, improper.(elem(control.caught, 2)))
      mutant = %{control |
        caught: changed,
        events: Enum.map(control.events, fn
          {at, kind, _payload} when kind in [:caught, :rethrow] -> {at, kind, changed}
          event -> event
        end)
      }
      {{:coherent_stack, control.mode}, control, mutant}
    end

    # A genuine read error remains unknown in an abort, never an absence proof.
    observation = hd(abort.measurement.native.observations)
    retained = %{observation | kind: :unknown, reads: [{:error, :eacces}],
      native_status_reads: ["/proc/" <> good.measurement.native.expected.native_pid <> "/status"]}
    unknown_native = abort
      |> put_in([:measurement, :native, :unknown], true)
      |> put_in([:measurement, :native, :observations], [retained])
    fallback_pairs = for field <- [:reads, :native_status_reads] do
      {{:unknown_native_abort, field}, unknown_native,
       update_in(unknown_native, [:measurement, :native, :observations, Access.at(0), field], improper)}
    end

    cases = Enum.flat_map(sampled_pairs ++ abort_pairs ++ stack_pairs ++ fallback_pairs,
      fn {label, control, mutant} -> [{label, true, control}, {label, false, mutant}] end)
    for {_label, expected, facts} <- cases do
      assert ua_boundary_protocol?(facts) == expected
    end
  end

  # Only literal setup: A's actual parsers supply typed fields. Expected identity
  # and all operation ledgers are supplied independently, never parser doubles.
  test "unconfirmed-await registration origin binds routing and query identity on every outcome" do
    good = ua_b_boundary_literal()
    aborts = for reason <- [:abort, :timeout, :observer_down, :observation_error, :failed_release] do
      events = Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:measurement, :continuation, :boundary_exit, :rethrow, :hygiene]
      end)
      exit_reason = case reason do
        :observation_error -> :error
        :failed_release -> :timeout
        other -> other
      end
      release = if reason == :failed_release, do: {:error, :failed_release}, else: :attempted
      %{good |
        mode: reason,
        events: Enum.sort_by(events ++ [
          {24, :continuation, {:abort_attempt, :observer, :owner, :nonce, :bounded, release}},
          {25, :boundary_exit, {:owner, :nonce, exit_reason}},
          {26, :rethrow, good.caught}
        ], &elem(&1, 0)),
        credits: %{sample: false, recovery: false, hygiene: false},
        failures: [{:observation, reason}], hygiene: :forbidden
      }
    end
    caught = {:exit, {:unexpected_helper, :original}, [:original_stack]}
    unknown = %{good |
      mode: :unknown_catch, caught: caught,
      events: Enum.sort_by(Enum.reject(good.events, fn {_at, kind, _} ->
        kind in [:caught, :boundary_entry, :measurement, :continuation, :boundary_exit, :rethrow, :hygiene]
      end) ++ [{10, :caught, caught}, {26, :rethrow, caught}], &elem(&1, 0)),
      credits: %{sample: false, recovery: false, hygiene: false},
      failures: [{:catch, :ineligible}], hygiene: :forbidden
    }
    controls = [good | aborts] ++ [unknown]

    # These are independently supplied model origins, not live registration proof.
    foreign_origin = %{
      private_key: :foreign_key, tag: "singularity_task18_foreign",
      run: :foreign_run, caller: :foreign_actor, observer: :foreign_observer
    }
    renamed = fn control, key, tag ->
      %{control |
        expected: %{control.expected | private_key: key, tag: tag},
        registration_origin: %{control.registration_origin | private_key: key, tag: tag},
        events: Enum.map(control.events, fn
          {at, :boundary_entry, {_key, owner, caller, database, nonce}} ->
            {at, :boundary_entry, {key, owner, caller, database, nonce}}
          {at, :measurement, {_key, owner, nonce, :held}} ->
            {at, :measurement, {key, owner, nonce, :held}}
          {at, :continuation, {_key, observer, owner, nonce, :sampled}} ->
            {at, :continuation, {key, observer, owner, nonce, :sampled}}
          event -> event
        end)
      }
    end

    mutations = Enum.flat_map(controls, fn control ->
      [
        {{:expected_tag, control.mode}, control,
         put_in(control, [:expected, :tag], "singularity_task18_other")},
        {{:expected_private_key, control.mode}, control,
         put_in(control, [:expected, :private_key], :other_key)},
        {{:missing_origin, control.mode}, control, Map.delete(control, :registration_origin)},
        {{:extra_origin_field, control.mode}, control,
         put_in(control, [:registration_origin, :extra], true)},
        {{:foreign_run_origin, control.mode}, control,
         %{control | registration_origin: foreign_origin}}
      ] ++
        (for malformed <- [nil, false, :unknown, [], [:entry | :invalid_tail], {:registration, :foreign}] do
          {{:malformed_origin, control.mode, malformed}, control,
           %{control | registration_origin: malformed}}
        end) ++
        (for field <- [:private_key, :tag, :run, :caller, :observer] do
          {{:missing_origin_field, control.mode, field}, control,
           %{control | registration_origin: Map.delete(control.registration_origin, field)}}
        end) ++
        (for {field, value} <- [
          {:private_key, :foreign_key}, {:tag, "singularity_task18_foreign"},
          {:run, :foreign_run}, {:caller, :foreign_actor}, {:observer, :foreign_observer}
        ] do
          {{:changed_origin_field, control.mode, field}, control,
           put_in(control, [:registration_origin, field], value)}
        end) ++
        (for {key, tag} <- [
          {:alternate_key, "singularity_task18_alternate"},
          {{:private, :alternate}, "another_probe"}
        ] do
          coherent = renamed.(control, key, tag)
          # Renaming the current claims cannot rebind the retained original origin.
          {{:retained_origin_after_rebinding, control.mode, key}, coherent,
           %{coherent | registration_origin: control.registration_origin}}
        end)
    end)

    cases = Enum.flat_map(mutations, fn {label, control, mutant} ->
      [{label, true, control}, {label, false, mutant}]
    end)

    for {_label, expected, facts} <- cases do
      assert ua_boundary_protocol?(facts) == expected
    end
  end

