        owner: {:fixture_cleanup_failed, [{:legacy_preparation_quarantined, :unconfirmed}]},
        actor: :normal, before_arm_on_exit: nil
      },
      joins: [
        {:reader, :reader_ref, :bounded, {:down, 9}}, {:writer, :writer_ref, :bounded, {:down, 9}},
        {:command, :command_ref, :bounded, {:down, 7}}, {:port, :port_ref, :bounded, {:down, 18}},
        {:migration_repo, :migration_ref, :bounded, {:down, 31}},
        {:request_repo, :request_ref, :bounded, {:down, 32}}, {:preauth_repo, :preauth_ref, :bounded, {:down, 33}},
        {:dispatcher_repo, :dispatcher_ref, :bounded, {:down, 34}}, {:worker_repo, :worker_ref, :bounded, {:down, 35}},
        {:maintenance, :maintenance_ref, :bounded, {:down, 36}},
        {:owner, :owner_ref, :bounded, {:down, 40}}, {:actor, :actor_ref, :bounded, {:down, 41}},
        {:observer_connection, :observer_connection_ref, :bounded, {:down, 42}}
      ],
      restoration: %{
        event_fence: true, trace_fence: true, late_message_drain: true,
        stdout: true, stderr: true, logger: true, exception_messages: true, inspect_canary: true,
        telemetry_registered_positive: true, own_telemetry_detached: true,
        entire_telemetry_baseline: true, own_trace_sessions_closed: true,
        traced: true, match_spec: true, meta: true, meta_match_spec: true,
        process_flags: true, tracer: true, config: true, compiler: true, environment: true,
        repository: true, no_content_in_diagnostics: true, original_failures_retained: true, original_observer_demonitor_only: true
      },
      retention: %{
        database_name_oid: true, allocation: true, objects: true, workspace: true,
        nonlink_identities: true, safe_ancestors: true, empty_inventories: true,
        quarantine_recorded: true, no_automatic_drop: true, no_original_removal: true,
        roots: roots, ancestors: [{"/private", {:directory, 33, 0, 800}}],
        inventories: %{allocation: ["historical-build", "objects"], objects: [], historical_build: []}
      },
      # recovery is independent recovery/hygiene eligibility, never helper recovery.
      credits: %{sample: true, recovery: true, hygiene: true}, failures: [],
      hygiene: %{
        independent_authority: true, connection: :new_hygiene, role: :singularity_migration,
        maintenance_database: "postgres", database: "A", oid: 7001,
        session_scope: :all_a, all_a_rows: [], native: hygiene_native, native_fresh: true,
        roots: roots, ancestors: [{"/private", {:directory, 33, 0, 800}}],
        inventories: %{allocation: ["historical-build", "objects"], objects: [], historical_build: []},
        fresh_identities: true, empty_inventories: true, repeated_safe_ancestors: true,
        drop: :ordinary_exact_quoted, termination: :none,
        database_absent: true, removal: :identity_confirmed_empty_rmdir,
        removal_order: [:historical_build, :objects, :allocation],
        each_fresh_enoent: true, connection_down: true
      }
    }
  end

  # RED behavior is deliberately total; no implementation/interface failure.
  defp ua_original_gone?(facts) do
    with %{expected: e, original: o, boundary: b, observations: observations,
           port_down: down, port_info: nil, port_info_at: info_at, deadline: deadline,
           sticky_invalid: false, replacement_seen: false, unknown: false} <- facts,
         true <- ua_b_native_expected?(e),
         true <- ua_b_time?(deadline),
         true <- ua_b_original?(o, e),
         {:ok, times} <- ua_b_native_boundary(b, e, o, deadline),
         true <- ua_b_port_gone?(down, info_at, o, times.exception, deadline),
         {:ok, :absent, _at, _serial} <-
           ua_b_observations(observations, e, o.admission,
             max(times.unlock, times.entry), deadline) do
      true
    else
      _ -> false
    end
  end

  defp ua_boundary_protocol?(facts) do
    with true <- ua_b_keys?(facts, [:mode, :expected, :preconditions, :gate, :caught,
           :events, :mailbox_arrival, :measurement, :helper, :terminal, :joins,
           :restoration, :retention, :credits, :failures, :hygiene, :registration_origin]),
         %{expected: e, measurement: m} <- facts,
         true <- ua_b_protocol_expected?(e),
         true <- facts.registration_origin ===
           Map.take(e, [:private_key, :tag, :run, :caller, :observer]),
         true <- ua_b_measurement?(m, e, facts.mode),
         true <- ua_b_preconditions?(facts.preconditions, e, m.native.original),
         true <- ua_b_helper?(facts.helper),
         true <- ua_b_terminal?(facts.terminal),
         true <- ua_b_restoration?(facts.restoration),
         true <- ua_b_retention?(facts.retention, e),
         {:ok, events} <- ua_b_events(facts.events, e.deadline),
         true <- ua_b_common_events?(events, facts.caught, e, m),
         true <- ua_b_gate?(facts.gate, e, m.native, events),
         true <- ua_b_mailbox?(facts.mailbox_arrival),
         {:ok, join_failures} <- ua_b_joins(facts.joins, e, m.native, events),
         true <- ua_b_protocol_outcome?(facts, events, join_failures) do
      true
    else
      _ -> false
    end
  end

  defp ua_b_keys?(map, keys) when is_map(map),
    do: Enum.sort(Map.keys(map)) == Enum.sort(keys)
  defp ua_b_keys?(_, _), do: false

  defp ua_b_time?(n), do: is_integer(n) and n >= 0 and n <= 18_446_744_073_709_551_615
  defp ua_b_identity?(value), do: value not in [nil, false, true] and
    (is_atom(value) or is_pid(value) or is_port(value) or is_reference(value) or is_tuple(value))
  defp ua_b_path?(path), do: is_binary(path) and byte_size(path) <= 4096 and
    ua_absolute?(path) and :binary.match(path, <<0>>) == :nomatch
  defp ua_b_proper_list?(values) when is_list(values) and length(values) >= 0, do: true
  defp ua_b_proper_list?(_), do: false

  defp ua_b_increasing?(values) when is_list(values) and length(values) > 0 do
    Enum.all?(values, &ua_b_time?/1) and
      Enum.all?(Enum.zip(values, tl(values)), fn {a, b} -> a < b end)
  end
  defp ua_b_increasing?(_), do: false

  defp ua_b_handle?({:handle, command, monitor, exit, owner}, e),
    do: command == e.command and monitor == e.monitor_ref and exit == e.exit_ref and owner == e.owner
  defp ua_b_handle?(%{__struct__: ExCmd.Process, pid: command, monitor_ref: monitor,
                     exit_ref: exit, owner: owner}, e),
    do: command == e.command and monitor == e.monitor_ref and exit == e.exit_ref and owner == e.owner
  defp ua_b_handle?(_, _), do: false

  defp ua_b_native_expected?(e) do
    with true <- ua_b_keys?(e, [:native_pid, :self_pid, :start_ticks, :uids, :cgroup_raw,
           :cgroup, :directory, :exe, :handle, :command, :reader, :writer, :owner,
           :caller, :run, :port, :port_ref, :observer, :observer_connection, :gate_key,
           :database, :nonce, :monitor_ref, :exit_ref]),
         true <- ua_uint?(e.native_pid, 4_294_967_295, true),
         true <- ua_uint?(e.self_pid, 4_294_967_295, true),
         true <- e.native_pid != e.self_pid,
         true <- ua_uint?(e.start_ticks, 18_446_744_073_709_551_615, false),
         uid = ua_qualified_launch_uid(),
         true <- e.uids == {uid, uid, uid, uid},
         true <- ua_object?(e.directory, :directory),
         %{path: path, object: object, bytes: bytes} <- e.exe,
         true <- ua_b_path?(path) and ua_object?(object, :regular),
         true <- is_integer(bytes) and bytes > 0,
         true <- ua_b_cgroup?(e.cgroup_raw, e.cgroup),
         true <- Enum.all?([e.command, e.reader, e.writer, e.owner, e.caller, e.run,
           e.port, e.port_ref, e.observer, e.observer_connection, e.nonce,
           e.monitor_ref, e.exit_ref], &ua_b_identity?/1),
         true <- length(Enum.uniq([e.command, e.reader, e.writer, e.owner, e.caller])) == 5,
         true <- ua_b_handle?(e.handle, e),
         true <- e.gate_key == @transport_lock,
         true <- is_binary(e.database) and e.database != "" do
      true
    else
      _ -> false
    end
  end

  defp ua_b_cgroup?(raw, {:ok, records}) when is_list(records) and length(records) > 0 do
    Enum.any?([:v2, :v1, :hybrid], &(ua_parse_cgroup(raw, raw, &1) == {:ok, records}))
  end
  defp ua_b_cgroup?(_, _), do: false

  defp ua_b_original?(o, e) do
    with true <- ua_b_keys?(o, [:native_pid, :pid_source, :admission, :live,
           :bound_after_two_live, :bound_at, :handle, :command, :reader, :writer,
           :monitor_ref, :exit_ref, :owner, :caller, :run, :observer_connection,
           :connected_ports, :connected_command, :port, :port_ref,
           :port_monitor_installed_live, :port_monitor_at]),
         true <- o.native_pid == e.native_pid and o.pid_source == :original_ex_cmd_return,
         true <- o.bound_after_two_live == true and o.port_monitor_installed_live == true,
         true <- Enum.all?([:handle, :command, :reader, :writer, :monitor_ref, :exit_ref,
           :owner, :caller, :run, :port, :port_ref, :observer_connection],
           &(Map.fetch!(o, &1) == Map.fetch!(e, &1))),
         true <- o.connected_ports == [e.port] and o.connected_command == e.command,
         true <- ua_admit_proc(o.admission),
         true <- o.admission.system_pid == e.self_pid and o.admission.native_pid == e.native_pid,
         [first, second] <- o.live,
         true <- ua_b_live_sample?(first, e, o.admission),
         true <- ua_b_live_sample?(second, e, o.admission),
         true <- ua_b_increasing?([first.at, second.at, o.bound_at]),
         true <- ua_b_time?(o.port_monitor_at) and o.port_monitor_at <= first.at do
      true
    else
      _ -> false
    end
  end

  defp ua_b_live_sample?(s, e, admission) do
    with true <- ua_b_keys?(s, [:at, :stat, :status, :cgroup, :directory, :exe,
           :stat_after, :fd_closed, :admission_before, :admission_after]),
         true <- ua_b_time?(s.at) and s.fd_closed == true,
         true <- ua_b_stat?(s.stat, e, :live) and ua_b_stat?(s.stat_after, e, :live),
         true <- ua_b_status?(s.status, e.native_pid, e.uids, :live),
         true <- s.directory == e.directory and s.exe == {:ok, e.exe} and s.cgroup == e.cgroup,
         true <- ua_b_same_admission?(s.admission_before, admission),
         true <- ua_b_same_admission?(s.admission_after, admission) do
      true
    else
      _ -> false
    end
  end

  defp ua_b_same_admission?(a, original) do
    ua_admit_proc(a) and
      Map.drop(a, [:self_status, :native_status, :self_stat_state, :native_stat_state]) ==
        Map.drop(original, [:self_status, :native_status, :self_stat_state, :native_stat_state])
  end

  defp ua_b_stat?({:ok, %{pid: pid, state: state, start_ticks: ticks}}, e, kind),
    do: pid == e.native_pid and ticks == e.start_ticks and
      if(kind == :live, do: ua_live_state?(state), else: ua_state?(state))
  defp ua_b_stat?(_, _, _), do: false

  defp ua_b_status?({:ok, %{pid: pid, tgid: pid, state: state, uids: uids,
                          nspid: [pid], nstgid: [pid]}}, expected_pid, expected_uids, kind),
    do: pid == expected_pid and uids == expected_uids and
      if(kind == :live, do: ua_live_state?(state), else: ua_state?(state))
  defp ua_b_status?(_, _, _, _), do: false

  defp ua_b_fresh_self?(f, e, a) do
    with true <- ua_b_keys?(f, [:kind, :system_pid, :readlink, :self_lstat, :directory,
           :numeric_directory, :directory_after, :status_fd, :status_path_before,
           :status_path_after, :status, :stat_state, :pid_namespace, :children_namespace,
           :mount_namespace, :proc_root, :mount, :cgroup, :fd_closed, :fresh,
           :startup_unchanged]),
         true <- f.kind == :fresh_self_only and f.system_pid == e.self_pid and f.readlink == e.self_pid,
         true <- f.self_lstat == a.self_lstat and f.directory == a.self_followed and
           f.numeric_directory == a.numeric_directory and f.directory_after == a.self_directory_after,
         true <- f.status_fd == a.status_fd and f.status_path_before == a.numeric_status_before and
           f.status_path_after == a.numeric_status_after,
         true <- ua_b_status?(f.status, e.self_pid, e.uids, :live) and ua_live_state?(f.stat_state),
         true <- f.pid_namespace == a.pid_namespace and f.children_namespace == a.children_pid_namespace and
           f.mount_namespace == a.mount_namespace and f.proc_root == a.proc_root and f.mount == a.mount,
         true <- f.cgroup == e.cgroup and f.fd_closed == true and f.fresh == true and
           f.startup_unchanged == true do
      true
    else
      _ -> false
    end
  end

  defp ua_b_native_boundary(b, e, o, deadline) do
    with true <- ua_b_keys?(b, [:command_kill, :await_entry, :await_exception, :unlock, :entry, :held]),
         {kill_at, command, :kill} <- b.command_kill,
         {await_at, owner, handle, timeout} <- b.await_entry,
         {exception_at, :exit, {:killed, {ExCmd.Process, :await_exit, [^handle, ^timeout]}}} <- b.await_exception,
         {unlock_at, observer, connection, key, [[true]]} <- b.unlock,
         {entry_at, ^owner, caller, database, nonce} <- b.entry,
         true <- command == e.command and owner == e.owner and handle == e.handle and
           observer == e.observer and connection == e.observer_connection and key == e.gate_key and
           caller == e.caller and database == e.database and nonce == e.nonce and b.held == true,
         true <- is_integer(timeout) and timeout > 0 and timeout <= 5000,
         true <- ua_b_increasing?([o.bound_at, kill_at, await_at, exception_at, unlock_at, deadline]),
         true <- ua_b_increasing?([exception_at, entry_at, deadline]) do
      {:ok, %{kill: kill_at, await: await_at, exception: exception_at, unlock: unlock_at,
              entry: entry_at, timeout: timeout}}
    else
      _ -> :error
    end
  end

  defp ua_b_port_gone?([{ref, :port, port, _reason, at}], info_at, o, after_at, deadline),
    do: ref == o.port_ref and port == o.port and
      ua_b_increasing?([after_at, at, info_at, deadline])
  defp ua_b_port_gone?(_, _, _, _, _), do: false

  defp ua_b_observations(observations, e, a, after_at, deadline)
       when is_list(observations) and length(observations) > 0 do
    Enum.reduce_while(observations, {:ok, :present, after_at, -1}, fn observation, {:ok, _, prior_at, prior_serial} ->
      case ua_b_observation(observation, e, a, prior_at, prior_serial, deadline) do
        {:ok, _, _, _} = next -> {:cont, next}
        :error -> {:halt, :error}
      end
    end)
  end
  defp ua_b_observations(_, _, _, _, _), do: :error

  defp ua_b_observation(f, e, a, prior_at, prior_serial, deadline) do
    with true <- ua_b_keys?(f, [:kind, :at, :before, :after, :reads, :read_serials, :native_status_reads]),
         true <- ua_b_increasing?([prior_at, f.at, deadline]),
         [s1, s2, s3] <- f.read_serials,
         true <- ua_b_increasing?([s1, s2, s3]) and s1 > prior_serial,
         true <- ua_b_fresh_self?(f.before, e, a) and ua_b_fresh_self?(f.after, e, a),
         {:ok, kind} <- ua_b_native_reads(f.kind, f.reads, f.native_status_reads, e) do
      {:ok, kind, f.at, s3}
    else
      _ -> :error
    end
  end

  defp ua_b_native_reads(:absent, reads, [], e) do
    directory = "/proc/" <> e.native_pid
    if reads == [{:lstat, directory, {:error, :enoent}},
                 {:stat_path, directory <> "/stat", {:error, :enoent}},
                 {:lstat, directory, {:error, :enoent}}],
      do: {:ok, :absent}, else: :error
  end
  defp ua_b_native_reads(:present,
         [{:lstat, path, {:ok, directory}}, {:stat, stat}, {:status, status},
          {:cgroup, cgroup}, {:exe, exe}], status_reads, e) do
    with true <- path == "/proc/" <> e.native_pid and directory == e.directory,
         true <- status_reads == [path <> "/status"],
         true <- ua_b_stat?(stat, e, :present) and ua_b_status?(status, e.native_pid, e.uids, :present),
         true <- cgroup == e.cgroup,
         {:ok, %{state: state}} <- stat,
         {:ok, %{state: status_state}} <- status,
         true <- (ua_live_state?(state) and ua_live_state?(status_state)) or
           (state in ["Z", "X"] and state == status_state),
         true <- exe == {:ok, e.exe} or (state in ["Z", "X"] and exe == {:error, :enoent}) do
      {:ok, :present}
    else
      _ -> :error
    end
  end
  defp ua_b_native_reads(_, _, _, _), do: :error

  defp ua_b_protocol_expected?(e) do
    with true <- ua_b_keys?(e, [:private_key, :run, :owner, :caller, :observer,
           :observer_connection, :nonce, :database, :oid, :handle, :timeout, :repos,
           :maintenance, :context, :roots, :ancestors, :original_monitors,
           :backend_baseline, :pool_counts, :observer_backend, :child_backend,
           :tag, :deadline, :captured_before_allocation]),
         true <- Enum.all?([e.private_key, e.run, e.owner, e.caller, e.observer,
           e.observer_connection, e.nonce, e.maintenance], &ua_b_identity?/1),
         true <- e.owner != e.caller and e.observer != e.owner,
         true <- is_binary(e.database) and e.database != "" and ua_token?(e.tag),
         true <- is_integer(e.oid) and e.oid > 0,
         true <- is_integer(e.timeout) and e.timeout > 0 and e.timeout <= 5000,
         true <- ua_b_time?(e.deadline) and e.deadline > 0 and e.captured_before_allocation == true,
         true <- ua_b_repos?(e.repos),
         true <- ua_b_keys?(e.context, [:caller, :report_cleanup]),
         true <- e.context.caller == e.caller and ua_b_identity?(e.context.report_cleanup),
         true <- ua_b_roots?(e.roots, e.ancestors),
         true <- is_integer(e.observer_backend) and e.observer_backend > 0 and
           is_integer(e.child_backend) and e.child_backend > 0 and e.child_backend != e.observer_backend,
         true <- ua_b_baseline?(e.backend_baseline, e.pool_counts, e.observer_backend, e.child_backend),
         true <- ua_b_proper_list?(e.original_monitors) and length(e.original_monitors) == 13,
         true <- Enum.all?(e.original_monitors, fn
           {id, ref} -> ua_b_identity?(id) and ua_b_identity?(ref)
           _ -> false
         end),
         true <- length(Enum.uniq(Enum.map(e.original_monitors, &elem(&1, 0)))) == 13 and
           length(Enum.uniq(Enum.map(e.original_monitors, &elem(&1, 1)))) == 13 do
      true
    else
      _ -> false
    end
  end

  defp ua_b_repos?(repos) do
    ua_b_keys?(repos, [Singularity.Storage.MigrationRepo, Singularity.Storage.RequestRepo,
      Singularity.Storage.PreAuthRepo, Singularity.Storage.DispatcherRepo, Singularity.Storage.WorkerRepo]) and
      Enum.all?(Map.values(repos), &ua_b_identity?/1) and length(Enum.uniq(Map.values(repos))) == 5
  end

  defp ua_b_baseline?(rows, counts, observer, child)
       when is_list(rows) and length(rows) > 0 and is_map(counts) and map_size(counts) == 5 do
    Enum.all?(counts, fn {name, count} ->
      is_binary(name) and name != "" and is_integer(count) and count > 0
    end) and
      Enum.all?(rows, fn
        [pid, name, "client backend"] ->
          is_integer(pid) and pid > 0 and pid != observer and pid != child and Map.has_key?(counts, name)
        _ -> false
      end) and
      rows == Enum.sort(rows) and
      length(Enum.uniq(Enum.map(rows, &hd/1))) == length(rows) and
      Enum.frequencies(Enum.map(rows, &Enum.at(&1, 1))) == counts
  end
  defp ua_b_baseline?(_, _, _, _), do: false

  defp ua_b_roots?(roots, ancestors) do
    with true <- ua_b_keys?(roots, [:allocation, :objects, :historical_build]),
         {allocation, allocation_object} <- roots.allocation,
         {objects, objects_object} <- roots.objects,
         {build, build_object} <- roots.historical_build,
         true <- Enum.all?([allocation, objects, build], &ua_b_path?/1),
         true <- objects == allocation <> "/objects" and build == allocation <> "/historical-build",
         true <- Enum.all?([allocation_object, objects_object, build_object], &ua_object?(&1, :directory)),
         true <- length(Enum.uniq([allocation_object, objects_object, build_object])) == 3,
         true <- ua_b_proper_list?(ancestors) and ancestors != [],
         true <- Enum.all?(ancestors, fn
           {path, object} -> ua_b_path?(path) and ua_object?(object, :directory) and
             ua_starts?(allocation, path <> "/")
           _ -> false
         end),
         true <- length(Enum.uniq(ancestors)) == length(ancestors) do
      true
    else
      _ -> false
    end
  end

  defp ua_b_preconditions?(p, e, o) do
    ua_b_keys?(p, [:clean_control_qualified, :original_context, :context, :nonce_fresh,
      :one_selective_receive, :receive_bound, :original_timers_unchanged,
      :foreign_continuations_accepted, :handle, :reader_blocked, :writer_completed_waiting,
      :primary_nil, :execution_deadline_live, :no_replacement, :on_exit, :command_kills,
      :extra_signals, :infrastructure_acquired]) and
      Enum.all?([:clean_control_qualified, :original_context, :nonce_fresh, :one_selective_receive,
        :original_timers_unchanged, :reader_blocked, :writer_completed_waiting, :primary_nil,
        :execution_deadline_live, :no_replacement], &(Map.fetch!(p, &1) == true)) and
      p.context == e.context and p.handle == e.handle and p.handle == o.handle and
      p.receive_bound == :remaining_original_absolute_deadline and p.foreign_continuations_accepted == 0 and
      p.on_exit == nil and p.command_kills == [o.command] and p.extra_signals == [] and
      p.infrastructure_acquired == false
  end

  # Retained context is audited on every path. Only a claimed sampled event
  # requires successful absence; a conforming abort may preserve unknown evidence.
  defp ua_b_measurement?(m, e, mode) do
    with true <- ua_b_keys?(m, [:native, :tagged_rows, :baselines, :sample_times,
           :repos_before, :repos_after, :owner_live, :maintenance_live, :held, :oid,
           :root_object_workspace_unchanged, :privacy_so_far, :queries_bounded, :brackets]),
         n = m.native,
         true <- ua_b_keys?(n, [:expected, :original, :boundary, :observations, :port_down,
           :port_info, :port_info_at, :deadline, :sticky_invalid, :replacement_seen, :unknown]),
         true <- ua_b_native_expected?(n.expected) and ua_b_original?(n.original, n.expected),
         true <- Enum.all?([:run, :owner, :caller, :observer, :observer_connection,
           :nonce, :database, :handle], &(Map.fetch!(e, &1) == Map.fetch!(n.expected, &1))),
         true <- n.deadline == e.deadline,
         {:ok, times} <- ua_b_native_boundary(n.boundary, n.expected, n.original, n.deadline),
         true <- times.timeout == e.timeout,
         true <- Enum.all?([n.sticky_invalid, n.replacement_seen, n.unknown], &is_boolean/1),
         true <- ua_b_proper_list?(n.observations) and ua_b_proper_list?(n.port_down),
         true <- Enum.all?(n.port_down, fn
           {ref, :port, port, _reason, at} ->
             ref == n.original.port_ref and port == n.original.port and
               ua_b_increasing?([times.exception, at, e.deadline])
           _ -> false
         end) and length(n.port_down) <= 1,
         true <- n.port_info == nil or n.port_info == :unknown or
           n.port_info == {:connected, n.original.command},
         true <- n.port_info_at == nil or ua_b_time?(n.port_info_at),
         true <- ua_b_native_history?(n, max(times.unlock, times.entry)) do
      if mode == :sampled do
        ua_b_sampled_measurement?(m, e)
      else
        # These payload fields confer no observation credit without their event.
        ua_b_proper_list?(m.tagged_rows) and ua_b_proper_list?(m.baselines) and ua_b_proper_list?(m.sample_times) and
          ua_b_proper_list?(m.brackets) and m.oid == e.oid and
          m.repos_before == e.repos and m.repos_after == e.repos and
          Enum.all?([m.owner_live, m.maintenance_live, m.held,
            m.root_object_workspace_unchanged, m.privacy_so_far, m.queries_bounded], &is_boolean/1)
      end
    else
      _ -> false
    end
  end

  defp ua_b_native_history?(%{observations: []}, _after_at), do: true
  defp ua_b_native_history?(n, after_at) do
    case ua_b_observations(n.observations, n.expected, n.original.admission, after_at, n.deadline) do
      {:ok, _, _, _} -> true
      :error ->
        (n.sticky_invalid or n.replacement_seen or n.unknown) and
          Enum.all?(n.observations, fn observation ->
            ua_b_keys?(observation, [:kind, :at, :before, :after, :reads,
              :read_serials, :native_status_reads]) and
              observation.kind in [:unknown, :present, :absent] and ua_b_time?(observation.at) and
              is_map(observation.before) and is_map(observation.after) and
              ua_b_proper_list?(observation.reads) and ua_b_proper_list?(observation.native_status_reads) and
              match?([_, _, _], observation.read_serials) and ua_b_increasing?(observation.read_serials)
          end)
    end
  end

  defp ua_b_sampled_measurement?(m, e) do
    with true <- ua_b_keys?(m, [:native, :tagged_rows, :baselines, :sample_times,
           :repos_before, :repos_after, :owner_live, :maintenance_live, :held, :oid,
           :root_object_workspace_unchanged, :privacy_so_far, :queries_bounded, :brackets]),
         true <- ua_original_gone?(m.native),
         true <- Enum.all?([:run, :owner, :caller, :observer, :observer_connection,
           :nonce, :database, :handle], &(Map.fetch!(e, &1) == Map.fetch!(m.native.expected, &1))),
         true <- m.native.deadline == e.deadline,
         true <- m.native.boundary.await_entry == {elem(m.native.boundary.await_entry, 0), e.owner, e.handle, e.timeout},
         true <- m.tagged_rows == [] and m.baselines == [e.backend_baseline, e.backend_baseline],
         true <- m.repos_before == e.repos and m.repos_after == e.repos and m.oid == e.oid,
         true <- Enum.all?([:owner_live, :maintenance_live, :held, :root_object_workspace_unchanged,
           :privacy_so_far, :queries_bounded], &(Map.fetch!(m, &1) == true)),
         [first_at, second_at] <- m.sample_times,
         [first, second] <- m.brackets,
         true <- ua_b_increasing?([List.last(m.native.observations).at, first_at, second_at, e.deadline]),
         true <- ua_b_sql_bracket?(first, first_at, e, m.native),
         true <- ua_b_sql_bracket?(second, second_at, e, m.native) do
      true
    else
      _ -> false
    end
  end

  defp ua_b_sql_bracket?(b, at, e, n) do
    ua_b_keys?(b, [:at, :repos_before, :repos_after, :maintenance, :owner,
      :registered_equal, :all_live, :oid, :self_before, :self_after]) and
      b.at == at and b.repos_before == e.repos and b.repos_after == e.repos and
      b.maintenance == e.maintenance and b.owner == e.owner and b.oid == e.oid and
      b.registered_equal == true and b.all_live == true and
      ua_b_fresh_self?(b.self_before, n.expected, n.original.admission) and
      ua_b_fresh_self?(b.self_after, n.expected, n.original.admission)
  end

  defp ua_b_helper?(h) do
    quarantine = [{:legacy_preparation_quarantined, :unconfirmed}]
    ua_b_keys?(h, [:primary, :await, :cleanup, :secondary, :preparation_error,
      :sql_absent, :child_absent, :closed, :workspace_removed, :ready,
      :before_database_drop, :normal_owner_cleanup, :after_hygiene, :reporter_calls]) and
      h.primary == :legacy_pipe and h.await == :unconfirmed and h.cleanup == :unconfirmed and
      h.secondary == quarantine and h.preparation_error == {:legacy_pipe, quarantine} and
      h.after_hygiene == :unconfirmed and h.reporter_calls == 1 and
      Enum.all?([:sql_absent, :child_absent, :closed, :workspace_removed, :ready,
        :before_database_drop, :normal_owner_cleanup], &(Map.fetch!(h, &1) == false))
  end

  defp ua_b_terminal?(t) do
    ua_b_keys?(t, [:owner, :actor, :before_arm_on_exit]) and
      t.owner == {:fixture_cleanup_failed, [{:legacy_preparation_quarantined, :unconfirmed}]} and
      t.actor == :normal and t.before_arm_on_exit == nil
  end

  defp ua_b_restoration?(r) do
    ua_b_keys?(r, [:event_fence, :trace_fence, :late_message_drain, :stdout, :stderr,
      :logger, :exception_messages, :inspect_canary, :telemetry_registered_positive,
      :own_telemetry_detached, :entire_telemetry_baseline, :own_trace_sessions_closed,
      :traced, :match_spec, :meta, :meta_match_spec, :process_flags, :tracer, :config,
      :compiler, :environment, :repository, :no_content_in_diagnostics,
      :original_failures_retained, :original_observer_demonitor_only]) and
      Enum.all?(Map.values(r), &(&1 == true))
  end

  defp ua_b_retention?(r, e) do
    ua_b_keys?(r, [:database_name_oid, :allocation, :objects, :workspace,
      :nonlink_identities, :safe_ancestors, :empty_inventories, :quarantine_recorded,
      :no_automatic_drop, :no_original_removal, :roots, :ancestors, :inventories]) and
      Enum.all?([:database_name_oid, :allocation, :objects, :workspace, :nonlink_identities,
        :safe_ancestors, :empty_inventories, :quarantine_recorded, :no_automatic_drop,
        :no_original_removal], &(Map.fetch!(r, &1) == true)) and
      r.roots == e.roots and r.ancestors == e.ancestors and ua_b_inventories?(r.inventories)
  end

  defp ua_b_inventories?(%{allocation: ["historical-build", "objects"], objects: [],
                         historical_build: []} = inventories),
    do: map_size(inventories) == 3
  defp ua_b_inventories?(_), do: false

  defp ua_b_events(events, deadline) when is_list(events) and length(events) > 0 do
    Enum.reduce_while(events, {:ok, %{}}, fn
      {at, kind, payload}, {:ok, acc} when is_atom(kind) ->
        if ua_b_time?(at) and at > 0 and at < deadline and not Map.has_key?(acc, kind),
          do: {:cont, {:ok, Map.put(acc, kind, {at, payload})}}, else: {:halt, :error}
      _, _ -> {:halt, :error}
    end)
  end
  defp ua_b_events(_, _), do: :error

  defp ua_b_event?(events, kind, payload) do
    case Map.get(events, kind) do
      {_, ^payload} -> true
      _ -> false
    end
  end

  defp ua_b_event_at(events, kind), do: elem(Map.fetch!(events, kind), 0)

  defp ua_b_common_events?(v, caught, e, m) do
    required = [:command_kill, :primary, :await_entry, :await_exception, :caught,
      :unlock, :rethrow, :mte_teardown, :owner_down, :actor_down,
      :observer_connection_down, :fences, :privacy, :restoration, :retention]
    with true <- Enum.all?(required, &Map.has_key?(v, &1)),
         {class, _value, stack} <- caught,
         true <- class in [:throw, :exit, :error] and ua_b_proper_list?(stack) and stack != [],
         true <- ua_b_event?(v, :command_kill, {m.native.original.command, :kill, 1}),
         true <- ua_b_event?(v, :primary, {e.owner, e.run, :legacy_pipe}),
         true <- ua_b_event?(v, :await_entry, {e.owner, e.handle, e.timeout}),
         true <- ua_b_event?(v, :await_exception, {e.owner, :exit,
           {:killed, {ExCmd.Process, :await_exit, [e.handle, e.timeout]}}}),
         true <- ua_b_event?(v, :caught, caught) and ua_b_event?(v, :rethrow, caught),
         true <- ua_b_event?(v, :unlock, {e.observer, e.observer_connection, @transport_lock, [[true]]}),
         true <- ua_b_event?(v, :mte_teardown, {e.owner, :original_six}),
         true <- ua_b_terminal_event?(v, :owner_down, e.owner, e.original_monitors,
           {:fixture_cleanup_failed, [{:legacy_preparation_quarantined, :unconfirmed}]}),
         true <- ua_b_terminal_event?(v, :actor_down, e.caller, e.original_monitors, :normal),
         true <- ua_b_terminal_event?(v, :observer_connection_down, e.observer_connection, e.original_monitors, :normal),
         true <- ua_b_event?(v, :fences, :complete) and ua_b_event?(v, :privacy, :complete) and
           ua_b_event?(v, :restoration, :complete) and ua_b_event?(v, :retention, :original_quarantine),
         true <- ua_b_increasing?(Enum.map([:command_kill, :primary, :await_entry,
           :await_exception, :caught, :rethrow, :mte_teardown, :owner_down, :actor_down,
           :observer_connection_down, :fences, :privacy, :restoration, :retention],
           &ua_b_event_at(v, &1))),
         b = m.native.boundary,
         true <- elem(b.command_kill, 0) == ua_b_event_at(v, :command_kill) and
           elem(b.await_entry, 0) == ua_b_event_at(v, :await_entry) and
           elem(b.await_exception, 0) == ua_b_event_at(v, :await_exception) and
           elem(b.unlock, 0) == ua_b_event_at(v, :unlock),
         true <- ua_b_increasing?([ua_b_event_at(v, :await_exception),
           ua_b_event_at(v, :unlock), ua_b_event_at(v, :rethrow)]) do
      true
    else
      _ -> false
    end
  end

  defp ua_b_terminal_event?(v, kind, id, monitors, reason) do
    case Map.get(v, kind) do
      {_, {ref, ^id, ^reason}} -> {id, ref} in monitors
      _ -> false
    end
  end

  defp ua_b_mailbox?(arrival) when is_list(arrival) and length(arrival) >= 0 do
    Enum.sort(arrival) == Enum.sort([:boundary_entry, :await_exception, :await_entry, :primary])
  end
  defp ua_b_mailbox?(_), do: false

  defp ua_b_gate?(g, e, n, events) do
    with true <- ua_b_keys?(g, [:key, :oid, :connection, :acquisitions, :query_bound_ms,
           :observer_identity, :waits, :locks, :samples, :unlock_results]),
         true <- g.key == @transport_lock and g.key == n.expected.gate_key and
           g.oid == e.oid and g.connection == e.observer_connection and g.acquisitions == 1,
         true <- is_integer(g.query_bound_ms) and g.query_bound_ms > 0 and g.query_bound_ms <= 1000,
         true <- g.observer_identity == [[e.observer_backend, "singularity_migration", e.database]],
         true <- ua_b_waits_locks?(g.waits, g.locks, e),
         true <- g.unlock_results == [[[true]]],
         [first, second] <- g.samples,
         true <- ua_b_gate_sample?(first, e, n) and ua_b_gate_sample?(second, e, n),
         true <- ua_b_increasing?([n.original.bound_at, first.at, second.at,
           ua_b_event_at(events, :command_kill)]) do
      true
    else
      _ -> false
    end
  end

  defp ua_b_waits_locks?(waits, locks, e) do
    [class, object] = @transport_lock
    waits == [[e.child_backend, "Lock", "advisory", [e.observer_backend]]] and
      locks == Enum.sort([
        [e.observer_backend, true, "ExclusiveLock", class, object, 2],
        [e.child_backend, false, "ExclusiveLock", class, object, 2]])
  end

  defp ua_b_gate_sample?(s, e, n) do
    ua_b_keys?(s, [:at, :repos, :maintenance, :owner, :all_live, :native_two_live,
      :port_live, :connection, :oid, :waits, :locks]) and
      s.repos == e.repos and s.maintenance == e.maintenance and s.owner == e.owner and
      s.all_live == true and s.native_two_live == n.original and s.port_live == n.original.port and
      s.connection == e.observer_connection and s.oid == e.oid and
      ua_b_waits_locks?(s.waits, s.locks, e)
  end

  defp ua_b_joins(joins, e, n, events) when is_list(joins) and length(joins) >= 0 do
    original_ids = [n.original.reader, n.original.writer, n.original.command, n.original.port] ++
      Map.values(e.repos) ++ [e.maintenance, e.owner, e.caller, e.observer_connection]
    with true <- Enum.sort(Enum.map(e.original_monitors, &elem(&1, 0))) == Enum.sort(original_ids),
         true <- length(joins) == 13,
         true <- Enum.all?(joins, fn
           {id, ref, :bounded, _result} -> {id, ref} in e.original_monitors
           _ -> false
         end),
         true <- length(Enum.uniq(Enum.map(joins, &elem(&1, 0)))) == 13 do
      Enum.reduce_while(joins, {:ok, []}, fn
        {id, _, :bounded, {:down, at}}, {:ok, failures} ->
          if ua_b_join_down?(id, at, e, n, events),
            do: {:cont, {:ok, failures}}, else: {:halt, :error}
        {id, _, :bounded, {:error, reason}}, {:ok, failures} when is_atom(reason) and reason != nil ->
          {:cont, {:ok, failures ++ [{:join, id, reason}]}}
        _, _ -> {:halt, :error}
      end)
    else
      _ -> :error
    end
  end
  defp ua_b_joins(_, _, _, _), do: :error

  defp ua_b_join_down?(id, at, e, n, v) do
    ua_b_time?(at) and at < ua_b_event_at(v, :fences) and
      cond do
        id == n.original.command ->
          ua_b_event_at(v, :command_kill) < at and at <= ua_b_event_at(v, :await_entry)
        id in [n.original.reader, n.original.writer] ->
          before_at = if Map.has_key?(v, :boundary_entry),
            do: ua_b_event_at(v, :boundary_entry), else: ua_b_event_at(v, :rethrow)
          at < before_at
        id == n.original.port ->
          Enum.any?(n.port_down, fn {_, :port, port, _, down_at} -> port == id and at == down_at end)
        id in Map.values(e.repos) or id == e.maintenance ->
          ua_b_event_at(v, :mte_teardown) < at and at < ua_b_event_at(v, :owner_down)
        id == e.owner -> at == ua_b_event_at(v, :owner_down)
        id == e.caller -> at == ua_b_event_at(v, :actor_down)
        id == e.observer_connection -> at == ua_b_event_at(v, :observer_connection_down)
        true -> false
      end
  end

  defp ua_b_protocol_outcome?(f, v, join_failures) do
    base = [:command_kill, :primary, :await_entry, :await_exception, :caught, :unlock,
      :rethrow, :mte_teardown, :owner_down, :actor_down, :observer_connection_down,
      :fences, :privacy, :restoration, :retention]
    e = f.expected
    eligible = case f.caught do
      {:throw, {:legacy_preparation_failed, :legacy_pipe}, _stack} -> true
      _ -> false
    end

    cond do
      f.mode == :unknown_catch ->
        not eligible and ua_b_keys?(v, base) and
          f.credits == %{sample: false, recovery: false, hygiene: false} and
          f.hygiene == :forbidden and
          f.failures == [{:catch, :ineligible} | join_failures]

      f.mode == :sampled ->
        eligible and ua_b_keys?(v, base ++ [:boundary_entry, :measurement, :continuation, :boundary_exit, :hygiene]) and
          f.credits == %{sample: true, recovery: true, hygiene: true} and
          f.failures == [] and join_failures == [] and ua_b_boundary_entry?(v, e, f.measurement.native) and
          ua_b_event?(v, :measurement, {e.private_key, e.owner, e.nonce, :held}) and
          ua_b_event_at(v, :measurement) == List.last(f.measurement.native.observations).at and
          ua_b_event?(v, :continuation, {e.private_key, e.observer, e.owner, e.nonce, :sampled}) and
          ua_b_event?(v, :boundary_exit, {e.owner, e.nonce, :sampled}) and
          ua_b_event?(v, :hygiene, :independent) and
          ua_b_increasing?([ua_b_event_at(v, :measurement), List.last(f.measurement.sample_times),
            ua_b_event_at(v, :continuation), ua_b_event_at(v, :boundary_exit), ua_b_event_at(v, :rethrow)]) and
          ua_b_hygiene?(f.hygiene, e, f.measurement.native, v)

      f.mode in [:abort, :timeout, :observer_down, :observation_error, :failed_release] ->
        exit_reason = case f.mode do
          :observation_error -> :error
          :failed_release -> :timeout
          reason -> reason
        end
        release = if f.mode == :failed_release, do: {:error, :failed_release}, else: :attempted
        eligible and ua_b_keys?(v, base ++ [:boundary_entry, :continuation, :boundary_exit]) and
          f.credits == %{sample: false, recovery: false, hygiene: false} and f.hygiene == :forbidden and
          f.failures == [{:observation, f.mode} | join_failures] and
          ua_b_boundary_entry?(v, e, f.measurement.native) and
          ua_b_event?(v, :continuation, {:abort_attempt, e.observer, e.owner, e.nonce, :bounded, release}) and
          ua_b_event?(v, :boundary_exit, {e.owner, e.nonce, exit_reason}) and
          ua_b_increasing?([ua_b_event_at(v, :boundary_entry), ua_b_event_at(v, :continuation),
            ua_b_event_at(v, :boundary_exit), ua_b_event_at(v, :rethrow)])

      true -> false
    end
  end

  defp ua_b_boundary_entry?(v, e, n) do
    ua_b_event?(v, :boundary_entry, {e.private_key, e.owner, e.caller, e.database, e.nonce}) and
      ua_b_event_at(v, :boundary_entry) == elem(n.boundary.entry, 0) and
      ua_b_increasing?([ua_b_event_at(v, :caught), ua_b_event_at(v, :boundary_entry),
        ua_b_event_at(v, :unlock), ua_b_event_at(v, :rethrow)])
  end

  defp ua_b_hygiene?(h, e, held, v) do
    with true <- ua_b_keys?(h, [:independent_authority, :connection, :role,
           :maintenance_database, :database, :oid, :session_scope, :all_a_rows,
           :native, :native_fresh, :roots, :ancestors, :inventories, :fresh_identities,
           :empty_inventories, :repeated_safe_ancestors, :drop, :termination,
           :database_absent, :removal, :removal_order, :each_fresh_enoent, :connection_down]),
         true <- Enum.all?([:independent_authority, :native_fresh, :fresh_identities,
           :empty_inventories, :repeated_safe_ancestors, :database_absent,
           :each_fresh_enoent, :connection_down], &(Map.fetch!(h, &1) == true)),
         true <- ua_b_identity?(h.connection) and h.connection not in [e.observer, e.observer_connection],
         true <- h.role == :singularity_migration and h.maintenance_database == "postgres" and
           h.database == e.database and h.oid == e.oid and h.session_scope == :all_a and h.all_a_rows == [],
         true <- h.roots == e.roots and h.ancestors == e.ancestors and ua_b_inventories?(h.inventories),
         true <- h.drop == :ordinary_exact_quoted and h.termination == :none and
           h.removal == :identity_confirmed_empty_rmdir and
           h.removal_order == [:historical_build, :objects, :allocation],
         true <- ua_b_hygiene_native?(h.native, held, ua_b_event_at(v, :retention),
           ua_b_event_at(v, :hygiene)) do
      true
    else
      _ -> false
    end
  end

  defp ua_b_hygiene_native?(n, held, after_at, before_at) do
    with true <- ua_b_keys?(n, [:scope, :expected, :original, :observations, :port_down,
           :port_info, :port_info_at, :deadline, :sticky_invalid, :replacement_seen, :unknown]),
         true <- n.scope == :independent_hygiene_after_original_closure,
         true <- n.expected == held.expected and n.original == held.original and n.deadline == held.deadline,
         true <- n.sticky_invalid == false and n.replacement_seen == false and n.unknown == false,
         true <- held.sticky_invalid == false and held.replacement_seen == false and held.unknown == false,
         true <- n.port_down == held.port_down and n.port_info == nil,
         true <- ua_b_port_gone?(n.port_down, n.port_info_at, n.original,
           elem(held.boundary.await_exception, 0), n.deadline),
         true <- ua_b_increasing?([after_at, n.port_info_at, before_at, n.deadline]),
         {:ok, :absent, _at, _last_serial} <- ua_b_observations(n.observations, n.expected,
           n.original.admission, after_at, before_at),
         true <- hd(hd(n.observations).read_serials) > List.last(List.last(held.observations).read_serials) do
      true
    else
      _ -> false
    end
  end
  # TASK18_UA_PURE_B_CONTRACT_END

  test "actual clean transport retains original native and Port custody through natural cleanup" do
    assert ua_actual_clean_control?() == true
  end

  defp ua_actual_clean_control? do
    transport_entrypoint!()
    transport_require!(Process.get({__MODULE__, :ua_control}) == nil)
    epoch = System.monotonic_time()
    before = transport_cleanup_baseline(System.monotonic_time(:millisecond) + 5_000)
    environment = System.get_env()
    Process.put({__MODULE__, :ua_control}, %{epoch: epoch, key: nil, fds: [], admitted: false,
      finished: false, session: nil, port_monitor: nil, failed: false,
      diagnostic_phase: :seed, diagnostic: nil})
    ua_pe_token = ua_pe_bridge_begin(); try do
    result = try do
      self_pid = System.pid()
      transport_require!(ua_uint?(self_pid, 4_294_967_295, true))
      transport_require!(:erlang.system_info(:system_architecture) |> to_string() |> String.starts_with?("x86_64"))
      transport_require!(:erlang.system_info(:endian) == :little)
      transport_require!(System.otp_release() == "28")
      self_root = "/proc/" <> self_pid
      root = ua_control_open!("/proc", :directory)
      own = ua_control_open!(self_root, :directory)
      ua_control_update(%{self_pid: self_pid, self_root: self_root, proc_fd: root, self_fd: own})
      seed = ua_control_self!(nil)
      ua_control_update(%{diagnostic_phase: :sources})
      sources = ua_control_sources!()
      ua_control_update(%{seed: seed, sources: sources})
      ua_control_update(%{diagnostic_phase: :transport})
      proof = transport_observation(:clean_frame)
      control = Process.get({__MODULE__, :ua_control})
      ua_control_update(%{diagnostic_phase: :restore})
      restored = transport_cleanup_baseline(System.monotonic_time(:millisecond) + 5_000)
      accepted = ua_control_diagnostic_predicate(proof.outcome == {:ok, true}, __ENV__.line) and
        ua_control_diagnostic_predicate(proof.valid?, __ENV__.line) and
        ua_control_diagnostic_predicate(proof.private?, __ENV__.line) and
        ua_control_diagnostic_predicate(control.admitted, __ENV__.line) and
        ua_control_diagnostic_predicate(control.finished, __ENV__.line) and
        ua_control_diagnostic_predicate(not control.failed, __ENV__.line) and
        ua_control_diagnostic_predicate(control.session == nil, __ENV__.line) and
        ua_control_diagnostic_predicate(control.port_monitor == nil, __ENV__.line) and
        ua_control_diagnostic_predicate(ua_control_sources!() == sources, __ENV__.line) and
        ua_control_diagnostic_predicate(ua_control_self!(control.native_pid) == seed, __ENV__.line) and
        ua_control_diagnostic_predicate(restored == before, __ENV__.line) and
        ua_control_diagnostic_predicate(System.get_env() == environment, __ENV__.line)
      ua_control_update(%{diagnostic_phase: :close})
      closed = Enum.map(control.fds, fn fd -> :file.close(fd) end)
      ua_control_update(%{fds: []})
      value = accepted and ua_control_diagnostic_predicate(Enum.all?(closed, &(&1 == :ok)), __ENV__.line)
      {value, Process.get({__MODULE__, :ua_control}).diagnostic}
    rescue
      _ -> {false, ua_control_diagnostic(:error, __STACKTRACE__)}
    catch
      kind, _ -> {false, ua_control_diagnostic(kind, __STACKTRACE__)}
    after
      control = Process.delete({__MODULE__, :ua_control})
      if is_map(control) do
        try do
          if control.session, do: :trace.session_destroy(control.session)
        catch
          _, _ -> :ok
        after
          if control.port_monitor, do: Process.demonitor(control.port_monitor, [:flush])
          Enum.each(control.fds, fn fd ->
            try do
              :file.close(fd)
            catch
              _, _ -> :ok
            end
          end)
        end
      end; ua_pe_bridge_stage(control, ua_pe_token)
    end
    ua_pe_bridge_finish(result, ua_pe_token)
    case result do
      {true, _} -> true
      {false, %{phase: phase, kind: kind, line: line} = diagnostic}
          when phase in [:seed, :sources, :transport, :admit, :post_loop, :restore, :close] and
            kind in [:error, :throw, :exit, :predicate] and is_integer(line) ->
        raise RuntimeError, "UA_CONTROL_FAILURE phase=#{phase} kind=#{kind} line=#{line}" <>
          ua_control_seed_suffix(diagnostic)
    end; after ua_pe_bridge_clear(ua_pe_token) end
  end

  defp ua_control_diagnostic(kind, stack) when kind in [:error, :throw, :exit, :predicate] do
    control = Process.get({__MODULE__, :ua_control})
    case control.diagnostic do
      nil ->
        line = Enum.find_value(Enum.take(stack, 16), 0, fn
          {__MODULE__, function, _, metadata} when is_atom(function) and is_list(metadata) ->
            ua_control_diagnostic_line(function, Keyword.get(metadata, :line))
          _ -> nil
        end)
        site = %{phase: control.diagnostic_phase, kind: kind, line: line}
        site = Map.put(site, :seed_fields, Map.get(control, :seed_mismatch)) |> Map.put(:mount_delta, Map.get(control, :mount_delta))
        ua_control_update(%{diagnostic: site})
        site
      site -> site
    end
  end

  defp ua_control_diagnostic_predicate(value, line) do
    if value == false do
      control = Process.get({__MODULE__, :ua_control})
      if control.diagnostic == nil do
        site = %{phase: control.diagnostic_phase, kind: :predicate,
          line: ua_control_diagnostic_line(:ua_actual_clean_control?, line) || 0}
        ua_control_update(%{diagnostic: site})
      end
    end
    value
  end

