      :ua_control_gone -> [6065, 6066, 6067, 6068, 6069, 6070, 6071, 6072, 6073, 6075, 6076, 6077, 6078, 6079, 6080, 6082, 6083, 6085]
      :ua_control_open! -> [6092, 6093, 6094, 6095, 6096]
