  defp ua_control_update(fields) do
    Process.put({__MODULE__, :ua_control},
      Map.merge(Process.get({__MODULE__, :ua_control}), fields))
    :ok
  end

  defp ua_control_active?(key) do
    case Process.get({__MODULE__, :ua_control}) do
      %{key: ^key} -> true
      _ -> false
    end
  end

  defp ua_control_key(key) do
    case Process.get({__MODULE__, :ua_control}) do
      %{key: nil} -> ua_control_update(%{key: key})
      _ -> :ok
    end
  end

  defp ua_control_actor_gate(parent, key, true) do
    receive do
      {^key, :ua_control_allocate, ^parent} ->
        Process.put({key, :ua_control_enabled}, true)
        :ok
    after
      5_000 -> throw(:legacy_transport_observer)
    end
  end
  defp ua_control_actor_gate(_, _, false), do: :ok

  defp ua_control_allocated(key, actor) do
    if ua_control_active?(key) do
      ua_control_update(%{lexical: %{key: key, tag: @transport_tag, caller: actor,
        observer: self()}, allocated: System.monotonic_time()})
      send(actor, {key, :ua_control_allocate, self()})
    end
  end

  defp ua_control_baseline(key, expected, baseline, repos) do
    if ua_control_active?(key),
      do: ua_control_update(%{expected: expected, baseline: baseline, repos: repos})
  end

  defp ua_control_trace(key, owner, caller) do
    if ua_control_active?(key) do
      session = :trace.session_create(:task18_ua_original_receive, self(), [])
      ua_control_update(%{session: session, owner: owner,
        trace_before: ua_control_trace_snapshot()})
      pattern = [
        {[%{run: :"$1", handle: :"$2", reader: :"$3", writer: :"$4",
            deadline: :"$5", pending_observer: self(), caller: caller,
            primary: nil, receipt: nil, stdin_closed: false,
            workspace: :"$6", dependency_paths: :"$7"}],
         [{:is_reference, :"$1"}, {:is_map, :"$2"}, {:is_pid, :"$3"},
          {:is_pid, :"$4"}, {:is_integer, :"$5"}],
         [{:message, {{:ua_original_receive, :"$1", :"$2", :"$3", :"$4", :"$5", :"$6", :"$7"}}}]}
      ]
      transport_require!(:trace.function(session,
        {LegacyUpgradeRuntimeFixture, :transport_receive, 1}, pattern, [:local]) == 1)
      transport_require!(:trace.function(session, {ExCmd.Process, :start_link, 2},
        [{[:"$1", [{:cd, :"$2"}, {:env, :"$3"}, {:stderr, :redirect_to_stdout}, {:log, nil}]],
          [{:is_list, :"$1"}, {:"=<", {:length, :"$1"}, 68},
           {:is_binary, :"$2"}, {:is_list, :"$3"}, {:==, {:length, :"$3"}, 11}],
          [{:message, {{:ua_original_launch, :"$1", :"$2", :"$3"}}}]}], [:local]) == 1)
      transport_require!(:trace.process(session, owner, true,
        [:call, :arity, :monotonic_timestamp]) == 1)
    end
  end

  defp ua_control_hold_ready(state, workers, monitors, run, at) do
    if ua_control_active?(state.key) do
      transport_require!(!Map.has_key?(Process.get({__MODULE__, :ua_control}), :started))
      ua_control_update(%{started: %{owner: state.owner, caller: state.actor, run: run,
        workers: workers, monitors: monitors, at: at}})
      ua_control_admit()
      true
    else
      false
    end
  end

  defp ua_control_project(state, run, handle, reader, writer, deadline, workspace, paths, at) do
    transport_require!(ua_control_active?(state.key))
    control = Process.get({__MODULE__, :ua_control})
    transport_require!(!Map.has_key?(control, :projection))
    ua_control_update(%{projection: %{run: run, handle: handle, reader: reader,
      writer: writer, deadline: deadline, workspace: workspace, paths: paths, at: at}})
    ua_control_admit()
    state
  end

  defp ua_control_admit do
    control = Process.get({__MODULE__, :ua_control})
    if Map.has_key?(control, :projection) and Map.has_key?(control, :started) do
      %{projection: p, started: s, lexical: lexical} = control
      ua_control_update(%{diagnostic_phase: :admit})
      try do
        transport_require!(not control.admitted and not control.failed)
        transport_require!(is_list(p.paths) and length(p.paths) in 1..32 and
          Enum.all?(p.paths, &(is_binary(&1) and byte_size(&1) in 1..4096)) and
          is_binary(p.workspace) and byte_size(p.workspace) in 1..4096)
        launch = control.launch
        expected_argv = [@start_failure_elixir <> "/bin/elixir", "--erl", "+fnu"] ++
          Enum.flat_map(p.paths, &["-pa", &1]) ++
          [Path.join(@start_failure_root, "apps/singularity_runtime/test/fixtures/legacy_v0_1_0/runner.exs")]
        expected_env = Enum.map(
          ~w(ERL_AFLAGS ERL_FLAGS ERL_ZFLAGS ERL_LIBS ELIXIR_ERL_OPTIONS ELIXIR_CLI_DRY_RUN RUN_ERL_PIPE RUN_ERL_LOG BASH_ENV ENV),
          &{&1, ""}) ++ [{"SINGULARITY_TASK18_PROBE", "clean_frame"}]
        transport_require!(launch.argv == expected_argv and launch.cd == p.workspace and
          launch.env == expected_env and control.allocated < launch.at and launch.at < s.at)
        origins = control.origins
        transport_require!(origins.owner == s.owner and origins.caller == s.caller and
          origins.repos == control.repos and Process.alive?(origins.maintenance) and
          origins.at < launch.at and origins.database != "")
        transport_require!(p.run == s.run and s.caller == lexical.caller and
          lexical.observer == self() and lexical.key == control.key and lexical.tag == @transport_tag)
        transport_require!(control.epoch < control.allocated and control.allocated < s.at and s.at <= p.at)
        transport_require!(Enum.sort(Map.keys(p.handle)) ==
          Enum.sort([:__struct__, :owner, :pid, :monitor_ref, :exit_ref]))
        transport_require!(p.handle.__struct__ == ExCmd.Process and p.handle.owner == s.owner and
          [p.handle.pid, p.reader, p.writer] == s.workers and
          length(Enum.uniq(s.workers)) == 3 and Enum.all?(s.workers, &Process.alive?/1))
        transport_require!(is_reference(p.handle.monitor_ref) and is_reference(p.handle.exit_ref) and
          p.handle.monitor_ref != p.handle.exit_ref and map_size(s.monitors) == 3)
        remaining = ua_control_remaining!(p.deadline)
        transport_require!(remaining <= 45_000 and
          p.deadline - System.convert_time_unit(p.at, :native, :millisecond) in 1..45_000)
        {:ok, native} = GenServer.call(p.handle.pid, :os_pid, min(1_000, remaining))
        transport_require!(is_integer(native) and native > 0 and native <= 4_294_967_295)
        [port] = Enum.filter(Port.list(), fn port ->
          Port.info(port, :connected) == {:connected, p.handle.pid}
        end)
        {:os_pid, odu_pid} = Port.info(port, :os_pid)
        {:name, odu_name} = Port.info(port, :name)
        transport_require!(is_integer(odu_pid) and odu_pid > 0 and native != odu_pid and
          Integer.to_string(native) != control.self_pid and
          to_string(odu_name) == control.sources.odu_path)
        monitor = :erlang.monitor(:port, port)
        ua_control_update(%{port: port, port_monitor: monitor, port_down: nil,
          odu_pid: odu_pid, native_pid: Integer.to_string(native), deadline: p.deadline})
        dir = ua_control_open!("/proc/" <> Integer.to_string(native), :directory)
        ua_control_update(%{native_fd: dir})
        ua_control_wait_beam!(nil)
        first = ua_control_live!()
        second = ua_control_live!()
        transport_require!(first.identity == second.identity and first.at < second.at and
          ua_control_sources!() == control.sources)
        ua_control_port!()
        ua_control_remaining!(p.deadline)
        ua_control_update(%{admitted: true, live: [first, second]})
      rescue
        _ ->
          ua_control_diagnostic(:error, __STACKTRACE__)
          ua_control_update(%{failed: true})
      catch
        kind, _ ->
          ua_control_diagnostic(kind, __STACKTRACE__)
          ua_control_update(%{failed: true})
      after
        # Release only the genuine helper's original run; failure earns no custody credit.
        send(s.owner, {s.run, :observer_ready, self()})
        ua_control_update(%{diagnostic_phase: :transport})
      end
    end
  end

  defp ua_control_trace_snapshot do
    Map.new([{LegacyUpgradeRuntimeFixture, :transport_receive, 1}, {ExCmd.Process, :start_link, 2}],
      fn mfa -> {mfa, Enum.map([:traced, :match_spec, :meta, :meta_match_spec],
        &:erlang.trace_info(mfa, &1))} end)
  end

  defp ua_control_wait_beam!(previous) do
    c = Process.get({__MODULE__, :ua_control})
    ua_control_remaining!(c.deadline)
    base = "/proc/" <> c.native_pid
    directory = ua_control_object!(base, :directory, c.native_fd)
    {:ok, stat} = ua_parse_stat(ua_control_read!(base <> "/stat", 4096), c.native_pid)
    transport_require!(ua_live_state?(stat.state))
    identity = {directory, stat.start_ticks}
    transport_require!(previous == nil or previous == identity)
    ua_control_port!()
    if ua_control_link!(base <> "/exe", 4096) == c.sources.beam_path do
      :ok
    else
      receive do
      after
        min(1, ua_control_remaining!(c.deadline)) -> ua_control_wait_beam!(identity)
      end
    end
  end

  defp ua_control_remaining!(deadline) do
    remaining = deadline - System.monotonic_time(:millisecond)
    transport_require!(is_integer(deadline) and remaining > 0)
    remaining
  end

  defp ua_control_port! do
    c = Process.get({__MODULE__, :ua_control})
    transport_require!(Port.info(c.port, :connected) == {:connected, c.projection.handle.pid} and
      Port.info(c.port, :os_pid) == {:os_pid, c.odu_pid} and
      Port.info(c.port, :name) == {:name, String.to_charlist(c.sources.odu_path)} and
      Process.alive?(c.projection.handle.pid) and
      Enum.all?(c.started.workers, &Process.alive?/1))
  end

  defp ua_control_checkpoint(parent, key, true,
         {:repo_started, Singularity.Storage.MigrationRepo, :destination}, resources) do
    transport_require!(map_size(resources.repos) == 5)
    send(parent, {key, :ua_control_origins, resources.owner, resources.caller,
      resources.maintenance, resources.repos, resources.names.database, System.monotonic_time()})
  end
  defp ua_control_checkpoint(parent, key, true, :ready, resources) do
    send(parent, {key, :ua_control_ready, resources.owner, resources.caller,
      resources.maintenance, resources.repos, resources.names.database, System.monotonic_time()})
  end
  defp ua_control_checkpoint(_, _, _, _, _), do: :ok

  defp ua_control_after_loop(state) do
    if ua_control_active?(state.key) do
      ua_control_update(%{diagnostic_phase: :post_loop})
      try do
        c = Process.get({__MODULE__, :ua_control})
        transport_require!(c.admitted and not c.failed and is_map(c.ready))
        ready = c.ready
        transport_require!(Map.drop(ready, [:at]) == Map.drop(c.origins, [:at]) and
          hd(c.live).at < ready.at)
        deadline = min(c.deadline, System.convert_time_unit(ready.at, :native, :millisecond) + 5_000)
        transport_require!(ready.owner == state.owner and ready.caller == state.actor and
          ready.database == state.destination.database and ready.repos == c.repos and
          Process.alive?(ready.maintenance) and Process.alive?(state.owner) and Process.alive?(state.actor))
        transport_require!(Enum.all?(ready.repos, fn {repo, pid} ->
          Process.whereis(repo) == pid and Process.alive?(pid)
        end))
        state = ua_control_gone(state, deadline)
        Enum.each(1..2, fn _ ->
          transport_require!(ua_control_remaining!(deadline) > 1_000)
          rows = transport_backends(state.connection, state.destination.database, c.baseline)
          transport_require!(rows == c.baseline and Enum.frequencies_by(rows, &elem(&1, 1)) == c.expected)
        end)
        transport_require!(Process.alive?(ready.maintenance) and
          Enum.all?(ready.repos, fn {repo, pid} -> Process.whereis(repo) == pid and Process.alive?(pid) end))
        state = transport_absence_connection_close(state)
        state = transport_deadline_fence(%{state | deadline: min(state.deadline, deadline)},
          c.session, state.owner)
        transport_require!(:trace.session_destroy(c.session))
        transport_require!(ua_control_trace_snapshot() == c.trace_before)
        Process.demonitor(c.port_monitor, [:flush])
        ua_control_update(%{session: nil, port_monitor: nil, finished: true,
          finished_at: System.monotonic_time()})
        state
      rescue
        exception ->
          ua_control_diagnostic(:error, __STACKTRACE__)
          reraise exception, __STACKTRACE__
      catch
        kind, reason ->
          ua_control_diagnostic(kind, __STACKTRACE__)
          :erlang.raise(kind, reason, __STACKTRACE__)
      end
    else
      state
    end
  end

  defp ua_control_gone(state, deadline) do
    c = Process.get({__MODULE__, :ua_control})
    ua_control_remaining!(deadline)
    ua_control_self!(c.native_pid)
    base = "/proc/" <> c.native_pid
    gone = File.stat(base) == {:error, :enoent} and
      File.stat(base <> "/stat") == {:error, :enoent} and File.stat(base) == {:error, :enoent}
    if gone and c.port_down == :normal and Port.info(c.port) == nil do
      transport_require!(ua_control_sources!() == c.sources)
      state
    else
      unless gone do
        {:ok, stat} = ua_parse_stat(ua_control_read!(base <> "/stat", 4096), c.native_pid)
        transport_require!(stat.start_ticks == hd(c.live).start_ticks)
        transport_require!(ua_control_object!(base, :directory, c.native_fd) ==
          elem(hd(c.live).identity, 0))
        if ua_live_state?(stat.state), do: ua_control_live!()
      end
      receive do
        message -> ua_control_gone(transport_message(message, state), deadline)
      after
        min(10, ua_control_remaining!(deadline)) -> ua_control_gone(state, deadline)
      end
    end
  end

  # All raw resources remain in this controlling observer; no native descriptor is transferred.
  defp ua_control_open!(path, type) do
    modes = [:read, :raw, :binary] ++ if(type == :directory, do: [:directory], else: [])
    {:ok, fd} = :file.open(String.to_charlist(path), modes)
    c = Process.get({__MODULE__, :ua_control})
    ua_control_update(%{fds: [fd | c.fds]})
    fd
  end

  defp ua_control_fstat!(fd) do
    {:ok, record} = :file.read_file_info(fd, time: :posix)
    File.Stat.from_record(record)
  end

  defp ua_control_low(stat) do
    {stat.type, stat.major_device, stat.minor_device, stat.inode, stat.uid, stat.gid}
  end

  defp ua_control_raw!(path, limit) do
    {:ok, fd} = :file.open(String.to_charlist(path), [:read, :raw, :binary])
    try do
      before = ua_control_fstat!(fd)
      transport_require!(before.type == :regular)
      bytes = ua_control_bytes!(fd, limit, "")
      transport_require!(ua_control_low(ua_control_fstat!(fd)) == ua_control_low(before) and
        ua_control_low(File.stat!(path, time: :posix)) == ua_control_low(before))
      bytes
    after
      :ok = :file.close(fd)
    end
  end

  defp ua_control_bytes!(fd, limit, bytes) do
    case :file.read(fd, limit + 1 - byte_size(bytes)) do
      :eof -> bytes
      {:ok, chunk} when is_binary(chunk) and byte_size(chunk) > 0 ->
        combined = bytes <> chunk
        transport_require!(byte_size(combined) <= limit)
        ua_control_bytes!(fd, limit, combined)
      _ -> throw(:legacy_transport_observer)
    end
  end

  defp ua_control_fdinfo!(fd) do
    <<number::signed-native-integer-size(32)>> = :prim_file.get_handle(fd)
    transport_require!(number >= 0)
    c = Process.get({__MODULE__, :ua_control})
    suffix = "/fdinfo/" <> Integer.to_string(number)
    if Map.has_key?(c, :mount_records) do
      routes = ["/proc/self" <> suffix, c.self_root <> suffix]
      transport_require!(not Enum.any?(c.mount_records, fn record ->
        record.id != c.proc_mount and Enum.any?(routes, &ua_covers?(record.point, &1))
      end))
    end
    literal = ua_control_raw!("/proc/self" <> suffix, 4096)
    numeric = ua_control_raw!(c.self_root <> suffix, 4096)
    transport_require!(literal == numeric)
    if Map.has_key?(c, :proc_mount) do
      root_stat = ua_control_fstat!(c.proc_fd)
      Enum.each(["/proc/self" <> suffix, c.self_root <> suffix], fn path ->
        stat = File.stat!(path, time: :posix)
        transport_require!(stat.type == :regular and stat.major_device == root_stat.major_device)
      end)
    end
    {:ok, lines} = ua_text_lines(literal, 4096)
    transport_require!(length(lines) == 4)
    rows = Map.new(lines, fn line ->
      [key, value] = :binary.split(line, "\t")
      {key, value}
    end)
    transport_require!(map_size(rows) == 4 and Enum.sort(Map.keys(rows)) ==
      Enum.sort(["pos:", "flags:", "mnt_id:", "ino:"]))
    transport_require!(ua_uint?(rows["pos:"], 9_223_372_036_854_775_807, false) and
      ua_uint?(rows["ino:"], 18_446_744_073_709_551_615, true) and
      ua_uint?(rows["mnt_id:"], 4_294_967_295, true) and
      byte_size(rows["flags:"]) in 2..12 and String.starts_with?(rows["flags:"], "0") and
      String.to_integer(rows["flags:"], 8) <= 4_294_967_295 and
      Enum.all?(:binary.bin_to_list(rows["flags:"]), &(&1 in ?0..?7)))
    transport_require!(:prim_file.get_handle(fd) == <<number::signed-native-integer-size(32)>>)
    %{inode: String.to_integer(rows["ino:"]), mount: rows["mnt_id:"]}
  end

  defp ua_control_object!(path, type, retained \\ nil) do
    before = File.stat!(path, time: :posix)
    modes = [:read, :raw, :binary] ++ if(type == :directory, do: [:directory], else: [])
    {:ok, fd} = :file.open(String.to_charlist(path), modes)
    try do
      stat = ua_control_fstat!(fd)
      info = ua_control_fdinfo!(fd)
      control = Process.get({__MODULE__, :ua_control})
      if Map.has_key?(control, :proc_mount) and String.starts_with?(path, "/proc/") and
           not String.contains?(path, "/ns/") and not String.ends_with?(path, "/exe"),
        do: transport_require!(info.mount == control.proc_mount)
      transport_require!(stat.type == type and ua_control_low(stat) == ua_control_low(before) and
        Bitwise.band(info.inode, 0xFFFFFFFF) == stat.inode)
      if retained do
        transport_require!(ua_control_low(ua_control_fstat!(retained)) == ua_control_low(stat) and
          ua_control_fdinfo!(retained) == info)
      end
      {:ok, recheck} = :file.open(String.to_charlist(path), modes)
      try do
        transport_require!(ua_control_low(ua_control_fstat!(recheck)) == ua_control_low(stat) and
          ua_control_fdinfo!(recheck) == info)
      after
        :ok = :file.close(recheck)
      end
      transport_require!(ua_control_low(ua_control_fstat!(fd)) == ua_control_low(stat) and
        ua_control_fdinfo!(fd) == info and
        ua_control_low(File.stat!(path, time: :posix)) == ua_control_low(stat))
      %{object: {type, Bitwise.band(Bitwise.bsr(stat.major_device, 8), 0xFFF),
        Bitwise.bor(Bitwise.band(stat.major_device, 0xFF),
          Bitwise.band(Bitwise.bsr(stat.major_device, 12), 0xFFF00)), info.inode},
        mount: info.mount, uid: stat.uid}
    after
      :ok = :file.close(fd)
    end
  end

  defp ua_control_read!(path, limit) do
    before = ua_control_object!(path, :regular)
    {:ok, fd} = :file.open(String.to_charlist(path), [:read, :raw, :binary])
    try do
      stat = ua_control_fstat!(fd)
      identity = ua_control_fdinfo!(fd)
      transport_require!(stat.type == :regular and identity.inode == elem(before.object, 3) and
        identity.mount == before.mount and Bitwise.band(identity.inode, 0xFFFFFFFF) == stat.inode)
      bytes = ua_control_bytes!(fd, limit, "")
      transport_require!(ua_control_fdinfo!(fd) == identity and
        ua_control_low(ua_control_fstat!(fd)) == ua_control_low(stat) and
        ua_control_object!(path, :regular) == before)
      bytes
    after
      :ok = :file.close(fd)
    end
  end

  defp ua_control_link!(path, limit) do
    before = File.lstat!(path, time: :posix)
    transport_require!(before.type == :symlink)
    value = File.read_link!(path)
    transport_require!(byte_size(value) > 0 and byte_size(value) <= limit and
      :binary.match(value, <<0>>) == :nomatch and
      ua_control_low(File.lstat!(path, time: :posix)) == ua_control_low(before) and
      File.read_link!(path) == value)
    value
  end

  defp ua_control_namespace!(path, kind) do
    link = ua_control_link!(path, 128)
    object = ua_control_object!(path, :regular)
    value = %{link: link, object: object.object}
    transport_require!(ua_namespace?(value, kind))
    {value, object.mount}
  end

  defp ua_control_self!(native_pid) do
    c = Process.get({__MODULE__, :ua_control})
    transport_require!(ua_control_link!("/proc/self", 128) == c.self_pid)
    root = ua_control_object!("/proc", :directory, c.proc_fd)
    if Map.has_key?(c, :proc_mount), do: transport_require!(root.mount == c.proc_mount),
      else: ua_control_update(%{proc_mount: root.mount})
    directory = ua_control_object!(c.self_root, :directory, c.self_fd)
    transport_require!(ua_control_object!("/proc/self", :directory) == directory)
    literal_status = ua_control_object!("/proc/self/status", :regular)
    transport_require!(literal_status == ua_control_object!(c.self_root <> "/status", :regular))
    status = ua_control_read!("/proc/self/status", 4096)
    {:ok, uid} = ua_live_status(ua_parse_status(status, c.self_pid), c.self_pid)
    {:ok, ^uid} = ua_live_status(ua_parse_status(ua_control_read!(c.self_root <> "/status", 4096), c.self_pid), c.self_pid)
    {:ok, stat} = ua_parse_stat(ua_control_read!(c.self_root <> "/stat", 4096), c.self_pid)
    transport_require!(ua_live_state?(stat.state))
    pid_ns = ua_control_namespace!(c.self_root <> "/ns/pid", "pid")
    mount_ns = ua_control_namespace!(c.self_root <> "/ns/mnt", "mnt")
    transport_require!(ua_control_namespace!("/proc/self/ns/pid", "pid") == pid_ns and
      ua_control_namespace!("/proc/self/ns/mnt", "mnt") == mount_ns and
      ua_control_namespace!(c.self_root <> "/ns/pid_for_children", "pid") == pid_ns and
      ua_control_namespace!("/proc/self/ns/pid_for_children", "pid") == pid_ns)
    cgroup = ua_control_read!(c.self_root <> "/cgroup", 4096)
    transport_require!(cgroup == ua_control_read!("/proc/self/cgroup", 4096))
    independent = if Map.has_key?(c, :seed), do: c.seed.cgroup, else: cgroup
    {:ok, _} = ua_parse_cgroup(cgroup, independent, :v2)
    mount = ua_control_read!(c.self_root <> "/mountinfo", 16384)
    transport_require!(mount == ua_control_read!("/proc/self/mountinfo", 16384))
    {:directory, major, minor, _} = root.object
    {:ok, lines} = ua_text_lines(mount, 16384)
    {:ok, records} = ua_mount_rows(lines, [], [])
    [proc] = Enum.filter(records, &(&1.point == "/proc"))
    transport_require!(proc.root == "/" and proc.type == "proc" and
      proc.device == {Integer.to_string(major), Integer.to_string(minor)} and
      ua_hidepid_zero?(proc.options ++ proc.super_options))
    if native_pid do
      {:ok, admitted} = ua_parse_mountinfo(mount,
        %{self_pid: c.self_pid, native_pid: native_pid, proc_device: {major, minor}})
      transport_require!(admitted.record == proc.raw)
    end
    ua_control_update(%{mount_records: records})
    transport_require!(root.mount == proc.id and directory.mount == proc.id and
      literal_status.mount == proc.id)
    extra = Enum.flat_map(["/proc/self", c.self_root], fn base ->
      Enum.map(["", "/status", "/stat", "/mountinfo", "/cgroup", "/ns", "/ns/pid",
        "/ns/mnt", "/ns/pid_for_children", "/exe", "/fdinfo", "/fdinfo/"], &(base <> &1))
    end) ++ if(native_pid, do: ["/proc/" <> native_pid <> "/ns/mnt"], else: [])
    transport_require!(not Enum.any?(records, fn record ->
      record.id != proc.id and Enum.any?(extra, &ua_covers?(record.point, &1))
    end))
    value = %{root: root, directory: directory, status: literal_status, uid: uid,
      pid_ns: pid_ns, mount_ns: mount_ns, cgroup: cgroup, mount: mount,
      proc: proc.raw, start_ticks: stat.start_ticks}
    if Map.has_key?(c, :seed), do: ua_control_seed_mismatch(value, c.seed)
    if Map.has_key?(c, :seed), do: transport_require!(value == c.seed)
    value
  end

  defp ua_control_live! do
    c = Process.get({__MODULE__, :ua_control})
    ua_control_remaining!(c.deadline)
    self_before = ua_control_self!(c.native_pid)
    base = "/proc/" <> c.native_pid
    directory = ua_control_object!(base, :directory, c.native_fd)
    {:ok, stat} = ua_parse_stat(ua_control_read!(base <> "/stat", 4096), c.native_pid)
    {:ok, uid} = ua_live_status(ua_parse_status(ua_control_read!(base <> "/status", 4096),
      c.native_pid), c.native_pid)
    transport_require!(ua_live_state?(stat.state) and uid == self_before.uid)
    transport_require!(ua_control_namespace!(base <> "/ns/pid", "pid") == self_before.pid_ns and
      ua_control_namespace!(base <> "/ns/mnt", "mnt") == self_before.mount_ns)
    {:ok, _} = ua_parse_cgroup(ua_control_read!(base <> "/cgroup", 4096), self_before.cgroup, :v2)
    transport_require!(ua_control_link!(base <> "/exe", 4096) == c.sources.beam_path and
      ua_control_object!(base <> "/exe", :regular) == c.sources.beam)
    transport_require!(ua_control_self!(c.native_pid) == self_before)
    ua_control_port!()
    ua_control_remaining!(c.deadline)
    at = System.monotonic_time()
    %{identity: {directory, stat.start_ticks, c.sources.beam, self_before.pid_ns,
      self_before.mount_ns, self_before.cgroup}, start_ticks: stat.start_ticks,
      at: at, since_epoch: at - c.epoch}
  end

  defp ua_control_sources! do
    transport_require!(start_failure_origins_valid?(start_failure_origins()))
    start_failure_launcher!()
    rows = [
      {LegacyUpgradeRuntimeFixture, Path.join(@start_failure_root, "apps/singularity_runtime/test/support/legacy_upgrade_runtime_fixture.ex"),
       "6a746fad9d73981e1c8c5fdc6d6fdb420493227093fb6d10de31acd74d1b7d87"},
      {ExCmd.Process.Proto, Path.join(@start_failure_deps, "lib/ex_cmd/process/proto.ex"),
       "3827ccf95ae89189d8a4439ea556514d6e5b9f9e040a2598811fa78b017cdf69"},
      {Mix.Tasks.Compile.Odu, Path.join(@start_failure_deps, "lib/mix/compile.ex"),
       "730108534c596ba3ef96298e7c0d331c2b8e688d288f2c5ee0a65b0daa14a20d"}
    ]
    modules = Enum.map(rows, fn {module, source, sha} ->
      transport_require!(Code.ensure_loaded?(module))
      bytes = ua_control_read!(source, 65_536)
      transport_require!(start_failure_sha(bytes) == sha)
      {^module, beam, origin} = :code.get_object_code(module)
      transport_require!(:code.which(module) == origin and :code.is_loaded(module) == {:file, origin} and
        ua_control_read!(to_string(origin), 262_144) == beam and not :erlang.check_old_code(module))
      {:ok, {^module, [{:compile_info, compile}]}} = :beam_lib.chunks(beam, [:compile_info])
      {:ok, {^module, md5}} = :beam_lib.md5(beam)
      transport_require!(Keyword.fetch!(compile, :source) == String.to_charlist(source) and
        :erlang.get_module_info(module, :compile) == compile and
        :erlang.get_module_info(module, :md5) == md5)
      {module, source, sha, origin, start_failure_sha(beam), compile, md5}
    end)
    transport_require!(Mix.Tasks.Compile.Odu.executable_name() == "odu_linux_amd64")
    odu_path = Application.app_dir(:ex_cmd, "priv") |> Path.join(Mix.Tasks.Compile.Odu.executable_name())
    odu = ua_control_object!(odu_path, :regular)
    transport_require!(odu == ua_control_object!(Path.join(@start_failure_deps, "priv/odu_linux_amd64"), :regular))
    transport_require!(start_failure_sha(ua_control_read!(odu_path, 1_944_902)) ==
      "09d7c40b95f225af04bc65d88c6c3dc2e9c10629c4961b334ad738c7d1f85443")
    beam_path = "/nix/store/ccqqw9mf6jqbampbc3ydvvidkwhs3446-erlang-28.5.0.3/lib/erlang/erts-16.4.0.3/bin/beam.smp"
    beam = ua_control_object!(beam_path, :regular)
    control = Process.get({__MODULE__, :ua_control})
    transport_require!(ua_control_link!("/proc/self/exe", 4096) == beam_path and
      ua_control_link!(control.self_root <> "/exe", 4096) == beam_path and
      ua_control_object!("/proc/self/exe", :regular) == beam and
      ua_control_object!(control.self_root <> "/exe", :regular) == beam)
    transport_require!(start_failure_sha(ua_control_read!(beam_path, 11_048_472)) ==
      "b76a55616834eeede74d7c8d4a086f8abbf8c873315095a95e8f6523ca4c7cc4")
    %{modules: modules, odu_path: odu_path, odu: odu, beam_path: beam_path, beam: beam}
  end



  test "the fixed clean transport closes its actual child before legacy readiness" do
    transport_entrypoint!()
    proof = transport_observation(:clean_frame)
    matches? = proof.outcome == {:ok, true}
    assert matches?
    valid? = proof.valid?
    assert valid?, "independent clean transport evidence is incomplete"
    private? = proof.private?
    assert private?, "transport diagnostics escaped the private channel"
  end

  test "a causal stderr prefix rejects after the same clean transport control" do
    transport_entrypoint!()
    control = transport_observation(:clean_frame)
    controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
    assert controlled?, "the same clean transport control must qualify first"

    proof = transport_observation(:stderr_prefix)
    rejected? = proof.outcome == {:error, :legacy_protocol, []}
    assert rejected?
    valid? = proof.valid?
    assert valid?, "independent rejected transport evidence is incomplete"
    private? = proof.private?
    assert private?, "transport diagnostics escaped the private channel"
  end

  for scenario <- [:malformed_payload, :short_frame_trailer] do
    test "#{scenario} rejects after the same clean transport control" do
      transport_entrypoint!()
      control = transport_observation(:clean_frame)
      controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
      assert controlled?, "the same clean transport control must qualify first"
      transport_scenario!(unquote(scenario))

      proof = transport_observation(unquote(scenario))
      rejected? = proof.outcome == {:error, :legacy_protocol, []}
      assert rejected?
      valid? = proof.valid?
      assert valid?, "independent reader and physical cleanup evidence is incomplete"
      private? = proof.private?
      assert private?, "transport diagnostics escaped the private channel"
    end
  end

