  test "the full-boundary control and overrun both close before their parser-order verdict" do
    transport_entrypoint!()
    transport_scenario!(:full_frame_eof)
    control = transport_observation(:full_frame_eof)
    controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
    assert controlled?, "full-boundary positive physical cleanup and privacy must qualify first"

    transport_scenario!(:full_frame_overrun)
    proof = transport_observation(:full_frame_overrun)
    rejected? = proof.outcome == {:error, :legacy_output_limit, []}
    assert rejected?
    physical? = proof.valid? and proof.private?
    assert physical?, "full-boundary overrun must independently close its actual child privately"

    ordered? = {control.full_ordered?, proof.full_ordered?}
    assert ordered? == {true, true}, "both full-boundary cases must probe before any decoder call"
  end

  test "full-boundary ordering rejects missing, reordered and mismatched positive facts" do
    state = transport_full_pure_state(:full_frame_eof)
    assert transport_full_valid?(state)

    mutants = [
      put_in(state.full.body, nil),
      put_in(state.full.body, 4),
      put_in(state.full.valid?, false),
      put_in(state.full.probe_call, 3),
      put_in(state.full.probe_return, {6, :byte}),
      put_in(state.full.probe_return, {5, :eof}),
      put_in(state.full.decode_call, 5),
      put_in(state.full.decode_return, {7, false}),
      put_in(state.full.decode_return, nil),
      %{state | stages: []},
      %{state | await_call: 8}
    ]

    for mutant <- mutants, do: refute(transport_full_valid?(mutant))

    reader = Enum.at(state.started, 1)
    initial = %{state | full: transport_full_initial()}
    ignored = transport_full_fact(initial, reader, :probe_call, 1)
    assert ignored.full == initial.full
    wrong_reader = transport_full_fact(initial, state.owner, {:body, true, true}, 2)
    refute wrong_reader.full.valid?
    wrong_body = transport_full_fact(initial, reader, {:body, true, false}, 2)
    refute wrong_body.full.valid?
    wrong_bound = transport_full_fact(initial, reader, {:body, false, true}, 2)
    refute wrong_bound.full.valid?

    for {reason, category} <- [
          {%{__struct__: Postgrex.Error, message: @transport_canary}, :postgrex},
          {%{__struct__: DBConnection.ConnectionError, message: @transport_canary}, :connection},
          {%{__struct__: MatchError, term: @transport_canary}, :match},
          {%{__struct__: FunctionClauseError, args: [@transport_canary]}, :function_clause},
          {%{__struct__: CaseClauseError, term: @transport_canary}, :case_clause},
          {%{__struct__: ArgumentError, message: @transport_canary}, :argument},
          {%{__struct__: Protocol.UndefinedError, value: @transport_canary}, :protocol},
          {%{__struct__: UndefinedFunctionError, module: @transport_canary}, :undefined_function}
        ] do
      diagnostic = transport_diagnostic6_caught(:error, reason)

      finite? =
        diagnostic == %{kind: :error, category: category} and
          not transport_contains?(diagnostic) and
          byte_size(:erlang.term_to_binary(diagnostic)) < 128

      assert finite?, "caught error diagnostics must retain only fixed categories"
    end

    guard? =
      transport_diagnostic6_caught(:throw, :legacy_transport_observer) ==
        %{kind: :throw, category: :observer_guard}

    assert guard?

    for {result, expected} <- [
          {{:ok, %{__struct__: Postgrex.Result, rows: [[@transport_canary]]}}, :rows_list},
          {{:error,
            %{
              __struct__: Postgrex.Error,
              postgres: %{code: :invalid_catalog_name, message: @transport_canary},
              query: @transport_canary
            }}, {:error, :invalid_catalog_name}},
          {{:error,
            %{
              __struct__: Postgrex.Error,
              postgres: %{code: @transport_canary},
              message: @transport_canary
            }}, {:error, :postgrex}},
          {{:error, %{__struct__: DBConnection.ConnectionError, message: @transport_canary}},
           {:error, :connection}},
          {{:error, @transport_canary}, {:error, :other}}
        ] do
      diagnostic = transport_diagnostic6_query_result(result)
      finite? = diagnostic == expected and not transport_contains?(diagnostic)
      assert finite?, "baseline query diagnostics must retain only fixed result categories"
    end
  end

  test "full-boundary rejection forbids decoding and requires its exact one-byte probe" do
    state = transport_full_pure_state(:full_frame_overrun)
    assert transport_full_valid?(state)

    mutants = [
      put_in(state.full.body, nil),
      put_in(state.full.probe_call, nil),
      put_in(state.full.probe_return, {6, :eof}),
      put_in(state.full.probe_return, {6, :invalid}),
      put_in(state.full.decode_call, 7),
      put_in(state.full.decode_return, {8, true}),
      %{state | stages: []},
      %{state | await_call: 6}
    ]

    for mutant <- mutants, do: refute(transport_full_valid?(mutant))

    reader = Enum.at(state.started, 1)
    duplicate = transport_full_fact(state, reader, :probe_call, 9)
    refute duplicate.full.valid?

    for kind <- [:throw, :exit, :error],
        reason <- [
          @transport_canary,
          {@transport_canary, [@transport_canary]},
          %{__struct__: @transport_canary, message: @transport_canary},
          [@transport_canary]
        ] do
      diagnostic = transport_diagnostic6_caught(kind, reason)

      rejected? =
        diagnostic == %{kind: kind, category: :other} and
          not transport_contains?(diagnostic)

      assert rejected?, "unknown caught data must collapse to the finite other category"

      result_diagnostic = transport_diagnostic6_query_result({kind, reason})
      expected_result = if kind == :error, do: {:error, :other}, else: :other

      rejected_result? =
        result_diagnostic == expected_result and not transport_contains?(result_diagnostic)

      assert rejected_result?, "unknown query results must never retain their inputs"
    end

    for result <- [
          @transport_canary,
          {:ok, %{__struct__: Postgrex.Result, rows: @transport_canary}},
          {:ok, %{__struct__: @transport_canary, rows: [[@transport_canary]]}}
        ] do
      diagnostic = transport_diagnostic6_query_result(result)
      rejected? = diagnostic == :other and not transport_contains?(diagnostic)
      assert rejected?
    end

    diagnostic = transport_diagnostic6_caught(@transport_canary, @transport_canary)
    rejected? = diagnostic == %{kind: :other, category: :other}
    assert rejected?

    for elapsed <- [0, 1, 4_999, 5_000] do
      bounded? = transport_diagnostic6_elapsed(elapsed) == elapsed
      assert bounded?
    end

    for elapsed <- [-1, 5_001, 1_000_000_000, @transport_canary] do
      bounded? = transport_diagnostic6_elapsed(elapsed) == :overrun
      assert bounded?, "elapsed diagnostics must never retain out-of-range inputs"
    end
  end

  test "full-boundary physical closure rejects missing workers, await, SQL and terminal ordering" do
    for scenario <- [:full_frame_eof, :full_frame_overrun] do
      state = transport_full_pure_state(scenario)
      assert transport_valid?(state)
      # Strict parser-order failure cannot substitute for or poison physical closure.
      assert transport_valid?(put_in(state.full.valid?, false))

      mutants = [
        %{state | valid?: false},
        %{state | gate: false},
        %{state | child: nil},
        %{state | absent?: false},
        %{state | down: MapSet.new()},
        %{state | exits: %{}},
        %{state | queued: []},
        %{state | await_call: nil},
        %{state | await_return: {13, :invalid}},
        %{state | sql_zero: nil},
        %{state | closed: 11},
        %{state | checkpoints: %{}}
      ]

      for mutant <- mutants, do: refute(transport_valid?(mutant))
    end

    key = make_ref()
    owner = self()
    diagnostic_state = %{key: key, owner: owner}

    for outcome <- [:armed, :expired], elapsed <- [0, 5_000, :overrun] do
      message = {key, :diagnostic6_armed, owner, outcome, elapsed}
      diagnostic = transport_diagnostic6_armed(message, diagnostic_state)
      finite? = diagnostic == %{outcome: outcome, elapsed: elapsed}
      assert finite?
    end

    for message <- [
          {make_ref(), :diagnostic6_armed, owner, :armed, 0},
          {key, :diagnostic6_armed, make_ref(), :armed, 0},
          {key, :diagnostic6_armed, owner, @transport_canary, 0},
          {key, :diagnostic6_armed, owner, :armed, @transport_canary},
          {key, :diagnostic6_armed, owner, :expired, 5_001},
          @transport_canary
        ] do
      diagnostic = transport_diagnostic6_armed(message, diagnostic_state)
      rejected? = diagnostic == :unmatched and not transport_contains?(diagnostic)
      assert rejected?, "armed diagnostics require the exact private key and known owner"
    end
  end

  test "backend-gate diagnostics require finite correlated snapshots before row rejection" do
    baseline = [{101, "singularity_runtime"}, {102, "singularity_storage"}]
    child = 103

    rows_result = fn rows -> {:ok, %{__struct__: Postgrex.Result, rows: rows}} end

    control_rows = [
      [101, "singularity_runtime", "client backend"],
      [102, "singularity_storage", "client backend"],
      [103, "singularity_migration", "client backend"]
    ]

    control_result = rows_result.(control_rows)
    legacy_control? = transport_diagnostic6_query_result(control_result) == :rows_list
    assert legacy_control?, "the existing rows-list measurement must qualify first"

    # Expectations are independent of the classifier. These pure fixtures do not
    # establish the cause of the actual PostgreSQL failure or observer enforcement.
    control = %{
      result: :rows_list,
      row_count: 3,
      joint_rows: %{
        {:three, :positive, :baseline_role, :client} => 2,
        {:three, :positive, :migration, :client} => 1
      },
      comparable?: true,
      child_pid?: true,
      child_tuple?: true,
      baseline_equal?: true,
      added: 0,
      missing: 0
    }

    empty = %{
      result: :rows_list,
      row_count: 0,
      joint_rows: %{},
      comparable?: true,
      child_pid?: false,
      child_tuple?: false,
      baseline_equal?: false,
      added: 0,
      missing: 2
    }

    unavailable = %{
      result: :other,
      row_count: 0,
      joint_rows: %{},
      comparable?: false,
      child_pid?: false,
      child_tuple?: false,
      baseline_equal?: false,
      added: 0,
      missing: 0
    }

    query_cases = [
      {control_result, baseline, child, control},
      {rows_result.([]), baseline, child, empty},
      {{:error,
        %{
          __struct__: Postgrex.Error,
          postgres: %{code: :invalid_catalog_name, message: @transport_canary},
          query: @transport_canary
        }}, baseline, child, %{unavailable | result: :invalid_catalog_name}},
      {{:error,
        %{
          __struct__: Postgrex.Error,
          postgres: %{code: @transport_canary},
          message: @transport_canary
        }}, baseline, child, %{unavailable | result: :postgrex}},
      {{:error, %{__struct__: DBConnection.ConnectionError, message: @transport_canary}},
       baseline, child, %{unavailable | result: :connection}},
      {{:error, {@transport_canary, %{message: @transport_canary}}}, baseline, child,
       %{unavailable | result: :error_other}},
      {@transport_canary, baseline, child, unavailable},
      {{:ok, %{__struct__: Postgrex.Result, rows: @transport_canary}}, baseline, child,
       unavailable},
      {{:ok, %{__struct__: @transport_canary, rows: control_rows}}, baseline, child, unavailable}
    ]

    # A malformed arity has no invented PID, username or backend-type evidence.
    arity_cases =
      for row <- [
            [],
            [103],
            [103, "singularity_migration"],
            [103, nil, nil, nil],
            @transport_canary
          ] do
        {rows_result.([row]), baseline, child,
         %{
           empty
           | row_count: 1,
             joint_rows: %{{:other, :unavailable, :unavailable, :unavailable} => 1},
             comparable?: false
         }}
      end

    pid_cases =
      for {pid, category} <- [
            {0, :nonpositive},
            {-1, :nonpositive},
            {nil, :null},
            {@transport_canary, :other},
            {1.0, :other}
          ] do
        {rows_result.([[pid, "singularity_migration", "client backend"]]), baseline, child,
         %{
           empty
           | row_count: 1,
             joint_rows: %{{:three, category, :migration, :client} => 1},
             comparable?: false
         }}
      end

    username_cases =
      for {username, category, comparable?, added} <- [
            {@transport_canary, :other_binary, true, 1},
            {nil, :null, false, 0},
            {42, :other, false, 0}
          ] do
        {rows_result.([[child, username, "client backend"]]), baseline, child,
         %{
           empty
           | row_count: 1,
             joint_rows: %{{:three, :positive, category, :client} => 1},
             comparable?: comparable?,
             child_pid?: true,
             added: added
         }}
      end

    backend_cases =
      for {backend_type, category} <- [
            {"client backend", :client},
            {"autovacuum worker", :autovacuum_worker},
            {"parallel worker", :parallel_worker},
            {@transport_canary, :other_binary},
            {nil, :null},
            {42, :other}
          ] do
        {rows_result.([[child, "singularity_migration", backend_type]]), baseline, child,
         %{
           empty
           | row_count: 1,
             joint_rows: %{{:three, :positive, :migration, category} => 1},
             child_pid?: true,
             child_tuple?: true
         }}
      end

    membership_cases = [
      {rows_result.(Enum.take(control_rows, 2)), baseline, child,
       %{
         control
         | row_count: 2,
           joint_rows: %{{:three, :positive, :baseline_role, :client} => 2},
           child_pid?: false,
           child_tuple?: false
       }},
      {rows_result.([Enum.at(control_rows, 0), Enum.at(control_rows, 2)]), baseline, child,
       %{
         control
         | row_count: 2,
           joint_rows: %{
             {:three, :positive, :baseline_role, :client} => 1,
             {:three, :positive, :migration, :client} => 1
           },
           baseline_equal?: false,
           missing: 1
       }},
      {rows_result.(control_rows ++ [[104, @transport_canary, "client backend"]]), baseline,
       child,
       %{
         control
         | row_count: 4,
           joint_rows: %{
             {:three, :positive, :baseline_role, :client} => 2,
             {:three, :positive, :migration, :client} => 1,
             {:three, :positive, :other_binary, :client} => 1
           },
           baseline_equal?: false,
           added: 1
       }},
      {control_result, baseline, 104,
       %{control | child_pid?: false, child_tuple?: false, baseline_equal?: false, added: 1}},
      {control_result, [{104, "singularity_runtime"}, {102, "singularity_storage"}], child,
       %{control | baseline_equal?: false, added: 1, missing: 1}},
      {rows_result.([
         [103, "singularity_runtime", "client backend"],
         [104, "singularity_migration", "client backend"]
       ]), baseline, child,
       %{
         control
         | row_count: 2,
           joint_rows: %{
             {:three, :positive, :baseline_role, :client} => 1,
             {:three, :positive, :migration, :client} => 1
           },
           child_tuple?: false,
           baseline_equal?: false,
           added: 2,
           missing: 2
       }}
    ]

    # These have identical marginal classes but different row correlation.
    correlation_cases = [
      {rows_result.([
         [103, "singularity_migration", "client backend"],
         [nil, nil, "autovacuum worker"]
       ]), baseline, child,
       %{
         empty
         | row_count: 2,
           joint_rows: %{
             {:three, :positive, :migration, :client} => 1,
             {:three, :null, :null, :autovacuum_worker} => 1
           },
           comparable?: false,
           child_pid?: true,
           child_tuple?: true
       }},
      {rows_result.([
         [103, "singularity_migration", "autovacuum worker"],
         [nil, nil, "client backend"]
       ]), baseline, child,
       %{
         empty
         | row_count: 2,
           joint_rows: %{
             {:three, :positive, :migration, :autovacuum_worker} => 1,
             {:three, :null, :null, :client} => 1
           },
           comparable?: false,
           child_pid?: true,
           child_tuple?: true
       }}
    ]

    baseline63 = for pid <- 1..63, do: {pid, "singularity_runtime"}
    rows63 = for pid <- 1..63, do: [pid, "singularity_runtime", "client backend"]
    migration_row = [103, "singularity_migration", "client backend"]
    baseline65 = for pid <- 1..65, do: {pid, "singularity_runtime"}

    bound_cases = [
      {rows_result.(rows63 ++ [migration_row]), baseline63, child,
       %{
         control
         | row_count: 64,
           joint_rows: %{
             {:three, :positive, :baseline_role, :client} => 63,
             {:three, :positive, :migration, :client} => 1
           }
       }},
      {rows_result.(List.duplicate(migration_row, 64)), [], child,
       %{
         control
         | row_count: 64,
           joint_rows: %{{:three, :positive, :migration, :client} => 64},
           baseline_equal?: false,
           added: 63
       }},
      {rows_result.(List.duplicate(migration_row, 65)), [], child,
       %{
         control
         | row_count: :overflow,
           joint_rows: %{{:three, :positive, :migration, :client} => :overflow},
           baseline_equal?: false,
           added: 64
       }},
      {rows_result.(List.duplicate(migration_row, 66)), [], child,
       %{
         control
         | row_count: :overflow,
           joint_rows: %{{:three, :positive, :migration, :client} => :overflow},
           baseline_equal?: false,
           added: :overflow
       }},
      {rows_result.([]), Enum.take(baseline65, 64), child, %{empty | missing: 64}},
      {rows_result.([]), baseline65, child, %{empty | missing: :overflow}}
    ]

    cases =
      query_cases ++
        arity_cases ++
        pid_cases ++
        username_cases ++
        backend_cases ++
        membership_cases ++ correlation_cases ++ bound_cases

    measurements =
      Enum.map(cases, fn {result, expected_baseline, expected_child, expected} ->
        diagnostic =
          transport_diagnostic7_backend_query(result, expected_baseline, expected_child)

        private? =
          not transport_contains?(diagnostic) and
            byte_size(:erlang.term_to_binary(diagnostic)) < 2_048

        {diagnostic == expected, private?}
      end)

    private? = Enum.all?(measurements, fn {_, private?} -> private? end)
    assert private?, "backend-gate diagnostics must never retain private canary inputs"
    finite_snapshot? = Enum.all?(measurements, fn {matches?, _} -> matches? end)

    assert finite_snapshot?,
           "backend-gate diagnostics must preserve finite private row and membership evidence"
  end

  # TASK18_FULL_BOUNDARY_CONTRACT_END
  # TASK18_TRANSPORT_CLOSURE_CONTRACT_BEGIN
  test "transport closure consumes its own checkpoint and preserves foreign rejection" do
    key = make_ref()
    owner = self()

    state = %{
      key: key,
      owner: owner,
      closed: 10,
      actor_closed: true,
      actor_down: true,
      checkpoints: %{},
      valid?: true
    }

    foreign = {make_ref(), :checkpoint, :before_database_drop, owner, 12}
    own = {key, :checkpoint, :before_database_drop, owner, 11}
    send(self(), foreign)
    send(self(), own)
    closed? = transport_actor_down(key, self(), make_ref(), state)

    consumed? =
      receive do
        ^own -> false
      after
        0 -> true
      end

    preserved? =
      receive do
        ^foreign -> true
      after
        0 -> false
      end

    rejected? = not transport_message(foreign, state).valid?
    assert closed?
    assert consumed?, "own closure checkpoint must be consumed before the next observation"
    assert preserved?, "foreign checkpoints must not be discarded"
    assert rejected?, "foreign checkpoints must still invalidate an observation"
  end

  test "transport closure requires its drop checkpoint strictly after confirmed closure" do
    key = make_ref()

    state = %{
      key: key,
      owner: self(),
      closed: 10,
      actor_closed: true,
      actor_down: true,
      checkpoints: %{before_database_drop: 11}
    }

    for invalid <- [9, 10, :untyped] do
      control? = transport_actor_down(key, self(), make_ref(), state)
      assert control?, "the ordered closure checkpoint must qualify first"
      mutant = put_in(state.checkpoints.before_database_drop, invalid)
      rejected? = not transport_actor_down(key, self(), make_ref(), mutant)
      assert rejected?, "unordered or untyped closure checkpoints must be rejected"
    end
  end

