  test "header diagnostics distinguish each initial header invariant without retaining inputs" do
    reader = self()

    state = %{
      scenario: :declared_oversize,
      started: [reader, reader, reader],
      down: MapSet.new(),
      header: %{start: nil, complete: nil, remaining: nil, requested: nil, steps: 0, reads: 0},
      valid?: true
    }

    message =
      {:trace_ts, reader, :call, {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3},
       {:legacy_header_fact, :start, true, true}, 10}

    control = transport_diagnostic_header(message, state)
    assert transport_message(message, state).valid?

    assert control == %{
             branch: :header_fact,
             phase: :start,
             reader?: true,
             bounded?: true,
             expected?: true,
             ordered?: true,
             notdown?: true,
             start?: false,
             complete?: false,
             remaining: nil,
             requested: nil,
             steps: 0,
             reads: 0
           }

    for mutation <- [:reader, :bounded, :expected, :ordered, :steps, :down, :scenario] do
      {changed_message, changed_state} =
        case mutation do
          :reader -> {message, %{state | started: []}}
          :bounded -> {put_elem(message, 4, {:legacy_header_fact, :start, false, true}), state}
          :expected -> {put_elem(message, 4, {:legacy_header_fact, :start, true, false}), state}
          :ordered -> {message, put_in(state.header.start, 9)}
          :steps -> {message, put_in(state.header.steps, 5)}
          :down -> {message, %{state | down: MapSet.new([reader])}}
          :scenario -> {message, %{state | scenario: :clean_frame}}
        end

      assert transport_message(message, state).valid?
      refute transport_message(changed_message, changed_state).valid?
      diagnostic = transport_diagnostic_header(changed_message, changed_state)
      assert byte_size(:erlang.term_to_binary(diagnostic)) < 1_024
      refute transport_contains?(diagnostic)
    end

    complete_first = put_elem(message, 4, {:legacy_header_fact, :complete, true, true})
    refute transport_message(complete_first, state).valid?
    first = transport_diagnostic_header(complete_first, state)
    assert first.phase == :complete and not first.start? and first.steps == 0 and first.reads == 0

    continued = %{
      state
      | header: %{start: 1, complete: nil, remaining: 4, requested: 4, steps: 1, reads: 1}
    }

    assert transport_message(complete_first, continued).valid?

    for mutation <- [:start, :time, :complete, :remaining, :requested] do
      mutant =
        case mutation do
          :start -> put_in(continued.header.start, nil)
          :time -> put_in(continued.header.start, 10)
          :complete -> put_in(continued.header.complete, 9)
          :remaining -> put_in(continued.header.remaining, 0)
          :requested -> put_in(continued.header.requested, 3)
        end

      assert transport_message(complete_first, continued).valid?
      refute transport_message(complete_first, mutant).valid?
      refute transport_diagnostic_header(complete_first, mutant).ordered?
    end
  end

