  test "diagnostic normalizers retain only their fixed finite categories" do
    canary = {@transport_canary, self(), make_ref(), %{secret: @transport_canary}}
    assert transport_diagnostic_header(canary, %{}) == :unmatched

    for fact <- [
          {:legacy_header_fact, canary, true, true},
