      {:trace_ts, self(), :call, {ExCmd.Process, :read, 2}, {:legacy_header_request, canary}, 10}

    assert transport_diagnostic_header(request, %{}) == :unmatched
    assert transport_diagnostic_small(nil) == nil
    assert transport_diagnostic_small(5) == nil
    for value <- 0..4, do: assert(transport_diagnostic_small(value) == value)
    for value <- 0..5, do: assert(transport_diagnostic_header_count(value) == value)

    for value <- [-1, 6, 1.0, canary] do
      assert transport_diagnostic_small(value) == nil
      assert transport_diagnostic_header_count(value) == :overflow
    end

    for step <- [
          :deadline,
          :query,
          :query_shape,
          :backend_baseline,
          :repo_identity,
          :repo_liveness,
          :worker_liveness,
          :unlock,
          :released
        ],
        status <- [:checking, :passed, :failed, :empty, :waiting] do
      assert transport_diagnostic_gate_status(step, status) == %{step: step, status: status}
    end

    diagnostic = transport_diagnostic_gate_status(canary, canary)
    assert diagnostic == %{step: :other, status: :other}
    refute transport_contains?(diagnostic)
    refute transport_contains?(transport_diagnostic_initial(canary))
    preparation = transport_diagnostic_initial_preparation(canary, [canary])
    assert preparation == %{primary: :other, cleanup: [:other]}
    refute transport_contains?(preparation)

    assert transport_diagnostic_initial_preparation(:legacy_start, []) ==
             %{primary: :legacy_start, cleanup: []}

    assert transport_initial_remaining(100, 10) == 90
    assert transport_initial_remaining(100, 60) == 40
    assert transport_initial_remaining(100, 100) == 0
    assert transport_initial_remaining(100, 110) == 0

    assert transport_diagnostic_initial({:error, :legacy_output_limit, []}) ==
             %{outcome: :legacy_output_limit, preparation: :legacy_output_limit}

    assert transport_diagnostic_initial(:actor_failed) ==
             %{outcome: :actor_failed, preparation: :unobserved}

    # Lane A vectors are synthetic: no fixture acquisition, monitor or wait.
    opaque_pid = self()
    opaque_ref = make_ref()
    opaque = {canary, "/private/task18-canary", fn -> canary end, opaque_pid, opaque_ref}
    origins = [
      {Singularity.Storage.MigrationTestEnvironment, :pause_owned_baseline, 0, :baseline_pause},
      {Singularity.Storage.MigrationTestEnvironment, :owned_checkpoint, 1, :acquisition_checkpoint},
      {Singularity.Storage.MigrationTestEnvironment, :acquire_owned_destination, 0, :destination_acquire},
      {Singularity.Storage.Backup.KnowledgeFixtureResourceOwner, :request, 2, :owner_request}
    ]
    reasons = [
      {:error, %{__struct__: RuntimeError, message: opaque}, :runtime_error},
      {:error, %{__struct__: MatchError, term: opaque}, :match_error},
      {:error, %{__struct__: FunctionClauseError, args: opaque}, :function_clause},
      {:error, %{__struct__: CaseClauseError, term: opaque}, :case_clause},
      {:error, %{__struct__: ArgumentError, message: opaque}, :argument_error},
      {:throw, :fixture_caller_down, :caller_down},
      {:exit, {:fixture_owner_down, opaque}, :owner_down}
    ]
    for {module, function, arity, origin} <- origins,
        tail <- [[], [opaque], opaque, List.duplicate(opaque, 4_096)],
        {kind, value, reason_tag} <- reasons do
      original = {kind, value, [{module, function, arity, opaque} | tail]}
      diagnostic = transport_actor_failure_diagnostic(original)
      exact = diagnostic === %{kind: kind, origin: origin, reason_tag: reason_tag}
      assert exact
      retained = original === {kind, value, [{module, function, arity, opaque} | tail]}
      assert retained
      refute transport_contains?(diagnostic)
      refute transport_contains?(inspect(diagnostic))
    end
    known = {Singularity.Storage.MigrationTestEnvironment, :pause_owned_baseline, 0, opaque}
    for stack <- [[], opaque, :not_a_stack, [opaque, known],
      [{Singularity.Storage.MigrationTestEnvironment, :pause_owned_baseline, 1, opaque}, known],
      [{Singularity.Storage.MigrationTestEnvironment, :pause_owned_baseline, [opaque], opaque}, known],
      [{Singularity.Storage.MigrationTestEnvironment, :anonymous, 0, opaque}, known],
      [{__MODULE__, :pause_owned_baseline, 0, opaque}, known],
      [{Singularity.Storage.MigrationTestEnvironment, :pause_owned_baseline, 0}, known]] do
      positive = transport_actor_failure_diagnostic({:throw, :fixture_caller_down, [known]})
      assert positive == %{kind: :throw, origin: :baseline_pause, reason_tag: :caller_down}
      diagnostic = transport_actor_failure_diagnostic({:throw, :fixture_caller_down, stack})
      rejected = diagnostic === %{kind: :throw, origin: :unknown, reason_tag: :caller_down}
      assert rejected
      refute transport_contains?(diagnostic)
    end
    for {tag, expected_tag} <- [{RuntimeError, :runtime_error}, {MatchError, :match_error},
      {FunctionClauseError, :function_clause}, {CaseClauseError, :case_clause},
      {ArgumentError, :argument_error}], message <- [opaque, "fixture_owner_down", "MatchError"] do
      diagnostic = transport_actor_failure_diagnostic({:error, %{__struct__: tag, message: message}, []})
      exact = diagnostic === %{kind: :error, origin: :unknown, reason_tag: expected_tag}
      assert exact
      refute transport_contains?(diagnostic)
    end
    for {kind, value} <- [{:error, %{__struct__: __MODULE__, message: "RuntimeError"}},
      {:error, %{message: "fixture_caller_down"}}, {:error, {:fixture_owner_down, opaque}},
      {:throw, {:fixture_caller_down, opaque}}, {:exit, {:fixture_owner_down, opaque, opaque}},
      {:throw, %{__struct__: RuntimeError, message: opaque}}, {:exit, :fixture_caller_down}] do
      diagnostic = transport_actor_failure_diagnostic({kind, value, [known]})
      rejected = diagnostic === %{kind: kind, origin: :baseline_pause, reason_tag: :unknown}
      assert rejected
    end
    unknown = %{kind: :unknown, origin: :unknown, reason_tag: :unknown}
    for original <- [opaque, [], %{reason: opaque}, {:foreign, opaque, []}] do
      fallback = transport_actor_failure_diagnostic(original) === unknown
      assert fallback
    end

    key = make_ref()
    actor = self()
    monitor = make_ref()
    foreign_actor = :erlang.list_to_pid(~c"<0.0.0>")
    state = %{key: key, actor: actor, valid?: true, private?: true, outcome: nil,
      queued: [], checkpoints: %{}, stages: [], deadline: 123, closed: nil}
    first = {key, :diagnostic_actor_failure, actor, :throw, :baseline_pause, :caller_down}
    duplicate = {key, :diagnostic_actor_failure, actor, :exit, :owner_request, :owner_down}
    expected_record = %{kind: :throw, origin: :baseline_pause, reason_tag: :caller_down}
    Process.put({key, :actor}, {actor, monitor})
    try do
      assert transport_actor_failure_get(key) ==
        %{kind: :unknown, origin: :unobserved, reason_tag: :unobserved}
      for original <- [{:throw, :fixture_caller_down, [known]},
        {:error, %{__struct__: RuntimeError, message: opaque}, [known]},
        {:exit, {:fixture_owner_down, opaque}, [known]}, opaque] do
        diagnostic = transport_actor_failure_diagnostic(original)
        transport_actor_failure_emit(self(), key, original)
        first_message = receive do
          value when is_tuple(value) and tuple_size(value) > 0 and elem(value, 0) == key -> value
        after 0 -> :missing end
        ordered = first_message === {key, :diagnostic_actor_failure, actor,
          diagnostic.kind, diagnostic.origin, diagnostic.reason_tag}
        assert ordered
        canonical = receive do
          {^key, :outcome, :actor_failed, [], false, false} -> true
        after 0 -> false end
        assert canonical
        duplicated = receive do
          value when is_tuple(value) and tuple_size(value) > 0 and elem(value, 0) == key -> true
        after 0 -> false end
        refute duplicated
        refute transport_contains?(first_message)
      end
      for route <- [:active, :drain] do
        Process.delete({key, :diagnostic_actor_failure})
        for message <- [first, duplicate] do
          case route do
            :active ->
              unchanged = transport_message(message, state) === state
              assert unchanged
            :drain ->
              send(self(), message)
              assert transport_diagnostic4_drain(key, 0) == :ok
          end
          assert transport_actor_failure_get(key) == expected_record
          assert Process.get({key, :actor}) == {actor, monitor}
        end
        for bad <- [put_elem(first, 0, make_ref()), put_elem(first, 2, foreign_actor),
          put_elem(first, 2, opaque), put_elem(first, 3, opaque), put_elem(first, 4, opaque),
          put_elem(first, 5, opaque), Tuple.append(first, opaque), Tuple.delete_at(first, 5), opaque] do
          assert transport_actor_failure_record(key, first) == :accepted
          assert transport_actor_failure_get(key) == expected_record
          assert transport_actor_failure_record(key, bad) == :rejected
          case route do
            :active ->
              unchanged_policy = transport_message(bad, state) === %{state | valid?: false}
              assert unchanged_policy
            :drain ->
              send(self(), bad)
              assert transport_diagnostic4_drain(key, 0) == :ok
              unconsumed = receive do ^bad -> true after 0 -> false end
              assert unconsumed
          end
          assert transport_actor_failure_get(key) == expected_record
          refute transport_contains?(inspect(transport_actor_failure_get(key)))
          refute String.contains?(inspect(transport_actor_failure_get(key)), inspect(opaque_pid))
          refute String.contains?(inspect(transport_actor_failure_get(key)), inspect(opaque_ref))
        end
      end
      Process.delete({key, :diagnostic_actor_failure})
      stages = [:before_allocation, :allocated, :baseline_paused, :maintenance_started,
        :database_created, :root_created, :extensions_ready, :before_migration, :migrated]
      for stage <- stages, do: send(self(), {key, :diagnostic4_stage, stage})
      send(self(), first)
      assert transport_diagnostic4_drain(key, 0) == :ok
      assert Process.get({key, :diagnostic4_acquisition}) == %{last: :migrated, count: 9}
      assert transport_actor_failure_get(key) == expected_record
      Process.delete({key, :diagnostic_actor_failure})
      Process.delete({key, :diagnostic4_acquisition})
      for _ <- 1..32, do: send(self(), {key, :diagnostic4_stage, :allocated})
      send(self(), first)
      assert transport_diagnostic4_drain(key, 0) == :ok
      assert Process.get({key, :diagnostic4_acquisition}) == %{last: :allocated, count: 32}
      assert Process.get({key, :diagnostic_actor_failure}) == nil
      capped = receive do ^first -> true after 0 -> false end
      assert capped
      Process.delete({key, :actor})
      assert transport_actor_failure_record(key, first) == :rejected
      unchanged_policy = transport_message(first, state) === %{state | valid?: false}
      assert unchanged_policy
      send(self(), first)
      assert transport_diagnostic4_drain(key, 0) == :ok
      unconsumed = receive do ^first -> true after 0 -> false end
      assert unconsumed
    after
      for field <- [:actor, :diagnostic_actor_failure, :diagnostic4_acquisition],
        do: Process.delete({key, field})
    end
  end

