  # TASK18_C3C_EMERGENCY_JOIN_CONTRACT_BEGIN
  test "emergency observer cleanup joins its real owner before accepting restoration" do
    deadline = System.monotonic_time(:millisecond) + 45_000
    baseline = transport_cleanup_baseline(deadline)
    baseline_valid? = Enum.all?(baseline.repos, fn {_repo, binding} -> binding != :invalid end)
    assert baseline_valid?, "the complete restoration baseline must be observable"

    control = transport_cleanup_case(:control, baseline, deadline)

    assert control.recovered?,
           "the unheld owner must physically restore before another allocation"

    joined = transport_cleanup_case(:held_join, baseline, deadline)
    assert joined.recovered?, "the held owner must physically restore before another allocation"
    expired = transport_cleanup_case(:held_expiry, baseline, deadline)

    assert expired.recovered?,
           "the expired owner must physically restore before the final verdict"

    IO.puts(
      :stderr,
      "TASK18_C3C_EMERGENCY_JOIN " <>
        inspect(%{
          control: control.observation,
          joined: joined.observation,
          expired: expired.observation
        })
    )

    qualified? =
      control.observation.receipt == %{actor: :confirmed, owner: :normal} and
        not control.observation.owner_alive? and
        joined.observation.kind == :joined and joined.observation.waiting? and
        joined.observation.receipt == %{actor: :confirmed, owner: :normal} and
        not joined.observation.owner_alive? and
        expired.observation.kind == :expired and
        expired.observation.receipt == %{actor: :confirmed, owner: :unconfirmed} and
        expired.observation.owner_alive?

    assert qualified?,
           "cleanup must join the exact owner or retain its bounded unconfirmed verdict"
  end

  test "emergency cleanup witnesses and receipts reject false restoration without replacing primary" do
    assert transport_cleanup_remaining_ms(10_000, 5_000) == 5_000
    assert transport_cleanup_remaining_ms(10_000, 9_000) == 1_000
    assert transport_cleanup_remaining_ms(10_000, 10_000) == 0
    assert transport_cleanup_remaining_ms(10_000, 10_001) == 0

    key = make_ref()
    pid = self()
    ref = make_ref()
    witness = {key, pid, ref, :normal}
    assert transport_cleanup_witness(key, pid, ref, witness) == :normal

    for mutant <- [
          nil,
          {make_ref(), pid, ref, :normal},
          {key, make_ref(), ref, :normal},
          {key, pid, make_ref(), :normal},
          {key, pid, ref},
          {key, pid, ref, @transport_canary}
        ] do
      assert transport_cleanup_witness(key, pid, ref, mutant) == :unconfirmed
    end

    assert transport_cleanup_witness(key, pid, ref, {key, pid, ref, :non_normal}) == :non_normal

    state = %{
      key: key,
      actor: pid,
      actor_monitor: ref,
      actor_down: nil,
      monitors: %{},
      down: MapSet.new()
    }

    owner_ref = make_ref()
    Process.put({key, :actor}, {pid, ref})
    Process.put({key, :owner}, {pid, owner_ref})

    try do
      actor_state = transport_message({:DOWN, ref, :process, pid, :normal}, state)
      owner_state = transport_message({:DOWN, owner_ref, :process, pid, :normal}, actor_state)
      assert owner_state == actor_state

      assert transport_cleanup_witness(key, pid, ref, Process.get({key, {:cleanup_down, :actor}})) ==
               :normal

      assert transport_cleanup_witness(
               key,
               pid,
               owner_ref,
               Process.get({key, {:cleanup_down, :owner}})
             ) == :normal

      transport_cleanup_record(key, :owner, make_ref(), pid, @transport_canary)

      assert transport_cleanup_witness(
               key,
               pid,
               owner_ref,
               Process.get({key, {:cleanup_down, :owner}})
             ) == :normal
    after
      for name <- [:actor, :owner, {:cleanup_down, :actor}, {:cleanup_down, :owner}],
          do: Process.delete({key, name})
    end

    receipt = %{actor: :confirmed, owner: :normal}

    proof = %{
      outcome: {:error, :legacy_pipe, []},
      valid?: true,
      private?: false,
      full_ordered?: false
    }

    assert transport_cleanup_proof(proof, receipt) == proof

    for value <- [
          nil,
          :ok,
          %{actor: :confirmed},
          %{owner: :normal},
          %{actor: :unconfirmed, owner: :normal},
          %{actor: :confirmed, owner: :non_normal},
          %{actor: :confirmed, owner: :unconfirmed},
          %{actor: :confirmed, owner: :normal, extra: @transport_canary},
          @transport_canary
        ] do
      result = transport_cleanup_proof(proof, value)
      preserved? = not result.valid? and Map.delete(result, :valid?) == Map.delete(proof, :valid?)
      assert preserved?, "cleanup failure must preserve the original primary and privacy"
      refute transport_contains?(transport_cleanup_receipt(value))
    end

    false_proof = %{proof | valid?: false}
    assert transport_cleanup_proof(false_proof, receipt) == false_proof
  end

