  test "an actually blocked reader loss closes before its independent pipe verdict" do
    transport_entrypoint!()
    control = transport_observation(:blocked_reader_control)
    controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
    assert controlled?, "the actual blocked-reader positive control must qualify first"

    proof = transport_observation(:reader_down)
    physical? = proof.valid?
    assert physical?, "reader loss must independently close its child before database removal"
    private? = proof.private?
    assert private?, "reader-loss observations must remain private"

    primary? = proof.outcome == {:error, :legacy_pipe, []}
    assert primary?, "actual blocked-reader loss must retain the pipe primary"
  end

  test "blocked-reader evidence rejects missing, foreign and reordered lifecycle facts" do
    state = transport_c4_pure_state()
    assert transport_c4_valid?(state)
    reader = Enum.at(state.started, 1)
    wrong = state.owner

    mutants = [
      %{state | valid?: false},
      %{state | started: [hd(state.started), wrong, List.last(state.started)]},
      put_in(state.c4.reader, wrong),
      put_in(state.c4.hold, nil),
      put_in(state.c4.hold, {make_ref(), state.owner, elem(state.c4.hold, 2)}),
      put_in(state.c4.hold, {state.key, hd(state.started), elem(state.c4.hold, 2)}),
      put_in(state.c4.acquired?, false),
      put_in(state.c4.ack_tag, make_ref()),
      put_in(state.c4.ack, nil),
      put_in(state.c4.ack, state.c4.trigger + 1),
      put_in(state.c4.resumed, state.c4.release - 1),
      put_in(state.c4.resumed, state.await_call + 1),
      put_in(state.c4.owned?, true),
      put_in(state.c4.read, nil),
      put_in(state.c4.pending, nil),
      put_in(state.c4.pending, state.c4.read - 1),
      put_in(state.c4.blocked, nil),
      put_in(state.c4.waiting?, false),
      put_in(state.c4.trigger, state.c4.blocked - 1),
      put_in(state.c4.reader_down, nil),
      put_in(state.c4.down_ref, make_ref()),
      put_in(state.c4.reader_down, state.c4.trigger - 1),
      %{state | exits: Map.delete(state.exits, reader)},
      put_in(state.c4.release, state.c4.reader_down - 1),
      put_in(state.c4.release, state.exits[reader] - 1),
      %{state | await_call: state.c4.release - 1},
      %{state | await_return: nil},
      %{state | await_return: {15, :invalid}},
      %{state | sql_zero: nil},
      %{state | absent?: false},
      %{state | down: MapSet.delete(state.down, reader)},
      %{state | checkpoints: %{ready: 20, before_database_drop: 20}},
      %{state | checkpoints: %{before_database_drop: state.closed - 1}},
      %{state | closed: state.sql_zero - 1},
      %{state | queued: []}
    ]

    for mutant <- mutants, do: refute(transport_c4_valid?(mutant))
    # The physical oracle must preserve a real wrong primary for the RED verdict.
    assert transport_c4_preparation(:reader_down, :legacy_deadline, [], true) ==
             {{:error, :legacy_deadline, []}, true}

    assert transport_c4_preparation(:reader_down, :legacy_pipe, [], false) ==
             {{:error, :legacy_pipe, []}, false}

    {outcome, private?} =
      transport_c4_preparation(:reader_down, @transport_canary, [@transport_canary], true)

    assert outcome == {:error, :other, [:other]}
    assert private?
    refute transport_contains?(outcome)
  end

