  # TASK18_WRITER_LOSS_CONTRACT_BEGIN
  test "an original writer lost after its completed write closes before its pipe verdict" do
    clock? =
      transport_writer_clock_unit?({
        System.convert_time_unit(1, :second, :native),
        System.convert_time_unit(1, :native, :nanosecond)
      })

    assert clock?, "the writer oracle requires a nanosecond-native parent VM"
    transport_entrypoint!()
    Process.delete({__MODULE__, :writer_control})

    try do
      control = transport_observation(:writer_wait_control)
      controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
      assert controlled?, "the completed-write waiting control must fully qualify first"
      Process.put({__MODULE__, :writer_control}, true)

      proof = transport_observation(:writer_down)
      physical? = proof.valid?
      assert physical?, "writer loss must independently close before database removal"
      private? = proof.private?
      assert private?, "writer-loss observations must remain private"
      workspace? = proof.workspace?
      assert workspace?, "writer loss must preserve its exact workspace boundaries"
      primary? = proof.outcome == {:error, :legacy_pipe, []}
      assert primary?, "actual original-writer loss must retain the pipe primary"
    after
      Process.delete({__MODULE__, :writer_control})
    end
  end

  test "writer evidence rejects foreign, missing, stale and reordered lifecycle facts" do
    for unit <- [
          {nil, 1},
          {false, 1},
          {0, 1},
          {-1, 1},
          {1, 1},
          {1_000, 1},
          {1_000_000, 1},
          {1_000_000_001, 1},
          {1_000_000_000.0, 1},
          {:invalid, 1},
          {1_000_000_000, nil},
          {1_000_000_000, false},
          {1_000_000_000, 0},
          {1_000_000_000, -1},
          {1_000_000_000, 2},
          {1_000_000_000, 1.0},
          {1_000_000_000, :invalid},
          1_000_000_000,
          nil,
          false,
          true,
          :invalid,
          %{},
          [],
          [1_000_000_000, 1],
          {},
          {1_000_000_000},
          {1_000_000_000, 1, true}
        ] do
      valid? = transport_writer_clock_unit?({1_000_000_000, 1})
      assert valid?, "the independent literal writer clock contract must qualify first"
      rejected? = not transport_writer_clock_unit?(unit)
      assert rejected?, "invalid writer clock contracts must be rejected privately"
    end

    mutations = [
      fn s -> %{s | valid?: false} end,
      fn s -> %{s | writer_loss: nil} end,
      fn s -> %{s | writer_loss: Map.delete(s.writer_loss, :write)} end,
      fn s -> %{s | writer_loss: Map.put(s.writer_loss, :extra, true)} end,
      fn s -> %{s | scenario: :reader_down} end,
      fn s -> %{s | run: make_ref()} end,
      fn s -> %{s | started: [hd(s.started), s.owner, List.last(s.started)]} end,
      fn s -> put_in(s.writer_loss.writer, s.owner) end,
      fn s -> put_in(s.writer_loss.command, s.owner) end,
      fn s -> put_in(s.writer_loss.owner, hd(s.started)) end,
      fn s -> put_in(s.writer_loss.run, make_ref()) end,
      fn s -> put_in(s.writer_loss.monitor, make_ref()) end,
      fn s -> put_in(s.writer_loss.write, nil) end,
      fn s -> put_in(s.writer_loss.write, s.writer_loss.blocked) end,
      fn s -> put_in(s.writer_loss.phase, :prestart) end,
      fn s -> put_in(s.writer_loss.phase, {:gen, :do_call, 4}) end,
      fn s -> put_in(s.writer_loss.gate_checked, nil) end,
      fn s -> put_in(s.writer_loss.baseline?, false) end,
      fn s -> put_in(s.writer_loss.repos?, false) end,
      fn s -> put_in(s.writer_loss.control?, false) end,
      fn s -> put_in(s.writer_loss.hold, nil) end,
      fn s -> put_in(s.writer_loss.hold, {make_ref(), s.owner, elem(s.writer_loss.hold, 2)}) end,
      fn s -> put_in(s.writer_loss.hold, {s.key, hd(s.started), elem(s.writer_loss.hold, 2)}) end,
      fn s -> put_in(s.writer_loss.acquired?, false) end,
      fn s -> put_in(s.writer_loss.ack_tag, make_ref()) end,
      fn s -> put_in(s.writer_loss.ack, nil) end,
      fn s -> put_in(s.writer_loss.owned?, true) end,
      fn s -> put_in(s.writer_loss.rechecked, s.writer_loss.ack - 1) end,
      fn s -> put_in(s.writer_loss.trigger, s.writer_loss.rechecked - 1) end,
      fn s -> put_in(s.writer_loss.triggers, 2) end,
      fn s -> put_in(s.writer_loss.down, nil) end,
      fn s -> put_in(s.writer_loss.down_ref, make_ref()) end,
      fn s -> put_in(s.writer_loss.down_reason, :normal) end,
      fn s -> put_in(s.writer_loss.down, s.writer_loss.trigger - 1) end,
      fn s -> put_in(s.writer_loss.exit, nil) end,
      fn s -> put_in(s.writer_loss.exit_reason, :normal) end,
      fn s -> put_in(s.writer_loss.exit, s.writer_loss.trigger - 1) end,
      fn s -> put_in(s.writer_loss.release, s.writer_loss.down - 1) end,
      fn s -> put_in(s.writer_loss.release, s.writer_loss.exit - 1) end,
      fn s -> put_in(s.writer_loss.resumed, s.writer_loss.release - 1) end,
      fn s -> put_in(s.writer_loss.resumed, s.await_call + 1) end,
      fn s -> %{s | await_return: nil} end,
      fn s -> %{s | await_return: {15, :unconfirmed}} end,
      fn s -> %{s | sql_zero: nil} end,
      fn s -> %{s | absent?: false} end,
      fn s -> %{s | gate: false} end,
      fn s -> %{s | child: nil} end,
      fn s -> %{s | down: MapSet.delete(s.down, List.last(s.started))} end,
      fn s -> %{s | exits: Map.delete(s.exits, hd(s.started))} end,
      fn s -> %{s | closed: s.sql_zero - 1} end,
      fn s -> %{s | checkpoints: %{ready: 20, before_database_drop: 20}} end,
      fn s -> %{s | checkpoints: %{before_database_drop: s.closed - 1}} end,
      fn s -> %{s | queued: []} end
    ]

    for mutate <- mutations do
      {state, facts} = transport_writer_pure_witness()
      valid? = transport_writer_final_valid?(state, facts)
      assert valid?, "the independent literal writer witness must qualify first"
      rejected? = not transport_writer_final_valid?(mutate.(state), facts)
      assert rejected?, "invalid writer lifecycle facts must be rejected privately"
    end

    for field <- [:trace?, :actor?, :workspace?, :privacy?, :registered?] do
      {state, facts} = transport_writer_pure_witness()
      valid? = transport_writer_final_valid?(state, facts)
      assert valid?, "the independent literal writer witness must qualify first"
      rejected? = not transport_writer_final_valid?(state, Map.put(facts, field, false))
      assert rejected?, "invalid writer completion facts must be rejected privately"
    end

    for cleanup <- [
          nil,
          %{actor: :unconfirmed, owner: :normal},
          %{actor: :confirmed, owner: :unconfirmed},
          %{actor: :confirmed, owner: :non_normal},
          %{actor: :confirmed, owner: :normal, extra: true}
        ] do
      {state, facts} = transport_writer_pure_witness()
      valid? = transport_writer_final_valid?(state, facts)
      assert valid?, "the independent literal writer witness must qualify first"
      rejected? = not transport_writer_final_valid?(state, %{facts | cleanup: cleanup})
      assert rejected?, "unconfirmed writer cleanup must be rejected privately"
    end

    for fact <- [:missing, :duplicate, :stale, :foreign, :malformed] do
      {state, facts} = transport_writer_pure_witness()
      valid? = transport_writer_final_valid?(state, facts)
      assert valid?, "the independent literal writer witness must qualify first"
      writer = state.writer_loss.writer

      pending = %{
        state
        | writer_loss: %{state.writer_loss | write: nil, blocked: nil, trigger: nil}
      }

      message =
        {:trace_ts, writer, :call, {ExCmd.Process, :write, 2}, {:legacy_writer_write, true}, 2}

      positive = transport_message(message, pending)
      matched? = positive.valid? and positive.writer_loss.write == 2
      assert matched?, "the exact independent write fact must qualify before its mutant"

      rejected? =
        case fact do
          :missing ->
            not transport_writer_final_valid?(
              %{state | writer_loss: %{state.writer_loss | write: nil}},
              facts
            )

          :duplicate ->
            not transport_message(message, positive).valid?

          :stale ->
            not transport_message(put_elem(message, 5, 1), pending).valid?

          :foreign ->
            not transport_message(put_elem(message, 1, state.owner), pending).valid?

          :malformed ->
            not transport_message(put_elem(message, 4, :malformed), pending).valid?
        end

      assert rejected?, "invalid writer trace facts must be rejected privately"
    end

    {state, facts} = transport_writer_pure_witness()
    valid? = transport_writer_final_valid?(state, facts)
    assert valid?, "the independent literal writer witness must qualify first"
    # Actual raw killed remains distinct from the helper's existing emitted nonzero.
    killed? = transport_writer_final_valid?(%{state | await_return: {15, :killed}}, facts)
    assert killed?, "actual raw killed maps only to the helper's existing nonzero fact"
  end

  # TASK18_WRITER_LOSS_CONTRACT_END

  # TASK18_DEADLINE_CONTRACT_BEGIN
  test "the original transport deadline closes naturally before its deadline verdict" do
    clock? =
      transport_writer_clock_unit?({
        System.convert_time_unit(1, :second, :native),
        System.convert_time_unit(1, :native, :nanosecond)
      })

    assert clock?, "the deadline oracle requires a nanosecond-native parent VM"
    transport_entrypoint!()
    Process.delete({__MODULE__, :deadline_control})

    try do
      control = transport_observation(:deadline_control)
      controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
      assert controlled?, "the unexpired deadline control must fully close first"
      Process.put({__MODULE__, :deadline_control}, true)
      proof = transport_observation(:deadline_expired)
      physical? = proof.valid?
      assert physical?, "natural deadline expiry must independently close before database removal"
      private? = proof.private?
      assert private?, "deadline observations must remain private"
      workspace? = proof.workspace?
      assert workspace?, "natural deadline expiry must preserve exact workspace boundaries"
      primary? = proof.outcome == {:error, :legacy_deadline, []}
      assert primary?, "natural original expiry must retain its actual deadline primary"
    after
      Process.delete({__MODULE__, :deadline_control})
    end
  end

  test "deadline scalars reject changed identities and early or unconfirmed closure" do
    mutations = [
      fn s -> %{s | valid?: false} end,
      fn s -> %{s | deadline_loss: nil} end,
      fn s -> %{s | deadline_loss: Map.delete(s.deadline_loss, :original)} end,
      fn s -> put_in(s.deadline_loss.owner, s.actor) end,
      fn s -> put_in(s.deadline_loss.caller, s.owner) end,
      fn s -> put_in(s.deadline_loss.run, make_ref()) end,
      fn s -> %{s | started: [s.owner | tl(s.started)]} end,
      fn s -> put_in(s.deadline_loss.pending, nil) end,
      fn s -> put_in(s.deadline_loss.active, nil) end,
      fn s -> put_in(s.deadline_loss.last_receive, s.deadline_loss.finish + 1) end,
      fn s -> put_in(s.deadline_loss.receives, 17) end,
      fn s -> put_in(s.deadline_loss.read, nil) end,
      fn s -> put_in(s.deadline_loss.operation, s.deadline_loss.read - 1) end,
      fn s -> put_in(s.deadline_loss.blocked, nil) end,
      fn s -> put_in(s.deadline_loss.baseline?, false) end,
      fn s -> put_in(s.deadline_loss.repos?, false) end,
      fn s -> put_in(s.deadline_loss.prior_control?, false) end,
      fn s -> put_in(s.deadline_loss.unheld?, false) end,
      fn s -> put_in(s.deadline_loss.finish, -10_000_001) end,
      fn s -> put_in(s.deadline_loss.primary, :legacy_pipe) end,
      fn s -> put_in(s.deadline_loss.release, s.await_call - 1) end,
      fn s -> %{s | exits: Map.put(s.exits, hd(s.started), s.deadline_loss.finish - 1)} end,
      fn s ->
        put_in(
          s.deadline_loss.downs,
          Map.put(s.deadline_loss.downs, hd(s.started), {make_ref(), s.deadline_loss.finish + 1})
        )
      end,
      fn s -> %{s | await_return: {-7_000_000, :unconfirmed}} end,
      fn s -> %{s | await_return: {-7_000_000, :zero}} end,
      fn s -> %{s | sql_zero: nil} end,
      fn s -> %{s | absent?: false} end,
      fn s -> %{s | checkpoints: Map.put(s.checkpoints, :ready, -3_000_000)} end,
      fn s -> %{s | checkpoints: %{before_database_drop: s.closed - 1}} end
    ]

    for mutate <- mutations do
      {state, facts} = transport_deadline_pure_witness()
      valid? = transport_deadline_final_valid?(state, facts)
      assert valid?, "the independent signed equal-expiry witness must qualify first"
      rejected? = not transport_deadline_final_valid?(mutate.(state), facts)
      assert rejected?, "invalid deadline closure facts must be rejected privately"
    end

    for field <- [:trace?, :actor?, :workspace?, :privacy?, :registered?, :cleanup] do
      {state, facts} = transport_deadline_pure_witness()
      valid? = transport_deadline_final_valid?(state, facts)
      assert valid?, "the independent signed equal-expiry witness must qualify first"
      rejected? = not transport_deadline_final_valid?(state, Map.put(facts, field, false))
      assert rejected?, "unconfirmed deadline final facts must be rejected privately"
    end

    for change <- [
          :foreign_owner,
          :foreign_run,
          :changed_deadline,
          :wrong_primary,
          :duplicate,
          :malformed
        ] do
      {state, facts} = transport_deadline_pure_witness()
      valid? = transport_deadline_final_valid?(state, facts)
      assert valid?, "the independent signed equal-expiry witness must qualify first"
      d = state.deadline_loss
      pending = %{state | deadline_loss: %{d | finish: nil}}

      message =
        {:trace_ts, state.owner, :call, {LegacyUpgradeRuntimeFixture, :transport_finish, 2},
         {:legacy_deadline_finish, state.run, d.original, :legacy_deadline}, d.finish}

      positive = transport_message(message, pending)
      matched? = transport_deadline_final_valid?(positive, facts)
      assert matched?, "the exact finish fact must qualify even when await arrives first"

      bad =
        case change do
          :foreign_owner ->
            put_elem(message, 1, state.actor)

          :foreign_run ->
            put_elem(
              message,
              4,
              {:legacy_deadline_finish, make_ref(), d.original, :legacy_deadline}
            )

          :changed_deadline ->
            put_elem(
              message,
              4,
              {:legacy_deadline_finish, state.run, d.original + 1, :legacy_deadline}
            )

          :wrong_primary ->
            put_elem(message, 4, {:legacy_deadline_finish, state.run, d.original, :other})

          :duplicate ->
            message

          :malformed ->
            put_elem(message, 4, :malformed)
        end

      rejected? =
        not transport_message(bad, if(change == :duplicate, do: positive, else: pending)).valid?

      assert rejected?, "foreign or duplicate deadline scalars must be rejected privately"
    end

    {state, facts} = transport_deadline_pure_witness()
    valid? = transport_deadline_final_valid?(state, facts)
    assert valid?, "the independent signed equal-expiry witness must qualify first"
    equal? = transport_deadline_ms(state.deadline_loss.finish) == state.deadline_loss.original
    assert equal?, "signed floor conversion must admit the exact expiry millisecond"

    killed? =
      transport_deadline_final_valid?(%{state | await_return: {-7_000_000, :killed}}, facts)

    assert killed?, "raw killed must retain the existing emitted nonzero distinction"

    for unit <- [{1_000_000_000.0, 1}, {1_000_000_000, 2}] do
      valid? = transport_writer_clock_unit?({1_000_000_000, 1})
      assert valid?, "the independent clock prerequisite must qualify first"
      rejected? = not transport_writer_clock_unit?(unit)
      assert rejected?, "wrong deadline clock prerequisites must fail closed"
    end
  end

  # TASK18_DEADLINE_CONTRACT_END

  # TASK18_EOF_EXIT_CONTRACT_BEGIN
  @transport_eof_modes [:clean_frame_exit17, :empty_eof, :partial_header_eof, :partial_body_eof]
  @transport_eof_mfas [
    {LegacyUpgradeRuntimeFixture, :transport_receive, 1},
    {LegacyUpgradeRuntimeFixture, :transport_read_result, 3},
    {LegacyUpgradeRuntimeFixture, :transport_full_probe, 4},
    {ExCmd.Process, :close_stdin, 1}
  ]

  for scenario <- @transport_eof_modes do
    @tag :integration
    test "actual EOF and exit contract #{scenario}" do
      transport_entrypoint!()
      control = transport_observation(:clean_frame)
      assert control.outcome == {:ok, true}
      assert control.valid? and control.private?
      assert control.physical? and control.workspace?
      assert control.cleanup == %{actor: :confirmed, owner: :normal}

      scenario = unquote(scenario)
      transport_scenario!(scenario)
      proof = transport_observation(scenario)
      category = Map.get(%{clean_frame_exit17: :legacy_exit}, scenario, :legacy_protocol)
      assert proof.outcome == {:error, category, []}
      assert proof.valid? and proof.private?
      assert proof.physical? and proof.workspace?
      assert proof.cleanup == %{actor: :confirmed, owner: :normal}
    end
  end

  test "literal EOF witnesses reject every missing, foreign and reordered dimension" do
    for scenario <- @transport_eof_modes do
      {literal, facts} = transport_eof_literal(scenario)

      mutants = [
        fn s -> put_in(s.eof.handle.exit_ref, make_ref()) end,
        fn s -> put_in(s.eof.run, make_ref()) end,
        fn s -> put_in(s.eof.capture_owner, s.actor) end,
        fn s -> put_in(s.eof.capture_workers, Enum.reverse(s.started)) end,
        fn s -> put_in(s.eof.installed?, false) end,
        fn s -> put_in(s.eof.baseline?, false) end,
        fn s -> put_in(s.eof.fenced?, false) end,
        fn s -> put_in(s.eof.ready, nil) end,
        fn s -> put_in(s.eof.capture, s.eof.ready + 1) end,
        fn s -> put_in(s.eof.steps, []) end,
        fn s -> put_in(s.eof.steps, if(length(s.eof.steps) == 1, do: [{0, :header, 4, true}], else: Enum.reverse(s.eof.steps))) end,
        fn s -> put_in(s.eof.steps, tl(s.eof.steps)) end,
        fn s -> put_in(s.eof.steps, Enum.map(s.eof.steps, fn {at, phase, n, _} -> {at, phase, n, false} end)) end,
        fn s -> put_in(s.eof.read_calls, []) end,
        fn s -> put_in(s.eof.read_calls, if(length(s.eof.read_calls) == 1, do: [{0, 4}], else: Enum.reverse(s.eof.read_calls))) end,
        fn s -> put_in(s.eof.read_calls, Enum.map(s.eof.read_calls, fn {at, n} -> {at + 1_000, n} end)) end,
        fn s -> put_in(s.eof.steps, [{1, :header, 3, true}]) end,
        fn s -> put_in(s.eof.results, []) end,
        fn s -> put_in(s.eof.results, s.eof.results ++ [List.last(s.eof.results)]) end,
        fn s -> put_in(s.eof.results, Enum.map(s.eof.results, fn {at, n, _} -> {at, n, :chunk} end)) end,
        fn s -> put_in(s.eof.results, Enum.map(s.eof.results, fn {at, n, k} -> {at, n + 1, k} end)) end,
        fn s -> put_in(s.eof.await, {elem(s.eof.await, 0), 1}) end,
        fn s -> put_in(s.eof.await, nil) end,
        fn s -> put_in(s.eof.await_handle, %{s.eof.handle | monitor_ref: make_ref()}) end,
        fn s -> %{s | await_call: nil} end,
        fn s -> %{s | await_return: {0, :zero}} end,
        fn s -> %{s | sql_call: nil} end,
        fn s -> %{s | sql_zero: s.await_call} end,
        fn s -> %{s | closed: s.sql_zero} end,
        fn s -> %{s | gate: false} end,
        fn s -> %{s | absent?: false} end,
        fn s -> %{s | queued: []} end,
        fn s -> %{s | outcome: {:ok, true}} end,
        fn s -> %{s | checkpoints: Map.put(s.checkpoints, :ready, s.closed + 1)} end,
        fn s -> %{s | checkpoints: %{before_database_drop: s.closed}} end,
        fn s -> %{s | down: MapSet.new()} end,
        fn s -> %{s | exits: %{}} end,
        fn s -> put_in(s.eof.downs, %{}) end,
        fn s -> put_in(s.eof.exit_reasons, %{}) end,
        fn s -> put_in(s.eof.exit_reasons, Map.new(s.started, &{&1, :shutdown})) end,
        fn s -> put_in(s.eof.full_probe, [1, 2]) end,
        fn s -> put_in(s.eof.decode_call, 0) end,
        fn s -> put_in(s.eof.decode_return, {0, false}) end
      ]

      for mutate <- mutants do
        assert transport_eof_final_valid?(literal, facts)
        refute transport_eof_final_valid?(mutate.(literal), facts)
      end

      for dimension <- [:trace?, :actor?, :workspace?, :privacy?, :registered?] do
        assert transport_eof_final_valid?(literal, facts)
        refute transport_eof_final_valid?(literal, Map.put(facts, dimension, false))
      end

      for cleanup <- [:missing, %{actor: :unconfirmed, owner: :normal}, %{actor: :confirmed, owner: :non_normal}] do
        assert transport_eof_final_valid?(literal, facts)
        refute transport_eof_final_valid?(literal, %{facts | cleanup: cleanup})
      end

      if scenario == :clean_frame_exit17 do
        for mutate <- [
              fn s -> put_in(s.eof.await, {elem(s.eof.await, 0), 0}) end,
              fn s -> put_in(s.eof.decode_call, nil) end,
              fn s -> put_in(s.eof.decode_return, nil) end,
              fn s -> put_in(s.eof.close_call, nil) end,
              fn s -> put_in(s.eof.close_return, nil) end,
              fn s -> put_in(s.eof.probe, nil) end
            ] do
          assert transport_eof_final_valid?(literal, facts)
          refute transport_eof_final_valid?(mutate.(literal), facts)
        end
      else
        for mutate <- [
              fn s -> put_in(s.eof.await, {elem(s.eof.await, 0), 17}) end,
              fn s -> put_in(s.eof.full_probe, [2]) end,
              fn s -> put_in(s.eof.decode_call, 2) end,
              fn s -> put_in(s.eof.decode_return, {3, true}) end,
              fn s -> put_in(s.eof.probe, 4) end,
              fn s -> %{s | stages: [{2, {:reader_eof, Enum.at(s.started, 1)}} | s.stages]} end
            ] do
          assert transport_eof_final_valid?(literal, facts)
          refute transport_eof_final_valid?(mutate.(literal), facts)
        end
      end
    end
  end
