  # TASK18_BACKEND_INVENTORY_CONTRACT_BEGIN
  test "backend inventory preserves named clients and accounts for a proved autovacuum separately" do
    baseline = [
      {101, "singularity_migration"}, {102, "singularity_migration"},
      {103, "singularity_runtime"}, {104, "singularity_runtime"},
      {105, "singularity_runtime"}, {106, "singularity_runtime"},
