      {123, "singularity_runtime"}, {124, "singularity_runtime"},
      {125, "singularity_runtime"}, {126, "singularity_runtime"},
      {127, "singularity_runtime"}, {128, "singularity_runtime"},
      {129, "singularity_runtime"}, {130, "singularity_runtime"},
      {131, "singularity_runtime"}, {132, "singularity_runtime"},
      {133, "singularity_runtime"}, {134, "singularity_runtime"},
      {135, "singularity_runtime"}, {136, "singularity_runtime"},
      {137, "singularity_runtime"}, {138, "singularity_runtime"},
      {139, "singularity_runtime"}, {140, "singularity_runtime"},
      {141, "singularity_runtime"}, {142, "singularity_runtime"}
    ]

    child = {143, "singularity_migration"}
    worker = %{
      pid: 144,
      datid: 2562145,
      usesysid: nil,
      backend_type: "autovacuum worker",
      backend_start_us: 1792546964726998
    }

    named_metadata =
      Enum.map(baseline ++ [child], fn {pid, _username} ->
        %{
          pid: pid,
          datid: 2562145,
          usesysid: 16384,
          backend_type: "client backend",
          backend_start_us: 1792546964000000 + pid
        }
      end)

    # These are synthetic direct-stack facts, not a live PostgreSQL capture.
    binding = %{
      observer: self(),
      key: make_ref(),
      operation: make_ref(),
      nonce: make_ref(),
      ordinary: :erlang.list_to_pid(~c"<0.701.0>"),
      admin: {:erlang.list_to_pid(~c"<0.702.0>"), make_ref()},
      custodian: {:erlang.list_to_pid(~c"<0.703.0>"), make_ref()},
      database: "synthetic_backend_inventory",
      database_oid: 2562145,
      stage: :baseline,
      columns: 2,
      baseline: baseline,
      child_pid: nil
    }

    context =
      Map.merge(binding, %{
        sequence: 1,
        scenario: :clean_frame,
        authority: :verified,
        capture: :complete,
        before_ns: 100,
        query_before_ns: 101,
        query_after_ns: 102,
        after_ns: 103,
        before: named_metadata ++ [worker],
        after: named_metadata ++ [worker]
      })

    named_rows = Enum.map(baseline, fn {pid, username} -> [pid, username] end)
    result = {:ok, %Postgrex.Result{rows: named_rows}}
    assert transport_backend_inventory(result, context, binding) == {:ok, {baseline, []}}

    for stage <- [:gate, :absence] do
      expected = %{binding | operation: make_ref(), columns: 3, stage: stage, child_pid: 143}
      facts = Map.merge(context, expected)
      rows = Enum.map(baseline, fn {pid, username} -> [pid, username, nil] end)
      assert transport_backend_inventory({:ok, %Postgrex.Result{rows: rows}}, facts, expected) ==
               {:ok, {baseline, []}}
    end

    expected = %{binding | operation: make_ref(), columns: 3, stage: :gate, child_pid: 143}
    facts = Map.merge(context, expected)
    rows = Enum.map(baseline ++ [child], fn {pid, username} -> [pid, username, nil] end)

    # The old strict mapper rejects this genuine NULL-role row. This is the RED.
    # Expected clients and worker are literal facts, never learned from the mapper.
    for {case_rows, expected_inventory} <- [
          {rows, {:ok, {baseline ++ [child], []}}},
          {rows ++ [[144, nil, nil]], {:ok, {baseline ++ [child], [worker]}}}
        ] do
      result = {:ok, %Postgrex.Result{rows: case_rows}}
      assert transport_backend_inventory(result, facts, expected) == expected_inventory
    end

    result = {:ok, %Postgrex.Result{rows: rows ++ [[144, nil, nil]]}}
    accepted = {:ok, {baseline ++ [child], [worker]}}

    # Literal cases cover both column shapes, multiple workers and signed clocks.
    worker2 = %{worker | pid: 145, backend_start_us: 1792546964727000}
    for {sample, evidence, bound, wanted} <- [
          {{:ok, %Postgrex.Result{rows: named_rows ++ [[144, nil]]}},
           context, binding, {:ok, {baseline, [worker]}}},
          {{:ok, %Postgrex.Result{rows: rows ++ [[144, nil, "autovacuum worker"], [145, nil, nil]]}},
           %{facts | before: named_metadata ++ [worker, worker2],
             after: named_metadata ++ [worker, worker2]},
           expected, {:ok, {baseline ++ [child], [worker, worker2]}}},
          {result, %{facts | before_ns: -103, query_before_ns: -102,
             query_after_ns: -101, after_ns: -100}, expected, accepted},
          {{:ok, %Postgrex.Result{rows: Enum.map(baseline ++ [child],
             fn {pid, username} -> [pid, username, "client backend"] end)}},
           facts, expected, {:ok, {baseline ++ [child], []}}}
        ] do
      assert transport_backend_inventory(sample, evidence, bound) == wanted
    end

    for mutate <- [
          fn c -> %{c | authority: :failed} end,
          fn c -> %{c | capture: :failed} end,
          fn c -> %{c | capture: :overflow} end,
          fn c -> %{c | sequence: 0} end,
          fn c -> %{c | before: :unavailable} end,
          fn c -> %{c | before: [nil]} end,
          fn c -> %{c | after: [%{worker | pid: 0}]} end,
          fn c -> %{c | after: :unavailable} end,
          fn c -> %{c | before: named_metadata} end,
          fn c -> %{c | after: named_metadata} end,
          fn c -> %{c | before: c.before ++ [worker]} end,
          fn c -> %{c | after: c.after ++ [worker]} end,
          fn c -> %{c | before: List.duplicate(worker, 65)} end,
          fn c -> %{c | after: List.duplicate(worker, 65)} end,
          fn c -> %{c | before: named_metadata ++ [%{worker | backend_start_us: 1}]} end,
          fn c -> %{c | after: named_metadata ++ [%{worker | backend_start_us: 1}]} end,
          fn c -> %{c | before: named_metadata ++ [%{worker | datid: 2562146}]} end,
          fn c -> %{c | after: named_metadata ++ [%{worker | datid: 2562146}]} end,
          fn c -> %{c | before: named_metadata ++ [%{worker | usesysid: 16384}],
            after: named_metadata ++ [%{worker | usesysid: 16384}]} end,
          fn c -> %{c | before: named_metadata ++ [%{worker | backend_type: "parallel worker"}],
            after: named_metadata ++ [%{worker | backend_type: "parallel worker"}]} end,
          fn c -> %{c | before: named_metadata ++ [%{worker | backend_start_us: 0}],
            after: named_metadata ++ [%{worker | backend_start_us: 0}]} end,
          fn c -> %{c | before_ns: 102} end,
          fn c -> %{c | query_after_ns: 100} end,
          fn c -> %{c | after_ns: 101} end,
          fn c -> %{c | before_ns: nil} end,
          fn c -> %{c | after_ns: 9_223_372_036_854_775_808} end,
          fn c -> %{c | operation: make_ref()} end,
          fn c -> Map.merge(c, %{key: make_ref(), operation: make_ref(), nonce: make_ref()}) end,
          fn c -> %{c | key: make_ref()} end,
          fn c -> %{c | nonce: make_ref()} end,
          fn c -> %{c | observer: :erlang.list_to_pid(~c"<0.704.0>")} end,
          fn c -> %{c | ordinary: :erlang.list_to_pid(~c"<0.704.0>")} end,
          fn c -> %{c | admin: {elem(c.admin, 0), make_ref()}} end,
          fn c -> %{c | custodian: {elem(c.custodian, 0), make_ref()}} end,
          fn c -> %{c | database: "foreign_inventory"} end,
          fn c -> %{c | database_oid: 2562146} end,
          fn c -> %{c | stage: :absence} end,
          fn c -> %{c | columns: 2} end,
          fn c -> %{c | baseline: tl(baseline)} end,
          fn c -> %{c | child_pid: 146} end
        ] do
      assert transport_backend_inventory(result, facts, expected) == accepted
      assert transport_backend_inventory(result, mutate.(facts), expected) == :error
    end

    for bad_rows <- [
          rows ++ [[144, nil, nil], [144, nil, nil]],
          rows ++ [[0, nil, nil]],
          rows ++ [[-1, nil, nil]],
          rows ++ [[2_147_483_648, nil, nil]],
          rows ++ [:invalid_row],
          rows ++ [["144", nil, nil]],
          rows ++ [[144, 7, nil]],
          rows ++ [[144, nil]],
          rows ++ [[144, nil, nil, nil]],
          rows ++ [[144, nil, "parallel worker"]],
          rows ++ [[144, nil, "unknown"]],
          rows ++ [[144, "singularity_runtime", nil]],
          rows ++ [[145, nil, nil]],
          rows ++ [[144, nil, nil] | List.duplicate([146, "singularity_runtime", nil], 22)],
          [[101, "singularity_migration", "autovacuum worker"] | tl(rows)],
          [[101, "singularity_migration", "unknown"] | tl(rows)]
        ] do
      assert transport_backend_inventory(result, facts, expected) == accepted
      assert transport_backend_inventory({:ok, %Postgrex.Result{rows: bad_rows}}, facts, expected) ==
               :error
    end

    for malformed <- [:error, {:error, :query_failed}, {:ok, %Postgrex.Result{rows: nil}}] do
      assert transport_backend_inventory(result, facts, expected) == accepted
      assert transport_backend_inventory(malformed, facts, expected) == :error
    end

    for excluded_pid <- [101, 143] do
      excluded_worker = %{worker | pid: excluded_pid}
      excluded_facts = %{facts | before: [excluded_worker], after: [excluded_worker]}
      excluded_result = {:ok, %Postgrex.Result{rows: [[excluded_pid, nil, nil]]}}
      assert transport_backend_inventory(result, facts, expected) == accepted
      assert transport_backend_inventory(excluded_result, excluded_facts, expected) == :error
    end

    # These are the actual caller membership checks, in addition to partitioning.
    for changed <- [
          tl(rows),
          List.replace_at(rows, 0, [146, "singularity_migration", nil]),
          List.replace_at(rows, 0, [101, "singularity_runtime", nil]),
          rows ++ [[146, "singularity_runtime", nil]],
          Enum.reverse(rows)
        ] do
      assert transport_backend_inventory(result, facts, expected) == accepted
      clients = transport_inventory_clients!(result, facts, expected)
      assert transport_require!(clients -- [child] == baseline) == :ok
      altered = {:ok, %Postgrex.Result{rows: changed ++ [[144, nil, nil]]}}
      altered_clients = transport_inventory_clients!(altered, facts, expected)
      assert catch_throw(transport_require!(altered_clients -- [child] == baseline)) ==
               :legacy_transport_observer
    end

    absence_binding = %{expected | stage: :absence, operation: make_ref()}
    absence_facts = Map.merge(facts, absence_binding)
    absence_rows = Enum.map(baseline, fn {pid, username} -> [pid, username, nil] end)
    absence_result = {:ok, %Postgrex.Result{rows: absence_rows ++ [[144, nil, nil]]}}

    for changed <- [tl(absence_rows), rows, absence_rows ++ [[146, "singularity_runtime", nil]]] do
      assert transport_backend_inventory(absence_result, absence_facts, absence_binding) ==
               {:ok, {baseline, [worker]}}
      clients = transport_inventory_clients!(absence_result, absence_facts, absence_binding)
      assert transport_require!(clients == baseline) == :ok
      altered = {:ok, %Postgrex.Result{rows: changed ++ [[144, nil, nil]]}}
      altered_clients = transport_inventory_clients!(altered, absence_facts, absence_binding)
      assert catch_throw(transport_require!(altered_clients == baseline)) ==
               :legacy_transport_observer
    end
  end

  test "backend inventory cleanup characterization preserves the actual actor and owner proof" do
    proof = %{valid?: true, physical?: true, workspace?: true, cleanup: :unobserved}
    receipt = %{actor: :confirmed, owner: :normal}
    closed = %{valid?: true, physical?: true, workspace?: true, cleanup: receipt}

    assert transport_cleanup_proof(proof, receipt) == closed

    for invalid <- [
          nil,
          %{actor: :unconfirmed, owner: :normal},
          %{actor: :confirmed, owner: :non_normal},
          %{actor: :confirmed, owner: :unconfirmed},
          %{actor: :confirmed, owner: :normal, foreign: true}
        ] do
      assert transport_cleanup_proof(proof, receipt) == closed
      rejected = transport_cleanup_proof(proof, invalid)
      refute rejected.valid?
      refute rejected.physical?
      assert rejected.workspace?
    end

    assert transport_cleanup_proof(proof, receipt) == closed
    assert transport_cleanup_proof(%{proof | valid?: false}, receipt) ==
             %{valid?: false, physical?: true, workspace?: true, cleanup: receipt}

    # Synthetic PD entries exercise only the real keyed acceptance predicate.
    # Actual nonce/reply/DOWN/drain closure remains a source and runtime obligation.
    key = make_ref()
    foreign = make_ref()
    stale = make_ref()

    try do
      for invalid <- [:missing, :failed, :unobserved, :disabled, true, %{close: :confirmed}] do
        Process.put({key, :backend_attribution_close}, :confirmed)
        assert transport_inventory_accept?(closed, key)
        if invalid == :missing,
          do: Process.delete({key, :backend_attribution_close}),
          else: Process.put({key, :backend_attribution_close}, invalid)
        refute transport_inventory_accept?(closed, key)
      end

      for other <- [foreign, stale] do
        Process.put({key, :backend_attribution_close}, :confirmed)
        assert transport_inventory_accept?(closed, key)
        Process.delete({key, :backend_attribution_close})
        Process.put({other, :backend_attribution_close}, :confirmed)
        refute transport_inventory_accept?(closed, key)
        Process.delete({other, :backend_attribution_close})
      end

      Process.put({key, :backend_attribution_close}, :confirmed)
      assert transport_inventory_accept?(closed, key)
      refute transport_inventory_accept?(%{closed | valid?: false}, key)
    after
      for owned_key <- [key, foreign, stale],
        do: Process.delete({owned_key, :backend_attribution_close})
    end

    # Synthetic lifecycle maps exercise the actual final persistence selector only.
    # They do not prove live sink failure, persistence or resource closure.
    enabled_sink = %{path: "synthetic-only"}
    empty = %{persistence: :unobserved, queued: 0, written: 0}
    written = %{persistence: :unobserved, queued: 2, written: 2}

    for {sink, lifecycle, wanted} <- [
          {:failed, empty, :failed},
          {:disabled, empty, :disabled},
          {enabled_sink, %{empty | persistence: :failed}, :failed},
          {enabled_sink, %{empty | persistence: :overflow}, :overflow}
        ] do
      assert transport_attribution_persistence(enabled_sink, empty) == :not_required
      assert transport_attribution_persistence(sink, lifecycle) == wanted
    end

    for {sink, lifecycle, wanted} <- [
          {:failed, written, :failed},
          {:disabled, written, :disabled},
          {enabled_sink, %{written | persistence: :failed}, :failed},
          {enabled_sink, %{written | persistence: :overflow}, :overflow},
          {enabled_sink, %{written | written: 0}, :failed},
          {enabled_sink, %{written | written: 1}, :failed},
          {enabled_sink, %{written | written: 3}, :failed},
          {enabled_sink, %{empty | written: 1}, :failed}
        ] do
      assert transport_attribution_persistence(enabled_sink, written) == :confirmed
      assert transport_attribution_persistence(sink, lifecycle) == wanted
    end
  end
  # TASK18_BACKEND_INVENTORY_CONTRACT_END

  # TASK18_WORKSPACE_ORACLE_CONTRACT_BEGIN
  test "workspace absence qualifies before a recreated-directory boundary is rejected" do
    transport_entrypoint!()
    control = transport_observation(:clean_frame)
    controlled? = control.outcome == {:ok, true} and control.valid? and control.private?
    assert controlled?, "the original clean transport must qualify before workspace checks"

    workspace? = Map.get(control, :workspace?, false)
    assert workspace?, "the clean transport must independently prove workspace removal"

    physical? = Map.get(control, :physical?, false)
    assert physical?, "workspace qualification must retain all original physical checks"
    cleanup? = Map.get(control, :cleanup) == %{actor: :confirmed, owner: :normal}
    assert cleanup?, "the clean observation must close its exact actor and normal owner"

    proof = transport_observation(:workspace_present)
    native? = proof.outcome == {:ok, true}
    assert native?, "the recreated-directory control must retain the real successful child"
    physical? = Map.get(proof, :physical?, false)
    assert physical?, "the negative control must independently retain physical closure"
    private? = proof.private?
    assert private?, "workspace observations must not disclose private records"
    cleanup? = Map.get(proof, :cleanup) == %{actor: :confirmed, owner: :normal}
    assert cleanup?, "the negative control must close its exact actor and normal owner"
    triggered? = Map.get(proof, :workspace_trigger?, false)
    assert triggered?, "the boundary control must actually recreate the bound directory"
    present? = Map.get(proof, :workspace_present?, false)
    assert present?, "the recreated workspace must actually remain at the checked boundary"
    rejected? = not Map.get(proof, :workspace?, true) and not proof.valid?
    assert rejected?, "a physically closed child must not qualify a present workspace"
  end

