  defp transport_workspace_valid?(%{
         key: key,
         owner: owner,
         caller: caller,
         destination: %{
           repo: Singularity.Storage.MigrationRepo,
           database: database,
           object_root: object_root
         },
         ready_required?: ready?,
         valid?: true,
         closed: closed,
         checkpoints: checkpoints,
         workspace:
           %{
             binding: binding,
             allocated_at: allocated,
             started: started,
             ack: ack,
             completed: completed,
             drop: drop,
             trigger: :unobserved,
             valid?: true
           } = workspace
       })
       when is_reference(key) and is_pid(owner) and is_pid(caller) and owner != caller and
              is_binary(database) and is_binary(object_root) and is_boolean(ready?) and
              is_integer(allocated) and is_integer(ack) and is_integer(closed) and
              is_map(checkpoints) and not is_struct(checkpoints) and map_size(workspace) == 8 do
    case binding do
      {^key, ^owner, ^caller, ^database, allocation, ^object_root, path, allocation_id, object_id}
      when is_binary(allocation) and is_binary(path) ->
        with true <- transport_workspace_path?(allocation),
             true <- object_root == Path.join(allocation, "objects"),
             true <- path == Path.join(allocation, "historical-build"),
             true <- transport_workspace_identity?(allocation_id),
             true <- transport_workspace_identity?(object_id),
             true <- allocation_id != object_id,
             {^binding, started_at, {:directory, target_id, 0o700}, ^allocation_id, ^object_id} <-
               started,
             true <- transport_workspace_identity?(target_id),
             true <- target_id not in [allocation_id, object_id],
             true <- is_integer(started_at) and allocated < started_at and started_at < ack,
             true <- ack < closed,
             {^binding, dropped_at, :enoent, ^allocation_id, ^object_id} <- drop,
             before_drop when is_integer(before_drop) <- checkpoints[:before_database_drop],
             true <- is_integer(dropped_at) and closed < dropped_at and dropped_at < before_drop do
          if ready? do
            case {completed, checkpoints[:ready]} do
              {{^binding, completed_at, :enoent, ^allocation_id, ^object_id}, ready_at}
              when is_integer(completed_at) and is_integer(ready_at) ->
                closed < completed_at and completed_at < ready_at and ready_at < dropped_at

              _ ->
                false
            end
          else
            completed == :unobserved and not Map.has_key?(checkpoints, :ready)
          end
        else
          _ -> false
        end

      _ ->
        false
    end
  end

  defp transport_workspace_valid?(_record), do: false

  defp transport_workspace_path?(path),
    do:
      String.valid?(path) and not String.contains?(path, <<0>>) and
        Path.type(path) == :absolute and Path.expand(path) == path

  defp transport_workspace_identity?({major, minor, inode}),
    do:
      is_integer(major) and major >= 0 and is_integer(minor) and minor >= 0 and
        is_integer(inode) and inode > 0

  defp transport_workspace_identity?(_), do: false

  defp transport_workspace_initial do
    %{
      binding: :unobserved,
      allocated_at: nil,
      started: :unobserved,
      ack: nil,
      completed: :unobserved,
      drop: :unobserved,
      trigger: :unobserved,
      valid?: true
    }
  end

  # All filesystem observations below are Ctest-private, explicitly opted in.
  defp transport_workspace_lstat(path) do
    case File.lstat(path) do
      {:ok, %File.Stat{type: :directory} = stat} ->
        {:directory, {stat.major_device, stat.minor_device, stat.inode},
         Bitwise.band(stat.mode, 0o7777)}

      {:ok, %File.Stat{type: :symlink}} ->
        :symlink

      {:ok, %File.Stat{}} ->
        :other_type

      {:error, :enoent} ->
        :enoent

      {:error, _} ->
        :other_error
    end
  end

  defp transport_workspace_directory_id(path) do
    case transport_workspace_lstat(path) do
      {:directory, identity, 0o700} -> identity
      _ -> :invalid
    end
  end

  defp transport_workspace_allocate(key, caller, %{
         owner: owner,
         caller: caller,
         names: %{database: database, storage_root: allocation}
       })
       when owner == self() and is_binary(database) and is_binary(allocation) do
    objects = Path.join(allocation, "objects")
    allocation_id = transport_workspace_directory_id(allocation)
    object_id = transport_workspace_directory_id(objects)

    binding =
      {key, owner, caller, database, allocation, objects,
       Path.join(allocation, "historical-build"), allocation_id, object_id}

    %{
      transport_workspace_initial()
      | binding: binding,
        allocated_at: System.monotonic_time(),
        valid?:
          transport_workspace_path?(allocation) and
            transport_workspace_identity?(allocation_id) and
            transport_workspace_identity?(object_id) and allocation_id != object_id
    }
  end

  defp transport_workspace_allocate(_key, _caller, _resources),
    do: %{transport_workspace_initial() | valid?: false}

  defp transport_workspace_sample({_, _, _, _, allocation, objects, path, _, _} = binding)
       when is_binary(allocation) and is_binary(objects) and is_binary(path) do
    allocation_id = transport_workspace_directory_id(allocation)
    object_id = transport_workspace_directory_id(objects)
    result = transport_workspace_lstat(path)

    stable? =
      allocation_id == transport_workspace_directory_id(allocation) and
        object_id == transport_workspace_directory_id(objects)

    {binding, System.monotonic_time(), if(stable?, do: result, else: :invalid), allocation_id,
     object_id}
  end

  defp transport_workspace_sample(_), do: :invalid

  defp transport_workspace_ancestors?(
         {_, _, _, _, _, _, _, allocation_id, object_id} = binding,
         {sample_binding, _, _, sampled_allocation, sampled_objects}
       ) do
    sample_binding == binding and transport_workspace_identity?(allocation_id) and
      transport_workspace_identity?(object_id) and allocation_id != object_id and
      sampled_allocation == allocation_id and sampled_objects == object_id
  end

  defp transport_workspace_ancestors?(_, _), do: false

  # Boundary recreated-directory control, not a helper removal mutant.
  defp transport_workspace_recreate(workspace, :workspace_present) do
    binding = workspace.binding
    absent = transport_workspace_sample(binding)

    with true <- workspace.valid? and transport_workspace_ancestors?(binding, absent),
         {^binding, _, :enoent, _, _} <- absent,
         rechecked <- transport_workspace_sample(binding),
         true <- transport_workspace_ancestors?(binding, rechecked),
         {^binding, _, :enoent, _, _} <- rechecked,
         {_, _, _, _, _, _, path, _, _} <- binding,
         :ok <- File.mkdir(path),
         :ok <- File.chmod(path, 0o700),
         {^binding, _, {:directory, identity, 0o700}, _, _} = present <-
           transport_workspace_sample(binding),
         true <- transport_workspace_identity?(identity),
         true <- transport_workspace_ancestors?(binding, present) do
      %{workspace | completed: present, trigger: absent}
    else
      _ -> %{workspace | completed: absent, valid?: false}
    end
  end

  defp transport_workspace_recreate(workspace, _scenario),
    do: %{workspace | completed: transport_workspace_sample(workspace.binding)}

  defp transport_workspace_checkpoint(parent, key, caller, _scenario, :root_created, resources) do
    workspace = transport_workspace_allocate(key, caller, resources)
    previous = Process.get({key, :workspace_owner})
    workspace = %{workspace | valid?: workspace.valid? and is_nil(previous)}
    Process.put({key, :workspace_owner}, workspace)
    send(parent, {key, :workspace_allocation, self(), caller, workspace})
  end

  defp transport_workspace_checkpoint(
         parent,
         key,
         _caller,
         scenario,
         :legacy_preparation_completed,
         _resources
       ) do
    workspace = Process.get({key, :workspace_owner}, transport_workspace_initial())

    workspace =
      if workspace.completed == :unobserved,
        do: transport_workspace_recreate(workspace, scenario),
        else: %{workspace | valid?: false}

    Process.put({key, :workspace_owner}, workspace)

    send(
      parent,
      {key, :workspace_boundary, :completed, self(), workspace.completed, workspace.trigger,
       workspace.valid?}
    )
  end

  defp transport_workspace_checkpoint(
         parent,
         key,
         _caller,
         _scenario,
         :before_database_drop,
         _resources
       ) do
    workspace = Process.get({key, :workspace_owner}, transport_workspace_initial())
    sample = transport_workspace_sample(workspace.binding)
    send(parent, {key, :workspace_boundary, :drop, self(), sample, :unobserved, workspace.valid?})
  end

  defp transport_workspace_checkpoint(_parent, _key, _caller, _scenario, _stage, _resources),
    do: :ok

  defp transport_workspace_initial_receive(key, owner, caller, workspace) do
    workspace =
      case workspace do
        %{
          binding: {^key, ^owner, ^caller, _, _, _, _, _, _},
          allocated_at: at,
          started: :unobserved,
          ack: nil,
          completed: :unobserved,
          drop: :unobserved,
          trigger: :unobserved,
          valid?: valid?
        }
        when map_size(workspace) == 8 and is_integer(at) and is_boolean(valid?) ->
          workspace

        _ ->
          %{transport_workspace_initial() | valid?: false}
      end

    case Process.get({key, :workspace_allocation}) do
      nil ->
        Process.put({key, :workspace_allocation}, workspace)

      _ ->
        Process.put(
          {key, :workspace_allocation},
          %{transport_workspace_initial() | valid?: false}
        )
    end
  end

  defp transport_workspace_started(%{workspace: workspace} = state) do
    sample = transport_workspace_sample(workspace.binding)
    valid? = workspace.valid? and workspace.started == :unobserved and is_nil(workspace.ack)

    %{
      state
      | workspace: %{workspace | started: sample, ack: System.monotonic_time(), valid?: valid?}
    }
  end

  defp transport_workspace_started(state), do: state

  defp transport_workspace_boundary(state, stage, sample, trigger, valid?) do
    workspace = state.workspace
    fresh? = Map.fetch!(workspace, stage) == :unobserved
    workspace = Map.put(workspace, stage, sample)

    %{
      state
      | workspace: %{
          workspace
          | trigger: if(stage == :completed, do: trigger, else: workspace.trigger),
            valid?: workspace.valid? and fresh? and valid? == true
        }
    }
  end

  defp transport_workspace_after_actor(state) do
    key = state.key
    owner = state.owner

    state =
      case Process.delete({key, :workspace_before_drop}) do
        at when is_integer(at) ->
          %{state | checkpoints: Map.put(state.checkpoints, :before_database_drop, at)}

        _ ->
          state
      end

    # The owner sends this receipt before the checkpoint actor_down consumed.
    # Selective after0 cannot add a new wait or borrow another owner's evidence.
    state =
      receive do
        {^key, :workspace_boundary, :drop, ^owner, sample, trigger, valid?} ->
          transport_workspace_boundary(state, :drop, sample, trigger, valid?)
      after
        0 -> state
      end

    receive do
      {^key, :workspace_boundary, :drop, ^owner, _, _, _} ->
        %{state | workspace: %{state.workspace | valid?: false}}
    after
      0 -> state
    end
  end

  defp transport_workspace_triggered?(%{binding: binding, trigger: trigger}) do
    case trigger do
      {^binding, at, :enoent, _, _} when is_integer(at) ->
        transport_workspace_ancestors?(binding, trigger)

      _ ->
        false
    end
  end

  defp transport_workspace_present?(%{binding: binding, completed: completed, drop: drop}) do
    case {completed, drop} do
      {{^binding, completed_at, {:directory, identity, 0o700}, _, _},
       {^binding, drop_at, {:directory, identity, 0o700}, _, _}}
      when is_integer(completed_at) and is_integer(drop_at) and completed_at < drop_at ->
        transport_workspace_identity?(identity) and
          transport_workspace_ancestors?(binding, completed) and
          transport_workspace_ancestors?(binding, drop)

      _ ->
        false
    end
  end

  # TASK18_WORKSPACE_ORACLE_CONTRACT_END

  defp transport_entrypoint! do
    present? =
      Code.ensure_loaded?(LegacyUpgradeRuntimeFixture) and
        function_exported?(LegacyUpgradeRuntimeFixture, :probe_transport!, 3)

    assert present?, "fixed legacy transport entrypoint is missing"
  end

  # TASK18_EOF_EXIT_OBSERVER_BEGIN
  defp transport_eof_initial do
    %{
      started_fact: nil, capture: nil, capture_owner: nil, capture_workers: nil,
      capture_handle: nil, handle: nil, run: nil, installed?: false, baseline?: false,
      ready: nil, pending_read: nil, read_calls: [], steps: [], results: [], full_probe: [], decode_call: nil,
      decode_return: nil, close_call: nil, close_return: nil, probe: nil,
      sql_pending: nil, await: nil, await_normalized: nil, await_handle: nil, full_probe_at: nil, body_complete: nil, downs: %{}, exit_reasons: %{}, fenced?: false
    }
  end

  defp transport_eof_snapshot do
    Map.new(@transport_eof_mfas, fn mfa ->
      {mfa, Enum.map([:traced, :match_spec, :meta, :meta_match_spec], &:erlang.trace_info(mfa, &1))}
    end)
  end

  defp transport_eof_pattern!(session, mfa, pattern, flags) do
    transport_require!(:trace.function(session, mfa, pattern, flags) == 1)
    transport_require!(:trace.info(session, mfa, :match_spec) == {:match_spec, pattern})
    transport_require!(:trace.info(session, mfa, :traced) ==
      {:traced, if(:local in flags, do: :local, else: :global)})
    transport_require!(:trace.info(session, mfa, :meta) in [{:meta, false}, {:meta, []}])
    transport_require!(:trace.info(session, mfa, :meta_match_spec) == {:meta_match_spec, false})
  end

  defp transport_eof_trace_start(scenario, session, owner, actor)
       when scenario in @transport_eof_modes do
    before = transport_eof_snapshot()
    for mfa <- @transport_eof_mfas do
      transport_require!(:trace.info(session, mfa, :traced) == {:traced, false})
      transport_require!(:erlang.trace_info(mfa, :traced) == {:traced, false})
      transport_require!(:erlang.trace_info(mfa, :match_spec) == {:match_spec, false})
      transport_require!(:erlang.trace_info(mfa, :meta) in [{:meta, false}, {:meta, []}])
      transport_require!(:erlang.trace_info(mfa, :meta_match_spec) == {:meta_match_spec, false})
    end
    transport_require!(:trace.info(session, owner, :flags) == {:flags, []})
    transport_require!(:trace.info(session, owner, :tracer) == {:tracer, []})

    pattern = [
      {[%{run: :"$1", handle: :"$2", reader: :"$3", writer: :"$4",
           pending_observer: self(), caller: actor, primary: nil, receipt: nil, stdin_closed: false}],
       [
         {:is_reference, :"$1"}, {:is_map, :"$2"}, {:==, {:map_size, :"$2"}, 5},
         {:==, {:map_get, :__struct__, :"$2"}, ExCmd.Process},
         {:==, {:map_get, :owner, :"$2"}, owner},
         {:is_pid, {:map_get, :pid, :"$2"}},
         {:is_reference, {:map_get, :monitor_ref, :"$2"}},
         {:is_reference, {:map_get, :exit_ref, :"$2"}},
         {:is_pid, :"$3"}, {:is_pid, :"$4"}
       ], [{:message, {{:legacy_eof_owner_state, :"$1", :"$2", :"$3", :"$4"}}}]}
    ]
    transport_eof_pattern!(session, {LegacyUpgradeRuntimeFixture, :transport_receive, 1}, pattern, [:local])
    events =
      Enum.map(transport_event_patterns(actor, owner), fn {arguments, guards, []} ->
        [^actor, {:legacy_upgrade_transport, run, ^owner, stage}] = arguments
        {arguments, guards, [{:message, {{:legacy_eof_stage, run, transport_eof_stage_term(stage)}}}]}
      end)
    transport_eof_pattern!(session, {LegacyUpgradeRuntimeFixture, :transport_event, 2}, events, [:local])
    sql = [
      {[Singularity.Storage.MigrationRepo, @transport_sql,
        [:"$1", @transport_tag], [{:timeout, :"$2"}]],
       [{:is_binary, :"$1"}, {:is_integer, :"$2"}, {:>, :"$2", 0}, {:"=<", :"$2", 1_000}],
       [{:message, {{:legacy_eof_sql, :"$1"}}}, {:return_trace}]}
    ]
    transport_eof_pattern!(session, {Singularity.Storage.SafeSQL, :query!, 4}, sql, [:local])
    before
  end
  defp transport_eof_trace_start(_, _, _, _), do: :not_applicable

  defp transport_eof_stage_term(stage) when is_tuple(stage),
    do: {stage |> Tuple.to_list() |> Enum.map(&transport_eof_stage_term/1) |> List.to_tuple()}
  defp transport_eof_stage_term(stage), do: stage

  defp transport_eof_patterns!(session, handle, scenario) do
    transport_eof_pattern!(session, {ExCmd.Process, :await_exit, 2}, [
      {[handle, :"$1"], [{:is_integer, :"$1"}, {:>, :"$1", 50}, {:"=<", :"$1", 5_000}],
       [{:message, {{:legacy_eof_await, {:const, handle}, :"$1"}}}, {:return_trace}]}
    ], [])
    body = @transport_expected_json
    prefixes =
      case scenario do
        :clean_frame_exit17 -> [{:header, <<byte_size(body)::32>>, 4}, {:body, body, byte_size(body)}]
        :empty_eof -> [{:header, <<0, 0, 0, 0>>, 0}]
        :partial_header_eof -> [{:header, <<0, 0, 0, 0>>, 3}]
        :partial_body_eof -> [{:header, <<0, 0, 0, 8>>, 4}, {:body, <<123, 34, 112, 0, 0, 0, 0, 0>>, 3}]
      end

    exact =
      for {phase, expected, last} <- prefixes, consumed <- 0..last do
        remaining = byte_size(expected) - consumed
        prefix = binary_part(expected, 0, consumed)
        {[handle, remaining, :"$1"],
         [{:is_binary, :"$1"}, {:==, {:byte_size, :"$1"}, consumed}],
         [{:message, {{:legacy_eof_exact, phase, remaining, {:==, :"$1", {:const, prefix}}}}}]}
      end

    exact = exact ++ [
      {[handle, :_, :_], [], [{:message, {{:legacy_eof_invalid, :exact}}}]}
    ]
    transport_eof_pattern!(session, {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3}, exact, [:local])

    requests = [{:is_integer, :"$1"}, {:>, :"$1", 0}, {:"=<", :"$1", 4_096}]
    results = [
      {[handle, :"$1", :eof], requests, [{:message, {{:legacy_eof_result, :"$1", :eof}}}]},
      {[handle, :"$1", {:ok, :_}], requests, [{:message, {{:legacy_eof_result, :"$1", :chunk}}}]},
      {[handle, :_, :_], [], [{:message, {{:legacy_eof_invalid, :read_result}}}]}
    ]
    transport_eof_pattern!(session, {LegacyUpgradeRuntimeFixture, :transport_read_result, 3}, results, [:local])
    transport_eof_pattern!(session, {ExCmd.Process, :read, 2}, [
      {[handle, :"$1"], requests, [{:message, {{:legacy_eof_read_request, :"$1"}}}]}
    ], [])
    transport_eof_pattern!(session, {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1}, [
      {[:"$1"], [], [{:message, {{:legacy_eof_decode, {:==, :"$1", {:const, frame(body)}}}}}, {:return_trace}]}
    ], [:local])
    transport_eof_pattern!(session, {LegacyUpgradeRuntimeFixture, :transport_full_probe, 4}, [
      {[:_, :_, handle, :_], [], [{:message, {{:legacy_eof_full_probe, true}}}]}
    ], [:local])
    transport_eof_pattern!(session, {ExCmd.Process, :close_stdin, 1}, [
      {[handle], [], [{:message, {{:legacy_eof_close, true}}}, {:return_trace}]}
    ], [])
  end

  defp transport_eof_join(%{eof: %{started_fact: nil}} = state), do: state
  defp transport_eof_join(%{eof: %{capture: nil}} = state), do: state
  defp transport_eof_join(state) do
    e = state.eof
    {run, workers, started_at} = e.started_fact
    [command, reader, writer] = workers
    handle = e.capture_handle
    transport_require!(is_nil(state.started) and e.capture_owner == state.owner)
    transport_require!(e.run == run and e.capture_workers == workers and started_at < e.capture)
    transport_require!(Enum.sort(Map.keys(handle)) == Enum.sort([:__struct__, :owner, :pid, :monitor_ref, :exit_ref]))
    transport_require!(handle.__struct__ == ExCmd.Process and handle.owner == state.owner and handle.pid == command)
    transport_require!(is_reference(handle.monitor_ref) and is_reference(handle.exit_ref) and handle.monitor_ref != handle.exit_ref)
    transport_require!(length(Enum.uniq(workers)) == 3 and Enum.all?(workers, &Process.alive?/1))
    session = Process.get({state.key, :session})
    transport_eof_patterns!(session, handle, state.scenario)

    for worker <- workers do
      transport_require!([:erlang.trace_info(worker, :flags), :erlang.trace_info(worker, :tracer)] ==
        [{:flags, []}, {:tracer, []}])
      transport_require!(:trace.info(session, worker, :flags) == {:flags, []})
      transport_require!(:trace.info(session, worker, :tracer) == {:tracer, []})
      flags = [:procs, :monotonic_timestamp] ++ if(worker in [reader, writer], do: [:call, :arity], else: [])
      transport_require!(:trace.process(session, worker, true, flags) == 1)
      {:flags, installed} = :trace.info(session, worker, :flags)
      transport_require!(Enum.sort(installed) == Enum.sort(flags))
      transport_require!(:trace.info(session, worker, :tracer) == {:tracer, self()})
    end

    {:flags, owner_flags} = :trace.info(session, state.owner, :flags)
    transport_require!(Enum.sort(owner_flags) == Enum.sort([:call, :arity, :monotonic_timestamp]))
    transport_require!(:trace.info(session, state.owner, :tracer) == {:tracer, self()})
    monitors = Map.new(workers, &{Process.monitor(&1), &1})
    state = transport_workspace_started(state)
    ready = System.monotonic_time()
    transport_require!(Enum.all?(workers, &Process.alive?/1))
    send(state.owner, {run, :observer_ready, self()})
    %{state | started: workers, monitors: monitors,
      eof: %{e | handle: handle, installed?: true, baseline?: true, ready: ready}}
  end

  defp transport_eof_exact(state, reader, phase, remaining, expected?, at) do
    e = state.eof
    last = List.last(e.steps)
    result = List.last(e.results)
    ordered? =
      case {last, result} do
        {nil, nil} -> phase == :header and remaining == 4 and e.ready < at
        {{previous, ^phase, old, true}, {read_at, request, :chunk}} ->
          previous < read_at and read_at < at and request == min(4_096, old) and remaining < old
        {{previous, :header, 0, true}, {read_at, _, :chunk}} ->
          phase == :body and read_at < previous and previous < at and
            remaining == if(state.scenario == :partial_body_eof, do: 8, else: byte_size(@transport_expected_json))
        _ -> false
      end
    valid? = state.started != nil and reader == Enum.at(state.started, 1) and expected? and
      is_integer(at) and remaining >= 0 and length(e.steps) < 4_102 and ordered?
    %{state | valid?: state.valid? and valid?,
      eof: %{e | steps: e.steps ++ [{at, phase, remaining, expected?}],
        body_complete: if(phase == :body and remaining == 0, do: at, else: e.body_complete)}}
  end

  defp transport_eof_result(state, reader, request, category, at) do
    e = state.eof
    last = List.last(e.steps)
    previous = List.last(e.results)
    probe? = state.scenario == :clean_frame_exit17 and is_integer(e.probe)
    expected_request =
      if probe? do
        1
      else
        case last do
          {_, _, remaining, true} -> min(4_096, remaining)
          _ -> nil
        end
      end
    lower =
      if probe? do
        e.probe
      else
        case last do
          {step_at, _, _, _} -> step_at
          _ -> nil
        end
      end
    valid? = state.started != nil and reader == Enum.at(state.started, 1) and
      category in [:chunk, :eof] and is_integer(lower) and lower < at and
      request == expected_request and match?({^request, _}, e.pending_read) and
      elem(e.pending_read, 1) < at and length(e.results) < 4_101 and
      (is_nil(previous) or elem(previous, 0) < lower)
    %{state | valid?: state.valid? and valid?,
      eof: %{e | pending_read: nil, results: e.results ++ [{at, request, category}]}}
  end

  defp transport_eof_fence(%{scenario: scenario} = state, session)
       when scenario in @transport_eof_modes do
    state = Enum.reduce([state.owner | state.started || []], state, fn pid, acc ->
      transport_deadline_fence(acc, session, pid)
    end)
    state = transport_eof_tail(state, 0)
    %{state | eof: %{state.eof | fenced?: true}}
  end
  defp transport_eof_fence(state, _), do: state

  defp transport_eof_tail(state, 64), do: %{state | valid?: false}
  defp transport_eof_tail(state, count) do
    receive do
      message -> transport_eof_tail(transport_message(message, state), count + 1)
    after
      0 -> state
    end
  end

  defp transport_eof_sequence_valid?(scenario, e) do
    header = Enum.take_while(e.steps, fn {_, phase, _, _} -> phase == :header end)
    body = Enum.drop(e.steps, length(header))
    complete? = scenario == :clean_frame_exit17
    body? = scenario in [:clean_frame_exit17, :partial_body_eof]
    header_end = if scenario == :partial_header_eof, do: 1, else: if(scenario == :empty_eof, do: 4, else: 0)
    body_size = if complete?, do: byte_size(@transport_expected_json), else: 8
    body_end = if complete?, do: 0, else: 5
    shape? = match?([{_, :header, 4, true} | _], header) and
      elem(List.last(header), 2) == header_end and elem(hd(header), 0) > e.ready and
      if(body?,
        do: match?([{_, :body, ^body_size, true} | _], body) and elem(List.last(body), 2) == body_end,
        else: body == [])
    pairs = Enum.chunk_every(e.steps, 2, 1, :discard)
    descending? = Enum.all?(pairs, fn
      [{a, phase, old, true}, {b, phase, new, true}] -> a < b and new < old
      [{a, :header, 0, true}, {b, :body, _, true}] -> a < b
      _ -> false
    end)
    intervals = Enum.flat_map(pairs, fn
      [{a, phase, remaining, true}, {b, phase, _, true}] -> [{a, b, min(4_096, remaining)}]
      _ -> []
    end)
    chunks = Enum.filter(e.results, fn {_, _, category} -> category == :chunk end)
    chunk_calls = Enum.take(e.read_calls, length(chunks))
    chunk_order? = length(chunks) == length(intervals) and length(chunk_calls) == length(intervals) and
      Enum.all?(Enum.zip([intervals, chunks, chunk_calls]), fn
        {{lower, upper, request}, {returned, actual, :chunk}, {called, requested}} ->
          is_integer(called) and is_integer(returned) and request == actual and actual == requested and
            lower < called and called < returned and returned < upper
      end)
    {eof_at, request, :eof} = List.last(e.results)
    {called, requested} = List.last(e.read_calls)
    last_step = elem(List.last(e.steps), 0)
    shape? and descending? and chunk_order? and
      Enum.count(e.results, fn {_, _, category} -> category == :eof end) == 1 and
      length(e.results) == length(chunks) + 1 and length(e.read_calls) == length(e.results) and
      is_integer(called) and is_integer(eof_at) and requested == request and
      last_step < called and called < eof_at and
      (not complete? or e.probe == called)
  rescue
    _ -> false
  catch
    _, _ -> false
  end

  defp transport_eof_valid?(%{scenario: scenario, eof: e} = state)
       when scenario in @transport_eof_modes do
    workers = state.started
    handle = e.handle
    stages = Enum.map(state.stages, &elem(&1, 1))
    status = if scenario == :clean_frame_exit17, do: :nonzero, else: :zero
    code = if scenario == :clean_frame_exit17, do: 17, else: 0
    result = List.last(e.results)
    final_request = %{clean_frame_exit17: 1, empty_eof: 4, partial_header_eof: 1, partial_body_eof: 5}[scenario]

    common? =
      state.valid? and state.gate and state.absent? and is_integer(state.child) and
        transport_eof_sequence_valid?(scenario, e) and
        is_list(workers) and length(workers) == 3 and
        e.capture_owner == state.owner and e.capture_workers == workers and e.run == state.run and
        handle == e.capture_handle and is_map(handle) and handle.owner == state.owner and handle.pid == hd(workers) and
        is_reference(handle.monitor_ref) and is_reference(handle.exit_ref) and
        is_nil(e.pending_read) and length(e.read_calls) == length(e.results) and
        Enum.all?(Enum.zip(e.read_calls, e.results), fn {{called, n}, {returned, n2, _}} -> n == n2 and called < returned end) and
        e.await_handle == handle and e.installed? and e.baseline? and e.fenced? and
        is_integer(e.capture) and is_integer(e.ready) and e.capture < e.ready and
        e.started_fact == {state.run, workers, elem(hd(state.stages), 0)} and
        elem(hd(state.stages), 0) < e.capture and
        state.queued == stages and not Map.has_key?(state.checkpoints, :ready) and
        is_integer(state.await_call) and state.await_return == e.await_normalized and
        e.await == {elem(state.await_return, 0), code} and elem(state.await_return, 1) == status and
        state.await_call < elem(state.await_return, 0) and
        is_integer(state.sql_call) and elem(state.await_return, 0) < state.sql_call and
        is_integer(state.sql_zero) and state.sql_call < state.sql_zero and
        is_integer(state.closed) and state.sql_zero < state.closed and
        is_integer(state.checkpoints[:before_database_drop]) and state.closed < state.checkpoints[:before_database_drop] and
        Enum.all?(workers, fn pid ->
          MapSet.member?(state.down, pid) and is_integer(state.exits[pid]) and state.exits[pid] < state.closed and
            e.exit_reasons[pid] in [:normal, :killed] and
            case e.downs[pid] do
              {ref, reason} -> state.monitors[ref] == pid and reason in [:normal, :killed]
              _ -> false
            end
        end) and map_size(e.downs) == 3 and map_size(e.exit_reasons) == 3 and
        match?({_, ^final_request, :eof}, result) and elem(result, 0) < state.await_call and
        Enum.count(e.results, &(elem(&1, 2) == :eof)) == 1 and
        Enum.find_value(state.stages, fn {at, stage} -> if stage == {:await_started, hd(workers)}, do: at end) < state.await_call and
        elem(state.await_return, 0) < Enum.find_value(state.stages, fn {at, stage} -> if stage == {:await_complete, status}, do: at end) and
        Enum.find_value(state.stages, fn {at, stage} -> if stage == :workers_down, do: at end) < state.sql_call and
        state.sql_zero < Enum.find_value(state.stages, fn {at, stage} -> if stage == :child_connections_absent, do: at end) and
        Enum.find_value(state.stages, fn {at, stage} -> if stage == {:cleanup, :closed}, do: at end) == state.closed and
        Enum.all?(e.steps, fn {_, _, _, prefix?} -> prefix? == true end) and
        state.outcome == {:error, if(scenario == :clean_frame_exit17, do: :legacy_exit, else: :legacy_protocol), []} and
        Enum.all?(Enum.chunk_every(state.stages, 2, 1, :discard), fn [{a, _}, {b, _}] -> a < b end)

    if common? do
      [command, reader, writer] = workers
      suffix = [{:await_started, command}, {:await_complete, status}, :workers_down,
        :child_connections_absent, {:cleanup, :closed}]
      first = [{:started, command, reader, writer}]
      if scenario == :clean_frame_exit17 do
        common? and stages == first ++ [{:stdin_closed, writer}, {:reader_eof, reader}] ++ suffix and
          e.full_probe == [e.full_probe_at] and is_integer(e.full_probe_at) and
          is_integer(e.decode_call) and e.full_probe_at < e.decode_call and
          match?({_, true}, e.decode_return) and e.decode_call < elem(e.decode_return, 0) and
          is_integer(e.close_call) and elem(e.decode_return, 0) < e.close_call and
          is_integer(e.close_return) and e.close_call < e.close_return and
          is_integer(e.probe) and e.close_return < e.probe and e.probe < elem(result, 0) and
          e.close_return < Enum.find_value(state.stages, fn {at, stage} -> if stage == {:stdin_closed, writer}, do: at end) and
          Enum.find_value(state.stages, fn {at, stage} -> if stage == {:stdin_closed, writer}, do: at end) < e.probe and
          elem(result, 0) < Enum.find_value(state.stages, fn {at, stage} -> if stage == {:reader_eof, reader}, do: at end) and
          List.last(e.steps) == {e.body_complete, :body, 0, true} and
          e.body_complete < e.full_probe_at
      else
        rejection = {:reader_rejected, :legacy_protocol}
        allowed = [first ++ [rejection] ++ suffix, first ++ [rejection, {:stdin_closed, writer}] ++ suffix]
        final_step = %{empty_eof: {:header, 4}, partial_header_eof: {:header, 1}, partial_body_eof: {:body, 5}}[scenario]
        case List.last(e.steps) do
          {step_at, phase, remaining, true} ->
            stages in allowed and {phase, remaining} == final_step and step_at < elem(result, 0) and
              e.full_probe == [] and is_nil(e.decode_call) and is_nil(e.decode_return) and is_nil(e.probe)
          _ -> false
        end
      end
    else
      false
    end
  rescue
    _ -> false
  catch
    _, _ -> false
  end

  defp transport_eof_final_valid?(state, %{
         trace?: true, actor?: true, workspace?: true, privacy?: true, registered?: true,
         cleanup: %{actor: :confirmed, owner: :normal}
       }), do: transport_eof_valid?(state)
  defp transport_eof_final_valid?(_, _), do: false

  defp transport_eof_literal(scenario) do
    owner = self()
    actor = Process.whereis(:init)
    workers = [Process.whereis(:code_server), Process.whereis(:logger), Process.whereis(:application_controller)]
    [command, reader, writer] = workers
    run = make_ref()
    refs = Enum.map(workers, fn _ -> make_ref() end)
    monitors = Map.new(Enum.zip(refs, workers))
    handle = %ExCmd.Process{pid: command, owner: owner, monitor_ref: make_ref(), exit_ref: make_ref()}
    complete? = scenario == :clean_frame_exit17
    size = byte_size(@transport_expected_json)
    {steps, results, calls} = case scenario do
      :clean_frame_exit17 ->
        {[{40, :header, 4, true}, {60, :header, 0, true}, {70, :body, size, true}, {90, :body, 0, true}],
         [{50, 4, :chunk}, {80, size, :chunk}, {170, 1, :eof}],
         [{45, 4}, {75, size}, {160, 1}]}
      :empty_eof ->
        {[{40, :header, 4, true}], [{50, 4, :eof}], [{45, 4}]}
      :partial_header_eof ->
        {[{40, :header, 4, true}, {60, :header, 1, true}],
         [{50, 4, :chunk}, {70, 1, :eof}], [{45, 4}, {65, 1}]}
      :partial_body_eof ->
        {[{40, :header, 4, true}, {60, :header, 0, true}, {70, :body, 8, true}, {90, :body, 5, true}],
         [{50, 4, :chunk}, {80, 8, :chunk}, {100, 5, :eof}],
         [{45, 4}, {75, 8}, {95, 5}]}
    end
    status = if complete?, do: :nonzero, else: :zero
    code = if complete?, do: 17, else: 0
    stage_values = [{:started, command, reader, writer}] ++
      if(complete?, do: [{:stdin_closed, writer}, {:reader_eof, reader}],
        else: [{:reader_rejected, :legacy_protocol}]) ++
      [{:await_started, command}, {:await_complete, status}, :workers_down,
       :child_connections_absent, {:cleanup, :closed}]
    times = if complete?, do: [10, 150, 180, 190, 220, 240, 270, 280],
      else: [10, 110, 190, 220, 240, 270, 280]
    stages = Enum.zip(times, stage_values)
    e = Map.merge(transport_eof_initial(), %{
      started_fact: {run, workers, 10}, capture: 20, capture_owner: owner, capture_workers: workers,
      capture_handle: handle, handle: handle, run: run, installed?: true, baseline?: true, ready: 30,
      steps: steps, results: results, read_calls: calls, full_probe: if(complete?, do: [100], else: []),
      full_probe_at: if(complete?, do: 100, else: nil), body_complete: if(complete?, do: 90, else: nil),
      decode_call: if(complete?, do: 110, else: nil), decode_return: if(complete?, do: {120, true}, else: nil),
      close_call: if(complete?, do: 130, else: nil), close_return: if(complete?, do: 140, else: nil),
      probe: if(complete?, do: 160, else: nil), await: {210, code}, await_normalized: {210, status},
      await_handle: handle, downs: Map.new(Enum.zip(workers, refs), fn {pid, ref} -> {pid, {ref, :normal}} end),
      exit_reasons: Map.new(workers, &{&1, :normal}), fenced?: true
    })
    state = %{
      key: make_ref(), owner: owner, actor: actor, run: run, scenario: scenario, started: workers,
      monitors: monitors, down: MapSet.new(workers), exits: Map.new(workers, &{&1, 230}),
      stages: stages, queued: stage_values, await_call: 200, await_return: {210, status},
      sql_call: 250, sql_zero: 260, closed: 280, checkpoints: %{before_database_drop: 290},
      valid?: true, gate: true, absent?: true, child: 1, eof: e,
      outcome: {:error, if(complete?, do: :legacy_exit, else: :legacy_protocol), []}
    }
    {state, %{trace?: true, actor?: true, workspace?: true, privacy?: true,
      registered?: true, cleanup: %{actor: :confirmed, owner: :normal}}}
  end
  # TASK18_EOF_EXIT_OBSERVER_END

  defp transport_scenario!(scenario) do
    supported? =
      try do
        apply(LegacyUpgradeRuntimeFixture, :probe_transport!, [%{}, %{}, scenario])
        false
      rescue
        _ in FunctionClauseError -> false
      catch
        :throw, {:legacy_preparation_failed, :legacy_identity} -> true
        _, _ -> false
      end

    assert supported?, "fixed legacy transport scenario support is missing"
  end

  defp transport_observation(scenario)
       when scenario in [
              :clean_frame,
              :stderr_prefix,
              :malformed_payload,
              :short_frame_trailer,
              :ascii_stderr_flood,
              :declared_oversize,
              :full_frame_eof,
              :full_frame_overrun,
              :blocked_reader_control,
              :reader_down,
              :writer_wait_control,
              :writer_down,
              :deadline_control,
              :deadline_expired,
              :workspace_present
            ] or scenario in @transport_eof_modes do
    key = make_ref()
    ua_control_key(key)
    Process.delete({key, :diagnostic7_backend_query})
    Process.delete({key, :diagnostic8_absence})

    try do
      logs =
        ExUnit.CaptureLog.capture_log(fn ->
          stderr =
            ExUnit.CaptureIO.capture_io(:stderr, fn ->
              stdout =
                ExUnit.CaptureIO.capture_io(fn ->
                  proof =
                    try do
                      transport_run(key, scenario)
                    rescue
                      error ->
                        Process.put(
                          {key, :diagnostic6_caught},
                          transport_diagnostic6_caught(:error, error)
                        )

                        %{outcome: :observer_failed, valid?: false, private?: false}
                    catch
                      kind, reason ->
                        Process.put(
                          {key, :diagnostic6_caught},
                          transport_diagnostic6_caught(kind, reason)
                        )

                        %{outcome: :observer_failed, valid?: false, private?: false}
                    end

                  cleanup = Process.get({key, :cleanup_receipt})
                  proof = transport_cleanup_proof(proof, cleanup)
                  proof = %{proof | valid?: transport_inventory_accept?(proof, key)}

                  proof =
                    case Process.get({key, :writer_evidence}) do
                      {state, facts} ->
                        writer? =
                          transport_writer_final_valid?(state, %{facts | cleanup: cleanup})

                        %{proof | valid?: proof.valid? and writer?}

                      nil ->
                        proof
                    end

                  proof =
                    case Process.get({key, :deadline_evidence}) do
                      {state, facts} ->
                        deadline? =
                          transport_deadline_final_valid?(state, %{facts | cleanup: cleanup})

                        %{proof | valid?: proof.valid? and deadline?}

                      nil ->
                        proof
                    end

                  proof =
                    case Process.get({key, :eof_evidence}) do
                      {state, facts} ->
                        %{proof | valid?: proof.valid? and
                          transport_eof_final_valid?(state, %{facts | cleanup: cleanup})}
                      nil ->
                        proof
                    end

                  Process.put({key, :proof}, proof)
                end)

              Process.put({key, :stdout_private}, not transport_contains?(stdout))
            end)

          Process.put({key, :stderr_private}, not transport_contains?(stderr))
        end)

      proof =
        Process.get({key, :proof}, %{outcome: :observer_failed, valid?: false, private?: false})

      private? =
        proof.private? and Process.get({key, :stdout_private}) == true and
          Process.get({key, :stderr_private}) == true and not transport_contains?(logs)

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      outcome =
        case proof.outcome do
          {:ok, true} ->
            :ok

          {:ok, false} ->
            :receipt_mismatch

          {:error, :legacy_protocol, []} ->
            :legacy_protocol

          {:error, :legacy_output_limit, []} ->
            :legacy_output_limit

          {:error, :legacy_exit, []} when scenario == :clean_frame_exit17 ->
            :legacy_exit

          {:error, category, []}
          when scenario in [
                 :blocked_reader_control,
                 :reader_down,
                 :writer_wait_control,
                 :writer_down,
                 :deadline_control,
                 :deadline_expired
               ] and
                 category in [:legacy_pipe, :legacy_deadline, :legacy_exit, :legacy_caller_down] ->
            category

          :observer_failed ->
            :observer_failed

          :unexpected_preparation ->
            :unexpected_preparation

          :actor_failed ->
            :actor_failed

          _ ->
            :unexpected
        end

      migration =
        case Process.get({__MODULE__, :transport_baseline_migration}) do
          {observed, expected} when observed in 0..100 and expected in 0..100 ->
            %{observed: observed, expected: expected}

          _ ->
            :unobserved
        end

      IO.puts(
        "Task18 actual transport observation: " <>
          inspect(%{
            scenario: scenario,
            outcome: outcome,
            valid: proof.valid?,
            private: private?,
            phase: Process.get({key, :observer_phase}, :unknown),
            migration: migration
          })
      )

      transport_attribution_safe(fn -> transport_attribution_emit(key, scenario) end, :failed)

      if scenario in [:full_frame_eof, :full_frame_overrun] do
        IO.puts(
          "Task18 full-boundary parser-order observation: " <>
            inspect(%{
              scenario: scenario,
              physical: proof.valid?,
              private: private?,
              ordered: Map.get(proof, :full_ordered?, false)
            })
        )
      end

      # TASK18_TRANSPORT_DIAGNOSTIC_END

      if scenario in @transport_eof_modes do
        diagnostic =
          case Process.get({key, :eof_evidence}) do
            {state, facts} ->
              e = state.eof
              exit = case e.await do
                {_, code} when code in [0, 17] -> code
                _ -> :unobserved
              end
              request = case List.last(e.results) do
                {_, n, :eof} when n in [1, 4, 5] -> n
                _ -> :unobserved
              end
              %{
                scenario: scenario, actual_exit: exit, eof_request: request,
                prefixes: Enum.all?(e.steps, fn {_, _, _, expected?} -> expected? == true end),
                decoded: not is_nil(e.decode_call), ready: Map.has_key?(state.checkpoints, :ready),
                ordered: transport_eof_valid?(state), trace: facts.trace?,
                workspace: facts.workspace?, actor: facts.actor?, physical: proof.physical?,
                cleanup: proof.cleanup == %{actor: :confirmed, owner: :normal}
              }
            _ ->
              %{scenario: scenario, observed: false}
          end
        IO.puts("Task18 EOF/exit observation: " <> inspect(diagnostic))
      end

      # TASK18_TRANSPORT_DIAGNOSTIC2_BEGIN
      IO.puts(
        "Task18 transport diagnostic2: " <>
          inspect(%{
            snapshot: Process.get({key, :diagnostic2_snapshot}, :unobserved),
            preparation: Process.get({key, :diagnostic2_preparation}, :unobserved)
          })
      )

      # TASK18_TRANSPORT_DIAGNOSTIC2_END
      # TASK18_TRANSPORT_DIAGNOSTIC3_BEGIN
      IO.puts(
        "Task18 transport diagnostic3: " <>
          inspect(Process.get({key, :diagnostic3_protocols}, :unobserved))
      )

      # TASK18_TRANSPORT_DIAGNOSTIC3_END
      # TASK18_TRANSPORT_DIAGNOSTIC4_BEGIN
      IO.puts(
        "Task18 transport diagnostic4: " <>
          inspect(%{
            receive_exit: Process.get({key, :diagnostic4_receive_exit}, :unobserved),
            acquisition: Process.get({key, :diagnostic4_acquisition}, :unobserved)
          })
      )

      # TASK18_TRANSPORT_DIAGNOSTIC4_END
      IO.puts("Task18 actor failure diagnostic: " <> inspect(transport_actor_failure_get(key)))
      # TASK18_TRANSPORT_DIAGNOSTIC5_BEGIN
      IO.puts(
        "Task18 transport diagnostic5: " <>
          inspect(Process.get({key, :diagnostic5_invalid}, :unobserved))
      )

      # TASK18_TRANSPORT_DIAGNOSTIC5_END
      IO.puts(
        "Task18 C3 diagnostic1: " <>
          inspect(%{
            gate: Process.get({key, :diagnostic1_gate}, :unobserved),
            initial: Process.get({key, :diagnostic1_initial}, :unobserved),
            preparation: Process.get({key, :diagnostic1_preparation}, :unobserved),
            emergency: Process.get({key, :diagnostic1_emergency}, :unobserved)
          })
      )

      IO.puts(
        "Task18 transport diagnostic6: " <>
          inspect(%{
            caught: Process.get({key, :diagnostic6_caught}, :unobserved),
            baseline_phase: Process.get({__MODULE__, :diagnostic6_baseline_phase}, :not_started),
            first_sample: Process.get({__MODULE__, :diagnostic6_first_sample}, :unobserved),
            baseline_query_result:
              Process.get({__MODULE__, :diagnostic6_baseline_query_result}, :unobserved),
            armed_wait: Process.get({key, :diagnostic6_armed}, :unobserved), inventory_rejection: transport_inventory_rejection_get(key)
          })
      )

      IO.puts(
        "Task18 transport diagnostic7: " <>
          inspect(Process.get({key, :diagnostic7_backend_query}, :unobserved),
            limit: :infinity,
            printable_limit: :infinity
          )
      )

      IO.puts(
        "Task18 transport diagnostic8 absence: " <>
          inspect(Process.get({key, :diagnostic8_absence}, :unobserved),
            limit: :infinity,
            printable_limit: :infinity
          )
      )

      %{proof | private?: private?}
    after
      for name <- [:proof, :stdout_private, :stderr_private], do: Process.delete({key, name})
      # TASK18_TRANSPORT_DIAGNOSTIC2_BEGIN
      Process.delete({key, :diagnostic2_snapshot})
      Process.delete({key, :diagnostic2_preparation})
      # TASK18_TRANSPORT_DIAGNOSTIC2_END
      # TASK18_TRANSPORT_DIAGNOSTIC3_BEGIN
      Process.delete({key, :diagnostic3_protocols})
      # TASK18_TRANSPORT_DIAGNOSTIC3_END
      # TASK18_TRANSPORT_DIAGNOSTIC4_BEGIN
      Process.delete({key, :diagnostic4_receive_exit})
      Process.delete({key, :diagnostic4_acquisition})
      Process.delete({key, :diagnostic_actor_failure})
      # TASK18_TRANSPORT_DIAGNOSTIC4_END
      # TASK18_TRANSPORT_DIAGNOSTIC5_BEGIN
      Process.delete({key, :diagnostic5_invalid})
      # TASK18_TRANSPORT_DIAGNOSTIC5_END
      for name <- [
            :diagnostic1_gate,
            :diagnostic1_initial,
            :diagnostic1_preparation,
            :diagnostic1_emergency
          ],
          do: Process.delete({key, name})

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.delete({key, :observer_phase})
      Process.delete({__MODULE__, :transport_baseline_migration})
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      Process.delete({key, :diagnostic6_caught})
      Process.delete({key, :diagnostic6_armed})
      Process.delete({key, :diagnostic7_backend_query})
      Process.delete({key, :diagnostic8_absence}); transport_inventory_rejection_clear(key)
      Process.delete({key, :cleanup_receipt})
      Process.delete({key, :c4_hold})
      Process.delete({key, :writer_evidence})
      Process.delete({key, :deadline_evidence})
      Process.delete({key, :eof_evidence})
      Process.delete({key, :workspace_allocation})
      Process.delete({key, :workspace_before_drop})
      Process.delete({key, {:cleanup_down, :actor}})
      Process.delete({key, {:cleanup_down, :owner}})
      Process.delete({__MODULE__, :diagnostic6_baseline_phase})
      Process.delete({__MODULE__, :diagnostic6_first_sample})
      Process.delete({__MODULE__, :diagnostic6_baseline_query_result})
      Process.delete({key, :backend_attribution_close})
      Process.delete({key, :backend_attribution_capture})
      Process.delete({key, :backend_attribution_lifecycle})
      case Process.get({__MODULE__, :backend_attribution_connection}) do
        {_, ^key} -> Process.delete({__MODULE__, :backend_attribution_connection})
        _ -> :ok
      end
    end
  end

  defp transport_run(key, scenario) do
    requested_scenario = scenario
    scenario = if scenario == :workspace_present, do: :clean_frame, else: scenario
    # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
    Process.put({key, :observer_phase}, :entry)
    # TASK18_TRANSPORT_DIAGNOSTIC_END
    parent = self()

    events =
      Enum.uniq(
        Enum.map(@transport_repos, &(&1.config()[:telemetry_prefix] ++ [:query])) ++
          [
            [:singularity, :authorization, :rls_denial],
            [:oban, :job, :start],
            [:oban, :job, :stop],
            [:oban, :job, :exception],
            [:singularity, :job, :retry],
            [:singularity, :outbox, :dispatch],
            [:singularity, :integrity, :failure]
          ]
      )

    handler = {__MODULE__, :transport_privacy, key}

    :ok =
      :telemetry.attach_many(
        handler,
        events,
        fn _event, measurements, metadata, _config ->
          private? =
            try do
              not transport_contains?(measurements) and not transport_contains?(metadata)
            rescue
              _ -> false
            catch
              _, _ -> false
            end

          send(parent, {key, :privacy, private?})
        end,
        nil
      )

    Process.put({key, :handler}, handler)

    try do
      ua_control? = ua_control_active?(key)
      {actor, actor_monitor} =
        spawn_monitor(fn ->
          ua_control_actor_gate(parent, key, ua_control?)
          transport_actor(parent, key, requested_scenario)
        end)
      ua_control_allocated(key, actor)

      Process.put({key, :actor}, {actor, actor_monitor})

      initial_deadline = System.monotonic_time(:millisecond) + 5_000

      {owner, destination} =
        transport_initial_owner(key, actor, actor_monitor, initial_deadline, true)

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.put({key, :observer_phase}, :prepare_received)
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      Process.put({key, :owner}, {owner, Process.monitor(owner)})

      options =
        Singularity.Storage.MigrationRepo.config()
        |> Keyword.drop([:url, :name])
        |> Keyword.put(:pool_size, 1)
        |> Keyword.put(:pool_count, 1)
        |> Keyword.put(:database, destination.database)
        |> Keyword.put(:parameters, application_name: @transport_observer_tag)

      transport_require!(options[:username] == "singularity_migration")
      {:ok, connection} = Postgrex.start_link(options)
      Process.unlink(connection)
      Process.put({key, :connection}, connection)
      transport_attribution_open(key, connection, destination.database, requested_scenario)
      repos = Map.new(@transport_repos, &{&1, Process.whereis(&1)})

      transport_require!(
        Enum.all?(repos, fn {_repo, pid} -> is_pid(pid) and Process.alive?(pid) end)
      )

      expected = transport_warm_repos()

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.put({key, :observer_phase}, :repos_warmed)
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      baseline =
        transport_parent_baseline(
          connection,
          destination.database,
          expected,
          nil,
          System.monotonic_time(:millisecond) + 5_000
        )

      ua_control_baseline(key, expected, baseline, repos)

      transport_rows(
        connection,
        "SELECT pg_advisory_lock($1::integer,$2::integer)",
        @transport_lock
      )

      Process.put({key, :locked}, true)

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.put({key, :observer_phase}, :advisory_locked)
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      transport_require!(
        Enum.all?(@transport_mfas, fn {module, _, _} -> Code.ensure_loaded?(module) end)
      )

      before = transport_legacy_trace(owner)
      c4_before = transport_c4_trace_patterns(scenario)
      writer_before = transport_writer_trace_patterns(scenario)
      transport_require!(before.owner == [{:flags, []}, {:tracer, []}])
      session = :trace.session_create(:task18_fixed_transport, self(), [])
      Process.put({key, :session}, session)

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.put({key, :observer_phase}, :trace_created)
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      handle_pattern = %{
        __struct__: ExCmd.Process,
        pid: :"$1",
        owner: owner,
        monitor_ref: :"$2",
        exit_ref: :"$3"
      }

      transport_require!(
        :trace.function(
          session,
          {ExCmd.Process, :await_exit, 2},
          [
            {[handle_pattern, :"$4"],
             [
               {:is_pid, :"$1"},
               {:is_reference, :"$2"},
               {:is_reference, :"$3"},
               {:is_integer, :"$4"},
               {:>, :"$4", 50},
               {:"=<", :"$4", 5_000}
             ], [{:return_trace}]}
          ],
          []
        ) == 1
      )

      transport_require!(
        :trace.function(
          session,
          {LegacyUpgradeRuntimeFixture, :transport_event, 2},
          transport_event_patterns(actor, owner),
          [:local]
        ) == 1
      )

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.put({key, :observer_phase}, :event_pattern_set)
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      transport_require!(
        :trace.function(
          session,
          {Singularity.Storage.SafeSQL, :query!, 4},
          [
            {[
               Singularity.Storage.MigrationRepo,
               @transport_sql,
               [destination.database, @transport_tag],
               [{:timeout, :"$1"}]
             ], [{:is_integer, :"$1"}, {:>, :"$1", 0}, {:"=<", :"$1", 1_000}], [{:return_trace}]}
          ],
          [:local]
        ) == 1
      )

      eof_before = transport_eof_trace_start(scenario, session, owner, actor)
      owner_flags = [:call, :monotonic_timestamp] ++ if(scenario in @transport_eof_modes, do: [:arity], else: [])
      transport_require!(:trace.process(session, owner, true, owner_flags) == 1)
      deadline_before = transport_deadline_trace_start(key, scenario, session, owner, actor)
      ua_control_trace(key, owner, actor)
      send(owner, {key, :armed})

      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.put({key, :observer_phase}, :armed)
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      state = %{
        key: key,
        actor: actor,
        actor_monitor: actor_monitor,
        actor_closed: nil,
        actor_down: nil,
        owner: owner,
        caller: actor,
        destination: destination,
        scenario: scenario,
        workspace:
          Process.delete({key, :workspace_allocation}) ||
            %{transport_workspace_initial() | valid?: false},
        connection: connection,
        repos: repos,
        baseline: baseline,
        deadline: System.monotonic_time(:millisecond) + 50_000,
        gate: false,
        child: nil,
        started: nil,
        monitors: %{},
        down: MapSet.new(),
        exits: %{},
        run: nil,
        stages: [],
        queued: nil,
        outcome: nil,
        checkpoints: %{},
        await_call: nil,
        await_return: nil,
        decode_call: nil,
        decode_return: nil,
        probe_call: nil,
        probe_return: nil,
        header: %{start: nil, complete: nil, remaining: nil, requested: nil, steps: 0, reads: 0},
        full: transport_full_initial(),
        eof: transport_eof_initial(),
        c4: transport_c4_initial(),
        writer_loss: transport_writer_initial(scenario),
        deadline_loss: transport_deadline_initial(scenario, owner, actor),
        sql_call: nil,
        sql_zero: nil,
        closed: nil,
        absent?: false,
        valid?: true,
        private?: true
      }

      state = transport_loop(state)
      state = ua_control_after_loop(state)
      state = transport_eof_fence(state, session)
      {state, deadline_restored?} = transport_deadline_trace_close(state, deadline_before)
      # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
      Process.put({key, :observer_phase}, :observation_complete)
      # TASK18_TRANSPORT_DIAGNOSTIC_END
      transport_require!(:trace.session_destroy(session))
      Process.delete({key, :session})

      trace_restored? =
        transport_legacy_trace_patterns() == before.patterns and
          (not Process.alive?(owner) or transport_legacy_trace(owner).owner == before.owner) and
          transport_c4_trace_patterns(scenario) == c4_before and
          transport_writer_trace_patterns(scenario) == writer_before and deadline_restored? and
          (eof_before == :not_applicable or transport_eof_snapshot() == eof_before)

      if scenario in [
           :clean_frame,
           :full_frame_eof,
           :blocked_reader_control,
           :writer_wait_control,
           :deadline_control
         ],
         do: send(actor, {key, :close})

      actor_closed? = transport_actor_down(key, actor, actor_monitor, state)
      state = transport_workspace_after_actor(state)

      registered? =
        Enum.all?(events, fn event ->
          Enum.any?(:telemetry.list_handlers(event), &(&1.id == handler))
        end)

      physical? = transport_valid?(state) and trace_restored? and actor_closed? and registered?

      workspace? =
        transport_workspace_valid?(
          Map.put(
            state,
            :ready_required?,
            scenario in [
              :clean_frame,
              :full_frame_eof,
              :blocked_reader_control,
              :writer_wait_control,
              :deadline_control
            ]
          )
        )

      if scenario in @transport_eof_modes do
        Process.put({key, :eof_evidence}, {state, %{
          trace?: trace_restored?, actor?: actor_closed?, workspace?: workspace?,
          privacy?: state.private? and transport_privacy_tail(key),
          registered?: registered?, cleanup: nil
        }})
      end

      if scenario in [:writer_wait_control, :writer_down] do
        Process.put(
          {key, :writer_evidence},
          {state,
           %{
             trace?: trace_restored?,
             actor?: actor_closed?,
             workspace?: workspace?,
             privacy?: state.private? and transport_privacy_tail(key),
             registered?: registered?,
             cleanup: nil
           }}
        )
      end

      if scenario in [:deadline_control, :deadline_expired] do
        Process.put(
          {key, :deadline_evidence},
          {state,
           %{
             trace?: trace_restored?,
             actor?: actor_closed?,
             workspace?: workspace?,
             privacy?: state.private? and transport_privacy_tail(key),
             registered?: registered?,
             cleanup: nil
           }}
        )
      end

      %{
        outcome: state.outcome,
        valid?: physical? and workspace?,
        physical?: physical?,
        workspace?: workspace?,
        workspace_trigger?: transport_workspace_triggered?(state.workspace),
        workspace_present?: transport_workspace_present?(state.workspace),
        cleanup: :missing,
        full_ordered?: transport_full_valid?(state),
        private?: state.private? and transport_privacy_tail(key)
      }
    after
      transport_test_cleanup(key)
      :telemetry.detach(handler)
      Process.delete({key, :handler})
    end
  end

  defp transport_initial_owner(key, actor, actor_monitor, deadline, accept_preparation?) do
    receive do
      {^key, :workspace_allocation, owner, ^actor, workspace} when is_pid(owner) ->
        transport_workspace_initial_receive(key, owner, actor, workspace)
        transport_initial_owner(key, actor, actor_monitor, deadline, accept_preparation?)

      {^key, :prepare, owner, destination} when is_pid(owner) ->
        Process.put({key, :diagnostic4_receive_exit}, :prepare_received)
        {owner, destination}

      {^key, :diagnostic2_preparation, primary, cleanup} when accept_preparation? == true ->
        Process.put(
          {key, :diagnostic1_preparation},
          transport_diagnostic_initial_preparation(primary, cleanup)
        )

        transport_initial_owner(key, actor, actor_monitor, deadline, false)

      {^key, :outcome, outcome, _, _, _} ->
        Process.put({key, :diagnostic1_initial}, transport_diagnostic_initial(outcome))
        Process.put({key, :diagnostic4_receive_exit}, :actor_outcome)
        throw(:legacy_transport_observer)

      {:DOWN, ^actor_monitor, :process, ^actor, reason} ->
        transport_cleanup_record(key, :actor, actor_monitor, actor, reason)
        Process.put({key, :diagnostic4_receive_exit}, :actor_down)
        throw(:legacy_transport_observer)
    after
      transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) ->
        Process.put({key, :diagnostic4_receive_exit}, :prepare_timeout)
        throw(:legacy_transport_observer)
    end
  end

  defp transport_initial_remaining(deadline, now), do: max(0, deadline - now)

  # Diagnostic-only: raw originals stay in the actor; tail and metadata are opaque.
  defguardp transport_actor_failure_fields(kind, origin, reason_tag)
            when kind in [:error, :throw, :exit, :unknown] and
              origin in [:baseline_pause, :acquisition_checkpoint, :destination_acquire,
                :owner_request, :unknown, :unobserved] and
              reason_tag in [:caller_down, :owner_down, :runtime_error, :match_error,
                :function_clause, :case_clause, :argument_error, :unknown, :unobserved]

  defp transport_actor_failure_diagnostic({kind, value, stack}) do
    %{kind: if(kind in [:error, :throw, :exit], do: kind, else: :unknown),
      origin: transport_actor_failure_origin(stack),
      reason_tag: transport_actor_failure_reason(kind, value)}
  end
  defp transport_actor_failure_diagnostic(_),
    do: %{kind: :unknown, origin: :unknown, reason_tag: :unknown}

  defp transport_actor_failure_origin([
    {Singularity.Storage.MigrationTestEnvironment, :pause_owned_baseline, 0, _} | _]),
    do: :baseline_pause
  defp transport_actor_failure_origin([
    {Singularity.Storage.MigrationTestEnvironment, :owned_checkpoint, 1, _} | _]),
    do: :acquisition_checkpoint
  defp transport_actor_failure_origin([
    {Singularity.Storage.MigrationTestEnvironment, :acquire_owned_destination, 0, _} | _]),
    do: :destination_acquire
  defp transport_actor_failure_origin([
    {Singularity.Storage.Backup.KnowledgeFixtureResourceOwner, :request, 2, _} | _]),
    do: :owner_request
  defp transport_actor_failure_origin(_), do: :unknown

  defp transport_actor_failure_reason(:throw, :fixture_caller_down), do: :caller_down
  defp transport_actor_failure_reason(:exit, {:fixture_owner_down, _}), do: :owner_down
  defp transport_actor_failure_reason(:error, %{__struct__: RuntimeError}), do: :runtime_error
  defp transport_actor_failure_reason(:error, %{__struct__: MatchError}), do: :match_error
  defp transport_actor_failure_reason(:error, %{__struct__: FunctionClauseError}), do: :function_clause
  defp transport_actor_failure_reason(:error, %{__struct__: CaseClauseError}), do: :case_clause
  defp transport_actor_failure_reason(:error, %{__struct__: ArgumentError}), do: :argument_error
  defp transport_actor_failure_reason(_, _), do: :unknown

  defp transport_actor_failure_emit(parent, key, original) do
    diagnostic =
      try do
        transport_actor_failure_diagnostic(original)
      rescue
        _ -> %{kind: :unknown, origin: :unknown, reason_tag: :unknown}
      catch
        _, _ -> %{kind: :unknown, origin: :unknown, reason_tag: :unknown}
      end
    send(parent, {key, :diagnostic_actor_failure, self(),
      diagnostic.kind, diagnostic.origin, diagnostic.reason_tag})
    send(parent, {key, :outcome, :actor_failed, [], false, false})
  end

  defp transport_actor_failure_record(key,
    {message_key, :diagnostic_actor_failure, actor, kind, origin, reason_tag})
    when message_key == key and is_pid(actor) and
      transport_actor_failure_fields(kind, origin, reason_tag) do
    case Process.get({key, :actor}) do
      {^actor, monitor} when is_reference(monitor) ->
        case Process.get({key, :diagnostic_actor_failure}) do
          %{kind: old_kind, origin: old_origin, reason_tag: old_reason} = record
          when map_size(record) == 3 and
            transport_actor_failure_fields(old_kind, old_origin, old_reason) -> :ok
          _ -> Process.put({key, :diagnostic_actor_failure},
            %{kind: kind, origin: origin, reason_tag: reason_tag})
        end
        :accepted
      _ -> :rejected
    end
  end
  defp transport_actor_failure_record(_, _), do: :rejected

  defp transport_actor_failure_get(key) do
    case Process.get({key, :diagnostic_actor_failure}) do
      %{kind: kind, origin: origin, reason_tag: reason_tag} = record
      when map_size(record) == 3 and transport_actor_failure_fields(kind, origin, reason_tag) ->
        %{kind: kind, origin: origin, reason_tag: reason_tag}
      _ -> %{kind: :unknown, origin: :unobserved, reason_tag: :unobserved}
    end
  end

  defp transport_diagnostic_initial_preparation(primary, cleanup) do
    %{
      primary: transport_diagnostic_primary(primary),
      cleanup: transport_diagnostic_cleanup(cleanup)
    }
  end

  defp transport_actor(parent, key, scenario),
    do: transport_actor(parent, key, scenario, nil, :workspace_oracle)

  defp transport_actor(parent, key, scenario, cleanup_controller),
    do: transport_actor(parent, key, scenario, cleanup_controller, :disabled)

  defp transport_actor(parent, key, scenario, cleanup_controller, workspace_mode) do
    workspace_scenario = scenario
    scenario = if scenario == :workspace_present, do: :clean_frame, else: scenario
    caller = self()
    parent_monitor = Process.monitor(parent)
    ua_control? = Process.delete({key, :ua_control_enabled}) == true

    prepare = fn destination, context ->
      transport_require!(context.caller == caller and self() != caller)
      caller_monitor = Process.monitor(context.caller)

      try do
        send(parent, {key, :prepare, self(), destination})

        armed_started = System.monotonic_time(:millisecond)

        receive do
          {^key, :armed} ->
            send(
              parent,
              {key, :diagnostic6_armed, self(), :armed,
               transport_diagnostic6_elapsed(System.monotonic_time(:millisecond) - armed_started)}
            )

            :ok

          {:DOWN, ^caller_monitor, :process, ^caller, _} ->
            throw(:fixture_caller_down)
        after
          5_000 ->
            send(
              parent,
              {key, :diagnostic6_armed, self(), :expired,
               transport_diagnostic6_elapsed(System.monotonic_time(:millisecond) - armed_started)}
            )

            throw(:legacy_transport_observer)
        end
      after
        Process.demonitor(caller_monitor, [:flush])
      end

      # TASK18_TRANSPORT_DIAGNOSTIC3_BEGIN
      send(parent, {key, :diagnostic3_protocols, transport_diagnostic3_protocols()})
      # TASK18_TRANSPORT_DIAGNOSTIC3_END
      apply(LegacyUpgradeRuntimeFixture, :probe_transport!, [
        destination,
        context,
        if(
          scenario in [
            :blocked_reader_control,
            :reader_down,
            :writer_wait_control,
            :writer_down,
            :deadline_control,
            :deadline_expired
          ],
          do: :clean_frame,
          else: scenario
        ),
        parent
      ])
    end

    checkpoint = fn stage, resources ->
      ua_control_checkpoint(parent, key, ua_control?, stage, resources)
      if workspace_mode == :workspace_oracle,
        do:
          transport_workspace_checkpoint(
            parent,
            key,
            caller,
            workspace_scenario,
            stage,
            resources
          )

      # TASK18_TRANSPORT_DIAGNOSTIC4_BEGIN
      if stage in [
           :before_allocation,
           :allocated,
           :baseline_paused,
           :maintenance_started,
           :database_created,
           :root_created,
           :extensions_ready,
           :before_migration,
           :migrated
         ] do
        send(parent, {key, :diagnostic4_stage, stage})
      end

      # TASK18_TRANSPORT_DIAGNOSTIC4_END
      if stage in [:ready, :before_database_drop] do
        send(parent, {key, :checkpoint, stage, resources.owner, System.monotonic_time()})
      end

      if stage == :before_database_drop,
        do: transport_cleanup_checkpoint(cleanup_controller, key, resources.owner)

      :ok
    end

    try do
      {owner, _destination, result} =
        Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.with_checkpoint(checkpoint, fn ->
          Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.open_legacy_v0_1_0(prepare)
        end)

      {queued, safe?} = transport_queued(owner, [], true)
      send(parent, {key, :outcome, {:ok, result == receipt()}, queued, safe?, true})

      try do
        receive do
          {^key, :close} -> :ok
          {:DOWN, ^parent_monitor, :process, ^parent, _} -> :ok
        after
          5_000 -> :ok
        end
      after
        Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.close(owner)
      end

      send(parent, {key, :actor_closed, true})
    rescue
      error in Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.PreparationError ->
        # TASK18_TRANSPORT_DIAGNOSTIC2_BEGIN
        send(
          parent,
          {key, :diagnostic2_preparation, transport_diagnostic_primary(error.primary),
           transport_diagnostic_cleanup(error.cleanup)}
        )

        # TASK18_TRANSPORT_DIAGNOSTIC2_END
        if scenario in [
             :blocked_reader_control,
             :reader_down,
             :writer_wait_control,
             :writer_down,
             :deadline_control,
             :deadline_expired
           ] do
          private? =
            not transport_contains?(Exception.message(error)) and
              not transport_contains?(
                inspect(error, limit: :infinity, printable_limit: :infinity)
              )

          {outcome, private?} =
            transport_c4_preparation(scenario, error.primary, error.cleanup, private?)

          {queued, safe?} = transport_queued(nil, [], true)
          send(parent, {key, :outcome, outcome, queued, safe?, private?})
          send(parent, {key, :actor_closed, error.cleanup == []})
        else
          category = transport_expected_category(scenario)
          expected? = error.primary == category and error.cleanup == []

          private? =
            expected? and not transport_contains?(Exception.message(error)) and
              not transport_contains?(
                inspect(error, limit: :infinity, printable_limit: :infinity)
              )

          {queued, safe?} = transport_queued(nil, [], true)
          outcome = if expected?, do: {:error, category, []}, else: :unexpected_preparation
          send(parent, {key, :outcome, outcome, queued, safe?, private?})
          send(parent, {key, :actor_closed, expected?})
        end

      error ->
        original = {:error, error, __STACKTRACE__}
        transport_actor_failure_emit(parent, key, original)
    catch
      kind, value ->
        original = {kind, value, __STACKTRACE__}
        transport_actor_failure_emit(parent, key, original)
    end
  end

  defp transport_loop(state) do
    # TASK18_TRANSPORT_DIAGNOSTIC2_BEGIN
    transport_diagnostic_snapshot(state)
    # TASK18_TRANSPORT_DIAGNOSTIC2_END
    transport_gate_check!(state, :deadline, fn ->
      System.monotonic_time(:millisecond) < state.deadline
    end)

    state = state |> transport_gate() |> transport_observe_absence()

    terminal? =
      not is_nil(state.outcome) and state.absent? and not is_nil(state.closed) and
        map_size(state.exits) == 3 and
        Map.has_key?(
          state.checkpoints,
          if(
            state.scenario in [
              :clean_frame,
              :full_frame_eof,
              :blocked_reader_control,
              :writer_wait_control,
              :deadline_control
            ],
            do: :ready,
            else: :before_database_drop
          )
        )

    if terminal? do
      state
    else
      receive do
        message ->
          # TASK18_TRANSPORT_DIAGNOSTIC5_BEGIN
          next = transport_message(message, state)

          if state.valid? and not next.valid? do
            Process.put({state.key, :diagnostic5_invalid}, %{
              reason: transport_diagnostic5_reason(message, state),
              header: transport_diagnostic_header(message, state),
              after_closed: is_integer(state.closed),
              after_await: not is_nil(state.await_return),
              after_sql_zero: is_integer(state.sql_zero),
              stages: transport_diagnostic_count(length(state.stages))
            })
          end

          transport_loop(next)
          # TASK18_TRANSPORT_DIAGNOSTIC5_END
      after
        10 -> transport_loop(state)
      end
    end
  end

  # TASK18_TRANSPORT_DIAGNOSTIC5_BEGIN
  defp transport_diagnostic5_reason(message, state) do
    case message do
      {:trace_ts, owner, :call, {LegacyUpgradeRuntimeFixture, :transport_event, _}, _}
      when owner == state.owner ->
        :stage_invariant

      {:trace_ts, owner, :call, {ExCmd.Process, :await_exit, _}, _}
      when owner == state.owner ->
        :await_call_invariant

      {:trace_ts, owner, :return_from, {ExCmd.Process, :await_exit, 2}, _, _}
      when owner == state.owner ->
        :await_return_invariant

      {:trace_ts, owner, :call, {Singularity.Storage.SafeSQL, :query!, _}, _}
      when owner == state.owner ->
        :sql_call_invariant

      {:trace_ts, owner, :return_from, {Singularity.Storage.SafeSQL, :query!, 4}, _, _}
      when owner == state.owner ->
        :sql_return_invariant

      {:trace_ts, _, :exit, _, _} ->
        :worker_exit_invariant

      {:trace_ts, owner, _, _, _} when owner == state.owner ->
        :unmatched_owner_trace5

      {:trace_ts, owner, _, _, _, _} when owner == state.owner ->
        :unmatched_owner_trace6

      {:trace_ts, _, _, _, _} ->
        :unmatched_trace5

      {:trace_ts, _, _, _, _, _} ->
        :unmatched_trace6

      {key, :outcome, _, _, _, _} when key == state.key ->
        :actor_queue_invariant

      {:EXIT, _, _} ->
        :unexpected_exit

      {key, :checkpoint, :before_database_drop, owner, at}
      when is_reference(key) and key != state.key and is_pid(owner) and owner != state.owner and
             is_integer(at) ->
        :foreign_before_database_drop_checkpoint

      _ ->
        :unmatched_message
    end
  end

  # TASK18_TRANSPORT_DIAGNOSTIC5_END
  defp transport_diagnostic_header(
         {:trace_ts, reader, :call, {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3},
          {:legacy_header_fact, phase, bounded?, expected?}, at},
         state
       )
       when phase in [:start, :three_left, :two_left, :one_left, :complete] and
              is_boolean(bounded?) and is_boolean(expected?) and is_integer(at) do
    header = state.header
    remaining = %{start: 4, three_left: 3, two_left: 2, one_left: 1, complete: 0}[phase]

    ordered? =
      if phase == :start do
        is_nil(header.start) and is_nil(header.remaining) and header.steps == 0
      else
        is_integer(header.start) and header.start < at and is_nil(header.complete) and
          is_integer(header.remaining) and remaining < header.remaining and
          header.requested == header.remaining
      end

    transport_diagnostic_header_state(header)
    |> Map.merge(%{
      branch: :header_fact,
      phase: phase,
      reader?: state.started != nil and reader == Enum.at(state.started, 1),
      bounded?: bounded?,
      expected?: expected?,
      ordered?: ordered?,
      notdown?: not MapSet.member?(state.down, reader)
    })
  end

  defp transport_diagnostic_header(
         {:trace_ts, reader, :call, {ExCmd.Process, :read, 2}, {:legacy_header_request, request},
          at},
         state
       )
       when request in [:four, :three, :two, :one] and is_integer(at) do
    header = state.header
    size = %{four: 4, three: 3, two: 2, one: 1}[request]

    transport_diagnostic_header_state(header)
    |> Map.merge(%{
      branch: :header_request,
      request: request,
      reader?: state.started != nil and reader == Enum.at(state.started, 1),
      bounded?: header.reads < 4,
      expected?: header.remaining == size,
      ordered?:
        is_integer(header.start) and header.start < at and
          is_nil(header.complete) and is_nil(header.requested),
      notdown?: not MapSet.member?(state.down, reader)
    })
  end

  defp transport_diagnostic_header(
         {:trace_ts, _, :call, {LegacyUpgradeRuntimeFixture, function, arity},
          {:legacy_forbidden_body_or_decode, true}, _},
         _
       )
       when {function, arity} in [{:transport_read_exact, 3}, {:decode_receipt!, 1}],
       do: %{branch: :forbidden_body_or_decode}

  defp transport_diagnostic_header(_, _), do: :unmatched

  defp transport_diagnostic_header_state(header) do
    %{
      start?: is_integer(header.start),
      complete?: is_integer(header.complete),
      remaining: transport_diagnostic_small(header.remaining),
      requested: transport_diagnostic_small(header.requested),
      steps: transport_diagnostic_header_count(header.steps),
      reads: transport_diagnostic_header_count(header.reads)
    }
  end

  defp transport_diagnostic_small(nil), do: nil
  defp transport_diagnostic_small(value) when is_integer(value) and value in 0..4, do: value
  defp transport_diagnostic_small(_), do: nil

  defp transport_diagnostic_header_count(value) when is_integer(value) and value in 0..5,
    do: value

  defp transport_diagnostic_header_count(_), do: :overflow

  defp transport_diagnostic_initial(outcome) do
    preparation =
      case outcome do
        {:error, category, []} -> transport_diagnostic_primary(category)
        _ -> :unobserved
      end

    %{outcome: transport_diagnostic_outcome(outcome), preparation: preparation}
  end

  defp transport_diagnostic_gate_status(step, status) do
    %{
      step:
        if(
          step in [
            :deadline,
            :query,
            :query_shape,
            :backend_baseline,
            :repo_identity,
            :repo_liveness,
            :worker_liveness,
            :unlock,
            :released
          ],
          do: step,
          else: :other
        ),
      status:
        if(status in [:checking, :passed, :failed, :empty, :waiting], do: status, else: :other)
    }
  end

  defp transport_gate_diagnostic(state, step, status) do
    Process.put({state.key, :diagnostic1_gate}, transport_diagnostic_gate_status(step, status))
    :ok
  end

  defp transport_gate_check!(state, step, check) do
    transport_gate_diagnostic(state, step, :checking)
    result = check.()
    transport_gate_diagnostic(state, step, if(result == true, do: :passed, else: :failed))
    transport_require!(result)
  end

  defp transport_gate(%{gate: true} = state), do: state

  defp transport_gate(%{scenario: scenario} = state)
       when scenario in [:deadline_control, :deadline_expired],
       do: transport_deadline_gate(state)

  defp transport_gate(%{scenario: scenario} = state)
       when scenario in [:writer_wait_control, :writer_down],
       do: transport_writer_gate(state)

  defp transport_gate(%{scenario: scenario} = state)
       when scenario in [:blocked_reader_control, :reader_down],
       do: transport_c4_gate(state)

  defp transport_gate(state) do
    transport_gate_diagnostic(state, :query, :checking)

    rows =
      transport_rows(state.connection, @transport_sql, [
        state.destination.database,
        @transport_tag
      ])

    case rows do
      [] ->
        transport_gate_diagnostic(state, :query_shape, :empty)
        state

      [[pid]] when is_integer(pid) and pid > 0 ->
        transport_gate_diagnostic(state, :query_shape, :passed)

        transport_gate_check!(state, :backend_baseline, fn ->
          transport_gate_backends(state, pid) --
            [{pid, "singularity_migration"}] == state.baseline
        end)

        transport_gate_check!(state, :repo_identity, fn ->
          Map.new(@transport_repos, &{&1, Process.whereis(&1)}) == state.repos
        end)

        transport_gate_check!(state, :repo_liveness, fn ->
          Enum.all?(state.repos, fn {_repo, p} -> Process.alive?(p) end)
        end)

        if state.started do
          transport_gate_check!(state, :worker_liveness, fn ->
            Enum.all?(state.started, &Process.alive?/1)
          end)

          transport_gate_check!(state, :unlock, fn ->
            transport_rows(
              state.connection,
              "SELECT pg_advisory_unlock($1::integer,$2::integer)",
              @transport_lock
            ) == [[true]]
          end)

          Process.put({state.key, :locked}, false)
          transport_gate_diagnostic(state, :released, :passed)
          %{state | gate: true, child: pid}
        else
          transport_gate_diagnostic(state, :worker_liveness, :waiting)
          state
        end

      _ ->
        transport_gate_diagnostic(state, :query_shape, :failed)
        throw(:legacy_transport_observer)
    end
  end

  # C4 holds only its exact owner to make termination -> unlock -> await causal.
  # OTP28 pauses a suspended receive timer; this is NOT deadline qualification.
  defp transport_c4_gate(state) do
    c4 = state.c4

    ready? =
      state.valid? and state.started != nil and is_integer(c4.read) and is_integer(c4.pending)

    if ready? do
      [command, reader, writer] = state.started

      rows =
        transport_rows(
          state.connection,
          "SELECT pid,wait_event_type='Lock' AND wait_event='advisory' FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND application_name=$2 ORDER BY pid",
          [state.destination.database, @transport_tag]
        )

      case rows do
        [[pid, true]] when is_integer(pid) and pid > 0 ->
          transport_require!(
            transport_gate_backends(state, pid, 2) --
              [{pid, "singularity_migration"}] == state.baseline
          )

          transport_require!(Map.new(@transport_repos, &{&1, Process.whereis(&1)}) == state.repos)
          transport_require!(Enum.all?(state.repos, fn {_repo, p} -> Process.alive?(p) end))

          cond do
            is_nil(c4.hold) ->
              waiting? =
                Process.info(reader, [:status, :current_function]) ==
                  [status: :waiting, current_function: {:gen, :do_call, 4}]

              if waiting? do
                transport_require!(Enum.all?(state.started, &Process.alive?/1))
                transport_require!(Process.alive?(state.owner))
                at = System.monotonic_time()
                tag = make_ref()

                transport_require!(
                  :erlang.suspend_process(
                    state.owner,
                    [:unless_suspending, {:asynchronous, tag}]
                  ) == true
                )

                hold = {state.key, state.owner, tag}
                Process.put({state.key, :c4_hold}, hold)

                %{
                  state
                  | child: pid,
                    c4: %{
                      c4
                      | blocked: at,
                        waiting?: true,
                        hold: hold,
                        acquired?: true,
                        owned?: true
                    }
                }
              else
                state
              end

            is_nil(c4.ack) ->
              state

            state.scenario == :reader_down and is_nil(c4.trigger) ->
              transport_require!(Process.info(state.owner, :status) == {:status, :suspended})

              transport_require!(
                Process.info(reader, [:status, :current_function]) ==
                  [status: :waiting, current_function: {:gen, :do_call, 4}]
              )

              transport_require!(Enum.all?(state.started, &Process.alive?/1))
              transport_require!(Process.get({state.key, :c4_hold}) == c4.hold)
              at = System.monotonic_time()
              Process.exit(reader, :kill)
              %{state | c4: %{c4 | trigger: at}}

            state.scenario == :reader_down and
                (is_nil(c4.reader_down) or not Map.has_key?(state.exits, reader)) ->
              state

            true ->
              transport_require!(Process.info(state.owner, :status) == {:status, :suspended})
              transport_require!(Process.alive?(command) and Process.alive?(writer))
              transport_require!(Process.get({state.key, :c4_hold}) == c4.hold)

              if state.scenario == :blocked_reader_control do
                transport_require!(
                  Process.info(reader, [:status, :current_function]) ==
                    [status: :waiting, current_function: {:gen, :do_call, 4}]
                )
              end

              transport_require!(
                transport_rows(
                  state.connection,
                  "SELECT pg_advisory_unlock($1::integer,$2::integer)",
                  @transport_lock
                ) == [[true]]
              )

              released = System.monotonic_time()
              Process.put({state.key, :locked}, false)
              resumed = System.monotonic_time()
              transport_require!(:erlang.resume_process(state.owner) == true)
              Process.delete({state.key, :c4_hold})

              %{
                state
                | gate: true,
                  child: pid,
                  c4: %{c4 | release: released, resumed: resumed, owned?: false}
              }
          end

        [] ->
          state

        [[_, waiting]] when waiting in [false, nil] ->
          state

        _ ->
          throw(:legacy_transport_observer)
      end
    else
      state
    end
  end

  defp transport_observe_absence(%{absent?: true} = state), do: state

  defp transport_observe_absence(state) do
    if state.gate and not is_nil(state.started) and not is_nil(state.await_return) and
         not is_nil(state.sql_zero) and
         Enum.all?(state.started, &MapSet.member?(state.down, &1)) do
      Process.put({state.key, :diagnostic8_absence}, %{
        stage: :tagged_query_before,
        tagged_result: :unobserved,
        tagged_rows_list?: false,
        tagged_row_count: :unobserved,
        tagged_empty?: :unobserved,
        tagged_result_guard: :unobserved,
        tagged_empty_guard: :unobserved,
        backend_sample: :unobserved,
        backend_query: :unobserved,
        backend_original_child_known?: :unobserved,
        backend_original_child_pid_match?: :unobserved,
        backend_result_guard: :unobserved,
        backend_row_guards: :unobserved,
        backend_baseline_equal?: :unobserved,
        backend_baseline_guard: :unobserved,
        repo_identity?: :unobserved,
        repo_identity_guard: :unobserved,
        repo_alive?: :unobserved,
        repo_alive_guard: :unobserved,
        stop: :unobserved
      })

      result =
        Postgrex.query(
          state.connection,
          @transport_sql,
          [state.destination.database, @transport_tag],
          timeout: 1_000
        )

      {rows_list?, row_count, empty?} =
        case result do
          {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) ->
            {true, transport_diagnostic7_count(length(rows)), rows == []}

          _ ->
            {false, :unobserved, :unobserved}
        end

      Process.put(
        {state.key, :diagnostic8_absence},
        Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
          stage: :tagged_result_guard_before,
          tagged_result: transport_diagnostic6_query_result(result),
          tagged_rows_list?: rows_list?,
          tagged_row_count: row_count,
          tagged_empty?: empty?,
          tagged_result_guard: :before
        })
      )

      rows =
        case result do
          {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) -> rows
          _ -> throw(:legacy_transport_observer)
        end

      Process.put(
        {state.key, :diagnostic8_absence},
        Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
          stage: :tagged_empty_guard_before,
          tagged_result_guard: :passed,
          tagged_empty_guard: :before
        })
      )

      transport_require!(rows == [])

      Process.put(
        {state.key, :diagnostic8_absence},
        Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
          stage: :tagged_empty_guard_after,
          tagged_empty_guard: :passed
        })
      )

      if state.scenario in [
           :clean_frame,
           :full_frame_eof,
           :blocked_reader_control,
           :writer_wait_control,
           :deadline_control
         ] do
        backends = transport_absence_backends(state)

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :backend_baseline_guard_before,
            backend_baseline_equal?: backends == state.baseline,
            backend_baseline_guard: :before
          })
        )

        transport_require!(backends == state.baseline)

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :backend_baseline_guard_after,
            backend_baseline_guard: :passed
          })
        )

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :repo_identity_before
          })
        )

        same_repos? = Map.new(@transport_repos, &{&1, Process.whereis(&1)}) == state.repos

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :repo_identity_guard_before,
            repo_identity?: same_repos?,
            repo_identity_guard: :before
          })
        )

        transport_require!(same_repos?)

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :repo_identity_guard_after,
            repo_identity_guard: :passed
          })
        )

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :repo_alive_before
          })
        )

        repos_alive? = Enum.all?(state.repos, fn {_repo, pid} -> Process.alive?(pid) end)

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :repo_alive_guard_before,
            repo_alive?: repos_alive?,
            repo_alive_guard: :before
          })
        )

        transport_require!(repos_alive?)

        Process.put(
          {state.key, :diagnostic8_absence},
          Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
            stage: :repo_alive_guard_after,
            repo_alive_guard: :passed
          })
        )
      end

      state = if ua_control_active?(state.key), do: state,
        else: transport_absence_connection_close(state)
      %{state | absent?: true}
    else
      state
    end
  end

  defp transport_absence_connection_close(state) do
    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :connection_stop_before,
        stop: :before
      })
    )

    GenServer.stop(state.connection, :normal, 1_000)

    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :connection_stop_after,
        stop: :passed
      })
    )

    Process.delete({state.key, :connection})
    state
  end

  # TASK18_EOF_EXIT_MESSAGES_BEGIN
  defp transport_message(
         {:trace_ts, owner, :call,
          {LegacyUpgradeRuntimeFixture, :transport_event, 2},
          {:legacy_eof_stage, run, {:started, command, reader, writer}}, at},
         %{scenario: scenario} = state
       ) when scenario in @transport_eof_modes do
    e = state.eof
    valid? = owner == state.owner and is_reference(run) and
      is_integer(at) and is_nil(e.started_fact) and is_nil(state.run) and
      Enum.all?([command, reader, writer], &is_pid/1)
    stage = {:started, command, reader, writer}
    state = %{state | valid?: state.valid? and valid?, run: run,
      stages: state.stages ++ [{at, stage}],
      eof: %{e | started_fact: {run, [command, reader, writer], at}}}
    if valid?, do: transport_eof_join(state), else: state
  end

  defp transport_message(
         {:trace_ts, owner, :call, {LegacyUpgradeRuntimeFixture, :transport_event, 2},
          {:legacy_eof_stage, run, stage}, at},
         %{scenario: scenario} = state
       ) when scenario in @transport_eof_modes do
    valid? = owner == state.owner and run == state.run and is_reference(run) and
      is_integer(at) and transport_stage?(stage) and length(state.stages) < 32
    %{state | valid?: state.valid? and valid?, stages: state.stages ++ [{at, stage}],
      closed: if(stage == {:cleanup, :closed}, do: at, else: state.closed)}
  end

  defp transport_message(
         {:trace_ts, owner, :call, {Singularity.Storage.SafeSQL, :query!, 4},
          {:legacy_eof_sql, database}, at},
         %{scenario: scenario} = state
       ) when scenario in @transport_eof_modes do
    valid? = owner == state.owner and database == state.destination.database and
      is_integer(at) and is_nil(state.sql_zero) and is_nil(state.eof.sql_pending)
    %{state | valid?: state.valid? and valid?, sql_call: at, eof: %{state.eof | sql_pending: at}}
  end

  defp transport_message(
         {:trace_ts, owner, :return_from, {Singularity.Storage.SafeSQL, :query!, 4}, result, at},
         %{scenario: scenario} = state
       ) when scenario in @transport_eof_modes do
    e = state.eof
    valid? = owner == state.owner and is_integer(e.sql_pending) and
      is_integer(at) and e.sql_pending < at
    case result do
      %Postgrex.Result{command: :select, columns: ["pid"], rows: [], num_rows: 0} ->
        %{state | valid?: state.valid? and valid?, sql_zero: at, eof: %{e | sql_pending: nil}}
      %Postgrex.Result{command: :select, columns: ["pid"], rows: rows, num_rows: count} ->
        typed? = is_list(rows) and length(rows) == count and
          Enum.all?(rows, fn [pid] when is_integer(pid) and pid > 0 -> true; _ -> false end)
        %{state | valid?: state.valid? and valid? and typed?, eof: %{e | sql_pending: nil}}
      _ ->
        %{state | valid?: false, eof: %{e | sql_pending: nil}}
    end
  end

  defp transport_message(
         {:trace_ts, owner, :call, {LegacyUpgradeRuntimeFixture, :transport_receive, 1},
          {:legacy_eof_owner_state, run, handle, reader, writer}, at},
         %{scenario: scenario} = state
       ) when scenario in @transport_eof_modes do
    e = state.eof
    valid? = owner == state.owner and is_reference(run) and is_integer(at) and
      is_nil(e.capture) and is_map(handle) and is_pid(reader) and is_pid(writer)
    state = %{state | valid?: state.valid? and valid?, eof: %{e | capture: at,
      capture_owner: owner, capture_handle: handle, run: run,
      capture_workers: [handle.pid, reader, writer]}}
    if valid?, do: transport_eof_join(state), else: state
  end

