         {:trace_ts, reader, :call, {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3},
          {:legacy_eof_exact, phase, remaining, expected?}, at},
         %{scenario: scenario} = state
       ) when scenario in @transport_eof_modes and phase in [:header, :body] and
              is_integer(remaining) and is_boolean(expected?) and is_integer(at),
