  defp transport_message(
         {:trace_ts, _, :call, {module, function, 2}, _, _},
         %{scenario: scenario} = state
       )
       when scenario in [:deadline_control, :deadline_expired] and
              ((module == ExCmd.Process and function == :read) or
                 (module == ExCmd.Process.State and function == :put_operation)),
       do: %{state | valid?: false}

  defp transport_message({:DOWN, ref, :process, pid, _}, %{scenario: scenario} = state)
       when scenario in [:deadline_control, :deadline_expired] and
              (is_map_key(state.monitors, ref) or pid == hd(state.started) or
                 pid == hd(tl(state.started)) or pid == hd(tl(tl(state.started)))) do
    valid? =
      state.monitors[ref] == pid and pid in state.started and
        not Map.has_key?(state.deadline_loss.downs, pid) and not MapSet.member?(state.down, pid)

    %{
      state
      | valid?: state.valid? and valid?,
        down: MapSet.put(state.down, pid),
        deadline_loss: %{
          state.deadline_loss
          | downs:
              Map.put(state.deadline_loss.downs, pid, {ref, System.monotonic_time(:nanosecond)})
        }
    }
  end

  # TASK18_DEADLINE_MESSAGES_END

  # TASK18_WRITER_LOSS_MESSAGES_BEGIN
  defp transport_message({tag, :suspended}, %{scenario: scenario} = state)
       when scenario in [:writer_wait_control, :writer_down] do
    w = state.writer_loss

    valid? =
      is_reference(tag) and w.hold == {state.key, state.owner, tag} and w.acquired? and
        w.owned? and is_nil(w.ack) and Process.get({state.key, :c4_hold}) == w.hold and
        Process.info(state.owner, :status) == {:status, :suspended}

    %{
      state
      | valid?: state.valid? and valid?,
        writer_loss: %{w | ack_tag: tag, ack: System.monotonic_time()}
    }
  end

  defp transport_message(
         {:trace_ts, pid, :call, {ExCmd.Process, :write, 2}, {:legacy_writer_write, true}, at},
         %{scenario: scenario} = state
       )
       when scenario in [:writer_wait_control, :writer_down] do
    w = state.writer_loss

    valid? =
      is_integer(at) and is_integer(w.started_at) and w.started_at < at and pid == w.writer and
        is_nil(w.write) and is_nil(w.blocked) and
        is_nil(w.trigger) and is_reference(w.run) and w.run == state.run and
        w.command == hd(state.started) and w.owner == state.owner

    %{state | valid?: state.valid? and valid?, writer_loss: %{w | write: at}}
  end

  defp transport_message(
         {:trace_ts, _, :call, {ExCmd.Process, :write, _}, _, _},
         %{scenario: scenario} = state
       )
       when scenario in [:writer_wait_control, :writer_down],
       do: %{state | valid?: false}

  defp transport_message(
         {:trace_ts, _, :call, {ExCmd.Process, :write, _}, _},
         %{scenario: scenario} = state
       )
       when scenario in [:writer_wait_control, :writer_down],
       do: %{state | valid?: false}

  defp transport_message(
         {:trace_ts, pid, :exit, reason, at},
         %{scenario: scenario, writer_loss: %{writer: writer}} = state
       )
       when scenario in [:writer_wait_control, :writer_down] and pid == writer do
    w = state.writer_loss

    expected? =
      if scenario == :writer_down,
        do: reason == :killed and is_integer(w.trigger) and is_integer(at) and w.trigger < at,
        else: reason == :normal and is_integer(w.resumed) and is_integer(at) and w.resumed < at

    valid? = expected? and is_nil(w.exit) and not Map.has_key?(state.exits, writer)

    %{
      state
      | valid?: state.valid? and valid?,
        exits: Map.put(state.exits, writer, at),
        writer_loss: %{w | exit: at, exit_reason: transport_writer_reason(reason)}
    }
  end

  defp transport_message(
         {:DOWN, ref, :process, pid, reason},
         %{scenario: scenario, writer_loss: %{writer: writer, monitor: monitor}} = state
       )
       when scenario in [:writer_wait_control, :writer_down] and
              (pid == writer or ref == monitor) do
    w = state.writer_loss
    at = System.monotonic_time()

    expected? =
      if scenario == :writer_down,
        do: reason == :killed and is_integer(w.trigger) and w.trigger < at,
        else: reason == :normal and is_integer(w.resumed) and w.resumed < at

    valid? =
      pid == writer and ref == monitor and is_reference(ref) and state.monitors[ref] == writer and
        is_nil(w.down) and not MapSet.member?(state.down, writer) and expected?

    %{
      state
      | valid?: state.valid? and valid?,
        down: MapSet.put(state.down, writer),
        writer_loss: %{w | down: at, down_ref: ref, down_reason: transport_writer_reason(reason)}
    }
  end

  # TASK18_WRITER_LOSS_MESSAGES_END

  defp transport_message({tag, :suspended}, %{scenario: scenario} = state)
       when scenario in [:blocked_reader_control, :reader_down] and is_reference(tag) do
    case state.c4.hold do
      {key, owner, ^tag} when key == state.key and owner == state.owner ->
        valid? =
          state.c4.acquired? and state.c4.owned? and is_nil(state.c4.ack) and
            Process.get({state.key, :c4_hold}) == state.c4.hold and
            Process.info(owner, :status) == {:status, :suspended}

        %{
          state
          | valid?: state.valid? and valid?,
            c4: %{state.c4 | ack_tag: tag, ack: System.monotonic_time()}
        }

      _ ->
        %{state | valid?: false}
    end
  end

  defp transport_message(
         {:trace_ts, owner, :call, {ExCmd.Process, :start_link, 2},
          {:ua_original_launch, argv, cd, env}, at}, state)
       when owner == state.owner and is_integer(at) do
    transport_require!(ua_control_active?(state.key))
    transport_require!(!Map.has_key?(Process.get({__MODULE__, :ua_control}), :launch))
    ua_control_update(%{launch: %{argv: argv, cd: cd, env: env, at: at}})
    state
  end

  defp transport_message(
         {:trace_ts, owner, :call, {LegacyUpgradeRuntimeFixture, :transport_receive, 1},
          {:ua_original_receive, run, handle, reader, writer, deadline, workspace, paths}, at}, state)
       when owner == state.owner and is_integer(at) do
    ua_control_project(state, run, handle, reader, writer, deadline, workspace, paths, at)
  end

  defp transport_message({:DOWN, ref, :port, port, reason}, state) do
    case Process.get({__MODULE__, :ua_control}) do
      %{key: key, port_monitor: ^ref, port: ^port, port_down: nil} when key == state.key ->
        ua_control_update(%{port_down: reason, port_down_at: System.monotonic_time()})
        state
      _ -> %{state | valid?: false}
    end
  end

  defp transport_message(
         {key, :ua_control_origins, owner, caller, maintenance, repos, database, at}, state)
       when key == state.key and owner == state.owner and caller == state.actor and
              is_pid(maintenance) and is_map(repos) and is_binary(database) and is_integer(at) do
    transport_require!(ua_control_active?(key))
    transport_require!(!Map.has_key?(Process.get({__MODULE__, :ua_control}), :origins))
    ua_control_update(%{origins: %{owner: owner, caller: caller, maintenance: maintenance,
      repos: repos, database: database, at: at}})
    state
  end

  defp transport_message(
         {key, :ua_control_ready, owner, caller, maintenance, repos, database, at}, state)
       when key == state.key and owner == state.owner and caller == state.actor and
              is_pid(maintenance) and is_map(repos) and is_binary(database) and is_integer(at) do
    transport_require!(ua_control_active?(key))
    transport_require!(!Map.has_key?(Process.get({__MODULE__, :ua_control}), :ready))
    ua_control_update(%{ready: %{owner: owner, caller: caller, maintenance: maintenance,
      repos: repos, database: database, at: at}})
    state
  end

  defp transport_message(
         {:trace_ts, owner, :call,
          {LegacyUpgradeRuntimeFixture, :transport_event,
           [caller, {:legacy_upgrade_transport, run, owner, stage}]}, at},
         state
       )
       when owner == state.owner and caller == state.actor and is_reference(run) and
              is_integer(at) do
    safe? =
      transport_stage?(stage) and (is_nil(state.run) or state.run == run) and
        length(state.stages) < 32

    if safe? do
      state = %{state | run: run, stages: state.stages ++ [{at, stage}]}

      case stage do
        {:started, command, reader, writer} ->
          workers = [command, reader, writer]
          transport_require!(is_nil(state.started) and length(Enum.uniq(workers)) == 3)
          transport_require!(Enum.all?(workers, &Process.alive?/1))
          session = Process.get({state.key, :session})

          reader_traced? =
            state.scenario in [
              :malformed_payload,
              :short_frame_trailer,
              :ascii_stderr_flood,
              :declared_oversize,
              :full_frame_eof,
              :full_frame_overrun,
              :blocked_reader_control,
              :reader_down
            ]

          if state.scenario in [:blocked_reader_control, :reader_down] do
            transport_c4_patterns!(session, state.owner, command, reader)
          else
            if reader_traced?,
              do: transport_reader_patterns!(session, state.owner, command, state.scenario)
          end

          deadline_traced? = state.scenario in [:deadline_control, :deadline_expired]

          if deadline_traced?,
            do: transport_deadline_reader_patterns!(session, state.owner, command, reader)

          writer_traced? = state.scenario in [:writer_wait_control, :writer_down]

          if writer_traced?,
            do: transport_writer_pattern!(session, state.owner, command)

          Enum.each(workers, fn worker ->
            transport_require!(
              [:erlang.trace_info(worker, :flags), :erlang.trace_info(worker, :tracer)] ==
                [{:flags, []}, {:tracer, []}]
            )

            transport_require!(
              :trace.process(
                session,
                worker,
                true,
                [:procs, :monotonic_timestamp] ++
                  if(
                    (deadline_traced? and worker in [reader, command]) or
                      (writer_traced? and worker == writer) or
                      (reader_traced? and
                         (worker == reader or
                            (worker == command and
                               state.scenario in [:blocked_reader_control, :reader_down]))),
                    do: [:call, :arity],
                    else: []
                  )
              ) == 1
            )
          end)

          transport_require!(Enum.all?(workers, &Process.alive?/1))
          monitors = Map.new(workers, &{Process.monitor(&1), &1})
          state = transport_workspace_started(state)

          writer_loss =
            if writer_traced? do
              ref = Enum.find_value(monitors, fn {ref, pid} -> if pid == writer, do: ref end)

              %{
                state.writer_loss
                | writer: writer,
                  command: command,
                  run: run,
                  owner: state.owner,
                  monitor: ref,
                  started_at: at
              }
            else
              state.writer_loss
            end

          state = transport_deadline_started(state, workers, monitors, run, at)
          unless ua_control_hold_ready(state, workers, monitors, run, at) do
          send(state.owner, {run, :observer_ready, self()})
          end

          c4 =
            if state.scenario in [:blocked_reader_control, :reader_down],
              do: %{state.c4 | reader: reader},
              else: state.c4

          %{state | started: workers, monitors: monitors, c4: c4, writer_loss: writer_loss}

        {:cleanup, :closed} ->
          %{state | closed: at}

        _ ->
          state
      end
    else
      %{state | valid?: false}
    end
  end

  defp transport_message(
         {:trace_ts, pid, :call, {ExCmd.Process, :read, 2}, {:legacy_c4_read, true}, at},
         %{scenario: scenario} = state
       )
       when scenario in [:blocked_reader_control, :reader_down] and is_integer(at),
       do: transport_c4_fact(state, pid, :read, at)

  defp transport_message(
         {:trace_ts, pid, :call, {ExCmd.Process.State, :put_operation, 2},
          {:legacy_c4_pending, true}, at},
         %{scenario: scenario} = state
       )
       when scenario in [:blocked_reader_control, :reader_down] and is_integer(at),
       do: transport_c4_fact(state, pid, :pending, at)

  defp transport_message(
         {:trace_ts, owner, :call, {ExCmd.Process, :await_exit, [handle, timeout]}, at},
         state
       )
       when owner == state.owner and is_integer(at) do
    safe? =
      is_map(handle) and
        Enum.sort(Map.keys(handle)) ==
          Enum.sort([:__struct__, :pid, :owner, :monitor_ref, :exit_ref]) and
        handle.__struct__ == ExCmd.Process and handle.owner == owner and is_pid(handle.pid) and
        is_reference(handle.monitor_ref) and is_reference(handle.exit_ref) and
        is_integer(timeout) and timeout > 50 and timeout <= 5_000 and
        state.started != nil and handle.pid == hd(state.started) and is_nil(state.await_call)

    if safe?, do: %{state | await_call: at}, else: %{state | valid?: false}
  end

  defp transport_message(
         {:trace_ts, owner, :return_from, {ExCmd.Process, :await_exit, 2}, result, at},
         state
       )
       when owner == state.owner and is_integer(at) do
    status =
      case result do
        {:ok, 0} -> :zero
        {:ok, code} when is_integer(code) and code > 0 -> :nonzero
        {:error, :killed} -> :killed
        _ -> :invalid
      end

    %{state | await_return: {at, status}, valid?: state.valid? and status != :invalid}
  end

  defp transport_message(
         {:trace_ts, owner, :call,
          {Singularity.Storage.SafeSQL, :query!,
           [Singularity.Storage.MigrationRepo, sql, params, _]}, at},
         state
       )
       when owner == state.owner and sql == @transport_sql and is_integer(at) do
    if params == [state.destination.database, @transport_tag],
      do: %{state | sql_call: at},
      else: %{state | valid?: false}
  end

  defp transport_message(
         {:trace_ts, owner, :return_from, {Singularity.Storage.SafeSQL, :query!, 4}, result, at},
         state
       )
       when owner == state.owner and is_integer(at) do
    case result do
      %Postgrex.Result{command: :select, columns: ["pid"], rows: [], num_rows: 0} ->
        %{state | sql_zero: at, valid?: state.valid? and not is_nil(state.sql_call)}

      %Postgrex.Result{command: :select, columns: ["pid"], rows: rows, num_rows: count} ->
        typed? =
          is_list(rows) and length(rows) == count and
            Enum.all?(rows, fn
              [pid] when is_integer(pid) and pid > 0 -> true
              _ -> false
            end)

        %{state | valid?: state.valid? and typed?}

      _ ->
        %{state | valid?: false}
    end
  end

  # TASK18_HEADER_LIMIT_OBSERVER_BEGIN
  defp transport_message(
         {:trace_ts, reader, :call, {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3},
          {:legacy_header_fact, phase, bounded?, expected?}, at},
         state
       )
       when phase in [:start, :three_left, :two_left, :one_left, :complete] and
              is_boolean(bounded?) and is_boolean(expected?) and is_integer(at) do
    remaining = %{start: 4, three_left: 3, two_left: 2, one_left: 1, complete: 0}[phase]
    header = state.header
    reader? = state.started != nil and reader == Enum.at(state.started, 1)

    ordered? =
      if phase == :start do
        is_nil(header.start) and is_nil(header.remaining) and header.steps == 0
      else
        is_integer(header.start) and header.start < at and is_nil(header.complete) and
          is_integer(header.remaining) and remaining < header.remaining and
          header.requested == header.remaining
      end

    valid? =
      state.scenario in [:ascii_stderr_flood, :declared_oversize] and
        reader? and bounded? and expected? and ordered? and header.steps < 5 and
        not MapSet.member?(state.down, reader)

    header = %{
      header
      | start: header.start || at,
        remaining: remaining,
        requested: nil,
        complete: if(phase == :complete, do: at, else: nil),
        steps: header.steps + 1
    }

    %{state | header: header, valid?: state.valid? and valid?}
  end

  defp transport_message(
         {:trace_ts, reader, :call, {ExCmd.Process, :read, 2}, {:legacy_header_request, request},
          at},
         state
       )
       when request in [:four, :three, :two, :one] and is_integer(at) do
    size = %{four: 4, three: 3, two: 2, one: 1}[request]
    header = state.header
    reader? = state.started != nil and reader == Enum.at(state.started, 1)

    valid? =
      state.scenario in [:ascii_stderr_flood, :declared_oversize] and reader? and
        is_integer(header.start) and header.start < at and is_nil(header.complete) and
        header.remaining == size and is_nil(header.requested) and header.reads < 4 and
        not MapSet.member?(state.down, reader)

    %{
      state
      | header: %{header | requested: size, reads: header.reads + 1},
        valid?: state.valid? and valid?
    }
  end

  defp transport_message(
         {:trace_ts, _reader, :call, {LegacyUpgradeRuntimeFixture, function, arity},
          {:legacy_forbidden_body_or_decode, true}, _at},
         state
       )
       when {function, arity} in [{:transport_read_exact, 3}, {:decode_receipt!, 1}],
       do: %{state | valid?: false}

  # TASK18_HEADER_LIMIT_OBSERVER_END

  # Dedicated full-boundary facts never change old short-frame/header validity.
  defp transport_message(
         {:trace_ts, reader, :call, {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3},
          {:legacy_full_body, bounded?, expected?}, at},
         %{scenario: scenario} = state
       )
       when scenario in [:full_frame_eof, :full_frame_overrun] and
              is_boolean(bounded?) and is_boolean(expected?) and is_integer(at),
       do: transport_full_fact(state, reader, {:body, bounded?, expected?}, at)

  defp transport_message(
         {:trace_ts, reader, :call, {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1},
          {:legacy_full_frame, expected?}, at},
         %{scenario: scenario} = state
       )
       when scenario in [:full_frame_eof, :full_frame_overrun] and
              is_boolean(expected?) and is_integer(at),
       do: transport_full_fact(state, reader, {:decode_call, expected?}, at)

  defp transport_message(
         {:trace_ts, reader, :return_from, {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1},
          result, at},
         %{scenario: scenario} = state
       )
       when scenario in [:full_frame_eof, :full_frame_overrun] and is_integer(at) do
    typed? = result == {:ok, receipt()}
    transport_full_fact(state, reader, {:decode_return, typed?}, at)
  end

  defp transport_message(
         {:trace_ts, reader, :call, {ExCmd.Process, :read, 2}, {:legacy_full_probe, true}, at},
         %{scenario: scenario} = state
       )
       when scenario in [:full_frame_eof, :full_frame_overrun] and is_integer(at),
       do: transport_full_fact(state, reader, :probe_call, at)

  defp transport_message(
         {:trace_ts, reader, :return_from, {ExCmd.Process, :read, 2}, result, at},
         %{scenario: scenario} = state
       )
       when scenario in [:full_frame_eof, :full_frame_overrun] and is_integer(at) do
    status =
      case result do
        :eof -> :eof
        {:ok, <<"T">>} -> :byte
        {:ok, [<<"T">>]} -> :byte
        {:ok, [84]} -> :byte
        _ -> :invalid
      end

    transport_full_fact(state, reader, {:probe_return, status}, at)
  end

  defp transport_message(
         {:trace_ts, reader, :call, {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1},
          {:legacy_frame_fact, expected?}, at},
         state
       )
       when is_pid(reader) and is_boolean(expected?) and is_integer(at) do
    valid? =
      state.scenario in [:malformed_payload, :short_frame_trailer] and
        state.started != nil and reader == Enum.at(state.started, 1) and expected? and
        is_nil(state.decode_call)

    %{state | decode_call: at, valid?: state.valid? and valid?}
  end

  defp transport_message(
         {:trace_ts, reader, :return_from, {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1},
          result, at},
         state
       )
       when is_pid(reader) and is_integer(at) do
    status =
      case {state.scenario, result} do
        {:malformed_payload, {:error, :legacy_protocol}} -> :legacy_protocol
        {:short_frame_trailer, {:ok, value}} -> if(value == receipt(), do: :typed, else: :invalid)
        _ -> :invalid
      end

    valid? =
      state.started != nil and reader == Enum.at(state.started, 1) and
        is_integer(state.decode_call) and state.decode_call < at and
        is_nil(state.decode_return) and status != :invalid

    %{state | decode_return: {at, status}, valid?: state.valid? and valid?}
  end

  defp transport_message(
         {:trace_ts, reader, :call, {ExCmd.Process, :read, 2}, {:legacy_one_byte_probe, true},
          at},
         state
       )
       when is_pid(reader) and is_integer(at) do
    reader? = state.started != nil and reader == Enum.at(state.started, 1)

    case state.decode_return do
      {decoded_at, :typed} when state.scenario == :short_frame_trailer ->
        valid? = reader? and decoded_at < at and is_nil(state.probe_call)
        %{state | probe_call: at, valid?: state.valid? and valid?}

      nil ->
        # A fragmented header/body may also need read(handle, 1).
        %{state | valid?: state.valid? and reader?}

      _ ->
        %{state | valid?: false}
    end
  end

  defp transport_message(
         {:trace_ts, reader, :return_from, {ExCmd.Process, :read, 2}, result, at},
         state
       )
       when is_pid(reader) and is_integer(at) do
    reader? = state.started != nil and reader == Enum.at(state.started, 1)

    case state.decode_return do
      {_, :typed} when state.scenario == :short_frame_trailer ->
        byte? =
          case result do
            {:ok, bytes} -> IO.iodata_to_binary(bytes) == <<"T">>
            _ -> false
          end

        valid? =
          reader? and byte? and is_integer(state.probe_call) and state.probe_call < at and
            is_nil(state.probe_return)

        %{state | probe_return: at, valid?: state.valid? and valid?}

      nil ->
        %{state | valid?: state.valid? and reader?}

      _ ->
        %{state | valid?: false}
    end
  end

  defp transport_message({:trace_ts, pid, :exit, _, at}, state)
       when is_pid(pid) and is_integer(at) do
    if pid in (state.started || []) and not Map.has_key?(state.exits, pid),
      do: %{state | exits: Map.put(state.exits, pid, at)},
      else: %{state | valid?: false}
  end

  defp transport_message({:trace_ts, pid, _, _, _}, state) when is_pid(pid) do
    if pid in (state.started || []), do: state, else: %{state | valid?: false}
  end

  defp transport_message({:trace_ts, pid, _, _, _, _}, state) when is_pid(pid) do
    if pid in (state.started || []), do: state, else: %{state | valid?: false}
  end

  defp transport_message({:DOWN, ref, :process, pid, reason}, state) do
    transport_attribution_down(state.key, ref, pid)

    cond do
      state.monitors[ref] == pid ->
        if state.scenario == :reader_down and state.started != nil and
             pid == Enum.at(state.started, 1) do
          %{
            state
            | down: MapSet.put(state.down, pid),
              c4: %{state.c4 | reader_down: System.monotonic_time(), down_ref: ref}
          }
        else
          %{state | down: MapSet.put(state.down, pid)}
        end

      ref == state.actor_monitor and pid == state.actor ->
        transport_cleanup_record(state.key, :actor, ref, pid, reason)
        %{state | actor_down: reason == :normal}

      Process.get({state.key, :owner}) == {pid, ref} ->
        transport_cleanup_record(state.key, :owner, ref, pid, reason)
        state

      true ->
        state
    end
  end

  defp transport_message(
         {key, :workspace_boundary, stage, owner, sample, trigger, valid?},
         %{workspace: _} = state
       )
       when key == state.key and owner == state.owner and stage in [:completed, :drop],
       do: transport_workspace_boundary(state, stage, sample, trigger, valid?)

  defp transport_message(
         {_, :workspace_boundary, _, _, _, _, _},
         %{workspace: workspace} = state
       ),
       do: %{state | workspace: %{workspace | valid?: false}}

  defp transport_message({key, :workspace_allocation, _, _, _}, %{workspace: workspace} = state)
       when key == state.key,
       do: %{state | workspace: %{workspace | valid?: false}}

  defp transport_message({key, :checkpoint, stage, owner, at}, state)
       when key == state.key and owner == state.owner and stage in [:ready, :before_database_drop] and
              is_integer(at),
       do: %{state | checkpoints: Map.put(state.checkpoints, stage, at)}

  defp transport_message({key, :privacy, private?}, state)
       when key == state.key and is_boolean(private?),
       do: %{state | private?: state.private? and private?}

  defp transport_message({key, :outcome, outcome, queued, safe?, private?}, state)
       when key == state.key do
    %{
      state
      | outcome: outcome,
        queued: queued,
        valid?: state.valid? and safe? == true,
        private?: state.private? and private? == true
    }
  end

  defp transport_message({key, :actor_closed, closed?}, state)
       when key == state.key and is_boolean(closed?),
       do: %{state | actor_closed: closed?}

  defp transport_message({key, :diagnostic6_armed, owner, _, _} = message, state)
       when key == state.key and owner == state.owner do
    case transport_diagnostic6_armed(message, state) do
      :unmatched ->
        %{state | valid?: false}

      diagnostic ->
        Process.put({key, :diagnostic6_armed}, diagnostic)
        state
    end
  end

  # TASK18_TRANSPORT_DIAGNOSTIC2_BEGIN
  defp transport_message({key, :diagnostic2_preparation, primary, cleanup}, state)
       when key == state.key do
    Process.put({key, :diagnostic2_preparation}, %{
      primary: transport_diagnostic_primary(primary),
      cleanup: transport_diagnostic_cleanup(cleanup)
    })

    state
  end

  # TASK18_TRANSPORT_DIAGNOSTIC2_END
  # TASK18_TRANSPORT_DIAGNOSTIC3_BEGIN
  defp transport_message({key, :diagnostic3_protocols, values}, state)
       when key == state.key do
    Process.put({key, :diagnostic3_protocols}, transport_diagnostic3_flags(values))
    state
  end

  # TASK18_TRANSPORT_DIAGNOSTIC3_END
  # TASK18_TRANSPORT_DIAGNOSTIC4_BEGIN
  defp transport_message({key, :diagnostic4_stage, stage}, state)
       when key == state.key and
              stage in [
                :before_allocation,
                :allocated,
                :baseline_paused,
                :maintenance_started,
                :database_created,
                :root_created,
                :extensions_ready,
                :before_migration,
                :migrated
              ] do
    transport_diagnostic4_record(key, stage)
    state
  end

  # TASK18_TRANSPORT_DIAGNOSTIC4_END
  defp transport_message({:task18_backend_attribution, nonce, custodian, event}, state) do
    if transport_attribution_late(state.key, nonce, custodian, event),
      do: state,
      else: %{state | valid?: false}
  end

  defp transport_message({key, :diagnostic_actor_failure, actor, kind, origin, reason_tag} = message, state)
       when key == state.key and is_pid(actor) and
         transport_actor_failure_fields(kind, origin, reason_tag) do
    case transport_actor_failure_record(key, message) do
      :accepted -> state
      :rejected -> %{state | valid?: false}
    end
  end

  defp transport_message(_message, state), do: %{state | valid?: false}

  # TASK18_TRANSPORT_DIAGNOSTIC3_BEGIN
  defp transport_diagnostic3_protocols do
    project = Path.expand("../../../../..", __DIR__)

    Map.new(
      [
        {:db_connection_query, DBConnection.Query, :db_connection},
        {:ecto_queryable, Ecto.Queryable, :ecto},
        {:jason_encoder, Jason.Encoder, :jason},
        {:plug_exception, Plug.Exception, :plug}
      ],
      fn {label, module, app} ->
        loaded? = :code.is_loaded(module) != false

        located =
          case :code.which(module) do
            path when is_list(path) -> List.to_string(path)
            _ -> nil
          end

        filename = Atom.to_string(module) <> ".beam"

        expected =
          Path.join([project, "_build", "test", "lib", Atom.to_string(app), "ebin", filename])

        consolidated = Path.join([project, "_build", "test", "consolidated", filename])

        {label,
         %{
           loaded?: loaded?,
           expected_app_ebin?: located == expected,
           exact_parent_consolidated?: located == consolidated
         }}
      end
    )
  end

  defp transport_diagnostic3_flags(values) do
    Map.new([:db_connection_query, :ecto_queryable, :jason_encoder, :plug_exception], fn label ->
      observed =
        case values do
          %{^label => entry} when is_map(entry) -> entry
          _ -> %{}
        end

      {label,
       %{
         loaded?: observed[:loaded?] == true,
         expected_app_ebin?: observed[:expected_app_ebin?] == true,
         exact_parent_consolidated?: observed[:exact_parent_consolidated?] == true
       }}
    end)
  end

  # TASK18_TRANSPORT_DIAGNOSTIC3_END
  # TASK18_TRANSPORT_DIAGNOSTIC2_BEGIN
  defp transport_diagnostic_snapshot(state) do
    started = if is_list(state.started), do: length(state.started), else: 0

    await_status =
      case state.await_return do
        {_at, status} when status in [:zero, :nonzero, :killed, :invalid] -> status
        nil -> :unobserved
        _ -> :invalid
      end

    Process.put({state.key, :diagnostic2_snapshot}, %{
      gate: state.gate == true,
      child_seen: is_integer(state.child),
      started: transport_diagnostic_count(started),
      stages:
        Enum.map(Enum.take(state.stages, 32), fn {_at, stage} ->
          transport_diagnostic_stage(stage)
        end),
      outcome: transport_diagnostic_outcome(state.outcome),
      await_call: is_integer(state.await_call),
      await_status: await_status,
      sql_call: is_integer(state.sql_call),
      sql_zero: is_integer(state.sql_zero),
      closed: is_integer(state.closed),
      absent: state.absent? == true,
      down: transport_diagnostic_count(MapSet.size(state.down)),
      exits: transport_diagnostic_count(map_size(state.exits)),
      checkpoints:
        Enum.filter([:ready, :before_database_drop], &Map.has_key?(state.checkpoints, &1)),
      valid: state.valid? == true,
      private: state.private? == true,
      actor_closed: state.actor_closed == true,
      actor_down: state.actor_down == true
    })
  end

  defp transport_diagnostic_count(count) when is_integer(count) and count in 0..32, do: count
  defp transport_diagnostic_count(_), do: :over_limit

  defp transport_diagnostic_outcome(nil), do: :unobserved
  defp transport_diagnostic_outcome({:ok, true}), do: :ok
  defp transport_diagnostic_outcome({:ok, false}), do: :receipt_mismatch
  defp transport_diagnostic_outcome({:error, :legacy_protocol, []}), do: :legacy_protocol
  defp transport_diagnostic_outcome({:error, :legacy_output_limit, []}), do: :legacy_output_limit

  defp transport_diagnostic_outcome(value) when value in [:unexpected_preparation, :actor_failed],
    do: value

  defp transport_diagnostic_outcome(_), do: :unexpected

  defp transport_diagnostic_stage({:started, _, _, _}), do: :started
  defp transport_diagnostic_stage({:reader_rejected, :legacy_protocol}), do: :reader_rejected
  defp transport_diagnostic_stage({:reader_rejected, :legacy_output_limit}), do: :reader_rejected
  defp transport_diagnostic_stage({:stdin_closed, _}), do: :stdin_closed
  defp transport_diagnostic_stage({:reader_eof, _}), do: :reader_eof
  defp transport_diagnostic_stage({:await_started, _}), do: :await_started

  defp transport_diagnostic_stage({:await_complete, status})
       when status in [:zero, :nonzero, :unconfirmed],
       do: status

  defp transport_diagnostic_stage({:cleanup, status}) when status in [:closed, :unconfirmed],
    do: status

  defp transport_diagnostic_stage(stage) when stage in [:workers_down, :child_connections_absent],
    do: stage

  defp transport_diagnostic_stage(_), do: :unexpected

  defp transport_diagnostic_primary(category)
       when category in [
              :legacy_protocol,
              :legacy_output_limit,
              :legacy_pipe,
              :legacy_start,
              :legacy_exit,
              :legacy_deadline,
              :legacy_caller_down,
              :legacy_identity,
              :legacy_dependency_identity,
              :legacy_preparation
            ],
       do: category

  defp transport_diagnostic_primary(_), do: :other

  defp transport_diagnostic_cleanup(failures) when is_list(failures) do
    items = Enum.take(failures, 17)

    if length(items) <= 16,
      do: Enum.map(items, &transport_diagnostic_cleanup_category/1),
      else: [:over_limit]
  end

  defp transport_diagnostic_cleanup(_), do: [:invalid]

  defp transport_diagnostic_cleanup_category({:legacy_preparation_quarantined, :running}),
    do: :quarantined_running

  defp transport_diagnostic_cleanup_category({:legacy_preparation_quarantined, :unconfirmed}),
    do: :quarantined_unconfirmed

  defp transport_diagnostic_cleanup_category({step, _, _}),
    do: transport_diagnostic_cleanup_step(step)

  defp transport_diagnostic_cleanup_category({step, _}),
    do: transport_diagnostic_cleanup_step(step)

  defp transport_diagnostic_cleanup_category(step), do: transport_diagnostic_cleanup_step(step)

  defp transport_diagnostic_cleanup_step({step, _, _}),
    do: transport_diagnostic_cleanup_step(step)

  defp transport_diagnostic_cleanup_step({step, _}), do: transport_diagnostic_cleanup_step(step)

  defp transport_diagnostic_cleanup_step(step)
       when step in [
              :quarantined_running,
              :quarantined_unconfirmed,
              :stop_infrastructure,
              :stop_repository,
              :stop_maintenance,
              :drop_database,
              :remove_root,
              :restore_configs,
              :restore_compiler,
              :restore_runtime,
              :restore_repository,
              :owned_process_exited,
              :unconfirmed_child_cleanup,
              :unconfirmed_parent_acknowledgment,
              :checkpoint_failed,
              :other,
              :over_limit,
              :invalid
            ],
       do: step

  defp transport_diagnostic_cleanup_step(_), do: :other
  # TASK18_TRANSPORT_DIAGNOSTIC2_END
  defp transport_valid?(%{scenario: scenario} = state)
       when scenario in @transport_eof_modes,
       do: transport_eof_valid?(state)

  defp transport_valid?(%{scenario: scenario} = state)
       when scenario in [:deadline_control, :deadline_expired],
       do: transport_deadline_valid?(state)

  defp transport_valid?(%{scenario: scenario} = state)
       when scenario in [:writer_wait_control, :writer_down],
       do: transport_writer_valid?(state)

  defp transport_valid?(%{scenario: scenario} = state)
       when scenario in [:blocked_reader_control, :reader_down],
       do: transport_c4_valid?(state)

  defp transport_valid?(state) do
    stages = Enum.map(state.stages, &elem(&1, 1))
    await_at = state.await_return && elem(state.await_return, 0)

    ordered? =
      is_integer(state.await_call) and is_integer(await_at) and
        is_integer(state.sql_zero) and is_integer(state.closed) and
        state.await_call < await_at and await_at < state.sql_zero and
        state.sql_zero < state.closed

    common? =
      state.valid? and state.gate and is_integer(state.child) and state.absent? and
        state.started != nil and Enum.all?(state.started, &MapSet.member?(state.down, &1)) and
        Enum.all?(state.started, fn pid ->
          is_integer(state.exits[pid]) and is_integer(state.closed) and
            state.exits[pid] <= state.closed
        end) and
        state.queued == stages and :workers_down in stages and :child_connections_absent in stages and
        {:cleanup, :closed} in stages and ordered?

    stdin_closed =
      Enum.find_value(state.stages, fn
        {at, {:stdin_closed, writer}} ->
          if state.started && writer == List.last(state.started), do: at

        _ ->
          nil
      end)

    case state.scenario do
      :full_frame_eof ->
        eof =
          Enum.find_value(state.stages, fn
            {at, {:reader_eof, reader}} ->
              if state.started && reader == Enum.at(state.started, 1), do: at

            _ ->
              nil
          end)

        common? and elem(state.await_return, 1) == :zero and is_integer(stdin_closed) and
          is_integer(eof) and stdin_closed < eof and eof < state.await_call and
          is_integer(state.checkpoints[:ready]) and state.checkpoints[:ready] > state.closed

      :clean_frame ->
        eof =
          Enum.find_value(state.stages, fn
            {at, {:reader_eof, reader}} ->
              if state.started && reader == Enum.at(state.started, 1), do: at

            _ ->
              nil
          end)

        common? and elem(state.await_return, 1) == :zero and is_integer(stdin_closed) and
          is_integer(eof) and stdin_closed < eof and eof < state.await_call and
          state.checkpoints[:ready] > state.closed

      :full_frame_overrun ->
        rejected =
          Enum.find_value(state.stages, fn
            {at, {:reader_rejected, :legacy_output_limit}} -> at
            _ -> nil
          end)

        common? and is_integer(stdin_closed) and is_integer(rejected) and
          stdin_closed < rejected and rejected < state.await_call and
          elem(state.await_return, 1) in [:nonzero, :killed] and
          not Map.has_key?(state.checkpoints, :ready) and
          is_integer(state.checkpoints[:before_database_drop]) and
          state.checkpoints[:before_database_drop] > state.closed

      :stderr_prefix ->
        rejected =
          Enum.find_value(state.stages, fn
            {at, {:reader_rejected, :legacy_protocol}} -> at
            _ -> nil
          end)

        common? and is_integer(rejected) and is_integer(stdin_closed) and rejected < stdin_closed and
          stdin_closed < state.await_call and
          not Map.has_key?(state.checkpoints, :ready) and
          state.checkpoints[:before_database_drop] > state.closed

      scenario when scenario in [:malformed_payload, :short_frame_trailer] ->
        rejected =
          Enum.find_value(state.stages, fn
            {at, {:reader_rejected, :legacy_protocol}} -> at
            _ -> nil
          end)

        reader_ordered? =
          case {scenario, state.decode_return} do
            {:malformed_payload, {decoded_at, :legacy_protocol}} ->
              is_integer(rejected) and decoded_at < rejected and rejected < stdin_closed and
                is_nil(state.probe_call) and is_nil(state.probe_return)

            {:short_frame_trailer, {decoded_at, :typed}} ->
              is_integer(state.probe_call) and is_integer(state.probe_return) and
                is_integer(rejected) and decoded_at < stdin_closed and
                stdin_closed < state.probe_call and state.probe_call < state.probe_return and
                state.probe_return < rejected

            _ ->
              false
          end

        common? and reader_ordered? and is_integer(stdin_closed) and
          stdin_closed < state.await_call and
          not Map.has_key?(state.checkpoints, :ready) and
          state.checkpoints[:before_database_drop] > state.closed

      scenario when scenario in [:ascii_stderr_flood, :declared_oversize] ->
        rejected =
          Enum.find_value(state.stages, fn
            {at, {:reader_rejected, :legacy_output_limit}} -> at
            _ -> nil
          end)

        header = state.header
        reader = state.started && Enum.at(state.started, 1)

        # Logical retained header/request bounds, not a literal VM heap ceiling.
        header? =
          is_integer(header.start) and is_integer(header.complete) and
            header.start < header.complete and header.remaining == 0 and
            is_nil(header.requested) and header.steps in 2..5 and header.reads in 1..4 and
            header.steps == header.reads + 1 and is_nil(state.decode_call) and
            is_nil(state.decode_return) and is_nil(state.probe_call) and
            is_nil(state.probe_return)

        common? and header? and is_integer(rejected) and header.complete < rejected and
          is_integer(stdin_closed) and rejected < stdin_closed and stdin_closed < state.await_call and
          elem(state.await_return, 1) in [:nonzero, :killed] and
          is_integer(state.exits[reader]) and header.complete < state.exits[reader] and
          MapSet.member?(state.down, reader) and not Map.has_key?(state.checkpoints, :ready) and
          state.checkpoints[:before_database_drop] > state.closed
    end
  end

  # TASK18_C4_BLOCKED_READER_OBSERVER_BEGIN
  defp transport_c4_initial do
    %{
      reader: nil,
      read: nil,
      pending: nil,
      blocked: nil,
      waiting?: false,
      trigger: nil,
      reader_down: nil,
      down_ref: nil,
      release: nil,
      hold: nil,
      acquired?: false,
      ack_tag: nil,
      ack: nil,
      owned?: false,
      resumed: nil
    }
  end

  defp transport_c4_preparation(_scenario, primary, cleanup, private?),
    do:
      {{:error, transport_diagnostic_primary(primary), transport_diagnostic_cleanup(cleanup)},
       private? == true}

  defp transport_c4_fact(state, pid, fact, at) do
    c4 = state.c4

    expected =
      case fact do
        :read -> state.started && Enum.at(state.started, 1)
        :pending -> state.started && hd(state.started)
      end

    # The two real tracees can deliver out of order; compare their actual timestamps.
    ordered? =
      case {fact, c4.read, c4.pending} do
        {:read, _, pending} when is_integer(pending) -> at < pending
        {:pending, read, _} when is_integer(read) -> read < at
        _ -> true
      end

    valid? =
      pid == expected and is_nil(Map.fetch!(c4, fact)) and ordered? and is_nil(c4.trigger)

    %{state | c4: Map.put(c4, fact, at), valid?: state.valid? and valid?}
  end

  defp transport_c4_trace_patterns(scenario) do
    if scenario in [:blocked_reader_control, :reader_down] do
      transport_require!(Code.ensure_loaded?(ExCmd.Process.State))

      Enum.map(
        [:traced, :match_spec, :meta, :meta_match_spec],
        &:erlang.trace_info({ExCmd.Process.State, :put_operation, 2}, &1)
      )
    else
      []
    end
  end

  defp transport_c4_hold_valid?(state) do
    c4 = state.c4

    case c4.hold do
      {key, owner, tag} when key == state.key and owner == state.owner and is_reference(tag) ->
        c4.acquired? == true and c4.ack_tag == tag and is_integer(c4.ack) and
          c4.blocked <= c4.ack and c4.ack < c4.release and
          is_integer(c4.resumed) and c4.release <= c4.resumed and c4.owned? == false

      _ ->
        false
    end
  end

  defp transport_c4_emergency_resume(key) do
    case Process.get({key, :c4_hold}) do
      nil ->
        true

      {^key, owner, tag} when is_pid(owner) and is_reference(tag) ->
        try do
          resumed? = :erlang.resume_process(owner) == true
          if resumed?, do: Process.delete({key, :c4_hold})
          resumed?
        catch
          _, _ -> false
        end

      _ ->
        false
    end
  end

  defp transport_c4_patterns!(session, owner, command, reader) do
    transport_require!(Code.ensure_loaded?(ExCmd.Process.State))

    handle = %{
      __struct__: ExCmd.Process,
      pid: command,
      owner: owner,
      monitor_ref: :"$1",
      exit_ref: :"$2"
    }

    transport_require!(
      :trace.function(
        session,
        {ExCmd.Process, :read, 2},
        [
          {[handle, 4], [{:is_reference, :"$1"}, {:is_reference, :"$2"}],
           [{:message, {{:legacy_c4_read, true}}}]}
        ],
        []
      ) == 1
    )

    transport_require!(
      :trace.function(
        session,
        {ExCmd.Process.State, :put_operation, 2},
        [{[:_, {:read_stdout, {reader, :_}, 4}], [], [{:message, {{:legacy_c4_pending, true}}}]}],
        []
      ) == 1
    )
  end

  defp transport_c4_valid?(state) do
    c4 = state.c4
    reader = state.started && Enum.at(state.started, 1)

    blocked? =
      state.valid? and is_pid(reader) and c4.reader == reader and
        is_integer(c4.read) and is_integer(c4.pending) and is_integer(c4.blocked) and
        c4.read < c4.pending and c4.pending <= c4.blocked and c4.waiting? == true and
        is_integer(c4.release) and c4.blocked < c4.release and
        transport_c4_hold_valid?(state) and is_integer(state.await_call) and
        c4.resumed < state.await_call

    if state.scenario == :blocked_reader_control do
      blocked? and is_nil(c4.trigger) and
        transport_valid?(%{state | scenario: :clean_frame})
    else
      stages = Enum.map(state.stages, &elem(&1, 1))
      await_at = state.await_return && elem(state.await_return, 0)
      status = state.await_return && elem(state.await_return, 1)
      reader_exit = state.exits[reader]

      blocked? and is_integer(c4.trigger) and c4.ack <= c4.trigger and
        is_integer(c4.reader_down) and c4.trigger < c4.reader_down and
        is_reference(c4.down_ref) and state.monitors[c4.down_ref] == reader and
        is_integer(reader_exit) and c4.trigger < reader_exit and
        c4.reader_down < c4.release and reader_exit < c4.release and
        is_integer(state.await_call) and c4.resumed < state.await_call and
        is_integer(await_at) and state.await_call < await_at and
        status in [:zero, :nonzero, :killed] and
        is_integer(state.sql_zero) and await_at < state.sql_zero and
        is_integer(state.closed) and state.sql_zero < state.closed and
        state.gate and is_integer(state.child) and state.absent? and
        length(state.started) == 3 and
        Enum.all?(state.started, &MapSet.member?(state.down, &1)) and
        Enum.all?(state.started, fn pid ->
          is_integer(state.exits[pid]) and state.exits[pid] < state.closed
        end) and state.queued == stages and
        :workers_down in stages and :child_connections_absent in stages and
        {:cleanup, :closed} in stages and
        not Map.has_key?(state.checkpoints, :ready) and
        is_integer(state.checkpoints[:before_database_drop]) and
        state.closed < state.checkpoints[:before_database_drop]
    end
  end

  # Pure contract data only; not an actual child or blocked-pipe observation.
  defp transport_c4_pure_state do
    owner = self()
    command = Process.whereis(:init)
    reader = Process.whereis(:code_server)
    writer = Process.whereis(:application_controller)
    ref = make_ref()
    key = make_ref()
    tag = make_ref()
    workers = [command, reader, writer]

    stages = [
      {1, {:started, command, reader, writer}},
      {14, {:await_started, command}},
      {15, {:await_complete, :nonzero}},
      {16, :workers_down},
      {17, :child_connections_absent},
      {18, {:cleanup, :closed}}
