  # TASK18_WRITER_LOSS_OBSERVER_BEGIN
  defp transport_writer_clock_unit?({1_000_000_000, 1}), do: true
  defp transport_writer_clock_unit?(_), do: false

  defp transport_writer_initial(scenario) do
    %{
      writer: nil,
      command: nil,
      owner: nil,
      run: nil,
      monitor: nil,
      started_at: nil,
      write: nil,
      blocked: nil,
      phase: nil,
      gate_checked: nil,
      baseline?: false,
      repos?: false,
      hold: nil,
      acquired?: false,
      owned?: false,
      ack_tag: nil,
      ack: nil,
      rechecked: nil,
      trigger: nil,
