      down: nil,
      down_ref: nil,
      down_reason: nil,
      exit: nil,
      exit_reason: nil,
      release: nil,
      resumed: nil,
      control?:
        scenario == :writer_wait_control or
          Process.get({__MODULE__, :writer_control}) == true
    }
  end

  defp transport_writer_trace_patterns(scenario) do
    if scenario in [:writer_wait_control, :writer_down] do
      Enum.map(
        [:traced, :match_spec, :meta, :meta_match_spec],
        &:erlang.trace_info({ExCmd.Process, :write, 2}, &1)
      )
    else
      []
    end
  end

  defp transport_writer_pattern!(session, owner, command) do
    handle = %{
      __struct__: ExCmd.Process,
      pid: command,
      owner: owner,
      monitor_ref: :"$1",
      exit_ref: :"$2"
    }

    transport_require!(
      :trace.function(
        session,
        {ExCmd.Process, :write, 2},
        [
          {[handle, :_], [{:is_reference, :"$1"}, {:is_reference, :"$2"}],
           [{:message, {{:legacy_writer_write, true}}}]}
        ],
        []
      ) == 1
    )
  end

  defp transport_writer_waiting?(writer) do
    Process.info(writer, [:status, :current_function]) ==
      [status: :waiting, current_function: {LegacyUpgradeRuntimeFixture, :transport_writer, 4}]
  end

  defp transport_writer_gate(state) do
    w = state.writer_loss

    if state.valid? and state.started != nil and is_integer(w.write) do
      [command, reader, writer] = state.started

      rows =
        transport_rows(
          state.connection,
          "SELECT pid,wait_event_type='Lock' AND wait_event='advisory' FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND application_name=$2 ORDER BY pid",
          [state.destination.database, @transport_tag]
        )

      case rows do
        [[pid, true]] when is_integer(pid) and pid > 0 ->
          transport_require!(w.control? and w.writer == writer and w.command == command)
          transport_require!(w.run == state.run and w.owner == state.owner)
          transport_require!(state.monitors[w.monitor] == writer)

          transport_require!(
            transport_gate_backends(state, pid, 2) --
              [{pid, "singularity_migration"}] == state.baseline
          )

          transport_require!(Map.new(@transport_repos, &{&1, Process.whereis(&1)}) == state.repos)
          transport_require!(Enum.all?(state.repos, fn {_repo, p} -> Process.alive?(p) end))

          cond do
            is_nil(w.hold) ->
              if transport_writer_waiting?(writer) do
                transport_require!(Enum.all?(state.started, &Process.alive?/1))
                transport_require!(Process.alive?(state.owner))
                transport_require!(is_nil(Process.get({state.key, :c4_hold})))
                at = System.monotonic_time()
                tag = make_ref()

                transport_require!(
                  :erlang.suspend_process(
                    state.owner,
                    [:unless_suspending, {:asynchronous, tag}]
                  ) == true
                )

                hold = {state.key, state.owner, tag}
                Process.put({state.key, :c4_hold}, hold)

                %{
                  state
                  | child: pid,
                    writer_loss: %{
                      w
                      | blocked: at,
                        phase: :close_wait,
                        gate_checked: at,
                        baseline?: true,
                        repos?: true,
                        hold: hold,
                        acquired?: true,
                        owned?: true
                    }
                }
              else
                state
              end

            is_nil(w.ack) ->
              state

            state.scenario == :writer_down and is_nil(w.trigger) ->
              transport_require!(Process.info(state.owner, :status) == {:status, :suspended})
              transport_require!(transport_writer_waiting?(writer))
              transport_require!(Enum.all?(state.started, &Process.alive?/1))
              transport_require!(Process.get({state.key, :c4_hold}) == w.hold)
              transport_require!(w.triggers == 0)
              checked = System.monotonic_time()
              triggered = System.monotonic_time()
              transport_require!(Process.exit(writer, :kill))

              %{
                state
                | writer_loss: %{w | rechecked: checked, trigger: triggered, triggers: 1}
              }

            state.scenario == :writer_down and (is_nil(w.down) or is_nil(w.exit)) ->
              state

            true ->
              transport_require!(Process.info(state.owner, :status) == {:status, :suspended})
              transport_require!(Process.alive?(command) and Process.alive?(reader))
              transport_require!(Process.get({state.key, :c4_hold}) == w.hold)

              checked =
                if state.scenario == :writer_wait_control do
                  transport_require!(transport_writer_waiting?(writer))
                  transport_require!(Process.alive?(writer))
                  System.monotonic_time()
                else
                  transport_require!(w.down_reason == :killed and w.exit_reason == :killed)
                  w.rechecked
                end

              transport_require!(
                transport_rows(
                  state.connection,
                  "SELECT pg_advisory_unlock($1::integer,$2::integer)",
                  @transport_lock
                ) == [[true]]
              )

              released = System.monotonic_time()
              Process.put({state.key, :locked}, false)
              resumed = System.monotonic_time()
              transport_require!(:erlang.resume_process(state.owner) == true)
              Process.delete({state.key, :c4_hold})

              %{
                state
                | gate: true,
                  child: pid,
                  writer_loss: %{
                    w
                    | rechecked: checked,
                      release: released,
                      resumed: resumed,
                      owned?: false
                  }
              }
          end

        [] ->
          state

        [[_, waiting]] when waiting in [false, nil] ->
          state

        _ ->
          throw(:legacy_transport_observer)
      end
    else
      state
    end
  end

  defp transport_writer_reason(reason) when reason in [:normal, :killed], do: reason
  defp transport_writer_reason(_), do: :other

  defp transport_writer_valid?(
         %{
           writer_loss:
             %{
               writer: _,
               command: _,
               owner: _,
               run: _,
               monitor: _,
               started_at: _,
               write: _,
               blocked: _,
               phase: _,
               gate_checked: _,
               baseline?: _,
               repos?: _,
               hold: _,
               acquired?: _,
               owned?: _,
               ack_tag: _,
               ack: _,
               rechecked: _,
               trigger: _,
               triggers: _,
               down: _,
               down_ref: _,
               down_reason: _,
               exit: _,
               exit_reason: _,
               release: _,
               resumed: _,
               control?: _
             } = w,
           started: [command, reader, writer],
           owner: _,
           run: _,
           key: _,
           monitors: _,
           stages: _,
           await_call: _,
           await_return: _,
           sql_zero: _,
           closed: _,
           valid?: _,
           gate: _,
           child: _,
           absent?: _,
           down: _,
           exits: _,
           queued: _,
           scenario: _,
           checkpoints: _
         } = state
       )
       when map_size(w) == 28 and is_map(state.monitors) and is_list(state.stages) and
              is_map(state.exits) and is_map(state.checkpoints) and is_struct(state.down, MapSet) do
    identity? =
      is_pid(command) and is_pid(reader) and is_pid(writer) and
        length(Enum.uniq(state.started)) == 3 and w.writer == writer and
        w.command == command and w.owner == state.owner and is_pid(state.owner) and
        is_reference(state.run) and w.run == state.run and
        is_reference(w.monitor) and state.monitors[w.monitor] == writer and
        w.down_ref == w.monitor and is_integer(w.started_at) and is_integer(w.write) and
        w.started_at < w.write and is_integer(w.blocked) and
        w.write < w.blocked and w.phase == :close_wait and
        is_integer(w.gate_checked) and w.write < w.gate_checked and
        w.baseline? == true and w.repos? == true and w.control? == true

    held? =
      case w.hold do
        {key, owner, tag} when key == state.key and owner == state.owner and is_reference(tag) ->
          w.acquired? == true and w.owned? == false and w.ack_tag == tag and
            is_integer(w.ack) and w.blocked <= w.ack and is_integer(w.rechecked) and
            w.ack <= w.rechecked and is_integer(w.release) and w.rechecked < w.release and
            is_integer(w.resumed) and w.release <= w.resumed

        _ ->
          false
      end

    times = [state.await_call, state.sql_zero, state.closed, w.down, w.exit]
    stages = Enum.map(state.stages, &elem(&1, 1))

    case state.await_return do
      {await_at, status} when is_integer(await_at) and status in [:zero, :nonzero, :killed] ->
        helper_status = if status == :killed, do: :nonzero, else: status

        common? =
          state.valid? == true and identity? and held? and Enum.all?(times, &is_integer/1) and
            w.resumed < state.await_call and state.await_call < await_at and
            await_at < state.sql_zero and state.sql_zero < state.closed and
            state.gate == true and is_integer(state.child) and state.child > 0 and
            state.absent? == true and MapSet.size(state.down) == 3 and
            Enum.all?(state.started, &MapSet.member?(state.down, &1)) and
            map_size(state.exits) == 3 and
            Enum.all?(state.started, fn pid ->
              is_integer(state.exits[pid]) and state.exits[pid] < state.closed
            end) and state.exits[writer] == w.exit and state.queued == stages and
            Enum.count(stages, &(&1 == {:await_started, command})) == 1 and
            Enum.count(stages, &(&1 == {:await_complete, helper_status})) == 1 and
            :workers_down in stages and :child_connections_absent in stages and
            {:cleanup, :closed} in stages

        if state.scenario == :writer_wait_control do
          common? and is_nil(w.trigger) and w.triggers == 0 and
            w.down_reason == :normal and w.exit_reason == :normal and
            w.resumed < w.down and w.resumed < w.exit and
            transport_valid?(%{state | scenario: :clean_frame})
        else
          common? and state.scenario == :writer_down and is_integer(w.trigger) and
            w.triggers == 1 and w.rechecked <= w.trigger and
            w.trigger < w.down and w.trigger < w.exit and
            w.down_reason == :killed and w.exit_reason == :killed and
            w.down < w.release and w.exit < w.release and
            not Map.has_key?(state.checkpoints, :ready) and
            is_integer(state.checkpoints[:before_database_drop]) and
            state.closed < state.checkpoints[:before_database_drop]
        end

      _ ->
        false
    end
  end

  defp transport_writer_valid?(_), do: false

  defp transport_writer_final_valid?(state, facts) do
    case facts do
      %{
        trace?: true,
        actor?: true,
        workspace?: true,
        privacy?: true,
        registered?: true,
        cleanup: %{actor: :confirmed, owner: :normal} = cleanup
      }
      when map_size(facts) == 6 and map_size(cleanup) == 2 ->
        transport_writer_valid?(state)

      _ ->
        false
    end
  end

  # Pure literal witness only, not a simulated writer or actual subprocess proof.
  defp transport_writer_pure_witness do
