  # TASK18_WRITER_LOSS_OBSERVER_END

  # TASK18_DEADLINE_OBSERVER_BEGIN
  defp transport_deadline_initial(scenario, owner, caller) do
    %{
      owner: owner,
      caller: caller,
      run: nil,
      original: nil,
      pending: nil,
      active: nil,
      last_receive: nil,
      receives: 0,
      read: nil,
      operation: nil,
      blocked: nil,
      baseline?: false,
      repos?: false,
      unheld?: false,
      finish: nil,
      primary: nil,
      release: nil,
      downs: %{},
      prior_control?:
        scenario == :deadline_control or
          Process.get({__MODULE__, :deadline_control}) == true
    }
  end

  defp transport_deadline_snapshot(session, owner) do
    mfas = [
      {LegacyUpgradeRuntimeFixture, :transport_receive, 1},
      {LegacyUpgradeRuntimeFixture, :transport_finish, 2}
    ]

    dimensions = [:traced, :match_spec, :meta, :meta_match_spec]

    %{
      legacy:
        Enum.map(mfas ++ [{ExCmd.Process.State, :put_operation, 2}], fn mfa ->
          Enum.map(dimensions, &:erlang.trace_info(mfa, &1))
        end),
      dynamic: Enum.map(mfas, fn mfa -> Enum.map(dimensions, &:trace.info(session, mfa, &1)) end),
      owner: Enum.map([:flags, :tracer], &:trace.info(session, owner, &1))
    }
  end

  defp transport_deadline_trace_start(key, scenario, original, owner, caller)
       when scenario in [:deadline_control, :deadline_expired] do
    transport_require!(Code.ensure_loaded?(ExCmd.Process.State))
    before = transport_deadline_snapshot(original, owner)
    session = :trace.session_create(:task18_deadline_scalar, self(), [])
    Process.put({key, :deadline_session}, session)

    handle = %{
      __struct__: ExCmd.Process,
      owner: owner,
      pid: :"$3",
      monitor_ref: :"$4",
      exit_ref: :"$5"
    }

    common = %{handle: handle, caller: caller, run: :"$1", deadline: :"$2"}

    guards = [
      {:is_reference, :"$1"},
      {:is_integer, :"$2"},
      {:is_pid, :"$3"},
      {:is_reference, :"$4"},
      {:is_reference, :"$5"}
    ]

    receive_patterns =
      for {pending, tag} <- [{self(), :pending}, {nil, :active}] do
        {[Map.put(common, :pending_observer, pending)], guards,
         [{:message, {{:legacy_deadline_receive, :"$1", :"$2", tag}}}]}
      end

    finish_patterns =
      for {primary, tag} <- [{nil, nil}, {:legacy_deadline, :legacy_deadline}, {:_, :other}] do
        {[Map.put(common, :primary, primary), :_], guards,
         [{:message, {{:legacy_deadline_finish, :"$1", :"$2", tag}}}]}
      end

    transport_require!(
      :trace.function(
        session,
        {LegacyUpgradeRuntimeFixture, :transport_receive, 1},
        receive_patterns,
        [:local]
      ) == 1
    )

    transport_require!(
      :trace.function(
        session,
        {LegacyUpgradeRuntimeFixture, :transport_finish, 2},
        finish_patterns,
        [:local]
      ) == 1
    )

    transport_require!(
      :trace.process(session, owner, true, [:call, :arity, :monotonic_timestamp]) == 1
    )

    before
  end

  defp transport_deadline_trace_start(_, _, _, _, _), do: nil

  defp transport_deadline_reader_patterns!(session, owner, command, reader) do
    handle = %{
      __struct__: ExCmd.Process,
      pid: command,
      owner: owner,
      monitor_ref: :"$1",
      exit_ref: :"$2"
    }

    transport_require!(
      :trace.function(
        session,
        {ExCmd.Process, :read, 2},
        [
          {[handle, 4], [{:is_reference, :"$1"}, {:is_reference, :"$2"}],
           [{:message, {{:legacy_deadline_read, true}}}]}
        ],
        []
      ) == 1
    )

    transport_require!(
      :trace.function(
        session,
        {ExCmd.Process.State, :put_operation, 2},
        [
          {[:_, {:read_stdout, {reader, :_}, 4}], [],
           [{:message, {{:legacy_deadline_operation, true}}}]}
        ],
        []
      ) == 1
    )
  end

  defp transport_deadline_trace_close(state, nil), do: {state, true}

  defp transport_deadline_trace_close(state, before) do
    session = Process.get({state.key, :deadline_session})
    original = Process.get({state.key, :session})
    # Explicit delivery fences, including dead original tracees; destroy is not a drain.
    state = transport_deadline_fence(state, session, state.owner)

    state =
      Enum.reduce([state.owner | state.started], state, fn pid, acc ->
        transport_deadline_fence(acc, original, pid)
      end)

    transport_require!(:trace.session_destroy(session) == true)
    Process.delete({state.key, :deadline_session})
    state = transport_deadline_tail(state, 0)
    after_snapshot = transport_deadline_snapshot(original, state.owner)

    owner? =
      if Process.alive?(state.owner) do
        after_snapshot.owner == before.owner
      else
        {owner, ref} = Process.get({state.key, :owner})
        transport_require!(owner == state.owner and is_reference(ref))

        case transport_cleanup_witness(
               state.key,
               owner,
               ref,
               Process.get({state.key, {:cleanup_down, :owner}})
             ) do
          :normal ->
            true

          :unconfirmed ->
            receive do
              {:DOWN, ^ref, :process, ^owner, reason} ->
                transport_cleanup_record(state.key, :owner, ref, owner, reason)
                reason == :normal
            after
              max(0, state.deadline - System.monotonic_time(:millisecond)) -> false
            end

          _ ->
            false
        end
      end

    {state,
     owner? and before.legacy == after_snapshot.legacy and
       before.dynamic == after_snapshot.dynamic}
  end

  defp transport_deadline_fence(state, session, pid) do
    ref = :trace.delivered(session, pid)
    transport_deadline_fence_wait(state, pid, ref)
  end

  defp transport_deadline_fence_wait(state, pid, ref) do
    transport_require!(System.monotonic_time(:millisecond) < state.deadline)

    receive do
      {:trace_delivered, ^pid, ^ref} -> state
      message -> transport_deadline_fence_wait(transport_message(message, state), pid, ref)
    after
      max(0, state.deadline - System.monotonic_time(:millisecond)) ->
        throw(:legacy_transport_observer)
    end
  end

  defp transport_deadline_tail(state, 32), do: %{state | valid?: false}

  defp transport_deadline_tail(state, count) do
    receive do
      {:trace_ts, _, :call, {LegacyUpgradeRuntimeFixture, function, _}, _, _} = message
      when function in [:transport_receive, :transport_finish] ->
        transport_deadline_tail(transport_message(message, state), count + 1)

      {:trace_ts, _, :call, {LegacyUpgradeRuntimeFixture, function, _}, _} = message
      when function in [:transport_receive, :transport_finish] ->
        transport_deadline_tail(transport_message(message, state), count + 1)
    after
      0 -> state
    end
  end

  defp transport_deadline_emergency(key) do
    case Process.get({key, :deadline_session}) do
      nil ->
        true

      session ->
        try do
          closed? = :trace.session_destroy(session) == true
          if closed?, do: Process.delete({key, :deadline_session})
          closed?
        catch
          _, _ -> false
        end
    end
  end

  defp transport_deadline_ms(at), do: System.convert_time_unit(at, :nanosecond, :millisecond)

  defp transport_deadline_gate(%{deadline_loss: %{blocked: blocked}} = state)
       when is_integer(blocked) do
    d = state.deadline_loss

    cond do
      state.scenario == :deadline_control ->
        transport_require!(transport_deadline_ms(System.monotonic_time(:nanosecond)) < d.original)
        transport_deadline_unlock(state)

      is_integer(d.finish) and is_integer(state.await_call) ->
        transport_require!(state.valid? and d.primary == :legacy_deadline)

        transport_require!(
          transport_deadline_ms(d.finish) >= d.original and d.finish <= state.await_call
        )

        transport_deadline_unlock(state)

      true ->
        state
    end
  end

  defp transport_deadline_gate(state) do
    d = state.deadline_loss

    if state.valid? and state.started != nil and
         Enum.all?([d.pending, d.active, d.read, d.operation], &is_integer/1) do
      [_, reader, _] = state.started

      rows =
        transport_rows(
          state.connection,
          "SELECT pid,wait_event_type='Lock' AND wait_event='advisory' FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND application_name=$2 ORDER BY pid",
          [state.destination.database, @transport_tag]
        )

      case rows do
        [[pid, true]] when is_integer(pid) and pid > 0 ->
          if Process.info(reader, [:status, :current_function]) ==
               [status: :waiting, current_function: {:gen, :do_call, 4}] do
            transport_require!(d.prior_control? and Process.alive?(state.owner))
            transport_require!(Enum.all?(state.started, &Process.alive?/1))

            transport_require!(
              map_size(state.monitors) == 3 and
                Enum.sort(Map.values(state.monitors)) == Enum.sort(state.started)
            )

            transport_require!(
              Process.get({state.key, :c4_hold}) == nil and
                Process.info(state.owner, :status) != {:status, :suspended}
            )

            transport_require!(
              transport_gate_backends(state, pid) --
                [{pid, "singularity_migration"}] == state.baseline
            )

            transport_require!(
              Map.new(@transport_repos, &{&1, Process.whereis(&1)}) == state.repos and
                Enum.all?(state.repos, fn {_, p} -> Process.alive?(p) end)
            )

            transport_require!(
              d.run == state.run and
                transport_deadline_ms(System.monotonic_time(:nanosecond)) < d.original
            )

            %{
              state
              | child: pid,
                deadline_loss: %{
                  d
                  | blocked: System.monotonic_time(:nanosecond),
                    baseline?: true,
                    repos?: true,
                    unheld?: true
                }
            }
          else
            state
          end

        [] ->
          state

        [[_, waiting]] when waiting in [false, nil] ->
          state

        _ ->
          throw(:legacy_transport_observer)
      end
    else
      state
    end
  end

  defp transport_deadline_unlock(state) do
    transport_require!(Process.alive?(state.owner))

    transport_require!(
      Process.get({state.key, :c4_hold}) == nil and
        Process.info(state.owner, :status) != {:status, :suspended}
    )

    # Entry precedes successful real unlock; a non-suspended owner may finish before its SQL reply.
    released = System.monotonic_time(:nanosecond)

    transport_require!(
      transport_rows(
        state.connection,
        "SELECT pg_advisory_unlock($1::integer,$2::integer)",
        @transport_lock
      ) == [[true]]
    )

    if state.scenario == :deadline_control,
      do: transport_require!(System.monotonic_time(:millisecond) < state.deadline_loss.original)

    Process.put({state.key, :locked}, false)
    %{state | gate: true, deadline_loss: %{state.deadline_loss | release: released}}
  end

  defp transport_deadline_started(%{scenario: scenario} = state, workers, monitors, run, at)
       when scenario in [:deadline_control, :deadline_expired] do
    state = %{state | started: workers, monitors: monitors}
    state = transport_deadline_pending(state)
    d = state.deadline_loss

    transport_require!(
      state.valid? and d.run == run and state.run == run and
        d.owner == state.owner and d.caller == state.actor and
        is_integer(d.original) and is_integer(d.pending) and at <= d.pending and
        map_size(monitors) == 3 and Enum.all?(Map.keys(monitors), &is_reference/1) and
        Enum.sort(Map.values(monitors)) == Enum.sort(workers)
    )

    state
  end

  defp transport_deadline_started(state, _, _, _, _), do: state

  defp transport_deadline_pending(state) do
    transport_require!(state.valid? and System.monotonic_time(:millisecond) < state.deadline)

    if is_integer(state.deadline_loss.pending) do
      state
    else
      receive do
        message -> transport_deadline_pending(transport_message(message, state))
      after
        max(0, state.deadline - System.monotonic_time(:millisecond)) ->
          throw(:legacy_transport_observer)
      end
    end
  end

  defp transport_deadline_fact(state, pid, fact, at) do
    d = state.deadline_loss

    expected =
      if fact == :read, do: Enum.at(state.started || [], 1), else: List.first(state.started || [])

    valid? =
      is_integer(at) and pid == expected and is_nil(Map.fetch!(d, fact)) and is_nil(d.blocked)

    if valid?, do: %{state | deadline_loss: Map.put(d, fact, at)}, else: %{state | valid?: false}
  end

  defp transport_deadline_scalar(state, owner, run, deadline, phase, at) do
    d = state.deadline_loss

    common? =
      owner == state.owner and owner == d.owner and is_reference(run) and
        is_integer(deadline) and is_integer(at) and (state.run == nil or state.run == run)

    case phase do
      :pending ->
        valid? = common? and is_nil(d.pending) and d.receives == 0

        if valid? do
          %{
            state
            | deadline_loss: %{
                d
                | run: run,
                  original: deadline,
                  pending: at,
                  last_receive: at,
                  receives: 1
              }
          }
        else
          %{state | valid?: false}
        end

      :active ->
        valid? =
          common? and d.run == run and d.original == deadline and
            is_integer(d.pending) and d.pending <= at and is_integer(d.last_receive) and
            d.last_receive <= at and is_nil(d.finish) and d.receives < 16

        if valid? do
          %{
            state
            | deadline_loss: %{
                d
                | active: d.active || at,
                  last_receive: at,
                  receives: d.receives + 1
              }
          }
        else
          %{state | valid?: false}
        end

      {:finish, primary} ->
        valid? =
          common? and d.run == run and d.original == deadline and
            is_integer(d.active) and is_integer(d.last_receive) and d.last_receive <= at and
            is_nil(d.finish) and primary in [nil, :legacy_deadline, :other]

        if valid? do
          %{
            state
            | valid?: state.valid? and primary != :other,
              deadline_loss: %{d | finish: at, primary: primary}
          }
        else
          %{state | valid?: false}
        end

      _ ->
        %{state | valid?: false}
    end
  end

  defp transport_deadline_valid?(
         %{
           deadline_loss:
             %{
               owner: _,
               caller: _,
               run: _,
               original: _,
               pending: _,
               active: _,
               last_receive: _,
               receives: _,
               read: _,
               operation: _,
               blocked: _,
               baseline?: _,
               repos?: _,
               unheld?: _,
               finish: _,
               primary: _,
               release: _,
               downs: _,
               prior_control?: _
             } = d,
           started: [command, reader, writer],
           owner: _,
           actor: _,
           run: _,
           valid?: _,
           monitors: _,
           exits: _,
           down: _,
           await_return: _,
           await_call: _,
           sql_zero: _,
           closed: _,
           stages: _,
           queued: _,
           gate: _,
           child: _,
           absent?: _,
           checkpoints: _,
           scenario: _
         } = state
       )
       when map_size(d) == 19 and is_map(d.downs) and is_map(state.monitors) and
              is_map(state.exits) and is_struct(state.down, MapSet) and
              is_list(state.stages) and is_map(state.checkpoints) and is_boolean(state.valid?) do
    times = [
      d.pending,
      d.active,
      d.last_receive,
      d.read,
      d.operation,
      d.blocked,
      d.finish,
      d.release,
      state.await_call,
      state.sql_zero,
      state.closed
    ]

    with true <- state.valid? and Enum.all?(times, &is_integer/1),
         {await_at, status} when is_integer(await_at) and status in [:zero, :nonzero, :killed] <-
           state.await_return do
      stages =
        Enum.map(state.stages, fn
          {_, stage} -> stage
          _ -> :invalid
        end)

      helper_status = if status == :killed, do: :nonzero, else: status

      common? =
        is_pid(state.owner) and is_pid(state.actor) and state.owner != state.actor and
          d.owner == state.owner and d.caller == state.actor and
          is_reference(state.run) and d.run == state.run and is_integer(d.original) and
          length(Enum.uniq(state.started)) == 3 and Enum.all?(state.started, &is_pid/1) and
          map_size(state.monitors) == 3 and map_size(d.downs) == 3 and
          map_size(state.exits) == 3 and MapSet.size(state.down) == 3 and
          Enum.all?(state.started, fn pid ->
            case d.downs[pid] do
              {ref, at} when is_reference(ref) and is_integer(at) ->
                state.monitors[ref] == pid and MapSet.member?(state.down, pid) and
                  at < state.closed and
                  is_integer(state.exits[pid]) and state.exits[pid] < state.closed

              _ ->
                false
            end
          end) and
          d.pending <= d.active and d.active <= d.last_receive and d.last_receive <= d.finish and
          d.read < d.operation and d.operation <= d.blocked and d.active <= d.blocked and
          d.blocked < d.release and d.baseline? == true and d.repos? == true and
          d.unheld? == true and d.prior_control? == true and d.receives in 2..16 and
          state.gate == true and is_integer(state.child) and state.child > 0 and
          state.absent? == true and
          state.await_call < await_at and await_at < state.sql_zero and
          state.sql_zero < state.closed and
          d.release < await_at and state.queued == stages and
          Enum.count(stages, &(&1 == {:started, command, reader, writer})) == 1 and
          Enum.any?(state.stages, fn
            {at, {:started, ^command, ^reader, ^writer}} -> is_integer(at) and at <= d.pending
            _ -> false
          end) and
          Enum.count(stages, &(&1 == {:await_started, command})) == 1 and
          Enum.count(stages, &(&1 == {:await_complete, helper_status})) == 1 and
          :workers_down in stages and :child_connections_absent in stages and
          {:cleanup, :closed} in stages

      if state.scenario == :deadline_control do
        common? and d.primary == nil and transport_deadline_ms(d.release) < d.original and
          d.release <= d.finish and d.finish <= state.await_call and
          transport_valid?(%{state | scenario: :clean_frame})
      else
        common? and state.scenario == :deadline_expired and d.primary == :legacy_deadline and
          transport_deadline_ms(d.finish) >= d.original and d.blocked < d.finish and
          d.finish <= state.await_call and state.await_call <= d.release and
          Enum.all?(state.started, fn pid ->
            {_, at} = d.downs[pid]
            d.finish <= at and d.finish <= state.exits[pid]
          end) and
          not Map.has_key?(state.checkpoints, :ready) and
          is_integer(state.checkpoints[:before_database_drop]) and
          state.closed < state.checkpoints[:before_database_drop]
      end
    else
      _ -> false
    end
  end

  defp transport_deadline_valid?(_), do: false

  defp transport_deadline_final_valid?(state, facts) do
    facts == %{
      trace?: true,
      actor?: true,
      workspace?: true,
      privacy?: true,
      registered?: true,
      cleanup: %{actor: :confirmed, owner: :normal}
    } and
      transport_deadline_valid?(state)
  end

  # Literal signed witness: floor(-9_999_999ns) == -10ms, exactly the original expiry.
  defp transport_deadline_pure_witness do
    owner = self()
    caller = Process.whereis(:logger)
    command = Process.whereis(:init)
    reader = Process.whereis(:code_server)
    writer = Process.whereis(:application_controller)
    run = make_ref()
    refs = Enum.map(1..3, fn _ -> make_ref() end)
    workers = [command, reader, writer]
    monitors = Map.new(Enum.zip(refs, workers))

    stages = [
      {-21_000_000, {:started, command, reader, writer}},
      {-9_600_000, {:await_started, command}},
      {-7_000_000, {:await_complete, :nonzero}},
      {-6_000_000, :workers_down},
      {-5_000_000, :child_connections_absent},
      {-4_000_000, {:cleanup, :closed}}
    ]

    state = %{
      key: make_ref(),
      owner: owner,
      actor: caller,
      run: run,
      scenario: :deadline_expired,
      started: workers,
      monitors: monitors,
      down: MapSet.new(workers),
      exits: Map.new(workers, &{&1, -8_000_000}),
      stages: stages,
      queued: Enum.map(stages, &elem(&1, 1)),
      await_call: -9_500_000,
      await_return: {-7_000_000, :nonzero},
      sql_zero: -5_000_000,
      closed: -4_000_000,
      gate: true,
      child: 1,
      absent?: true,
      valid?: true,
      checkpoints: %{before_database_drop: -3_000_000},
      deadline_loss: %{
        owner: owner,
        caller: caller,
        run: run,
        original: -10,
        pending: -20_000_000,
        active: -19_000_000,
        last_receive: -19_000_000,
        receives: 2,
        read: -18_000_000,
        operation: -17_000_000,
        blocked: -16_000_000,
        baseline?: true,
        repos?: true,
        unheld?: true,
        prior_control?: true,
        finish: -9_999_999,
        primary: :legacy_deadline,
        release: -9_000_000,
        downs: Map.new(Enum.zip(workers, refs), fn {pid, ref} -> {pid, {ref, -8_000_000}} end)
      }
    }

    {state,
     %{
       trace?: true,
       actor?: true,
       workspace?: true,
       privacy?: true,
       registered?: true,
       cleanup: %{actor: :confirmed, owner: :normal}
     }}
  end

  # TASK18_DEADLINE_OBSERVER_END

  defp transport_full_initial do
    %{
      valid?: true,
      body: nil,
      probe_call: nil,
      probe_return: nil,
      decode_call: nil,
      decode_return: nil
    }
  end

  defp transport_full_fact(state, reader, fact, at) do
    full = state.full
    reader? = state.started != nil and reader == Enum.at(state.started, 1)
    full = %{full | valid?: full.valid? and reader?}

    full =
      case fact do
        {:body, bounded?, expected?} ->
          %{full | body: at, valid?: full.valid? and bounded? and expected? and is_nil(full.body)}

        :probe_call when is_nil(full.body) ->
          # A fragmented header/body may request its final byte before completion.
          full

        {:probe_return, _} when is_nil(full.body) ->
          full

        :probe_call ->
          %{full | probe_call: at, valid?: full.valid? and is_nil(full.probe_call)}

        {:probe_return, status} ->
          %{full | probe_return: {at, status}, valid?: full.valid? and is_nil(full.probe_return)}

        {:decode_call, expected?} ->
          %{
            full
            | decode_call: at,
              valid?: full.valid? and expected? and is_nil(full.decode_call)
          }

        {:decode_return, typed?} ->
          %{
            full
            | decode_return: {at, typed?},
              valid?: full.valid? and is_nil(full.decode_return)
          }
      end

    %{state | full: full}
  end

  defp transport_full_valid?(%{scenario: scenario} = state)
       when scenario in [:full_frame_eof, :full_frame_overrun] do
    full = state.full

    stdin_closed =
      Enum.find_value(state.stages, fn
        {at, {:stdin_closed, writer}} ->
          if writer == List.last(state.started), do: at

        _ ->
          nil
      end)

    prefix? =
      full.valid? and is_integer(full.body) and is_integer(stdin_closed) and
        is_integer(full.probe_call) and full.body < stdin_closed and
        stdin_closed < full.probe_call

    case {scenario, full.probe_return, full.decode_return} do
      {:full_frame_eof, {probe_at, :eof}, {decoded_at, true}} ->
        eof =
          Enum.find_value(state.stages, fn
            {at, {:reader_eof, reader}} ->
              if reader == Enum.at(state.started, 1), do: at

            _ ->
              nil
          end)

        prefix? and is_integer(full.decode_call) and
          full.probe_call < probe_at and probe_at < full.decode_call and
          full.decode_call < decoded_at and is_integer(eof) and
          decoded_at < eof and eof < state.await_call

      {:full_frame_overrun, {probe_at, :byte}, nil} ->
        rejected =
          Enum.find_value(state.stages, fn
            {at, {:reader_rejected, :legacy_output_limit}} -> at
            _ -> nil
          end)

        prefix? and full.probe_call < probe_at and is_nil(full.decode_call) and
          is_integer(rejected) and probe_at < rejected and rejected < state.await_call

      _ ->
        false
    end
  end

  defp transport_full_valid?(_state), do: false

  # Pure contract data only; this does not prove any actual child lifecycle.
  defp transport_full_pure_state(scenario) do
    owner = self()
    reader = Process.whereis(:init)
    writer = Process.whereis(:code_server)
    workers = [owner, reader, writer]
    positive? = scenario == :full_frame_eof

    terminal =
      if positive?, do: {:reader_eof, reader}, else: {:reader_rejected, :legacy_output_limit}

    stages = [
      {1, {:started, owner, reader, writer}},
      {4, {:stdin_closed, writer}},
      {9, terminal},
      {10, {:await_started, owner}},
      {13, {:await_complete, if(positive?, do: :zero, else: :nonzero)}},
      {14, :workers_down},
      {15, :child_connections_absent},
      {16, {:cleanup, :closed}}
    ]

    %{
      scenario: scenario,
      owner: owner,
      started: workers,
      stages: stages,
      full: %{
        valid?: true,
        body: 2,
        probe_call: 5,
        probe_return: {6, if(positive?, do: :eof, else: :byte)},
        decode_call: if(positive?, do: 7, else: nil),
        decode_return: if(positive?, do: {8, true}, else: nil)
      },
      await_call: 10,
      await_return: {13, if(positive?, do: :zero, else: :nonzero)},
      sql_zero: 15,
      closed: 16,
      valid?: true,
      gate: true,
      child: 1,
      absent?: true,
      down: MapSet.new(workers),
      exits: Map.new(workers, &{&1, 14}),
      queued: Enum.map(stages, &elem(&1, 1)),
      checkpoints: if(positive?, do: %{ready: 17}, else: %{before_database_drop: 17})
    }
  end

  defp transport_stage?({:started, command, reader, writer}),
    do: is_pid(command) and is_pid(reader) and is_pid(writer)

  defp transport_stage?({:reader_rejected, :legacy_protocol}), do: true
  defp transport_stage?({:reader_rejected, :legacy_output_limit}), do: true
  defp transport_stage?({:stdin_closed, writer}), do: is_pid(writer)
  defp transport_stage?({:reader_eof, reader}), do: is_pid(reader)
  defp transport_stage?({:await_started, pid}), do: is_pid(pid)
  defp transport_stage?({:await_complete, status}), do: status in [:zero, :nonzero, :unconfirmed]
  defp transport_stage?({:cleanup, status}), do: status in [:closed, :unconfirmed]
  defp transport_stage?(stage), do: stage in [:workers_down, :child_connections_absent]

  defp transport_reader_patterns!(session, owner, command, scenario)
       when scenario in [:full_frame_eof, :full_frame_overrun],
       do: transport_full_patterns!(session, owner, command)

  defp transport_reader_patterns!(session, owner, command, scenario)
       when scenario in [:ascii_stderr_flood, :declared_oversize],
       do: transport_header_patterns!(session, owner, command, scenario)

  defp transport_reader_patterns!(session, owner, command, scenario) do
    payload =
      case scenario do
        :malformed_payload ->
          "{" <>
            @transport_canary <>
            binary_part(@transport_expected_json, 1, byte_size(@transport_expected_json) - 1)

        :short_frame_trailer ->
          @transport_expected_json
      end

    expected = frame(payload)

    transport_require!(
      :trace.function(
        session,
        {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1},
        [
          {[:"$1"], [],
           [
             {:message, {{:legacy_frame_fact, {:==, :"$1", {:const, expected}}}}},
             {:return_trace}
           ]}
        ],
        [:local]
      ) == 1
    )

    handle = %{
      __struct__: ExCmd.Process,
      pid: command,
      owner: owner,
      monitor_ref: :"$1",
      exit_ref: :"$2"
    }

    transport_require!(
      :trace.function(
        session,
        {ExCmd.Process, :read, 2},
        [
          {[handle, 1], [{:is_reference, :"$1"}, {:is_reference, :"$2"}],
           [{:message, {{:legacy_one_byte_probe, true}}}, {:return_trace}]}
        ],
        []
      ) == 1
    )
  end

  defp transport_full_patterns!(session, owner, command) do
    body =
      @transport_expected_json <>
        String.duplicate(" ", 65_536 - byte_size(@transport_expected_json))

    expected = frame(body)

    handle = %{
      __struct__: ExCmd.Process,
      pid: command,
      owner: owner,
      monitor_ref: :"$1",
      exit_ref: :"$2"
    }

    references = [{:is_reference, :"$1"}, {:is_reference, :"$2"}]

    transport_require!(
      :trace.function(
        session,
        {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3},
        [
          {[handle, 0, :"$3"],
           references ++ [{:is_binary, :"$3"}, {:==, {:byte_size, :"$3"}, 65_536}],
           [{:message, {{:legacy_full_body, true, {:==, :"$3", {:const, body}}}}}]}
        ],
        [:local]
      ) == 1
    )

    transport_require!(
      :trace.function(
        session,
        {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1},
        [
          {[:"$1"], [],
           [
             {:message, {{:legacy_full_frame, {:==, :"$1", {:const, expected}}}}},
             {:return_trace}
           ]}
        ],
        [:local]
      ) == 1
    )

    transport_require!(
      :trace.function(
        session,
        {ExCmd.Process, :read, 2},
        [
          {[handle, 1], references, [{:message, {{:legacy_full_probe, true}}}, {:return_trace}]}
        ],
        []
      ) == 1
    )
  end

  # TASK18_HEADER_LIMIT_PATTERNS_BEGIN
  defp transport_expected_category(scenario)
       when scenario in [:ascii_stderr_flood, :declared_oversize, :full_frame_overrun],
       do: :legacy_output_limit

  defp transport_expected_category(:clean_frame_exit17), do: :legacy_exit

  defp transport_expected_category(_scenario), do: :legacy_protocol

  defp transport_header_patterns!(session, owner, command, scenario) do
    expected =
      case scenario do
        :ascii_stderr_flood -> <<84, 65, 83, 75>>
        :declared_oversize -> <<0, 1, 0, 1>>
      end

    handle = %{
      __struct__: ExCmd.Process,
      pid: command,
      owner: owner,
      monitor_ref: :"$1",
      exit_ref: :"$2"
    }

    references = [{:is_reference, :"$1"}, {:is_reference, :"$2"}]

    headers =
      for {remaining, phase} <- [
            {4, :start},
            {3, :three_left},
            {2, :two_left},
            {1, :one_left},
            {0, :complete}
          ] do
        expected? = if remaining == 0, do: {:==, :"$3", {:const, expected}}, else: true

        {[handle, remaining, :"$3"], references ++ [{:is_binary, :"$3"}],
         [
           {:message,
            {{:legacy_header_fact, phase, {:==, {:byte_size, :"$3"}, 4 - remaining}, expected?}}}
         ]}
      end

    # One body-start fact, not return buffers or every body-chunk recursion.
    forbidden =
      {[handle, :"$3", <<>>], references ++ [{:is_integer, :"$3"}, {:>, :"$3", 4}],
       [{:message, {{:legacy_forbidden_body_or_decode, true}}}]}

    transport_require!(
      :trace.function(
        session,
        {LegacyUpgradeRuntimeFixture, :transport_read_exact, 3},
        headers ++ [forbidden],
        [:local]
      ) == 1
    )

    transport_require!(
      :trace.function(
        session,
        {LegacyUpgradeRuntimeFixture, :decode_receipt!, 1},
        [{[:_], [], [{:message, {{:legacy_forbidden_body_or_decode, true}}}]}],
        [:local]
      ) == 1
    )

    requests =
      for {size, request} <- [{4, :four}, {3, :three}, {2, :two}, {1, :one}] do
        {[handle, size], references, [{:message, {{:legacy_header_request, request}}}]}
      end

    transport_require!(:trace.function(session, {ExCmd.Process, :read, 2}, requests, []) == 1)
  end

  # TASK18_HEADER_LIMIT_PATTERNS_END

  defp transport_event_patterns(actor, owner) do
    stages = [
      {{:started, :"$2", :"$3", :"$4"}, [{:is_pid, :"$2"}, {:is_pid, :"$3"}, {:is_pid, :"$4"}]},
      {{:reader_rejected, :legacy_protocol}, []},
      {{:reader_rejected, :legacy_output_limit}, []},
      {{:stdin_closed, :"$2"}, [{:is_pid, :"$2"}]},
      {{:reader_eof, :"$2"}, [{:is_pid, :"$2"}]},
      {{:await_started, :"$2"}, [{:is_pid, :"$2"}]},
      {{:await_complete, :zero}, []},
      {{:await_complete, :nonzero}, []},
      {{:await_complete, :unconfirmed}, []},
      {{:cleanup, :closed}, []},
      {{:cleanup, :unconfirmed}, []},
      {:workers_down, []},
      {:child_connections_absent, []}
    ]

    Enum.map(stages, fn {stage, guards} ->
      {[actor, {:legacy_upgrade_transport, :"$1", owner, stage}],
       [{:is_reference, :"$1"} | guards], []}
    end)
  end

  defp transport_queued(owner, stages, safe?) do
    receive do
      {:legacy_upgrade_transport, run, from, stage} ->
        valid? =
          is_reference(run) and is_pid(from) and (is_nil(owner) or from == owner) and
            transport_stage?(stage) and length(stages) < 32

        transport_queued(owner, if(valid?, do: stages ++ [stage], else: stages), safe? and valid?)

      _ ->
        transport_queued(owner, stages, false)
    after
      0 -> {stages, safe?}
    end
  end

  defp transport_actor_down(key, actor, monitor, state) do
    deadline = System.monotonic_time(:millisecond) + 5_000

    closed? =
      case state.actor_closed do
        nil ->
          receive do
            {^key, :actor_closed, closed?} when is_boolean(closed?) -> closed?
          after
            max(0, deadline - System.monotonic_time(:millisecond)) -> false
          end

        closed? ->
          closed?
      end

    before_drop =
      case state.checkpoints[:before_database_drop] do
        nil ->
          owner = state.owner

          receive do
            {^key, :checkpoint, :before_database_drop, ^owner, at} when is_integer(at) -> at
          after
            max(0, deadline - System.monotonic_time(:millisecond)) -> nil
          end

        at ->
          at
      end

    if Map.has_key?(state, :workspace),
      do: Process.put({key, :workspace_before_drop}, before_drop)

    dropped? =
      is_integer(state.closed) and is_integer(before_drop) and state.closed < before_drop

    down? =
      case state.actor_down do
        nil ->
          receive do
            {:DOWN, ^monitor, :process, ^actor, :normal} ->
              transport_cleanup_record(key, :actor, monitor, actor, :normal)
              true

            {:DOWN, ^monitor, :process, ^actor, reason} ->
              transport_cleanup_record(key, :actor, monitor, actor, reason)
              false
          after
            5_000 -> false
          end

        down? ->
          down?
      end

    closed? and down? and dropped?
  end

  # TASK18_BACKEND_ATTRIBUTION_IMPLEMENTATION_BEGIN
  # Diagnostic rendering never authorizes inventory or changes the original query result.
  defp transport_backend_attribution_sample(_result, %{sequence: sequence})
       when not is_integer(sequence) or sequence < 1 or sequence > 32,
       do: {:error, :record_limit}

  defp transport_backend_attribution_sample(result, context) do
    rows =
      case result do
        {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) ->
          transport_attribution_bound(rows, 64)

        _ ->
          :unavailable
      end

    result_kind =
      case result do
        {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) -> "rows"
        {:error, _} -> "query_error"
        _ -> "malformed_result"
      end

    baseline = transport_attribution_bound(context.baseline, 64)
    before_sample = transport_attribution_bound(context.before, 64)
    after_sample = transport_attribution_bound(context.after, 64)

    overflow? =
      Enum.any?([rows, baseline, before_sample, after_sample], &(&1 == :overflow))

    baseline =
      if is_list(baseline) and
           Enum.all?(baseline, fn
             {pid, username} -> transport_attribution_pid?(pid) and is_binary(username)
             _ -> false
           end) and length(Enum.uniq_by(baseline, &elem(&1, 0))) == length(baseline),
         do: baseline,
         else: :unavailable

    record = %{
      "version" => 1,
      "sequence" => context.sequence,
      "stage" => Atom.to_string(context.stage),
      "scenario" => Atom.to_string(context.scenario),
      "columns" => context.columns,
      "result" => result_kind,
      "row_count" =>
        case rows do
          :overflow -> "overflow"
          :unavailable -> "unavailable"
          rows -> length(rows)
        end,
      "database_oid" => transport_attribution_oid(context.database_oid),
      "child_pid" => transport_attribution_pid(context.child_pid),
      "baseline_pids" =>
        if(is_list(baseline), do: Enum.map(baseline, &elem(&1, 0)), else: "unavailable"),
      "authority" => Atom.to_string(context.authority),
      "capture" =>
        cond do
          overflow? or context.capture == :overflow -> "overflow"
          context.capture == :failed -> "failed"
          true -> "complete"
        end,
      "clock" => transport_attribution_clock(context),
      "candidates" => []
    }

    if record["capture"] == "complete" and is_list(rows) do
      candidates =
        rows
        |> Enum.with_index()
        |> Enum.flat_map(fn {row, index} ->
          transport_attribution_row(row, index, record, baseline)
        end)

      # A malformed current row must not also fabricate a missing member.
      candidates =
        if not is_list(baseline) do
          candidates
        else
          present =
            Enum.flat_map(rows, fn row ->
              case {record["columns"], row} do
                {2, [pid, username]} when is_integer(pid) and pid > 0 and is_binary(username) ->
                  [{pid, username}]

                {3, [pid, username, _]}
                when is_integer(pid) and pid > 0 and is_binary(username) ->
                  [{pid, username}]

                _ ->
                  []
              end
            end)

          malformed_pids =
            for candidate <- candidates,
                candidate["kind"] == "invalid_row",
                transport_attribution_pid?(candidate["pid"]),
                do: candidate["pid"]

          expected =
            if record["stage"] == "gate" and transport_attribution_pid?(record["child_pid"]),
              do: Enum.uniq(baseline ++ [{record["child_pid"], "singularity_migration"}]),
              else: baseline

          candidates ++
            for {pid, _} = tuple <- expected, tuple not in present, pid not in malformed_pids do
              transport_attribution_candidate(
                "missing",
                "unavailable",
                pid,
                "missing",
                "unavailable",
                "unavailable",
                record
              )
            end
        end

      if length(candidates) > 8 do
        %{record | "capture" => "overflow"}
      else
        candidates =
          Enum.map(candidates, fn candidate ->
            candidate =
              candidate
              |> Map.put(
                "before",
                transport_attribution_metadata(before_sample, candidate["pid"])
              )
              |> Map.put("after", transport_attribution_metadata(after_sample, candidate["pid"]))

            if transport_attribution_corroborated?(record, candidate),
              do: %{candidate | "attribution" => "same_incarnation_bracket_corroborated"},
              else: candidate
          end)

        %{record | "candidates" => candidates}
      end
    else
      record
    end
  end

  defp transport_attribution_bound(value, maximum) when is_list(value) do
    bounded = Enum.take(value, maximum + 1)
    if length(bounded) > maximum, do: :overflow, else: bounded
  end

  defp transport_attribution_bound(:overflow, _), do: :overflow
  defp transport_attribution_bound(_, _), do: :unavailable

  defp transport_attribution_pid?(value),
    do: is_integer(value) and value > 0 and value <= 2_147_483_647

  defp transport_attribution_oid?(value),
    do: is_integer(value) and value > 0 and value <= 4_294_967_295

  defp transport_attribution_pid(value),
    do: if(transport_attribution_pid?(value), do: value, else: "unavailable")

  defp transport_attribution_oid(value),
    do: if(transport_attribution_oid?(value), do: value, else: "unavailable")

  defp transport_attribution_integer?(value),
    do:
      is_integer(value) and value >= -9_223_372_036_854_775_808 and
        value <= 9_223_372_036_854_775_807

  defp transport_attribution_decimal?(value, positive?) when is_binary(value) do
    byte_size(value) in 1..20 and
      case Integer.parse(value) do
        {integer, ""} ->
          transport_attribution_integer?(integer) and Integer.to_string(integer) == value and
            (not positive? or integer > 0)

        _ ->
          false
      end
  end

  defp transport_attribution_decimal?(_, _), do: false

  defp transport_attribution_clock(context) do
    times = [context.before_ns, context.query_before_ns, context.query_after_ns, context.after_ns]

    if Enum.all?(times, &transport_attribution_integer?/1) and times == Enum.sort(times) do
      Enum.zip(["before_ns", "query_before_ns", "query_after_ns", "after_ns"], times)
      |> Map.new(fn {key, value} -> {key, Integer.to_string(value)} end)
    else
      "unavailable"
    end
  end

  defp transport_attribution_backend("client backend"), do: "client"
  defp transport_attribution_backend("autovacuum worker"), do: "autovacuum_worker"
  defp transport_attribution_backend("parallel worker"), do: "parallel_worker"
  defp transport_attribution_backend(nil), do: "null"
  defp transport_attribution_backend(_), do: "other"

  defp transport_attribution_row(row, index, record, baseline) do
    {pid, username, backend, shape} =
      case {record["columns"], row} do
        {2, [pid, username]} -> {pid, username, :unavailable, "two"}
        {3, [pid, username, backend]} -> {pid, username, backend, "three"}
        _ -> {:unavailable, :unavailable, :unavailable, "other"}
      end

    username_kind =
      cond do
        shape == "other" -> "unavailable"
        is_nil(username) -> "null"
        username == "singularity_migration" -> "migration"
        is_list(baseline) and {pid, username} in baseline -> "baseline"
        true -> "other"
      end

    backend_kind =
      if record["columns"] == 2 or shape == "other",
        do: "unavailable",
        else: transport_attribution_backend(backend)

    kind =
      cond do
        shape == "other" or not transport_attribution_pid?(pid) or not is_binary(username) ->
          "invalid_row"

        is_list(baseline) and {pid, username} not in baseline and
            not (record["stage"] == "gate" and pid == record["child_pid"] and
                     username == "singularity_migration") ->
          "extra"

        true ->
          nil
      end

    if kind do
      [
        transport_attribution_candidate(
          kind,
          index,
          transport_attribution_pid(pid),
          shape,
          username_kind,
          backend_kind,
          record
        )
      ]
    else
      []
    end
  end

  defp transport_attribution_candidate(kind, index, pid, shape, username, backend, record) do
    %{
      "kind" => kind,
      "row_index" => index,
      "pid" => pid,
      "shape" => shape,
      "username" => username,
      "backend" => backend,
      "child_relation" => transport_attribution_child_relation(pid, record["child_pid"]),
      "baseline_relation" =>
        transport_attribution_baseline_relation(pid, record["baseline_pids"]),
      "before" => "unavailable",
      "after" => "unavailable",
      "attribution" => "unresolved"
    }
  end

  defp transport_attribution_child_relation(pid, child) do
    cond do
      not transport_attribution_pid?(pid) or not transport_attribution_pid?(child) ->
        "unavailable"

      pid == child ->
        "same"

      true ->
        "different"
    end
  end

  defp transport_attribution_baseline_relation(pid, baseline) do
    cond do
      not transport_attribution_pid?(pid) or not is_list(baseline) -> "unavailable"
      pid in baseline -> "present"
      true -> "absent"
    end
  end

  defp transport_attribution_metadata(rows, pid) when is_list(rows) and is_integer(pid) do
    case Enum.filter(rows, &(is_map(&1) and Map.get(&1, :pid) == pid)) do
      [
        %{
          pid: pid,
          datid: datid,
          usesysid: usesysid,
          backend_type: backend,
          backend_start_us: started
        }
      ] ->
        if transport_attribution_pid?(pid) and transport_attribution_oid?(datid) and
             (is_nil(usesysid) or transport_attribution_oid?(usesysid)) and
             transport_attribution_integer?(started) and started > 0 do
          %{
            "pid" => pid,
            "datid" => datid,
            "usesysid" => transport_attribution_oid(usesysid),
            "backend" =>
              case transport_attribution_backend(backend) do
                "null" -> "other"
                kind -> kind
              end,
            "backend_start_us" => Integer.to_string(started)
          }
        else
          "unavailable"
        end

      _ ->
        "unavailable"
    end
  end

  defp transport_attribution_metadata(_, _), do: "unavailable"

  defp transport_attribution_corroborated?(record, candidate) do
    before_sample = candidate["before"]

    record["capture"] == "complete" and record["authority"] == "verified" and
      transport_attribution_clock_valid?(record["clock"]) and record["clock"] != "unavailable" and
      transport_attribution_pid?(candidate["pid"]) and
      transport_attribution_oid?(record["database_oid"]) and is_map(before_sample) and
      transport_attribution_metadata_valid?(before_sample) and
      before_sample === candidate["after"] and before_sample["pid"] == candidate["pid"] and
      before_sample["datid"] == record["database_oid"] and
      before_sample["backend"] in ["client", "autovacuum_worker", "parallel_worker"]
  end

  defp transport_backend_attribution_valid?(record) do
    transport_attribution_record_valid?(record)
  rescue
    _ -> false
  catch
    _, _ -> false
  end

  defp transport_attribution_keys?(map, keys),
    do: is_map(map) and Enum.sort(Map.keys(map)) == Enum.sort(keys)

  defp transport_attribution_clock_valid?("unavailable"), do: true

  defp transport_attribution_clock_valid?(clock) do
    keys = ["before_ns", "query_before_ns", "query_after_ns", "after_ns"]

    if transport_attribution_keys?(clock, keys) and
         Enum.all?(keys, &transport_attribution_decimal?(clock[&1], false)) do
      times = Enum.map(keys, &String.to_integer(clock[&1]))
      times == Enum.sort(times)
    else
      false
    end
  end

  defp transport_attribution_metadata_valid?("unavailable"), do: true

  defp transport_attribution_metadata_valid?(metadata) do
    transport_attribution_keys?(metadata, [
      "pid",
      "datid",
      "usesysid",
      "backend",
      "backend_start_us"
    ]) and
      transport_attribution_pid?(metadata["pid"]) and
      transport_attribution_oid?(metadata["datid"]) and
      (metadata["usesysid"] == "unavailable" or transport_attribution_oid?(metadata["usesysid"])) and
      metadata["backend"] in ["client", "autovacuum_worker", "parallel_worker", "other"] and
      transport_attribution_decimal?(metadata["backend_start_us"], true)
  end

  defp transport_attribution_record_valid?(record) do
    keys = ~w(version sequence stage scenario columns result row_count database_oid child_pid
              baseline_pids authority capture clock candidates)

    transport_attribution_keys?(record, keys) and record["version"] === 1 and
      is_integer(record["sequence"]) and record["sequence"] in 1..32 and
      record["stage"] in ["baseline", "backend_sample", "gate", "absence"] and
      record["scenario"] in ~w(clean_frame stderr_prefix malformed_payload short_frame_trailer
        ascii_stderr_flood declared_oversize full_frame_eof full_frame_overrun blocked_reader_control
        reader_down writer_wait_control writer_down deadline_control deadline_expired workspace_present) and
      ((record["stage"] in ["baseline", "backend_sample"] and record["columns"] === 2) or
         (record["stage"] in ["gate", "absence"] and record["columns"] === 3)) and
      record["result"] in ["rows", "query_error", "malformed_result"] and
      (record["database_oid"] == "unavailable" or
         transport_attribution_oid?(record["database_oid"])) and
      (record["child_pid"] == "unavailable" or transport_attribution_pid?(record["child_pid"])) and
      transport_attribution_baseline_valid?(record["baseline_pids"]) and
      record["authority"] in ["verified", "unavailable", "failed"] and
      record["capture"] in ["complete", "overflow", "failed"] and
      transport_attribution_clock_valid?(record["clock"]) and
      transport_attribution_result_valid?(record) and
      is_list(record["candidates"]) and length(record["candidates"]) <= 8 and
      length(Enum.uniq(record["candidates"])) == length(record["candidates"]) and
      Enum.all?(record["candidates"], &transport_attribution_candidate_valid?(&1, record)) and
      byte_size(Jason.encode!(record)) <= 32_768
  end

  defp transport_attribution_baseline_valid?("unavailable"), do: true

  defp transport_attribution_baseline_valid?(pids),
    do:
      is_list(pids) and length(pids) <= 64 and Enum.all?(pids, &transport_attribution_pid?/1) and
        length(Enum.uniq(pids)) == length(pids)

  defp transport_attribution_result_valid?(record) do
    row_count? =
      case record["result"] do
        "rows" ->
          (is_integer(record["row_count"]) and record["row_count"] in 0..64) or
            (record["row_count"] == "overflow" and record["capture"] == "overflow")

        _ ->
          record["row_count"] == "unavailable" and record["candidates"] == []
      end

    row_count? and
      (record["capture"] == "complete" or record["candidates"] == [])
  end

  defp transport_attribution_candidate_valid?(candidate, record) do
    keys = ~w(kind row_index pid shape username backend child_relation baseline_relation
              before after attribution)

    transport_attribution_keys?(candidate, keys) and
      (candidate["pid"] == "unavailable" or transport_attribution_pid?(candidate["pid"])) and
      candidate["username"] in ["migration", "baseline", "null", "other", "unavailable"] and
      candidate["backend"] in [
        "client",
        "autovacuum_worker",
        "parallel_worker",
        "null",
        "other",
        "unavailable"
      ] and
      candidate["child_relation"] ==
        transport_attribution_child_relation(candidate["pid"], record["child_pid"]) and
      candidate["baseline_relation"] ==
        transport_attribution_baseline_relation(candidate["pid"], record["baseline_pids"]) and
      transport_attribution_shape_valid?(candidate, record) and
      transport_attribution_metadata_valid?(candidate["before"]) and
      transport_attribution_metadata_valid?(candidate["after"]) and
      (candidate["attribution"] == "unresolved" or
         (candidate["attribution"] == "same_incarnation_bracket_corroborated" and
            transport_attribution_corroborated?(record, candidate)))
  end

  defp transport_attribution_shape_valid?(candidate, record) do
    if candidate["kind"] == "missing" do
      candidate["shape"] == "missing" and candidate["row_index"] == "unavailable" and
        transport_attribution_pid?(candidate["pid"]) and candidate["username"] == "unavailable" and
        candidate["backend"] == "unavailable" and
        (candidate["baseline_relation"] == "present" or
           (record["stage"] == "gate" and candidate["child_relation"] == "same"))
    else
      candidate["kind"] in ["invalid_row", "extra"] and
        is_integer(candidate["row_index"]) and is_integer(record["row_count"]) and
        candidate["row_index"] >= 0 and candidate["row_index"] < record["row_count"] and
        ((candidate["shape"] == "other" and candidate["kind"] == "invalid_row" and
            candidate["pid"] == "unavailable" and candidate["username"] == "unavailable" and
            candidate["backend"] == "unavailable") or
           (candidate["shape"] == if(record["columns"] == 2, do: "two", else: "three") and
              candidate["username"] != "unavailable" and
              ((record["columns"] == 2 and candidate["backend"] == "unavailable") or
                 (record["columns"] == 3 and candidate["backend"] != "unavailable")) and
              (candidate["kind"] == "invalid_row" or
                 (transport_attribution_pid?(candidate["pid"]) and
                    candidate["username"] in ["migration", "baseline", "other"] and
                    is_list(record["baseline_pids"])))))
    end
  end

  # The optional sink is fixed and root-prepared. No environment switch or fallback path.
  defp transport_attribution_sink_path do
    Path.expand("../../../../../.devenv/phase5-task18-backend-attribution1", __DIR__)
  end

  defp transport_attribution_safe(fun, fallback) do
    fun.()
  rescue
    _ -> fallback
  catch
    _, _ -> fallback
  end

  defp transport_attribution_identity(stat) do
    {stat.type, stat.major_device, stat.minor_device, stat.inode, stat.uid, stat.mode, stat.links}
  end

  defp transport_attribution_sink do
    path = transport_attribution_sink_path()

    case File.lstat(path) do
      {:error, :enoent} ->
        :disabled

      {:ok, stat} ->
        with {:ok, source} <- File.lstat(__ENV__.file),
             true <- stat.type == :directory and stat.uid == source.uid,
             true <- Bitwise.band(stat.mode, 0o7777) == 0o700,
             {:ok, parent} <- File.lstat(Path.dirname(path)),
             {:ok, root} <- File.lstat(Path.dirname(Path.dirname(path))),
             true <- parent.type == :directory and root.type == :directory,
             true <- parent.uid == source.uid and root.uid == source.uid do
          %{
            path: path,
            uid: source.uid,
            directory: transport_attribution_identity(stat),
            parent: transport_attribution_identity(parent),
            root: transport_attribution_identity(root)
          }
        else
          _ -> :failed
        end

      _ ->
        :failed
    end
  end

  defp transport_attribution_sink_same?(sink) do
    with {:ok, stat} <- File.lstat(sink.path),
         {:ok, parent} <- File.lstat(Path.dirname(sink.path)),
         {:ok, root} <- File.lstat(Path.dirname(Path.dirname(sink.path))) do
      transport_attribution_identity(stat) == sink.directory and
        transport_attribution_identity(parent) == sink.parent and
        transport_attribution_identity(root) == sink.root
    else
      _ -> false
    end
  end

  defp transport_attribution_lifecycle_default do
    %{
      enabled: false,
      close: :unobserved,
      persistence: :unobserved,
      queued: :unavailable,
      written: :unavailable
    }
  end

  defp transport_attribution_lifecycle(key, updates) do
    lifecycle =
      Process.get(
        {key, :backend_attribution_lifecycle},
        transport_attribution_lifecycle_default()
      )

    Process.put({key, :backend_attribution_lifecycle}, Map.merge(lifecycle, updates))
    :ok
  end

  defp transport_attribution_emit(key, scenario) do
    lifecycle =
      Process.get(
        {key, :backend_attribution_lifecycle},
        transport_attribution_lifecycle_default()
      )

    # All keys, scenarios, states and counts are finite ASCII; no raw process,
    # query, exception, role, path or content value crosses this output boundary.
    receipt = %{
      "version" => 1,
      "scenario" => Atom.to_string(scenario),
      "enabled" => lifecycle.enabled == true,
      "close" =>
        if(lifecycle.close in [:confirmed, :failed, :unobserved, :disabled],
          do: Atom.to_string(lifecycle.close),
          else: "unobserved"
        ),
      "persistence" =>
        if(
          lifecycle.persistence in [
            :confirmed,
            :not_required,
            :failed,
            :overflow,
            :unobserved,
            :disabled
          ],
          do: Atom.to_string(lifecycle.persistence),
          else: "unobserved"
        ),
      "queued" => transport_attribution_count(lifecycle.queued),
      "written" => transport_attribution_count(lifecycle.written)
    }

    IO.puts("Task18 backend attribution lifecycle: " <> Jason.encode!(receipt))
  end

  defp transport_attribution_count(value) when is_integer(value) and value in 0..32, do: value
  defp transport_attribution_count(_), do: "unavailable"

  defp transport_attribution_open(key, ordinary, database, scenario) do
    transport_require!(is_reference(key))
    transport_require!(Process.get({key, :backend_attribution}) == nil)
    transport_require!(Process.get({key, :backend_attribution_close}) == nil)
    transport_require!(Process.get({__MODULE__, :backend_attribution_connection}) == nil)
    sink = transport_attribution_safe(&transport_attribution_sink/0, :failed)

    Process.put({key, :backend_attribution_lifecycle}, %{
      enabled: sink != :disabled,
      close: :unobserved,
      persistence:
        case sink do
          :disabled -> :disabled
          :failed -> :failed
          _ -> :unobserved
        end,
      queued: 0,
      written: 0
    })

    state = %{
      key: key,
      observer: self(),
      ordinary: ordinary,
      database: database,
      scenario: scenario,
      sink: sink,
      admin: nil,
      admin_down?: false,
      custodian: nil,
      custodian_down?: false,
      nonce: :erlang.alias(),
      failed?: false,
      authority: :failed,
      database_oid: :unavailable,
      pending: []
    }

    Process.put({key, :backend_attribution}, state)
    Process.put({__MODULE__, :backend_attribution_connection}, {ordinary, key})

    connected =
      transport_attribution_safe(
        fn -> transport_attribution_connect(key, ordinary, database) end,
        :failed
      )

    transport_require!(connected == :ok)
  end

  defp transport_attribution_connect(key, ordinary, database) do
    config = Singularity.Storage.MigrationRepo.config()
    host = System.get_env("PGHOST")
    user = System.get_env("PGUSER")
    port = System.get_env("PGPORT")
    selected_database = System.get_env("PGDATABASE")

    with true <- is_binary(host) and String.starts_with?(host, "/"),
         true <- is_binary(user) and byte_size(user) > 0,
         true <- is_binary(port),
         {port, ""} <- Integer.parse(port),
         true <- port in 1..65_535 and port == config[:port] and host == config[:socket_dir],
         true <- selected_database == "postgres",
         {:ok, admin} <-
           transport_attribution_start(key,
             socket_dir: host,
             port: port,
             username: user,
             database: selected_database,
             pool_size: 1,
             backoff_type: :stop,
             connect_timeout: 1_000,
             timeout: 1_000,
             parameters: [default_transaction_read_only: "on"]
           ) do
      with {:ok, %Postgrex.Result{rows: [[started, oid, true]]}} <-
             Postgrex.query(
               ordinary,
               "SELECT (extract(epoch FROM pg_postmaster_start_time())*1000000)::bigint,(SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=current_database()),current_database()=$1",
               [database],
               timeout: 1_000
             ),
           true <- transport_attribution_integer?(started) and started > 0,
           true <- transport_attribution_oid?(oid),
           {:ok, %Postgrex.Result{rows: [[true, true, true, true, ^started, ^oid]]}} <-
             Postgrex.query(
               admin,
               "SELECT current_user=$1,(SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname=current_user),current_database()='postgres',current_setting('transaction_read_only')='on',(extract(epoch FROM pg_postmaster_start_time())*1000000)::bigint,(SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$2)",
               [user, database],
               timeout: 1_000
             ) do
        state = Process.get({key, :backend_attribution})

        Process.put({key, :backend_attribution}, %{
          state
          | authority: :verified,
            database_oid: oid
        })

        :ok
      else
        _ -> :failed
      end
    else
      _ -> :failed
    end
  end

  # The observer is never linked to this custodian or its admin pool.
  # New diagnostic waits are bounded; DBConnection pool initialization is not.
  defp transport_attribution_start(key, options) do
    observer = self()
    state = Process.get({key, :backend_attribution})
    nonce = state.nonce

    {custodian, monitor} =
      :erlang.spawn_monitor(fn ->
        transport_attribution_custodian(observer, nonce)
      end)

    Process.put({key, :backend_attribution}, %{state | custodian: {custodian, monitor}})
    send(custodian, {:task18_backend_attribution, nonce, observer, {:start, options}})

    receive do
      {:task18_backend_attribution, ^nonce, ^custodian, {:ready, admin}} when is_pid(admin) ->
        admin_monitor = Process.monitor(admin)
        state = Process.get({key, :backend_attribution})
        Process.put({key, :backend_attribution}, %{state | admin: {admin, admin_monitor}})
        send(custodian, {:task18_backend_attribution, nonce, observer, :adopt})

        receive do
          {:task18_backend_attribution, ^nonce, ^custodian, :adopted} ->
            {:ok, admin}

          {:task18_backend_attribution, ^nonce, ^custodian, _event} ->
            transport_attribution_cancel(key)

          {:DOWN, ^admin_monitor, :process, ^admin, _reason} ->
            transport_attribution_down(key, admin_monitor, admin)
            transport_attribution_cancel(key)

          {:DOWN, ^monitor, :process, ^custodian, _reason} ->
            transport_attribution_down(key, monitor, custodian)
            transport_attribution_cancel(key)
        after
          1_000 -> transport_attribution_cancel(key)
        end

      {:task18_backend_attribution, ^nonce, ^custodian, _event} ->
        transport_attribution_cancel(key)

      {:DOWN, ^monitor, :process, ^custodian, _reason} ->
        transport_attribution_down(key, monitor, custodian)
        transport_attribution_cancel(key)
    after
      1_000 -> transport_attribution_cancel(key)
    end
  end

  defp transport_attribution_cancel(key) do
    state = Process.get({key, :backend_attribution})
    Process.put({key, :backend_attribution}, %{state | failed?: true, authority: :failed})

    case state.custodian do
      {custodian, _} ->
        send(custodian, {:task18_backend_attribution, state.nonce, self(), :cancel})

      nil ->
        :ok
    end

    :failed
  end

  defp transport_attribution_custodian(observer, nonce) do
    Process.flag(:trap_exit, true)
    observer_monitor = Process.monitor(observer)

    receive do
      {:task18_backend_attribution, ^nonce, ^observer, {:start, options}} ->
        # Keep ownership if this call remains blocked: observer timeout is not
        # proof that the as-yet-unknown pool or its supervised connections closed.
        result = transport_attribution_safe(fn -> Postgrex.start_link(options) end, :failed)

        case result do
          {:ok, admin} ->
            monitor = Process.monitor(admin)
            send(nonce, {:task18_backend_attribution, nonce, self(), {:ready, admin}})
            transport_attribution_adopt(observer, observer_monitor, nonce, admin, monitor)

          _ ->
            send(nonce, {:task18_backend_attribution, nonce, self(), :failed})
        end

      {:task18_backend_attribution, ^nonce, ^observer, :cancel} ->
        :ok

      {:DOWN, ^observer_monitor, :process, ^observer, _reason} ->
        :ok
    after
      1_000 -> :ok
    end
  end

  defp transport_attribution_adopt(observer, observer_monitor, nonce, admin, monitor) do
    receive do
      {:task18_backend_attribution, ^nonce, ^observer, :adopt} ->
        send(nonce, {:task18_backend_attribution, nonce, self(), :adopted})
        transport_attribution_owned(observer, observer_monitor, nonce, admin, monitor)

      {:task18_backend_attribution, ^nonce, ^observer, action} when action in [:cancel, :close] ->
        transport_attribution_stop(observer, nonce, admin, monitor, false)

      {:DOWN, ^observer_monitor, :process, ^observer, _reason} ->
        transport_attribution_stop(observer, nonce, admin, monitor, false)

      {:DOWN, ^monitor, :process, ^admin, _reason} ->
        send(nonce, {:task18_backend_attribution, nonce, self(), {:closed, false}})

      {:EXIT, ^admin, _reason} ->
        transport_attribution_stop(observer, nonce, admin, monitor, false)
    after
      1_000 -> transport_attribution_stop(observer, nonce, admin, monitor, false)
    end
  end

  # This is a passive ownership lifetime, not a wait that blocks the observer.
  defp transport_attribution_owned(observer, observer_monitor, nonce, admin, monitor) do
    receive do
      {:task18_backend_attribution, ^nonce, ^observer, :close} ->
        transport_attribution_stop(observer, nonce, admin, monitor, true)

      {:task18_backend_attribution, ^nonce, ^observer, :cancel} ->
        transport_attribution_stop(observer, nonce, admin, monitor, false)

      {:DOWN, ^observer_monitor, :process, ^observer, _reason} ->
        transport_attribution_stop(observer, nonce, admin, monitor, false)

      {:DOWN, ^monitor, :process, ^admin, _reason} ->
        send(nonce, {:task18_backend_attribution, nonce, self(), {:closed, false}})

      {:EXIT, ^admin, _reason} ->
        transport_attribution_stop(observer, nonce, admin, monitor, false)
    end
  end

  defp transport_attribution_stop(_observer, nonce, admin, monitor, clean?) do
    stopped = transport_attribution_safe(fn -> GenServer.stop(admin, :normal, 1_000) end, :failed)

    # A forced known-PID kill is best effort only, never normal closure proof.
    if stopped != :ok and Process.alive?(admin), do: Process.exit(admin, :kill)

    normal_down? =
      receive do
        {:DOWN, ^monitor, :process, ^admin, reason} -> reason == :normal
      after
        1_000 -> false
      end

    closed? = clean? and stopped == :ok and normal_down?
    send(nonce, {:task18_backend_attribution, nonce, self(), {:closed, closed?}})
  end

  defp transport_attribution_late(key, nonce, custodian, event) do
    case Process.get({key, :backend_attribution}) do
      %{nonce: ^nonce, custodian: {^custodian, _}} ->
        known? =
          case event do
            {:ready, admin} when is_pid(admin) -> true
            :adopted -> true
            :failed -> true
            {:closed, closed?} when is_boolean(closed?) -> true
            _ -> false
          end

        if known?, do: transport_attribution_cancel(key)
        known?

      _ ->
        false
    end
  end

  defp transport_attribution_context(state, stage, columns, baseline, child) do
    %{
      sequence: 1,
      stage: stage,
      scenario: state.scenario,
      columns: columns,
      database_oid: state.database_oid,
      child_pid: child,
      baseline: baseline,
      authority: state.authority,
      capture: if(state.authority == :verified, do: :complete, else: :failed),
      before_ns: :unavailable,
      query_before_ns: :unavailable,
      query_after_ns: :unavailable,
      after_ns: :unavailable,
      before: :unavailable,
      after: :unavailable
    }
  end

  defp transport_attribution_metadata_query(
         %{authority: :verified, admin: {admin, _}, database_oid: oid},
         which,
         pids
       ) do
    result =
      case which do
        :before ->
          Postgrex.query(
            admin,
            "SELECT pid,datid::bigint,usesysid::bigint,backend_type,(extract(epoch FROM backend_start)*1000000)::bigint,count(*) OVER() FROM pg_catalog.pg_stat_activity WHERE datid=$1::oid ORDER BY pid LIMIT 64",
            [oid],
            timeout: 1_000
          )

        :after ->
          Postgrex.query(
            admin,
            "SELECT pid,datid::bigint,usesysid::bigint,backend_type,(extract(epoch FROM backend_start)*1000000)::bigint,count(*) OVER() FROM pg_catalog.pg_stat_activity WHERE datid=$1::oid AND pid=ANY($2::integer[]) ORDER BY pid LIMIT 64",
            [oid, pids],
            timeout: 1_000
          )
      end

    case result do
      {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) ->
        bounded = Enum.take(rows, 65)

        cond do
          length(bounded) > 64 ->
            :overflow

          not Enum.all?(bounded, fn
            [_, _, _, _, _, total] -> is_integer(total) and total >= length(bounded)
            _ -> false
          end) ->
            :unavailable

          Enum.any?(bounded, fn [_, _, _, _, _, total] -> total > 64 end) ->
            :overflow

          true ->
            Enum.map(bounded, fn [pid, datid, usesysid, backend, started, _total] ->
              %{
                pid: pid,
                datid: datid,
                usesysid: usesysid,
                backend_type: backend,
                backend_start_us: started
              }
            end)
        end

      _ ->
        :unavailable
    end
  end

  defp transport_attribution_metadata_query(_, _, _), do: :unavailable

  defp transport_inventory_binding(key, ordinary, database, stage, columns, baseline, child) do
    state = Process.get({key, :backend_attribution})
    transport_require!(is_map(state))
    transport_require!(state.key == key and state.observer == self())
    transport_require!(state.ordinary == ordinary and state.database == database)
    transport_require!(state.authority == :verified and not state.failed?)
    transport_require!(not state.admin_down? and not state.custodian_down?)
    transport_require!(Process.get({key, :backend_attribution_close}) == nil)
    transport_require!(
      Process.get({__MODULE__, :backend_attribution_connection}) == {ordinary, key}
    )

    expected = %{
      observer: self(),
      key: key,
      operation: make_ref(),
      nonce: state.nonce,
      ordinary: ordinary,
      admin: state.admin,
      custodian: state.custodian,
      database: database,
      database_oid: state.database_oid,
      stage: stage,
      columns: columns,
      baseline: baseline,
      child_pid: child
    }

    transport_require!(transport_inventory_binding_valid?(expected))
    transport_require!(
      Enum.all?([ordinary, elem(state.admin, 0), elem(state.custodian, 0)], &Process.alive?/1)
    )
    expected
  end

  defp transport_attribution_capture(key, stage, columns, baseline, child, operation, fun) do
    state = Process.get({key, :backend_attribution})
    transport_require!(
      is_map(state) and state.key == key and state.observer == self() and
        state.authority == :verified and not state.failed? and
        not state.admin_down? and not state.custodian_down? and
        Process.get({key, :backend_attribution_close}) == nil
    )

    diagnostic_stage = if stage == :baseline, do: :backend_sample, else: stage
    context =
      state
      |> transport_attribution_context(stage, columns, baseline, child)
      |> Map.merge(%{
        observer: self(),
        key: key,
        operation: operation,
        nonce: state.nonce,
        ordinary: state.ordinary,
        admin: state.admin,
        custodian: state.custodian,
        database: state.database
      })

    before_sample =
      transport_attribution_safe(
        fn -> transport_attribution_metadata_query(state, :before, []) end,
        :unavailable
      )

    context = %{context | before: before_sample, before_ns: System.monotonic_time(:nanosecond)}
    query_before = System.monotonic_time(:nanosecond)

    # Preserve the original callback's class/reason/stack; never execute it twice.
    original =
      try do
        {:returned, fun.()}
      catch
        kind, reason -> {:raised, kind, reason, __STACKTRACE__}
      end

    query_after = System.monotonic_time(:nanosecond)
    result =
      case original do
        {:returned, value} -> value
        {:raised, _, _, _} -> {:error, :query_raised}
      end

    pids =
      case result do
        {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) ->
          rows
          |> Enum.flat_map(fn
            [pid | _] when is_integer(pid) and pid > 0 -> [pid]
            _ -> []
          end)
          |> Enum.uniq()

        _ ->
          []
      end

    # Even an empty raw PID set gets an actual AFTER query.
    after_sample =
      transport_attribution_safe(
        fn -> transport_attribution_metadata_query(state, :after, pids) end,
        :unavailable
      )

    capture =
      cond do
        before_sample == :overflow or after_sample == :overflow -> :overflow
        not is_list(before_sample) or not is_list(after_sample) -> :failed
        length(before_sample) > 64 or length(after_sample) > 64 -> :overflow
        true -> :complete
      end

    context = %{context | query_before_ns: query_before, query_after_ns: query_after,
      after: after_sample, after_ns: System.monotonic_time(:nanosecond), capture: capture}

    # Optional rendering/persistence cannot authorize the direct inventory result.
    if state.sink != :disabled do
      transport_attribution_safe(
        fn ->
          record = transport_backend_attribution_sample(result, %{context | stage: diagnostic_stage})
          transport_attribution_queue(key, record)
        end,
        :failed
      )
    end

    case original do
      {:returned, value} -> {value, context}
      {:raised, kind, reason, stack} -> :erlang.raise(kind, reason, stack)
    end
  end

  defp transport_attribution_queue(key, record) do
    state = Process.get({key, :backend_attribution})

    if state.sink != :disabled and
         (record["candidates"] != [] or record["result"] != "rows" or record["capture"] != "complete") do
      pending =
        case length(state.pending) do
          count when count < 31 -> state.pending ++ [record]
          31 -> state.pending ++ [%{record | "capture" => "overflow", "candidates" => []}]
          _ -> state.pending
        end

      Process.put({key, :backend_attribution}, %{state | pending: pending})
    end

    :ok
  end

  defp transport_attribution_down(key, ref, pid) do
    case Process.get({key, :backend_attribution}) do
      %{admin: {^pid, ^ref}} = state ->
        Process.put(
          {key, :backend_attribution},
          %{state | admin_down?: true, failed?: true, authority: :failed}
        )

        :ok

      %{custodian: {^pid, ^ref}} = state ->
        Process.put(
          {key, :backend_attribution},
          %{state | custodian_down?: true, failed?: true, authority: :failed}
        )

        :ok

      _ ->
        :ok
    end
  end

  defp transport_attribution_close(key) do
    case Process.get({key, :backend_attribution}) do
      nil ->
        :ok

      state ->
        witnesses =
          case state.custodian do
            {custodian, _} ->
              action = if state.failed?, do: :cancel, else: :close
              send(custodian, {:task18_backend_attribution, state.nonce, self(), action})

              transport_attribution_witnesses(
                state,
                %{admin: false, custodian: false, closed: :pending, failed: false},
                System.monotonic_time(:millisecond) + 1_000
              )

            nil ->
              %{admin: false, custodian: false, closed: :pending, failed: true}
          end

        # Revocation isolates future cases, not resource lifetime. The producer
        # sends at most ready + adopted + closed, or fewer on every failure path.
        :erlang.unalias(state.nonce)
        drained? = transport_attribution_drain(state, 3)

        closed? =
          witnesses.admin and witnesses.custodian and witnesses.closed == true and
            not witnesses.failed and not state.failed? and not state.admin_down? and
            not state.custodian_down? and state.authority == :verified and drained?

        Process.put({key, :backend_attribution_close}, if(closed?, do: :confirmed, else: :failed))
        transport_attribution_lifecycle(key, %{close: if(closed?, do: :confirmed, else: :failed)})

        if closed? do
          Process.delete({key, :backend_attribution})
        else
          # In particular, a blocked startup retains its exact pending owner.
          Process.put({key, :backend_attribution}, %{state | failed?: true, authority: :failed})
        end

        pending =
          cond do
            state.sink == :disabled ->
              []
            closed? ->
              state.pending
            true ->
            context =
              transport_attribution_context(state, :backend_sample, 2, :unavailable, :unavailable)

            failed =
              transport_backend_attribution_sample({:error, :close_unconfirmed}, %{
                context
                | capture: :failed
              })

            [failed | Enum.map(state.pending, &%{&1 | "capture" => "failed", "candidates" => []})]
            |> Enum.take(32)
          end

        # Only a nonce-bound normal-close witness plus BOTH exact DOWNs can
        # release complete evidence. Failed/unknown closure grants no credit.
        transport_attribution_lifecycle(
          key,
          %{
            queued: length(pending),
            written: 0,
            persistence:
              case state.sink do
                :disabled -> :disabled
                :failed -> :failed
                _ -> :unobserved
              end
          }
        )

        Enum.each(pending, fn record ->
          persisted =
            transport_attribution_safe(
              fn -> transport_attribution_persist(state.sink, record) end,
              :failed
            )

          lifecycle = Process.get({key, :backend_attribution_lifecycle})

          updates =
            case persisted do
              :ok ->
                %{written: lifecycle.written + 1}

              :overflow ->
                %{persistence: if(lifecycle.persistence == :failed, do: :failed, else: :overflow)}

              _ ->
                %{persistence: :failed}
            end

          transport_attribution_lifecycle(key, updates)
          if persisted == :failed, do: Process.put({key, :backend_attribution_capture}, :failed)
        end)

        lifecycle = Process.get({key, :backend_attribution_lifecycle})

        persistence = transport_attribution_persistence(state.sink, lifecycle)

        transport_attribution_lifecycle(key, %{persistence: persistence})
        :ok
    end
  end

  defp transport_attribution_persistence(:disabled, _lifecycle), do: :disabled
  defp transport_attribution_persistence(:failed, _lifecycle), do: :failed

  defp transport_attribution_persistence(_sink, lifecycle) do
    cond do
      lifecycle.persistence in [:failed, :overflow] -> lifecycle.persistence
      lifecycle.queued == 0 and lifecycle.written == 0 -> :not_required
      lifecycle.queued > 0 and lifecycle.written == lifecycle.queued -> :confirmed
      true -> :failed
    end
  end

  defp transport_attribution_witnesses(state, witnesses, deadline) do
    if witnesses.admin and witnesses.custodian and witnesses.closed != :pending do
      witnesses
    else
      {admin, admin_monitor} = state.admin || {nil, nil}
      {custodian, custodian_monitor} = state.custodian
      nonce = state.nonce
      remaining = max(deadline - System.monotonic_time(:millisecond), 0)

      receive do
        {:task18_backend_attribution, ^nonce, ^custodian, {:closed, normal?}}
        when is_boolean(normal?) ->
          transport_attribution_witnesses(
            state,
            %{witnesses | closed: normal?, failed: witnesses.failed or not normal?},
            deadline
          )

        {:task18_backend_attribution, ^nonce, ^custodian, _event} ->
          transport_attribution_witnesses(state, %{witnesses | failed: true}, deadline)

        {:DOWN, ^admin_monitor, :process, ^admin, reason} ->
          transport_attribution_witnesses(
            state,
            %{witnesses | admin: true, failed: witnesses.failed or reason != :normal},
            deadline
          )

        {:DOWN, ^custodian_monitor, :process, ^custodian, reason} ->
          transport_attribution_witnesses(
            state,
            %{witnesses | custodian: true, failed: witnesses.failed or reason != :normal},
            deadline
          )
      after
        remaining -> witnesses
      end
    end
  end

  defp transport_attribution_drain(%{custodian: nil}, _), do: true

  defp transport_attribution_drain(state, remaining) do
    {custodian, _} = state.custodian
    nonce = state.nonce

    receive do
      {:task18_backend_attribution, ^nonce, ^custodian, _event} ->
        if remaining > 0,
          do: transport_attribution_drain(state, remaining - 1),
          else: false
    after
      0 -> true
    end
  end

  defp transport_attribution_persist(sink, record) when is_map(sink) do
    with true <- transport_attribution_sink_same?(sink),
         {:ok, entries} <- File.ls(sink.path),
         true <- length(entries) <= 32,
         true <-
           Enum.sort(entries) ==
             Enum.sort(
               for n <- Enum.take(1..32, length(entries)), do: transport_attribution_filename(n)
             ),
         true <-
           Enum.all?(entries, fn name ->
             case File.lstat(Path.join(sink.path, name)) do
               {:ok, stat} ->
                 stat.type == :regular and stat.uid == sink.uid and stat.links == 1 and
                   Bitwise.band(stat.mode, 0o7777) == 0o600 and stat.size in 1..32_768

               _ ->
                 false
             end
           end) do
      if length(entries) == 32 do
        :overflow
      else
        sequence = length(entries) + 1
        record = %{record | "sequence" => sequence}

        record =
          if sequence == 32,
            do: %{record | "capture" => "overflow", "candidates" => []},
            else: record

        if transport_backend_attribution_valid?(record) do
          encoded = Jason.encode!(record) <> "\n"

          if byte_size(encoded) <= 32_768 do
            transport_attribution_write(sink, transport_attribution_filename(sequence), encoded)
          else
            :failed
          end
        else
          :failed
        end
      end
    else
      _ -> :failed
    end
  end

  defp transport_attribution_persist(_, _), do: :failed

  defp transport_attribution_filename(sequence),
    do:
      "backend-attribution-" <> String.pad_leading(Integer.to_string(sequence), 2, "0") <> ".json"

  defp transport_attribution_write(sink, name, encoded) do
    path = Path.join(sink.path, name)

    with true <- transport_attribution_sink_same?(sink),
         {:ok, file} <- File.open(path, [:write, :binary, :exclusive]) do
      outcome =
        transport_attribution_safe(
          fn ->
            with :ok <- File.chmod(path, 0o600),
                 {:ok, before_stat} <- File.lstat(path),
                 true <- before_stat.type == :regular and before_stat.uid == sink.uid,
                 true <- before_stat.links == 1 and before_stat.size == 0,
                 true <- Bitwise.band(before_stat.mode, 0o7777) == 0o600,
                 true <- transport_attribution_sink_same?(sink),
                 :ok <- IO.binwrite(file, encoded) do
              {:written, transport_attribution_identity(before_stat)}
            else
              _ -> :failed
            end
          end,
          :failed
        )

      closed = File.close(file)

      with :ok <- closed,
           {:written, identity} <- outcome,
           {:ok, after_stat} <- File.lstat(path),
           true <- transport_attribution_identity(after_stat) == identity,
           true <- after_stat.size == byte_size(encoded),
           true <- transport_attribution_sink_same?(sink) do
        :ok
      else
        _ -> :failed
      end
    else
      _ -> :failed
    end
  end

  # TASK18_BACKEND_ATTRIBUTION_IMPLEMENTATION_END

  defp transport_warm_repos do
    Map.new(@transport_repos, fn repo ->
      config = repo.config()
      pool_size = if repo == Singularity.Storage.MigrationRepo, do: 2, else: config[:pool_size]
      pool_count = Keyword.get(config, :pool_count, 1)

      transport_require!(
        is_integer(pool_size) and pool_size > 0 and is_integer(pool_count) and pool_count > 0
      )

      case Singularity.Storage.SafeSQL.query!(repo, "SELECT pg_backend_pid()", [], timeout: 1_000) do
        %Postgrex.Result{rows: [[pid]]} when is_integer(pid) and pid > 0 -> :ok
        _ -> throw(:legacy_transport_observer)
      end

      {Keyword.fetch!(config, :username), pool_size * pool_count}
    end)
  end

  defp transport_parent_baseline(connection, database, expected, previous, deadline) do
    Process.put({__MODULE__, :diagnostic6_baseline_phase}, :deadline_check)
    transport_require!(System.monotonic_time(:millisecond) < deadline)
    Process.put({__MODULE__, :diagnostic6_baseline_phase}, :query)
    Process.delete({__MODULE__, :diagnostic6_baseline_query_result})
    rows = transport_backends(connection, database, previous || [])
    Process.put({__MODULE__, :diagnostic6_baseline_phase}, :query_complete)
    if is_nil(previous), do: Process.put({__MODULE__, :diagnostic6_first_sample}, :query_complete)
    counts = Enum.frequencies_by(rows, &elem(&1, 1))
    Process.put({__MODULE__, :diagnostic6_baseline_phase}, :counts_complete)

    if is_nil(previous),
      do: Process.put({__MODULE__, :diagnostic6_first_sample}, :counts_complete)

    # TASK18_TRANSPORT_DIAGNOSTIC_BEGIN
    Process.put(
      {__MODULE__, :transport_baseline_migration},
      {Map.get(counts, "singularity_migration", 0), Map.get(expected, "singularity_migration", 0)}
    )

    # TASK18_TRANSPORT_DIAGNOSTIC_END
    if rows == previous and counts == expected,
      do: rows,
      else: transport_parent_baseline(connection, database, expected, rows, deadline)
  end

  defp transport_backends(connection, database, baseline) do
    key =
      case Process.get({__MODULE__, :backend_attribution_connection}) do
        {^connection, key} when is_reference(key) -> key
        _ -> throw(:legacy_transport_observer)
      end

    expected = transport_inventory_binding(key, connection, database, :baseline, 2, baseline, nil)
    {result, context} =
      transport_attribution_capture(key, :baseline, 2, baseline, nil, expected.operation, fn ->
        Postgrex.query(
          connection,
          "SELECT pid,usename FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND pid<>pg_backend_pid() ORDER BY pid",
          [database],
          timeout: 1_000
        )
      end)

    Process.put(
      {__MODULE__, :diagnostic6_baseline_query_result},
      transport_diagnostic6_query_result(result)
    )
    transport_inventory_clients!(result, context, expected)
  end

  defp transport_rows(connection, sql, parameters) do
    result = Postgrex.query(connection, sql, parameters, timeout: 1_000)

    if Process.get({__MODULE__, :diagnostic6_baseline_phase}) == :query do
      Process.put(
        {__MODULE__, :diagnostic6_baseline_query_result},
        transport_diagnostic6_query_result(result)
      )
    end

    case result do
      {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) -> rows
      _ -> throw(:legacy_transport_observer)
    end
  end

  defp transport_absence_backends(state) do
    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :backend_query_before,
        backend_sample: :actual_three_column_absence
      })
    )

    expected =
      transport_inventory_binding(state.key, state.connection, state.destination.database,
        :absence, 3, state.baseline, state.child)

    {result, context} =
      transport_attribution_capture(state.key, :absence, 3, state.baseline, state.child,
        expected.operation, fn ->
        Postgrex.query(
          state.connection,
          "SELECT pid,usename,backend_type FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND pid<>pg_backend_pid() ORDER BY pid",
          [state.destination.database],
          timeout: 1_000
        )
      end)

    {original_child_known?, original_child_pid_match?} =
      case {result, state.child} do
        {{:ok, %Postgrex.Result{rows: rows}}, child}
        when is_list(rows) and is_integer(child) and child > 0 ->
          {true, transport_diagnostic7_backend_query(result, state.baseline, child).child_pid?}

        _ ->
          {:unobserved, :unobserved}
      end

    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :backend_result_guard_before,
        backend_query: transport_diagnostic7_backend_query(result, state.baseline, nil),
        backend_original_child_known?: original_child_known?,
        backend_original_child_pid_match?: original_child_pid_match?,
        backend_result_guard: :before
      })
    )

    case result do
      {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) -> :ok
      _ -> throw(:legacy_transport_observer)
    end

    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :backend_result_guard_after,
        backend_result_guard: :passed
      })
    )

    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :backend_row_guard_before,
        backend_row_guards: :before
      })
    )

    pairs = transport_inventory_clients!(result, context, expected)

    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :backend_row_guard_after,
        backend_row_guards: :passed
      })
    )

    Process.put(
      {state.key, :diagnostic8_absence},
      Map.merge(Process.get({state.key, :diagnostic8_absence}), %{
        stage: :backend_row_guards_after,
        backend_row_guards: :passed
      })
    )

    pairs
  end

  defp transport_gate_backends(state, child), do: transport_gate_backends(state, child, 3)

  defp transport_gate_backends(state, child, columns) do
    expected =
      transport_inventory_binding(state.key, state.connection, state.destination.database,
        :gate, columns, state.baseline, child)

    sql =
      case columns do
        2 ->
          "SELECT pid,usename FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND pid<>pg_backend_pid() ORDER BY pid"
        3 ->
          "SELECT pid,usename,backend_type FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND pid<>pg_backend_pid() ORDER BY pid"
      end

    {result, context} =
      transport_attribution_capture(state.key, :gate, columns, state.baseline, child,
        expected.operation, fn ->
          Postgrex.query(state.connection, sql, [state.destination.database], timeout: 1_000)
        end)

    Process.put(
      {state.key, :diagnostic7_backend_query},
      transport_diagnostic7_backend_query(result, state.baseline, child)
    )
    transport_inventory_clients!(result, context, expected)
  end

  defp transport_inventory_clients!(result, context, expected) do
    case transport_backend_inventory(result, context, expected) |> transport_inventory_rejection_observe(result, context, expected) do
      {:ok, {clients, _workers}} -> clients
      :error -> throw(:legacy_transport_observer)
    end
  end

  defp transport_backend_inventory({:ok, %Postgrex.Result{rows: rows}}, context, expected)
       when is_list(rows) and is_map(context) and is_map(expected) do
    with true <- transport_inventory_binding_valid?(expected),
         true <- Enum.all?(Map.keys(expected),
           fn field -> Map.fetch(context, field) == Map.fetch(expected, field) end),
         true <- context[:authority] == :verified and context[:capture] == :complete,
         true <- is_integer(context[:sequence]) and context[:sequence] in 1..32,
         true <- transport_inventory_clock_valid?(context),
         true <- length(rows) <= 64,
         true <- transport_inventory_metadata_valid?(context[:before], expected.database_oid),
         true <- transport_inventory_metadata_valid?(context[:after], expected.database_oid) do
      before = Map.new(context.before, &{&1.pid, &1})
      after_sample = Map.new(context.after, &{&1.pid, &1})

      Enum.reduce_while(rows, {:ok, {[], [], MapSet.new()}}, fn row, {:ok, {clients, workers, seen}} ->
        case transport_inventory_row(row, expected, before, after_sample) do
          {:client, {pid, _} = pair} ->
            if MapSet.member?(seen, pid),
              do: {:halt, :error},
              else: {:cont, {:ok, {[pair | clients], workers, MapSet.put(seen, pid)}}}

          {:worker, %{pid: pid} = worker} ->
            if MapSet.member?(seen, pid),
              do: {:halt, :error},
              else: {:cont, {:ok, {clients, [worker | workers], MapSet.put(seen, pid)}}}

          :error ->
            {:halt, :error}
        end
      end)
      |> case do
        {:ok, {clients, workers, _}} -> {:ok, {Enum.reverse(clients), Enum.reverse(workers)}}
        :error -> :error
      end
    else
      _ -> :error
    end
  end

  defp transport_backend_inventory(_, _, _), do: :error

  defp transport_inventory_binding_valid?(binding) when is_map(binding) do
    case binding do
      %{observer: observer, key: key, operation: operation, nonce: nonce,
        ordinary: ordinary, admin: {admin, admin_monitor}, custodian: {custodian, custodian_monitor},
        database: database, database_oid: oid, stage: stage, columns: columns,
        baseline: baseline, child_pid: child} ->
        observer == self() and is_reference(key) and is_reference(operation) and
          is_reference(nonce) and is_pid(ordinary) and is_pid(admin) and is_reference(admin_monitor) and
          is_pid(custodian) and is_reference(custodian_monitor) and
          is_binary(database) and byte_size(database) > 0 and transport_attribution_oid?(oid) and
          is_list(baseline) and length(baseline) <= 64 and
          Enum.all?(baseline, fn
            {pid, username} -> transport_attribution_pid?(pid) and is_binary(username)
            _ -> false
          end) and length(Enum.uniq_by(baseline, &elem(&1, 0))) == length(baseline) and
          ((stage == :baseline and columns == 2 and child == nil) or
             ((stage == :gate and columns in [2, 3] or stage == :absence and columns == 3) and
                transport_attribution_pid?(child) and not List.keymember?(baseline, child, 0)))

      _ ->
        false
    end
  end

  defp transport_inventory_binding_valid?(_), do: false

  defp transport_inventory_clock_valid?(context) do
    clocks = Enum.map([:before_ns, :query_before_ns, :query_after_ns, :after_ns], &context[&1])
    Enum.all?(clocks, &transport_attribution_integer?/1) and clocks == Enum.sort(clocks)
  end

  defp transport_inventory_metadata_valid?(rows, oid) when is_list(rows) do
    length(rows) <= 64 and
      Enum.all?(rows, fn
        %{pid: pid, datid: ^oid, usesysid: role, backend_type: backend, backend_start_us: started} ->
          transport_attribution_pid?(pid) and (is_nil(role) or transport_attribution_oid?(role)) and
            is_binary(backend) and byte_size(backend) > 0 and
            transport_attribution_integer?(started) and started > 0

        _ ->
          false
      end) and length(Enum.uniq_by(rows, & &1.pid)) == length(rows)
  end

  defp transport_inventory_metadata_valid?(_, _), do: false

  defp transport_inventory_row([pid, username], %{columns: 2} = expected, before, after_sample),
    do: transport_inventory_row([pid, username, nil], %{expected | columns: 3}, before, after_sample)

  defp transport_inventory_row([pid, username, backend], %{columns: 3} = expected, before, after_sample) do
    prior = Map.get(before, pid)
    later = Map.get(after_sample, pid)
    worker? =
      is_map(prior) and prior == later and prior.backend_type == "autovacuum worker" and
        prior.usesysid == nil and prior.datid == expected.database_oid

    cond do
      not transport_attribution_pid?(pid) ->
        :error

      is_binary(username) and backend in [nil, "client backend"] and not worker? ->
        {:client, {pid, username}}

      is_nil(username) and backend in [nil, "autovacuum worker"] and worker? and
          pid != expected.child_pid and not List.keymember?(expected.baseline, pid, 0) ->
        {:worker, Map.take(prior, [:pid, :datid, :usesysid, :backend_type, :backend_start_us])}

      true ->
        :error
    end
  end

  defp transport_inventory_row(_, _, _, _), do: :error

  defp transport_inventory_accept?(%{valid?: true}, key),
    do: Process.get({key, :backend_attribution_close}) == :confirmed

  defp transport_inventory_accept?(_, _), do: false

  defp transport_legacy_trace(owner) do
    %{
      owner: [:erlang.trace_info(owner, :flags), :erlang.trace_info(owner, :tracer)],
      patterns: transport_legacy_trace_patterns()
    }
  end

  defp transport_legacy_trace_patterns do
    Map.new(@transport_mfas ++ @transport_reader_mfas, fn mfa ->
      {mfa,
       Enum.map([:traced, :match_spec, :meta, :meta_match_spec], &:erlang.trace_info(mfa, &1))}
    end)
  end

  defp transport_privacy_tail(key) do
    receive do
      {^key, :privacy, private?} when is_boolean(private?) ->
        transport_privacy_tail(key) and private?
    after
      0 -> true
    end
  end

  defp transport_contains?(binary) when is_binary(binary) do
    Enum.any?(
      [@transport_canary, "synthetic-contract-password", @text_pdf, @binary_png, @deleted_png],
      &(:binary.match(binary, &1) != :nomatch)
    )
  end

  defp transport_contains?(map) when is_map(map),
    do:
      Enum.any?(Map.to_list(map), fn {key, value} ->
        transport_contains?(key) or transport_contains?(value)
      end)

  defp transport_contains?(tuple) when is_tuple(tuple),
    do: tuple |> Tuple.to_list() |> transport_contains?()

  defp transport_contains?(list) when is_list(list) do
    characters? = Enum.all?(list, &(is_integer(&1) and &1 >= 0 and &1 <= 0x10FFFF))

    (characters? and transport_contains?(List.to_string(list))) or
      Enum.any?(list, &transport_contains?/1)
  end

  defp transport_contains?(_), do: false

  defp transport_require!(true), do: :ok
  defp transport_require!(_), do: throw(:legacy_transport_observer)

  # Only this contract controller can hold the real restoration checkpoint.
  # Controller loss releases it naturally; there is no second cleanup timer.
  defp transport_cleanup_checkpoint(nil, _key, _owner), do: :ok

  defp transport_cleanup_checkpoint(controller, key, owner) do
    monitor = Process.monitor(controller)

    try do
      send(controller, {key, :cleanup_checkpoint, owner})

      receive do
        {^key, :cleanup_release, ^controller} -> :ok
        {:DOWN, ^monitor, :process, ^controller, _} -> :ok
      end
    after
      Process.demonitor(monitor, [:flush])
    end
  end

  defp transport_cleanup_remaining_ms(original_absolute_deadline, now),
    do: max(original_absolute_deadline - now, 0)

  defp transport_cleanup_witness(key, pid, ref, {key, pid, ref, category})
       when is_reference(key) and is_pid(pid) and is_reference(ref) and
              category in [:normal, :non_normal],
       do: category

  defp transport_cleanup_witness(_key, _pid, _ref, _witness), do: :unconfirmed

  defp transport_cleanup_record(key, role, ref, pid, reason),
    do: transport_cleanup_record(key, role, ref, pid, reason, Process.get({key, role}))

  defp transport_cleanup_record(key, role, ref, pid, reason, {pid, ref})
       when is_reference(key) and is_pid(pid) and is_reference(ref) and role in [:actor, :owner] do
    category = if reason == :normal, do: :normal, else: :non_normal
    Process.put({key, {:cleanup_down, role}}, {key, pid, ref, category})
    :ok
  end

  defp transport_cleanup_record(_key, _role, _ref, _pid, _reason, _owned), do: :ok

  defp transport_cleanup_receipt(%{actor: actor, owner: owner} = receipt)
       when map_size(receipt) == 2 and actor in [:confirmed, :unconfirmed] and
              owner in [:normal, :non_normal, :unconfirmed],
       do: %{actor: actor, owner: owner}

  defp transport_cleanup_receipt(_), do: :missing

  defp transport_cleanup_proof(%{physical?: physical?, workspace?: workspace?} = proof, receipt)
       when is_boolean(physical?) and is_boolean(workspace?) do
    normalized = transport_cleanup_receipt(receipt)
    closed? = normalized == %{actor: :confirmed, owner: :normal}

    %{
      proof
      | physical?: physical? and closed?,
        valid?: proof.valid? and closed?,
        cleanup: normalized
    }
  end

  defp transport_cleanup_proof(proof, receipt) do
    %{
      proof
      | valid?:
          proof.valid? and
            transport_cleanup_receipt(receipt) == %{actor: :confirmed, owner: :normal}
    }
  end

  defp transport_cleanup_baseline(deadline) do
    %{
      configs:
        Map.new(
          [:singularity_storage, :singularity_runtime],
          &{&1, Map.new(Application.get_all_env(&1))}
        ),
      compiler: Code.compiler_options(),
      runtime?:
        Enum.any?(Application.started_applications(), &(elem(&1, 0) == :singularity_runtime)),
      repos: Map.new(@transport_repos, &{&1, transport_cleanup_binding(&1, deadline)})
    }
  end

  defp transport_cleanup_binding(repo, deadline) do
    case Process.whereis(repo) do
      nil ->
        :absent

      pid when is_pid(pid) ->
        remaining = deadline - System.monotonic_time(:millisecond)

        if remaining > 0 and Process.alive?(pid) do
          case Ecto.Adapters.SQL.query(
                 repo,
                 "SELECT current_database(), oid::bigint FROM pg_catalog.pg_database WHERE datname=current_database()",
                 [],
                 log: false,
                 timeout: min(1_000, remaining)
               ) do
            {:ok, %{rows: [[database, oid]]}}
            when is_binary(database) and is_integer(oid) and oid > 0 ->
              {:present, database, oid}

            _ ->
              :invalid
          end
        else
          :invalid
        end
    end
  rescue
    _ -> :invalid
  catch
    _, _ -> :invalid
  end

  defp transport_cleanup_case(mode, baseline, deadline) do
    controller = self()
    key = make_ref()

    {observer, observer_ref} =
      spawn_monitor(fn -> transport_cleanup_observer(controller, key, mode, deadline) end)

    ready =
      receive do
        {^key, :cleanup_ready, ^observer, owner} when is_pid(owner) -> {:ok, owner}
        {:DOWN, ^observer_ref, :process, ^observer, _} -> :failed
      after
        transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) -> :failed
      end

    case ready do
      {:ok, owner} ->
        owner_ref = Process.monitor(owner)
        send(observer, {key, :cleanup_go, controller})

        observation =
          try do
            receive do
              {^key, :cleanup_started, ^observer, cleanup_deadline}
              when is_integer(cleanup_deadline) ->
                transport_cleanup_observe(mode, key, observer, owner, cleanup_deadline, deadline)
            after
              transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) ->
                transport_cleanup_missing()
            end
          rescue
            _ -> transport_cleanup_missing()
          catch
            _, _ -> transport_cleanup_missing()
          after
            send(owner, {key, :cleanup_release, controller})
          end

        owner_normal? =
          receive do
            {:DOWN, ^owner_ref, :process, ^owner, reason} -> reason == :normal
          after
            transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) -> false
          end

        restored? = owner_normal? and transport_cleanup_baseline(deadline) == baseline
        send(observer, {key, :cleanup_finish, controller})

        observer_normal? =
          receive do
            {:DOWN, ^observer_ref, :process, ^observer, reason} -> reason == :normal
          after
            transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) -> false
          end

        Process.demonitor(owner_ref, [:flush])
        Process.demonitor(observer_ref, [:flush])
        %{observation: observation, recovered?: restored? and observer_normal?}

      :failed ->
        Process.demonitor(observer_ref, [:flush])
        %{observation: transport_cleanup_missing(), recovered?: false}
    end
  end

  defp transport_cleanup_observer(controller, key, mode, deadline) do
    controller_ref = Process.monitor(controller)
    gate = if mode == :control, do: nil, else: controller
    observer = self()

    {actor, actor_ref} =
      spawn_monitor(fn -> transport_actor(observer, key, :clean_frame, gate) end)

    Process.put({key, :actor}, {actor, actor_ref})

    try do
      {owner, _destination} =
        transport_initial_owner(
          key,
          actor,
          actor_ref,
          min(deadline, System.monotonic_time(:millisecond) + 5_000),
          true
        )

      Process.put({key, :owner}, {owner, Process.monitor(owner)})
      send(controller, {key, :cleanup_ready, self(), owner})

      receive do
        {^key, :cleanup_go, ^controller} -> :ok
        {:DOWN, ^controller_ref, :process, ^controller, _} -> :ok
      after
        transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) -> :ok
      end

      cleanup_deadline = System.monotonic_time(:millisecond) + 5_000
      send(controller, {key, :cleanup_started, self(), cleanup_deadline})
      receipt = transport_cleanup_receipt(transport_test_cleanup(key))

      send(
        controller,
        {key, :cleanup_returned, self(), receipt, System.monotonic_time(:millisecond),
         Process.alive?(owner)}
      )

      receive do
        {^key, :cleanup_finish, ^controller} -> :ok
        {:DOWN, ^controller_ref, :process, ^controller, _} -> :ok
      after
        transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) -> :ok
      end
    after
      if Process.get({key, :actor}) || Process.get({key, :owner}), do: transport_test_cleanup(key)

      for name <- [:cleanup_receipt, {:cleanup_down, :actor}, {:cleanup_down, :owner}],
          do: Process.delete({key, name})

      Process.demonitor(controller_ref, [:flush])
    end
  end

  defp transport_cleanup_observe(:control, key, observer, _owner, cleanup_deadline, deadline) do
    transport_cleanup_return(key, observer, cleanup_deadline, deadline, :control, false)
  end

  defp transport_cleanup_observe(mode, key, observer, owner, cleanup_deadline, deadline) do
    held? =
      receive do
        {^key, :cleanup_checkpoint, ^owner} -> true
      after
        transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) -> false
      end

    if held? do
      if mode == :held_join do
        case transport_cleanup_waiting(key, observer, min(cleanup_deadline, deadline)) do
          :waiting ->
            send(owner, {key, :cleanup_release, self()})
            transport_cleanup_return(key, observer, cleanup_deadline, deadline, :joined, true)

          {:returned, receipt, alive?, _at} ->
            %{kind: :early_return, receipt: receipt, waiting?: false, owner_alive?: alive?}

          :unconfirmed ->
            transport_cleanup_missing()
        end
      else
        transport_cleanup_return(key, observer, cleanup_deadline, deadline, :expired, false)
      end
    else
      transport_cleanup_missing()
    end
  end

  defp transport_cleanup_waiting(key, observer, deadline) do
    receive do
      {^key, :cleanup_returned, ^observer, receipt, at, alive?}
      when is_integer(at) and is_boolean(alive?) ->
        {:returned, receipt, alive?, at}
    after
      0 ->
        if System.monotonic_time(:millisecond) < deadline do
          case Process.info(observer, [:status, :current_function]) do
            [status: :waiting, current_function: {__MODULE__, :transport_cleanup_owner_join, 4}] ->
              :waiting

            nil ->
              :unconfirmed

            _ ->
              transport_cleanup_waiting(key, observer, deadline)
          end
        else
          :unconfirmed
        end
    end
  end

  defp transport_cleanup_return(key, observer, cleanup_deadline, deadline, kind, waiting?) do
    receive do
      {^key, :cleanup_returned, ^observer, receipt, at, alive?}
      when is_integer(at) and is_boolean(alive?) ->
        observed_kind =
          if kind == :expired and at < cleanup_deadline, do: :early_return, else: kind

        %{kind: observed_kind, receipt: receipt, waiting?: waiting?, owner_alive?: alive?}
    after
      transport_initial_remaining(deadline, System.monotonic_time(:millisecond)) ->
        transport_cleanup_missing()
    end
  end

  defp transport_cleanup_missing do
    %{kind: :unconfirmed, receipt: :missing, waiting?: false, owner_alive?: true}
  end

  # Only test-owned observer resources are released here. Emergency actor death
  # never changes an unsuccessful proof into helper cleanup credit.
  defp transport_test_cleanup(key) do
    if connection = Process.delete({key, :connection}) do
      try do
        if Process.delete({key, :locked}) == true do
          Postgrex.query(
            connection,
            "SELECT pg_advisory_unlock($1::integer,$2::integer)",
            @transport_lock,
            timeout: 1_000
          )
        end
      rescue
        _ -> :ok
      catch
        _, _ -> :ok
      after
        try do
          if Process.alive?(connection), do: GenServer.stop(connection, :normal, 1_000)
        catch
          _, _ -> :ok
        end
      end
    end

    Process.delete({key, :locked})
    c4_resumed? = transport_c4_emergency_resume(key)
    deadline_closed? = transport_deadline_emergency(key)

    if session = Process.delete({key, :session}) do
      try do
        :trace.session_destroy(session)
      catch
        _, _ -> :ok
      end
    end

    deadline = System.monotonic_time(:millisecond) + 5_000

    # TASK18_TRANSPORT_DIAGNOSTIC4_BEGIN
    transport_diagnostic4_drain(key, 0)
    # TASK18_TRANSPORT_DIAGNOSTIC4_END
    Process.put({key, :diagnostic1_emergency}, %{
      before_actor: transport_diagnostic_owner_alive(key),
      after_actor: :unobserved,
      before_demonitor: :unobserved,
      actor_down_witness: false
    })

    actor_status =
      case Process.delete({key, :actor}) do
        {actor, monitor} = owned ->
          status =
            case transport_cleanup_witness(
                   key,
                   actor,
                   monitor,
                   Process.get({key, {:cleanup_down, :actor}})
                 ) do
              category when category in [:normal, :non_normal] ->
                :confirmed

              :unconfirmed ->
                if ua_control_active?(key) do
                  if Process.alive?(actor), do: send(actor, {key, :close})
                else
                if Process.alive?(actor), do: Process.exit(actor, :kill)
                end

                receive do
                  {:DOWN, ^monitor, :process, ^actor, reason} ->
                    transport_cleanup_record(key, :actor, monitor, actor, reason, owned)
                    :confirmed
                after
                  transport_cleanup_remaining_ms(deadline, System.monotonic_time(:millisecond)) ->
                    :unconfirmed
                end
            end

          Process.demonitor(monitor, [:flush])
          status

        nil ->
          :unconfirmed
      end

    diagnostic = Process.get({key, :diagnostic1_emergency})

    Process.put({key, :diagnostic1_emergency}, %{
      diagnostic
      | after_actor: transport_diagnostic_owner_alive(key),
        actor_down_witness: actor_status == :confirmed
    })

    owner_status =
      case Process.delete({key, :owner}) do
        {owner, monitor} ->
          transport_diagnostic6_drain(key, owner, 0)
          diagnostic = Process.get({key, :diagnostic1_emergency})

          Process.put({key, :diagnostic1_emergency}, %{
            diagnostic
            | before_demonitor: Process.alive?(owner)
          })

          status = transport_cleanup_owner_join(key, owner, monitor, deadline)
          Process.demonitor(monitor, [:flush])
          status

        nil ->
          :unconfirmed
      end

    owner_status = if c4_resumed? and deadline_closed?, do: owner_status, else: :unconfirmed
    receipt = %{actor: actor_status, owner: owner_status}
    Process.put({key, :cleanup_receipt}, receipt)
    transport_attribution_safe(fn -> transport_attribution_close(key) end, :failed)
    receipt
  end

  defp transport_cleanup_owner_join(key, owner, monitor, deadline) do
    case transport_cleanup_witness(
           key,
           owner,
           monitor,
           Process.get({key, {:cleanup_down, :owner}})
         ) do
      category when category in [:normal, :non_normal] ->
        category

      :unconfirmed ->
        receive do
          {:DOWN, ^monitor, :process, ^owner, reason} ->
            transport_cleanup_record(key, :owner, monitor, owner, reason, {owner, monitor})
            if reason == :normal, do: :normal, else: :non_normal
        after
          transport_cleanup_remaining_ms(deadline, System.monotonic_time(:millisecond)) ->
            :unconfirmed
        end
    end
  end

  defp transport_diagnostic6_caught(kind, reason) do
    category =
      case {kind, reason} do
        {:throw, :legacy_transport_observer} -> :observer_guard
        {:error, %{__struct__: Postgrex.Error}} -> :postgrex
        {:error, %{__struct__: DBConnection.ConnectionError}} -> :connection
        {:error, %{__struct__: MatchError}} -> :match
        {:error, %{__struct__: FunctionClauseError}} -> :function_clause
        {:error, %{__struct__: CaseClauseError}} -> :case_clause
        {:error, %{__struct__: ArgumentError}} -> :argument
        {:error, %{__struct__: Protocol.UndefinedError}} -> :protocol
        {:error, %{__struct__: UndefinedFunctionError}} -> :undefined_function
        _ -> :other
      end

    %{kind: if(kind in [:error, :throw, :exit], do: kind, else: :other), category: category}
  end

  defp transport_diagnostic6_query_result({:ok, %Postgrex.Result{rows: rows}})
       when is_list(rows),
       do: :rows_list

  defp transport_diagnostic6_query_result(
         {:error, %Postgrex.Error{postgres: %{code: :invalid_catalog_name}}}
       ),
       do: {:error, :invalid_catalog_name}

  defp transport_diagnostic6_query_result({:error, %Postgrex.Error{}}),
    do: {:error, :postgrex}

  defp transport_diagnostic6_query_result({:error, %DBConnection.ConnectionError{}}),
    do: {:error, :connection}

  defp transport_diagnostic6_query_result({:error, _}), do: {:error, :other}
  defp transport_diagnostic6_query_result(_), do: :other

  defp transport_diagnostic7_backend_query(result, baseline, child) do
    category =
      case transport_diagnostic6_query_result(result) do
        {:error, :other} -> :error_other
        {:error, category} -> category
        category -> category
      end

    snapshot = %{
      result: category,
      row_count: 0,
      joint_rows: %{},
      comparable?: false,
      child_pid?: false,
      child_tuple?: false,
      baseline_equal?: false,
      added: 0,
      missing: 0
    }

    case result do
      {:ok, %Postgrex.Result{rows: rows}} when is_list(rows) ->
        # Invalid pairs contribute classes, never valid membership evidence.
        # Enforcement separately checks every original row without filtering.
        pairs =
          for [pid, username, _backend_type] <- rows,
              is_integer(pid) and pid > 0 and is_binary(username),
              do: {pid, username}

        remaining = pairs -- [{child, "singularity_migration"}]
        comparable? = length(pairs) == length(rows)

        joint_rows =
          rows
          |> Enum.frequencies_by(&transport_diagnostic7_row(&1, baseline))
          |> Map.new(fn {category, count} -> {category, transport_diagnostic7_count(count)} end)

        %{
          snapshot
          | row_count: transport_diagnostic7_count(length(rows)),
            joint_rows: joint_rows,
            comparable?: comparable?,
            child_pid?:
              Enum.any?(rows, fn
                [pid, _, _] when is_integer(pid) and pid > 0 -> pid == child
                _ -> false
              end),
            child_tuple?: {child, "singularity_migration"} in pairs,
            baseline_equal?: comparable? and remaining == baseline,
            added: transport_diagnostic7_count(length(remaining -- baseline)),
            missing: transport_diagnostic7_count(length(baseline -- remaining))
        }

      _ ->
        snapshot
    end
  end

  defp transport_diagnostic7_row([pid, username, backend_type], baseline) do
    pid_class =
      case pid do
        value when is_integer(value) and value > 0 -> :positive
        value when is_integer(value) -> :nonpositive
        nil -> :null
        _ -> :other
      end

    username_class =
      case username do
        "singularity_migration" ->
          :migration

        nil ->
          :null

        value when is_binary(value) ->
          if Enum.any?(baseline, fn {_pid, role} -> role == value end),
            do: :baseline_role,
            else: :other_binary

        _ ->
          :other
      end

    backend_class =
      case backend_type do
        "client backend" -> :client
        "autovacuum worker" -> :autovacuum_worker
        "parallel worker" -> :parallel_worker
        nil -> :null
        value when is_binary(value) -> :other_binary
        _ -> :other
      end

    {:three, pid_class, username_class, backend_class}
  end

  defp transport_diagnostic7_row(_, _),
    do: {:other, :unavailable, :unavailable, :unavailable}

  defp transport_diagnostic7_count(count) when count in 0..64, do: count
  defp transport_diagnostic7_count(_), do: :overflow

  defp transport_diagnostic6_elapsed(value) when is_integer(value) and value in 0..5_000,
    do: value

  defp transport_diagnostic6_elapsed(_), do: :overrun

  defp transport_diagnostic6_armed(
         {key, :diagnostic6_armed, owner, outcome, elapsed},
         %{key: key, owner: owner}
       )
       when is_reference(key) and is_pid(owner) and outcome in [:armed, :expired] and
              ((is_integer(elapsed) and elapsed in 0..5_000) or elapsed == :overrun),
       do: %{outcome: outcome, elapsed: elapsed}

  defp transport_diagnostic6_armed(_, _), do: :unmatched

  defp transport_diagnostic6_drain(_key, _owner, 2), do: :ok

  defp transport_diagnostic6_drain(key, owner, count) do
    receive do
      {^key, :diagnostic6_armed, ^owner, outcome, elapsed}
      when outcome in [:armed, :expired] and
             ((is_integer(elapsed) and elapsed in 0..5_000) or elapsed == :overrun) ->
        Process.put({key, :diagnostic6_armed}, %{outcome: outcome, elapsed: elapsed})
        transport_diagnostic6_drain(key, owner, count + 1)
    after
      0 -> :ok
    end
  end

  defp transport_diagnostic_owner_alive(key) do
    case Process.get({key, :owner}) do
      {owner, _} when is_pid(owner) -> Process.alive?(owner)
      _ -> :unobserved
    end
  end

  # TASK18_TRANSPORT_DIAGNOSTIC4_BEGIN
  defp transport_diagnostic4_record(key, stage) do
    count =
      case Process.get({key, :diagnostic4_acquisition}) do
        %{count: count} when is_integer(count) and count in 0..32 -> min(count + 1, 32)
        _ -> 1
      end

    Process.put({key, :diagnostic4_acquisition}, %{last: stage, count: count})
    :ok
  end

  defp transport_diagnostic4_drain(_key, 32), do: :ok

  defp transport_diagnostic4_drain(key, count) do
    actor = case Process.get({key, :actor}) do
      {pid, monitor} when is_pid(pid) and is_reference(monitor) -> pid
      _ -> nil
    end
    receive do
      {^key, :diagnostic4_stage, stage}
      when stage in [
             :before_allocation,
             :allocated,
             :baseline_paused,
             :maintenance_started,
             :database_created,
             :root_created,
             :extensions_ready,
             :before_migration,
             :migrated
           ] ->
        transport_diagnostic4_record(key, stage)
        transport_diagnostic4_drain(key, count + 1)
      {^key, :diagnostic_actor_failure, ^actor, kind, origin, reason_tag} = message
      when is_pid(actor) and transport_actor_failure_fields(kind, origin, reason_tag) ->
        transport_actor_failure_record(key, message)
        transport_diagnostic4_drain(key, count + 1)
    after
      0 -> :ok
    end
  end

