  test "self-seed categories survive the existing first-failure diagnostic interface" do
    key = {__MODULE__, :ua_control}
    previous = Process.get(key)
    Process.put(key, %{diagnostic: nil, diagnostic_phase: :admit, seed_mismatch: [:mount]})

    try do
      site = ua_control_diagnostic(:throw, [{__MODULE__, :ua_control_self!, 1, [line: 6298]}])
      assert Map.get(site, :seed_fields) == [:mount]
      assert Map.take(site, [:phase, :kind, :line]) ==
        %{phase: :admit, kind: :throw, line: 6298}
      ua_control_update(%{diagnostic_phase: :restore, seed_mismatch: [:uid]})
      assert ua_control_diagnostic(:error, []) == site
    after
      if previous == nil, do: Process.delete(key), else: Process.put(key, previous)
    end
  end

  test "self-seed diagnostics retain only first fixed field categories and sanitize output" do
    key = {__MODULE__, :ua_control}
    previous = Process.get(key)
    fields = [:root, :directory, :status, :uid, :pid_ns, :mount_ns, :cgroup, :mount,
      :proc, :start_ticks]
    canary = <<0, 255, "PRIVATE_SELF_SEED_DIAGNOSTIC">>
    seed = Map.new(fields, &{&1, canary})

    try do
      Enum.each(fields, fn field ->
        Process.put(key, %{diagnostic: nil, diagnostic_phase: :admit})
        :ok = ua_control_seed_mismatch(seed, seed)
        assert Map.get(Process.get(key), :seed_mismatch) == nil
        :ok = ua_control_seed_mismatch(Map.put(seed, field, :changed), seed)
        assert Map.get(Process.get(key), :seed_mismatch) == [field]
        assert ua_control_seed_suffix(%{seed_fields: [field]}) ==
          " seed_fields=" <> Atom.to_string(field)
      end)

      Process.put(key, %{diagnostic: nil, diagnostic_phase: :admit})
      :ok = ua_control_seed_mismatch(%{seed | mount: :changed, cgroup: :changed}, seed)
      :ok = ua_control_seed_mismatch(%{seed | root: :later}, seed)
      assert Map.get(Process.get(key), :seed_mismatch) == [:cgroup, :mount]
      assert ua_control_seed_suffix(%{seed_fields: [:cgroup, :mount], ignored: canary}) ==
        " seed_fields=cgroup,mount"
      retained = %{phase: :sources, kind: :error, line: 0}
      Process.put(key, %{diagnostic: retained, diagnostic_phase: :admit})
      :ok = ua_control_seed_mismatch(%{seed | root: :later}, seed)
      assert Map.get(Process.get(key), :seed_mismatch) == nil
      assert Map.get(Process.get(key), :diagnostic) == retained

      Enum.each([nil, [], canary, [canary], [:unknown], [:root, :root],
        [:mount, :root], Enum.concat(fields, [:root])], fn invalid ->
        assert ua_control_seed_suffix(%{seed_fields: invalid}) == ""
      end)
      assert ua_control_seed_suffix(%{}) == ""
      assert ua_control_seed_suffix(%{seed_fields: [:root]}) == " seed_fields=root"
      assert ua_control_seed_suffix(%{seed_fields: [:root | :invalid_tail]}) == ""
      assert ua_control_seed_suffix(%{seed_fields: [:root | canary]}) == ""
    after
      if previous == nil, do: Process.delete(key), else: Process.put(key, previous)
    end
  end

  defp ua_control_seed_mismatch(value, seed) do
    control = Process.get({__MODULE__, :ua_control})
    if control.diagnostic == nil and Map.get(control, :seed_mismatch) == nil and value != seed do
      fields = Enum.filter(ua_control_seed_fields(), fn field ->
        Map.fetch!(value, field) != Map.fetch!(seed, field)
      end)
      ua_control_update(%{seed_mismatch: fields, mount_delta: if(:mount in fields, do: ua_control_mount_delta(value.mount, seed.mount), else: nil)})
      ua_pe_bridge_capture(value, seed, fields); end
    :ok
  end

  defp ua_control_seed_fields do
    [:root, :directory, :status, :uid, :pid_ns, :mount_ns, :cgroup, :mount,
      :proc, :start_ticks]
  end

  defp ua_control_seed_suffix(diagnostic) do
    fields = Map.get(diagnostic, :seed_fields)
    allowed = ua_control_seed_fields()
    case fields do
      fields when is_list(fields) and length(fields) in 1..10 ->
        if fields == Enum.filter(allowed, &(&1 in fields)),
          do: " seed_fields=" <> Enum.map_join(fields, ",", &Atom.to_string/1) <> ua_control_mount_suffix(diagnostic), else: ""
      _ -> ""
    end
  end

