    seed = Map.new(ua_control_seed_fields(), &{&1, :unchanged}) |> Map.put(:mount, ua_mount_literal())
    changed = %{seed | mount: String.replace(seed.mount, "rw,nosuid", "ro,nosuid")}

    try do
      Process.put(key, %{diagnostic: nil, diagnostic_phase: :restore})
      :ok = ua_control_seed_mismatch(seed, seed)
      assert Map.get(Process.get(key), :mount_delta) == nil
      :ok = ua_control_seed_mismatch(changed, seed)
      site = ua_control_diagnostic(:throw, [{__MODULE__, :ua_control_self!, 1, [line: 6298]}])
      assert Map.get(site, :mount_delta) == [:options]
      assert ua_control_seed_suffix(site) == " seed_fields=mount mount_delta=options"
      :ok = ua_control_seed_mismatch(%{seed | mount: seed.mount <> seed.mount}, seed)
      assert ua_control_diagnostic(:error, []) == site
      assert Map.get(Process.get(key), :mount_delta) == [:options]
      Process.put(key, %{diagnostic: site, diagnostic_phase: :restore})
      :ok = ua_control_seed_mismatch(changed, seed)
      assert Map.get(Process.get(key), :mount_delta) == nil
    after
      if previous == nil, do: Process.delete(key), else: Process.put(key, previous)
    end
  end

  test "mount delta distinguishes raw field changes, membership and order with bounded pure inputs" do
    seed = ua_mount_literal()
    columns = ["21", "1", "0:5", "/", "/proc", "rw,nosuid,nodev,noexec,relatime",
      "-", "proc", "proc", "rw"]
    assert Enum.join(columns, " ") <> "\n" == seed

    for {index, replacement, label} <- [
      {1, "2", :parent}, {2, "0:6", :device}, {3, "/other", :root},
      {4, "/other", :point}, {5, "ro", :options}, {7, "tmpfs", :type},
      {8, "PRIVATE_MOUNT_SOURCE", :source}, {9, "ro", :super_options}
    ] do
      assert ua_control_mount_delta(seed, seed) == []
      changed = columns |> List.replace_at(index, replacement) |> Enum.join(" ")
      assert ua_control_mount_delta(changed <> "\n", seed) == [label]
    end

    other = "22 1 0:6 / /other rw - tmpfs tmpfs rw\n"
    for {current, original, expected} <- [
      {seed <> other, seed, [:added]},
      {seed, seed <> other, [:removed]},
      {other <> seed, seed <> other, [:order]},
      {String.replace(seed, "21 1 ", "23 1 "), seed, [:added, :removed]},
      {String.replace(seed, " - ", " shared:2 - "), seed, [:optional]},
      {String.replace(seed, "rw,nosuid", "nosuid,rw"), seed, [:options]},
      {String.replace(seed, "21 1 ", "21 2 ") |> String.replace("proc proc", "proc private"),
        seed, [:parent, :source]}
    ] do
      assert ua_control_mount_delta(original, original) == []
      assert ua_control_mount_delta(current, original) == expected
    end

    for invalid <- [nil, :unknown, <<0, 255>>, "", "truncated", seed <> seed,
      String.duplicate("x", 16_385), String.replace(seed, "0:5", "00:5")] do
      assert ua_control_mount_delta(seed, seed) == []
      assert ua_control_mount_delta(invalid, seed) == [:invalid]
      assert ua_control_mount_delta(seed, invalid) == [:invalid]
    end
  end

  test "mount delta output accepts only canonical finite labels" do
    canary = <<0, 255, "PRIVATE_MOUNT_DIAGNOSTIC">>
    labels = [:added, :removed, :order, :parent, :device, :root, :point,
      :options, :optional, :type, :source, :super_options, :invalid]
    for label <- labels do
      assert ua_control_mount_suffix(%{mount_delta: [label], ignored: canary}) ==
        " mount_delta=" <> Atom.to_string(label)
    end
    assert ua_control_mount_suffix(%{mount_delta: [:added, :removed]}) ==
      " mount_delta=added,removed"
    for invalid <- [nil, [], canary, [canary], [:unknown], [:added, :added],
      [:removed, :added], labels ++ [:added], [:added | :tail], [:added | canary]] do
      assert ua_control_mount_suffix(%{mount_delta: invalid}) == ""
    end
    assert ua_control_mount_suffix(%{}) == ""
  end

  # Diagnostic-only reduction of the two already-acquired byte strings.
  # No returned label participates in mount admission or seed equality.
  defp ua_control_mount_delta(current, seed) do
    with {:ok, current_lines} <- ua_text_lines(current, 16384),
         {:ok, seed_lines} <- ua_text_lines(seed, 16384),
         {:ok, current_rows} <- ua_mount_rows(current_lines, [], []),
         {:ok, seed_rows} <- ua_mount_rows(seed_lines, [], []) do
      current_ids = Enum.map(current_rows, & &1.id)
      seed_ids = Enum.map(seed_rows, & &1.id)
      current_map = Map.new(current_rows, &{&1.id, ua_control_mount_row_fields(&1)})
      seed_map = Map.new(seed_rows, &{&1.id, ua_control_mount_row_fields(&1)})
      common = Enum.filter(current_ids, &Map.has_key?(seed_map, &1))
      original_common = Enum.filter(seed_ids, &Map.has_key?(current_map, &1))
      Enum.filter(ua_control_mount_labels(), fn
        :added -> Enum.any?(current_ids, &(not Map.has_key?(seed_map, &1)))
        :removed -> Enum.any?(seed_ids, &(not Map.has_key?(current_map, &1)))
        :order -> common != original_common
        :invalid -> false
        field -> Enum.any?(common, fn id -> current_map[id][field] != seed_map[id][field] end)
      end)
    else
      _ -> [:invalid]
    end
  end

  defp ua_control_mount_row_fields(record) do
    [left, right] = :binary.split(record.raw, " - ", [:global])
    [_id, parent, device, root, point, options | optional] = :binary.split(left, " ", [:global])
    [type, source, super_options] = :binary.split(right, " ", [:global])
    %{parent: parent, device: device, root: root, point: point, options: options,
      optional: optional, type: type, source: source, super_options: super_options}
  end

  defp ua_control_mount_labels do
    [:added, :removed, :order, :parent, :device, :root, :point,
      :options, :optional, :type, :source, :super_options, :invalid]
  end

  defp ua_control_mount_suffix(diagnostic) do
    labels = Map.get(diagnostic, :mount_delta)
    case labels do
      labels when is_list(labels) and length(labels) in 1..13 ->
        if labels == Enum.filter(ua_control_mount_labels(), &(&1 in labels)),
          do: " mount_delta=" <> Enum.map_join(labels, ",", &Atom.to_string/1), else: ""
      _ -> ""
    end
  end

