  defp ua_mi_path?(path) when is_binary(path) and byte_size(path) in 1..4096 do
    path == "/" or
      (ua_absolute?(path) and :binary.match(path, <<0>>) == :nomatch and
        Enum.all?(tl(:binary.split(path, "/", [:global])), &(&1 not in ["", ".", ".."])))
  end
  defp ua_mi_path?(_), do: false

  defp ua_mi_stable?({type, major, minor, inode, uid, mode}, expected) do
    ua_object?({type, major, minor, inode}, expected) and is_integer(uid) and
      uid >= 0 and uid <= 4_294_967_295 and is_integer(mode) and mode >= 0 and mode <= 65_535 and
      Bitwise.band(mode, 0o170000) ==
        case expected do
          :directory -> 0o040000
          :regular -> 0o100000
          :symlink -> 0o120000
        end
  end
