  # Step order is a finite input contract, not attestation that IO occurred.
  # It contains no changing timestamp in the immutable closure identity.
  defp ua_mi_closure?(closure) do
    routes = ua_mi_routes()
    with true <- ua_b_keys?(closure, [:regions, :directories, :aliases, :origins,
           :tmpdir, :system_tmpdir, :resolved_tmp, :launcher]),
         true <- closure.regions == routes.regions,
         true <- closure.tmpdir == routes.tmp and closure.system_tmpdir == routes.tmp and
           closure.resolved_tmp == routes.tmp and closure.launcher == routes.launcher,
         true <- ua_b_proper_list?(closure.directories),
         true <- length(closure.directories) == length(routes.directories),
         true <- Enum.all?(Enum.zip(closure.directories, routes.directories), fn
           {%{path: path, before: identity, after: identity} = row, path} ->
             ua_b_keys?(row, [:path, :before, :after]) and ua_mi_path?(path) and
               ua_mi_stable?(identity, :directory)
           _ -> false
         end),
         true <- ua_b_proper_list?(closure.aliases) and length(closure.aliases) == 2,
         true <- Enum.all?(Enum.zip(closure.aliases, routes.aliases), fn
           {%{path: path, target_before: target, target_after: target, resolved: resolved,
              link_before: link, link_after: link, lexical: object, physical: object} = row,
            {path, target, resolved}} ->
             ua_b_keys?(row, [:path, :target_before, :target_after, :resolved,
               :link_before, :link_after, :lexical, :physical]) and
               ua_mi_stable?(link, :symlink) and
               ua_mi_stable?(object, if(target == "../../../../../../deps/ex_cmd/priv",
                 do: :directory, else: :regular))
           _ -> false
         end),
         true <- ua_b_proper_list?(closure.origins) and length(closure.origins) == 3,
         true <- Enum.all?(Enum.zip(closure.origins, routes.origins), fn
           {%{module: module, before_load: path, returned: path, before_read: path,
              steps: steps, object_before: object, object_after: object} = row,
            {module, path}} ->
             ua_b_keys?(row, [:module, :before_load, :returned, :before_read, :steps,
               :object_before, :object_after]) and ua_mi_stable?(object, :regular) and
               steps == [:origin_check, :load, :returned_origin_check, :read]
