  end

  defp ua_mi_admit_relation?(previous, sample, seed, binding) do
    with true <- ua_mi_pending_native?(binding),
         true <- ua_mi_boot_observation?(sample),
         true <- sample.identity == seed and seed == binding.bootstrap.identity,
         true <- sample.self.pid == binding.bootstrap.self.pid and
           sample.self.descriptors == binding.bootstrap.self.descriptors and
           sample.sources == binding.bootstrap.sources,
         {:directory, major, minor, _} = seed.root.object,
         {:ok, _, old_proc} <- ua_mi_self_table(previous, sample.self.pid, {major, minor}),
         {:ok, _, new_proc} <- ua_mi_self_table(sample.literal, sample.self.pid, {major, minor}),
         true <- old_proc.raw == new_proc.raw,
         {:ok, _} <- ua_parse_mountinfo(sample.literal,
           %{self_pid: sample.self.pid, native_pid: binding.native_pid, proc_device: {major, minor}}),
         {:ok, lines} <- ua_text_lines(sample.literal, 16384),
         {:ok, rows} <- ua_mount_rows(lines, [], []),
         false <- Enum.any?(rows, fn row ->
           row.id != new_proc.id and ua_covers?(row.point, "/proc/" <> binding.native_pid <> "/ns/mnt")
         end) do
      ua_mi_retained_additions?(previous, sample.literal)
    else
      _ -> false
    end
  end

  defp ua_mi_admit_commit?(state, full) do
    with true <- ua_mi_pending_native?(state.custody),
         true <- ua_mi_custody?(full),
         b = state.custody,
         true <- full.expected.native_pid == b.native_pid and
           full.expected.self_pid == b.bootstrap.self.pid and
           full.expected.directory == b.directory.object,
         true <- Enum.all?([:handle, :command, :reader, :writer, :owner, :caller, :run,
           :monitor_ref, :exit_ref, :port, :port_ref],
           &(Map.fetch!(full.expected, &1) == Map.fetch!(b, &1))),
         true <- full.sources == b.bootstrap.sources,
         [root, own, _status] = full.descriptors,
         [root_before, own_before] = b.bootstrap.self.descriptors,
         true <- root.number == root_before.number and own.number == own_before.number,
         true <- ua_mi_relation?(state.committed,
           %{literal: state.pending, numeric: state.pending, identity: state.seed, custody: full},
           state.seed, full) do
      true
    else
      _ -> false
    end
  end

  # Phase names identify actual enclosing boundaries; tokens are IO obligations,
  # never proof that IO occurred. No inapplicable guard is credited vacuously.
  defp ua_mi_guards(phase \\ :post_loop)
  defp ua_mi_guards(:bootstrap), do: [:source, :closure, :self, :raw, :seed_once]
  defp ua_mi_guards(:admit), do: [:beam, :live, :source, :port, :deadline, :self, :descriptors_open]
  defp ua_mi_guards(:post_loop),
    do: [:absence, :port, :source, :sql, :sql_close, :self, :terminal, :trace, :deadline, :descriptors_open]
  defp ua_mi_guards(:restore), do: [:source, :self, :environment, :cleanup, :close]
  defp ua_mi_guards(_), do: :invalid

  defp ua_mi_checkpoint(state, :begin) do
    if ua_mi_state?(state) and state.status == :committed and state.pending == nil and
         state.primary == nil and state.phase == :post_loop and state.descriptors == :open,
      do: %{state | status: :open},
      else: ua_mi_fail(state, :state)
  end

  defp ua_mi_checkpoint(state, {:sample, sample}) do
    if ua_mi_state?(state) and state.status == :open and state.descriptors == :open do
      previous = if state.pending == nil, do: state.committed, else: state.pending
      valid = case state.phase do
        :bootstrap -> ua_mi_bootstrap(state.custody, sample, nil) and sample.literal == previous
        :admit -> ua_mi_admit_relation?(previous, sample, state.seed, state.custody)
        phase when phase in [:post_loop, :restore] ->
          ua_mi_relation?(previous, sample, state.seed, state.custody)
      end
      if valid, do: %{state | pending: sample.literal}, else: ua_mi_fail(state, :sample)
    else
      ua_mi_fail(state, :state)
    end
  end

  # Admission has no two-argument success path: full original custody is mandatory.
  defp ua_mi_checkpoint(state, {:commit, guards, full}) do
    if ua_mi_state?(state) and state.phase == :admit and state.status == :open and
         state.descriptors == :open and state.pending != nil and state.primary == nil and
         guards == ua_mi_guards(:admit) and ua_mi_admit_commit?(state, full) do
      %{state | custody: full, committed: state.pending, pending: nil, status: :committed}
    else
      ua_mi_fail(state, :commit)
    end
  end

  defp ua_mi_checkpoint(state, {:commit, guards}) do
    if ua_mi_state?(state) and state.phase != :admit and state.status == :open and
         state.descriptors == :open and state.pending != nil and
         guards == ua_mi_guards(state.phase) and state.primary == nil do
      %{state | committed: state.pending, pending: nil, status: :committed,
        descriptors: if(state.phase == :restore, do: :closed, else: :open)}
    else
      ua_mi_fail(state, :commit)
    end
  end

  defp ua_mi_checkpoint(state, {:abort, reason}) when reason in [:exception, :timeout, :abort],
    do: ua_mi_fail(state, reason)
  defp ua_mi_checkpoint(state, _), do: ua_mi_fail(state, :state)

  defp ua_mi_state?(state) do
    with true <- ua_b_keys?(state, [:phase, :descriptors, :seed, :custody, :committed,
           :pending, :status, :primary]),
         true <- state.phase in [:bootstrap, :admit, :post_loop, :restore],
         true <- state.status in [:open, :committed, :failed],
         true <- state.descriptors == :open or
           (state.phase == :restore and state.status == :committed and state.descriptors == :closed),
         true <- ua_mi_primary?(state.primary),
         true <- ua_mi_state_observation?(state, state.committed),
         true <- state.pending == nil or ua_mi_state_observation?(state, state.pending) do
      true
    else
      _ -> false
    end
  end

  defp ua_mi_state_observation?(%{phase: :bootstrap} = state, raw) do
    ua_mi_boot_observation?(state.custody) and state.seed == state.custody.identity and
      raw == state.custody.literal
  end
  defp ua_mi_state_observation?(%{phase: :admit, status: status} = state, raw)
       when status != :committed do
    if ua_mi_pending_native?(state.custody) do
      sample = ua_mi_raw(state.custody.bootstrap, raw)
      ua_mi_admit_relation?(state.committed, sample, state.seed, state.custody)
    else
      false
    end
  end
  defp ua_mi_state_observation?(state, raw) do
    ua_mi_relation?(state.committed,
      %{literal: raw, numeric: raw, identity: state.seed, custody: state.custody},
      state.seed, state.custody)
  end

  defp ua_mi_primary?(value) when value in [nil, :sample, :commit, :exception, :timeout, :abort, :state],
    do: true
  defp ua_mi_primary?(%{phase: phase, kind: kind, line: line} = value) do
    ua_b_keys?(value, [:phase, :kind, :line]) and
      phase in [:admit, :restore, :sources, :post_loop] and kind in [:error, :throw, :exit] and
      is_integer(line) and line >= 0
  end
  defp ua_mi_primary?(_), do: false

  defp ua_mi_fail(state, reason) when is_map(state) do
    state |> Map.put(:pending, nil) |> Map.put(:status, :failed) |>
      Map.put(:primary, Map.get(state, :primary) || reason)
  end
  defp ua_mi_fail(_, reason), do: %{pending: nil, status: :failed, primary: reason}
  defp ua_mi_closure_literal do
    routes = ua_mi_routes()
    stable = fn type, inode -> {type, 254, 0, inode, 1000, 0o100600} end
    directories = Enum.with_index(routes.directories, 100) |> Enum.map(fn {path, inode} ->
      object = {:directory, 254, 0, inode, 1000, 0o40700}
      %{path: path, before: object, after: object}
    end)
    aliases = Enum.with_index(routes.aliases, 200) |> Enum.map(fn {{path, target, resolved}, inode} ->
      link = {:symlink, 254, 0, inode, 1000, 0o120777}
      object = if target == "../../../../../../deps/ex_cmd/priv",
        do: {:directory, 254, 0, inode + 10, 1000, 0o40700},
        else: stable.(:regular, inode + 10)
      %{path: path, target_before: target, target_after: target, resolved: resolved,
        link_before: link, link_after: link, lexical: object, physical: object}
    end)
    origins = Enum.with_index(routes.origins, 300) |> Enum.map(fn {{module, path}, inode} ->
      object = stable.(:regular, inode)
      %{module: module, before_load: path, returned: path, before_read: path,
        steps: [:origin_check, :load, :returned_origin_check, :read],
        object_before: object, object_after: object}
    end)
    %{regions: routes.regions, directories: directories, aliases: aliases,
      origins: origins, tmpdir: routes.tmp, system_tmpdir: routes.tmp,
      resolved_tmp: routes.tmp, launcher: routes.launcher}
  end

  defp ua_mi_literal do
    closure = ua_mi_closure_literal()
    native = ua_b_native_literal()
    admission = native.original.admission
    custody = %{expected: native.expected, original: native.original,
      sources: ua_mi_sources(),
      descriptors: [
        %{number: 9, object: admission.proc_root, mount: "21"},
        %{number: 10, object: admission.numeric_directory, mount: "21"},
        %{number: 11, object: admission.status_fd, mount: "21"}
      ]}
    raw = ua_mount_literal() <> "22 1 0:6 / /contract/project rw - tmpfs tmpfs rw\n"
    selected = String.trim_trailing(ua_mount_literal(), "\n")
    identity = %{root: %{object: admission.proc_root, mount: "21", uid: 0},
      directory: %{object: admission.numeric_directory, mount: "21", uid: 1000},
      status: %{object: admission.status_fd, mount: "21", uid: 1000},
      uid: "1000", pid_ns: {admission.pid_namespace, "20"},
      mount_ns: {admission.mount_namespace, "20"}, cgroup: native.expected.cgroup_raw,
      proc: selected, start_ticks: "123456789",
      mount: %{selected_proc_raw: selected, closure: closure}}
    %{literal: raw, numeric: raw, identity: identity, custody: custody}
  end

  defp ua_mi_raw(sample, raw), do: %{sample | literal: raw, numeric: raw}
  defp ua_mi_closure(sample, change),
    do: update_in(sample, [:identity, :mount, :closure], change)
  defp ua_mi_accept?(original, current),
    do: ua_mi_relation?(original.literal, current, original.identity, original.custody)
  defp ua_mi_boot_literal do
    raw = ua_mount_literal() <> "22 1 0:6 / /contract/project rw - tmpfs tmpfs rw\n"
    selected = String.trim_trailing(ua_mount_literal(), "\n")
    pid_ns = {%{link: "pid:[4026531836]", object: {:regular, 0, 4, 4026531836}}, "20"}
    mount_ns = {%{link: "mnt:[4026531840]", object: {:regular, 0, 4, 4026531840}}, "20"}
    root = %{object: {:directory, 0, 5, 1}, mount: "21", uid: 0}
    directory = %{object: {:directory, 0, 5, 4242}, mount: "21", uid: 1000}
    status = %{object: {:regular, 0, 5, 42420}, mount: "21", uid: 1000}
    identity = %{root: root, directory: directory, status: status, uid: "1000",
      pid_ns: pid_ns, mount_ns: mount_ns, cgroup: "0::/owned:test scope\n",
      proc: selected, start_ticks: "123456789",
      mount: %{selected_proc_raw: selected, closure: ua_mi_closure_literal()}}
    self = %{pid: "4242", readlink: "4242", literal_status: ua_status_literal(),
      numeric_status: ua_status_literal(),
      stat: ua_stat_literal("beam.smp", "S", List.replace_at(ua_stat_fields(), 18, "123456789")),
      literal_cgroup: identity.cgroup, numeric_cgroup: identity.cgroup,
      literal_directory: directory, numeric_status_object: status,
      literal_pid_namespace: pid_ns, children_namespace: pid_ns,
      literal_children_namespace: pid_ns, literal_mount_namespace: mount_ns,
      descriptors: [%{number: 9, observation: root}, %{number: 10, observation: directory}]}
    %{kind: :bootstrap_self, literal: raw, numeric: raw, identity: identity,
      self: self, sources: ua_mi_sources()}
  end

  # Literal fixture construction only; operational callers supply observed values.
  defp ua_mi_pending_literal(sample) do
    %{bootstrap: sample, native_pid: "5252",
      directory: %{object: {:directory, 0, 5, 5252}, mount: "21", uid: 1000},
      handle: {:handle, :command, :command_ref, :exit_ref, :owner},
      command: :command, reader: :reader, writer: :writer, owner: :owner, caller: :actor,
      run: :run, monitor_ref: :command_ref, exit_ref: :exit_ref,
      port: :port, port_ref: :port_ref, odu_pid: "5251", connected: :command,
      odu_path: "/home/gao/Workspace/gsmlg-opt/Singularity/.trees/v0.2-phase-5-export-backup/_build/test/lib/ex_cmd/priv/odu_linux_amd64"}
  end

  defp ua_mi_state(sample, phase \\ :post_loop) do
    custody = case phase do
      :bootstrap -> sample
      :admit -> ua_mi_pending_literal(sample)
      phase when phase in [:post_loop, :restore] -> sample.custody
    end
    %{phase: phase, descriptors: :open, seed: sample.identity, custody: custody,
      committed: sample.literal, pending: nil, status: :open, primary: nil}
  end

  # Test call shorthand only: never used as an operational evidence collector.
  defp ua_mi_literal_commit(%{phase: :admit} = state, guards),
    do: ua_mi_checkpoint(state, {:commit, guards, ua_mi_literal().custody})
  defp ua_mi_literal_commit(state, guards), do: ua_mi_checkpoint(state, {:commit, guards})
  defp ua_mi_added(point, id \\ "23", root \\ "/", type \\ "tmpfs"),
    do: id <> " 1 0:7 " <> root <> " " <> point <> " rw - " <> type <> " none rw\n"

  test "mount refinement M01 identical observations require complete typed closure" do
    for mutate <- [
      fn s -> ua_mi_closure(s, fn _ -> nil end) end,
      fn s -> ua_mi_closure(s, &Map.delete(&1, :directories)) end,
      fn s -> ua_mi_closure(s, &%{&1 | regions: tl(&1.regions)}) end,
      fn s -> ua_mi_closure(s, &%{&1 | directories: []}) end,
      fn s -> ua_mi_closure(s, &%{&1 | origins: []}) end,
      fn s -> ua_mi_closure(s, fn c ->
        %{c | origins: [Map.put(hd(c.origins), :before_load, "/outside/beam") | tl(c.origins)]}
      end) end
    ] do
      good = ua_mi_literal()
      assert ua_mi_accept?(good, good)
      refute ua_mi_accept?(good, mutate.(good))
      fresh = ua_mi_literal()
      assert ua_mi_accept?(fresh, fresh)
      invalid = mutate.(fresh)
      refute ua_mi_accept?(invalid, invalid)
    end
  end

  test "mount refinement M02 disjoint additions retain every old row in relative order" do
    good = ua_mi_literal()
    [first, second, ""] = :binary.split(good.literal, "\n", [:global])
    a = ua_mi_added("/unrelated/a")
    b = ua_mi_added("/unrelated/b", "24")
    for raw <- [good.literal <> a, good.literal <> a <> b, a <> good.literal,
      first <> "\n" <> a <> second <> "\n", a <> first <> "\n" <> b <> second <> "\n"] do
      fresh = ua_mi_literal()
      assert ua_mi_accept?(fresh, fresh)
      assert ua_mi_accept?(fresh, ua_mi_raw(fresh, raw))
    end
  end

  test "mount refinement M02 each fixed protected root rejects an added row" do
    for point <- ua_mi_routes().regions do
      good = ua_mi_literal()
      assert ua_mi_accept?(good, good)
      refute ua_mi_accept?(good, ua_mi_raw(good, good.literal <> ua_mi_added(point)))
    end
  end

  test "mount refinement M03 each old raw field and membership remains immutable" do
    good = ua_mi_literal()
    row = "22 1 0:6 / /contract/project rw - tmpfs tmpfs rw\n"
    fields = ["22", "1", "0:6", "/", "/contract/project", "rw", "-", "tmpfs", "tmpfs", "rw"]
    mutations = Enum.map([
      {0, "25"}, {1, "2"}, {2, "0:8"}, {3, "/other"}, {4, "/other"}, {5, "ro"},
      {7, "ext4"}, {8, "other"}, {9, "ro"}
    ], fn {index, value} -> Enum.join(List.replace_at(fields, index, value), " ") <> "\n" end)
    mutations = mutations ++ [
      String.replace(row, " - ", " shared:2 - "),
      String.replace(row, " rw - ", " rw,nosuid - "),
      String.replace(row, "/contract/project", "/contract/\\160roject")
    ]
    for changed <- mutations do
      fresh = ua_mi_literal()
      assert ua_mi_accept?(fresh, fresh)
      refute ua_mi_accept?(fresh, ua_mi_raw(fresh, ua_mount_literal() <> changed))
    end
    for raw <- [ua_mount_literal(), row, good.literal <> row, row <> ua_mount_literal()] do
      fresh = ua_mi_literal()
      assert ua_mi_accept?(fresh, fresh)
      refute ua_mi_accept?(fresh, ua_mi_raw(fresh, raw))
    end
  end

  test "mount refinement M03 semantically equal option and escape spellings are immutable" do
    for {old, changed} <- [
      {"22 1 0:6 / /ordinary rw,nosuid - tmpfs tmpfs rw\n",
       "22 1 0:6 / /ordinary nosuid,rw - tmpfs tmpfs rw\n"},
      {"22 1 0:6 / /ordinary/#name rw - tmpfs tmpfs rw\n",
       "22 1 0:6 / /ordinary/\\043name rw - tmpfs tmpfs rw\n"}
    ] do
      fresh = ua_mi_raw(ua_mi_literal(), ua_mount_literal() <> old)
      assert ua_mi_accept?(fresh, fresh)
      refute ua_mi_accept?(fresh, ua_mi_raw(fresh, ua_mount_literal() <> changed))
    end
  end

  test "mount refinement M04 two additive proposals commit only their final observation" do
    good = ua_mi_literal()
    a = good.literal <> ua_mi_added("/unrelated/a")
    b = a <> ua_mi_added("/unrelated/b", "24")
    state = ua_mi_state(good)
    first = ua_mi_checkpoint(state, {:sample, ua_mi_raw(good, a)})
    assert first.status == :open and first.pending == a and first.committed == good.literal
    second = ua_mi_checkpoint(first, {:sample, ua_mi_raw(good, b)})
    assert second.status == :open and second.pending == b and second.committed == good.literal
    committed = ua_mi_checkpoint(second, {:commit, ua_mi_guards()})
    assert committed.status == :committed and committed.committed == b and committed.pending == nil
    assert committed.seed == good.identity and committed.custody == good.custody
  end

  test "mount refinement M04 committed additions remain obligations in the next checkpoint" do
    good = ua_mi_literal()
    a = ua_mi_raw(good, good.literal <> ua_mi_added("/unrelated/a"))
    b = ua_mi_raw(good, a.literal <> ua_mi_added("/unrelated/b", "24"))
    first = ua_mi_state(good) |> ua_mi_checkpoint({:sample, a}) |>
      ua_mi_checkpoint({:commit, ua_mi_guards()})
    assert first.status == :committed and first.committed == a.literal
    next = ua_mi_checkpoint(first, :begin)
    assert next.status == :open and next.committed == a.literal
    second = next |> ua_mi_checkpoint({:sample, b}) |>
      ua_mi_checkpoint({:commit, ua_mi_guards()})
    assert second.status == :committed and second.committed == b.literal
    assert second.seed == good.identity
  end

  test "mount refinement M04 an added row becomes an immutable old obligation" do
    good = ua_mi_literal()
    a = ua_mi_added("/unrelated/a")
    b = ua_mi_added("/unrelated/b", "24")
    admitted = ua_mi_raw(good, good.literal <> a <> b)
    for raw <- [good.literal <> b,
      good.literal <> String.replace(a, " rw - ", " ro - ") <> b,
      good.literal <> b <> a] do
      fresh = ua_mi_raw(ua_mi_literal(), admitted.literal)
      assert ua_mi_accept?(fresh, fresh)
      failed = ua_mi_checkpoint(ua_mi_state(fresh), {:sample, ua_mi_raw(fresh, raw)})
      assert failed.status == :failed and failed.pending == nil
      assert failed.committed == fresh.literal and failed.seed == fresh.identity
      later = ua_mi_checkpoint(failed, {:sample, fresh})
      assert later == failed
    end
  end

  test "mount refinement M04 a pending addition cannot disappear before commit" do
    good = ua_mi_literal()
    changed = ua_mi_raw(good, good.literal <> ua_mi_added("/unrelated/a"))
    pending = ua_mi_checkpoint(ua_mi_state(good), {:sample, changed})
    assert pending.status == :open and pending.pending == changed.literal
    fresh = ua_mi_checkpoint(ua_mi_state(good), {:sample, changed})
    assert ua_mi_checkpoint(fresh, {:sample, changed}).status == :open
    failed = ua_mi_checkpoint(fresh, {:sample, good})
    assert failed.status == :failed and failed.pending == nil
    assert failed.committed == good.literal and failed.seed == good.identity
    assert ua_mi_checkpoint(failed, {:sample, changed}) == failed
  end

  test "mount refinement M05 component neighbours are disjoint" do
    [_, _, work, deps, _tmp, runtime] = ua_mi_routes().regions
    for point <- ["/ordinary", "/proc-other", "/nix/store-other",
      work <> "-other", deps <> "-other", runtime <> "-other"] do
      good = ua_mi_literal()
      assert ua_mi_accept?(good, good)
      assert ua_mi_accept?(good, ua_mi_raw(good, good.literal <> ua_mi_added(point)))
    end
  end

  test "mount refinement M05 roots ancestors and future descendants stay protected" do
    routes = ua_mi_routes()
    [_, _, work, deps, tmp, runtime] = routes.regions
    points = Enum.uniq(Enum.flat_map(routes.regions, &ua_mi_components/1)) ++ [
      "/proc/5252/ns/mnt", "/proc/self/fdinfo/999", "/proc/4242/fdinfo/999",
      tmp <> "/singularity/integration/new/historical-build",
      runtime <> "/socket/new", runtime <> "/evidence/new", runtime <> "/pgdata/new",
      work <> "/new", deps <> "/new", "/nix/store/new", tmp <> "-other"
    ]
    for point <- points do
      good = ua_mi_literal()
      assert ua_mi_accept?(good, good)
      refute ua_mi_accept?(good, ua_mi_raw(good, good.literal <> ua_mi_added(point)))
    end
  end

  test "mount refinement M06 a decoded ordinary escaped space stays disjoint" do
    good = ua_mi_literal()
    assert ua_mi_accept?(good, good)
    assert ua_mi_accept?(good, ua_mi_raw(good, good.literal <> ua_mi_added("/unrelated/has\\040space")))
  end

  test "mount refinement M06 malformed spelling and decoded protected routes reject" do
    for point <- ["/unrelated/\\777", "/unrelated/\\04", "relative", "/unrelated//x",
      "/unrelated/", "/unrelated/./x", "/unrelated/../x", "/proc/has\\040space",
      "/unrelated/" <> <<0>>, "/unrelated/" <> String.duplicate("x", 4096)] do
      good = ua_mi_literal()
      assert ua_mi_accept?(good, good)
      refute ua_mi_accept?(good, ua_mi_raw(good, good.literal <> ua_mi_added(point)))
    end
  end

  test "mount refinement M07 exact aliases origins ancestors and temporary identity are required" do
    for mutate <- [
      fn c -> update_in(c, [:aliases, Access.at(0), :target_before], &(&1 <> "/other")) end,
      fn c -> update_in(c, [:aliases, Access.at(0), :target_after], &(&1 <> "/other")) end,
      fn c -> update_in(c, [:aliases, Access.at(1), :target_before], &(&1 <> "/other")) end,
      fn c -> update_in(c, [:aliases, Access.at(1), :resolved], &(&1 <> "/other")) end,
      fn c -> put_in(c, [:aliases, Access.at(0), :physical], {:regular, 254, 0, 999, 1000, 0o100600}) end,
      fn c -> put_in(c, [:aliases, Access.at(1), :link_after], {:symlink, 254, 0, 999, 1000, 0o120777}) end,
      fn c -> put_in(c, [:directories, Access.at(0), :before], {:symlink, 254, 0, 100, 1000, 0o120777}) end,
      fn c -> put_in(c, [:directories, Access.at(0), :after], {:directory, 254, 0, 999, 1000, 0o40700}) end,
      fn c -> put_in(c, [:origins, Access.at(0), :before_load], "/outside/beam") end,
      fn c -> put_in(c, [:origins, Access.at(1), :returned], "/outside/beam") end,
      fn c -> put_in(c, [:origins, Access.at(2), :before_read], "/outside/beam") end,
      fn c -> put_in(c, [:origins, Access.at(0), :steps],
        [:load, :origin_check, :returned_origin_check, :read]) end,
      fn c -> put_in(c, [:origins, Access.at(0), :steps],
        [:origin_check, :load, :read, :returned_origin_check]) end,
      fn c -> put_in(c, [:origins, Access.at(0), :object_after], {:regular, 254, 0, 999, 1000, 0o100600}) end,
      fn c -> %{c | tmpdir: "/other"} end,
      fn c -> %{c | system_tmpdir: "/other"} end,
      fn c -> %{c | resolved_tmp: "/other"} end,
      fn c -> %{c | launcher: "/other"} end
    ] do
      good = ua_mi_literal()
