    bounded = prefix <> String.duplicate("x", 16_384 - byte_size(prefix) - byte_size(suffix)) <> suffix
    control = ua_mi_raw(good, bounded)
    assert byte_size(bounded) == 16_384
    assert ua_mi_accept?(control, control)
    for raw <- [bounded <> "\n", String.trim_trailing(bounded, "\n"),
      good.literal <> "malformed unrelated\n", good.literal <> ua_mount_literal()] do
      fresh = ua_mi_raw(ua_mi_literal(), bounded)
