      refute ua_mi_accept?(fresh, ua_mi_raw(fresh, raw))
    end
    fresh = ua_mi_raw(ua_mi_literal(), bounded)
    assert ua_mi_accept?(fresh, fresh)
    refute ua_mi_accept?(fresh, %{fresh | numeric: good.literal})
  end

