  test "mount refinement M12 identical samples remain pending until all checkpoint guards pass" do
    good = ua_mi_literal()
    initial = ua_mi_state(good)
    first = ua_mi_checkpoint(initial, {:sample, good})
    second = ua_mi_checkpoint(first, {:sample, good})
    assert first.status == :open and second.status == :open
    assert second.pending == good.literal and second.committed == initial.committed
    committed = ua_mi_checkpoint(second, {:commit, ua_mi_guards()})
    assert committed.status == :committed and committed.pending == nil
    assert committed.committed == good.literal and committed.seed == initial.seed
    next = ua_mi_checkpoint(committed, :begin)
    assert next.status == :open and next.committed == good.literal and next.pending == nil
  end

  test "mount refinement M12 a late failed guard never advances committed state" do
    for guard <- ua_mi_guards() do
      good = ua_mi_literal()
      pending = ua_mi_checkpoint(ua_mi_state(good), {:sample, good})
      control = ua_mi_checkpoint(pending, {:commit, ua_mi_guards()})
      assert control.status == :committed
      failed = ua_mi_checkpoint(pending, {:commit, List.delete(ua_mi_guards(), guard)})
      assert failed.status == :failed and failed.pending == nil
      assert failed.committed == good.literal and failed.seed == good.identity
      assert ua_mi_checkpoint(failed, {:commit, ua_mi_guards()}) == failed
    end
  end

  test "mount refinement M12 a bad second sample abort or existing primary remains sticky" do
    for reason <- [:exception, :timeout, :abort] do
      good = ua_mi_literal()
      pending = ua_mi_checkpoint(ua_mi_state(good), {:sample, good})
      assert ua_mi_checkpoint(pending, {:commit, ua_mi_guards()}).status == :committed
      failed = ua_mi_checkpoint(pending, {:abort, reason})
      assert failed.status == :failed and failed.primary == reason and failed.pending == nil
      assert failed.committed == good.literal and failed.seed == good.identity
      assert ua_mi_checkpoint(failed, {:sample, good}) == failed
    end
    good = ua_mi_literal()
    pending = ua_mi_checkpoint(ua_mi_state(good), {:sample, good})
    assert ua_mi_checkpoint(pending, {:sample, good}).status == :open
    failed = ua_mi_checkpoint(pending, {:sample, %{good | numeric: "bad"}})
    assert failed.status == :failed and failed.committed == good.literal and failed.pending == nil
    assert failed.seed == good.identity and failed.primary == :sample
    good = ua_mi_literal()
    pending = ua_mi_checkpoint(ua_mi_state(good), {:sample, good})
    assert ua_mi_checkpoint(pending, {:commit, ua_mi_guards()}).status == :committed
    diagnostic = %{phase: :admit, kind: :throw, line: 6298}
    primary = %{pending | primary: diagnostic}
    failed = ua_mi_checkpoint(primary, {:commit, ua_mi_guards()})
    assert failed.status == :failed and failed.primary == diagnostic
    assert failed.committed == good.literal and failed.seed == good.identity and failed.pending == nil
  end

  test "mount refinement M12 additive pending state aborts without committing or replacing seed" do
