  test "mount refinement M12 every phase has applicable guards and descriptor lifetime" do
    for phase <- [:bootstrap, :admit, :post_loop, :restore],
        guard <- ua_mi_guards(phase) do
      good = if phase in [:bootstrap, :admit], do: ua_mi_boot_literal(), else: ua_mi_literal()
      pending = ua_mi_state(good, phase) |> ua_mi_checkpoint({:sample, good})
      control = ua_mi_literal_commit(pending, ua_mi_guards(phase))
      assert control.status == :committed and control.phase == phase
      assert control.descriptors == if(phase == :restore, do: :closed, else: :open)
      assert control.seed == good.identity and control.pending == nil
      failed = ua_mi_literal_commit(pending, List.delete(ua_mi_guards(phase), guard))
      assert failed.status == :failed and failed.pending == nil
      assert failed.committed == good.literal and failed.seed == good.identity
      assert ua_mi_literal_commit(failed, ua_mi_guards(phase)) == failed
    end
  end

  test "mount refinement M12 wrong phases and inapplicable credit cannot close descriptors" do
    for phase <- [:bootstrap, :admit, :post_loop, :restore],
        other <- [:bootstrap, :admit, :post_loop, :restore] -- [phase] do
      good = if phase in [:bootstrap, :admit], do: ua_mi_boot_literal(), else: ua_mi_literal()
      pending = ua_mi_state(good, phase) |> ua_mi_checkpoint({:sample, good})
      assert ua_mi_literal_commit(pending, ua_mi_guards(phase)).status == :committed
      failed = ua_mi_literal_commit(pending, ua_mi_guards(other))
      assert failed.status == :failed and failed.committed == good.literal
      assert failed.descriptors == :open and failed.pending == nil
    end
    for {phase, guard} <- [{:bootstrap, :port}, {:bootstrap, :sql}, {:bootstrap, :close},
      {:admit, :sql}, {:admit, :close}, {:post_loop, :close}, {:restore, :port}] do
      good = if phase in [:bootstrap, :admit], do: ua_mi_boot_literal(), else: ua_mi_literal()
      pending = ua_mi_state(good, phase) |> ua_mi_checkpoint({:sample, good})
      assert ua_mi_literal_commit(pending, ua_mi_guards(phase)).status == :committed
      failed = ua_mi_literal_commit(pending, ua_mi_guards(phase) ++ [guard])
      assert failed.status == :failed and failed.descriptors == :open
      assert failed.committed == good.literal and failed.pending == nil
    end
    for phase <- [:unknown, nil, :close] do
      good = ua_mi_literal()
      pending = ua_mi_state(good) |> ua_mi_checkpoint({:sample, good})
      assert ua_mi_checkpoint(pending, {:commit, ua_mi_guards(:post_loop)}).status == :committed
      failed = ua_mi_checkpoint(%{pending | phase: phase}, {:commit, ua_mi_guards(:post_loop)})
      assert failed.status == :failed and failed.committed == good.literal
    end
    for phase <- [:bootstrap, :admit, :post_loop, :restore] do
      good = if phase in [:bootstrap, :admit], do: ua_mi_boot_literal(), else: ua_mi_literal()
      pending = ua_mi_state(good, phase) |> ua_mi_checkpoint({:sample, good})
      assert ua_mi_literal_commit(pending, ua_mi_guards(phase)).status == :committed
      failed = ua_mi_literal_commit(%{pending | descriptors: :closed}, ua_mi_guards(phase))
      assert failed.status == :failed and failed.committed == good.literal
    end
  end


  test "mount refinement M12 admission samples precede complete two-live custody" do
    good = ua_mi_boot_literal()
    state = ua_mi_state(good, :admit)
    assert not Map.has_key?(good, :custody) and not Map.has_key?(good, :native_pid)
    assert not Map.has_key?(state.custody, :live) and not Map.has_key?(state.custody, :original)
    first = ua_mi_checkpoint(state, {:sample, good})
    second = ua_mi_checkpoint(first, {:sample, good})
    assert first.status == :open and second.status == :open
    assert second.pending == good.literal and second.committed == good.literal
    assert second.descriptors == :open and second.seed == good.identity
    assert ua_mi_literal_commit(second, ua_mi_guards(:admit)).status == :committed
    failed = ua_mi_checkpoint(second, {:commit, ua_mi_guards(:admit)})
    assert failed.status == :failed and failed.pending == nil and failed.descriptors == :open
    assert failed.committed == good.literal and failed.seed == good.identity
    for mutate <- [
      fn _full -> nil end,
      fn full -> Map.delete(full, :original) end,
      fn full -> put_in(full, [:original, :live], []) end,
      fn full -> put_in(full, [:original, :live], [hd(full.original.live)]) end,
      fn full -> put_in(full, [:original, :bound_after_two_live], false) end,
      fn full -> put_in(full, [:original, :port], :replacement_port) end,
      fn full -> put_in(full, [:original, :port_ref], :replacement_ref) end,
      fn full -> put_in(full, [:expected, :native_pid], "5253") end,
      fn full -> put_in(full, [:descriptors, Access.at(0), :number], 99) end
    ] do
      fresh = ua_mi_boot_literal()
      pending = ua_mi_state(fresh, :admit) |> ua_mi_checkpoint({:sample, fresh})
      full = ua_mi_literal().custody
      assert ua_mi_checkpoint(pending, {:commit, ua_mi_guards(:admit), full}).status == :committed
      failed = ua_mi_checkpoint(pending, {:commit, ua_mi_guards(:admit), mutate.(full)})
      assert failed.status == :failed and failed.committed == fresh.literal and failed.pending == nil
      assert failed.seed == fresh.identity and failed.descriptors == :open
      assert ua_mi_checkpoint(failed, {:commit, ua_mi_guards(:admit), full}) == failed
    end
  end

