  test "mount refinement M12 each phase preserves abort and first-primary rollback" do
    for phase <- [:bootstrap, :admit, :post_loop, :restore],
        reason <- [:exception, :timeout, :abort] do
      good = if phase in [:bootstrap, :admit], do: ua_mi_boot_literal(), else: ua_mi_literal()
      pending = ua_mi_state(good, phase) |> ua_mi_checkpoint({:sample, good})
