      assert failed.committed == good.literal and failed.seed == good.identity
      assert ua_mi_literal_commit(failed, ua_mi_guards(phase)) == failed
      fresh = ua_mi_state(good, phase) |> ua_mi_checkpoint({:sample, good})
      assert ua_mi_literal_commit(fresh, ua_mi_guards(phase)).status == :committed
      diagnostic = %{phase: :admit, kind: :throw, line: 6298}
      prior = %{fresh | primary: diagnostic}
      failed = ua_mi_checkpoint(prior, {:abort, reason})
      assert failed.primary == diagnostic and failed.pending == nil and failed.status == :failed
      assert failed.committed == good.literal and failed.seed == good.identity
      assert ua_mi_literal_commit(failed, ua_mi_guards(phase)) == failed
    end
  end

  test "mount refinement M10 full object UID and namespace mount remain immutable" do
    for mutate <- [
      fn s -> put_in(s, [:identity, :root, :uid], 1) end,
      fn s -> put_in(s, [:identity, :directory, :uid], 1001) end,
      fn s -> put_in(s, [:identity, :status, :uid], 1001) end,
      fn s -> update_in(s, [:identity, :pid_ns], fn {ns, _} -> {ns, "99"} end) end,
      fn s -> update_in(s, [:identity, :mount_ns], fn {ns, _} -> {ns, "99"} end) end
    ] do
      good = ua_mi_literal()
      assert ua_mi_accept?(good, good)
      refute ua_mi_accept?(good, mutate.(good))
    end
  end


  test "mount refinement M12 each native phase rejects missing guards after additive samples" do
    for phase <- [:admit, :post_loop, :restore], guard <- ua_mi_guards(phase) do
      good = if phase == :admit, do: ua_mi_boot_literal(), else: ua_mi_literal()
      added = ua_mi_raw(good, good.literal <> ua_mi_added("/unrelated/a"))
      pending = ua_mi_state(good, phase) |> ua_mi_checkpoint({:sample, added})
      assert pending.status == :open and pending.pending == added.literal
      assert pending.committed == good.literal and pending.seed == good.identity
      assert ua_mi_literal_commit(pending, ua_mi_guards(phase)).status == :committed
      failed = ua_mi_literal_commit(pending, List.delete(ua_mi_guards(phase), guard))
      assert failed.status == :failed and failed.pending == nil
      assert failed.committed == good.literal and failed.seed == good.identity
      assert failed.descriptors == :open
      assert ua_mi_literal_commit(failed, ua_mi_guards(phase)) == failed
    end
  end

  # TASK18_MOUNT_IDENTITY_REFINEMENT_RED_END

  # TASK18_PRIVATE_MOUNT_EVIDENCE_RED_BEGIN
  # Defined restrictive seams for D01-D15. The writer phase replaces these bodies;
  # tests and actual finalization must use these same functions.
  defp ua_pe_capture(state, seed, current, phase, fields, labels, deadline), do: ua_pe_impl_capture(state, seed, current, phase, fields, labels, deadline)
  defp ua_pe_encode(capsule, primary), do: ua_pe_red_return(ua_pe_impl_encode(capsule, primary))
  defp ua_pe_decode(bytes), do: ua_pe_impl_decode(bytes)
  defp ua_pe_write(binding, bytes, deadline, operation), do: ua_pe_impl_write(binding, bytes, deadline, operation)
  defp ua_pe_dispatch(state, primary, sink), do: ua_pe_impl_dispatch(state, primary, sink)
  defp ua_pe_transfer(value, primary, state), do: ua_pe_impl_transfer(value, primary, state)
  defp ua_pe_finish(result, sink, emit), do: ua_pe_impl_finish(result, sink, emit)
  defp ua_pe_public_line(status), do: ua_pe_impl_public_line(status)
  defp ua_pe_analyze(seed, current, regions), do: ua_pe_impl_analyze(seed, current, regions)
  defp ua_pe_relation(point, region), do: ua_pe_impl_relation(point, region)

  # These are synthetic input constructors and an independent byte oracle,
  # never a second implementation of the capsule, decoder or writer.
  defp ua_pe_pair do
    seed = ua_mount_literal() <> "31 1 0:7 / /synthetic\\040old rw - tmpfs none rw\n"
    %{status: :captured_once, seed: seed, current: ua_mount_literal(),
      phase: :admit, fields: [:mount], labels: [:removed], deadline: 1_000,
      attempted: false}
  end

  defp ua_pe_primary do
    %{phase: :admit, kind: :throw, line: 6298,
      seed_fields: [:mount], mount_delta: [:removed]}
  end

  defp ua_pe_armed, do: %{status: :armed_without_pair, attempted: false}

  defp ua_pe_oracle(pair) do
    seed_hash = :crypto.hash(:sha256, pair.seed)
    current_hash = :crypto.hash(:sha256, pair.current)
    <<"T18MOUNT", 1, 4, 4, 2, 6298::32, 128::16, 2::16,
      byte_size(pair.seed)::32, byte_size(pair.current)::32,
      seed_hash::binary-size(32), current_hash::binary-size(32),
      pair.seed::binary, pair.current::binary>>
  end

  defp ua_pe_positive_codec(pair) do
    encoded = ua_pe_encode(pair, ua_pe_primary())
    matches? = encoded == {:ok, ua_pe_oracle(pair)}
    assert matches?
    {:ok, bytes} = encoded
    decoded? = ua_pe_decode(bytes) == {:ok, Map.take(pair, [:seed, :current, :phase, :fields, :labels]) |> Map.put(:primary, ua_pe_primary())}
    assert decoded?
    bytes
  end

  defp ua_pe_positive_capture do
    pair = ua_pe_pair()
    captured = ua_pe_capture(ua_pe_armed(), pair.seed, pair.current, pair.phase,
      pair.fields, pair.labels, pair.deadline)
    exact? = captured == pair
    assert exact?
    captured
  end

  defp ua_pe_positive_dispatch do
    captured = ua_pe_positive_capture()
    primary = ua_pe_primary()
    key = {__MODULE__, :ua_pe_positive_dispatch_count}
    previous = Process.get(key)
    Process.put(key, 0)
    try do
      sink = fn actual, diagnostic ->
        exact? = actual == captured and diagnostic == primary
        assert exact?
        Process.put(key, Process.get(key) + 1)
        :stored
      end
      {attempted, status} = ua_pe_dispatch(captured, primary, sink)
      assert status == :stored and attempted.attempted
      assert Process.get(key) == 1
      {cached, cached_status} = ua_pe_dispatch(attempted, primary, sink)
      retained? = cached == attempted and cached_status == :stored
      assert retained? and Process.get(key) == 1
    after
      if previous == nil, do: Process.delete(key), else: Process.put(key, previous)
    end
  end

  # Fixed task-owned fixtures, registered by ROOT before any test execution.
  # No actual evidence directory is used; cleanup is a finite exact leaf list.
  defp ua_pe_fixture_root(id) when id in [:d05, :d06, :d07, :d08, :d09, :d10, :d11, :d15] do
    "/home/gao/Workspace/gsmlg-opt/Singularity/.trees/v0.2-phase-5-export-backup/.devenv/" <>
      "phase5-task18-ua-mount-delta-private-evidence1-red-fixture-" <> Atom.to_string(id)
  end

  defp ua_pe_fixture(id, fun) do
    root = ua_pe_fixture_root(id)
    assert File.lstat(root) == {:error, :enoent}
    assert File.mkdir(root) == :ok
    assert File.chmod(root, 0o700) == :ok
    key = {__MODULE__, :ua_pe_handles}
    previous = Process.get(key)
    Process.put(key, [])
    try do
      fun.(root)
    after
      # Emergency test cleanup gives no writer-close credit. Assertions inspect
      # the remaining handles before this safety cleanup on every completed case.
      Enum.each(Process.get(key, []), fn fd -> :file.close(fd) end)
      if previous == nil, do: Process.delete(key), else: Process.put(key, previous)
      for leaf <- ["control.bin", "subject.bin", "target.bin", "exclusive.bin"] do
        path = root <> "/" <> leaf
        case File.lstat(path) do
          {:ok, %{type: :directory}} -> assert File.rmdir(path) == :ok
          {:ok, _} -> assert File.rm(path) == :ok
          {:error, :enoent} -> :ok
        end
      end
      assert File.rmdir(root) == :ok
    end
  end

  defp ua_pe_identity(stat) do
    Map.take(stat, [:type, :major_device, :minor_device, :inode, :uid, :gid])
    |> Map.put(:mode, Bitwise.band(stat.mode, 0o7777))
  end

  defp ua_pe_binding(root, leaf) when leaf in ["control.bin", "subject.bin"] do
    # Literal fixture root only; ancestors are finite and never enumerated.
    paths = ["/", "/home", "/home/gao", "/home/gao/Workspace",
      "/home/gao/Workspace/gsmlg-opt", "/home/gao/Workspace/gsmlg-opt/Singularity",
      "/home/gao/Workspace/gsmlg-opt/Singularity/.trees",
      "/home/gao/Workspace/gsmlg-opt/Singularity/.trees/v0.2-phase-5-export-backup",
      "/home/gao/Workspace/gsmlg-opt/Singularity/.trees/v0.2-phase-5-export-backup/.devenv", root]
    route = Enum.map(paths, fn path ->
      {:ok, stat} = File.lstat(path, time: :posix)
      {path, ua_pe_identity(stat)}
    end)
    %{directory: root, path: root <> "/" <> leaf, route: route,
      parent: elem(List.last(route), 1)}
  end

  # Operation labels are the one shared low-level writer interface. The future
  # actual sink supplies this builtin adapter; tests only decorate its results.
  defp ua_pe_builtin(:now, []), do: System.monotonic_time(:millisecond)
  defp ua_pe_builtin(step, [path]) when step in
      [:route_before, :parent_named, :route_held, :leaf_named_empty,
       :parent_prewrite, :route_prewrite, :leaf_named_written,
       :parent_postwrite, :leaf_named_final, :parent_final, :route_final],
      do: File.lstat(path, time: :posix)
  defp ua_pe_builtin(step, [path]) when step in [:parent_open, :leaf_open] do
    modes = if step == :parent_open,
      do: [:read, :raw, :binary, :directory],
      else: [:read, :write, :raw, :binary, :exclusive]
    :file.open(String.to_charlist(path), modes)
  end
  defp ua_pe_builtin(step, [fd]) when step in
      [:parent_fd, :leaf_fd_empty, :parent_fd_prewrite, :leaf_fd_written,
       :leaf_fd_preread, :leaf_fd_postread, :parent_fd_final] do
    case :file.read_file_info(fd, time: :posix) do
      {:ok, record} -> {:ok, File.Stat.from_record(record)}
      error -> error
    end
  end
  defp ua_pe_builtin(:write, [fd, bytes]), do: :file.write(fd, bytes)
  defp ua_pe_builtin(:position, [fd]), do: :file.position(fd, :cur)
  defp ua_pe_builtin(:readback, [fd, size]), do: :file.pread(fd, 0, size)
  defp ua_pe_builtin(step, [fd]) when step in [:leaf_close, :parent_close],
    do: :file.close(fd)

  defp ua_pe_recording(inject) do
    key = {__MODULE__, :ua_pe_calls}
    Process.put(key, [])
    fn step, args ->
      calls = Process.get(key)
      Process.put(key, calls ++ [step])
      base = fn ->
        result = if step == :now, do: 999, else: ua_pe_builtin(step, args)
        handles = {__MODULE__, :ua_pe_handles}
        case {step, args, result} do
          {open, _, {:ok, fd}} when open in [:parent_open, :leaf_open] ->
            Process.put(handles, [fd | Process.get(handles, [])])
          {close, [fd], :ok} when close in [:leaf_close, :parent_close] ->
            Process.put(handles, List.delete(Process.get(handles, []), fd))
          _ -> :ok
        end
        result
      end
      inject.(step, args, base, length(calls) + 1)
    end
  end

  defp ua_pe_calls, do: Process.get({__MODULE__, :ua_pe_calls}, [])
  defp ua_pe_passthrough(_step, _args, base, _ordinal), do: base.()

  defp ua_pe_run(binding, injection, deadline \\ 1_000) do
    bytes = ua_pe_oracle(ua_pe_pair())
    operation = ua_pe_recording(injection)
    status = ua_pe_write(binding, bytes, deadline, operation)
    {status, ua_pe_calls()}
  end

  defp ua_pe_control(root) do
    binding = ua_pe_binding(root, "control.bin")
    assert File.lstat(binding.path) == {:error, :enoent}
    {status, calls} = ua_pe_run(binding, &ua_pe_passthrough/4)
    assert status == :stored
    {:ok, stat} = File.lstat(binding.path, time: :posix)
    private? = stat.type == :regular and stat.uid == 1000 and stat.links == 1 and
      Bitwise.band(stat.mode, 0o7777) == 0o600 and stat.size == byte_size(ua_pe_oracle(ua_pe_pair()))
    assert private?
    {:ok, bytes} = File.read(binding.path)
    exact? = bytes == ua_pe_oracle(ua_pe_pair())
    assert exact?
    assert Enum.count(calls, &(&1 == :parent_open)) == 1
    assert Enum.count(calls, &(&1 == :leaf_open)) == 1
    assert Enum.count(calls, &(&1 == :write)) == 1
    assert Enum.count(calls, &(&1 == :readback)) == 1
    steps = calls |> Enum.reject(&(&1 == :now)) |> Enum.dedup()
    assert steps == [:route_before, :parent_open, :parent_fd, :parent_named,
      :route_held, :leaf_open, :leaf_fd_empty, :leaf_named_empty,
      :parent_prewrite, :parent_fd_prewrite, :route_prewrite, :write, :position,
      :leaf_fd_written, :leaf_named_written, :parent_postwrite,
      :leaf_fd_preread, :readback, :leaf_fd_postread, :leaf_close,
      :leaf_named_final, :parent_final, :parent_fd_final, :route_final, :parent_close]
    assert Enum.count(calls, &(&1 == :leaf_close)) == 1
    assert Enum.count(calls, &(&1 == :parent_close)) == 1
    assert Process.get({__MODULE__, :ua_pe_handles}) == []
    assert File.rm(binding.path) == :ok
    calls
  end

  defp ua_pe_closed(calls) do
    assert Enum.count(calls, &(&1 == :parent_close)) == Enum.count(calls, &(&1 == :parent_open))
    assert Enum.count(calls, &(&1 == :leaf_close)) <= 1
    assert Enum.count(calls, &(&1 == :write)) <= 1
    assert Process.get({__MODULE__, :ua_pe_handles}) == []
  end

  defp ua_pe_remove_subject(root) do
    case File.lstat(root <> "/subject.bin") do
      {:ok, %{type: :directory}} -> assert File.rmdir(root <> "/subject.bin") == :ok
      {:ok, _} -> assert File.rm(root <> "/subject.bin") == :ok
      {:error, :enoent} -> :ok
    end
  end

  describe "private mount evidence diagnostic contracts D01-D15" do
    test "D01 unarmed minimal maps retain existing finite mismatch diagnostics without IO" do
      key = {__MODULE__, :ua_control}
      previous = Process.get(key)
      seed = Map.new(ua_control_seed_fields(), &{&1, :unchanged}) |> Map.put(:mount, ua_mount_literal())
      try do
        Process.put(key, %{diagnostic: nil, diagnostic_phase: :admit})
        assert ua_control_seed_mismatch(%{seed | mount: :changed}, seed) == :ok
        control = Process.get(key)
        assert control.seed_mismatch == [:mount] and control.mount_delta == [:invalid]
        op = ua_pe_recording(&ua_pe_passthrough/4)
        state = ua_pe_capture(nil, seed.mount, :changed, :admit, [:mount], [:invalid], nil)
        assert state == nil
        {nil, status} = ua_pe_dispatch(state, ua_pe_primary(), fn _, _ ->
          op.(:unexpected_dispatch, [])
        end)
        assert status == :not_captured and ua_pe_calls() == []
        assert ua_control_seed_suffix(%{seed_fields: [:mount], mount_delta: [:invalid]}) ==
          " seed_fields=mount mount_delta=invalid"
      after
        if previous == nil, do: Process.delete(key), else: Process.put(key, previous)
      end
    end

    test "D02 first exact capsule phase deadline and primary are sticky with once-only dispatch" do
      pair = ua_pe_pair()
      first = ua_pe_capture(ua_pe_armed(), pair.seed, pair.current, :admit, [:mount], [:removed], pair.deadline)
      exact? = first == pair
      assert exact?
      for {seed, current, phase, fields, labels, deadline} <- [
        {pair.current, pair.seed, :restore, [:mount], [:added], 2_000},
        {:changed, nil, :close, [:root], [], nil}
      ] do
        control = ua_pe_capture(ua_pe_armed(), pair.seed, pair.current, :admit, [:mount], [:removed], 1_000)
        matches? = control == pair
        assert matches?
        unchanged? = ua_pe_capture(control, seed, current, phase, fields, labels, deadline) == control
        assert unchanged?
      end
      key = {__MODULE__, :ua_pe_dispatch_count}
      Process.put(key, 0)
      sink = fn actual, primary ->
        matches? = actual == pair and primary == ua_pe_primary()
        assert matches?
        Process.put(key, Process.get(key) + 1)
        :stored
      end
      {attempted, status} = ua_pe_dispatch(first, ua_pe_primary(), sink)
      assert status == :stored and attempted.attempted
      {later, later_status} = ua_pe_dispatch(attempted, %{phase: :close, kind: :error, line: 0}, sink)
      retained? = later == attempted and later_status == :stored
      assert retained?
      assert Process.get(key) == 1
      Process.delete(key)
    end

    test "D03 malformed first operands non-mount mismatch and wrong primary never authorize IO" do
      pair = ua_pe_pair()
      for bad <- ["", String.duplicate("x", 16_385), nil, :changed, [], 1],
          side <- [:seed, :current] do
        ua_pe_positive_codec(ua_pe_pair())
        ua_pe_positive_capture()
        input = Map.put(pair, side, bad)
        state = ua_pe_capture(ua_pe_armed(), input.seed, input.current, :admit, [:mount], [:removed], 1_000)
        assert state.status == :invalid_input
        assert ua_pe_capture(state, pair.seed, pair.current, :admit, [:mount], [:removed], 1_000) == state
        op = ua_pe_recording(&ua_pe_passthrough/4)
        {_state, status} = ua_pe_dispatch(state, ua_pe_primary(), fn _, _ -> op.(:unexpected_dispatch, []) end)
        assert status == :invalid_input and ua_pe_calls() == []
      end
      ua_pe_positive_codec(ua_pe_pair())
      ua_pe_positive_capture()
      no_mount = ua_pe_capture(ua_pe_armed(), pair.seed, pair.seed, :admit, [:root], [], 1_000)
      assert no_mount.status == :no_mount_pair
      unchanged? = ua_pe_capture(no_mount, pair.seed, pair.current, :admit, [:mount], [:removed], 1_000) == no_mount
      assert unchanged?
      op = ua_pe_recording(&ua_pe_passthrough/4)
      {_state, status} = ua_pe_dispatch(no_mount, ua_pe_primary(), fn _, _ -> op.(:unexpected_dispatch, []) end)
      assert status == :not_captured and ua_pe_calls() == []
      for bad <- [nil, %{ua_pe_primary() | line: 6297}, %{ua_pe_primary() | phase: :restore},
        %{ua_pe_primary() | kind: :error}, %{ua_pe_primary() | seed_fields: [:root]}] do
        ua_pe_positive_codec(ua_pe_pair())
        ua_pe_positive_dispatch()
        fresh = ua_pe_positive_capture()
        op = ua_pe_recording(&ua_pe_passthrough/4)
        {_state, status} = ua_pe_dispatch(fresh, bad, fn _, _ -> op.(:unexpected_dispatch, []) end)
        assert status == :primary_mismatch and ua_pe_calls() == []
      end
    end

    test "D04 exact bounded binary envelope rejects every header and payload corruption" do
      pair = ua_pe_pair()
      for input <- [pair, %{pair | seed: <<0>>, current: <<255>>},
        %{pair | seed: String.duplicate("s", 16_384), current: String.duplicate("c", 16_384)}] do
        bytes = ua_pe_positive_codec(input)
        assert byte_size(bytes) == 92 + byte_size(input.seed) + byte_size(input.current)
        assert byte_size(bytes) <= 32_860
      end
      for {offset, replacement} <- [{0, <<0>>}, {8, <<2>>}, {9, <<0>>}, {9, <<8>>},
        {10, <<0>>}, {10, <<8>>}, {10, <<5>>}, {11, <<0>>}, {11, <<5>>}, {12, <<0::32>>},
        {16, <<0::16>>}, {16, <<32768::16>>}, {18, <<32768::16>>},
        {20, <<0::32>>}, {20, <<16385::32>>}, {24, <<0::32>>}, {24, <<16385::32>>},
        {28, <<0::256>>}, {60, <<0::256>>}] do
        bytes = ua_pe_positive_codec(ua_pe_pair())
        tail_at = offset + byte_size(replacement)
        mutant = binary_part(bytes, 0, offset) <> replacement <>
          binary_part(bytes, tail_at, byte_size(bytes) - tail_at)
        rejected? = ua_pe_decode(mutant) == {:error, :invalid_input}
        assert rejected?
      end
      for {field, value} <- [phase: :unknown, fields: [], fields: [:root],
        fields: [:mount, :unknown], labels: [:unknown], labels: [:removed, :removed]] do
        ua_pe_positive_codec(ua_pe_pair())
        rejected? = ua_pe_encode(Map.put(pair, field, value), ua_pe_primary()) == {:error, :invalid_input}
        assert rejected?
      end
      for mutation <- [:trailing, :short, :swapped] do
        bytes = ua_pe_positive_codec(ua_pe_pair())
        mutant = case mutation do
          :trailing -> bytes <> <<0>>
          :short -> binary_part(bytes, 0, byte_size(bytes) - 1)
          :swapped -> binary_part(bytes, 0, 92) <> pair.current <> pair.seed
        end
        rejected? = ua_pe_decode(mutant) == {:error, :invalid_input}
        assert rejected?
      end
    end

    test "D05 real private exclusive writer proves bytes metadata one write readback and both closes" do
      ua_pe_fixture(:d05, fn root -> ua_pe_control(root) end)
    end

    test "D06 existing regular symlink hardlink and directory leaves are never changed" do
      ua_pe_fixture(:d06, fn root ->
        for kind <- [:regular, :symlink, :hardlink, :directory] do
          ua_pe_control(root)
          path = root <> "/subject.bin"
          target = root <> "/target.bin"
          assert File.write(target, "SYNTHETIC_TARGET", [:exclusive]) == :ok
          case kind do
            :regular -> assert File.write(path, "SYNTHETIC_EXISTING", [:exclusive]) == :ok
            :symlink -> assert File.ln_s(target, path) == :ok
            :hardlink -> assert File.ln(target, path) == :ok
            :directory -> assert File.mkdir(path) == :ok
          end
          before = File.lstat(path, time: :posix)
          target_before = File.lstat(target, time: :posix)
          {status, calls} = ua_pe_run(ua_pe_binding(root, "subject.bin"), &ua_pe_passthrough/4)
          assert status == :open_failed
          assert :write not in calls and :readback not in calls
          unchanged? = File.lstat(path, time: :posix) == before and
            File.lstat(target, time: :posix) == target_before and File.read(target) == {:ok, "SYNTHETIC_TARGET"}
          assert unchanged?
          if kind == :regular do
            unchanged? = File.read(path) == {:ok, "SYNTHETIC_EXISTING"}
            assert unchanged?
          end
          if kind == :symlink, do: assert(File.read_link(path) == {:ok, target})
          ua_pe_closed(calls)
          ua_pe_remove_subject(root)
          assert File.rm(target) == :ok
        end
      end)
    end

    test "D07 binding and observed ancestor parent or held identity substitutions fail before payload" do
      ua_pe_fixture(:d07, fn root ->
