        end
        for step <- [:route_before, :parent_named, :parent_fd, :route_held, :parent_prewrite, :parent_fd_prewrite, :route_prewrite],
            {field, value} <- [type: :symlink, type: :regular, mode: 0o40777, uid: 1001, inode: 0] do
          ua_pe_control(root)
          inject = fn label, _args, base, _n ->
            case base.() do
              {:ok, %File.Stat{} = stat} when label == step -> {:ok, Map.put(stat, field, value)}
              result -> result
            end
          end
          {status, calls} = ua_pe_run(ua_pe_binding(root, "subject.bin"), inject)
          assert status == :parent_rejected and :write not in calls
          ua_pe_closed(calls)
          ua_pe_remove_subject(root)
        end
      end)
    end

