    test "D09 write errors short success and corrupt readback retain unqualified partial output" do
      ua_pe_fixture(:d09, fn root ->
        for {fault, expected} <- [write_error: :write_failed, short_write: :length_failed,
          short_read: :readback_failed, different_read: :readback_failed] do
          ua_pe_control(root)
          inject = fn step, args, base, _n ->
            case {fault, step, args} do
              {:write_error, :write, _} -> {:error, :enospc}
              {:short_write, :write, [fd, bytes]} -> :file.write(fd, binary_part(bytes, 0, 1))
              {:short_read, :readback, _} -> {:ok, <<0>>}
              {:different_read, :readback, [_fd, size]} -> {:ok, :binary.copy(<<0>>, size)}
