          {status, calls} = ua_pe_run(ua_pe_binding(root, "subject.bin"), inject)
          assert status == expected and Enum.count(calls, &(&1 == :write)) == 1
          {:ok, stat} = File.lstat(root <> "/subject.bin")
          expected_size = case fault do
            :write_error -> 0
            :short_write -> 1
            _ -> byte_size(ua_pe_oracle(ua_pe_pair()))
          end
          assert stat.size == expected_size
          assert Enum.count(calls, &(&1 == :leaf_close)) == 1
