    test "D10 close errors and every owned-handle phase exception keep the primary and close once" do
      ua_pe_fixture(:d10, fn root ->
        for failing_close <- [:leaf_close, :parent_close, :both],
            first_failure <- [:none, :write_failed] do
          ua_pe_control(root)
          inject = fn step, _args, base, _n ->
            cond do
              step == :write and first_failure == :write_failed -> {:error, :enospc}
              step in [:leaf_close, :parent_close] and (failing_close == :both or step == failing_close) ->
                assert base.() == :ok
                {:error, :synthetic_close_failure}
              true -> base.()
            end
          end
          {status, calls} = ua_pe_run(ua_pe_binding(root, "subject.bin"), inject)
          assert status == :close_failed
          assert Enum.count(calls, &(&1 == :leaf_close)) == 1
          ua_pe_closed(calls)
          ua_pe_remove_subject(root)
        end
        control_calls = ua_pe_control(root)
        owned_start = Enum.find_index(control_calls, &(&1 == :parent_open))
        targets = control_calls |> Enum.with_index(1) |> Enum.filter(fn {step, n} ->
          n > owned_start + 1 and step != :now
        end)
        assert targets != []
        for {target, ordinal} <- targets, kind <- [:error, :throw, :exit] do
          ua_pe_control(root)
          inject = fn step, _args, base, n ->
            if n == ordinal do
              if step in [:leaf_close, :parent_close], do: assert(base.() == :ok)
              case kind do
                :error -> :erlang.error({:synthetic, "PRIVATE_CANARY_ERROR"})
                :throw -> throw({:synthetic, "PRIVATE_CANARY_THROW"})
                :exit -> exit({:synthetic, "PRIVATE_CANARY_EXIT"})
              end
            else
              base.()
            end
          end
          output = ExUnit.CaptureIO.capture_io(fn ->
            {status, calls} = ua_pe_run(ua_pe_binding(root, "subject.bin"), inject)
            expected = if target in [:leaf_close, :parent_close], do: :close_failed, else: :unexpected_exception
            assert status == expected
            ua_pe_closed(calls)
            primary = ua_pe_primary()
            result = ua_pe_finish({false, primary, ua_pe_pair()}, fn _, _ -> status end, fn _ -> :ok end)
            assert result == {false, primary}
          end)
          private? = not String.contains?(output, "PRIVATE_CANARY") and not String.contains?(output, root)
          assert private?
          ua_pe_remove_subject(root)
        end
      end)
    end

    test "D11 missing expired and expiry at each finite operation allow only owned closes" do
      ua_pe_fixture(:d11, fn root ->
        for {deadline, expected} <- [{nil, :deadline_unavailable}, {999, :deadline_expired}] do
          ua_pe_control(root)
          {status, calls} = ua_pe_run(ua_pe_binding(root, "subject.bin"), &ua_pe_passthrough/4, deadline)
          assert status == expected and Enum.all?(calls, &(&1 == :now))
          assert File.lstat(root <> "/subject.bin") == {:error, :enoent}
        end
        baseline = ua_pe_control(root)
        targets = baseline |> Enum.with_index(1) |> Enum.reject(fn {step, _} -> step == :now end)
        for {_target, ordinal} <- targets do
          ua_pe_control(root)
          key = {__MODULE__, :ua_pe_expired}
          Process.put(key, false)
          inject = fn step, _args, base, n ->
            cond do
              step == :now -> if Process.get(key), do: 1_000, else: 999
              true ->
                result = base.()
                if n == ordinal, do: Process.put(key, true)
                result
            end
          end
          {status, calls} = ua_pe_run(ua_pe_binding(root, "subject.bin"), inject)
          assert status == :deadline_expired
          assert Enum.all?(Enum.drop(calls, ordinal), &(&1 in [:now, :leaf_close, :parent_close]))
          ua_pe_closed(calls)
          Process.delete(key)
          ua_pe_remove_subject(root)
        end
      end)
    end

    test "D12 shared transfer and finalizer retain all result paths with cleanup before sink before raise" do
      for path <- [:normal, :rescue, :catch] do
        key = {__MODULE__, :ua_pe_order}
        Process.put(key, [])
        mark = fn event -> Process.put(key, Process.get(key) ++ [event]) end
        primary = ua_pe_primary()
        pair = ua_pe_pair()
        result = try do
          case path do
            :normal -> ua_pe_transfer(false, primary, pair)
            :rescue -> raise "SYNTHETIC_FAILURE"
            :catch -> throw(:synthetic)
          end
        rescue
          _ -> ua_pe_transfer(false, primary, pair)
        catch
          _, _ -> ua_pe_transfer(false, primary, pair)
        after
          mark.(:original_cleanup)
        end
        transferred? = result == {false, primary, pair}
        assert transferred?
        final = ua_pe_finish(result, fn actual, diagnostic ->
          mark.(:sink)
          exact? = actual == pair and diagnostic == primary
          assert exact?
          :stored
        end, fn status -> assert status == :stored; mark.(:status) end)
        assert final == {false, primary}
        try do
          case final do
            {false, diagnostic} -> mark.(:original_raise); throw(diagnostic)
          end
        catch
          :throw, diagnostic -> assert diagnostic == primary
        end
        assert Process.get(key) == [:original_cleanup, :sink, :status, :original_raise]
        Process.delete(key)
      end
    end

    test "D13 output accepts only finite status enums and never reveals synthetic rows paths or exceptions" do
      statuses = [:stored, :not_captured, :invalid_input, :primary_mismatch,
        :deadline_unavailable, :deadline_expired, :parent_rejected, :open_failed,
        :file_rejected, :write_failed, :length_failed, :readback_failed,
        :close_failed, :unexpected_exception]
      for status <- statuses do
        line = ua_pe_public_line(status)
        assert line == "TASK18_UA_PRIVATE_MOUNT_CAPTURE status=" <> Atom.to_string(status) <> "\n"
      end
      for canary <- ["PRIVATE_CANARY_ROW /synthetic/path", {:error, "PRIVATE_CANARY_REASON"}, [:stored], nil] do
        assert ua_pe_public_line(:stored) == "TASK18_UA_PRIVATE_MOUNT_CAPTURE status=stored\n"
        line = ua_pe_public_line(canary)
        finite? = line == "TASK18_UA_PRIVATE_MOUNT_CAPTURE status=unexpected_exception\n"
        assert finite?
        diagnostic = Map.put(ua_pe_primary(), :raw, canary)
        suffix = ua_control_seed_suffix(diagnostic)
        assert suffix == " seed_fields=mount mount_delta=removed"
        for failure <- [:sink_error, :sink_throw, :sink_exit, :emit_error, :emit_throw, :emit_exit] do
          key = {__MODULE__, :ua_pe_public_control}
          Process.put(key, [])
          control = ua_pe_finish({false, diagnostic, ua_pe_pair()},
            fn _, _ -> Process.put(key, [:sink]); :stored end,
            fn status -> Process.put(key, Process.get(key) ++ [status]) end)
          retained? = control == {false, diagnostic}
          assert retained? and Process.get(key) == [:sink, :stored]
          Process.delete(key)
          sink = fn _, _ ->
            case failure do
              :sink_error -> :erlang.error(canary)
              :sink_throw -> throw(canary)
              :sink_exit -> exit(canary)
              _ -> :stored
            end
          end
          emit = fn _ ->
            case failure do
              :emit_error -> :erlang.error(canary)
              :emit_throw -> throw(canary)
              :emit_exit -> exit(canary)
              _ -> :ok
            end
          end
          output = ExUnit.CaptureIO.capture_io(fn ->
            retained? = ua_pe_finish({false, diagnostic, ua_pe_pair()}, sink, emit) == {false, diagnostic}
            assert retained?
          end)
          assert output == ""
        end
      end
    end

    test "D14 complete offline delta retains every removed row and all six component relations" do
      regions = %{:proc => "/proc", :store => "/nix/store",
        :"W" => "/home/gao/Workspace/gsmlg-opt/Singularity/.trees/v0.2-phase-5-export-backup",
        :"D" => "/home/gao/Workspace/gsmlg-opt/Singularity/deps",
        :"T" => "/dev/shm/singularity-t16.R2tasM/tmp", :"R" => "/dev/shm/singularity-t16.R2tasM"}
      protected = "31 1 0:7 / /proc/old rw - tmpfs none rw"
      disjoint = "32 1 0:7 / /synthetic/unrelated rw - tmpfs none rw"
      seed = ua_mount_literal() <> protected <> "\n" <> disjoint <> "\n"
      current = ua_mount_literal()
      result = ua_pe_analyze(seed, current, regions)
      expected_rows = [%{id: "31", raw: protected, relations: %{:proc => :descendant, :store => :disjoint, :"W" => :disjoint, :"D" => :disjoint, :"T" => :disjoint, :"R" => :disjoint}},
        %{id: "32", raw: disjoint, relations: Map.new(regions, fn {name, _} -> {name, :disjoint} end)}]
      complete? = result == {:ok, %{removed: expected_rows, labels: [:removed], acceptance: :rejected}}
      assert complete?
      for {_name, region} <- regions do
        for {point, relation} <- [{region, :equal}, {"/", :ancestor},
          {region <> "/child", :descendant}, {region <> "-neighbour", :disjoint}] do
          assert ua_pe_relation(region, region) == {:ok, :equal}
          assert ua_pe_relation(point, region) == {:ok, relation}
        end
        for invalid <- ["relative", "//proc", "/proc/../other", "/proc/./child", "/proc/", <<0>>] do
          assert ua_pe_relation(region, region) == {:ok, :equal}
          assert ua_pe_relation(invalid, region) == {:error, :invalid_input}
        end
      end
      for {mutant, labels} <- [
        {current <> "40 1 0:9 / /new rw - tmpfs none rw\n", [:added, :removed]},
        {String.replace(current, "rw,nosuid", "ro,nosuid"), [:removed, :options]}
      ] do
        control? = ua_pe_analyze(seed, current, regions) == result
        assert control?
        {:ok, changed} = ua_pe_analyze(seed, mutant, regions)
        exact? = changed.removed == expected_rows and changed.labels == labels and changed.acceptance == :rejected
        assert exact?
      end
      for field <- [:parent, :device, :root, :point, :options, :optional, :type, :source, :super_options] do
        control? = ua_pe_analyze(seed, current, regions) == result
        assert control?
        replacements = %{parent: {"21 1 ", "21 2 "}, device: {"0:5", "0:6"},
          root: {" / /proc ", " /root /proc "}, point: {" /proc ", " /proc/new "},
          options: {"rw,nosuid", "ro,nosuid"}, optional: {" - proc", " shared:1 - proc"},
          type: {" - proc ", " - tmpfs "}, source: {"proc proc rw", "proc none rw"},
          super_options: {"proc proc rw", "proc proc ro"}}
        {from, to} = Map.fetch!(replacements, field)
        {:ok, changed} = ua_pe_analyze(seed, String.replace(current, from, to), regions)
        matches? = changed.removed == expected_rows and changed.labels == [:removed, field]
        assert matches?
      end
      for invalid <- ["", :changed, current <> current,
        String.replace(current, "/proc", "/proc/../other"),
        String.replace(current, "/proc", "/bad\\999")] do
        control? = ua_pe_analyze(seed, current, regions) == result
        assert control?
        assert ua_pe_analyze(seed, invalid, regions) == {:error, :invalid_input}
      end
      common = current <> "40 1 0:9 / /new rw - tmpfs none rw\n"
      control? = match?({:ok, %{removed: [], labels: [], acceptance: :unchanged}}, ua_pe_analyze(common, common, regions))
      assert control?
      {:ok, reordered} = ua_pe_analyze(common, "40 1 0:9 / /new rw - tmpfs none rw\n" <> current, regions)
      assert reordered.removed == [] and reordered.labels == [:order]
    end

    # Independent test: no positive capture/codec/writer assertion precedes D15.
    # Holding the first FD while opening the same path is the narrow contention
    # contract; this does not establish arbitrary concurrent-race guarantees.
    test "D15 same-worktree zero-payload exclusive-create prerequisite executes independently" do
      ua_pe_fixture(:d15, fn root ->
        path = root <> "/exclusive.bin"
        {:ok, parent} = File.lstat(root, time: :posix)
        {:ok, devenv} = File.lstat(Path.dirname(root), time: :posix)
        assert {parent.major_device, parent.minor_device} == {devenv.major_device, devenv.minor_device}
        assert parent.type == :directory and parent.uid == 1000 and Bitwise.band(parent.mode, 0o7777) == 0o700
        modes = [:read, :write, :raw, :binary, :exclusive]
        {:ok, first} = :file.open(String.to_charlist(path), modes)
        try do
          {:ok, record} = :file.read_file_info(first, time: :posix)
          descriptor = File.Stat.from_record(record)
          {:ok, named} = File.lstat(path, time: :posix)
          assert ua_pe_identity(descriptor) == ua_pe_identity(named)
          assert named.type == :regular and named.uid == 1000 and named.links == 1 and named.size == 0
          assert Bitwise.band(named.mode, 0o7777) == 0o600
          second = :file.open(String.to_charlist(path), modes)
          case second do
            {:ok, unexpected} -> assert :file.close(unexpected) == :ok
            _ -> :ok
          end
          assert second == {:error, :eexist}
          {:ok, after_named} = File.lstat(path, time: :posix)
          assert ua_pe_identity(after_named) == ua_pe_identity(named) and after_named.size == 0
          assert :file.pread(first, 0, 1) == :eof
        after
          assert :file.close(first) == :ok
        end
        assert File.read(path) == {:ok, ""}
      end)
    end
  end
  # TASK18_PRIVATE_MOUNT_EVIDENCE_RED_END
  # TASK18_INVENTORY_REJECTION_REPAIR1_BEGIN
  defp ua_pe_red_return(value) do
    invoke = fn -> value end
    invoke.()
  end

  defp transport_inventory_rejection_classify(result, context, expected), do: transport_ir_classify(result, context, expected)
  defp transport_inventory_rejection_observe(value, result, context, expected), do: transport_ir_observe(value, result, context, expected)
  defp transport_inventory_rejection_get(key), do: transport_ir_get(key)
  defp transport_inventory_rejection_clear(key), do: transport_ir_clear(key)

  defp transport_ir_fixture(columns) do
    worker = %{pid: 144, datid: 2_562_145, usesysid: nil,
      backend_type: "autovacuum worker", backend_start_us: 123}
    expected = %{observer: self(), key: make_ref(), operation: make_ref(), nonce: make_ref(),
      ordinary: self(), admin: {self(), make_ref()}, custodian: {self(), make_ref()},
      database: "synthetic_database", database_oid: 2_562_145,
      stage: if(columns == 2, do: :baseline, else: :gate), columns: columns,
      baseline: [{101, "synthetic_role"}], child_pid: if(columns == 2, do: nil, else: 143)}
    rows = if columns == 2, do: [[101, "synthetic_role"], [144, nil]],
      else: [[101, "synthetic_role", nil], [144, nil, nil]]
    context = Map.merge(expected, %{authority: :verified, capture: :complete, sequence: 1,
      before_ns: 100, query_before_ns: 101, query_after_ns: 102, after_ns: 103,
      before: [worker], after: [worker]})
    {{:ok, %Postgrex.Result{rows: rows}}, context, expected}
  end

  defp transport_ir_finite?(value) do
    case value do
      %{stage: stage, reason: reason, row_mask: mask} when map_size(value) == 3 ->
        stage in [:baseline, :gate, :absence, :unknown] and
          reason in [:input_shape, :binding, :context_binding, :capture, :sequence,
            :clock, :row_limit, :before_metadata, :after_metadata, :duplicate, :row,
            :accepted, :unavailable] and is_integer(mask) and mask in 0..16_383 and
          (reason == :row or mask == 0)
      _ -> false
    end
  end

  defp transport_ir_slot(key, fun) do
    slot = {key, :inventory_rejection}
    absent = make_ref()
    previous = Process.get(slot, absent)
    try do
      fun.()
    after
      if previous === absent, do: Process.delete(slot), else: Process.put(slot, previous)
    end
  end

  defp transport_ir_positive!(columns) do
    {result, context, expected} = triple = transport_ir_fixture(columns)
    literal = {:ok, {[{101, "synthetic_role"}], [%{pid: 144, datid: 2_562_145,
      usesysid: nil, backend_type: "autovacuum worker", backend_start_us: 123}]}}
    assert transport_backend_inventory(result, context, expected) === literal
    assert transport_inventory_rejection_classify(result, context, expected) === %{stage: expected.stage, reason: :accepted, row_mask: 0}
    transport_ir_slot(expected.key, fn ->
      assert transport_inventory_rejection_get(expected.key) === :unobserved
      assert transport_inventory_rejection_observe(literal, result, context, expected) === literal
      assert transport_inventory_rejection_get(expected.key) === :unobserved
    end)
    triple
  end

  defp transport_ir_mutant!(columns, change, reason, mask) do
    {result, context, expected} = change.(transport_ir_positive!(columns))
    rejected? = transport_backend_inventory(result, context, expected) === :error
    assert rejected?
    actual = transport_inventory_rejection_classify(result, context, expected)
    stage = if is_map(expected) and expected[:stage] in [:baseline, :gate, :absence],
      do: expected.stage, else: :unknown
    finite? = transport_ir_finite?(actual)
    matches? = actual === %{stage: stage, reason: reason, row_mask: mask}
    assert finite?
    assert matches?
  end

  defp transport_ir_context(triple, field, value) do
    {result, context, expected} = triple
    {result, Map.put(context, field, value), expected}
  end

  defp transport_ir_binding(triple, field, value) do
    {result, context, expected} = triple
    {result, Map.put(context, field, value), Map.put(expected, field, value)}
  end

  defp transport_ir_rows({{:ok, result}, context, expected}, rows),
    do: {{:ok, %{result | rows: rows}}, context, expected}

  defp transport_ir_worker({result, context, expected}, field, value, where) do
    context = Enum.reduce(where, context, fn side, acc ->
      Map.update!(acc, side, fn [worker] -> [Map.put(worker, field, value)] end)
    end)
    {result, context, expected}
  end

  test "R02 inventory rejection accepts literal two and three column workers inertly" do
    transport_ir_positive!(2)
    transport_ir_positive!(3)
    {result, context, expected} = transport_ir_binding(transport_ir_positive!(3), :stage, :absence)
    original = transport_backend_inventory(result, context, expected)
    assert match?({:ok, _}, original)
    assert transport_inventory_rejection_classify(result, context, expected) === %{stage: :absence, reason: :accepted, row_mask: 0}
    transport_ir_slot(expected.key, fn ->
      assert transport_inventory_rejection_observe(original, result, context, expected) === original
      assert transport_inventory_rejection_get(expected.key) === :unobserved
    end)
  end

  test "R03 inventory rejection follows first predicates and unsupported binding boundary" do
    changes = [
      {fn {_r, c, e} -> {:malformed, c, e} end, :input_shape},
      {fn {r, _c, e} -> {r, nil, e} end, :input_shape},
      {fn {r, c, _e} -> {r, c, nil} end, :input_shape},
      {fn t -> transport_ir_binding(t, :nonce, nil) end, :binding},
      {fn t -> transport_ir_binding(t, :baseline, List.duplicate({101, "synthetic_role"}, 65)) end, :binding},
      {fn t -> transport_ir_context(t, :database, "synthetic_other") end, :context_binding},
      {fn {r, c, e} -> {r, Map.delete(c, :child_pid), e} end, :context_binding},
      {fn t -> transport_ir_context(t, :authority, :unverified) end, :capture},
      {fn t -> transport_ir_context(t, :capture, :failed) end, :capture},
      {fn t -> transport_ir_context(t, :capture, :overflow) end, :capture},
      {fn t -> transport_ir_context(t, :sequence, 0) end, :sequence},
      {fn t -> transport_ir_context(t, :sequence, 33) end, :sequence},
      {fn t -> transport_ir_context(t, :sequence, :invalid) end, :sequence},
      {fn {r, c, e} -> {r, Map.delete(c, :after_ns), e} end, :clock},
      {fn t -> transport_ir_context(t, :query_after_ns, :invalid) end, :clock},
      {fn t -> transport_ir_context(t, :query_before_ns, 99) end, :clock},
      {fn t -> transport_ir_context(t, :before_ns, -9_223_372_036_854_775_809) end, :clock},
      {fn t -> transport_ir_context(t, :after_ns, 9_223_372_036_854_775_808) end, :clock},
      {fn t -> transport_ir_rows(t, List.duplicate([101, "synthetic_role"], 65)) end, :row_limit},
      {fn t -> transport_ir_context(t, :before, nil) end, :before_metadata},
      {fn {r, c, e} -> {r, %{c | before: c.before ++ c.before}, e} end, :before_metadata},
      {fn {r, c, e} -> {r, %{c | before: List.duplicate(hd(c.before), 65)}, e} end, :before_metadata},
      {fn t -> transport_ir_context(t, :after, nil) end, :after_metadata},
      {fn {r, c, e} -> {r, %{c | after: c.after ++ c.after}, e} end, :after_metadata},
      {fn {r, c, e} -> {r, %{c | after: List.duplicate(hd(c.after), 65)}, e} end, :after_metadata},
      {fn t -> transport_ir_rows(t, [[101, "synthetic_role"], [144, nil], [101, "synthetic_role"]]) end, :duplicate},
      {fn t -> transport_ir_rows(t, [[101, "synthetic_role"], [144, nil], [144, nil]]) end, :duplicate},
      {fn {r, c, e} -> {r, c, Map.delete(e, :child_pid)} end, :unavailable}
    ]
    for {change, reason} <- changes, do: transport_ir_mutant!(2, change, reason, 0)
    {r, c, e} = transport_ir_positive!(2)
    equal = Map.merge(c, %{before_ns: 100, query_before_ns: 100, query_after_ns: 100, after_ns: 100})
    assert transport_backend_inventory(r, equal, e) === transport_backend_inventory(r, c, e)
    assert transport_inventory_rejection_classify(r, equal, e) === %{stage: :baseline, reason: :accepted, row_mask: 0}
    for mode <- [:matching, :capture_failed, :mismatching] do
      {result, context, expected} = transport_ir_positive!(2)
      expected = Map.put(expected, :synthetic_extension, :literal)
      context = Map.put(context, :synthetic_extension, if(mode == :mismatching, do: :different, else: :literal))
      context = if mode == :capture_failed, do: %{context | capture: :failed}, else: context
      original = transport_backend_inventory(result, context, expected)
      assert (if mode == :matching, do: match?({:ok, _}, original), else: original === :error)
      assert transport_inventory_rejection_classify(result, context, expected) === %{stage: :baseline, reason: :unavailable, row_mask: 0}
      transport_ir_slot(expected.key, fn ->
        assert transport_inventory_rejection_observe(original, result, context, expected) === original
        if mode == :matching, do: assert(transport_inventory_rejection_get(expected.key) === :unobserved)
      end)
    end
  end

