    {result, context, expected} = transport_ir_positive!(2)
    transport_ir_slot(expected.key, fn ->
      first = %{context | before: []}
      assert transport_inventory_rejection_observe(:error, result, first, expected) === :error
      assert transport_inventory_rejection_get(expected.key) === %{stage: :baseline, reason: :row, row_mask: 12_475}
      {r2, c2, e2} = transport_ir_positive!(2)
      second = %{c2 | after: []}
