      assert transport_inventory_rejection_observe(:error, r3, bad_context, bad_expected) === :error
      assert catch_throw(transport_inventory_clients!(result, first, expected)) === :legacy_transport_observer
      assert transport_inventory_rejection_get(expected.key) === %{stage: :baseline, reason: :row, row_mask: 12_475}
