  test "R07 inventory rejection exposes only finite records under malformed canaries" do
    {result, context, expected} = transport_ir_positive!(2)
    canary = "synthetic-inventory-private-canary"
    fallback = %{stage: :unknown, reason: :unavailable, row_mask: 0}
    for fun <- [fn -> raise canary end, fn -> throw(canary) end, fn -> exit(canary) end] do
      transport_ir_positive!(2)
      assert transport_attribution_safe(fun, fallback) === fallback
    end
    for change <- [fn {_r, c, e} -> {{:error, canary}, c, e} end,
      fn {r, _c, e} -> {r, canary, e} end,
      fn {r, c, _e} -> {r, c, canary} end] do
      transport_ir_mutant!(2, change, :input_shape, 0)
    end
    for corrupt <- [canary, %{stage: canary, reason: :row, row_mask: 1},
      %{stage: :baseline, reason: canary, row_mask: 0},
      %{stage: :baseline, reason: :row, row_mask: 16_384},
      %{stage: :baseline, reason: :accepted, row_mask: 1},
      %{stage: :baseline, reason: :row, row_mask: 0, extra: canary}] do
      transport_ir_positive!(2)
      transport_ir_slot(expected.key, fn ->
        Process.put({expected.key, :inventory_rejection}, corrupt)
        safe = transport_inventory_rejection_get(expected.key)
        finite? = transport_ir_finite?(safe)
        fallback? = safe === fallback
        assert finite?
        assert fallback?
        assert transport_inventory_rejection_observe(:error, result, %{context | before: []}, expected) === :error
        unchanged? = transport_inventory_rejection_get(expected.key) === fallback
        preserved? = Process.get({expected.key, :inventory_rejection}) === corrupt
        assert unchanged?
        assert preserved?
      end)
    end
    assert transport_inventory_rejection_get(nil) === fallback
    assert transport_inventory_rejection_clear(nil) === :ok
  end
