  defp transport_ir_record(expected, reason, mask \\ 0) do
    stage = case expected do
      %{stage: stage} when stage in [:baseline, :gate, :absence] -> stage
      _ -> :unknown
    end
    %{stage: stage, reason: reason, row_mask: mask}
  end

  defp transport_ir_bounded?(rows), do: transport_ir_bounded?(rows, 0)
  defp transport_ir_bounded?([], _count), do: true
  defp transport_ir_bounded?([_ | rest], count) when count < 64,
    do: transport_ir_bounded?(rest, count + 1)
  defp transport_ir_bounded?(_, _count), do: false

  defp transport_ir_supported?(expected) do
    map_size(expected) == 13 and Enum.all?(transport_ir_fields(), &Map.has_key?(expected, &1))
  end

  defp transport_ir_classify(result, context, expected) do
    transport_attribution_safe(fn -> transport_ir_classify_input(result, context, expected) end,
      transport_ir_record(expected, :unavailable))
  end

  defp transport_ir_classify_input({:ok, %Postgrex.Result{rows: rows}}, context, expected)
       when is_list(rows) and is_map(context) and is_map(expected) do
    cond do
      not transport_ir_supported?(expected) -> transport_ir_record(expected, :unavailable)
      not transport_ir_bounded?(expected.baseline) -> transport_ir_record(expected, :binding)
      not transport_inventory_binding_valid?(expected) -> transport_ir_record(expected, :binding)
      not Enum.all?(transport_ir_fields(), fn field ->
        Map.fetch(context, field) == Map.fetch(expected, field)
      end) -> transport_ir_record(expected, :context_binding)
      context[:authority] != :verified or context[:capture] != :complete ->
        transport_ir_record(expected, :capture)
      not (is_integer(context[:sequence]) and context[:sequence] in 1..32) ->
        transport_ir_record(expected, :sequence)
      not transport_inventory_clock_valid?(context) -> transport_ir_record(expected, :clock)
      not transport_ir_bounded?(rows) -> transport_ir_record(expected, :row_limit)
      not (transport_ir_bounded?(context[:before]) and
        transport_inventory_metadata_valid?(context[:before], expected.database_oid)) ->
        transport_ir_record(expected, :before_metadata)
      not (transport_ir_bounded?(context[:after]) and
        transport_inventory_metadata_valid?(context[:after], expected.database_oid)) ->
        transport_ir_record(expected, :after_metadata)
      true ->
        before = Map.new(context.before, &{&1.pid, &1})
        after_sample = Map.new(context.after, &{&1.pid, &1})
        transport_ir_classify_rows(rows, expected, before, after_sample, MapSet.new())
    end
  end

  defp transport_ir_classify_input(_result, _context, expected),
    do: transport_ir_record(expected, :input_shape)

  defp transport_ir_classify_rows([], expected, _before, _after, _seen),
    do: transport_ir_record(expected, :accepted)

  defp transport_ir_classify_rows([row | rest], expected, before, after_sample, seen) do
    case transport_inventory_row(row, expected, before, after_sample) do
      {:client, {pid, _}} -> transport_ir_next(pid, rest, expected, before, after_sample, seen)
      {:worker, %{pid: pid}} -> transport_ir_next(pid, rest, expected, before, after_sample, seen)
      :error -> transport_ir_record(expected, :row, transport_ir_mask(row, expected, before, after_sample))
    end
  end

  defp transport_ir_next(pid, rest, expected, before, after_sample, seen) do
    if MapSet.member?(seen, pid), do: transport_ir_record(expected, :duplicate),
      else: transport_ir_classify_rows(rest, expected, before, after_sample, MapSet.put(seen, pid))
  end

  defp transport_ir_mask([pid, username], %{columns: 2} = expected, before, after_sample),
    do: transport_ir_mask([pid, username, nil], %{expected | columns: 3}, before, after_sample)

  defp transport_ir_mask([pid, username, backend], %{columns: 3} = expected, before, after_sample) do
    prior = Map.get(before, pid)
    later = Map.get(after_sample, pid)
    facts = [true, transport_attribution_pid?(pid), is_binary(username), is_nil(username),
      backend in [nil, "client backend"], backend in [nil, "autovacuum worker"],
      is_map(prior), is_map(later), is_map(prior) and is_map(later) and prior == later,
      is_map(prior) and Map.get(prior, :backend_type) == "autovacuum worker",
      is_map(prior) and Map.get(prior, :usesysid) == nil,
      is_map(prior) and Map.get(prior, :datid) == expected.database_oid,
      pid != expected.child_pid, not List.keymember?(expected.baseline, pid, 0)]
    facts |> Enum.with_index() |> Enum.reduce(0, fn {fact, bit}, mask ->
      if fact, do: Bitwise.bor(mask, Bitwise.bsl(1, bit)), else: mask
    end)
  end

  defp transport_ir_mask(_row, _expected, _before, _after), do: 0

  defp transport_ir_sanitize(value) do
    case value do
      %{stage: stage, reason: reason, row_mask: mask} when map_size(value) == 3 ->
        valid = stage in [:baseline, :gate, :absence, :unknown] and
          reason in [:input_shape, :binding, :context_binding, :capture, :sequence,
            :clock, :row_limit, :before_metadata, :after_metadata, :duplicate, :row,
            :accepted, :unavailable] and is_integer(mask) and mask in 0..16_383 and
          (reason == :row or mask == 0)
        if valid, do: %{stage: stage, reason: reason, row_mask: mask},
          else: transport_ir_record(nil, :unavailable)
      _ -> transport_ir_record(nil, :unavailable)
    end
  end

  defp transport_ir_observe(:error, result, context, expected) do
    transport_attribution_safe(fn ->
      case expected do
        %{key: key} when is_reference(key) ->
          slot = {key, :inventory_rejection}
          absent = make_ref()
          if Process.get(slot, absent) === absent do
            record = transport_inventory_rejection_classify(result, context, expected)
            Process.put(slot, transport_ir_sanitize(record))
          end
        _ -> :ok
      end
    end, :ok)
    :error
  end

  defp transport_ir_observe(value, _result, _context, _expected), do: value

  defp transport_ir_get(key) when is_reference(key) do
    transport_attribution_safe(fn ->
      case Process.get({key, :inventory_rejection}, :unobserved) do
        :unobserved -> :unobserved
        value -> transport_ir_sanitize(value)
      end
    end, transport_ir_record(nil, :unavailable))
  end

  defp transport_ir_get(_key), do: transport_ir_record(nil, :unavailable)

  defp transport_ir_clear(key) when is_reference(key) do
    transport_attribution_safe(fn -> Process.delete({key, :inventory_rejection}) end, :ok)
    :ok
  end

  defp transport_ir_clear(_key), do: :ok
