  # TASK18_UA_MOUNT_RECURRENCE_COLLECTOR_C_BEGIN
  # Shared diagnostic implementation; no live hook is installed by component C.
  defp ua_pe_impl_safe(fun, fallback) do
    try do
      fun.()
    rescue
      _ -> fallback
    catch
      _, _ -> fallback
    end
  end

  defp ua_pe_impl_phases, do: [:seed, :sources, :transport, :admit, :post_loop, :restore, :close]
  defp ua_pe_impl_statuses do
    [:stored, :not_captured, :invalid_input, :primary_mismatch,
     :deadline_unavailable, :deadline_expired, :parent_rejected, :open_failed,
     :file_rejected, :write_failed, :length_failed, :readback_failed,
     :close_failed, :unexpected_exception]
  end

  # Consume at most the finite enum length, including improper-list rejection.
  defp ua_pe_impl_bounded_list?([], _remaining), do: true
  defp ua_pe_impl_bounded_list?([_ | tail], remaining) when remaining > 0,
    do: ua_pe_impl_bounded_list?(tail, remaining - 1)
  defp ua_pe_impl_bounded_list?(_, _), do: false

  defp ua_pe_impl_enum?(list, allowed) do
    ua_pe_impl_bounded_list?(list, length(allowed)) and
      list == Enum.filter(allowed, &(&1 in list))
  end

  defp ua_pe_impl_bytes?(bytes),
    do: is_binary(bytes) and byte_size(bytes) in 1..16_384

  defp ua_pe_impl_pair?(pair) do
    ua_b_keys?(pair, [:status, :seed, :current, :phase, :fields, :labels, :deadline, :attempted]) and
      pair.status == :captured_once and pair.attempted == false and
      ua_pe_impl_bytes?(pair.seed) and ua_pe_impl_bytes?(pair.current) and
      pair.phase in ua_pe_impl_phases() and
      ua_pe_impl_enum?(pair.fields, ua_control_seed_fields()) and :mount in pair.fields and
      ua_pe_impl_enum?(pair.labels, ua_control_mount_labels()) and
      (is_integer(pair.deadline) or is_nil(pair.deadline))
  end

  defp ua_pe_impl_capture(nil, _seed, _current, _phase, _fields, _labels, _deadline), do: nil
  defp ua_pe_impl_capture(state, seed, current, phase, fields, labels, deadline) do
    ua_pe_impl_safe(fn ->
      cond do
        state == ua_pe_armed() ->
          cond do
            phase not in ua_pe_impl_phases() or
                not ua_pe_impl_enum?(fields, ua_control_seed_fields()) or fields == [] or
                not (is_integer(deadline) or is_nil(deadline)) ->
              %{status: :invalid_input, attempted: false}
            :mount not in fields ->
              %{status: :no_mount_pair, attempted: false}
            not ua_pe_impl_enum?(labels, ua_control_mount_labels()) or
                not ua_pe_impl_bytes?(seed) or not ua_pe_impl_bytes?(current) ->
              %{status: :invalid_input, attempted: false}
            true ->
              %{status: :captured_once, seed: seed, current: current, phase: phase,
                fields: fields, labels: labels, deadline: deadline, attempted: false}
          end
        ua_pe_impl_pair?(state) -> state
        state in [%{status: :invalid_input, attempted: false},
                  %{status: :no_mount_pair, attempted: false}] -> state
        ua_pe_impl_attempted?(state) -> state
        true -> %{status: :invalid_input, attempted: false}
      end
    end, %{status: :invalid_input, attempted: false})
  end

  defp ua_pe_impl_primary?(pair, primary) do
    is_map(primary) and Map.get(primary, :phase) == pair.phase and
      Map.get(primary, :kind) == :throw and Map.get(primary, :line) == 6298 and
      Map.get(primary, :seed_fields) == pair.fields and Map.get(primary, :mount_delta) == pair.labels
  end

  defp ua_pe_impl_mask(list, allowed) do
    allowed |> Enum.with_index() |> Enum.reduce(0, fn {value, bit}, mask ->
      if value in list, do: Bitwise.bor(mask, Bitwise.bsl(1, bit)), else: mask
    end)
  end

  defp ua_pe_impl_unmask(mask, allowed) do
    allowed |> Enum.with_index() |> Enum.flat_map(fn {value, bit} ->
      if Bitwise.band(mask, Bitwise.bsl(1, bit)) != 0, do: [value], else: []
    end)
  end

  defp ua_pe_impl_encode(pair, primary) do
    ua_pe_impl_safe(fn ->
      if ua_pe_impl_pair?(pair) and ua_pe_impl_primary?(pair, primary) do
        phase = Enum.find_index(ua_pe_impl_phases(), &(&1 == pair.phase)) + 1
        fields = ua_pe_impl_mask(pair.fields, ua_control_seed_fields())
        labels = ua_pe_impl_mask(pair.labels, ua_control_mount_labels())
        seed_hash = :crypto.hash(:sha256, pair.seed)
        current_hash = :crypto.hash(:sha256, pair.current)
        {:ok, <<"T18MOUNT", 1, phase, phase, 2, 6298::32, fields::16, labels::16,
          byte_size(pair.seed)::32, byte_size(pair.current)::32,
          seed_hash::binary-size(32), current_hash::binary-size(32),
          pair.seed::binary, pair.current::binary>>}
      else
        {:error, :invalid_input}
      end
    end, {:error, :invalid_input})
  end

  defp ua_pe_impl_decode(bytes) when is_binary(bytes) and byte_size(bytes) <= 32_860 do
    ua_pe_impl_safe(fn ->
      with <<"T18MOUNT", 1, phase, primary_phase, 2, 6298::32, fields::16, labels::16,
             seed_size::32, current_size::32, seed_hash::binary-size(32),
             current_hash::binary-size(32), payload::binary>> <- bytes,
           true <- phase in 1..7 and primary_phase == phase,
           true <- fields < 1024 and Bitwise.band(fields, 128) != 0 and labels < 8192,
           true <- seed_size in 1..16_384 and current_size in 1..16_384,
           <<seed::binary-size(seed_size), current::binary-size(current_size)>> <- payload,
           true <- :crypto.hash(:sha256, seed) == seed_hash,
           true <- :crypto.hash(:sha256, current) == current_hash do
        phase = Enum.at(ua_pe_impl_phases(), phase - 1)
        fields = ua_pe_impl_unmask(fields, ua_control_seed_fields())
        labels = ua_pe_impl_unmask(labels, ua_control_mount_labels())
        {:ok, %{seed: seed, current: current, phase: phase, fields: fields, labels: labels,
          primary: %{phase: phase, kind: :throw, line: 6298, seed_fields: fields, mount_delta: labels}}}
      else
        _ -> {:error, :invalid_input}
      end
    end, {:error, :invalid_input})
  end
  defp ua_pe_impl_decode(_), do: {:error, :invalid_input}

  defp ua_pe_impl_attempted?(%{attempted: true, dispatch_status: status} = state) do
    status in ua_pe_impl_statuses() and ua_pe_impl_pair?(state |> Map.delete(:dispatch_status) |> Map.put(:attempted, false))
  end
  defp ua_pe_impl_attempted?(_), do: false

  defp ua_pe_impl_dispatch(state, primary, sink) do
    ua_pe_impl_safe(fn ->
      cond do
        ua_pe_impl_attempted?(state) -> {state, state.dispatch_status}
        ua_pe_impl_pair?(state) ->
          status =
            if ua_pe_impl_primary?(state, primary) do
              ua_pe_impl_safe(fn -> sink.(state, primary) end, :unexpected_exception)
            else
              :primary_mismatch
            end
          status = if status in ua_pe_impl_statuses(), do: status, else: :unexpected_exception
          {Map.merge(state, %{attempted: true, dispatch_status: status}), status}
        state == %{status: :invalid_input, attempted: false} -> {state, :invalid_input}
        state in [nil, ua_pe_armed(), %{status: :no_mount_pair, attempted: false}] -> {state, :not_captured}
        true -> {state, :invalid_input}
      end
    end, {state, :unexpected_exception})
  end

  defp ua_pe_impl_transfer(value, primary, state), do: {value, primary, state}

  defp ua_pe_impl_finish({value, primary, state}, sink, emit) do
    ua_pe_impl_safe(fn ->
      {_attempted, status} = ua_pe_dispatch(state, primary, sink)
      ua_pe_impl_safe(fn -> emit.(status) end, :ok)
    end, :ok)
    {value, primary}
  end

  defp ua_pe_impl_public_line(status) do
    status = if status in ua_pe_impl_statuses(), do: status, else: :unexpected_exception
    "TASK18_UA_PRIVATE_MOUNT_CAPTURE status=" <> Atom.to_string(status) <> "\n"
  end

