  defp ua_pe_impl_relation(point, region) do
    if ua_mi_path?(point) and ua_mi_path?(region) do
      relation = cond do
        point == region -> :equal
        point == "/" or ua_starts?(region, point <> "/") -> :ancestor
        region == "/" or ua_starts?(point, region <> "/") -> :descendant
        true -> :disjoint
      end
      {:ok, relation}
    else
      {:error, :invalid_input}
    end
  end

  defp ua_pe_impl_analyze(seed, current, regions) do
    ua_pe_impl_safe(fn ->
      with true <- regions == ua_pe_impl_regions(),
           {:ok, seed_lines} <- ua_text_lines(seed, 16_384),
           {:ok, current_lines} <- ua_text_lines(current, 16_384),
           {:ok, seed_rows} <- ua_mount_rows(seed_lines, [], []),
           {:ok, current_rows} <- ua_mount_rows(current_lines, [], []),
           true <- Enum.all?(seed_rows ++ current_rows, &ua_mi_path?(&1.point)) do
        current_ids = MapSet.new(current_rows, & &1.id)
        removed = seed_rows |> Enum.reject(&MapSet.member?(current_ids, &1.id)) |> Enum.map(fn row ->
          relations = Map.new(regions, fn {name, region} ->
            {:ok, relation} = ua_pe_relation(row.point, region)
            {name, relation}
          end)
          %{id: row.id, raw: row.raw, relations: relations}
        end)
        {:ok, %{removed: removed, labels: ua_control_mount_delta(current, seed),
          acceptance: if(seed == current, do: :unchanged, else: :rejected)}}
      else
        _ -> {:error, :invalid_input}
      end
    end, {:error, :invalid_input})
