  # Only registered lexical roots and leaves are admitted. Identity comes from
  # the fixed binding; no path discovery, normalization or fallback is performed.
  defp ua_pe_impl_binding?(binding) do
    ua_pe_impl_safe(fn ->
      roots = Enum.map([:d05, :d06, :d07, :d08, :d09, :d10, :d11, :d15], &ua_pe_fixture_root/1)
      actual = "/home/gao/Workspace/gsmlg-opt/Singularity/.trees/v0.2-phase-5-export-backup/.devenv/phase5-task18-selected-command-fault1-process4.private"
      with true <- ua_b_keys?(binding, [:directory, :path, :route, :parent]),
           true <- binding.directory in [actual | roots],
           leaves = if(binding.directory == actual, do: ["mount-pair.bin"], else: ["control.bin", "subject.bin"]),
           true <- binding.path in Enum.map(leaves, &(binding.directory <> "/" <> &1)),
           true <- ua_pe_impl_bounded_list?(binding.route, 10) and length(binding.route) == 10,
           true <- Enum.all?(binding.route, fn
             {path, identity} -> ua_mi_path?(path) and ua_pe_impl_directory_identity?(identity)
             _ -> false
           end),
           true <- Enum.map(binding.route, &elem(&1, 0)) == ua_mi_components(binding.directory),
           true <- List.last(binding.route) == {binding.directory, binding.parent},
