  defp ua_pe_impl_directory_identity?(identity) do
    ua_b_keys?(identity, [:type, :major_device, :minor_device, :inode, :uid, :gid, :mode]) and
      identity.type == :directory and
      Enum.all?([identity.major_device, identity.minor_device, identity.uid, identity.gid],
        &(is_integer(&1) and &1 >= 0 and &1 <= 4_294_967_295)) and
      is_integer(identity.inode) and identity.inode > 0 and
      is_integer(identity.mode) and identity.mode in 0..0o7777 and
      Bitwise.band(identity.mode, 0o022) == 0
  end

  # State is threaded across every callback so a returned FD is owned before
  # its post-deadline check. The two close flags mean attempted, not successful.
  defp ua_pe_impl_write(binding, bytes, deadline, operation) do
    cond do
      ua_pe_decode(bytes) == {:error, :invalid_input} -> :invalid_input
      not ua_pe_impl_binding?(binding) -> :parent_rejected
      not is_integer(deadline) -> :deadline_unavailable
      true ->
        state = %{binding: binding, bytes: bytes, deadline: deadline, operation: operation,
          parent: nil, leaf: nil, parent_close: false, leaf_close: false,
          identity: nil, error: nil, close_failed: false}
        steps =
          Enum.map(binding.route, &{:route_before, &1}) ++
          [:parent_open, :parent_fd, :parent_named] ++
          Enum.map(binding.route, &{:route_held, &1}) ++
          [:leaf_open, :leaf_fd_empty, :leaf_named_empty, :parent_prewrite, :parent_fd_prewrite] ++
          Enum.map(binding.route, &{:route_prewrite, &1}) ++
          [:write, :position, :leaf_fd_written, :leaf_named_written, :parent_postwrite,
           :leaf_fd_preread, :readback, :leaf_fd_postread, :leaf_close,
           :leaf_named_final, :parent_final, :parent_fd_final] ++
          Enum.map(binding.route, &{:route_final, &1}) ++ [:parent_close]
        state = Enum.reduce_while(steps, state, fn step, state ->
          state = ua_pe_impl_step(state, step)
          if state.error == nil and not state.close_failed, do: {:cont, state}, else: {:halt, state}
        end)
        state = state |> ua_pe_impl_close(:leaf_close) |> ua_pe_impl_close(:parent_close) |> ua_pe_impl_clock()
        cond do
          state.close_failed -> :close_failed
          state.error != nil -> state.error
          true -> :stored
        end
    end
  end

  defp ua_pe_impl_error(%{error: nil} = state, error), do: %{state | error: error}
  defp ua_pe_impl_error(state, _error), do: state

  defp ua_pe_impl_clock(state) do
    result = ua_pe_impl_safe(fn -> state.operation.(:now, []) end, :exception)
    cond do
      not is_integer(result) -> ua_pe_impl_error(state, :unexpected_exception)
      result >= state.deadline -> ua_pe_impl_error(state, :deadline_expired)
      true -> state
    end
  end

  defp ua_pe_impl_step(state, step) when step in [:leaf_close, :parent_close],
    do: ua_pe_impl_close(state, step)
  defp ua_pe_impl_step(state, step) do
    state = ua_pe_impl_clock(state)
    if state.error != nil do
      state
    else
      {label, args} = ua_pe_impl_args(state, step)
      result = ua_pe_impl_safe(fn -> {:returned, state.operation.(label, args)} end, :exception)
      # No validation or clock call intervenes between successful open and ownership.
      state = case {label, result} do
        {:parent_open, {:returned, {:ok, fd}}} -> %{state | parent: {:owned, fd}}
        {:leaf_open, {:returned, {:ok, fd}}} -> %{state | leaf: {:owned, fd}}
        _ -> state
      end
      checked = ua_pe_impl_safe(fn -> ua_pe_impl_check(state, step, result) end,
        ua_pe_impl_error(state, :unexpected_exception))
      ua_pe_impl_clock(checked)
    end
  end

  defp ua_pe_impl_close(state, step) do
    handle = if step == :leaf_close, do: state.leaf, else: state.parent
    if handle != nil and not Map.fetch!(state, step) do
      {:owned, fd} = handle
      state = state |> Map.put(step, true) |> ua_pe_impl_clock()
      result = ua_pe_impl_safe(fn -> state.operation.(step, [fd]) end, :exception)
      state = if result == :ok, do: state, else: %{state | close_failed: true}
      ua_pe_impl_clock(state)
    else
      state
    end
  end

  defp ua_pe_impl_args(_state, {label, {path, _identity}}), do: {label, [path]}
  defp ua_pe_impl_args(state, step) do
    args = case step do
      :parent_open -> [state.binding.directory]
      :leaf_open -> [state.binding.path]
      named when named in [:parent_named, :parent_prewrite, :parent_postwrite, :parent_final] ->
        [state.binding.directory]
      named when named in [:leaf_named_empty, :leaf_named_written, :leaf_named_final] ->
        [state.binding.path]
      held when held in [:parent_fd, :parent_fd_prewrite, :parent_fd_final] -> [elem(state.parent, 1)]
      :write -> [elem(state.leaf, 1), state.bytes]
      :readback -> [elem(state.leaf, 1), byte_size(state.bytes)]
      _ -> [elem(state.leaf, 1)]
    end
    {step, args}
  end

  defp ua_pe_impl_check(state, _step, :exception), do: ua_pe_impl_error(state, :unexpected_exception)
  defp ua_pe_impl_check(state, {_label, {_path, identity}}, {:returned, result}),
    do: ua_pe_impl_parent_check(state, result, identity)
  defp ua_pe_impl_check(state, step, {:returned, result}) when step in [:parent_open, :leaf_open] do
    if match?({:ok, _}, result), do: state, else: ua_pe_impl_error(state, :open_failed)
  end
  defp ua_pe_impl_check(state, step, {:returned, result})
       when step in [:parent_fd, :parent_named, :parent_prewrite, :parent_fd_prewrite,
                     :parent_postwrite, :parent_final, :parent_fd_final],
    do: ua_pe_impl_parent_check(state, result, state.binding.parent)
  defp ua_pe_impl_check(state, :write, {:returned, result}) do
    if result == :ok, do: state, else: ua_pe_impl_error(state, :write_failed)
  end
  defp ua_pe_impl_check(state, :position, {:returned, result}) do
    if result == {:ok, byte_size(state.bytes)}, do: state, else: ua_pe_impl_error(state, :length_failed)
  end
  defp ua_pe_impl_check(state, :readback, {:returned, result}) do
    if result == {:ok, state.bytes}, do: state, else: ua_pe_impl_error(state, :readback_failed)
  end
  defp ua_pe_impl_check(state, step, {:returned, result}) do
    size = if step in [:leaf_fd_empty, :leaf_named_empty], do: 0, else: byte_size(state.bytes)
    case result do
      {:ok, %File.Stat{} = stat} ->
        identity = ua_pe_identity(stat) |> Map.put(:links, stat.links)
        cond do
          stat.type != :regular or stat.uid != 1000 or stat.links != 1 or
              Bitwise.band(stat.mode, 0o7777) != 0o600 or stat.inode <= 0 ->
            ua_pe_impl_error(state, :file_rejected)
          state.identity != nil and identity != state.identity ->
            ua_pe_impl_error(state, :file_rejected)
          stat.size != size ->
            ua_pe_impl_error(state, if(size == 0, do: :file_rejected, else: :length_failed))
          true -> %{state | identity: identity}
        end
      _ -> ua_pe_impl_error(state, :file_rejected)
    end
  end

  defp ua_pe_impl_parent_check(state, result, identity) do
    case result do
      {:ok, %File.Stat{} = stat} ->
        if stat.type == :directory and ua_pe_identity(stat) == identity,
          do: state, else: ua_pe_impl_error(state, :parent_rejected)
      _ -> ua_pe_impl_error(state, :parent_rejected)
    end
  end

