      valid? = is_map(control) and is_integer(Map.get(control, :epoch)) and
        Map.has_key?(control, :diagnostic) and ua_pe_bridge_diagnostic?(control.diagnostic) and
        Map.get(control, :diagnostic_phase) in ua_pe_impl_phases() and
