  defp ua_pe_b_literals do
    p = "21 1 0:5 / /proc rw,nosuid,nodev,noexec,relatime - proc proc rw\n"
    a = "31 1 0:7 / /synthetic\\040new rw - tmpfs none rw\n"
    q = p <> a
    pair = %{status: :captured_once, seed: p, current: q, phase: :admit,
      fields: [:mount], labels: [:added], deadline: 1_000, attempted: false}
    primary = %{phase: :admit, kind: :throw, line: 6298,
      seed_fields: [:mount], mount_delta: [:added]}
    seed_hash = :crypto.hash(:sha256, p)
    current_hash = :crypto.hash(:sha256, q)
    oracle = <<"T18MOUNT", 1, 4, 4, 2, 6298::32, 128::16, 1::16,
      byte_size(p)::32, byte_size(q)::32, seed_hash::binary-size(32),
      current_hash::binary-size(32), p::binary, q::binary>>
    {p, a, q, pair, primary, oracle}
  end

