    pure? = ua_pe_capture(ua_pe_armed(), p, q, :admit, [:mount], [:added], 1_000) == pair
    assert pure?
    encoded? = ua_pe_encode(pair, primary) == {:ok, oracle}
    assert encoded?
    decoded? = ua_pe_decode(oracle) == {:ok, %{seed: p, current: q, phase: :admit,
      fields: [:mount], labels: [:added], primary: primary}}
    assert decoded?
    {pair, primary}
  end

