        assert ua_control_seed_mismatch(%{seed | mount: nil}, seed) == :ok
        retained? = get_in(Process.get({__MODULE__, :ua_control}), [:ua_pe_capture, :state]) == pair
        primary_retained? = ua_control_diagnostic(:error, []) == primary
