            bad when bad in [:empty, :oversize, :nonbinary, :empty_seed, :oversize_seed, :nonbinary_seed] -> %{status: :invalid_input, attempted: false}
            :nil_deadline -> %{pair | deadline: nil}
            :prior_primary -> ua_pe_armed()
            :corrupt_arm -> :corrupt
            _ -> nil
          end
          exact? = state == expected
          assert exact?
          if mutant == :unarmed do
            assert not Map.has_key?(control, :ua_pe_capture)
            assert ua_control_seed_suffix(%{seed_fields: control.seed_mismatch, mount_delta: control.mount_delta}) ==
              " seed_fields=mount mount_delta=added"
          end
          local = Process.delete(key)
          assert ua_pe_bridge_stage(local, token) == :ok
          sink = fn actual, diagnostic ->
            assert mutant == :nil_deadline
            nil_pair? = actual == %{pair | deadline: nil} and diagnostic == primary
            assert nil_pair?
            # Synthetic missing deadline: the IO callback must never be invoked.
            status = ua_pe_write(ua_pe_b_binding(), elem(ua_pe_b_literals(), 5), actual.deadline,
              fn _, _ -> ua_pe_b_mark(:unexpected_io); :unexpected_exception end)
            assert status == :deadline_unavailable
            ua_pe_b_mark(:nil_deadline)
            status
          end
          exact? = ua_pe_bridge_finish({false, primary}, token, sink, fn _ -> :ok end) == {false, primary}
          assert exact?
          assert Process.get({__MODULE__, :ua_pe_b_events}) ==
            if(mutant == :nil_deadline, do: [:nil_deadline], else: [])
        after
          ua_pe_bridge_clear(token)
        end
      end)
    end

    for {field, value} <- [line: 6297, kind: :error, phase: :restore,
                           seed_fields: [:root], mount_delta: [:removed]] do
      ua_pe_b_positive()
      ua_pe_b_isolated(fn ->
        {token, seed, pair, primary} = ua_pe_b_arm()
