          ua_pe_bridge_stage(local, token)
          exact? = ua_pe_bridge_finish({false, bad}, token,
            fn _, _ -> ua_pe_b_mark(:unexpected_sink); :stored end, &ua_pe_b_mark/1) == {false, bad}
          assert exact?
          assert Process.get({__MODULE__, :ua_pe_b_events}) == [:primary_mismatch]
        after
          ua_pe_bridge_clear(token)
        end
      end)
