  test "B02 synthetic owned handoff clears through normal rescue catch and secondary failures" do
    ua_pe_b_positive_handoff()
    ua_pe_b_isolated(fn ->
      {pair, primary} = ua_pe_b_positive()
      pair = %{pair | deadline: -1_000}
      seed = Map.new(ua_control_seed_fields(), &{&1, :unchanged}) |> Map.put(:mount, pair.seed)
      Process.put({__MODULE__, :ua_control},
        %{epoch: -123, diagnostic: nil, diagnostic_phase: :admit, deadline: -1_000})
      token = ua_pe_bridge_begin()
      assert is_reference(token)
      try do
        value = %{seed | mount: pair.current}
        assert ua_control_seed_mismatch(value, seed) == :ok
        assert ua_pe_bridge_capture(value, seed, [:mount]) == :ok
        retained? = get_in(Process.get({__MODULE__, :ua_control}), [:ua_pe_capture, :state]) == pair
        assert retained?
        control = Process.delete({__MODULE__, :ua_control})
        ua_pe_bridge_stage(control, token)
        exact? = ua_pe_bridge_finish({false, primary}, token,
          ua_pe_b_sink(pair, primary), &ua_pe_b_mark/1) == {false, primary}
        assert exact?
        assert Process.get({__MODULE__, :ua_pe_b_events}) == [:sink, :stored]
      after
        ua_pe_bridge_clear(token)
      end
    end)
    for path <- [:normal, :rescue, :catch] do
      ua_pe_b_positive_handoff()
      ua_pe_b_isolated(fn ->
        {token, _seed, pair, primary} = ua_pe_b_synthetic_capture()
        caught = try do
          try do
            result = try do
              case path do
                :normal -> {false, primary}
                :rescue -> raise "SYNTHETIC_BRIDGE"
                :catch -> throw(:synthetic_bridge)
              end
            rescue
              _ -> {false, primary}
            catch
              :throw, :synthetic_bridge -> {false, primary}
            after
              control = Process.delete({__MODULE__, :ua_control})
              ua_pe_b_mark(:original_cleanup)
              ua_pe_bridge_stage(control, token)
            end
            exact? = ua_pe_bridge_finish(result, token, ua_pe_b_sink(pair, primary), &ua_pe_b_mark/1) == result
            assert exact?
            ua_pe_b_mark(:original_raise)
            throw(primary)
          after
            ua_pe_bridge_clear(token)
          end
        catch
          :throw, reason -> reason
        end
        exact? = caught == primary
        assert exact?
        assert Process.get({__MODULE__, :ua_pe_b_events}) ==
          [:original_cleanup, :sink, :stored, :original_raise]
        absent? = Process.get({__MODULE__, :ua_pe_bridge}) == nil
        assert absent?
      end)
    end

    for when_failure <- [:before_stage, :after_stage], kind <- [:error, :throw, :exit] do
      ua_pe_b_positive_handoff()
      ua_pe_b_isolated(fn ->
        {token, _seed, pair, primary} = ua_pe_b_synthetic_capture()
        reason = {:synthetic_cleanup, when_failure, kind}
        caught = try do
          try do
            control = Process.delete({__MODULE__, :ua_control})
            ua_pe_b_mark(:original_cleanup)
            if when_failure == :before_stage, do: ua_pe_b_fault(kind, reason)
            ua_pe_bridge_stage(control, token)
            ua_pe_b_fault(kind, reason)
            ua_pe_bridge_finish({false, primary}, token, ua_pe_b_sink(pair, primary), &ua_pe_b_mark/1)
          after
            ua_pe_bridge_clear(token)
          end
        catch
          actual_kind, actual_reason -> {actual_kind, actual_reason}
        end
        exact? = caught == {kind, reason}
        assert exact?
        absent? = Process.get({__MODULE__, :ua_pe_bridge}) == nil
        assert absent?
        assert Process.get({__MODULE__, :ua_pe_b_events}) == [:original_cleanup]
      end)
    end

    for failing <- [:sink, :emit], kind <- [:error, :throw, :exit] do
      ua_pe_b_positive_handoff()
      ua_pe_b_isolated(fn ->
        {token, _seed, pair, primary} = ua_pe_b_synthetic_capture()
        try do
          control = Process.delete({__MODULE__, :ua_control})
          ua_pe_bridge_stage(control, token)
          output = ExUnit.CaptureIO.capture_io(fn ->
            sink = fn actual, diagnostic ->
              exact? = actual == pair and diagnostic == primary
              assert exact?
              absent? = Process.get({__MODULE__, :ua_pe_bridge}) == nil
        assert absent?
              ua_pe_b_mark(:sink)
              if failing == :sink, do: ua_pe_b_fault(kind, "PRIVATE_BRIDGE_CANARY"), else: :stored
            end
            emit = fn status ->
              ua_pe_b_mark(status)
              if failing == :emit, do: ua_pe_b_fault(kind, "PRIVATE_BRIDGE_CANARY"), else: :ok
            end
            exact? = ua_pe_bridge_finish({false, primary}, token, sink, emit) == {false, primary}
            assert exact?
          end)
          assert output == ""
          assert Process.get({__MODULE__, :ua_pe_b_events}) ==
            [:sink, if(failing == :sink, do: :unexpected_exception, else: :stored)]
          absent? = Process.get({__MODULE__, :ua_pe_bridge}) == nil
        assert absent?
        after
          ua_pe_bridge_clear(token)
        end
      end)
    end

    for mutant <- [:invalid_primary, :missing_handoff, :corrupt_slot, :foreign_owner,
                   :wrong_epoch, :double_stage, :double_finish] do
      ua_pe_b_positive_handoff()
      ua_pe_b_isolated(fn ->
        {token, _seed, pair, primary} = ua_pe_b_synthetic_capture()
        try do
          key = {__MODULE__, :ua_pe_bridge}
          control = Process.delete({__MODULE__, :ua_control})
          case mutant do
            :corrupt_slot -> Process.put(key, :corrupt_owned)
            :foreign_owner -> Process.put(key, %{Process.get(key) | owner: :foreign})
            :wrong_epoch -> Process.put(key, %{Process.get(key) | epoch: 124})
            _ -> :ok
          end
          unless mutant == :missing_handoff, do: ua_pe_bridge_stage(control, token)
          if mutant == :double_stage do
            changed = put_in(control, [:ua_pe_capture, :state], ua_pe_armed())
            ua_pe_bridge_stage(changed, token)
          end
          diagnostic = if mutant == :invalid_primary, do: %{primary | line: 6297}, else: primary
          exact? = ua_pe_bridge_finish({false, diagnostic}, token,
            ua_pe_b_sink(pair, primary), &ua_pe_b_mark/1) == {false, diagnostic}
          assert exact?
          if mutant == :double_finish do
            again? = ua_pe_bridge_finish({false, primary}, token,
              ua_pe_b_sink(pair, primary), &ua_pe_b_mark/1) == {false, primary}
            assert again?
          end
          expected = case mutant do
            :invalid_primary -> [:primary_mismatch]
            valid when valid in [:double_stage, :double_finish] -> [:sink, :stored]
            _ -> []
          end
          assert Process.get({__MODULE__, :ua_pe_b_events}) == expected
          absent? = Process.get(key) == nil
          assert absent?
        after
          ua_pe_bridge_clear(token)
        end
      end)
    end

    for mutant <- [:foreign_slot, :nil_slot, :sentinel_slot, :capture_field, :nil_capture, :missing_epoch,
                   :bad_epoch, :missing_phase, :bad_diagnostic, :non_map] do
      ua_pe_b_positive_handoff()
      ua_pe_b_isolated(fn ->
        key = {__MODULE__, :ua_control}
        slot_key = {__MODULE__, :ua_pe_bridge}
        control = %{epoch: 123, diagnostic: nil, diagnostic_phase: :admit, deadline: 1_000}
        input = case mutant do
          :capture_field -> Map.put(control, :ua_pe_capture, %{token: make_ref(), state: ua_pe_armed()})
          :nil_capture -> Map.put(control, :ua_pe_capture, nil)
          :missing_epoch -> Map.delete(control, :epoch)
          :bad_epoch -> %{control | epoch: :corrupt}
          :missing_phase -> Map.delete(control, :diagnostic_phase)
          :bad_diagnostic -> %{control | diagnostic: :corrupt}
          :non_map -> :corrupt
          _ -> control
        end
        Process.put(key, input)
        if mutant == :foreign_slot, do: Process.put(slot_key, %{foreign: :PRIVATE_BRIDGE_CANARY})
        if mutant == :nil_slot, do: Process.put(slot_key, nil)
        if mutant == :sentinel_slot, do: Process.put(slot_key, :ua_pe_absent)
        sentinel = make_ref()
        before_slot = Process.get(slot_key, sentinel)
        token = ua_pe_bridge_begin()
        assert token == nil
        ua_pe_bridge_clear(token)
        unchanged? = Process.get(key) == input and Process.get(slot_key, sentinel) == before_slot
        assert unchanged?
        exact? = ua_pe_bridge_finish({false, :original}, token,
          fn _, _ -> ua_pe_b_mark(:unexpected_sink) end, &ua_pe_b_mark/1) == {false, :original}
        assert exact?
        assert Process.get({__MODULE__, :ua_pe_b_events}) == []
      end)
    end

    ua_pe_b_positive_handoff()
    ua_pe_b_isolated(fn ->
      {token, _seed, _pair, _primary} = ua_pe_b_synthetic_capture()
      try do
        Process.put({__MODULE__, :ua_pe_bridge}, {:corrupt, "PRIVATE_BRIDGE_CANARY"})
      after
        ua_pe_bridge_clear(token)
      end
      absent? = Process.get({__MODULE__, :ua_pe_bridge}) == nil
