  test "B03 literal forward reverse complete deltas six relations and added codec stay diagnostic" do
    ua_pe_b_positive()
    ua_pe_b_analysis_positive()
    for mutation <- [:options, :order, :unchanged, :duplicate, :bad_escape, :noncanonical] do
      {p, a, b, regions, a_row, b_row} = ua_pe_b_analysis_positive()
      case mutation do
        :options ->
          changed = String.replace(p, "rw,nosuid", "ro,nosuid") <> b
          forward? = ua_pe_analyze(p <> a, changed, regions) ==
            {:ok, %{removed: [a_row], labels: [:added, :removed, :options], acceptance: :rejected}}
          reverse? = ua_pe_analyze(changed, p <> a, regions) ==
            {:ok, %{removed: [b_row], labels: [:added, :removed, :options], acceptance: :rejected}}
          assert forward? and reverse?
        :order ->
          forward? = ua_pe_analyze(p <> a, a <> p, regions) ==
            {:ok, %{removed: [], labels: [:order], acceptance: :rejected}}
          reverse? = ua_pe_analyze(a <> p, p <> a, regions) ==
            {:ok, %{removed: [], labels: [:order], acceptance: :rejected}}
          assert forward? and reverse?
        :unchanged ->
          exact? = ua_pe_analyze(p <> a, p <> a, regions) ==
            {:ok, %{removed: [], labels: [], acceptance: :unchanged}}
          assert exact?
        invalid ->
          changed = case invalid do
            :duplicate -> p <> p
            :bad_escape -> String.replace(p, "/proc", "/bad\\999")
            :noncanonical -> String.replace(p, "/proc", "/proc/../other")
          end
          forward? = ua_pe_analyze(p <> a, changed, regions) == {:error, :invalid_input}
          reverse? = ua_pe_analyze(changed, p <> a, regions) == {:error, :invalid_input}
          assert forward? and reverse?
