    {p, _a, q, pair, primary, oracle} = ua_pe_b_literals()
    exact? = ua_pe_encode(pair, primary) == {:ok, oracle}
    assert exact?
    assert binary_part(oracle, 18, 2) == <<1::16>>
    reverse_pair = %{pair | seed: q, current: p, labels: [:removed]}
    reverse_primary = %{primary | mount_delta: [:removed]}
    seed_hash = :crypto.hash(:sha256, q)
    current_hash = :crypto.hash(:sha256, p)
    reverse_oracle = <<"T18MOUNT", 1, 4, 4, 2, 6298::32, 128::16, 2::16,
      byte_size(q)::32, byte_size(p)::32, seed_hash::binary-size(32),
      current_hash::binary-size(32), q::binary, p::binary>>
    reversed? = ua_pe_encode(reverse_pair, reverse_primary) == {:ok, reverse_oracle}
    assert reversed?
    ua_pe_b_positive()
    rejected? = ua_pe_decode(binary_part(oracle, 0, 92) <> q <> p) == {:error, :invalid_input}
    assert rejected?
  end
