  defp ua_mi_retained_additions?(previous, current) do
    with {:ok, old_lines} <- ua_text_lines(previous, 16_384),
         {:ok, old_rows} <- ua_mount_rows(old_lines, [], []),
         {:ok, new_lines} <- ua_text_lines(current, 16_384),
         {:ok, new_rows} <- ua_mount_rows(new_lines, [], []) do
      ua_mi_retain_rows?(old_rows, new_rows, MapSet.new(old_rows, & &1.id))
    else
      _ -> false
    end
  end

  defp ua_mi_retain_rows?(previous, [], _old_ids), do: previous == []
  defp ua_mi_retain_rows?(previous, [row | rest], old_ids) do
    if MapSet.member?(old_ids, row.id) do
      case previous do
        [old | remaining] ->
          old.id == row.id and old.raw == row.raw and
            ua_mi_retain_rows?(remaining, rest, old_ids)
        [] ->
          false
      end
    else
      ua_mi_path?(row.point) and
        not Enum.any?(ua_mi_routes().regions, fn region ->
          row.point == "/" or region == "/" or
            ua_covers?(row.point, region) or ua_covers?(region, row.point)
        end) and ua_mi_retain_rows?(previous, rest, old_ids)
    end
  end
