  # TASK18_SELECTED_COMMAND_FAULT_BEGIN
  # S1/S2 were authored before the adapters. Their synthetic values are never
  # available to the actual native producer below.
  test "selected-fault S1 preserves the original exception through one owned hold" do
    for mode <- [:abort, :observer_down, :expired, :observation_error,
                 :observation_throw, :observation_exit, :foreign_nonce] do
      positive = ua_sf_hold_contract(:sampled)
      assert is_boolean(positive)
      assert positive
      rejected = ua_sf_hold_contract(mode)
      assert is_boolean(rejected)
      assert rejected
    end
  end

  test "selected-fault S2 binds raw context and denies unproved transitions and hygiene" do
    {caller, ref} = spawn_monitor(fn -> receive do :stop -> :ok end end)
    try do
      owner = self()
      token = make_ref()
      reporter = fn value -> send(owner, {token, :reporter_called, value}) end
      raw = %{caller: caller, report_cleanup: reporter}
      {:ok, projected} = ua_sf_context_projection(raw, raw, owner, caller)
      different = make_ref()
      foreign = fn value -> send(owner, {different, :reporter_called, value}) end
      for changed <- [
        %{raw | report_cleanup: foreign}, %{raw | report_cleanup: fn -> :ok end},
        %{raw | report_cleanup: fn _, _ -> :ok end}, %{raw | caller: owner},
        Map.put(raw, :extra, token), nil, projected
      ] do
        positive = ua_sf_context_projection(raw, raw, owner, caller) == {:ok, projected}
        assert positive
        rejected = ua_sf_context_projection(changed, raw, owner, caller) == :error
        assert rejected
      end
      for changed <- [
        %{projected | caller: owner},
        %{projected | report_cleanup: {:task18_original_reporter, caller, reporter}},
        %{projected | report_cleanup: {:task18_original_reporter, owner, foreign}},
        %{projected | report_cleanup: {:foreign_tag, owner, reporter}},
        Map.put(projected, :extra, token)
      ] do
        positive = ua_sf_context_inverse?(projected, raw, owner, caller)
        assert positive
        rejected = not ua_sf_context_inverse?(changed, raw, owner, caller)
        assert rejected
      end
      binding = %{key: token, owner: owner, caller: caller, database: "S2",
        run: make_ref(), handle: {:handle, make_ref()}, timeout: 100, nonce: make_ref()}
      events = [
        {:primary, {owner, binding.run, :legacy_pipe}},
        {:await_entry, {owner, binding.handle, 100}},
        {:await_exception, {owner, :exit, {:killed,
          {ExCmd.Process, :await_exit, [binding.handle, 100]}}}},
        {:boundary_entry, {token, owner, caller, "S2", binding.nonce}}
      ]
      for permutation <- ua_sf_permutations(events) do
        reduced = Enum.reduce(permutation, {:ok, %{}}, &ua_sf_transition/2)
        positive = ua_sf_unlock_ready?(binding, reduced)
        assert positive
        for event <- events do
          missing = Enum.reject(permutation, &(&1 == event))
          rejected = not ua_sf_unlock_ready?(binding,
            Enum.reduce(missing, {:ok, %{}}, &ua_sf_transition/2))
          assert rejected
          duplicate = Enum.reduce(permutation ++ [event], {:ok, %{}}, &ua_sf_transition/2)
          assert duplicate == :error
        end
      end
      for {kind, payload} <- [
        {:primary, {owner, binding.run, :legacy_exit}},
        {:await_entry, {owner, binding.handle, 99}},
        {:await_exception, {owner, :error, :killed}},
        {:await_exception, {owner, :exit, {:killed,
          {ExCmd.Process, :await_exit, [{:foreign_handle}, 100]}}}},
        {:boundary_entry, {different, owner, caller, "S2", binding.nonce}}
      ] do
        positive = ua_sf_unlock_ready?(binding, Enum.reduce(events, {:ok, %{}}, &ua_sf_transition/2))
        assert positive
        changed = List.keyreplace(events, kind, 0, {kind, payload})
        rejected = not ua_sf_unlock_ready?(binding, Enum.reduce(changed, {:ok, %{}}, &ua_sf_transition/2))
        assert rejected
      end
      literal = ua_b_boundary_literal()
      schema = literal
        |> ua_sf_fixture_identity(:owner, owner)
        |> ua_sf_fixture_identity(:actor, caller)
      keys_preserved = ua_sf_structural_keys?(literal, schema) and
        not Map.has_key?(schema.expected, owner) and
        schema.expected.owner === owner and schema.expected.caller === caller and
        elem(schema.expected.handle, 4) === owner and
        {owner, :owner_ref} in schema.expected.original_monitors and
        {caller, :actor_ref} in schema.expected.original_monitors and
        Enum.any?(schema.events, fn
          {_, :boundary_entry, {:key, ^owner, ^caller, "A", :nonce}} -> true
          _ -> false
        end) and literal === ua_b_boundary_literal()
      assert keys_preserved
      schema = put_in(schema, [:expected, :context], projected)
      schema = put_in(schema, [:preconditions, :context], projected)
      provenance = %{raw: raw, observed: [raw], owner: owner, caller: caller}
      positive = ua_sf_protocol_bound?(schema, provenance)
      assert positive
      for changed <- [
        %{provenance | observed: []}, %{provenance | observed: [raw, raw]},
        %{provenance | observed: [%{raw | report_cleanup: foreign}]},
        %{provenance | raw: %{raw | report_cleanup: foreign}},
        %{provenance | observed: [projected]},
        %{provenance | raw: %{raw | report_cleanup: fn -> :ok end}},
        %{provenance | raw: %{raw | report_cleanup: fn _, _ -> :ok end}},
        %{provenance | owner: caller}
      ] do
        positive = ua_sf_protocol_bound?(schema, provenance)
        assert positive
        rejected = not ua_sf_protocol_bound?(schema, changed)
        assert rejected
      end
      # Counterfeit schema tokens must fail the combined path, not just the
      # standalone inverse; even two identical forged fields confer no credit.
      for counterfeit <- [
        %{projected | report_cleanup: {:task18_original_reporter, caller, reporter}},
        %{projected | report_cleanup: {:task18_original_reporter, owner, foreign}},
        %{projected | report_cleanup: {:foreign_tag, owner, reporter}},
        %{projected | report_cleanup: {:task18_original_reporter, owner, token}},
        %{projected | report_cleanup: {:task18_original_reporter, owner, fn -> :ok end}},
        %{projected | caller: owner}
      ], positions <- [[:expected], [:preconditions], [:expected, :preconditions]] do
        positive = ua_sf_protocol_bound?(schema, provenance)
        assert positive
        forged = Enum.reduce(positions, schema, fn position, acc ->
          put_in(acc, [position, :context], counterfeit)
        end)
        rejected = not ua_sf_protocol_bound?(forged, provenance)
        assert rejected
      end
      original = %{schema | events: Enum.reject(schema.events, &(elem(&1, 1) == :hygiene)),
        hygiene: :forbidden, credits: %{sample: true, recovery: false, hygiene: false}}
      for changed <- [
        put_in(original, [:measurement, :native, :replacement_seen], true),
        put_in(original, [:measurement, :baselines], []),
        put_in(original, [:measurement, :repos_after], %{}),
        put_in(original, [:helper, :primary], :legacy_exit),
        %{original | failures: [:unproved]}, %{original | hygiene: schema.hygiene},
        %{original | credits: %{sample: true, recovery: true, hygiene: true}},
        put_in(original, [:joins], tl(original.joins)),
        put_in(original, [:events], Enum.reject(original.events, &(elem(&1, 1) == :boundary_exit)))
      ] ++ Enum.map(Map.keys(original.restoration), &put_in(original, [:restoration, &1], false)) do
        positive = ua_sf_original_ready?(original, provenance)
        assert positive
        rejected = not ua_sf_original_ready?(changed, provenance)
        assert rejected
      end
      # Labelled synthetic projection: no SQL or native observation is performed.
      {result, context, expected, pools} = ua_sf_inventory_fixture(owner, caller)
      producer_roles = Enum.map(@transport_repos, fn repo ->
        Keyword.fetch!(repo.config(), :username)
      end)
      configured_roles = length(producer_roles) == 5 and
        length(Enum.uniq(producer_roles)) == 5 and
        Enum.sort(producer_roles) == Enum.sort(Map.keys(pools))
      assert configured_roles
      {:ok, measured} = ua_sf_project_inventory(result, context, expected, pools)
      baseline = Enum.reject(measured.triples, &(hd(&1) == expected.child_pid))
      raw_baseline = Enum.filter(result.rows, fn [pid, _, _] ->
        List.keymember?(expected.baseline, pid, 0)
      end)
      positive = ua_sf_projection_inverse?(measured, result, context, expected, pools) and
        measured.raw === result.rows and Enum.all?(raw_baseline, &(Enum.at(&1, 2) == nil)) and
        not ua_b_baseline?(raw_baseline, pools, 401, expected.child_pid) and
        ua_b_baseline?(baseline, pools, 401, expected.child_pid)
      assert positive
      for mutate <- ua_sf_inventory_mutants() do
        positive = ua_sf_project_inventory(result, context, expected, pools) == {:ok, measured}
        assert positive
        {bad_result, bad_context, bad_expected, bad_pools} =
          mutate.({result, context, expected, pools})
        rejected = ua_sf_project_inventory(bad_result, bad_context, bad_expected, bad_pools) == :error
        assert rejected
      end
      for forged <- [
        %{measured | raw: tl(measured.raw)},
        %{measured | origins: tl(measured.origins)},
        put_in(measured, [:origins, Access.at(0), :raw], [101, "singularity_migration", "client backend"]),
        put_in(measured, [:origins, Access.at(0), :before, :backend_start_us], 999),
        %{measured | expected: %{expected | operation: make_ref()}}
      ] do
        positive = ua_sf_projection_inverse?(measured, result, context, expected, pools)
        assert positive
        rejected = not ua_sf_projection_inverse?(forged, result, context, expected, pools)
        assert rejected
      end

      absence_expected = %{expected | stage: :absence}
      absence_context = %{context | stage: :absence,
        before: Enum.reject(context.before, &(&1.pid == expected.child_pid)),
        after: Enum.reject(context.after, &(&1.pid == expected.child_pid))}
      absence_result = %{result | rows: Enum.reject(result.rows, &(hd(&1) == expected.child_pid)),
        num_rows: result.num_rows - 1}
      {:ok, absent} = ua_sf_project_inventory(absence_result, absence_context, absence_expected, pools)
      positive = absent.triples === baseline and
        ua_sf_projection_inverse?(absent, absence_result, absence_context, absence_expected, pools)
      assert positive
      other_expected = %{expected | operation: make_ref()}
      other_context = %{context | operation: other_expected.operation, sequence: 2}
      {:ok, other_capture} = ua_sf_project_inventory(result, other_context, other_expected, pools)
      positive = ua_sf_projection_inverse?(measured, result, context, expected, pools)
      assert positive
      reused = not ua_sf_projection_inverse?(other_capture, result, context, expected, pools)
      assert reused

      # Same finite executor and plan used by actual cleanup; actions below
      # inject only synthetic failures, never real resource operations.
      monitors = Map.new(1..13, &{make_ref(), {:synthetic_resource, &1}})
      cleanup = %{monitors: monitors, flags: %{owner => :synthetic_flags}}
      plan = ua_sf_cleanup_plan(cleanup, %{fds: [:synthetic_fd_a, :synthetic_fd_b]})
      for failing <- plan do
        positive = ua_sf_cleanup_contract(plan, nil, monitors)
        assert positive
        isolated = ua_sf_cleanup_contract(plan, failing, monitors)
        assert isolated
      end
      # Hygiene acquires these labelled synthetic identities AFTER the original
      # cleanup plan. Both normal/after routes must share one-shot outcomes.
      for count <- 0..2, prior <- [false, true],
          failure <- [nil, :first_fd, :second_fd, :fd_verify, :stop, :join, :retire] do
        positive = ua_sf_hygiene_cleanup_contract(count, false, nil, caller)
        assert positive
        isolated = ua_sf_hygiene_cleanup_contract(count, prior, failure, caller)
        assert isolated
      end
      uncalled = receive do {^token, :reporter_called, _} -> false after 0 -> true end
      assert uncalled
    after
      send(caller, :stop)
      receive do {:DOWN, ^ref, :process, ^caller, :normal} -> :ok after 1_000 -> flunk("S2 closure") end
    end
  end

  defp ua_sf_context_projection(raw, retained, owner, caller) do
    with true <- is_pid(owner) and is_pid(caller) and owner != caller,
         true <- ua_b_keys?(raw, [:caller, :report_cleanup]),
         true <- raw === retained and raw.caller === caller,
         true <- is_function(raw.report_cleanup, 1) do
      {:ok, %{caller: caller,
        report_cleanup: {:task18_original_reporter, owner, raw.report_cleanup}}}
    else
      _ -> :error
    end
  end

  defp ua_sf_context_inverse?(encoded, raw, owner, caller) do
    with true <- ua_b_keys?(encoded, [:caller, :report_cleanup]),
         %{caller: ^caller, report_cleanup: {:task18_original_reporter, ^owner, fun}} <- encoded,
         true <- is_function(fun, 1),
         {:ok, ^encoded} <- ua_sf_context_projection(%{caller: caller, report_cleanup: fun},
           raw, owner, caller) do
      true
    else
      _ -> false
    end
  end

  defp ua_sf_binding?(facts, %{raw: raw, observed: [observed], owner: owner, caller: caller}) do
    with true <- facts.expected.owner === owner and facts.expected.caller === caller,
         {:ok, projected} <- ua_sf_context_projection(observed, raw, owner, caller),
         true <- facts.expected.context === projected and facts.preconditions.context === projected do
      ua_sf_context_inverse?(facts.expected.context, raw, owner, caller) and
        ua_sf_context_inverse?(facts.preconditions.context, raw, owner, caller)
    else
      _ -> false
    end
  end
  defp ua_sf_binding?(_, _), do: false

  defp ua_sf_protocol_bound?(facts, provenance),
    do: ua_sf_binding?(facts, provenance) and ua_boundary_protocol?(facts)

  defp ua_sf_transition({kind, payload}, {:ok, entries})
       when kind in [:primary, :await_entry, :await_exception, :boundary_entry] do
    if Map.has_key?(entries, kind), do: :error, else: {:ok, Map.put(entries, kind, payload)}
  end
  defp ua_sf_transition(_, _), do: :error

  defp ua_sf_unlock_ready?(b, {:ok, e}) do
    ua_b_keys?(e, [:primary, :await_entry, :await_exception, :boundary_entry]) and
      e.primary === {b.owner, b.run, :legacy_pipe} and
      e.await_entry === {b.owner, b.handle, b.timeout} and
      e.await_exception === {b.owner, :exit,
        {:killed, {ExCmd.Process, :await_exit, [b.handle, b.timeout]}}} and
      e.boundary_entry === {b.key, b.owner, b.caller, b.database, b.nonce}
  end
  defp ua_sf_unlock_ready?(_, _), do: false

  defp ua_sf_original_ready?(f, provenance) do
    with true <- ua_sf_binding?(f, provenance),
         true <- f.mode == :sampled and f.failures == [] and f.hygiene == :forbidden,
         true <- f.credits == %{sample: true, recovery: false, hygiene: false},
         true <- ua_b_protocol_expected?(f.expected),
         true <- f.registration_origin ===
           Map.take(f.expected, [:private_key, :tag, :run, :caller, :observer]),
         true <- ua_b_measurement?(f.measurement, f.expected, :sampled),
         true <- ua_b_preconditions?(f.preconditions, f.expected, f.measurement.native.original),
         true <- ua_b_helper?(f.helper) and ua_b_terminal?(f.terminal),
         true <- ua_b_restoration?(f.restoration) and ua_b_retention?(f.retention, f.expected),
         {:ok, events} <- ua_b_events(f.events, f.expected.deadline),
         true <- ua_b_common_events?(events, f.caught, f.expected, f.measurement),
         true <- ua_b_gate?(f.gate, f.expected, f.measurement.native, events),
         true <- ua_b_mailbox?(f.mailbox_arrival),
         {:ok, []} <- ua_b_joins(f.joins, f.expected, f.measurement.native, events),
         true <- ua_b_boundary_entry?(events, f.expected, f.measurement.native),
         true <- elem(f.caught, 0) == :throw,
         true <- elem(f.caught, 1) == {:legacy_preparation_failed, :legacy_pipe},
         true <- ua_b_event?(events, :boundary_exit, {f.expected.owner, f.expected.nonce, :sampled}),
         true <- ua_b_event?(events, :continuation,
           {f.expected.private_key, f.expected.observer, f.expected.owner, f.expected.nonce, :sampled}),
         true <- ua_b_increasing?([List.last(f.measurement.sample_times),
           ua_b_event_at(events, :continuation), ua_b_event_at(events, :boundary_exit),
           ua_b_event_at(events, :rethrow)]) do
      true
    else
      _ -> false
    end
  rescue
    _ -> false
  catch
    _, _ -> false
  end

  defp ua_sf_permutations([]), do: [[]]
  defp ua_sf_permutations(items),
    do: for(item <- items, rest <- ua_sf_permutations(List.delete(items, item)), do: [item | rest])

  # Labelled S2-only identity substitution. The operational route never calls it.
  defp ua_sf_fixture_identity(value, from, to) when value === from, do: to
  defp ua_sf_fixture_identity(value, from, to) when is_map(value),
    do: Map.new(value, fn {key, item} ->
      {key, ua_sf_fixture_identity(item, from, to)}
    end)
  defp ua_sf_fixture_identity(value, from, to) when is_tuple(value),
    do: value |> Tuple.to_list() |> Enum.map(&ua_sf_fixture_identity(&1, from, to)) |> List.to_tuple()
  defp ua_sf_fixture_identity(value, from, to) when is_list(value),
    do: Enum.map(value, &ua_sf_fixture_identity(&1, from, to))
  defp ua_sf_fixture_identity(value, _, _), do: value


  defp ua_sf_structural_keys?(original, changed) when is_map(original) and is_map(changed) do
    Enum.sort(Map.keys(original)) == Enum.sort(Map.keys(changed)) and
      Enum.all?(original, fn {key, value} -> ua_sf_structural_keys?(value, changed[key]) end)
  end
  defp ua_sf_structural_keys?(original, changed) when is_tuple(original) and is_tuple(changed),
    do: ua_sf_structural_keys?(Tuple.to_list(original), Tuple.to_list(changed))
  defp ua_sf_structural_keys?(original, changed) when is_list(original) and is_list(changed),
    do: length(original) == length(changed) and
      Enum.all?(Enum.zip(original, changed), fn {left, right} -> ua_sf_structural_keys?(left, right) end)
  defp ua_sf_structural_keys?(original, changed),
    do: not is_map(original) and not is_map(changed)

  # Pure adapter. The ordinary result stays intact; measured schema fields have
  # explicit links to this operation's original row and both metadata records.
  defp ua_sf_project_inventory(%Postgrex.Result{rows: raw} = result, context, expected, pools) do
    with true <- result.command == :select and
           result.columns == ["pid", "usename", "backend_type"] and result.num_rows == length(raw),
         {:ok, {pairs, workers}} <- transport_backend_inventory({:ok, result}, context, expected),
         true <- expected.columns == 3 and expected.stage in [:gate, :absence],
         true <- Enum.sort(Map.keys(pools)) == Enum.sort(~w(singularity_migration singularity_web singularity_pre_auth singularity_dispatcher singularity_worker)),
         true <- Enum.all?(pools, fn {_, count} -> is_integer(count) and count > 0 end),
         true <- expected.baseline == Enum.sort(expected.baseline) and
           Enum.frequencies_by(expected.baseline, &elem(&1, 1)) == pools,
         required <- if(expected.stage == :gate,
           do: Enum.sort([{expected.child_pid, "singularity_migration"} | expected.baseline]),
           else: expected.baseline),
         true <- pairs === required,
         true <- Enum.sort(Enum.map(context.after, & &1.pid)) == Enum.sort(Enum.map(raw, &hd/1)) do
      origins = Enum.with_index(raw, fn [pid, name, visible] = row, index ->
        [before] = Enum.filter(context.before, &(&1.pid == pid))
        [after_sample] = Enum.filter(context.after, &(&1.pid == pid))
        true = before === after_sample and before.datid == expected.database_oid
        kind =
          if {pid, name} in pairs do
            true = is_integer(before.usesysid) and before.usesysid > 0 and
              is_integer(before.backend_start_us) and before.backend_start_us > 0 and
              before.backend_type == "client backend" and
              (visible == nil or visible === before.backend_type)
            :client
          else
            [worker] = Enum.filter(workers, &(&1.pid == pid))
            true = worker === Map.take(before, [:pid, :datid, :usesysid, :backend_type, :backend_start_us])
            :worker
          end
        %{index: index, raw: row, before: before, after: after_sample, kind: kind}
      end)
      triples = for %{kind: :client, raw: [pid, name, _], before: metadata} <- origins,
        do: [pid, name, metadata.backend_type]
      true = Enum.map(triples, fn [pid, name, _] -> {pid, name} end) === pairs and
        length(raw) == length(triples) + length(workers)
      {:ok, %{result: result, raw: raw, context: context, expected: expected,
        pool_counts: pools, pairs: pairs, workers: workers, triples: triples, origins: origins}}
    else
      _ -> :error
    end
  rescue
    _ -> :error
  catch
    _, _ -> :error
  end
  defp ua_sf_project_inventory(_, _, _, _), do: :error

  defp ua_sf_projection_inverse?(projection, result, context, expected, pools) do
    case ua_sf_project_inventory(result, context, expected, pools) do
      {:ok, original} ->
        projection === original and
          Enum.map(projection.origins, & &1.raw) === result.rows and
          Enum.map(projection.origins, & &1.index) === Enum.to_list(0..(length(result.rows) - 1))
      :error -> false
    end
  end

  defp ua_sf_inventory_fixture(owner, caller) do
    names = ~w(singularity_migration singularity_web singularity_pre_auth singularity_dispatcher singularity_worker)
    baseline = Enum.with_index(names, 101) |> Enum.map(fn {name, pid} -> {pid, name} end)
    rows = Enum.map(baseline, fn {pid, name} -> [pid, name, nil] end) ++
      [[501, "singularity_migration", "client backend"], [601, nil, nil]]
    metadata = Enum.map(rows, fn [pid, name, _] ->
      %{pid: pid, datid: 7001, usesysid: if(name, do: 1000 + pid, else: nil),
        backend_type: if(name, do: "client backend", else: "autovacuum worker"),
        backend_start_us: 100_000 + pid}
    end)
    expected = %{observer: owner, key: make_ref(), operation: make_ref(), nonce: make_ref(),
      ordinary: caller, admin: {caller, make_ref()}, custodian: {owner, make_ref()},
      database: "S2", database_oid: 7001, stage: :gate, columns: 3, baseline: baseline, child_pid: 501}
    context = Map.merge(expected, %{authority: :verified, capture: :complete, sequence: 1,
      before_ns: 1, query_before_ns: 2, query_after_ns: 3, after_ns: 4,
      before: metadata ++ [%{pid: 701, datid: 7001, usesysid: 1701,
        backend_type: "client backend", backend_start_us: 100_701}], after: metadata})
    result = %Postgrex.Result{command: :select, columns: ["pid", "usename", "backend_type"],
      rows: rows, num_rows: length(rows)}
    {result, context, expected, Map.new(names, &{&1, 1})}
  end

  defp ua_sf_inventory_mutants do
    metadata = for side <- [:before, :after],
      {field, value} <- [pid: 999, datid: 7002, usesysid: nil,
        backend_start_us: 0, backend_type: "autovacuum worker"] do
      fn {r, c, e, p} ->
        {r, update_in(c, [side, Access.at(0)], &Map.put(&1, field, value)), e, p}
      end
    end
    bindings = for field <- [:operation, :key, :nonce, :observer, :ordinary, :admin, :custodian,
        :database, :database_oid, :stage, :columns, :baseline, :child_pid] do
      fn {r, c, e, p} -> {r, Map.put(c, field, :foreign), e, p} end
    end
    role_names = for {from, to} <- [
      {"singularity_web", "singularity_request"},
      {"singularity_pre_auth", "singularity_preauth"},
      {"singularity_worker", "unexpected_worker"}
    ] do
      fn {r, c, e, p} ->
        rename = fn name -> if name == from, do: to, else: name end
        baseline = Enum.map(e.baseline, fn {pid, name} -> {pid, rename.(name)} end)
        rows = Enum.map(r.rows, fn [pid, name, kind] -> [pid, rename.(name), kind] end)
        pools = p |> Map.delete(from) |> Map.put(to, Map.fetch!(p, from))
        {%{r | rows: rows}, %{c | baseline: baseline}, %{e | baseline: baseline}, pools}
      end
    end
    metadata ++ bindings ++ role_names ++ [
      fn {r, c, e, p} -> {r, %{c | before: tl(c.before)}, e, p} end,
      fn {r, c, e, p} -> {r, %{c | after: tl(c.after)}, e, p} end,
      fn {r, c, e, p} -> {r, %{c | before: [hd(c.before) | c.before]}, e, p} end,
      fn {r, c, e, p} -> {r, %{c | after: [hd(c.after) | c.after]}, e, p} end,
      fn {r, c, e, p} -> {r, %{c | authority: :failed}, e, p} end,
      fn {r, c, e, p} -> {r, %{c | capture: :overflow}, e, p} end,
      fn {r, c, e, p} -> {r, %{c | after_ns: 0}, e, p} end,
      fn {r, c, e, p} -> {r, %{c | operation: make_ref()}, e, p} end,
      fn {r, c, e, p} -> {%{r | rows: List.update_at(r.rows, 0, &List.replace_at(&1, 2, "parallel worker"))}, c, e, p} end,
      fn {r, c, e, p} -> {%{r | rows: List.update_at(r.rows, 0, &List.replace_at(&1, 1, nil))}, c, e, p} end,
      fn {r, c, e, p} -> {%{r | rows: r.rows ++ [[999, "unknown", nil]], num_rows: r.num_rows + 1}, c, e, p} end,
      fn {r, c, e, p} -> {r, c, e, Map.put(p, "singularity_web", 2)} end,
      fn {r, c, e, p} -> {r, c, e, Map.delete(p, "singularity_web")} end,
      fn {r, c, e, p} -> {r, c, e, Map.put(p, "unexpected_role", 1)} end,
      fn {r, c, e, p} -> {r, c, %{e | child_pid: 101}, p} end,
      fn {r, c, e, p} ->
        change = fn rows -> Enum.map(rows, fn row ->
          if row.pid == 601, do: %{row | usesysid: 123}, else: row
        end) end
        {r, %{c | before: change.(c.before), after: change.(c.after)}, e, p}
      end,
      fn {r, c, e, p} ->
        change = fn rows -> List.update_at(rows, 0, &%{&1 | backend_type: "parallel worker"}) end
        {r, %{c | before: change.(c.before), after: change.(c.after)}, e, p}
      end
    ]
  end

  # Exactly one selective receive; the surrounding after always raises the
  # originally caught tuple. No observer exception can replace it.
  defp ua_sf_hold(b, {kind, value, stack} = original) do
    try do
      send(b.audit, {b.key, :sf_caught, self(), original, b.context, System.monotonic_time()})
      if kind == :throw and value == {:legacy_preparation_failed, :legacy_pipe} do
        nonce = make_ref()
        monitors_before = Process.info(self(), :monitors)
        observer_ref = Process.monitor(b.observer)
        try do
          send(b.observer, {b.key, :sf_boundary, self(), b.caller, b.database,
            nonce, original, b.context, System.monotonic_time()})
          result =
            receive do
              {key, :sf_continue, observer, owner, ^nonce, decision}
                  when key == b.key and observer == b.observer and owner == self() and
                    decision in [:sampled, :abort] ->
                decision
              {:DOWN, ^observer_ref, :process, observer, _} when observer == b.observer ->
                :observer_down
            after
              max(0, b.deadline - System.monotonic_time(:millisecond)) -> :timeout
            end
          send(b.audit, {b.key, :sf_boundary_exit, self(), nonce, result,
            System.monotonic_time()})
        after
          Process.demonitor(observer_ref, [:flush])
          send(b.audit, {b.key, :sf_hold_monitor, self(), nonce,
            Process.info(self(), :monitors) == monitors_before})
        end
      end
    after
      send(b.audit, {b.key, :sf_rethrow, self(), original, System.monotonic_time()})
      :erlang.raise(kind, value, stack)
    end
  end

  defp ua_sf_hold_contract(mode) do
    parent = self()
    key = make_ref()
    {observer, observer_ref} =
      if mode == :observer_down do
        spawn_monitor(fn ->
          receive do
            {^key, :sf_boundary, owner, caller, database, nonce, original, raw, at} ->
              send(parent, {key, :contract_boundary, owner, caller, database, nonce, original, raw, at})
          end
        end)
      else
        {parent, nil}
      end
    reporter = fn status -> send(parent, {key, :reporter_called, status}) end
    raw = %{caller: parent, report_cleanup: reporter}
    deadline = System.monotonic_time(:millisecond) + if(mode == :expired, do: 0, else: 1_000)
    {owner, ref} = spawn_monitor(fn ->
      # Only S1 uses its already-owned controller as audit witness when the
      # synthetic observer dies. The actual constructor fixes audit=observer.
      b = %{key: key, observer: observer, audit: parent, caller: parent, database: "S1",
        context: raw, deadline: deadline}
      outcome =
        try do
          try do
            throw({:legacy_preparation_failed, :legacy_pipe})
          catch
            kind, value ->
              original = {kind, value, __STACKTRACE__}
              send(parent, {key, :contract_original, self(), original})
              ua_sf_hold(b, original)
          end
        catch
          kind, value -> {kind, value, __STACKTRACE__}
        end
      send(parent, {key, :contract_result, self(), outcome})
    end)
    try do
      original = receive do {^key, :contract_original, ^owner, original} -> original after 1_000 -> nil end
      witnessed = receive do
        {^key, :sf_caught, ^owner, tuple, ^raw, at} -> {tuple, at}
      after 1_000 -> nil end
      boundary = receive do
        {^key, type, ^owner, ^parent, "S1", nonce, caught, ^raw, at}
            when type in [:sf_boundary, :contract_boundary] -> {nonce, caught, at}
      after
        1_000 -> nil
      end
      case boundary do
        {nonce, caught, entry_at} ->
          if mode == :foreign_nonce do
            send(owner, {key, :sf_continue, observer, owner, make_ref(), :abort})
          end
          decision = if mode in [:sampled, :foreign_nonce], do: :sampled, else: :abort
          unless mode in [:expired, :observer_down] do
            try do
              case mode do
                :observation_error -> raise ArgumentError, "S1"
                :observation_throw -> throw(:s1)
                :observation_exit -> exit(:s1)
                _ -> :ok
              end
            catch
              _, _ -> :ok
            after
              send(owner, {key, :sf_continue, observer, owner, nonce, decision})
            end
          end
          exit_event = receive do
            {^key, :sf_boundary_exit, ^owner, ^nonce, outcome, at} -> {outcome, at}
          after 1_000 -> :missing end
          monitor_restored = receive do
            {^key, :sf_hold_monitor, ^owner, ^nonce, restored} -> restored
          after 1_000 -> false end
          rethrow = receive do
            {^key, :sf_rethrow, ^owner, tuple, at} -> {tuple, at}
          after 1_000 -> nil end
          result = receive do {^key, :contract_result, ^owner, tuple} -> tuple after 1_000 -> nil end
          down = receive do {:DOWN, ^ref, :process, ^owner, :normal} -> true after 1_000 -> false end
          observer_closed = if observer_ref do
            receive do {:DOWN, ^observer_ref, :process, ^observer, :normal} -> true after 1_000 -> false end
          else
            true
          end
          uncalled = receive do {^key, :reporter_called, _} -> false after 0 -> true end
          expected = case mode do
            :expired -> :timeout
            :observer_down -> :observer_down
            value when value in [:sampled, :foreign_nonce] -> :sampled
            _ -> :abort
          end
          case {witnessed, exit_event, rethrow} do
            {{^original, caught_at}, {^expected, exit_at}, {^original, rethrow_at}} ->
              original != nil and caught === original and result === original and
                caught_at < entry_at and entry_at < exit_at and exit_at < rethrow_at and
                monitor_restored and down and observer_closed and uncalled
            _ -> false
          end
        _ -> false
      end
    after
      Process.demonitor(ref, [:flush])
      if observer_ref, do: Process.demonitor(observer_ref, [:flush])
    end
  end

  defp ua_sf_state, do: Process.get({__MODULE__, :ua_sf})
  defp ua_sf_put(fields), do: Process.put({__MODULE__, :ua_sf}, Map.merge(ua_sf_state(), fields))
  defp ua_sf_stage(stage), do: ua_sf_put(%{stage: stage})
  defp ua_sf_time, do: System.monotonic_time()
  defp ua_sf_relative(at), do: at - ua_sf_state().epoch
  defp ua_sf_remaining do
    remaining = ua_sf_state().deadline - System.monotonic_time(:millisecond)
    transport_require!(remaining > 0)
    remaining
  end
  defp ua_sf_cleanup_remaining,
    do: max(0, min(1_000, ua_sf_state().deadline - System.monotonic_time(:millisecond)))
  defp ua_sf_require(value), do: transport_require!(value)

  defp ua_sf_run? do
    transport_entrypoint!()
    ua_sf_require(Process.get({__MODULE__, :ua_sf}) == nil and
      Process.get({__MODULE__, :ua_control}) == nil)
    clean = ua_sf_case(:clean, nil)
    if clean == {:ok, :closed}, do: ua_sf_case(:fault, clean) == {:ok, :qualified}, else: false
  end

  defp ua_sf_case(mode, clean) do
    epoch = ua_sf_time()
    deadline = System.monotonic_time(:millisecond) + 50_000
    baseline = transport_cleanup_baseline(deadline)
    environment = System.get_env()
    dictionary = Enum.map([:diagnostic6_baseline_phase, :diagnostic6_baseline_query_result,
      :diagnostic6_first_sample, :transport_baseline_migration], fn field ->
      key = {__MODULE__, field}
      {key, key in Process.get_keys(), Process.get(key)}
    end)
    key = make_ref()
    initial = %{key: key, mode: mode, clean: clean, epoch: epoch, deadline: deadline,
      baseline: baseline, environment: environment, dictionary: dictionary,
      events: [], transition: {:ok, %{}},
      arrival: [], monitors: %{}, downs: %{}, join_attempts: %{}, checkpoints: %{}, helper: [],
      contexts: [], reporter: [], traces: [], flags: %{}, session: nil,
      raw: nil, actor: nil, owner: nil, connection: nil, nonce: nil,
      locked: false, release_sent: false, errors: [], first_failure: nil,
      stage: :acquisition, privacy: [], serial: 0, cleanup_steps: %{}}
    Process.put({__MODULE__, :ua_sf}, initial)
    result =
      try do
        logs = ExUnit.CaptureLog.capture_log(fn ->
          stderr = ExUnit.CaptureIO.capture_io(:stderr, fn ->
            stdout = ExUnit.CaptureIO.capture_io(fn ->
              try do
                ua_sf_original(mode)
              rescue
                error -> ua_sf_failure(:original, :error, error, __STACKTRACE__)
              catch
                kind, value -> ua_sf_failure(:original, kind, value, __STACKTRACE__)
              after
                ua_sf_finalize_original()
              end
            end)
            ua_sf_put(%{stdout: not transport_contains?(stdout)})
          end)
          ua_sf_put(%{stderr: not transport_contains?(stderr)})
        end)
        ua_sf_put(%{logger: not transport_contains?(logs)})
        ua_sf_complete_restoration()
        if mode == :clean do
          ua_sf_stage(:clean_closure)
          ua_sf_clean_final()
          {:ok, :closed}
        else
          ua_sf_stage(:original_proof)
          facts = ua_sf_facts()
          provenance = ua_sf_provenance()
          ua_sf_require(ua_sf_original_ready?(facts, provenance))
          hygiene = ua_sf_hygiene(facts)
          ua_sf_event(:hygiene, :independent, ua_sf_time())
          completed = %{facts | hygiene: hygiene, events: ua_sf_events(),
            credits: %{sample: true, recovery: true, hygiene: true}}
          ua_sf_stage(:final_protocol)
          ua_sf_require(ua_sf_protocol_bound?(completed, provenance))
          {:ok, :qualified}
        end
      rescue
        error ->
          ua_sf_failure(:original, :error, error, __STACKTRACE__)
          {:error, :selected_fault_proof}
      catch
        kind, value ->
          ua_sf_failure(:original, kind, value, __STACKTRACE__)
          {:error, :selected_fault_proof}
      end
    evidence = ua_sf_last_cleanup()
    if evidence.errors == [] do
      result
    else
      # Fixed source-owned atoms/counts only; never Inspect original exception,
      # context, SQL/proc payload, frame, stack, function or content.
      first = evidence.first_failure
      IO.puts("task18_selected_fault=" <> Atom.to_string(mode) <>
        " stage=" <> Atom.to_string(first.stage) <> " class=" <> Atom.to_string(first.kind) <>
        " site_line=" <> Integer.to_string(first.site_line) <>
        " cleanup_failures=" <> Integer.to_string(Enum.count(evidence.errors, &(&1.scope == :cleanup))))
      evidence.errors
      |> Enum.filter(&(&1.scope == :cleanup))
      |> Enum.frequencies_by(&{&1.stage, &1.kind, &1.site_line})
      |> Enum.sort()
      |> Enum.each(fn {{stage, kind, line}, count} ->
        IO.puts("task18_selected_cleanup stage=" <> Atom.to_string(stage) <>
          " class=" <> Atom.to_string(kind) <> " site_line=" <> Integer.to_string(line) <>
          " count=" <> Integer.to_string(count))
      end)
      {:error, evidence}
    end
  end

  defp ua_sf_failure(scope, kind, value, stack) do
    s = ua_sf_state()
    failure = ua_sf_failure_fact(scope, s.stage, kind, value, stack)
    ua_sf_put(%{errors: s.errors ++ [failure], first_failure: s.first_failure || failure})
    :ok
  end

  defp ua_sf_failure_fact(scope, stage, kind, value, stack) do
    allowed = [:ua_sf_original, :ua_sf_gate, :ua_sf_wait_child, :ua_sf_inventory,
      :ua_sf_clean_measure, :ua_sf_fault, :ua_sf_cleanup_action, :ua_sf_until,
      :ua_sf_trace_call, :ua_sf_trace_return, :ua_sf_receive, :ua_sf_complete_restoration,
      :ua_sf_clean_final, :ua_sf_native_live, :ua_sf_baseline_bracket, :ua_sf_remaining]
    line = Enum.find_value(stack, 0, fn
      {__MODULE__, function, _, location} when is_list(location) ->
        if function in allowed do
          case Keyword.get(location, :line) do
            number when is_integer(number) and number >= 20_525 and number <= 100_000 -> number
            _ -> nil
          end
        end
      _ -> nil
    end)
    %{scope: scope, stage: stage, kind: kind, value: value, stack: stack, site_line: line}
  end

  defp ua_sf_event(kind, payload, at) do
    s = ua_sf_state()
    ua_sf_require(is_integer(at) and at >= s.epoch and
      not Enum.any?(s.events, &(elem(&1, 1) == kind)))
    updates = %{events: s.events ++ [{at, kind, payload}]}
    updates = if kind in [:primary, :await_entry, :await_exception, :boundary_entry],
      do: Map.merge(updates, %{transition: ua_sf_transition({kind, payload}, s.transition),
        arrival: s.arrival ++ [kind]}), else: updates
    ua_sf_put(updates)
    :ok
  end

  defp ua_sf_events, do: Enum.map(ua_sf_state().events, fn {at, kind, payload} ->
    {ua_sf_relative(at), kind, payload}
  end)
  defp ua_sf_at(kind), do: ua_sf_state().events |> Enum.find(&(elem(&1, 1) == kind)) |> elem(0)

  defp ua_sf_monitor(id) do
    s = ua_sf_state()
    ua_sf_require(not Enum.any?(s.monitors, fn {_, value} -> value == id end))
    ref = if is_port(id), do: :erlang.monitor(:port, id), else: Process.monitor(id)
    ua_sf_put(%{monitors: Map.put(s.monitors, ref, id)})
    ref
  end

  defp ua_sf_original(mode) do
    ua_sf_init_proc()
    ua_sf_telemetry_open()
    observer = self()
    s = ua_sf_state()
    {actor, ref} = spawn_monitor(fn -> ua_sf_actor(observer, s.key, s.deadline, mode) end)
    ua_sf_put(%{actor: actor, monitors: %{ref => actor}})
    # Registration key/observer/caller/tag exist before this permission is sent.
    ua_sf_put(%{allocated: ua_sf_time(), lexical: %{private_key: s.key,
      observer: observer, caller: actor, tag: @transport_tag}})
    send(actor, {s.key, :sf_allocate, observer})
    ua_sf_until(fn current -> current.raw != nil end)
    s = ua_sf_state()
    ua_sf_require(is_pid(s.owner) and s.owner != actor and s.raw.caller == actor and
      ua_b_keys?(s.raw, [:caller, :report_cleanup]) and is_function(s.raw.report_cleanup, 1))
    ua_sf_monitor(s.owner)
    origin = s.origins
    ua_sf_require(origin.owner == s.owner and origin.caller == actor and
      origin.names.database == s.destination.database and map_size(origin.repos) == 5)
    Enum.each(Map.values(origin.repos) ++ [origin.maintenance], &ua_sf_monitor/1)
    options = Singularity.Storage.MigrationRepo.config()
      |> Keyword.drop([:url, :name])
      |> Keyword.put(:pool_size, 1) |> Keyword.put(:pool_count, 1)
      |> Keyword.put(:database, s.destination.database)
      |> Keyword.put(:parameters, application_name: @transport_observer_tag)
    ua_sf_require(options[:username] == "singularity_migration")
    {:ok, connection} = Postgrex.start_link(options)
    Process.unlink(connection)
    ua_sf_put(%{connection: connection, connection_options: options})
    ua_sf_monitor(connection)
    transport_attribution_open(s.key, connection, s.destination.database, :clean_frame)
    expected = transport_warm_repos()
    pairs = transport_parent_baseline(connection, s.destination.database, expected, nil,
      min(s.deadline, System.monotonic_time(:millisecond) + 5_000))
    [[observer_backend, "singularity_migration", database]] =
      ua_sf_rows("SELECT pg_backend_pid(),current_user,current_database()", [])
    ua_sf_require(database == s.destination.database)
    [[oid]] = ua_sf_rows("SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [database])
    ua_sf_put(%{pools: expected, pairs: pairs, observer_backend: observer_backend, oid: oid,
      repos: origin.repos, maintenance: origin.maintenance})
    ua_sf_stage(:gate_acquisition)
    ua_sf_rows("SELECT pg_advisory_lock($1::integer,$2::integer)", @transport_lock)
    ua_sf_put(%{locked: true})
    ua_sf_trace_open()
    send(s.owner, {s.key, :sf_armed, observer})
    ua_sf_until(fn current -> Map.has_key?(current, :receive) and Map.has_key?(current, :started) and
      length(current.contexts) == 1 and Map.has_key?(current, :launch) end)
    ua_sf_stage(:native_admission)
    ua_sf_admit()
    s = ua_sf_state()
    send(s.owner, {s.run, :observer_ready, observer})
    ua_sf_put(%{ready_sent: true})
    ua_sf_stage(:gate_samples)
    ua_sf_gate()
    if mode == :clean do
      ua_sf_unlock()
      ua_sf_until(fn current -> Map.has_key?(current.checkpoints, :ready) and
        Map.has_key?(current, :actor_result) end)
      ua_sf_clean_measure()
      ua_sf_close_clean_connection()
      current = ua_sf_state()
      ua_sf_require(current.errors == [] and Map.has_key?(current, :clean_connection_join))
      ua_sf_cleanup_run([:actor_release])
    else
      ua_sf_fault()
    end
    ua_sf_until(fn current ->
      Map.has_key?(current.downs, current.owner) and Map.has_key?(current.downs, current.actor)
    end)
  end

  defp ua_sf_actor(observer, key, deadline, mode) do
    observer_ref = Process.monitor(observer)
    caller = self()
    receive do
      {^key, :sf_allocate, ^observer} -> :ok
      {:DOWN, ^observer_ref, :process, ^observer, _} -> exit(:normal)
    after
      max(0, deadline - System.monotonic_time(:millisecond)) -> exit(:normal)
    end
    checkpoint = fn stage, resources ->
      send(observer, {key, :sf_checkpoint, stage, resources, ua_sf_time()})
      :ok
    end
    prepare = fn destination, context ->
      send(observer, {key, :sf_prepare, self(), destination, context, ua_sf_time()})
      receive do
        {^key, :sf_armed, ^observer} -> :ok
      after
        max(0, min(5_000, deadline - System.monotonic_time(:millisecond))) ->
          throw(:legacy_transport_observer)
      end
      try do
        apply(LegacyUpgradeRuntimeFixture, :probe_transport!,
          [destination, context, :clean_frame, observer])
      catch
        kind, value ->
          stack = __STACKTRACE__
          b = %{key: key, observer: observer, audit: observer, caller: caller, database: destination.database,
            context: context, deadline: deadline}
          ua_sf_hold(b, {kind, value, stack})
      end
    end
    try do
      {owner, _destination, result} =
        Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.with_checkpoint(checkpoint, fn ->
          Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.open_legacy_v0_1_0(prepare)
        end)
      {queued, private?} = transport_queued(owner, [], true)
      send(observer, {key, :sf_actor_result, caller, {:ok, result == receipt()}, queued, private?})
      receive do
        {^key, :sf_close, ^observer} ->
          if mode == :clean,
            do: send(observer, {key, :sf_clean_release, caller, owner, ua_sf_time()})
        {:DOWN, ^observer_ref, :process, ^observer, _} -> :ok
      after
        max(0, deadline - System.monotonic_time(:millisecond)) -> :ok
      end
      Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.close(owner)
    rescue
      error in Singularity.Storage.Backup.KnowledgeFixtureResourceOwner.PreparationError ->
        safe? = not transport_contains?(Exception.message(error)) and
          not transport_contains?(inspect(error, limit: :infinity, printable_limit: :infinity))
        {queued, private?} = transport_queued(nil, [], true)
        send(observer, {key, :sf_actor_result, caller,
          {:error, error.primary, error.cleanup}, queued, safe? and private?})
      error ->
        send(observer, {key, :sf_actor_failure, caller, {:error, error, __STACKTRACE__}})
    catch
      kind, value ->
        send(observer, {key, :sf_actor_failure, caller, {kind, value, __STACKTRACE__}})
    after
      Process.demonitor(observer_ref, [:flush])
    end
    # The failed-acquisition acknowledgement closes the original owner before
    # the actor is allowed to exit; the observer independently joins that owner.
    send(observer, {key, :sf_actor_finished, caller, mode})
  end

  defp ua_sf_until(predicate) do
    ua_sf_remaining()
    if predicate.(ua_sf_state()) do
      :ok
    else
      ua_sf_receive(min(10, ua_sf_remaining()))
      ua_sf_until(predicate)
    end
  end

  defp ua_sf_receive(timeout) do
    s = ua_sf_state()
    key = s.key
    refs = s.monitors
    receive do
      {^key, :sf_checkpoint, stage, resources, at} ->
        ua_sf_require(resources.caller == s.actor)
        updates = %{checkpoints: Map.put(s.checkpoints, stage, {resources, at})}
        updates =
          if stage == {:repo_started, Singularity.Storage.MigrationRepo, :destination} do
            Map.put(updates, :origins, resources)
          else
            updates
          end
        ua_sf_put(updates)
      {^key, :sf_prepare, owner, destination, context, at} ->
        ua_sf_require(s.raw == nil and is_pid(owner) and context.caller == s.actor)
        ua_sf_put(%{owner: owner, destination: destination, raw: context, prepare_at: at})
      {^key, :sf_actor_result, actor, outcome, queued, private?} when actor == s.actor ->
        ua_sf_require(not Map.has_key?(s, :actor_result))
        ua_sf_put(%{actor_result: outcome, actor_queued: queued, actor_private: private?})
      {^key, :sf_clean_release, actor, owner, at} when actor == s.actor and owner == s.owner ->
        ua_sf_require(s.mode == :clean and not Map.has_key?(s, :clean_actor_release) and
          is_integer(at) and at >= s.epoch)
        ua_sf_put(%{clean_actor_release: {actor, owner, at}})
      {^key, :sf_actor_finished, actor, _} when actor == s.actor ->
        ua_sf_put(%{actor_finished: true})
      {^key, :sf_actor_failure, actor, {kind, value, stack}} when actor == s.actor ->
        ua_sf_stage(:actor_failure)
        ua_sf_failure(:original, kind, value, stack)
        ua_sf_put(%{actor_result: :unexpected, actor_private: false})
      {^key, :sf_caught, owner, original, context, at} when owner == s.owner ->
        ua_sf_require(not Map.has_key?(s, :caught) and context === s.raw)
        ua_sf_put(%{caught: original})
        ua_sf_event(:caught, original, at)
      {^key, :sf_boundary, owner, caller, database, nonce, caught, context, at}
          when owner == s.owner and caller == s.actor ->
        ua_sf_require(s.nonce == nil and context === s.raw and database == s.destination.database and
          s.caught === caught and ua_sf_at(:caught) < at)
        ua_sf_put(%{nonce: nonce, held_context: context})
        # Entry is a distinct owner event emitted after catch capture.
        ua_sf_put(%{boundary_pending: {owner, caller, database, nonce, at}})
        ua_sf_event(:boundary_entry, {key, owner, caller, database, nonce}, at)
      {^key, :sf_boundary_exit, owner, nonce, result, at} when owner == s.owner and nonce == s.nonce ->
        ua_sf_put(%{hold_decision: result})
        ua_sf_event(:boundary_exit, {owner, nonce, result}, at)
      {^key, :sf_hold_monitor, owner, nonce, restored} when owner == s.owner and nonce == s.nonce ->
        ua_sf_require(not Map.has_key?(s, :hold_monitor_restored) and is_boolean(restored))
        ua_sf_put(%{hold_monitor_restored: restored})
      {^key, :sf_rethrow, owner, original, at} when owner == s.owner ->
        ua_sf_require(Map.get(s, :caught) === original)
        ua_sf_event(:rethrow, original, at)
      {^key, :sf_privacy, safe?} when is_boolean(safe?) ->
        ua_sf_put(%{privacy: s.privacy ++ [safe?]})
      {:DOWN, ref, type, id, reason} when is_map_key(refs, ref) and type in [:process, :port] ->
        ua_sf_require(refs[ref] == id and not Map.has_key?(s.downs, id))
        at = ua_sf_time()
        ua_sf_put(%{downs: Map.put(s.downs, id, {ref, type, reason, at})})
        cond do
          id == s.owner -> ua_sf_event(:owner_down, {ref, id, reason}, at)
          id == s.actor -> ua_sf_event(:actor_down, {ref, id, reason}, at)
          id == s.connection -> ua_sf_event(:observer_connection_down, {ref, id, reason}, at)
          true -> :ok
        end
      {:trace_ts, pid, :call, mfa, payload, at} ->
        ua_sf_trace_call(pid, mfa, payload, at)
      {:trace_ts, pid, :return_from, mfa, result, at} ->
        ua_sf_trace_return(pid, mfa, result, at)
      {:trace_ts, pid, :exception_from, {ExCmd.Process, :await_exit, 2}, reason, at}
          when pid == s.owner ->
        {class, value} = reason
        ua_sf_event(:await_exception, {pid, class, value}, at)
      {:trace_delivered, pid, ref} ->
        ua_sf_require(Map.get(Map.get(s, :fence_waits, %{}), pid) === ref and
          not Map.has_key?(Map.get(s, :fence_acks, %{}), pid))
        ua_sf_put(%{fence_acks: Map.put(Map.get(s, :fence_acks, %{}), pid, ref)})
    after
      timeout -> :ok
    end
  end

  defp ua_sf_trace_open do
    s = ua_sf_state()
    {:module, reporter_module} = :erlang.fun_info(s.raw.report_cleanup, :module)
    {:name, reporter_name} = :erlang.fun_info(s.raw.report_cleanup, :name)
    {:type, :local} = :erlang.fun_info(s.raw.report_cleanup, :type)
    {:arity, 1} = :erlang.fun_info(s.raw.report_cleanup, :arity)
    {:env, reporter_env} = :erlang.fun_info(s.raw.report_cleanup, :env)
    ua_sf_require(reporter_module == Singularity.Storage.MigrationTestEnvironment and
      reporter_env === [s.owner])
    # OTP compiles local closures as explicit arguments followed by free vars.
    # This is the original logical unary fun; it is never invoked or wrapped here.
    reporter = {reporter_module, reporter_name, 1 + length(reporter_env)}
    mfas = [
      {LegacyUpgradeRuntimeFixture, :probe_transport!, 4},
      {LegacyUpgradeRuntimeFixture, :transport_receive, 1},
      {LegacyUpgradeRuntimeFixture, :transport_finish, 2},
      {LegacyUpgradeRuntimeFixture, :transport_event, 2},
      {ExCmd.Process, :start_link, 2}, {ExCmd.Process, :await_exit, 2},
      {ExCmd.Process, :read, 2}, {ExCmd.Process, :write, 2},
      {ExCmd.Process.State, :put_operation, 2},
      {Singularity.Storage.MigrationTestEnvironment, :cleanup_owned_destination, 0},
      reporter
    ]
    snapshot = ua_sf_trace_snapshot(mfas)
    flags = %{s.owner => [:erlang.trace_info(s.owner, :flags), :erlang.trace_info(s.owner, :tracer)]}
    ua_sf_require(flags[s.owner] == [{:flags, []}, {:tracer, []}])
    session = :trace.session_create(:task18_selected_command_fault, self(), [])
    ua_sf_put(%{session: session, traces: mfas, trace_before: snapshot,
      flags: flags, reporter_mfa: reporter})
    ua_sf_pattern({LegacyUpgradeRuntimeFixture, :probe_transport!, 4}, [
      {[:"$1", :"$2", :clean_frame, self()],
       [{:is_map, :"$1"}, {:is_map, :"$2"}, {:==, {:map_size, :"$2"}, 2}],
       [{:message, {{:sf_context, :"$1", :"$2"}}}]}
    ])
    ua_sf_pattern({LegacyUpgradeRuntimeFixture, :transport_receive, 1}, [
      {[%{run: :"$1", handle: :"$2", reader: :"$3", writer: :"$4", deadline: :"$5",
          pending_observer: self(), primary: :"$8", receipt: nil, stdin_closed: false,
          caller: s.actor, workspace: :"$6", dependency_paths: :"$7"}], [{:==, :"$8", nil}],
       [{:message, {{:sf_receive, :"$1", :"$2", :"$3", :"$4", :"$5", :"$6", :"$7", :"$8"}}}]}
    ])
    ua_sf_pattern({LegacyUpgradeRuntimeFixture, :transport_finish, 2}, [
      {[%{run: :"$1", handle: :"$2", primary: :"$3", caller: s.actor}, :_], [],
       [{:message, {{:sf_finish, :"$1", :"$2", :"$3"}}}]}
    ])
    ua_sf_pattern({LegacyUpgradeRuntimeFixture, :transport_event, 2}, [
      {[s.actor, {:legacy_upgrade_transport, :"$1", s.owner, :"$2"}], [],
       [{:message, {{:sf_helper, :"$1", :"$2"}}}]}
    ])
    ua_sf_pattern({ExCmd.Process, :start_link, 2}, [
      {[:"$1", [{:cd, :"$2"}, {:env, :"$3"}, {:stderr, :redirect_to_stdout}, {:log, nil}]],
       [{:is_list, :"$1"}, {:"=<", {:length, :"$1"}, 68},
        {:is_binary, :"$2"}, {:is_list, :"$3"}, {:==, {:length, :"$3"}, 11}],
       [{:message, {{:sf_launch, :"$1", :"$2", :"$3"}}}]}
    ])
    ua_sf_pattern({ExCmd.Process, :await_exit, 2}, [
      {[:"$1", :"$2"], [{:is_map, :"$1"}, {:is_integer, :"$2"}],
       [{:message, {{:sf_await, :"$1", :"$2"}}}, {:exception_trace}]}
    ])
    ua_sf_pattern({Singularity.Storage.MigrationTestEnvironment, :cleanup_owned_destination, 0},
      [{[], [], [{:message, :sf_teardown}]}])
    ua_sf_pattern(reporter, [
      {[:running | reporter_env], [], [{:message, {{:sf_reporter, :running}}}]},
      {[:closed | reporter_env], [], [{:message, {{:sf_reporter, :closed}}}]},
      {[:unconfirmed | reporter_env], [], [{:message, {{:sf_reporter, :unconfirmed}}}]}
    ])
    ua_sf_require(:trace.process(session, s.owner, true, [:call, :arity, :monotonic_timestamp]) == 1)
  end

  defp ua_sf_pattern(mfa, pattern) do
    session = ua_sf_state().session
    ua_sf_require(:trace.function(session, mfa, pattern, [:local]) == 1)
    ua_sf_require(:trace.info(session, mfa, :match_spec) == {:match_spec, pattern})
  end
  defp ua_sf_trace_snapshot(mfas), do: Map.new(mfas, fn mfa ->
    {mfa, Enum.map([:traced, :match_spec, :meta, :meta_match_spec], &:erlang.trace_info(mfa, &1))}
  end)

  defp ua_sf_trace_workers do
    s = ua_sf_state()
    flags = Map.new([s.command, s.reader, s.writer], fn pid ->
      {pid, [:erlang.trace_info(pid, :flags), :erlang.trace_info(pid, :tracer)]}
    end)
    ua_sf_require(Enum.all?(flags, fn {_, value} -> value == [{:flags, []}, {:tracer, []}] end))
    ua_sf_put(%{flags: Map.merge(s.flags, flags)})
    ua_sf_pattern({ExCmd.Process, :read, 2},
      [{[s.handle, 4], [], [{:message, :sf_reader_call}]}])
    ua_sf_pattern({ExCmd.Process, :write, 2},
      [{[s.handle, :_], [], [{:message, :sf_writer_call}, {:return_trace}]}])
    ua_sf_pattern({ExCmd.Process.State, :put_operation, 2},
      [{[:_, {:read_stdout, {s.reader, :_}, 4}], [], [{:message, :sf_reader_pending}]}])
    Enum.each([s.command, s.reader, s.writer], fn pid ->
      ua_sf_require(:trace.process(s.session, pid, true, [:call, :arity, :monotonic_timestamp]) == 1)
    end)
  end

  defp ua_sf_trace_call(pid, mfa, payload, at) do
    s = ua_sf_state()
    ua_sf_require(mfa in s.traces and is_integer(at))
    case payload do
      {:sf_context, destination, raw} ->
        ua_sf_require(pid == s.owner and destination === s.destination)
        {:ok, _} = ua_sf_context_projection(raw, s.raw, s.owner, s.actor)
        ua_sf_put(%{contexts: s.contexts ++ [raw]})
      {:sf_launch, argv, cd, env} ->
        ua_sf_require(pid == s.owner and not Map.has_key?(s, :launch))
        ua_sf_put(%{launch: %{argv: argv, cd: cd, env: env, at: at}})
      {:sf_receive, run, handle, reader, writer, deadline, workspace, paths, primary} ->
        ua_sf_require(pid == s.owner and not Map.has_key?(s, :receive))
        ua_sf_put(%{receive: %{run: run, handle: handle, reader: reader, writer: writer,
          deadline: deadline, workspace: workspace, paths: paths, primary: primary, at: at}})
      {:sf_helper, run, {:started, command, reader, writer} = event} ->
        ua_sf_require(pid == s.owner and not Map.has_key?(s, :started))
        ua_sf_put(%{started: {command, reader, writer, run, at}, helper: s.helper ++ [{at, event}]})
      {:sf_helper, run, event} ->
        ua_sf_require(pid == s.owner and run == s.run and transport_stage?(event))
        ua_sf_put(%{helper: s.helper ++ [{at, event}]})
      {:sf_finish, run, handle, primary} ->
        ua_sf_require(pid == s.owner and run == s.run and handle === s.handle)
        ua_sf_put(%{finish_primary: primary})
        if s.mode == :fault, do: ua_sf_event(:primary, {pid, run, primary}, at)
      {:sf_await, handle, timeout} ->
        ua_sf_require(pid == s.owner and handle === s.handle and timeout in 1..5_000)
        ua_sf_put(%{await_timeout: timeout})
        ua_sf_event(:await_entry, {pid, handle, timeout}, at)
      {:sf_reporter, status} ->
        ua_sf_require(pid == s.owner and mfa == s.reporter_mfa)
        ua_sf_put(%{reporter: s.reporter ++ [{status, at}]})
      :sf_teardown ->
        ua_sf_require(pid == s.owner)
        ua_sf_event(:mte_teardown, {pid, :original_six}, at)
      :sf_reader_call ->
        ua_sf_require(pid == s.reader and not Map.has_key?(s, :reader_call))
        ua_sf_put(%{reader_call: at})
      :sf_reader_pending ->
        ua_sf_require(pid == s.command and not Map.has_key?(s, :reader_pending))
        ua_sf_put(%{reader_pending: at})
      :sf_writer_call ->
        ua_sf_require(pid == s.writer and not Map.has_key?(s, :writer_call))
        ua_sf_put(%{writer_call: at})
      _ -> throw(:legacy_transport_observer)
    end
  end

  defp ua_sf_trace_return(pid, {ExCmd.Process, :write, 2}, result, at) do
    s = ua_sf_state()
    ua_sf_require(pid == s.writer and Map.has_key?(s, :writer_call) and
      not Map.has_key?(s, :writer_return) and result == :ok)
    ua_sf_put(%{writer_return: at})
  end
  defp ua_sf_trace_return(pid, {ExCmd.Process, :await_exit, 2}, result, at) do
    ua_sf_require(pid == ua_sf_state().owner)
    ua_sf_put(%{await_return: {result, at}})
  end
  defp ua_sf_trace_return(_, _, _, _), do: throw(:legacy_transport_observer)

  defp ua_sf_rows(sql, params) do
    timeout = min(1_000, ua_sf_remaining())
    {:ok, %Postgrex.Result{rows: rows}} =
      Postgrex.query(ua_sf_state().connection, sql, params, timeout: timeout)
    ua_sf_require(is_list(rows) and length(rows) <= 64)
    rows
  end

  defp ua_sf_inventory(stage) do
    ua_sf_stage(if(stage == :gate, do: :gate_inventory, else: :held_inventory))
    s = ua_sf_state()
    expected = transport_inventory_binding(s.key, s.connection, s.destination.database,
      stage, 3, s.pairs, s.child)
    {result, context} = transport_attribution_capture(s.key, stage, 3, s.pairs, s.child,
      expected.operation, fn ->
        Postgrex.query(s.connection,
          "SELECT pid,usename,backend_type FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND pid<>pg_backend_pid() ORDER BY pid",
          [s.destination.database], timeout: min(1_000, ua_sf_remaining()))
      end)
    ua_sf_stage(if(stage == :gate, do: :gate_projection, else: :held_projection))
    {:ok, %Postgrex.Result{} = ordinary} = result
    {:ok, projection} = ua_sf_project_inventory(ordinary, context, expected, s.pools)
    ua_sf_require(ua_sf_projection_inverse?(projection, ordinary, context, expected, s.pools))
    projection
  end

  defp ua_sf_gate do
    s = ua_sf_state()
    ua_sf_stage(:gate_worker_wait)
    ua_sf_until(fn current -> Map.has_key?(current, :reader_pending) and
      Map.has_key?(current, :reader_call) and Map.has_key?(current, :writer_return) end)
    ua_sf_stage(:gate_child_wait)
    ua_sf_wait_child()
    samples = Enum.map(1..2, fn _ ->
      ua_sf_stage(:gate_liveness)
      ua_sf_liveness()
      ua_sf_original_port()
      ua_sf_stage(:gate_wait_lock)
      waits = ua_sf_rows(
        "SELECT pid,wait_event_type,wait_event,pg_catalog.pg_blocking_pids(pid) FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND application_name=$2 ORDER BY pid",
        [s.destination.database, @transport_tag])
      locks = ua_sf_rows(
        "SELECT pid,granted,mode,classid::bigint,objid::bigint,objsubid FROM pg_catalog.pg_locks WHERE locktype='advisory' AND database=$1::oid AND classid=$2::oid AND objid=$3::oid AND objsubid=2 ORDER BY pid,granted",
        [ua_sf_state().oid | @transport_lock])
      current = ua_sf_state()
      expected = %{child_backend: current.child, observer_backend: current.observer_backend}
      ua_sf_stage(:gate_wait_lock_guard)
      ua_sf_require(ua_b_waits_locks?(waits, locks, expected))
      capture = ua_sf_inventory(:gate)
      ua_sf_require(capture.pairs == Enum.sort([{current.child, "singularity_migration"} | current.pairs]))
      baseline = Enum.reject(capture.triples, &(hd(&1) == current.child))
      ua_sf_require(Enum.map(baseline, fn [pid, role, _] -> {pid, role} end) == current.pairs)
      ua_sf_require(not Map.has_key?(current, :triples) or current.triples == baseline)
      ua_sf_put(%{triples: baseline})
      ua_sf_liveness()
      %{at: ua_sf_relative(ua_sf_time()), repos: current.repos, maintenance: current.maintenance,
        owner: current.owner, all_live: ua_sf_live?(), native_two_live: current.native_original,
        port_live: current.port, connection: current.connection, oid: current.oid,
        waits: waits, locks: locks, capture: capture}
    end)
    current = ua_sf_state()
    ua_sf_stage(:gate_worker_guard)
    ua_sf_require(Process.info(current.reader, [:status, :current_function]) ==
      [status: :waiting, current_function: {:gen, :do_call, 4}] and
      Process.info(current.writer, [:status, :current_function]) ==
      [status: :waiting, current_function: {LegacyUpgradeRuntimeFixture, :transport_writer, 4}] and
      current.reader_call < current.reader_pending and current.writer_call < current.writer_return)
    ua_sf_put(%{gate_samples: samples, prekill_workers: true})
  end

  defp ua_sf_wait_child do
    s = ua_sf_state()
    ua_sf_remaining()
    rows = ua_sf_rows(
      "SELECT pid,wait_event_type,wait_event,pg_catalog.pg_blocking_pids(pid) FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND application_name=$2 ORDER BY pid",
      [s.destination.database, @transport_tag])
    case rows do
      [[pid, "Lock", "advisory", [blocker]]] when blocker == s.observer_backend and is_integer(pid) and pid > 0 ->
        ua_sf_require(not List.keymember?(s.pairs, pid, 0))
        ua_sf_put(%{child: pid})
      [] ->
        ua_sf_receive(min(10, ua_sf_remaining()))
        ua_sf_wait_child()
      [[pid, _, _, _]] when is_integer(pid) and pid > 0 ->
        ua_sf_receive(min(10, ua_sf_remaining()))
        ua_sf_wait_child()
      _ -> throw(:legacy_transport_observer)
    end
  end

  defp ua_sf_live? do
    s = ua_sf_state()
    Process.alive?(s.owner) and Process.alive?(s.maintenance) and
      Enum.all?(s.repos, fn {repo, pid} -> Process.whereis(repo) == pid and Process.alive?(pid) end)
  end
  defp ua_sf_liveness do
    ua_sf_require(ua_sf_live?())
    s = ua_sf_state()
    # A successful clean helper already removed historical-build; it is not
    # quarantine. Fault measurements retain and compare all three roots.
    if s.mode == :fault or not Map.has_key?(s, :actor_result), do: ua_sf_roots_equal()
    ua_sf_remaining()
  end

  defp ua_sf_unlock do
    s = ua_sf_state()
    ua_sf_require(s.locked and not s.release_sent)
    # Record the attempt first; failure cannot authorize another unlock.
    ua_sf_put(%{release_sent: true})
    rows = ua_sf_rows("SELECT pg_advisory_unlock($1::integer,$2::integer)", @transport_lock)
    ua_sf_require(rows == [[true]])
    ua_sf_put(%{locked: false, unlock_rows: rows})
    ua_sf_event(:unlock, {self(), s.connection, @transport_lock, rows}, ua_sf_time())
  end

  defp ua_sf_fault do
    ua_sf_stage(:selected_command_fault)
    s = ua_sf_state()
    ua_sf_require(s.clean == {:ok, :closed} and s.prekill_workers and
      s.receive.primary == nil and System.monotonic_time(:millisecond) < s.receive.deadline and s.errors == [])
    ua_sf_original_port()
    ua_sf_self()
    ua_sf_event(:command_kill, {s.command, :kill, 1}, ua_sf_time())
    Process.exit(s.command, :kill)
    ua_sf_until(fn current -> current.nonce != nil and
      Map.has_key?(current, :await_timeout) and
      ua_sf_unlock_ready?(%{key: current.key, owner: current.owner, caller: current.actor,
        database: current.destination.database, run: current.run, handle: current.handle,
        timeout: current.await_timeout, nonce: current.nonce}, current.transition) end)
    ua_sf_liveness()
    ua_sf_unlock()
    ua_sf_stage(:held_native_absence)
    ua_sf_until(fn current -> Enum.all?([current.command, current.reader, current.writer, current.port],
      &Map.has_key?(current.downs, &1)) end)
    native = ua_sf_absence(:held)
    ua_sf_event(:measurement, {s.key, s.owner, ua_sf_state().nonce, :held},
      List.last(native.observations).at + s.epoch)
    ua_sf_stage(:held_repo_baselines)
    brackets = Enum.map(1..2, fn _ -> ua_sf_baseline_bracket() end)
    ua_sf_put(%{held_native: native, brackets: brackets})
    ua_sf_liveness()
    current = ua_sf_state()
    ua_sf_require(not Enum.any?(current.events, &(elem(&1, 1) == :boundary_exit)))
    ua_sf_event(:continuation, {s.key, self(), s.owner, current.nonce, :sampled}, ua_sf_time())
    send(s.owner, {s.key, :sf_continue, self(), s.owner, current.nonce, :sampled})
  end

  defp ua_sf_init_proc do
    pid = System.pid()
    ua_sf_require(ua_uint?(pid, 4_294_967_295, true) and System.otp_release() == "28" and
      :erlang.system_info(:endian) == :little and
      String.starts_with?(to_string(:erlang.system_info(:system_architecture)), "x86_64"))
    Process.put({__MODULE__, :ua_control}, %{fds: [], self_pid: pid,
      self_root: "/proc/" <> pid, epoch: ua_sf_state().epoch})
    proc_fd = ua_control_open!("/proc", :directory)
    self_fd = ua_control_open!("/proc/" <> pid, :directory)
    ua_control_update(%{proc_fd: proc_fd, self_fd: self_fd})
    first = ua_sf_self()
    ua_control_update(%{seed: first.seed})
    sources = ua_sf_sources()
    ua_control_update(%{sources: sources})
    ua_sf_put(%{self_pid: pid, self_initial: first, sources: sources})
  end

  defp ua_sf_sources do
    ua_sf_require(start_failure_origins_valid?(start_failure_origins()))
    start_failure_launcher!()
    rows = [
      {LegacyUpgradeRuntimeFixture, Path.join(@start_failure_root, "apps/singularity_runtime/test/support/legacy_upgrade_runtime_fixture.ex"),
       "6a746fad9d73981e1c8c5fdc6d6fdb420493227093fb6d10de31acd74d1b7d87"},
      {ExCmd.Process.Proto, Path.join(@start_failure_deps, "lib/ex_cmd/process/proto.ex"),
       "3827ccf95ae89189d8a4439ea556514d6e5b9f9e040a2598811fa78b017cdf69"},
      {Mix.Tasks.Compile.Odu, Path.join(@start_failure_deps, "lib/mix/compile.ex"),
       "730108534c596ba3ef96298e7c0d331c2b8e688d288f2c5ee0a65b0daa14a20d"}
    ]
    modules = Enum.map(rows, fn {module, source, sha} ->
      ua_sf_require(Code.ensure_loaded?(module))
      bytes = ua_control_read!(source, 65_536)
      ua_sf_require(start_failure_sha(bytes) == sha)
      {^module, beam, origin} = :code.get_object_code(module)
      ua_sf_require(:code.which(module) == origin and :code.is_loaded(module) == {:file, origin} and
        ua_control_read!(to_string(origin), 262_144) == beam and not :erlang.check_old_code(module))
      {:ok, {^module, [{:compile_info, compile}]}} = :beam_lib.chunks(beam, [:compile_info])
      {:ok, {^module, md5}} = :beam_lib.md5(beam)
      ua_sf_require(Keyword.fetch!(compile, :source) == String.to_charlist(source) and
        :erlang.get_module_info(module, :compile) == compile and
        :erlang.get_module_info(module, :md5) == md5)
      {module, source, sha, origin, start_failure_sha(beam), compile, md5}
    end)
    ua_sf_require(Mix.Tasks.Compile.Odu.executable_name() == "odu_linux_amd64")
    odu_path = Path.join(Application.app_dir(:ex_cmd, "priv"), "odu_linux_amd64")
    odu = ua_control_object!(odu_path, :regular)
    ua_sf_require(odu == ua_control_object!(Path.join(@start_failure_deps, "priv/odu_linux_amd64"), :regular))
    odu_bytes = ua_control_read!(odu_path, 1_944_902)
    ua_sf_require(start_failure_sha(odu_bytes) == "09d7c40b95f225af04bc65d88c6c3dc2e9c10629c4961b334ad738c7d1f85443")
    beam_path = "/nix/store/ccqqw9mf6jqbampbc3ydvvidkwhs3446-erlang-28.5.0.3/lib/erlang/erts-16.4.0.3/bin/beam.smp"
    beam = ua_control_object!(beam_path, :regular)
    c = Process.get({__MODULE__, :ua_control})
    ua_sf_require(ua_control_link!("/proc/self/exe", 4096) == beam_path and
      ua_control_link!(c.self_root <> "/exe", 4096) == beam_path and
      ua_control_object!("/proc/self/exe", :regular) == beam and
      ua_control_object!(c.self_root <> "/exe", :regular) == beam)
    beam_bytes = ua_control_read!(beam_path, 11_048_472)
    ua_sf_require(start_failure_sha(beam_bytes) == "b76a55616834eeede74d7c8d4a086f8abbf8c873315095a95e8f6523ca4c7cc4")
    %{modules: modules, odu_path: odu_path, odu: odu, beam_path: beam_path, beam: beam,
      beam_bytes: byte_size(beam_bytes), odu_bytes: byte_size(odu_bytes)}
  end

  # This retains full results at the prescribed self reads, not a second read of
  # omitted fields after calling the compact clean-control sampler.
  defp ua_sf_self do
    c = Process.get({__MODULE__, :ua_control})
    {readlink, self_lstat} = ua_sf_self_link()
    ua_sf_require(readlink == c.self_pid)
    root = ua_control_object!("/proc", :directory, c.proc_fd)
    if Map.has_key?(c, :proc_mount), do: ua_sf_require(root.mount == c.proc_mount),
      else: ua_control_update(%{proc_mount: root.mount})
    directory = ua_control_object!(c.self_root, :directory, c.self_fd)
    followed = ua_control_object!("/proc/self", :directory)
    ua_sf_require(followed == directory)
    literal_status = ua_control_object!("/proc/self/status", :regular)
    numeric_status = ua_control_object!(c.self_root <> "/status", :regular)
    ua_sf_require(literal_status == numeric_status)
    status = ua_parse_status(ua_control_read!("/proc/self/status", 4096), c.self_pid)
    {:ok, uid} = ua_live_status(status, c.self_pid)
    numeric_parsed = ua_parse_status(ua_control_read!(c.self_root <> "/status", 4096), c.self_pid)
    {:ok, ^uid} = ua_live_status(numeric_parsed, c.self_pid)
    {:ok, stat} = ua_parse_stat(ua_control_read!(c.self_root <> "/stat", 4096), c.self_pid)
    ua_sf_require(ua_live_state?(stat.state))
    pid_ns = ua_control_namespace!(c.self_root <> "/ns/pid", "pid")
    mount_ns = ua_control_namespace!(c.self_root <> "/ns/mnt", "mnt")
    literal_pid = ua_control_namespace!("/proc/self/ns/pid", "pid")
    literal_mount = ua_control_namespace!("/proc/self/ns/mnt", "mnt")
    children = ua_control_namespace!(c.self_root <> "/ns/pid_for_children", "pid")
    literal_children = ua_control_namespace!("/proc/self/ns/pid_for_children", "pid")
    ua_sf_require(literal_pid == pid_ns and literal_mount == mount_ns and
      children == pid_ns and literal_children == pid_ns)
    cgroup = ua_control_read!(c.self_root <> "/cgroup", 4096)
    ua_sf_require(cgroup == ua_control_read!("/proc/self/cgroup", 4096))
    independent = if Map.has_key?(c, :seed), do: c.seed.cgroup, else: cgroup
    {:ok, _} = parsed_cgroup = ua_parse_cgroup(cgroup, independent, :v2)
    mount = ua_control_read!(c.self_root <> "/mountinfo", 16384)
    ua_sf_require(mount == ua_control_read!("/proc/self/mountinfo", 16384))
    {:directory, major, minor, _} = root.object
    {:ok, lines} = ua_text_lines(mount, 16384)
    {:ok, records} = ua_mount_rows(lines, [], [])
    [proc] = Enum.filter(records, &(&1.point == "/proc"))
    ua_sf_require(proc.root == "/" and proc.type == "proc" and
      proc.device == {Integer.to_string(major), Integer.to_string(minor)} and
      ua_hidepid_zero?(proc.options ++ proc.super_options))
    native = Map.get(c, :native_pid)
    parsed_mount = if native do
      {:ok, admitted} = result = ua_parse_mountinfo(mount,
        %{self_pid: c.self_pid, native_pid: native, proc_device: {major, minor}})
      ua_sf_require(admitted.record == proc.raw)
      result
    else
      nil
    end
    ua_control_update(%{mount_records: records})
    ua_sf_require(root.mount == proc.id and directory.mount == proc.id and literal_status.mount == proc.id)
    extra = Enum.flat_map(["/proc/self", c.self_root], fn base ->
      Enum.map(["", "/status", "/stat", "/mountinfo", "/cgroup", "/ns", "/ns/pid",
        "/ns/mnt", "/ns/pid_for_children", "/exe", "/fdinfo", "/fdinfo/"], &(base <> &1))
    end) ++ if(native, do: ["/proc/" <> native <> "/ns/mnt"], else: [])
    ua_sf_require(not Enum.any?(records, fn record ->
      record.id != proc.id and Enum.any?(extra, &ua_covers?(record.point, &1))
    end))
    seed = %{root: root, directory: directory, status: literal_status, uid: uid,
      pid_ns: pid_ns, mount_ns: mount_ns, cgroup: cgroup, mount: mount,
      proc: proc.raw, start_ticks: stat.start_ticks}
    ua_sf_require(not Map.has_key?(c, :seed) or seed == c.seed)
    %{seed: seed, readlink: readlink, self_lstat: self_lstat, root: root,
      directory: directory, followed: followed, status_object: literal_status,
      numeric_status: numeric_status, status: status, numeric_parsed: numeric_parsed,
      stat: stat, pid_ns: pid_ns, mount_ns: mount_ns, children: children,
      cgroup: parsed_cgroup, mount: parsed_mount, closed: true}
  end

  # The same four link reads as ua_control_link!/2; retain the first lstat
  # already taken, rather than taking a fifth read to populate the schema.
  defp ua_sf_self_link do
    path = "/proc/self"
    stat = File.lstat!(path, time: :posix)
    ua_sf_require(stat.type == :symlink)
    value = File.read_link!(path)
    ua_sf_require(byte_size(value) > 0 and byte_size(value) <= 128 and
      :binary.match(value, <<0>>) == :nomatch and
      ua_control_low(File.lstat!(path, time: :posix)) == ua_control_low(stat) and
      File.read_link!(path) == value)
    object = {:symlink, Bitwise.band(Bitwise.bsr(stat.major_device, 8), 0xFFF),
      Bitwise.bor(Bitwise.band(stat.major_device, 0xFF),
        Bitwise.band(Bitwise.bsr(stat.major_device, 12), 0xFFF00)), stat.inode}
    {value, object}
  end

  defp ua_sf_admit do
    s = ua_sf_state()
    p = s.receive
    {command, reader, writer, run, started_at} = s.started
    ua_sf_require(p.run == run and p.reader == reader and p.writer == writer and
      p.handle.owner == s.owner and p.handle.pid == command and
      p.handle.__struct__ == ExCmd.Process and
      Enum.sort(Map.keys(p.handle)) == Enum.sort([:__struct__, :owner, :pid, :monitor_ref, :exit_ref]) and
      is_reference(p.handle.monitor_ref) and is_reference(p.handle.exit_ref) and
      p.handle.monitor_ref != p.handle.exit_ref and length(Enum.uniq([command, reader, writer])) == 3)
    expected_argv = [@start_failure_elixir <> "/bin/elixir", "--erl", "+fnu"] ++
      Enum.flat_map(p.paths, &["-pa", &1]) ++
      [Path.join(@start_failure_root, "apps/singularity_runtime/test/fixtures/legacy_v0_1_0/runner.exs")]
    expected_env = Enum.map(
      ~w(ERL_AFLAGS ERL_FLAGS ERL_ZFLAGS ERL_LIBS ELIXIR_ERL_OPTIONS ELIXIR_CLI_DRY_RUN RUN_ERL_PIPE RUN_ERL_LOG BASH_ENV ENV),
      &{&1, ""}) ++ [{"SINGULARITY_TASK18_PROBE", "clean_frame"}]
    ua_sf_require(s.launch.argv == expected_argv and s.launch.cd == p.workspace and
      s.launch.env == expected_env and s.allocated < s.launch.at and s.launch.at < started_at and
      started_at <= p.at and p.deadline - System.monotonic_time(:millisecond) in 1..45_000)
    ua_sf_put(%{command: command, reader: reader, writer: writer, run: run, handle: p.handle,
      launch_qualified: s.launch.argv == expected_argv and s.launch.env == expected_env})
    Enum.each([command, reader, writer], &ua_sf_monitor/1)
    ua_sf_trace_workers()
    {:ok, native} = GenServer.call(command, :os_pid, min(1_000, ua_sf_remaining()))
    ua_sf_require(is_integer(native) and native > 0 and native <= 4_294_967_295)
    [port] = Enum.filter(Port.list(), &(Port.info(&1, :connected) == {:connected, command}))
    {:os_pid, odu_pid} = Port.info(port, :os_pid)
    {:name, odu_name} = Port.info(port, :name)
    ua_sf_require(native != odu_pid and is_integer(odu_pid) and odu_pid > 0 and
      to_string(odu_name) == s.sources.odu_path and Integer.to_string(native) != s.self_pid)
    port_ref = ua_sf_monitor(port)
    monitor_at = ua_sf_time()
    ua_sf_put(%{native_pid: Integer.to_string(native), port: port, port_ref: port_ref,
      port_monitor_at: monitor_at, odu_pid: odu_pid})
    ua_control_update(%{native_pid: Integer.to_string(native)})
    native_fd = ua_control_open!("/proc/" <> Integer.to_string(native), :directory)
    ua_control_update(%{native_fd: native_fd})
    ua_sf_wait_beam(nil)
    first = ua_sf_native_live()
    second = ua_sf_native_live()
    ua_sf_require(first.directory == second.directory and first.exe == second.exe and
      elem(first.stat, 1).pid == elem(second.stat, 1).pid and
      elem(first.stat, 1).start_ticks == elem(second.stat, 1).start_ticks and first.at < second.at and
      ua_b_same_admission?(second.admission_before, first.admission_before))
    bound_at = ua_sf_time()
    original = %{native_pid: Integer.to_string(native), pid_source: :original_ex_cmd_return,
      admission: first.admission_before, live: [first, second],
      bound_after_two_live: first.at < second.at, bound_at: ua_sf_relative(bound_at),
      handle: p.handle, command: command, reader: reader, writer: writer,
      monitor_ref: p.handle.monitor_ref, exit_ref: p.handle.exit_ref, owner: s.owner,
      caller: s.actor, run: run, observer_connection: s.connection,
      connected_ports: [port], connected_command: command, port: port, port_ref: port_ref,
      port_monitor_installed_live: monitor_at < bound_at, port_monitor_at: ua_sf_relative(monitor_at)}
    ua_sf_put(%{native_original: original})
    ua_sf_roots_capture()
    ua_sf_original_port()
  end

  defp ua_sf_original_port do
    s = ua_sf_state()
    ua_sf_require(Port.info(s.port, :connected) == {:connected, s.command} and
      Port.info(s.port, :os_pid) == {:os_pid, s.odu_pid} and
      Port.info(s.port, :name) == {:name, String.to_charlist(s.sources.odu_path)} and
      Enum.all?([s.command, s.reader, s.writer], &Process.alive?/1))
  end

  defp ua_sf_wait_beam(previous) do
    s = ua_sf_state()
    c = Process.get({__MODULE__, :ua_control})
    ua_sf_remaining()
    base = "/proc/" <> s.native_pid
    directory = ua_control_object!(base, :directory, c.native_fd)
    {:ok, stat} = ua_parse_stat(ua_control_read!(base <> "/stat", 4096), s.native_pid)
    ua_sf_require(ua_live_state?(stat.state))
    identity = {directory, stat.start_ticks}
    ua_sf_require(previous == nil or previous == identity)
    ua_sf_original_port()
    if ua_control_link!(base <> "/exe", 4096) == s.sources.beam_path do
      :ok
    else
      receive do after min(1, ua_sf_remaining()) -> ua_sf_wait_beam(identity) end
    end
  end

  defp ua_sf_native_live do
    s = ua_sf_state()
    c = Process.get({__MODULE__, :ua_control})
    before = ua_sf_self()
    base = "/proc/" <> s.native_pid
    directory = ua_control_object!(base, :directory, c.native_fd)
    {:ok, stat} = parsed_stat = ua_parse_stat(ua_control_read!(base <> "/stat", 4096), s.native_pid)
    status = ua_parse_status(ua_control_read!(base <> "/status", 4096), s.native_pid)
    {:ok, uid} = ua_live_status(status, s.native_pid)
    ua_sf_require(ua_live_state?(stat.state) and uid == before.seed.uid)
    pid_ns = ua_control_namespace!(base <> "/ns/pid", "pid")
    mount_ns = ua_control_namespace!(base <> "/ns/mnt", "mnt")
    ua_sf_require(pid_ns == before.pid_ns and mount_ns == before.mount_ns)
    {:ok, _} = cgroup = ua_parse_cgroup(ua_control_read!(base <> "/cgroup", 4096), before.seed.cgroup, :v2)
    exe_path = ua_control_link!(base <> "/exe", 4096)
    exe_object = ua_control_object!(base <> "/exe", :regular)
    ua_sf_require(exe_path == s.sources.beam_path and exe_object == s.sources.beam)
    {:ok, stat_after} = parsed_after = ua_parse_stat(ua_control_read!(base <> "/stat", 4096), s.native_pid)
    ua_sf_require(stat_after.start_ticks == stat.start_ticks and ua_live_state?(stat_after.state))
    after_self = ua_sf_self()
    ua_sf_require(after_self.seed == before.seed)
    ua_sf_original_port()
    admission_before = ua_sf_admission(before, status, stat.state, pid_ns, mount_ns)
    admission_after = ua_sf_admission(after_self, status, stat_after.state, pid_ns, mount_ns)
    ua_sf_require(ua_admit_proc(admission_before) and ua_admit_proc(admission_after))
    %{at: ua_sf_relative(ua_sf_time()), stat: parsed_stat, status: status, cgroup: cgroup,
      directory: directory.object, exe: {:ok, %{path: exe_path, object: exe_object.object,
        bytes: s.sources.beam_bytes}}, stat_after: parsed_after, fd_closed: Enum.all?([before.closed, after_self.closed], &(&1 === true)),
      admission_before: admission_before, admission_after: admission_after}
  end

  defp ua_sf_admission(own, status, state, pid_ns, mount_ns) do
    s = ua_sf_state()
    unchanged = own.seed == Process.get({__MODULE__, :ua_control}).seed
    source = s.launch_qualified and length(s.sources.modules) == 3
    %{self_pid_source: :system_pid_getpid, system_pid: s.self_pid,
      expected_self_pid: s.self_pid, self_readlink: own.readlink,
      self_lstat: own.self_lstat, self_followed: own.followed.object,
      numeric_directory: own.directory.object, self_directory_after: own.directory.object,
      status_fd: own.status_object.object, numeric_status_before: own.numeric_status.object,
      numeric_status_after: own.numeric_status.object,
      self_status: own.status, self_stat_state: own.stat.state, native_stat_state: state,
      pid_namespace: elem(own.pid_ns, 0), children_pid_namespace: elem(own.children, 0),
      native_pid_namespace: elem(pid_ns, 0), pid_namespace_after: elem(own.pid_ns, 0),
      mount_namespace: elem(own.mount_ns, 0), mount_namespace_after: elem(mount_ns, 0),
      proc_root: own.root.object, proc_root_after: own.root.object,
      mount: own.mount, expected_mount: own.mount, native_pid: s.native_pid,
      source_returned_native_pid: s.native_pid, native_pid_source: :original_ex_cmd_return,
      original_handle_bound?: s.handle.pid == s.command and s.handle.owner == s.owner,
      native_status: status, stable_admission?: unchanged,
      spawn_premise: %{controlled_new_vm: source,
        common_thread_forker_namespace_history: source and own.pid_ns == pid_ns,
        unchanged_qualified_launcher_argv_environment: s.launch_qualified,
        installed_source_correspondence: source,
        no_namespace_transition: unchanged and own.pid_ns == pid_ns and own.mount_ns == mount_ns,
        no_mount_transition: unchanged, no_security_transition: source and unchanged,
        no_cgroup_transition: unchanged, no_credential_transition: unchanged}}
  end

  defp ua_sf_fresh_self do
    own = ua_sf_self()
    s = ua_sf_state()
    original = s.native_original.admission
    fresh = %{kind: :fresh_self_only, system_pid: s.self_pid, readlink: own.readlink,
      self_lstat: own.self_lstat, directory: own.followed.object,
      numeric_directory: own.directory.object, directory_after: own.directory.object,
      status_fd: own.status_object.object, status_path_before: own.numeric_status.object,
      status_path_after: own.numeric_status.object, status: own.status, stat_state: own.stat.state,
      pid_namespace: elem(own.pid_ns, 0), children_namespace: elem(own.children, 0),
      mount_namespace: elem(own.mount_ns, 0), proc_root: own.root.object, mount: own.mount,
      cgroup: own.cgroup, fd_closed: own.closed, fresh: own.seed == Process.get({__MODULE__, :ua_control}).seed,
      startup_unchanged: s.launch_qualified}
    ua_sf_require(ua_b_fresh_self?(fresh, ua_sf_native_expected(), original))
    fresh
  end

  defp ua_sf_native_expected do
    s = ua_sf_state()
    first = hd(s.native_original.live)
    {:ok, stat} = first.stat
    {:ok, status} = first.status
    {:ok, exe} = first.exe
    %{native_pid: s.native_pid, self_pid: s.self_pid, start_ticks: stat.start_ticks,
      uids: status.uids, cgroup_raw: Process.get({__MODULE__, :ua_control}).seed.cgroup,
      cgroup: first.cgroup, directory: first.directory, exe: exe,
      handle: s.handle, command: s.command, reader: s.reader, writer: s.writer,
      owner: s.owner, caller: s.actor, run: s.run, port: s.port, port_ref: s.port_ref,
      observer: self(), observer_connection: s.connection, gate_key: @transport_lock,
      database: s.destination.database, nonce: s.nonce, monitor_ref: s.handle.monitor_ref,
      exit_ref: s.handle.exit_ref}
  end

  defp ua_sf_roots_capture do
    s = ua_sf_state()
    objects = s.destination.object_root
    allocation = Path.dirname(objects)
    build = Path.join(allocation, "historical-build")
    ua_sf_require(s.receive.workspace == build and objects == Path.join(allocation, "objects"))
    roots = Map.new([allocation: allocation, objects: objects, historical_build: build],
      fn {kind, path} -> {kind, {path, ua_sf_directory(path, true)}} end)
    ancestors = ua_sf_ancestors(Path.dirname(allocation), [])
    ua_sf_require(ua_b_roots?(roots, ancestors))
    inventory = ua_sf_inventories(roots)
    ua_sf_require(ua_b_inventories?(inventory))
    ua_sf_put(%{roots: roots, ancestors: ancestors, root_inventory: inventory})
  end

  defp ua_sf_directory(path, private?) do
    {:ok, stat} = File.lstat(path, time: :posix)
    ua_sf_require(stat.type == :directory and
      (not private? or stat.uid == 1000 and Bitwise.band(stat.mode, 0o7777) == 0o700))
    object = ua_control_object!(path, :directory)
    after_stat = File.lstat!(path, time: :posix)
    ua_sf_require(object.uid == stat.uid and after_stat.uid == stat.uid and
      after_stat.mode == stat.mode and ua_control_low(after_stat) == ua_control_low(stat) and
      Bitwise.band(elem(object.object, 3), 0xFFFFFFFF) == stat.inode)
    object.object
  end

  defp ua_sf_ancestors("/", acc), do: Enum.reverse(acc)
  defp ua_sf_ancestors(path, acc) when length(acc) < 16 do
    object = ua_sf_directory(path, false)
    ua_sf_ancestors(Path.dirname(path), [{path, object} | acc])
  end
  defp ua_sf_ancestors(_, _), do: throw(:legacy_transport_observer)

  defp ua_sf_roots_equal do
    s = ua_sf_state()
    roots = Map.new(s.roots, fn {kind, {path, _}} -> {kind, {path, ua_sf_directory(path, true)}} end)
    ancestors = Enum.map(s.ancestors, fn {path, _} -> {path, ua_sf_directory(path, false)} end)
    inventory = ua_sf_inventories(roots)
    ua_sf_require(roots == s.roots and ancestors == s.ancestors and inventory == s.root_inventory)
    %{roots: roots, ancestors: ancestors, inventory: inventory}
  end

  defp ua_sf_inventories(roots), do: Map.new(roots, fn {kind, {path, _}} ->
    {:ok, entries} = File.ls(path)
    ua_sf_require(length(entries) <= 2)
    {kind, Enum.sort(entries)}
  end)

  defp ua_sf_absence(scope) do
    observations = ua_sf_absence_loop([])
    s = ua_sf_state()
    {ref, :port, reason, down_at} = Map.fetch!(s.downs, s.port)
    port_info = Port.info(s.port)
    info_at = ua_sf_time()
    ua_sf_require(ref == s.port_ref and port_info == nil)
    common = %{expected: ua_sf_native_expected(), original: s.native_original,
      observations: observations, port_down: [{ref, :port, s.port, reason, ua_sf_relative(down_at)}],
      port_info: port_info, port_info_at: ua_sf_relative(info_at), deadline: ua_sf_deadline_value(),
      sticky_invalid: false, replacement_seen: false, unknown: false}
    case scope do
      :held ->
        b = %{command_kill: {ua_sf_relative(ua_sf_at(:command_kill)), s.command, :kill},
          await_entry: {ua_sf_relative(ua_sf_at(:await_entry)), s.owner, s.handle, s.await_timeout},
          await_exception: {ua_sf_relative(ua_sf_at(:await_exception)), :exit,
            {:killed, {ExCmd.Process, :await_exit, [s.handle, s.await_timeout]}}},
          unlock: {ua_sf_relative(ua_sf_at(:unlock)), self(), s.connection, @transport_lock, s.unlock_rows},
          entry: {ua_sf_relative(ua_sf_at(:boundary_entry)), s.owner, s.actor, s.destination.database, s.nonce},
          held: not Enum.any?(s.events, &(elem(&1, 1) == :boundary_exit))}
        facts = Map.put(common, :boundary, b)
        ua_sf_require(ua_original_gone?(facts))
        facts
      :hygiene -> Map.put(common, :scope, :independent_hygiene_after_original_closure)
      :clean -> common
    end
  end

  defp ua_sf_deadline_value do
    s = ua_sf_state()
    System.convert_time_unit(s.deadline, :millisecond, :native) - s.epoch
  end

  defp ua_sf_absence_loop(observations) do
    ua_sf_remaining()
    s = ua_sf_state()
    before = ua_sf_fresh_self()
    path = "/proc/" <> s.native_pid
    first_serial = ua_sf_read_serial()
    first = File.lstat(path, time: :posix)
    {kind, reads, status_reads, serials} =
      case first do
        {:error, :enoent} ->
          second_serial = ua_sf_read_serial()
          second = File.stat(path <> "/stat", time: :posix)
          third_serial = ua_sf_read_serial()
          third = File.lstat(path, time: :posix)
          ua_sf_require(second == {:error, :enoent} and third == {:error, :enoent})
          {:absent, [{:lstat, path, first}, {:stat_path, path <> "/stat", second},
            {:lstat, path, third}], [], [first_serial, second_serial, third_serial]}
        {:ok, %File.Stat{type: :directory}} ->
          c = Process.get({__MODULE__, :ua_control})
          directory = ua_control_object!(path, :directory, c.native_fd)
          second_serial = ua_sf_read_serial()
          stat = ua_parse_stat(ua_control_read!(path <> "/stat", 4096), s.native_pid)
          third_serial = ua_sf_read_serial()
          status = ua_parse_status(ua_control_read!(path <> "/status", 4096), s.native_pid)
          cgroup = ua_parse_cgroup(ua_control_read!(path <> "/cgroup", 4096), c.seed.cgroup, :v2)
          exe =
            case File.lstat(path <> "/exe", time: :posix) do
              {:error, :enoent} -> {:error, :enoent}
              {:ok, %File.Stat{type: :symlink}} ->
                exe_path = ua_control_link!(path <> "/exe", 4096)
                object = ua_control_object!(path <> "/exe", :regular)
                ua_sf_require(exe_path == s.sources.beam_path and object == s.sources.beam)
                {:ok, %{path: exe_path, object: object.object, bytes: s.sources.beam_bytes}}
              _ -> throw(:legacy_transport_observer)
            end
          {:present, [{:lstat, path, {:ok, directory.object}}, {:stat, stat},
            {:status, status}, {:cgroup, cgroup}, {:exe, exe}], [path <> "/status"],
            [first_serial, second_serial, third_serial]}
        _ -> throw(:legacy_transport_observer)
      end
    after_self = ua_sf_fresh_self()
    observation = %{kind: kind, at: ua_sf_relative(ua_sf_time()),
      before: before, after: after_self, reads: reads,
      read_serials: serials, native_status_reads: status_reads}
    # Rejection is sticky: this function never catches and resumes ambiguous reads.
    {:ok, ^kind} = ua_b_native_reads(kind, reads, status_reads, ua_sf_native_expected())
    next = observations ++ [observation]
    if kind == :absent do
      next
    else
      ua_sf_receive(min(10, ua_sf_remaining()))
      ua_sf_absence_loop(next)
    end
  end

  defp ua_sf_read_serial do
    next = ua_sf_state().serial + 1
    ua_sf_put(%{serial: next})
    next
  end

  defp ua_sf_baseline_bracket do
    s = ua_sf_state()
    before = ua_sf_fresh_self()
    ua_sf_liveness()
    tagged = ua_sf_rows("SELECT pid FROM pg_catalog.pg_stat_activity WHERE datname=$1 AND application_name=$2 ORDER BY pid",
      [s.destination.database, @transport_tag])
    ua_sf_require(tagged == [])
    capture = ua_sf_inventory(:absence)
    ua_sf_require(capture.pairs == s.pairs and capture.triples == s.triples and
      Enum.frequencies_by(capture.pairs, &elem(&1, 1)) == s.pools)
    [[oid]] = ua_sf_rows("SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1",
      [s.destination.database])
    ua_sf_require(oid == s.oid)
    ua_sf_liveness()
    after_self = ua_sf_fresh_self()
    at = ua_sf_relative(ua_sf_time())
    %{at: at, repos_before: s.repos, repos_after: Map.new(@transport_repos, &{&1, Process.whereis(&1)}),
      maintenance: s.maintenance, owner: s.owner, oid: oid, self_before: before, self_after: after_self,
      registered_equal: Enum.all?(s.repos, fn {repo, pid} -> Process.whereis(repo) == pid end),
      all_live: ua_sf_live?(), capture: capture, tagged: tagged}
  end

  defp ua_sf_clean_measure do
    s = ua_sf_state()
    ua_sf_require(s.mode == :clean and s.actor_result == {:ok, true} and
      elem(s.await_return, 0) == {:ok, 0} and s.finish_primary == nil)
    ua_sf_until(fn current -> Enum.all?([current.command, current.reader, current.writer, current.port],
      &Map.has_key?(current.downs, &1)) end)
    native = ua_sf_absence(:clean)
    brackets = Enum.map(1..2, fn _ -> ua_sf_baseline_bracket() end)
    ua_sf_put(%{clean_native: native, brackets: brackets})
  end

  defp ua_sf_telemetry_open do
    s = ua_sf_state()
    events = [
      [:singularity, :runtime, :operation], [:singularity, :storage, :operation],
      [:singularity, :job, :enqueue], [:singularity, :job, :retry],
      [:singularity, :outbox, :dispatch], [:singularity, :integrity, :failure]
    ]
    before = :telemetry.list_handlers([])
    events = Enum.uniq(events ++ Enum.map(before, & &1.event_name))
    handler = {__MODULE__, :selected_fault, s.key}
    observer = self()
    :ok = :telemetry.attach_many(handler, events, fn _, measurements, metadata, _ ->
      safe? = try do
        not transport_contains?(measurements) and not transport_contains?(metadata)
      rescue _ -> false catch _, _ -> false end
      send(observer, {s.key, :sf_privacy, safe?})
    end, nil)
    ua_sf_put(%{telemetry_before: before, telemetry_handler: handler, telemetry_events: events})
    installed = Enum.filter(:telemetry.list_handlers([]), &(&1.id == handler))
    ua_sf_put(%{telemetry_installed: installed})
    ua_sf_require(Enum.sort(Enum.map(installed, & &1.event_name)) == Enum.sort(events))
  end

  defp ua_sf_safe(fun) do
    try do
      fun.()
      :ok
    rescue
      error -> ua_sf_failure(:cleanup, :error, error, __STACKTRACE__)
    catch
      kind, value -> ua_sf_failure(:cleanup, kind, value, __STACKTRACE__)
    end
  end

  # One finite executor is used by the actual plan and per-step fault contracts.
  # It catches each action independently and keeps the original class/value/stack.
  defp ua_sf_cleanup_execute(plan, state, action, record) do
    Enum.map_reduce(plan, state, fn step, current ->
      outcome =
        try do
          {:ok, action.(step, current)}
        catch
          kind, value -> {:error, kind, value, __STACKTRACE__}
        end
      {{step, outcome}, record.(current, step, outcome)}
    end)
  end

  defp ua_sf_cleanup_once({:ok, previous}, _action), do: {:previous, previous}
  defp ua_sf_cleanup_once(:error, action), do: action.()

  defp ua_sf_cleanup_plan(s, c) do
    [:release_ready, :abort_hold, :release_unlock, :clean_stop, :clean_join,
      :actor_release, :owner_actor_join, :retained_database, :fault_stop, :fault_join,
      :attribution_close] ++
      Enum.map(s.monitors, fn {ref, id} -> {:join, id, ref} end) ++
      Enum.map(Map.keys(s.flags), &{:trace_fence, &1}) ++
      [:trace_destroy, :trace_verify, :telemetry_detach, :telemetry_verify,
        :late_drain, :fence_event, :baseline_capture, :baseline_verify, :environment_verify,
        :self_verify, :source_verify, :retention] ++
      Enum.map(if(is_map(c), do: c.fds, else: []), &{:fd_close, &1}) ++ [:fd_verify]
  end

  defp ua_sf_cleanup_contract(plan, failing, monitors) do
    original = %{scope: :original, stage: :synthetic_primary, kind: :throw,
      value: :synthetic_primary, stack: [:synthetic_stack], site_line: 0}
    initial = %{first_failure: original, errors: [], cleanup_steps: %{}, join_attempts: %{},
      monitors: monitors, stage: :synthetic_cleanup}
    {outcomes, retained} = ua_sf_cleanup_execute(plan, initial, fn step, _ ->
      if step == failing, do: throw({:synthetic_failure, step}), else: {:terminal, step}
    end, &ua_sf_cleanup_record/3)
    Enum.map(outcomes, &elem(&1, 0)) === plan and length(Enum.uniq(plan)) == length(plan) and
      Enum.count(plan, &match?({:join, _, _}, &1)) == 13 and
      retained.monitors === monitors and retained.first_failure === original and
      map_size(retained.cleanup_steps) == length(plan) and
      Enum.all?(outcomes, fn
        {step, {:ok, {:terminal, same}}} -> step === same and step != failing
        {step, {:error, :throw, {:synthetic_failure, same}, stack}} ->
          step === same and step === failing and is_list(stack) and stack != []
        _ -> false
      end) and
      (if failing == nil do
        retained.errors == []
      else
        case retained.errors do
          [%{scope: :cleanup, kind: :throw, value: {:synthetic_failure, ^failing}, stack: stack}] ->
            is_list(stack) and stack != [] and
              (case failing do
                {:join, id, ref} ->
                  retained.join_attempts === %{id => {ref, {:error,
                    {:throw, {:synthetic_failure, failing}, stack}}}}
                _ -> retained.join_attempts === %{}
              end)
          _ -> false
        end
      end)
  end

  defp ua_sf_cleanup_record(s, _, {:ok, {:previous, _}}), do: s
  defp ua_sf_cleanup_record(s, step, outcome) do
    s = %{s | cleanup_steps: Map.put(s.cleanup_steps, step, outcome)}
    case outcome do
      {:error, kind, value, stack} ->
        failure = ua_sf_failure_fact(:cleanup, ua_sf_cleanup_stage(step), kind, value, stack)
        joins = case step do
          {:join, id, ref} -> Map.put(s.join_attempts, id, {ref, {:error, {kind, value, stack}}})
          _ -> s.join_attempts
        end
        %{s | errors: s.errors ++ [failure], first_failure: s.first_failure || failure,
          join_attempts: joins}
      {:ok, value} ->
        case {step, value} do
          {{:hygiene_fd_close, fd}, :closed} -> %{s | hygiene_fds: List.delete(s.hygiene_fds, fd)}
          {:hygiene_join, {:normal, recovery, ref}} -> Map.put(s, :hygiene_down, {recovery, ref, :normal})
          {:hygiene_retire, {:retired, _, _}} -> %{s | hygiene_connection: nil}
          _ -> s
        end
    end
  end

  defp ua_sf_cleanup_run(plan) do
    ua_sf_cleanup_execute(plan, ua_sf_state(), fn step, _ ->
      s = ua_sf_state()
      ua_sf_cleanup_once(Map.fetch(s.cleanup_steps, step), fn ->
        ua_sf_put(%{cleanup_steps: Map.put(s.cleanup_steps, step, :attempted)})
        ua_sf_stage(ua_sf_cleanup_stage(step))
        ua_sf_cleanup_action(step)
      end)
    end, fn _, step, outcome ->
      current = ua_sf_cleanup_record(ua_sf_state(), step, outcome)
      ua_sf_put(current)
      case step do
        {:hygiene_fd_close, _} -> ua_control_update(%{fds: current.hygiene_fds})
        _ -> :ok
      end
      current
    end)
    :ok
  end

  defp ua_sf_cleanup_stage({:join, _, _}), do: :cleanup_join
  defp ua_sf_cleanup_stage({:trace_fence, _}), do: :cleanup_trace_fence
  defp ua_sf_cleanup_stage({:fd_close, _}), do: :cleanup_fd_close
  defp ua_sf_cleanup_stage({:hygiene_fd_close, _}), do: :cleanup_hygiene_fd
  defp ua_sf_cleanup_stage(step) when step in [
    :release_ready, :abort_hold, :release_unlock, :clean_stop, :clean_join, :actor_release,
    :owner_actor_join, :retained_database, :fault_stop, :fault_join, :attribution_close,
    :trace_destroy, :trace_verify, :telemetry_detach, :telemetry_verify, :late_drain,
    :fence_event, :baseline_capture, :baseline_verify, :environment_verify, :self_verify,
    :source_verify, :retention, :fd_verify, :hygiene_fd_verify, :hygiene_stop,
    :hygiene_join, :hygiene_retire], do: step

  # Clean measurements precede the one normal stop and its original normal DOWN.
  # The later full plan sees the attempt markers and cannot retry either action.
  defp ua_sf_close_clean_connection do
    ua_sf_require(ua_sf_state().mode == :clean)
    ua_sf_cleanup_run([:clean_stop, :clean_join])
  end

  defp ua_sf_finalize_original do
    ua_sf_stage(:original_cleanup)
    s = ua_sf_state()
    c = Process.get({__MODULE__, :ua_control})
    ua_sf_put(%{cleanup_fds: if(is_map(c), do: c.fds, else: []),
      cleanup_session: s.session})
    ua_sf_cleanup_run(ua_sf_cleanup_plan(s, c))
  end

  defp ua_sf_cleanup_action(:release_ready) do
    s = ua_sf_state()
    if s.errors != [] and Map.has_key?(s, :run) and not Map.get(s, :ready_sent, false) do
      ua_sf_put(%{ready_sent: true})
      send(s.owner, {s.run, :observer_ready, self()})
    end
  end
  defp ua_sf_cleanup_action(:abort_hold) do
    s = ua_sf_state()
    if s.errors != [] and s.nonce != nil,
      do: send(s.owner, {s.key, :sf_continue, self(), s.owner, s.nonce, :abort})
  end
  defp ua_sf_cleanup_action(:release_unlock) do
    s = ua_sf_state()
    if s.errors != [] and s.locked and not s.release_sent, do: ua_sf_unlock()
  end
  defp ua_sf_cleanup_action(:clean_stop) do
    s = ua_sf_state()
    if s.mode == :clean and is_pid(s.connection) do
      [{ref, connection}] = Enum.filter(s.monitors, fn {_, id} -> id == s.connection end)
      ua_sf_put(%{clean_connection_close: {connection, ref, ua_sf_time()}})
      :ok = GenServer.stop(connection, :normal, ua_sf_cleanup_remaining())
    end
  end
  defp ua_sf_cleanup_action(:clean_join) do
    s = ua_sf_state()
    if s.mode == :clean and is_pid(s.connection) do
      [{ref, connection}] = Enum.filter(s.monitors, fn {_, id} -> id == s.connection end)
      ua_sf_until(fn current -> Map.has_key?(current.downs, connection) end)
      {^ref, :process, :normal, at} = Map.fetch!(ua_sf_state().downs, connection)
      ua_sf_put(%{clean_connection_join: {connection, ref, at}})
    end
  end
  defp ua_sf_cleanup_action(:actor_release) do
    s = ua_sf_state()
    if is_pid(s.actor) and (s.mode == :clean or s.errors != []),
      do: send(s.actor, {s.key, :sf_close, self()})
  end
  defp ua_sf_cleanup_action(:owner_actor_join) do
    s = ua_sf_state()
    if s.actor do
      ua_sf_until(fn value ->
        Map.has_key?(value.downs, value.actor) and
          (value.owner == nil or Map.has_key?(value.downs, value.owner))
      end)
    end
  end
  defp ua_sf_cleanup_action(:retained_database) do
    s = ua_sf_state()
    live = s.mode == :fault and is_pid(s.connection) and Process.alive?(s.connection)
    ua_sf_put(%{fault_connection_live: live})
    if live and s.errors == [] do
      [[oid]] = ua_sf_rows("SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1",
        [s.destination.database])
      ua_sf_require(oid == s.oid)
      ua_sf_put(%{retained_database: {s.destination.database, oid, ua_sf_time()}})
    end
  end
  defp ua_sf_cleanup_action(:fault_stop) do
    s = ua_sf_state()
    if Map.get(s, :fault_connection_live, false),
      do: :ok = GenServer.stop(s.connection, :normal, ua_sf_cleanup_remaining())
  end
  defp ua_sf_cleanup_action(:fault_join) do
    s = ua_sf_state()
    if Map.get(s, :fault_connection_live, false),
      do: ua_sf_until(fn value -> Map.has_key?(value.downs, value.connection) end)
  end
  defp ua_sf_cleanup_action(:attribution_close) do
    s = ua_sf_state()
    transport_attribution_close(s.key)
    if s.connection,
      do: ua_sf_require(Process.get({s.key, :backend_attribution_close}) == :confirmed)
    Process.delete({__MODULE__, :backend_attribution_connection})
  end
  defp ua_sf_cleanup_action({:join, id, ref}) do
    ua_sf_put(%{join_attempts: Map.put(ua_sf_state().join_attempts, id, {ref, :attempted})})
    ua_sf_until(fn value -> Map.has_key?(value.downs, id) end)
    {^ref, _, _, at} = Map.fetch!(ua_sf_state().downs, id)
    ua_sf_put(%{join_attempts: Map.put(ua_sf_state().join_attempts, id, {ref, {:down, at}})})
  end
  defp ua_sf_cleanup_action({:trace_fence, pid}) do
    s = ua_sf_state()
    if s.session do
      ref = :trace.delivered(s.session, pid)
      ua_sf_put(%{fence_waits: Map.put(Map.get(s, :fence_waits, %{}), pid, ref)})
      ua_sf_until(&(Map.get(Map.get(&1, :fence_acks, %{}), pid) === ref))
      ua_sf_put(%{fenced: Map.get(ua_sf_state(), :fenced, []) ++ [pid]})
    end
  end
  defp ua_sf_cleanup_action(:trace_destroy) do
    s = ua_sf_state()
    if s.session do
      ua_sf_require(:trace.session_destroy(s.session))
      ua_sf_put(%{session: nil})
    end
  end
  defp ua_sf_cleanup_action(:trace_verify) do
    s = ua_sf_state()
    if s.cleanup_session do
      ua_sf_require(s.session == nil)
      after_snapshot = ua_sf_trace_snapshot(s.traces)
      ua_sf_require(after_snapshot == s.trace_before)
      flags_restored = Enum.all?(s.flags, fn {pid, before} ->
        if Process.alive?(pid) do
          [:erlang.trace_info(pid, :flags), :erlang.trace_info(pid, :tracer)] == before
        else
          Map.has_key?(ua_sf_state().downs, pid)
        end
      end)
      ua_sf_require(flags_restored)
      ua_sf_require(Enum.sort(Map.get(s, :fenced, [])) == Enum.sort(Map.keys(s.flags)))
      ua_sf_put(%{trace_restored: true, trace_after: after_snapshot,
        flags_restored: flags_restored})
    end
  end
  defp ua_sf_cleanup_action(:telemetry_detach) do
    s = ua_sf_state()
    if Map.has_key?(s, :telemetry_handler), do: :ok = :telemetry.detach(s.telemetry_handler)
  end
  defp ua_sf_cleanup_action(:telemetry_verify) do
    s = ua_sf_state()
    if Map.has_key?(s, :telemetry_handler) do
      after_handlers = Enum.sort(:telemetry.list_handlers([]))
      ua_sf_require(after_handlers == Enum.sort(s.telemetry_before))
      ua_sf_put(%{telemetry_restored: true, telemetry_after: after_handlers})
    end
  end
  defp ua_sf_cleanup_action(:late_drain), do: ua_sf_drain(0)
  defp ua_sf_cleanup_action(:fence_event), do: ua_sf_event(:fences, :complete, ua_sf_time())
  defp ua_sf_cleanup_action(:baseline_capture) do
    ua_sf_put(%{restored_baseline: transport_cleanup_baseline(ua_sf_state().deadline)})
  end
  defp ua_sf_cleanup_action(:baseline_verify) do
    s = ua_sf_state()
    ua_sf_require(s.restored_baseline == s.baseline)
  end
  defp ua_sf_cleanup_action(:environment_verify) do
    ua_sf_require(System.get_env() == ua_sf_state().environment)
    ua_sf_put(%{restored_environment: System.get_env()})
  end
  defp ua_sf_cleanup_action(:self_verify) do
    c = Process.get({__MODULE__, :ua_control})
    ua_sf_require(ua_sf_self().seed == c.seed)
  end
  defp ua_sf_cleanup_action(:source_verify), do: ua_sf_require(ua_sf_sources() == ua_sf_state().sources)
  defp ua_sf_cleanup_action(:retention) do
    s = ua_sf_state()
    if s.mode == :fault and s.errors == [] do
      retained = ua_sf_roots_equal()
      ua_sf_put(%{retention_roots: retained.roots, retention_ancestors: retained.ancestors,
        retention_inventory: retained.inventory})
    end
  end
  defp ua_sf_cleanup_action({:fd_close, fd}) do
    :ok = :file.close(fd)
    c = Process.get({__MODULE__, :ua_control})
    ua_control_update(%{fds: List.delete(c.fds, fd)})
  end
  defp ua_sf_cleanup_action(:fd_verify) do
    s = ua_sf_state()
    closed = Enum.map(s.cleanup_fds, fn fd ->
      case Map.fetch!(s.cleanup_steps, {:fd_close, fd}) do
        {:ok, _} -> :ok
        other -> other
      end
    end)
    ua_sf_require(Enum.all?(closed, &(&1 == :ok)))
    ua_sf_put(%{fds_closed: closed})
  end

  defp ua_sf_cleanup_action({:hygiene_fd_close, fd}) do
    :ok = :file.close(fd)
    :closed
  end
  defp ua_sf_cleanup_action(:hygiene_fd_verify) do
    ua_sf_require(ua_sf_hygiene_fds_closed?(ua_sf_state()))
  end
  defp ua_sf_cleanup_action(:hygiene_stop) do
    s = ua_sf_state()
    {recovery, _ref} = s.hygiene_connection
    case s.hygiene_cleanup_mode do
      :normal -> :ok = GenServer.stop(recovery, :normal, min(1_000, ua_sf_remaining()))
      :after ->
        if Process.alive?(recovery),
          do: :ok = GenServer.stop(recovery, :normal, ua_sf_cleanup_remaining())
    end
  end
  defp ua_sf_cleanup_action(:hygiene_join) do
    s = ua_sf_state()
    {recovery, ref} = s.hygiene_connection
    timeout = case s.hygiene_cleanup_mode do
      :normal -> ua_sf_remaining()
      :after -> ua_sf_cleanup_remaining()
    end
    # No expired-budget queued message can grant a new successful join.
    ua_sf_require(timeout > 0)
    ua_sf_put(%{hygiene_observed_down: :unconfirmed})
    observed = case s.hygiene_cleanup_mode do
      :normal ->
        receive do
          {:DOWN, ^ref, :process, ^recovery, _reason} = down -> down
        after timeout -> :unconfirmed end
      :after ->
        receive do
          {:DOWN, ^ref, :process, ^recovery, :normal} = down -> down
        after timeout -> throw(:hygiene_join) end
    end
    ua_sf_put(%{hygiene_observed_down: observed})
    ua_sf_require(observed === {:DOWN, ref, :process, recovery, :normal})
    {:normal, recovery, ref}
  end
  defp ua_sf_cleanup_action(:hygiene_retire) do
    s = ua_sf_state()
    ua_sf_require(ua_sf_hygiene_terminal?(s))
    {recovery, ref} = s.hygiene_connection
    Process.demonitor(ref, [:flush])
    {:retired, recovery, ref}
  end

  defp ua_sf_drain(64), do: throw(:legacy_transport_observer)
  defp ua_sf_drain(count) do
    s = ua_sf_state()
    key = s.key
    receive do
      {^key, :sf_privacy, safe?} ->
        ua_sf_require(safe? == true)
        ua_sf_put(%{privacy: s.privacy ++ [safe?]})
        ua_sf_drain(count + 1)
      {^key, :sf_clean_release, actor, owner, at} when actor == s.actor and owner == s.owner ->
        ua_sf_require(s.mode == :clean and not Map.has_key?(s, :clean_actor_release) and
          is_integer(at) and at >= s.epoch)
        ua_sf_put(%{clean_actor_release: {actor, owner, at}})
        ua_sf_drain(count + 1)
      {^key, :sf_actor_finished, actor, _} when actor == s.actor ->
        ua_sf_put(%{actor_finished: true})
        ua_sf_drain(count + 1)
      {^key, :sf_actor_result, actor, outcome, queued, safe?} when actor == s.actor ->
        ua_sf_require(not Map.has_key?(s, :actor_result))
        ua_sf_put(%{actor_result: outcome, actor_queued: queued, actor_private: safe?})
        ua_sf_drain(count + 1)
      {^key, _, _, _, _, _, _, _, _} -> throw(:legacy_transport_observer)
    after
      0 -> ua_sf_put(%{late_drain_complete: true})
    end
  end

  defp ua_sf_complete_restoration do
    ua_sf_stage(:privacy_restoration)
    s = ua_sf_state()
    ua_sf_require(s.errors == [] and s.stdout and s.stderr and s.logger and
      s.actor_private and Enum.all?(s.privacy, &(&1 == true)) and s.late_drain_complete)
    ua_sf_event(:privacy, :complete, ua_sf_time())
    ua_sf_require(s.trace_restored and s.telemetry_restored and
      s.restored_baseline == s.baseline and s.restored_environment == s.environment and
      Enum.all?(s.fds_closed, &(&1 == :ok)))
    ua_sf_event(:restoration, :complete, ua_sf_time())
    if s.mode == :fault do
      ua_sf_require(s.retention_roots == s.roots and s.retention_ancestors == s.ancestors and
        s.retention_inventory == s.root_inventory)
      ua_sf_require(elem(s.retained_database, 0) == s.destination.database and
        elem(s.retained_database, 1) == s.oid)
      ua_sf_event(:retention, :original_quarantine, ua_sf_time())
    end
  end

  defp ua_sf_provenance do
    s = ua_sf_state()
    %{raw: s.raw, observed: s.contexts, owner: s.owner, caller: s.actor}
  end

  defp ua_sf_facts do
    s = ua_sf_state()
    {:ok, encoded} = ua_sf_context_projection(hd(s.contexts), s.raw, s.owner, s.actor)
    ua_sf_require(length(s.contexts) == 1 and s.held_context === s.raw)
    monitors = Enum.map(s.monitors, fn {ref, pid} -> {pid, ref} end)
    expected = %{private_key: s.key, run: s.run, owner: s.owner, caller: s.actor,
      observer: self(), observer_connection: s.connection, nonce: s.nonce,
      database: s.destination.database, oid: s.oid, handle: s.handle, timeout: s.await_timeout,
      repos: s.repos, maintenance: s.maintenance, context: encoded, roots: s.roots, ancestors: s.ancestors,
      original_monitors: monitors, backend_baseline: s.triples, pool_counts: s.pools,
      observer_backend: s.observer_backend, child_backend: s.child, tag: s.lexical.tag,
      deadline: ua_sf_deadline_value(),
      captured_before_allocation: s.epoch < s.allocated and s.lexical.private_key == s.key and
        s.lexical.observer == self() and s.lexical.caller == s.actor and s.allocated < s.launch.at}
    {before_arm, _} = Map.fetch!(s.checkpoints, :before_arm)
    {owner_ref, :process, owner_reason, _} = Map.fetch!(s.downs, s.owner)
    {_actor_ref, :process, actor_reason, _} = Map.fetch!(s.downs, s.actor)
    ua_sf_require({s.owner, owner_ref} in monitors)
    stages = Enum.map(s.helper, &elem(&1, 1))
    quarantine = [{:legacy_preparation_quarantined, :unconfirmed}]
    {:error, primary, cleanup} = s.actor_result
    [{:running, _}, {:unconfirmed, _}] = s.reporter
    ua_sf_require(primary == :legacy_pipe and cleanup == quarantine and
      s.actor_queued == stages and elem(s.caught, 1) == {:legacy_preparation_failed, :legacy_pipe})
    before_after = s.brackets
    [first, last] = before_after
    measurement = %{native: s.held_native, tagged_rows: first.tagged ++ last.tagged,
      baselines: Enum.map(before_after, & &1.capture.triples), sample_times: Enum.map(before_after, & &1.at),
      repos_before: first.repos_before, repos_after: last.repos_after,
      owner_live: Enum.all?(before_after, & &1.all_live),
      maintenance_live: Enum.all?(before_after, & &1.all_live),
      held: ua_sf_at(:boundary_entry) < ua_sf_at(:measurement) and
        ua_sf_at(:measurement) < ua_sf_at(:boundary_exit),
      oid: last.oid, root_object_workspace_unchanged: s.root_inventory == ua_sf_inventories(s.roots),
      privacy_so_far: s.actor_private and Enum.all?(s.privacy, &(&1 == true)),
      queries_bounded: Enum.all?(before_after, &transport_inventory_clock_valid?(&1.capture.context)),
      brackets: Enum.map(before_after, &Map.drop(&1, [:capture, :tagged]))}
    trace_equal = fn field ->
      Enum.all?(s.traces, fn mfa ->
        List.keyfind(s.trace_after[mfa], field, 0) == List.keyfind(s.trace_before[mfa], field, 0)
      end)
    end
    restoration = %{
      event_fence: map_size(s.downs) == 13 and length(s.fenced) == map_size(s.flags),
      trace_fence: Enum.sort(s.fenced) == Enum.sort(Map.keys(s.flags)),
      late_message_drain: s.late_drain_complete, stdout: s.stdout, stderr: s.stderr, logger: s.logger,
      exception_messages: s.actor_private, inspect_canary: s.actor_private,
      telemetry_registered_positive: Enum.sort(Enum.map(s.telemetry_installed, & &1.event_name)) ==
        Enum.sort(s.telemetry_events),
      own_telemetry_detached: s.telemetry_restored,
      entire_telemetry_baseline: s.telemetry_after == Enum.sort(s.telemetry_before),
      own_trace_sessions_closed: s.session == nil and s.trace_restored,
      traced: trace_equal.(:traced), match_spec: trace_equal.(:match_spec),
      meta: trace_equal.(:meta), meta_match_spec: trace_equal.(:meta_match_spec),
      process_flags: s.flags_restored, tracer: s.flags_restored,
      config: s.restored_baseline.configs == s.baseline.configs,
      compiler: s.restored_baseline.compiler == s.baseline.compiler,
      environment: s.restored_environment == s.environment,
      repository: s.restored_baseline.repos == s.baseline.repos and
        s.restored_baseline.runtime? == s.baseline.runtime?,
      no_content_in_diagnostics: s.stdout and s.stderr and s.logger and s.actor_private,
      original_failures_retained: primary == elem(elem(s.caught, 1), 1) and cleanup == quarantine and s.errors == [],
      original_observer_demonitor_only: s.hold_monitor_restored}
    actual_roots = s.retention_roots
    retention = %{database_name_oid: elem(s.retained_database, 0) == s.destination.database and
        elem(s.retained_database, 1) == s.oid,
      allocation: actual_roots.allocation == s.roots.allocation,
      objects: actual_roots.objects == s.roots.objects,
      workspace: actual_roots.historical_build == s.roots.historical_build,
      nonlink_identities: actual_roots == s.roots, safe_ancestors: s.retention_ancestors == s.ancestors,
      empty_inventories: ua_b_inventories?(s.retention_inventory),
      quarantine_recorded: cleanup == quarantine,
      no_automatic_drop: not Map.has_key?(s.checkpoints, :before_database_drop),
      no_original_removal: actual_roots == s.roots, roots: actual_roots,
      ancestors: s.retention_ancestors, inventories: s.retention_inventory}
    gate = %{key: @transport_lock, oid: s.oid, connection: s.connection,
      acquisitions: 1, query_bound_ms: 1_000,
      observer_identity: [[s.observer_backend, "singularity_migration", s.destination.database]],
      waits: List.last(s.gate_samples).waits, locks: List.last(s.gate_samples).locks,
      samples: Enum.map(s.gate_samples, &Map.drop(&1, [:capture])), unlock_results: [s.unlock_rows]}
    %{mode: :sampled, expected: expected, registration_origin:
        Map.put(s.lexical, :run, s.run),
      preconditions: %{clean_control_qualified: s.clean == {:ok, :closed},
        original_context: ua_sf_context_inverse?(encoded, s.raw, s.owner, s.actor) and s.held_context === s.raw,
        context: encoded, nonce_fresh: is_reference(s.nonce) and s.nonce not in [s.key, s.run],
        one_selective_receive: s.hold_monitor_restored,
        receive_bound: :remaining_original_absolute_deadline,
        original_timers_unchanged: s.receive.deadline - System.convert_time_unit(s.receive.at, :native, :millisecond) in 1..45_000,
        foreign_continuations_accepted: 0, handle: s.handle,
        reader_blocked: s.prekill_workers, writer_completed_waiting: s.prekill_workers,
        primary_nil: s.receive.handle === s.handle and s.receive.primary == nil,
        execution_deadline_live: System.convert_time_unit(ua_sf_at(:command_kill), :native, :millisecond) < s.receive.deadline,
        no_replacement: s.held_native.replacement_seen == false,
        on_exit: before_arm.on_exit, command_kills: [s.command], extra_signals: [],
        infrastructure_acquired: false},
      gate: gate, caught: s.caught, events: ua_sf_events(), mailbox_arrival: s.arrival,
      measurement: measurement,
      helper: %{primary: s.finish_primary, await: if({:await_complete, :unconfirmed} in stages, do: :unconfirmed, else: :invalid),
        cleanup: if({:cleanup, :unconfirmed} in stages, do: :unconfirmed, else: :invalid),
        secondary: cleanup, preparation_error: {primary, cleanup},
        sql_absent: :child_connections_absent in stages, child_absent: :child_connections_absent in stages,
        closed: {:cleanup, :closed} in stages, workspace_removed: actual_roots != s.roots,
        ready: Map.has_key?(s.checkpoints, :ready), before_database_drop: Map.has_key?(s.checkpoints, :before_database_drop),
        normal_owner_cleanup: owner_reason == :normal, after_hygiene: elem(List.last(s.reporter), 0),
        reporter_calls: Enum.count(s.reporter, &(elem(&1, 0) == :unconfirmed))},
      terminal: %{owner: owner_reason, actor: actor_reason, before_arm_on_exit: before_arm.on_exit},
      joins: Enum.map(monitors, fn {id, ref} ->
        {^ref, {:down, at}} = Map.fetch!(s.join_attempts, id)
        {id, ref, :bounded, {:down, ua_sf_relative(at)}}
      end),
      restoration: restoration, retention: retention,
      credits: %{sample: true, recovery: false, hygiene: false}, failures: s.errors, hygiene: :forbidden}
  end

  defp ua_sf_clean_final do
    s = ua_sf_state()
    stages = Enum.map(s.helper, &elem(&1, 1))
    {_ref, :process, owner_reason, _} = s.downs[s.owner]
    {_ref, :process, actor_reason, _} = s.downs[s.actor]
    ua_sf_require(s.mode == :clean and s.actor_result == {:ok, true} and
      owner_reason == :normal and actor_reason == :normal and map_size(s.downs) == 13 and
      s.actor_queued == stages and {:await_complete, :zero} in stages and
      {:cleanup, :closed} in stages and :workers_down in stages and :child_connections_absent in stages and
      Enum.map(s.reporter, &elem(&1, 0)) == [:running, :closed] and
      Map.has_key?(s.checkpoints, :ready) and Map.has_key?(s.checkpoints, :before_database_drop) and
      List.last(s.clean_native.observations).kind == :absent and s.clean_native.port_info == nil and
      elem(s.downs[s.port], 2) == :normal)
    {connection, connection_ref, close_at} = s.clean_connection_close
    {^connection_ref, :process, :normal, down_at} = Map.fetch!(s.downs, connection)
    {actor, owner, release_at} = s.clean_actor_release
    {drop_resources, drop_at} = Map.fetch!(s.checkpoints, :before_database_drop)
    ua_sf_require(connection == s.connection and s.monitors[connection_ref] == connection and
      s.clean_connection_join == {connection, connection_ref, down_at} and
      actor == s.actor and owner == s.owner and drop_resources.owner == owner and
      drop_resources.caller == actor and drop_resources.names.database == s.destination.database and
      close_at < down_at and down_at < release_at and release_at < drop_at)
    Enum.each(s.roots, fn {_, {path, _}} -> ua_sf_require(File.lstat(path) == {:error, :enoent}) end)
    :ok
  end

  defp ua_sf_reopen_custody do
    c = Process.get({__MODULE__, :ua_control})
    ua_sf_require(c.fds == [])
    root = ua_control_open!("/proc", :directory)
    own = ua_control_open!(c.self_root, :directory)
    ua_control_update(%{proc_fd: root, self_fd: own})
    ua_sf_require(ua_sf_self().seed == c.seed)
  end

  # These identities are acquired by existing hygiene only after the original
  # plan. A distinct step namespace prevents an old close credit from being reused.
  defp ua_sf_hygiene_plan(fds) do
    Enum.map(fds, &{:hygiene_fd_close, &1}) ++
      [:hygiene_fd_verify, :hygiene_stop, :hygiene_join, :hygiene_retire]
  end

  defp ua_sf_hygiene_fds_closed?(s) do
    s.hygiene_fds == [] and Enum.all?(s.hygiene_original_fds, fn fd ->
      Map.get(s.cleanup_steps, {:hygiene_fd_close, fd}) === {:ok, :closed}
    end)
  end

  defp ua_sf_hygiene_terminal?(s) do
    case s.hygiene_connection do
      {recovery, ref} ->
        Map.get(s, :hygiene_down) === {recovery, ref, :normal} and
          Map.get(s.cleanup_steps, :hygiene_join) === {:ok, {:normal, recovery, ref}}
      nil -> false
    end
  end

  defp ua_sf_hygiene_cleanup(mode) do
    s = ua_sf_state()
    unless Map.has_key?(s, :hygiene_plan) do
      c = Process.get({__MODULE__, :ua_control})
      ua_sf_put(%{hygiene_plan: ua_sf_hygiene_plan(c.fds), hygiene_cleanup_mode: mode,
        hygiene_original_fds: c.fds, hygiene_fds: c.fds})
    end
    ua_sf_cleanup_run(ua_sf_state().hygiene_plan)
  end

  defp ua_sf_hygiene_cleanup_contract(count, prior_failure?, failure, recovery) do
    monitors = Map.new(1..13, &{make_ref(), {:synthetic_original, &1}})
    initial = %{first_failure: nil, errors: [], cleanup_steps: %{}, join_attempts: %{},
      monitors: monitors, flags: %{}, stage: :synthetic_cleanup}
    original_plan = ua_sf_cleanup_plan(initial, %{fds: [:synthetic_fd_a]})
    {_, original_done} = ua_sf_cleanup_execute(original_plan, initial,
      fn step, _ -> {:terminal, step} end, &ua_sf_cleanup_record/3)
    fds = Enum.take([:synthetic_fd_a, :synthetic_fd_b], count)
    ref = make_ref()
    primary = ua_sf_failure_fact(:original, :independent_hygiene, :throw,
      :synthetic_hygiene_primary, [:synthetic_stack])
    acquired = Map.merge(original_done, %{hygiene_original_fds: fds, hygiene_fds: fds,
      hygiene_connection: {recovery, ref},
      first_failure: if(prior_failure?, do: primary, else: nil),
      errors: if(prior_failure?, do: [primary], else: [])})
    plan = ua_sf_hygiene_plan(fds)
    failing = case failure do
      :first_fd -> if(count >= 1, do: {:hygiene_fd_close, :synthetic_fd_a})
      :second_fd -> if(count >= 2, do: {:hygiene_fd_close, :synthetic_fd_b})
      :fd_verify -> :hygiene_fd_verify
      :stop -> :hygiene_stop
      :join -> :hygiene_join
      :retire -> :hygiene_retire
      nil -> nil
    end
    action = fn step, state ->
      ua_sf_cleanup_once(Map.fetch(state.cleanup_steps, step), fn ->
        if step == failing, do: throw({:synthetic_hygiene_failure, step})
        case step do
          {:hygiene_fd_close, _} -> :closed
          :hygiene_fd_verify ->
            if ua_sf_hygiene_fds_closed?(state), do: :ok, else: throw(:synthetic_unclosed)
          :hygiene_stop -> :ok
          :hygiene_join -> {:normal, recovery, ref}
          :hygiene_retire ->
            if ua_sf_hygiene_terminal?(state),
              do: {:retired, recovery, ref}, else: throw(:synthetic_unconfirmed)
        end
      end)
    end
    {outcomes, retained} = ua_sf_cleanup_execute(plan, acquired, action, &ua_sf_cleanup_record/3)
    {after_outcomes, after_state} =
      ua_sf_cleanup_execute(plan, retained, action, &ua_sf_cleanup_record/3)
    failed_fds = Enum.filter(fds, &({:hygiene_fd_close, &1} == failing))
    terminal? = failing not in [:hygiene_join, :hygiene_retire]
    expected_first = if prior_failure?, do: primary, else: List.first(retained.errors)
    Enum.map(outcomes, &elem(&1, 0)) === plan and length(Enum.uniq(plan)) == length(plan) and
      not Enum.any?(outcomes, &match?({_, {:ok, {:previous, _}}}, &1)) and
      Enum.all?(after_outcomes, &match?({_, {:ok, {:previous, _}}}, &1)) and
      after_state === retained and retained.monitors === monitors and
      retained.hygiene_fds === failed_fds and
      retained.hygiene_connection === (if terminal?, do: nil, else: {recovery, ref}) and
      retained.first_failure === expected_first and
      (if prior_failure? or failing != nil, do: retained.errors != [], else: retained.errors == []) and
      (if failing == :hygiene_stop,
        do: Map.get(retained.cleanup_steps, :hygiene_join) === {:ok, {:normal, recovery, ref}},
        else: true) and
      Enum.all?(fds, fn fd ->
        case Map.get(retained.cleanup_steps, {:hygiene_fd_close, fd}) do
          {:ok, :closed} -> fd not in retained.hygiene_fds
          {:error, :throw, {:synthetic_hygiene_failure, {:hygiene_fd_close, ^fd}}, stack} ->
            fd in retained.hygiene_fds and is_list(stack) and stack != []
          _ -> false
        end
      end)
  end

  defp ua_sf_hygiene(facts) do
    ua_sf_stage(:independent_hygiene)
    s = ua_sf_state()
    ua_sf_require(ua_sf_original_ready?(facts, ua_sf_provenance()))
    options = s.connection_options
      |> Keyword.put(:database, "postgres")
      |> Keyword.put(:parameters, application_name: @transport_observer_tag)
    {:ok, recovery} = Postgrex.start_link(options)
    Process.unlink(recovery)
    ref = Process.monitor(recovery)
    ua_sf_put(%{hygiene_connection: {recovery, ref}})
    try do
      ua_sf_require(recovery != s.connection and recovery != self())
      [[role, "postgres"]] = ua_sf_recovery_rows(recovery, "SELECT current_user,current_database()", [])
      ua_sf_require(role == "singularity_migration")
      [[oid]] = ua_sf_recovery_rows(recovery,
        "SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [s.destination.database])
      rows = ua_sf_recovery_rows(recovery,
        "SELECT pid FROM pg_catalog.pg_stat_activity WHERE datname=$1 ORDER BY pid", [s.destination.database])
      ua_sf_require(oid == s.oid and rows == [])
      ua_sf_reopen_custody()
      native = ua_sf_absence(:hygiene)
      fresh = ua_sf_roots_equal()
      roots = fresh.roots
      ancestors = fresh.ancestors
      inventory = fresh.inventory
      ua_sf_require(ua_b_inventories?(inventory))
      ua_sf_require(Regex.match?(~r/\Asingularity_test_[0-9a-f]{24}\z/, s.destination.database))
      quoted = "\"" <> String.replace(s.destination.database, "\"", "\"\"") <> "\""
      # Only exact, ordinary DROP after complete proof; no FORCE/termination.
      {:ok, %Postgrex.Result{}} = Postgrex.query(recovery, "DROP DATABASE " <> quoted, [],
        timeout: min(1_000, ua_sf_remaining()))
      absent = ua_sf_recovery_rows(recovery,
        "SELECT oid::bigint FROM pg_catalog.pg_database WHERE datname=$1", [s.destination.database])
      ua_sf_require(absent == [])
      removed = Enum.map([:historical_build, :objects, :allocation], fn kind ->
        {path, identity} = roots[kind]
        ua_sf_require(ua_sf_directory(path, true) == identity)
        Enum.each(ancestors, fn {parent, object} -> ua_sf_require(ua_sf_directory(parent, false) == object) end)
        {:ok, []} = File.ls(path)
        :ok = File.rmdir(path)
        ua_sf_require(File.lstat(path) == {:error, :enoent})
        kind
      end)
      ua_sf_hygiene_cleanup(:normal)
      current = ua_sf_state()
      normal = Map.get(current, :hygiene_down) === {recovery, ref, :normal}
      ua_sf_require(normal and current.hygiene_connection == nil and
        ua_sf_hygiene_fds_closed?(current) and current.errors == [])
      %{independent_authority: ua_sf_original_ready?(facts, ua_sf_provenance()),
        connection: recovery, role: :singularity_migration, maintenance_database: "postgres",
        database: s.destination.database, oid: oid, session_scope: :all_a, all_a_rows: rows,
        native: native, native_fresh: hd(hd(native.observations).read_serials) >
          List.last(List.last(s.held_native.observations).read_serials),
        roots: roots, ancestors: ancestors, inventories: inventory,
        fresh_identities: roots == facts.expected.roots, empty_inventories: ua_b_inventories?(inventory),
        repeated_safe_ancestors: ancestors == facts.expected.ancestors,
        drop: :ordinary_exact_quoted, termination: :none, database_absent: absent == [],
        removal: :identity_confirmed_empty_rmdir, removal_order: removed,
        each_fresh_enoent: removed == [:historical_build, :objects, :allocation], connection_down: normal}
    catch
      kind, value ->
        stack = __STACKTRACE__
        ua_sf_failure(:original, kind, value, stack)
        :erlang.raise(kind, value, stack)
    after
      ua_sf_hygiene_cleanup(:after)
    end
  end

  defp ua_sf_recovery_rows(connection, sql, parameters) do
    {:ok, %Postgrex.Result{rows: rows}} =
      Postgrex.query(connection, sql, parameters, timeout: min(1_000, ua_sf_remaining()))
    ua_sf_require(is_list(rows) and length(rows) <= 64)
    rows
  end

  defp ua_sf_last_cleanup do
    s = ua_sf_state()
    if is_map(s) do
      # Finalization is one-shot. A failed action must not be retried here.
      # Unknown ownership stays private in this existing observer's dictionary.
      if s.errors == [] do
        ua_sf_safe(fn ->
          ua_sf_require(map_size(s.monitors) == 13 and
            Enum.all?(s.monitors, fn {ref, id} ->
              case {Map.get(s.downs, id), Map.get(s.join_attempts, id)} do
                {{^ref, _, _, at}, {^ref, {:down, at}}} -> true
                _ -> false
              end
            end))
        end)
      end
      final = ua_sf_state()
      evidence = %{original: Map.get(final, :caught), first_failure: final.first_failure,
        errors: final.errors, actor_result: Map.get(final, :actor_result),
        joins: final.join_attempts, monitors: final.monitors, cleanup_steps: final.cleanup_steps}
      if final.errors == [] do
        Enum.each(final.monitors, fn {ref, _} -> Process.demonitor(ref, [:flush]) end)
        Enum.each(final.dictionary, fn
          {key, true, value} -> Process.put(key, value)
          {key, false, _} -> Process.delete(key)
        end)
        # Exact private state is retired only after all original terminal proofs.
        Enum.each(Process.get_keys(), fn
          {key, _} = dictionary_key when key == final.key -> Process.delete(dictionary_key)
          _ -> :ok
        end)
        Process.delete({__MODULE__, :backend_attribution_connection})
        Process.delete({__MODULE__, :ua_control})
        Process.delete({__MODULE__, :ua_sf})
      end
      # Natural owner termination is not closure, restoration or acceptance.
      evidence
    else
      %{original: nil, first_failure: nil, errors: [], actor_result: nil}
    end
  end
  # TASK18_SELECTED_COMMAND_FAULT_END
end
